def migrate_vehicle_applications_nullable():
    """兼容旧库：用车申请表 vehicle_id/applicant_id/start_at/end_at 改为可空，
    以支持移动端“仅填事由”的极简申请形态（重建表以解除 NOT NULL 约束）。"""
    with get_db() as db:
        try:
            cols = [r['name'] for r in db.execute("PRAGMA table_info(vehicle_applications)").fetchall()]
            # 仅当存在 NOT NULL 约束时才重建
            notnull = db.execute("PRAGMA table_info(vehicle_applications)").fetchall()
            if all(c['notnull'] == 0 for c in notnull if c['name'] in ('vehicle_id', 'applicant_id', 'start_at', 'end_at')):
                print('[Migrate] vehicle_applications 已为可空，跳过重建')
                return
            db.execute("""CREATE TABLE vehicle_applications_new (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                vehicle_id INTEGER,
                applicant_id INTEGER,
                start_at TIMESTAMP,
                end_at TIMESTAMP,
                destination TEXT DEFAULT NULL,
                reason TEXT DEFAULT NULL,
                status TEXT DEFAULT 'pending',
                approver_id INTEGER,
                approved_at TIMESTAMP,
                reject_reason TEXT,
                created_at TIMESTAMP DEFAULT (datetime('now','localtime')),
                site_id TEXT,
                work_order_no TEXT,
                no_vehicle_required INTEGER DEFAULT 0,
                vehicle_exception_reason TEXT DEFAULT ''
            )""")
            db.execute(f"""INSERT INTO vehicle_applications_new ({','.join(cols)})
                SELECT {','.join(cols)} FROM vehicle_applications""")
            db.execute("DROP TABLE vehicle_applications")
            db.execute("ALTER TABLE vehicle_applications_new RENAME TO vehicle_applications")
            db.commit()
            print('[Migrate] vehicle_applications 已重建为可空（保留原数据）')
        except Exception as e:
            print(f'[Migrate] vehicle_applications 重建跳过: {e}')


def migrate_vehicle_lifecycle_schema():
    """车辆全生命周期的增量迁移。

    旧的车辆模块只有台账、申请和简单的行车/加油/保养流水。本迁移保留所有
    历史记录，同时补上纸质检查表、证照和交接所需字段；采用逐列补齐，便于在
    现有演示库与新库上重复执行。
    """
    with get_db() as db:
        try:
            vehicle_columns = {
                'vehicle_name': 'TEXT DEFAULT \'\'', 'department': 'TEXT DEFAULT \'\'',
                'fuel_type': 'TEXT DEFAULT \'\'', 'purchase_date': 'TEXT',
                'insurance_expiry': 'TEXT', 'annual_inspection_expiry': 'TEXT',
                'registration_expiry': 'TEXT', 'last_inspection_at': 'TEXT',
                'last_inspection_status': 'TEXT DEFAULT \'normal\'',
            }
            existing = {r['name'] for r in db.execute('PRAGMA table_info(vehicles)').fetchall()}
            for name, column_type in vehicle_columns.items():
                if name not in existing:
                    db.execute(f'ALTER TABLE vehicles ADD COLUMN {name} {column_type}')

            use_columns = {
                'checked_out_at': 'TEXT', 'status': 'TEXT DEFAULT \'checked_out\'',
                'out_inspection_id': 'INTEGER', 'return_inspection_id': 'INTEGER',
                'checkout_operator_id': 'INTEGER', 'return_operator_id': 'INTEGER',
            }
            existing = {r['name'] for r in db.execute('PRAGMA table_info(vehicle_use_records)').fetchall()}
            for name, column_type in use_columns.items():
                if name not in existing:
                    db.execute(f'ALTER TABLE vehicle_use_records ADD COLUMN {name} {column_type}')

            refuel_columns = {
                'unit_price': 'REAL', 'operator_id': 'INTEGER', 'operator_name': 'TEXT',
                'fuel_type': 'TEXT', 'energy_quantity': 'REAL', 'energy_unit': "TEXT DEFAULT 'L'",
                'evidence_expected_count': 'INTEGER DEFAULT 0',
                'evidence_status': "TEXT DEFAULT 'not_required'",
            }
            existing = {r['name'] for r in db.execute('PRAGMA table_info(vehicle_refueling_records)').fetchall()}
            for name, column_type in refuel_columns.items():
                if name not in existing:
                    db.execute(f'ALTER TABLE vehicle_refueling_records ADD COLUMN {name} {column_type}')

            maintenance_columns = {
                'maint_status': 'TEXT DEFAULT \'completed\'', 'vendor': 'TEXT',
                'expected_return_at': 'TEXT', 'actual_return_at': 'TEXT', 'fault_description': 'TEXT',
                'affects_safe_operation': 'INTEGER',
                'evidence_expected_count': 'INTEGER DEFAULT 0',
                'evidence_status': "TEXT DEFAULT 'not_required'",
            }
            existing = {r['name'] for r in db.execute('PRAGMA table_info(vehicle_maintenance_records)').fetchall()}
            for name, column_type in maintenance_columns.items():
                if name not in existing:
                    db.execute(f'ALTER TABLE vehicle_maintenance_records ADD COLUMN {name} {column_type}')

            mileage_indexes = (
                ('vehicle_refueling_records', 'uq_vehicle_refueling_vehicle_mileage'),
                ('vehicle_maintenance_records', 'uq_vehicle_maintenance_vehicle_mileage'),
            )
            for table, index_name in mileage_indexes:
                duplicate = db.execute(
                    f'''SELECT 1 FROM {table}
                        WHERE mileage_at IS NOT NULL
                        GROUP BY vehicle_id, mileage_at HAVING COUNT(*) > 1 LIMIT 1''',
                ).fetchone()
                if duplicate:
                    print(f'[Migrate] {table} 存在同车同里程历史重复记录，暂不建立唯一索引')
                else:
                    db.execute(
                        f'''CREATE UNIQUE INDEX IF NOT EXISTS {index_name}
                            ON {table}(vehicle_id, mileage_at) WHERE mileage_at IS NOT NULL''',
                    )

            db.execute('''CREATE TABLE IF NOT EXISTS vehicle_documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                vehicle_id INTEGER NOT NULL,
                document_type TEXT NOT NULL,
                document_no TEXT DEFAULT '',
                valid_until TEXT,
                attachment TEXT DEFAULT '',
                remark TEXT DEFAULT '',
                created_by INTEGER,
                created_at TEXT DEFAULT (datetime('now','localtime')),
                FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
            )''')
            db.execute('''CREATE TABLE IF NOT EXISTS vehicle_inspections (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                vehicle_id INTEGER NOT NULL,
                inspection_type TEXT NOT NULL DEFAULT 'routine',
                inspection_date TEXT DEFAULT (datetime('now','localtime')),
                inspector_id INTEGER,
                inspector_name TEXT DEFAULT '',
                overall_status TEXT NOT NULL DEFAULT 'normal',
                odometer REAL,
                items_json TEXT NOT NULL DEFAULT '[]',
                remarks TEXT DEFAULT '',
                photos TEXT DEFAULT '[]',
                created_at TEXT DEFAULT (datetime('now','localtime')),
                FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
            )''')
            db.execute('CREATE INDEX IF NOT EXISTS idx_vehicle_documents_vehicle ON vehicle_documents(vehicle_id, valid_until)')
            db.execute('CREATE INDEX IF NOT EXISTS idx_vehicle_inspections_vehicle ON vehicle_inspections(vehicle_id, inspection_date DESC)')
            db.commit()
            print('[Migrate] 车辆全生命周期字段已确保（证照/检查/交接/费用）')
        except Exception as e:
            print(f'[Migrate] 车辆全生命周期迁移跳过: {e}')


def _merge_legacy_plan_vehicle_trips(db):
    """Merge old daily plan reservations into one continuous vehicle trip.

    Historical use records stay untouched for audit. The first application becomes the
    plan-level trip; redundant daily reservations no longer participate in dispatch.
    """
    rows = db.execute("""SELECT id, vehicle_id, applicant_id, start_at, end_at, status, reason
                         FROM vehicle_applications
                         WHERE vehicle_id IS NOT NULL AND applicant_id IS NOT NULL
                           AND reason LIKE '%#%'""").fetchall()
    groups = {}
    for row in rows:
        item = dict(row)
        match = re.search(r'巡检计划#(\d+)', str(item.get('reason') or ''))
        if match:
            groups.setdefault((match.group(1), item['vehicle_id'], item['applicant_id']), []).append(item)

    merged = 0
    for (schedule_id, _vehicle_id, _applicant_id), items in groups.items():
        if len([item for item in items if item['status'] == 'approved']) <= 1:
            continue
        ordered = sorted(items, key=lambda item: (str(item.get('start_at') or ''), item['id']))
        primary = ordered[0]
        start_at = min(str(item['start_at']) for item in items if item.get('start_at'))
        end_at = max(str(item['end_at']) for item in items if item.get('end_at'))
        reason = f'巡检计划#{schedule_id}用车（连续行程 {start_at[:10]} 至 {end_at[:10]}）'
        db.execute("""UPDATE vehicle_applications
                      SET start_at=?, end_at=?, reason=?, status='approved', reject_reason=NULL
                      WHERE id=?""", (start_at, end_at, reason, primary['id']))
        for item in ordered[1:]:
            has_use = db.execute('SELECT 1 FROM vehicle_use_records WHERE application_id=? LIMIT 1',
                                 (item['id'],)).fetchone()
            status = 'archived' if has_use else 'cancelled'
            db.execute('UPDATE vehicle_applications SET status=?, reject_reason=? WHERE id=?', (
                status, f'已并入巡检计划#{schedule_id}连续行程（申请#{primary["id"]}）', item['id']))
        merged += 1
    return merged


def migrate_legacy_plan_vehicle_trips():
    """Apply the daily-reservation compatibility migration at startup."""
    try:
        with get_db() as db:
            merged = _merge_legacy_plan_vehicle_trips(db)
            db.commit()
        if merged:
            print(f'[Migrate] 已合并 {merged} 组旧版按日巡检用车申请为连续行程')
    except Exception as e:
        print(f'[Migrate] 旧版巡检用车合并跳过: {e}')

def migrate_plan_schedules():
    """巡检计划调度层（周/月/季/年统一）：
    1. 创建 plan_schedules 表（不叫 inspection_schedules，该表名已被"检查项排程"占用）
    2. insp_plans 补 plan_schedule_id 列（执行任务溯源到调度计划）
    3. 旧 weekly_inspection_plans 数据幂等迁移（plan_data 兼容 "1"/"周一" 两种键）
    """
    with get_db() as db:
        db.execute("""
            CREATE TABLE IF NOT EXISTS plan_schedules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                schedule_type TEXT NOT NULL DEFAULT 'weekly',
                period_start DATE NOT NULL,
                period_end DATE NOT NULL,
                plan_data TEXT NOT NULL DEFAULT '{}',
                vehicle_days TEXT DEFAULT '{}',
                spare_parts TEXT DEFAULT '[]',
                work_order_ids TEXT DEFAULT '[]',
                status TEXT DEFAULT 'draft',
                field_status TEXT NOT NULL DEFAULT 'active',
                field_completed_at TIMESTAMP,
                approver_id INTEGER,
                submitted_at TIMESTAMP,
                approved_at TIMESTAMP,
                reject_reason TEXT,
                version INTEGER DEFAULT 1,
                change_reason TEXT,
                previous_plan_data TEXT,
                remarks TEXT,
                tasks_generated INTEGER DEFAULT 0,
                no_vehicle_required INTEGER NOT NULL DEFAULT 0,
                created_at TIMESTAMP DEFAULT (datetime('now','localtime')),
                FOREIGN KEY (user_id) REFERENCES users(id)
            )""")
        had_explicit_no_vehicle = _table_has_column(db, 'plan_schedules', 'no_vehicle_required')
        for col_sql in [
            "ALTER TABLE insp_plans ADD COLUMN plan_schedule_id INTEGER",
            "ALTER TABLE plan_schedules ADD COLUMN previous_vehicle_days TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_vehicle_id INTEGER",
            "ALTER TABLE plan_schedules ADD COLUMN previous_spare_parts TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_work_order_ids TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_remarks TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_period_start TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_period_end TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_coverage_exception_reason TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN previous_vehicle_exception_reason TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN coverage_exception_reason TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN vehicle_exception_reason TEXT DEFAULT ''",
            "ALTER TABLE plan_schedules ADD COLUMN vehicle_id INTEGER",
            "ALTER TABLE plan_schedules ADD COLUMN no_vehicle_required INTEGER NOT NULL DEFAULT 0",
            "ALTER TABLE plan_schedules ADD COLUMN previous_no_vehicle_required INTEGER",
            "ALTER TABLE plan_schedules ADD COLUMN validation_snapshot TEXT",
            "ALTER TABLE plan_schedules ADD COLUMN field_status TEXT NOT NULL DEFAULT 'active'",
            "ALTER TABLE plan_schedules ADD COLUMN field_completed_at TIMESTAMP",
            "ALTER TABLE insp_plans ADD COLUMN schedule_version INTEGER DEFAULT 1",
            "ALTER TABLE insp_plans ADD COLUMN plan_snapshot TEXT",
            "ALTER TABLE insp_plans ADD COLUMN rework_of_plan_id INTEGER",
            "ALTER TABLE insp_plans ADD COLUMN rework_batch_key TEXT DEFAULT ''",
            "ALTER TABLE insp_plans ADD COLUMN resource_state TEXT DEFAULT 'ready'",
            "ALTER TABLE insp_plan_items ADD COLUMN execution_status TEXT DEFAULT 'active'",
            "ALTER TABLE insp_plan_items ADD COLUMN rework_source_item_id INTEGER",
            "ALTER TABLE inspection_checkins ADD COLUMN plan_id INTEGER",
            "ALTER TABLE vehicle_applications ADD COLUMN rework_plan_id INTEGER",
        ]:
            try:
                db.execute(col_sql)
            except Exception:
                pass
        if not had_explicit_no_vehicle and _table_has_column(db, 'plan_schedules', 'no_vehicle_required'):
            db.execute("""UPDATE plan_schedules SET no_vehicle_required=1
                WHERE vehicle_id IS NULL AND COALESCE(vehicle_days,'{}') IN ('','{}')""")
        # 调度计划的资源仅在审批后预留；实际领用/退回由现场执行确认，不能把预申报当作出库。
        db.execute("""CREATE TABLE IF NOT EXISTS plan_resource_reservations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            schedule_id INTEGER NOT NULL,
            part_id INTEGER NOT NULL,
            planned_quantity INTEGER NOT NULL DEFAULT 0,
            reserved_quantity INTEGER NOT NULL DEFAULT 0,
            issued_quantity INTEGER NOT NULL DEFAULT 0,
            used_quantity INTEGER NOT NULL DEFAULT 0,
            returned_quantity INTEGER NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'reserved',
            created_at TEXT DEFAULT (datetime('now','localtime')),
            updated_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        db.execute("""CREATE TABLE IF NOT EXISTS plan_schedule_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            schedule_id INTEGER NOT NULL,
            version INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            operator_id INTEGER,
            payload TEXT DEFAULT '{}',
            created_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        db.execute("""CREATE TABLE IF NOT EXISTS plan_schedule_favorites (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            source_schedule_id INTEGER,
            name TEXT NOT NULL,
            snapshot TEXT NOT NULL DEFAULT '{}',
            created_at TEXT DEFAULT (datetime('now','localtime')),
            FOREIGN KEY (user_id) REFERENCES users(id)
        )""")
        # 出发前资源确认只做现场留痕：不锁车、不出库、不改变审批结果。
        db.execute("""CREATE TABLE IF NOT EXISTS plan_departure_confirmations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            schedule_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            work_date TEXT NOT NULL,
            vehicle_confirmed INTEGER NOT NULL DEFAULT 0,
            parts_confirmed INTEGER NOT NULL DEFAULT 0,
            note TEXT DEFAULT '',
            confirmed_at TEXT DEFAULT (datetime('now','localtime')),
            UNIQUE(schedule_id, user_id, work_date),
            FOREIGN KEY (schedule_id) REFERENCES plan_schedules(id),
            FOREIGN KEY (user_id) REFERENCES users(id)
        )""")
        # Backfill existing approved schedules after the execution/checkout
        # schema is available. A completed field loop is historical state, not
        # merely a result of newly introduced checkout events.
        try:
            for schedule in db.execute("SELECT id FROM plan_schedules").fetchall():
                if _ps_execution_completed(db, schedule['id']):
                    db.execute("""UPDATE plan_schedules
                        SET field_status='completed',
                            field_completed_at=COALESCE(field_completed_at, datetime('now','localtime'))
                        WHERE id=?""", (schedule['id'],))
                else:
                    db.execute("""UPDATE plan_schedules SET field_status=COALESCE(field_status, 'active')
                        WHERE id=?""", (schedule['id'],))
        except sqlite3.OperationalError:
            # Startup can run against partial legacy schemas; list/detail will
            # lazily synchronize once those tables have been migrated.
            pass
        db.commit()
        # ---- 旧周计划数据迁移（幂等：同用户同周期已存在则跳过）----
        try:
            import json as _json
            _day_cn = {'周一': 0, '周二': 1, '周三': 2, '周四': 3, '周五': 4, '周六': 5, '周日': 6}
            old_rows = db.execute("SELECT * FROM weekly_inspection_plans").fetchall()
            migrated = 0
            for old in old_rows:
                dup = db.execute(
                    "SELECT id FROM plan_schedules WHERE user_id=? AND period_start=? AND schedule_type='weekly' LIMIT 1",
                    (old['user_id'], old['week_start'])).fetchone()
                if dup:
                    continue
                # plan_data: {"1":[site_ids]} 或 {"周一":[site_ids]} → {"2026-07-13":{"sites":[...],"notes":""}}
                try:
                    old_pd = _json.loads(old['plan_data']) if old['plan_data'] else {}
                except Exception:
                    old_pd = {}
                new_pd = {}
                try:
                    ws = datetime.strptime(str(old['week_start'])[:10], '%Y-%m-%d')
                except Exception:
                    ws = None
                for key, site_ids in (old_pd or {}).items():
                    if not isinstance(site_ids, list):
                        continue
                    offset = None
                    if str(key).isdigit():
                        offset = int(key) - 1  # "1"=周一
                    elif key in _day_cn:
                        offset = _day_cn[key]
                    if offset is None or ws is None:
                        continue
                    d = (ws + timedelta(days=offset)).strftime('%Y-%m-%d')
                    new_pd[d] = {"sites": site_ids, "notes": ""}
                # 历史空计划没有任何可执行价值；删除后也不得在每次启动时反复迁回。
                if not any(day_data.get('sites') for day_data in new_pd.values()):
                    continue
                # 旧单车辆 → vehicle_days（有安排的日期都用这辆车）
                vehicle_days = {}
                if old['vehicle_id']:
                    for d, day_data in new_pd.items():
                        if day_data["sites"]:
                            vehicle_days[d] = old['vehicle_id']
                status = old['status'] if old['status'] in ('draft', 'submitted', 'approved', 'rejected', 'archived') else 'draft'
                db.execute("""
                    INSERT INTO plan_schedules
                        (user_id, schedule_type, period_start, period_end, plan_data, vehicle_days,
                         status, approver_id, submitted_at, approved_at, remarks, tasks_generated)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (old['user_id'], 'weekly', old['week_start'],
                     (ws + timedelta(days=6)).strftime('%Y-%m-%d') if ws else old['week_start'],
                     _json.dumps(new_pd, ensure_ascii=False), _json.dumps(vehicle_days),
                     status, old['approver_id'], old['submitted_at'], old['approved_at'],
                     old['remarks'] or '', 1 if status == 'approved' else 0))
                migrated += 1
            if migrated:
                db.commit()
                print(f'[Migrate] 旧周计划迁移完成（{migrated} 条 → plan_schedules）')
        except Exception as e:
            print(f'[Migrate] 旧周计划迁移跳过: {e}')

def migrate_reagent_qc():
    """试剂标定（更换后使用标样验证）：
    1. reagent_inventory 补 qc_status 兼容列（pending=待标定/passed=通过/failed=不通过）。
       默认 'passed'——存量数据视为已验证，避免历史库存全部被标为待标定。
    2. 创建 reagent_qc_records 表记录每次标定结果。"""
    with get_db() as db:
        db.execute("""
            CREATE TABLE IF NOT EXISTS reagent_qc_records (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                site_id INTEGER NOT NULL,
                reagent_id INTEGER NOT NULL,
                standard_value REAL,
                measured_value REAL,
                deviation REAL,
                passed INTEGER NOT NULL DEFAULT 0,
                fail_action TEXT DEFAULT '',
                operator TEXT DEFAULT '',
                operator_id INTEGER,
                qc_time TEXT,
                remark TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime')),
                FOREIGN KEY (site_id) REFERENCES sites(id)
            )""")
        for col_sql in [
            "ALTER TABLE reagent_inventory ADD COLUMN qc_status TEXT DEFAULT 'passed'",
            "ALTER TABLE reagent_records ADD COLUMN plan_id INTEGER",
            "ALTER TABLE reagent_qc_records ADD COLUMN plan_id INTEGER",
        ]:
            try:
                db.execute(col_sql)
            except Exception:
                pass
        db.commit()


def migrate_manual_report_closure():
    """为人工异常上报补齐核实、解决和归档的审计字段。"""
    with get_db() as db:
        try:
            cols = {r['name'] for r in db.execute("PRAGMA table_info(manual_reports)").fetchall()}
            for col, ctype in (
                ('verification_note', "TEXT DEFAULT ''"),
                ('verified_by', 'INTEGER'),
                ('verified_at', 'TEXT'),
                ('archived_by', 'INTEGER'),
                ('archived_at', 'TEXT'),
                ('resolved_at', 'TEXT'),
            ):
                if col not in cols:
                    db.execute(f"ALTER TABLE manual_reports ADD COLUMN {col} {ctype}")
            db.commit()
        except Exception as e:
            print(f'[Migrate] 人工上报闭环字段迁移跳过: {e}')

def migrate_parts_requests_v2():
    """将 parts_requests 扩展为统一备件单据模型。
    历史 spare_part_requests 保持只读；本迁移不搬迁、不扣库。
    plan_id=0 表示工单/现场临时申请，正数仍表示巡检执行包申请。"""
    with get_db() as db:
        db.execute("""CREATE TABLE IF NOT EXISTS parts_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            plan_id INTEGER NOT NULL DEFAULT 0,
            requester_id INTEGER NOT NULL DEFAULT 0,
            site_id INTEGER,
            work_order_no TEXT DEFAULT '',
            request_no TEXT DEFAULT '',
            source TEXT NOT NULL DEFAULT 'inspection',
            reason TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'pending',
            approver_id INTEGER,
            approve_comment TEXT DEFAULT '',
            approved_at TEXT,
            created_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        db.execute("""CREATE TABLE IF NOT EXISTS parts_request_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER NOT NULL,
            part_sku TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 1,
            created_at TEXT DEFAULT (datetime('now','localtime')),
            FOREIGN KEY (request_id) REFERENCES parts_requests(id)
        )""")
        for column_sql in [
            "ALTER TABLE parts_requests ADD COLUMN site_id INTEGER",
            "ALTER TABLE parts_requests ADD COLUMN work_order_no TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN request_no TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN source TEXT DEFAULT 'inspection'",
            "ALTER TABLE parts_requests ADD COLUMN reason TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN approver_id INTEGER",
            "ALTER TABLE parts_requests ADD COLUMN approve_comment TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN approved_at TEXT",
            "ALTER TABLE parts_requests ADD COLUMN fulfillment_type TEXT DEFAULT 'stock'",
            "ALTER TABLE parts_requests ADD COLUMN requested_part_name TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN specification TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN estimated_amount REAL",
            "ALTER TABLE parts_requests ADD COLUMN actual_amount REAL",
            "ALTER TABLE parts_requests ADD COLUMN supplier TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN approval_channel TEXT DEFAULT 'system'",
            "ALTER TABLE parts_requests ADD COLUMN receipt_no TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN tracking_no TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN evidence_urls TEXT DEFAULT '[]'",
            "ALTER TABLE parts_requests ADD COLUMN destination TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN old_part_disposition TEXT DEFAULT ''",
            "ALTER TABLE parts_requests ADD COLUMN ordered_at TEXT",
            "ALTER TABLE parts_requests ADD COLUMN received_at TEXT",
            "ALTER TABLE parts_requests ADD COLUMN completed_at TEXT",
            "ALTER TABLE parts_request_items ADD COLUMN part_id INTEGER",
        ]:
            try:
                db.execute(column_sql)
            except sqlite3.OperationalError as exc:
                if 'duplicate column name' not in str(exc).lower():
                    raise
        db.execute("""CREATE INDEX IF NOT EXISTS idx_parts_request_items_request_id
            ON parts_request_items(request_id)""")
        db.execute("""CREATE TABLE IF NOT EXISTS parts_request_reservations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER NOT NULL,
            part_id INTEGER NOT NULL,
            requested_quantity INTEGER NOT NULL DEFAULT 0,
            reserved_quantity INTEGER NOT NULL DEFAULT 0,
            issued_quantity INTEGER NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'reserved',
            created_at TEXT DEFAULT (datetime('now','localtime')),
            updated_at TEXT DEFAULT (datetime('now','localtime')),
            UNIQUE(request_id, part_id)
        )""")
        db.execute("""CREATE TABLE IF NOT EXISTS parts_request_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            operator_id INTEGER,
            operator TEXT DEFAULT '',
            details TEXT DEFAULT '{}',
            created_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        db.commit()


def retire_legacy_spare_part_requests():
    """将可识别的旧备件待审申请一次性纳入 v2；无法识别的记录保留为只读历史。

    旧表不再承担新增或审批职责，避免同一申请在两条链路中被重复处理。
    """
    with get_db() as db:
        try:
            legacy_rows = db.execute("""SELECT * FROM spare_part_requests
                WHERE status='pending' ORDER BY id""").fetchall()
            migrated = readonly = 0
            for legacy in legacy_rows:
                item = dict(legacy)
                inventory = db.execute(
                    "SELECT id, part_code FROM spare_parts_inventory WHERE part_name=? ORDER BY id LIMIT 1",
                    (item.get('part_name') or '',),
                ).fetchone()
                if not inventory or not item.get('site_id'):
                    db.execute("UPDATE spare_part_requests SET status='legacy_readonly' WHERE id=?", (item['id'],))
                    readonly += 1
                    continue
                requester = db.execute(
                    "SELECT id FROM users WHERE real_name=? OR username=? ORDER BY id LIMIT 1",
                    (item.get('applicant') or '', item.get('applicant') or ''),
                ).fetchone()
                request_no = f"LEGACY-{item['id']}"
                existing = db.execute("SELECT id FROM parts_requests WHERE request_no=?", (request_no,)).fetchone()
                if not existing:
                    cur = db.execute("""INSERT INTO parts_requests
                        (plan_id,requester_id,site_id,work_order_no,request_no,source,reason,status,created_at)
                        VALUES (0,?,?,?,?,?,?,'pending',COALESCE(?,datetime('now','localtime')))""", (
                            requester['id'] if requester else 0, item['site_id'], item.get('work_order_no') or '',
                            request_no, 'legacy_migration',
                            f"[历史申请 {item.get('request_no') or item['id']}] {item.get('reason') or ''}",
                            item.get('created_at'),
                        ))
                    db.execute("""INSERT INTO parts_request_items (request_id,part_sku,quantity,part_id)
                        VALUES (?,?,?,?)""", (cur.lastrowid, inventory['part_code'], item.get('quantity') or 1, inventory['id']))
                db.execute("UPDATE spare_part_requests SET status='migrated' WHERE id=?", (item['id'],))
                migrated += 1
            db.commit()
            if migrated or readonly:
                print(f'[Migrate] 旧备件待审收口：迁入v2 {migrated} 条，只读保留 {readonly} 条')
        except Exception as e:
            print(f'[Migrate] 旧备件待审收口跳过: {e}')

def _reconcile_device_management_scope(db):
    """Keep operational connectivity separate from asset lifecycle state."""
    db.execute("""UPDATE device_shadows SET management_scope='managed'
                  WHERE management_scope IS NULL OR TRIM(management_scope)=''
                     OR management_scope NOT IN ('managed','retired')""")
    if _table_exists(db, 'device_recycle'):
        db.execute("""UPDATE device_shadows
                      SET management_scope='retired', status='offline'
                      WHERE EXISTS (
                          SELECT 1 FROM device_recycle dr
                          WHERE dr.device_id=device_shadows.id AND dr.status='recycled'
                      )""")


