def auto_resolve_alerts(db, site_id):
    """检查未办结告警对应站点的数据是否已恢复，是则自动办结"""
    try:
        unresolved = db.execute(
            "SELECT id, metric FROM alerts WHERE site_id=? AND status IN ('pending','acknowledged') AND flow_type='auto'",
            (site_id,)
        ).fetchall()
        for a in unresolved:
            if a['metric'] == 'device_status':
                continue  # 设备状态告警需人工确认
            # 检查是否有最近1小时的数据
            has_data = db.execute(
                "SELECT COUNT(*) FROM sensor_data WHERE site_id=? AND recorded_at >= datetime('now','-1 hour')",
                (site_id,)
            ).fetchone()[0]
            if has_data > 0:
                db.execute("UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime') WHERE id=?", (a['id'],))
    except Exception as e:
        print(f'[AutoResolve] error site={site_id}: {e}')

# ---- 告警规则引擎缓存（避免每条数据都查DB）----
_alert_rules_cache = None
_alert_rules_cache_time = 0

def _load_alert_rules(db):
    """加载告警规则配置，缓存60秒"""
    global _alert_rules_cache, _alert_rules_cache_time
    now = __import__('time').time()
    if _alert_rules_cache is not None and (now - _alert_rules_cache_time) < 60:
        return _alert_rules_cache
    import json as _j
    rules = {}
    rows = db.execute('SELECT * FROM alert_rule_config WHERE enabled=1').fetchall()
    for r in rows:
        d = dict(r)
        try: d['thresholds'] = _j.loads(d['thresholds']) if d.get('thresholds') else {}
        except: d['thresholds'] = {}
        rules[d['metric']] = d
    _alert_rules_cache = rules
    _alert_rules_cache_time = now
    return rules

def detect_site_anomalies(db, site_id, site_type, metric, current_value, recorded_at):
    """检测单个站点指标的异常情况：突变、冻结、缺失"""
    METRIC_CN = {
        'codmn':'高锰酸盐指数','ammonia':'氨氮','total_phosphorus':'总磷','total_nitrogen':'总氮',
        'water_temp':'水温','dissolved_oxygen':'溶解氧','ph':'pH','turbidity':'浊度',
        'conductivity':'电导率','temperature':'气温',
        'data_spike':'数据突变','data_freeze':'数据冻结','data_gap':'数据缺失',
        'device_status':'设备状态',
    }
    metric_cn = METRIC_CN.get(metric, metric)

    # ===== 水质指标阈值超标检测（基于GB 3838-2002 III类水标准） =====
    WQ_THRESHOLDS = {
        'ph':              {'min': 6.0, 'max': 9.0, 'unit': ''},
        'dissolved_oxygen':{'min': 5.0, 'max': None,'unit': 'mg/L'},
        'codmn':           {'min': None,'max': 6.0,  'unit': 'mg/L'},
        'ammonia':         {'min': None,'max': 1.0,  'unit': 'mg/L'},
        'total_phosphorus':{'min': None,'max': 0.2,  'unit': 'mg/L'},
        'total_nitrogen':  {'min': None,'max': 1.0,  'unit': 'mg/L'},
        'turbidity':       {'min': None,'max': 20,   'unit': 'NTU'},
        'conductivity':    {'min': None,'max': None,  'unit': 'μS/cm'},
    }
    if metric in WQ_THRESHOLDS:
        th = WQ_THRESHOLDS[metric]
        exceeded = False
        level = 'yellow'
        msg = ''
        if th['min'] is not None and current_value < th['min']:
            exceeded = True
            level = 'orange' if current_value < th['min'] * 0.85 else 'yellow'
            msg = f'{metric_cn}偏低：{current_value:.2f}{th["unit"]}（阈值≥{th["min"]}{th["unit"]}）'
        if th['max'] is not None and current_value > th['max']:
            exceeded = True
            level = 'red' if current_value > th['max'] * 1.2 else 'orange'
            msg = f'{metric_cn}超标：{current_value:.2f}{th["unit"]}（阈值≤{th["max"]}{th["unit"]}）'
        # pH双向超标用更严重的等级
        if metric == 'ph' and exceeded:
            if current_value < 5.5 or current_value > 9.5:
                level = 'red'
            elif current_value < 6.0 or current_value > 9.0:
                level = 'orange'
        if exceeded:
            create_alert_internal(db, site_id, metric, current_value, level, msg)

    try:
        # 在检测新异常之前，先检查已有的未办结告警是否可自动恢复
        auto_resolve_alerts(db, site_id)
        # 自动解除已有data_gap误报：站点恢复数据后自动办结告警
        try:
            existing_gaps = db.execute(
                "SELECT id FROM alerts WHERE site_id=? AND metric='data_gap' AND status IN ('pending','acknowledged')",
                (site_id,)
            ).fetchall()
            if existing_gaps:
                recent_data = db.execute(
                    "SELECT COUNT(*) FROM sensor_data WHERE site_id=? AND recorded_at >= datetime('now','-1 hour')",
                    (site_id,)
                ).fetchone()[0]
                if recent_data > 0:
                    for gap in existing_gaps:
                        db.execute(
                            "UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime') WHERE id=?",
                            (gap['id'],)
                        )
                        db.execute(
                            "INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                            ('alert', gap['id'], 'resolved', '系统', '数据已自动恢复，告警自动办结')
                        )
        except Exception:
            pass
        # 排除自然波动大的指标（pH、溶解氧、电导率受环境影响正常波动）
        EXCLUDE_SPIKE = {'ph','dissolved_oxygen','conductivity','water_temp'}
        recent = db.execute(
            "SELECT value, recorded_at FROM sensor_data WHERE site_id=? AND metric=? ORDER BY recorded_at DESC LIMIT 12",
            (site_id, metric)
        ).fetchall()
        if len(recent) < 4:
            return
        values = [r['value'] for r in recent]
        timestamps = [r['recorded_at'] for r in recent]
        latest = values[0]

        # 1. 数据冻结检测：连续N条完全相同（N从规则引擎读取，默认6条）
        rule_freeze = _load_alert_rules(db).get('data_freeze', {})
        freeze_n = int((rule_freeze.get('thresholds') or {}).get('yellow', 6))
        if len(values) >= freeze_n and metric not in EXCLUDE_SPIKE:
            frozen = len(set(round(v, 4) for v in values[:freeze_n])) == 1
            if frozen:
                create_alert_internal(db, site_id, 'data_freeze', latest, 'yellow',
                    f'数据冻结：{metric_cn}连续{freeze_n}条记录值一致（{latest}），传感器可能故障')
                return

        # 2. 突变检测（排除自然波动指标）
        # 要求至少8条历史数据，确保趋势稳定后再检测（避免重启后误报）
        if len(values) >= 8 and metric not in EXCLUDE_SPIKE:
            prev_vals = values[1:8]
            mean = sum(prev_vals) / len(prev_vals)
            # 均值为0或接近0时跳过
            if abs(mean) < 0.001:
                return
            # 计算百分比变化
            pct_change = abs(latest - mean) / abs(mean)
            # 标准差检测
            std = (sum((v - mean)**2 for v in prev_vals) / len(prev_vals))**0.5
            if std < abs(mean) * 0.005:
                std = abs(mean) * 0.005
            z_score = abs(latest - mean) / std
            # 要求：变化幅度 > 30% 且 偏离 > 8σ，同时绝对变化值大于指标特定阈值
            min_abs_change = {'ph': 0.8, 'dissolved_oxygen': 1.5, 'ammonia': 0.15,
                              'codmn': 2, 'total_phosphorus': 0.05, 'total_nitrogen': 0.3,
                              'turbidity': 5, 'conductivity': 50, 'water_temp': 3}
            abs_change = abs(latest - mean)
            min_abs = min_abs_change.get(metric, abs(mean) * 0.35)
            # 从规则引擎读取突变百分比阈值（默认30%），同时保留Z-score和绝对变化值双重校验
            rule_spike = _load_alert_rules(db).get('data_spike', {})
            spike_pct = (rule_spike.get('thresholds') or {}).get('yellow', 30)
            if pct_change * 100 > spike_pct and z_score > 8 and abs_change > min_abs:
                direction = '陡增' if latest > mean else '陡降'
                level = 'red' if z_score > 10 else 'orange'
                create_alert_internal(db, site_id, 'data_spike', latest, level,
                    f'数据异常{direction}：{metric_cn} {latest:.2f}（均值{mean:.2f}，变化{pct_change*100:.0f}%）')

        # 3. 数据缺失检测（阈值从规则引擎读取，默认60分钟）
        if len(timestamps) >= 2:
            try:
                t1 = datetime.strptime(str(timestamps[0])[:19], '%Y-%m-%d %H:%M:%S')
                t0 = datetime.strptime(str(timestamps[1])[:19], '%Y-%m-%d %H:%M:%S')
                gap_min = (t1 - t0).total_seconds() / 60
                rule_gap = _load_alert_rules(db).get('data_gap', {})
                threshold = int((rule_gap.get('thresholds') or {}).get('yellow', 60))
                if gap_min > threshold:
                    create_alert_internal(db, site_id, 'data_gap', gap_min, 'yellow',
                        f'数据延迟：{metric_cn}已有{gap_min:.0f}分钟未更新')
            except Exception:
                pass
    except Exception as e:
        print(f'[Anomaly] 检测异常失败 site={site_id} metric={metric}: {e}')

def _scheduler_db():
    """专用调度器数据库连接（超时5秒，异步写入，避免阻塞API）"""
    db = sqlite3.connect(DB_PATH, timeout=5, check_same_thread=False)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA journal_mode=WAL")
    db.execute("PRAGMA busy_timeout=5000")
    db.execute("PRAGMA synchronous=OFF")
    return db

def generate_sensor_data():
    """每30秒生成模拟传感器数据"""
    PRESET_OFFLINE = {5}  # 预设离线站点（仅江桥水质监测站），跳过状态更新
    db = None
    try:
        db = _scheduler_db()
    except Exception as e:
        print(f'[Sim] 调度器连接失败: {e}')
        return
    try:
        sites = db.execute("SELECT * FROM sites").fetchall()
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

        for idx, site in enumerate(sites):
            sid = site['id']
            # 预设离线站点跳过所有数据生成，保持种子数据一致性
            if sid in PRESET_OFFLINE:
                # 预设离线站点：确保设备和站点状态为offline
                db.execute("UPDATE device_shadows SET status='offline' WHERE site_id=?", (sid,))
                db.execute("UPDATE sites SET status='offline' WHERE id=?", (sid,))
                try:
                    db.commit()
                except Exception:
                    pass
                continue
            try:
                _generate_site_data(site, db, now)
            except Exception as e:
                if 'database is locked' in str(e):
                    print(f'[Sim] DB locked, skip site {sid}')
                else:
                    print(f'[Sim] site {sid} error: {e}')

            # === 数据自洽性修复：设备/站点状态同步 ===
            # 0.5%概率设备离线（模拟真实场景），99.5%在线
            devices = db.execute("SELECT id FROM device_shadows WHERE site_id=?", (sid,)).fetchall()
            any_online = False
            for dev in devices:
                dev_status = 'offline' if random.random() < 0.005 else 'online'
                if dev_status == 'online':
                    any_online = True
                db.execute("UPDATE device_shadows SET status=?, last_data_time=? WHERE id=?",
                           (dev_status, now if dev_status == 'online' else None, dev['id']))

            # 站点状态根据设备状态决定：全部离线→站点离线，否则在线
            site_status = 'online' if any_online else 'offline'
            db.execute("UPDATE sites SET status=?, last_heartbeat=? WHERE id=?",
                       (site_status, now if site_status == 'online' else None, sid))

            # 每个站点单独提交，释放写锁，让API请求能快速插入
            try:
                db.commit()
            except Exception as e:
                print(f'[Sim] commit fail site {sid}: {e}')

        # === 数据自洽性修复：长时间无数据的设备自动标记离线 ===
        rule_dev = _load_alert_rules(db).get('device_status', {})
        dev_timeout = int((rule_dev.get('thresholds') or {}).get('yellow', 30))
        threshold_time = (datetime.now() - timedelta(minutes=dev_timeout)).strftime('%Y-%m-%d %H:%M:%S')
        stale_devices = db.execute(
            "SELECT id, site_id FROM device_shadows WHERE last_data_time < ? AND status != 'offline'",
            (threshold_time,)
        ).fetchall()
        for dev in stale_devices:
            db.execute("UPDATE device_shadows SET status='offline' WHERE id=?", (dev['id'],))
            # 检查该站点是否所有设备都离线
            online_count = db.execute(
                "SELECT COUNT(*) FROM device_shadows WHERE site_id=? AND status='online'",
                (dev['site_id'],)
            ).fetchone()[0]
            if online_count == 0:
                db.execute("UPDATE sites SET status='offline' WHERE id=?", (dev['site_id'],))
        if stale_devices:
            db.commit()

        # === 数据到报率模拟（在同一个连接中完成） ===
        today = datetime.now().strftime('%Y-%m-%d')
        for site in sites:
            metrics_map = {
                'water_quality': 'codmn',
                'manual_station': 'ammonia',
                'drinking_source': 'ph',
                'cross_boundary': 'total_nitrogen',
                'groundwater': 'ammonia',
            }
            m = metrics_map.get(site['type'])
            if not m: continue
            is_miss = random.random() < 0.08
            existing = db.execute(
                "SELECT id, expected_count, actual_count FROM data_arrival WHERE site_id=? AND date=? AND metric=?",
                (site['id'], today, m)
            ).fetchone()
            if existing:
                exp = existing['expected_count'] + 1
                act = existing['actual_count'] + (0 if is_miss else 1)
                rate = round(act / exp * 100, 1)
                db.execute("UPDATE data_arrival SET expected_count=?, actual_count=?, arrival_rate=? WHERE id=?",
                           (exp, act, rate, existing['id']))
            else:
                db.execute("INSERT INTO data_arrival (site_id,date,metric,expected_count,actual_count,arrival_rate) VALUES (?,?,?,1,?,?)",
                           (site['id'], today, m, 0 if is_miss else 1, 100 if not is_miss else 0))

        # === 天气数据 ===
        # 启动时尝试获取实时天气（不插入模拟数据，让 API 请求时自动刷新）
        fetch_real_weather()
        
        # === 离线设备告警 ===
        offline_devices = db.execute("""
            SELECT d.site_id, d.device_name, d.device_code, s.name as site_name
            FROM device_shadows d JOIN sites s ON d.site_id=s.id
            WHERE d.status='offline'
        """).fetchall()
        for dev in offline_devices:
            # 该站点已存在未闭环离线工单则跳过，避免模拟器每 30s 反复触发告警/工单
            if db.execute(
                "SELECT 1 FROM work_orders WHERE site_id=? AND metric IN ('device_status','data_gap') AND status NOT IN ('closed','resolved') LIMIT 1",
                (dev['site_id'],)
            ).fetchone():
                continue
            create_alert_internal(db, dev['site_id'], 'device_status', 0, 'yellow',
                f"设备离线: {dev['device_name']} ({dev['device_code']}) · {dev['site_name']}")
    except Exception as e:
        print(f'[Sim] 数据生成异常: {e}')
    finally:
        if db:
            try:
                db.close()
            except:
                pass

def migrate_alerts_messages():
    """迁移旧告警消息中的英文指标名为中文"""
    METRIC_EN_CN = {
        'codmn':'高锰酸盐指数','ammonia':'氨氮','total_phosphorus':'总磷','total_nitrogen':'总氮',
        'water_temp':'水温','dissolved_oxygen':'溶解氧','ph':'pH','turbidity':'浊度',
        'conductivity':'电导率','temperature':'气温',
        'data_spike':'数据突变','data_freeze':'数据冻结','data_gap':'数据缺失',
        'device_status':'设备状态'
    }
    with get_db() as db:
        for en, cn in METRIC_EN_CN.items():
            db.execute("UPDATE alerts SET message=REPLACE(message,?,?) WHERE message LIKE ?",
                       (en, cn, '%'+en+'%'))
        db.commit()
        fixed = db.execute("SELECT changes()").fetchone()[0]
        if fixed:
            print(f"[Migrate] 已修正 {fixed} 条告警消息中的英文指标名")

def migrate_alert_flow():
    """迁移告警表：新增 flow_type / flow_status / tracking 字段"""
    with get_db() as db:
        for col_sql in [
            "ALTER TABLE alerts ADD COLUMN flow_type TEXT DEFAULT 'manual'",
            "ALTER TABLE alerts ADD COLUMN flow_status TEXT DEFAULT 'pending_review'",
            "ALTER TABLE alerts ADD COLUMN tracking_count INTEGER DEFAULT 0",
        ]:
            try:
                db.execute(col_sql)
            except Exception:
                pass
        # 所有未设 flow_type 的告警统一为 manual（create_alert_internal 自行管理 auto 类型）
        db.execute("UPDATE alerts SET flow_type='manual', flow_status='pending_review' WHERE flow_type IS NULL")
        # 已有 related_order_no 的设置 converted
        db.execute("UPDATE alerts SET flow_status='converted' WHERE related_order_no IS NOT NULL AND related_order_no != ''")
        # 修复：之前被错误自动转化的 data_gap/device_status 告警 → 重置为手动复核
        # （仅限没有关联工单的，有工单的保持已完结状态）
        db.execute("UPDATE alerts SET flow_type='manual', flow_status='pending_review', status='pending' WHERE metric IN ('data_gap','device_status') AND flow_type='auto' AND (related_order_no IS NULL OR related_order_no='')")
        db.commit()
        # 统计修复的告警数
        fixed = db.execute("SELECT COUNT(*) as c FROM alerts WHERE flow_type='manual' AND flow_status='pending_review' AND status='pending' AND metric IN ('data_gap','device_status')").fetchone()['c']
        if fixed:
            print(f"[Migrate] 已重置 {fixed} 条 device_status/data_gap 告警为手动复核模式")
        print("[Migrate] alert_flow 迁移完成: flow_type/flow_status 字段已添加并初始化")

def _auto_convert_alert(db, alert_id, site_id, alert_level, message, metric):
    """A级告警自动转工单（防重复：同站点离线类已有未闭环工单则跳过，避免列表重复）"""
    # 离线类告警（设备离线/数据缺失）视为同一现场事件，按站点去重
    OFFLINE_METRICS = ('device_status', 'data_gap')
    if metric in OFFLINE_METRICS:
        dup = db.execute(
            "SELECT order_no FROM work_orders WHERE site_id=? AND metric IN ('device_status','data_gap') AND status NOT IN ('closed','resolved') LIMIT 1",
            (site_id,)
        ).fetchone()
        if dup:
            # 已存在未闭环工单：仅关联告警，不再新建，消除重复工单
            db.execute("UPDATE alerts SET flow_status='converted', related_order_no=?, status='pending' WHERE id=?",
                       (dup['order_no'], alert_id))
            return
    now = datetime.now()
    order_no = f"WO-{now.strftime('%Y%m%d')}-{random.randint(100,999)}"
    order_level = 'critical' if alert_level == 'red' else ('urgent' if alert_level == 'orange' else 'normal')
    sla_hours = {'normal': 72, 'urgent': 24, 'critical': 2}.get(order_level, 72)
    sla_deadline = (now + timedelta(hours=sla_hours)).strftime('%Y-%m-%d %H:%M')

    # 自动派单：根据站点责任人（user_sites 唯一真相源），忽略前端任意指派
    site = db.execute("SELECT manager FROM sites WHERE id=?", (site_id,)).fetchone()
    assignee = _station_operator(site_id) if site else ''

    # description 与 title 均仅取单条干净消息（按 ' | ' 取首段），杜绝多段拼接导致的重复/乱码
    clean_desc = (message or '').split(' | ')[0] if message else ''
    db.execute("""
        INSERT INTO work_orders (order_no,site_id,source,event_type,metric,level,title,description,assignee,status,sla_deadline,related_alert_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        order_no, site_id, 'auto', '告警自动转工单', metric or '',
        order_level, _generated_workorder_title('auto', clean_desc, metric or '告警自动转工单'), clean_desc,
        assignee, 'pending', sla_deadline, alert_id
    ))
    # 更新告警状态：保持 pending 可见，标记已流转
    db.execute("UPDATE alerts SET flow_status='converted', related_order_no=?, status='pending' WHERE id=?",
               (order_no, alert_id))
    # 时间线
    db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
               ('alert', alert_id, 'auto_converted', '系统', f'自动转工单 {order_no}'))
    db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
               ('order', 0, 'auto_created', '系统', f'告警{alert_id}自动转工单-{order_no}'))

# =============================================================================
# 微信订阅消息推送（移动端）
# 设计原则：最佳努力（best-effort）—— 任何微信接口异常均静默捕获，绝不阻断
# 主业务流程（告警生成 / 工单审批）。未配置 AppSecret 或模板 ID 时直接跳过。
# 推送对象：按站点群发——查该站点已绑定 openid 的用户逐个下发（因 work_orders
# 的 assignee 存的是 real_name，不可靠，故统一按 user_sites 站点级投递，与告警一致）。
# =============================================================================
_WX_TOKEN_CACHE = {'token': '', 'expire_at': 0}

def _wx_get_access_token():
    """获取并缓存微信 access_token（默认 7200s 有效期，提前 60s 续期）"""
    global _WX_TOKEN_CACHE
    now = time.time()
    if _WX_TOKEN_CACHE['token'] and _WX_TOKEN_CACHE['expire_at'] > now + 60:
        return _WX_TOKEN_CACHE['token']
    if not WX_APPID or not WX_APPSECRET:
        return ''
    try:
        url = ("https://api.weixin.qq.com/cgi-bin/token"
                "?grant_type=client_credential&appid=%s&secret=%s" % (WX_APPID, WX_APPSECRET))
        req = urllib.request.Request(url, headers={'User-Agent': 'water-ops'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = _json.loads(resp.read().decode('utf-8'))
        if 'access_token' in data:
            _WX_TOKEN_CACHE['token'] = data['access_token']
            _WX_TOKEN_CACHE['expire_at'] = now + int(data.get('expires_in', 7200))
            return data['access_token']
        print('[WX] access token unavailable errcode=%s' % data.get('errcode', 'unknown'))
    except Exception:
        print('[WX] access token request failed')
    return ''

def _wx_code2openid(code):
    """用 wx.login 拿到的 code 换取用户 openid"""
    if not WX_APPID or not WX_APPSECRET or not code:
        return ''
    try:
        url = ("https://api.weixin.qq.com/sns/jscode2session"
                "?appid=%s&secret=%s&js_code=%s&grant_type=authorization_code"
                % (WX_APPID, WX_APPSECRET, code))
        req = urllib.request.Request(url, headers={'User-Agent': 'water-ops'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = _json.loads(resp.read().decode('utf-8'))
        if 'openid' in data:
            return data['openid']
        print('[WX] openid exchange unavailable errcode=%s' % data.get('errcode', 'unknown'))
    except Exception:
        print('[WX] openid exchange failed')
    return ''

def _wx_push_subscribe(openid, template_id, data):
    """向单个 openid 下发订阅消息，成功返回 True；参数缺失或失败返回 False"""
    if not openid or not template_id:
        return False
    token = _wx_get_access_token()
    if not token:
        return False
    try:
        url = "https://api.weixin.qq.com/cgi-bin/message/subscribe/send?access_token=%s" % token
        payload = _json.dumps({
            'touser': openid,
            'template_id': template_id,
            'data': data,
        }).encode('utf-8')
        req = urllib.request.Request(url, data=payload,
                                    headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            result = _json.loads(resp.read().decode('utf-8'))
        if result.get('errcode', 0) == 0:
            return True
        print('[WX] subscription delivery rejected errcode=%s' % result.get('errcode', 'unknown'))
    except Exception:
        print('[WX] subscription delivery request failed')
    return False


def _wx_trim(value, limit):
    text = str(value or '').strip()
    return text[:limit]


def _wx_page(path, **params):
    query = urllib.parse.urlencode({key: value for key, value in params.items()
                                    if value not in (None, '')})
    return path + (('?' + query) if query else '')


def _wx_pending_data(request_type, project, applicant, request_no, submitted_at):
    return {
        'thing9': {'value': _wx_trim(request_type, 20)},
        'thing8': {'value': _wx_trim(project, 20)},
        'thing4': {'value': _wx_trim(applicant, 20)},
        'character_string7': {'value': _wx_trim(request_no, 32)},
        'time6': {'value': _wx_trim(submitted_at, 20)},
    }


def _wx_result_data(review_type, project, result, reviewed_at, next_step):
    return {
        'thing18': {'value': _wx_trim(review_type, 20)},
        'thing1': {'value': _wx_trim(project, 20)},
        'thing5': {'value': _wx_trim(result, 20)},
        'time3': {'value': _wx_trim(reviewed_at, 20)},
        'thing4': {'value': _wx_trim(next_step, 20)},
    }


def _ensure_wx_outbox_schema(db):
    db.execute("""CREATE TABLE IF NOT EXISTS wx_subscription_outbox (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        dedupe_key TEXT NOT NULL UNIQUE,
        purpose TEXT NOT NULL,
        business_type TEXT NOT NULL,
        business_id TEXT NOT NULL,
        business_status TEXT NOT NULL,
        recipient_user_id INTEGER NOT NULL,
        template_id TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        context_json TEXT DEFAULT '{}',
        cycle_key TEXT NOT NULL DEFAULT '',
        page TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending',
        attempts INTEGER NOT NULL DEFAULT 0,
        claim_token TEXT DEFAULT '',
        claimed_at TEXT,
        next_attempt_at TEXT,
        last_errcode TEXT DEFAULT '',
        last_error TEXT DEFAULT '',
        created_at TEXT DEFAULT (datetime('now','localtime')),
        updated_at TEXT DEFAULT (datetime('now','localtime')),
        sent_at TEXT
    )""")
    db.execute("""CREATE INDEX IF NOT EXISTS idx_wx_outbox_delivery
        ON wx_subscription_outbox(status,next_attempt_at,id)""")
    columns = {row['name'] for row in db.execute('PRAGMA table_info(wx_subscription_outbox)').fetchall()}
    for column, definition in (
            ('cycle_key', "TEXT NOT NULL DEFAULT ''"),
            ('page', "TEXT NOT NULL DEFAULT ''"),
            ('claim_token', "TEXT DEFAULT ''"),
            ('claimed_at', 'TEXT')):
        if column not in columns:
            db.execute(f'ALTER TABLE wx_subscription_outbox ADD COLUMN {column} {definition}')


def _wx_user_roles(db, user_id):
    user = db.execute('SELECT * FROM users WHERE id=?', (user_id,)).fetchone()
    if not user:
        return None, set()
    roles = {str(user['role'] or '').strip()} if 'role' in user.keys() else set()
    if _table_exists(db, 'user_roles'):
        roles.update(str(row['role'] or '').strip() for row in db.execute(
            'SELECT role FROM user_roles WHERE user_id=?', (user_id,)).fetchall())
    return user, {role for role in roles if role}


def _wx_pending_recipient_allowed(db, user_id, business_type, context):
    user, roles = _wx_user_roles(db, user_id)
    if not user or ('status' in user.keys() and user['status'] != 'active'):
        return False
    if business_type in ('plan_schedule', 'vehicle_application', 'parts_request'):
        return 'admin' in roles
    if business_type == 'workorder':
        if 'admin' in roles:
            return True
        site_id = context.get('site_id')
        return bool(roles.intersection({'reviewer', 'inspector'}) and site_id and db.execute(
            'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?', (user_id, site_id)
        ).fetchone())
    return False


def _wx_queue_intent(db, purpose, business_type, business_id, business_status,
                     recipient_user_id, payload, context=None, cycle_key='', page=''):
    if not recipient_user_id or purpose not in WX_SUBSCRIPTION_TEMPLATES:
        return None
    context = context or {}
    user, _ = _wx_user_roles(db, recipient_user_id)
    if not user or ('status' in user.keys() and user['status'] != 'active'):
        return None
    if purpose == 'approval_pending' and not _wx_pending_recipient_allowed(
            db, recipient_user_id, business_type, context):
        return None
    cycle_key = str(cycle_key or business_status)
    page = str(page or '').strip()
    if not page.startswith('/pages/') or '://' in page or len(page) > 512:
        return None
    dedupe_key = ':'.join((purpose, business_type, str(business_id),
                           cycle_key, str(recipient_user_id)))
    _ensure_wx_outbox_schema(db)
    db.execute("""INSERT OR IGNORE INTO wx_subscription_outbox
        (dedupe_key,purpose,business_type,business_id,business_status,
         recipient_user_id,template_id,payload_json,context_json,cycle_key,page)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""", (
            dedupe_key, purpose, business_type, str(business_id), str(business_status),
            recipient_user_id, WX_SUBSCRIPTION_TEMPLATES[purpose],
            json.dumps(payload, ensure_ascii=False, separators=(',', ':')),
            json.dumps(context, ensure_ascii=False, separators=(',', ':')),
            cycle_key, page,
        ))
    row = db.execute('SELECT id FROM wx_subscription_outbox WHERE dedupe_key=?',
                     (dedupe_key,)).fetchone()
    return row['id'] if row else None


def _wx_queue_pending_approval(db, business_type, business_id, business_status,
                               recipient_ids, submitter_id, request_type, project,
                               request_no, submitted_at, site_id=None,
                               cycle_key='', page=''):
    submitter = db.execute('SELECT real_name FROM users WHERE id=?', (submitter_id,)).fetchone()
    submitter_name = (submitter['real_name'] or '').strip() if submitter else ''
    payload = _wx_pending_data(request_type, project, submitter_name or f'用户{submitter_id}',
                               request_no, submitted_at)
    ids = []
    for user_id in sorted(set(recipient_ids or [])):
        if user_id == submitter_id:
            continue
        context = {'site_id': site_id, 'submitter_id': submitter_id,
                   'cycle_key': cycle_key}
        if business_type == 'workorder' and str(cycle_key).startswith('review:'):
            try:
                context['review_cycle'] = int(str(cycle_key).split(':', 1)[1])
            except ValueError:
                pass
        outbox_id = _wx_queue_intent(
            db, 'approval_pending', business_type, business_id, business_status,
            user_id, payload, context, cycle_key=cycle_key, page=page)
        if outbox_id:
            ids.append(outbox_id)
    return ids


def _wx_queue_approval_result(db, business_type, business_id, business_status,
                              recipient_user_id, review_type, project, result,
                              reviewed_at, next_step, cycle_key='', page=''):
    return _wx_queue_intent(
        db, 'approval_result', business_type, business_id, business_status,
        recipient_user_id,
        _wx_result_data(review_type, project, result, reviewed_at, next_step), {},
        cycle_key=cycle_key, page=page)


def _wx_intent_business_current(db, row, context):
    if row['purpose'] != 'approval_pending':
        return True
    business_type = row['business_type']
    if business_type == 'plan_schedule':
        current = db.execute('SELECT status FROM plan_schedules WHERE id=?',
                             (row['business_id'],)).fetchone()
        cycle_key = str(context.get('cycle_key') or '')
        if current and cycle_key.startswith('event:'):
            latest = db.execute("""SELECT id FROM plan_schedule_events
                WHERE schedule_id=? AND event_type IN ('submitted','change_submitted')
                ORDER BY id DESC LIMIT 1""", (row['business_id'],)).fetchone()
            if not latest or cycle_key != f'event:{latest["id"]}':
                return False
    elif business_type == 'vehicle_application':
        current = db.execute('SELECT status FROM vehicle_applications WHERE id=?',
                             (row['business_id'],)).fetchone()
    elif business_type == 'parts_request':
        current = db.execute('SELECT status FROM parts_requests WHERE id=?',
                             (row['business_id'],)).fetchone()
    elif business_type == 'workorder':
        cycle_column = ',review_cycle' if _table_has_column(db, 'work_orders', 'review_cycle') else ''
        current = db.execute(f'SELECT status{cycle_column} FROM work_orders WHERE order_no=?',
                             (row['business_id'],)).fetchone()
        if current and cycle_column and int(current['review_cycle'] or 0) != int(context.get('review_cycle') or 0):
            return False
    else:
        return False
    return bool(current and str(current['status']) == str(row['business_status']))


def _wx_send_subscribe_result(openid, template_id, data, page=''):
    if not WX_APPID or not WX_APPSECRET or not template_id:
        return {'ok': False, 'permanent': True, 'status': 'config_missing', 'errcode': ''}
    if not openid:
        return {'ok': False, 'permanent': True, 'status': 'no_openid', 'errcode': ''}
    token = _wx_get_access_token()
    if not token:
        return {'ok': False, 'permanent': False, 'status': 'temporary_failure', 'errcode': 'TOKEN'}
    try:
        url = 'https://api.weixin.qq.com/cgi-bin/message/subscribe/send?access_token=%s' % token
        request_body = _json.dumps({
            'touser': openid, 'template_id': template_id, 'data': data, 'page': page,
            'miniprogram_state': WX_MINIPROGRAM_STATE,
        }).encode('utf-8')
        req = urllib.request.Request(url, data=request_body,
                                    headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            result = _json.loads(resp.read().decode('utf-8'))
    except Exception:
        return {'ok': False, 'permanent': False, 'status': 'temporary_failure', 'errcode': 'NETWORK'}
    errcode = str(result.get('errcode', 0))
    if errcode == '0':
        return {'ok': True, 'permanent': True, 'status': 'sent', 'errcode': '0'}
    if errcode in ('40001', '40014', '42001'):
        _WX_TOKEN_CACHE['token'] = ''
        _WX_TOKEN_CACHE['expire_at'] = 0
        status = 'temporary_failure'
    elif errcode == '43101':
        status = 'no_authorization'
    elif errcode in ('40003', '40037', '47003'):
        status = 'permanent_failure'
    else:
        status = 'temporary_failure'
    return {'ok': False, 'permanent': status != 'temporary_failure',
            'status': status, 'errcode': errcode}


def _wx_flush_outbox(outbox_ids=None, limit=20):
    claim_token = uuid.uuid4().hex
    try:
        with get_db() as db:
            _ensure_wx_outbox_schema(db)
            db.execute("""UPDATE wx_subscription_outbox
                SET status='temporary_failure',claim_token='',claimed_at=NULL,
                    next_attempt_at=datetime('now','localtime')
                WHERE status='sending' AND claimed_at<datetime('now','localtime','-5 minutes')""")
            params = []
            id_clause = ''
            if outbox_ids:
                ids = list(dict.fromkeys(int(item) for item in outbox_ids if item))
                if not ids:
                    return
                id_clause = ' AND id IN (%s)' % ','.join('?' for _ in ids)
                params.extend(ids)
            candidates = db.execute("""SELECT id FROM wx_subscription_outbox
                WHERE status IN ('pending','temporary_failure')
                  AND attempts < 3
                  AND (next_attempt_at IS NULL OR next_attempt_at<=datetime('now','localtime'))"""
                + id_clause + ' ORDER BY id LIMIT ?', params + [limit]).fetchall()
            claimed_ids = []
            for candidate in candidates:
                changed = db.execute("""UPDATE wx_subscription_outbox
                    SET status='sending',claim_token=?,claimed_at=datetime('now','localtime')
                    WHERE id=? AND status IN ('pending','temporary_failure')
                      AND (next_attempt_at IS NULL OR next_attempt_at<=datetime('now','localtime'))""",
                    (claim_token, candidate['id']))
                if changed.rowcount:
                    claimed_ids.append(candidate['id'])
            db.commit()
            if not claimed_ids:
                return
            rows = db.execute("""SELECT * FROM wx_subscription_outbox
                WHERE claim_token=? AND status='sending' ORDER BY id""", (claim_token,)).fetchall()
        for row in rows:
            context = json.loads(row['context_json'] or '{}')
            with get_db() as db:
                if not _wx_intent_business_current(db, row, context):
                    db.execute("""UPDATE wx_subscription_outbox
                        SET status='superseded',claim_token='',claimed_at=NULL,
                            updated_at=datetime('now','localtime')
                        WHERE id=? AND status='sending' AND claim_token=?""",
                        (row['id'], claim_token))
                    db.commit()
                    continue
                user, _ = _wx_user_roles(db, row['recipient_user_id'])
                allowed = (row['purpose'] != 'approval_pending' or _wx_pending_recipient_allowed(
                    db, row['recipient_user_id'], row['business_type'], context))
                openid = user['openid'] if user and 'openid' in user.keys() else ''
            if not user or ('status' in user.keys() and user['status'] != 'active') or not allowed:
                result = {'ok': False, 'permanent': True, 'status': 'permanent_failure',
                          'errcode': 'RECIPIENT_INELIGIBLE'}
            else:
                result = _wx_send_subscribe_result(
                    openid, row['template_id'], json.loads(row['payload_json']), row['page'])
            with get_db() as db:
                attempts = int(row['attempts'] or 0) + 1
                next_retry = None if result['permanent'] else datetime.now() + timedelta(minutes=attempts)
                db.execute("""UPDATE wx_subscription_outbox
                    SET status=?,attempts=?,next_attempt_at=?,last_errcode=?,last_error='',
                        claim_token='',claimed_at=NULL,
                        updated_at=datetime('now','localtime'),
                        sent_at=CASE WHEN ?='sent' THEN datetime('now','localtime') ELSE sent_at END
                    WHERE id=? AND status='sending' AND claim_token=?""", (
                        result['status'], attempts,
                        next_retry.strftime('%Y-%m-%d %H:%M:%S') if next_retry else None,
                        result['errcode'], result['status'], row['id'], claim_token))
                db.commit()
    except Exception as exc:
        print('[WX] outbox delivery failed safely: %s' % type(exc).__name__)

def _wx_push_to_site_users(site_id, template_id, data):
    """按站点群发：查该站点已绑定 openid 的用户，逐个下发订阅消息"""
    if not site_id or not template_id:
        return
    try:
        with get_db() as db:
            rows = db.execute(
                "SELECT DISTINCT u.openid FROM users u "
                "JOIN user_sites us ON us.user_id=u.id "
                "WHERE us.site_id=? AND u.openid IS NOT NULL AND u.openid!=''",
                (site_id,)
            ).fetchall()
        for r in rows:
            _wx_push_subscribe(r['openid'], template_id, data)
    except Exception as e:
        print('[WX] 站点群发异常 site_id=%s: %s' % (site_id, e))

def _wx_push_alert(site_id, metric, value, level, message):
    """新告警产生时，向该站点负责用户推送「告警信息」订阅消息

    推送字段结构与微信「告警信息」订阅模板关键词对应（见上方配置注释）：
        thing1=告警内容 / character_string1=站点编码 / phrase2=告警等级 / time3=告警时间
    """
    if not WX_TMPL_ALERT:
        return
    # 告警等级/指标中文（内联映射，避免依赖局部变量）
    level_cn = {'red': '红色', 'orange': '橙色', 'yellow': '黄色', 'blue': '蓝色'}.get(level, level or '')
    metric_cn = METRIC_CN.get(metric, metric or '')
    # 站点名称：优先用站点 name，fallback code / site_id
    site_name = ''
    try:
        with get_db() as db:
            row = db.execute("SELECT code, name FROM sites WHERE id=?", (site_id,)).fetchone()
        if row:
            site_name = (row['name'] or row['code'] or str(site_id))[:20]
    except Exception:
        site_name = str(site_id)[:20]
    # 告警内容：指标类(metric_cn) + 说明；特殊告警类型(data_spike/data_freeze/data_gap/device_status)的 message 已语义完整，直接取 message 避免重复
    SPECIAL_ALERT_METRICS = {'data_spike', 'data_freeze', 'data_gap', 'device_status'}
    if metric in SPECIAL_ALERT_METRICS and message:
        content = message[:20]
    elif message:
        content = (metric_cn + '：' + message)[:20]
    else:
        content = (metric_cn or '水质') + '异常'
    # 告警推送字段：按微信「监测预警信息通知」模板关键词
    #   thing1=预警接收人 / thing2=预警内容 / time3=预警时间 / thing7=监测点名称
    data = {
        'thing1': {'value': '站点负责人'},
        'thing2': {'value': content[:20]},
        'time3': {'value': datetime.now().strftime('%Y年%m月%d日 %H:%M:%S')},
        'thing7': {'value': site_name},
    }
    _wx_push_to_site_users(site_id, WX_TMPL_ALERT, data)

def create_alert_internal(db, site_id, metric, value, level, message):
    """创建告警——同站点合并为一条告警（不同异常追加消息），去重同站点同metric"""
    LEVEL_PRIORITY = {'yellow':0, 'orange':1, 'red':2}
    # 判断流转类型（A级：data_gap/device_status → 自动转工单；B级：其他 → 人工复核）
    A_LEVEL_METRICS = {'data_gap', 'device_status'}
    is_auto = metric in A_LEVEL_METRICS
    flow_type = 'auto' if is_auto else 'manual'
    flow_status = 'pending' if is_auto else 'pending_review'

    # 强化去重：同site+同metric+同level+未办结 且120分钟内 → 更新tracking_count，不新建
    dedup_window = "datetime('now','localtime','-120 minutes')"
    existing = db.execute(
        f"SELECT id, tracking_count FROM alerts WHERE site_id=? AND metric=? AND level=? AND status IN ('pending','acknowledged') AND created_at > {dedup_window}",
        (site_id, metric, level if level else 'yellow')
    ).fetchone()
    if existing:
        new_count = (existing['tracking_count'] or 0) + 1
        db.execute(
            "UPDATE alerts SET tracking_count=?, message=?, created_at=datetime('now','localtime') WHERE id=?",
            (new_count, message, existing['id'])
        )
        db.commit()
        return existing['id']

    # 同站点同metric精确去重（120分钟窗口）——计数累加
    same = db.execute(
        f"SELECT id, tracking_count FROM alerts WHERE site_id=? AND metric=? AND status!='resolved' AND created_at > {dedup_window}",
        (site_id, metric)
    ).fetchone()
    if same:
        new_tracking = (same['tracking_count'] or 0) + 1
        db.execute("UPDATE alerts SET tracking_count=?, value=? WHERE id=?",
                   (new_tracking, value, same['id']))
        # 同一测项第3次触发 → 自动升级为A级
        if new_tracking >= 2:
            db.execute("UPDATE alerts SET flow_type='auto', flow_status='pending' WHERE id=?",
                       (same['id'],))
            alert_row = db.execute("SELECT * FROM alerts WHERE id=?", (same['id'],)).fetchone()
            if alert_row and alert_row['flow_type'] == 'auto' and alert_row['flow_status'] == 'pending':
                _auto_convert_alert(db, same['id'], site_id, alert_row['level'],
                                    alert_row['message'], metric)
        return same['id']

    # 检查同站点其他metric的未办结告警（120分钟内合并到同一条告警）
    existing = db.execute(
        f"SELECT id, message, level, flow_type, flow_status FROM alerts WHERE site_id=? AND status!='resolved' AND created_at > {dedup_window} ORDER BY id DESC LIMIT 1",
        (site_id,)
    ).fetchone()
    if existing:
        new_level = level
        if LEVEL_PRIORITY.get(existing['level'], 0) > LEVEL_PRIORITY.get(level, 0):
            new_level = existing['level']
        # 仅当新消息未包含于已有消息时追加，避免模拟器轮询反复拼接导致消息膨胀
        if message and message not in existing['message']:
            new_message = existing['message'] + ' | ' + message
        else:
            new_message = existing['message']

        # 合并后包含A级metric → 整体视为A级
        merged_flow_type = existing['flow_type']
        merged_flow_status = existing['flow_status']
        if is_auto or existing['flow_type'] == 'auto':
            merged_flow_type = 'auto'
            merged_flow_status = 'pending'

        db.execute(
            "UPDATE alerts SET message=?, level=?, value=?, flow_type=?, flow_status=? WHERE id=?",
            (new_message, new_level, value, merged_flow_type, merged_flow_status, existing['id'])
        )

        # 合并后为A级且原未转工单 → 立即自动转工单
        if merged_flow_type == 'auto' and existing['flow_status'] in ('pending', 'pending_review'):
            # 传递单条 message（非拼接 blob）；重复工单由 _auto_convert_alert 内站点去重拦截
            _auto_convert_alert(db, existing['id'], site_id, new_level, message, metric)
    else:
        db.execute(
            "INSERT INTO alerts (site_id,metric,value,level,message,flow_type,flow_status) VALUES (?,?,?,?,?,?,?)",
            (site_id, metric, value, level, message, flow_type, flow_status)
        )
        new_id = db.execute("SELECT last_insert_rowid()").fetchone()[0]
        # 新创建的A级告警 → 立即自动转工单
        if is_auto:
            _auto_convert_alert(db, new_id, site_id, level, message, metric)
        # 推送订阅消息给站点负责用户（最佳努力，不阻断主流程）
        try:
            _wx_push_alert(site_id, metric, value, level, message)
        except Exception as e:
            print('[WX] 告警推送异常: %s' % e)
        return new_id

    return existing['id']

# ===================== 登录认证系统 =====================

# Token存储
_tokens = {}
# 站点范围缓存：token -> [site_id,...]，避免每个/api/请求都查 user_sites（消除并发读时的锁等待卡顿）
_site_ids_cache = {}
AUTH_SESSION_HOURS = max(1, int(os.environ.get('AUTH_SESSION_HOURS', str(30 * 24))))
LOGIN_FAILURE_LIMIT = max(3, int(os.environ.get('LOGIN_FAILURE_LIMIT', '5')))
LOGIN_ATTEMPT_WINDOW_SECONDS = max(60, int(os.environ.get('LOGIN_ATTEMPT_WINDOW_SECONDS', '900')))
LOGIN_LOCK_BASE_SECONDS = max(10, int(os.environ.get('LOGIN_LOCK_BASE_SECONDS', '60')))
LOGIN_LOCK_MAX_SECONDS = max(LOGIN_LOCK_BASE_SECONDS, int(os.environ.get('LOGIN_LOCK_MAX_SECONDS', '900')))
_PASSWORD_CHANGE_PATHS = {
    '/api/auth/me',
    '/api/auth/logout',
    '/api/auth/change-password',
}
_KNOWN_DEFAULT_PASSWORD_HASHES = {
    'admin': hashlib.sha256(b'admin123').hexdigest(),
    'personnel': hashlib.sha256(b'yw123456').hexdigest(),
}

def _hash_pw(pw):
    return hashlib.sha256(pw.encode()).hexdigest()


def _hash_token(token):
    return hashlib.sha256(token.encode()).hexdigest()


def _table_exists(db, table_name):
    return db.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table_name,)
    ).fetchone() is not None


def _current_actor_name(fallback='系统'):
    user = getattr(g, 'current_user', None) or {}
    return user.get('real_name') or user.get('username') or fallback


def _actor_display_name(db, actor='', actor_id=None, fallback='系统'):
    """Return a business-facing name while preserving legacy account-based records."""
    if actor_id:
        row = db.execute("SELECT real_name FROM users WHERE id=?", (actor_id,)).fetchone()
        if row and (row['real_name'] or '').strip():
            return row['real_name'].strip()
    raw_actor = (actor or '').strip()
    if raw_actor:
        row = db.execute(
            "SELECT real_name FROM users WHERE username=? OR real_name=? ORDER BY CASE WHEN username=? THEN 0 ELSE 1 END LIMIT 1",
            (raw_actor, raw_actor, raw_actor),
        ).fetchone()
        if row and (row['real_name'] or '').strip():
            return row['real_name'].strip()
        return raw_actor
    return fallback


def _login_client_ip():
    remote = request.remote_addr or 'unknown'
    if remote in ('127.0.0.1', '::1'):
        forwarded = (request.headers.get('X-Forwarded-For') or '').split(',')[0].strip()
        if forwarded:
            return forwarded[:64]
    return remote[:64]


def _login_throttle_status(db, username, ip_address):
    if not _table_exists(db, 'auth_login_attempts'):
        return None
    cutoff = (datetime.now() - timedelta(seconds=LOGIN_ATTEMPT_WINDOW_SECONDS)).strftime('%Y-%m-%d %H:%M:%S')
    counts = []
    latest_failures = []
    for field, value in (('username', username), ('ip_address', ip_address)):
        row = db.execute(
            f"""SELECT COUNT(*) AS failures, MAX(attempted_at) AS latest_failure
                FROM auth_login_attempts
                WHERE {field}=? AND success=0 AND attempted_at>=?""",
            (value, cutoff),
        ).fetchone()
        counts.append(int(row['failures'] or 0))
        if row['latest_failure']:
            latest_failures.append(row['latest_failure'])
    failures = max(counts or [0])
    if failures < LOGIN_FAILURE_LIMIT or not latest_failures:
        return None
    lock_seconds = min(
        LOGIN_LOCK_MAX_SECONDS,
        LOGIN_LOCK_BASE_SECONDS * (2 ** min(failures - LOGIN_FAILURE_LIMIT, 4)),
    )
    latest = max(datetime.strptime(value, '%Y-%m-%d %H:%M:%S') for value in latest_failures)
    retry_after = int(lock_seconds - (datetime.now() - latest).total_seconds())
    return max(1, retry_after) if retry_after > 0 else None


def _record_login_attempt(db, username, ip_address, success):
    if not _table_exists(db, 'auth_login_attempts'):
        return
    db.execute(
        'INSERT INTO auth_login_attempts (username,ip_address,success) VALUES (?,?,?)',
        (username, ip_address, 1 if success else 0),
    )
    db.execute("DELETE FROM auth_login_attempts WHERE attempted_at < datetime('now','-30 day')")


def _evict_token(token):
    _tokens.pop(token, None)
    _site_ids_cache.pop(token, None)


def _evict_user_tokens(uid):
    for token, user in list(_tokens.items()):
        if user.get('id') == uid:
            _evict_token(token)


def _build_session_user(db, user_row):
    user = dict(user_row)
    roles = _roles_for_user(db, user['id'], user.get('role') or 'operator')
    session_user = {
        'id': user['id'],
        'username': user.get('username') or '',
        'role': _primary_role(roles),
        'roles': roles,
        'login_name': user.get('login_name') or user.get('real_name') or '',
        'real_name': user.get('real_name') or '',
        'phone': user.get('phone') or '',
        'must_change_password': bool(user.get('must_change_password') or 0),
    }
    session_user['capabilities'] = _public_capabilities(session_user)
    return session_user


def _issue_session(db, user_row):
    """签发可撤销会话；旧测试库没有会话表时保留内存兼容。"""
    user = dict(user_row)
    token = secrets.token_urlsafe(32)
    session_user = _build_session_user(db, user)
    if _table_exists(db, 'auth_sessions'):
        issued_at = datetime.now()
        db.execute(
            """INSERT INTO auth_sessions
               (token_hash,user_id,auth_version,issued_at,expires_at,last_seen_at)
               VALUES (?,?,?,?,?,?)""",
            (
                _hash_token(token), user['id'], int(user.get('auth_version') or 1),
                issued_at.strftime('%Y-%m-%d %H:%M:%S'),
                (issued_at + timedelta(hours=AUTH_SESSION_HOURS)).strftime('%Y-%m-%d %H:%M:%S'),
                issued_at.strftime('%Y-%m-%d %H:%M:%S'),
            ),
        )
    _tokens[token] = session_user
    return token, session_user


def _authenticate_token(token):
    """以数据库会话为权威校验 token，并返回最新用户、角色和站点范围。"""
    if not token:
        return None, [], 'AUTH_REQUIRED'
    with get_db() as db:
        if not _table_exists(db, 'auth_sessions'):
            # 兼容现有测试夹具。正式库由 init_db 创建 auth_sessions，不进入此分支。
            user = _tokens.get(token)
            if not user:
                return None, [], 'AUTH_REQUIRED'
            rows = db.execute("SELECT site_id FROM user_sites WHERE user_id=?", (user['id'],)).fetchall()
            return user, [row['site_id'] for row in rows], None

        now = datetime.now()
        session = db.execute(
            "SELECT * FROM auth_sessions WHERE token_hash=?", (_hash_token(token),)
        ).fetchone()
        if not session:
            _evict_token(token)
            return None, [], 'AUTH_REQUIRED'
        if session['revoked_at']:
            _evict_token(token)
            return None, [], 'SESSION_REVOKED'
        if session['expires_at'] <= now.strftime('%Y-%m-%d %H:%M:%S'):
            db.execute(
                "UPDATE auth_sessions SET revoked_at=?, revoke_reason='expired' WHERE id=?",
                (now.strftime('%Y-%m-%d %H:%M:%S'), session['id']),
            )
            db.commit()
            _evict_token(token)
            return None, [], 'SESSION_EXPIRED'

        user_row = db.execute("SELECT * FROM users WHERE id=?", (session['user_id'],)).fetchone()
        if not user_row or user_row['status'] != 'active':
            _evict_token(token)
            return None, [], 'ACCOUNT_DISABLED'
        user_data = dict(user_row)
        if int(session['auth_version']) != int(user_data.get('auth_version') or 1):
            _evict_token(token)
            return None, [], 'SESSION_REVOKED'

        user = _build_session_user(db, user_data)
        site_rows = db.execute(
            "SELECT site_id FROM user_sites WHERE user_id=? ORDER BY site_id", (user['id'],)
        ).fetchall()
        site_ids = [row['site_id'] for row in site_rows]
        last_seen = session['last_seen_at'] or session['issued_at']
        if last_seen <= (now - timedelta(minutes=5)).strftime('%Y-%m-%d %H:%M:%S'):
            db.execute(
                "UPDATE auth_sessions SET last_seen_at=? WHERE id=?",
                (now.strftime('%Y-%m-%d %H:%M:%S'), session['id']),
            )
            db.commit()
        _tokens[token] = user
        _site_ids_cache[token] = site_ids
        return user, site_ids, None


def _revoke_session_token(token, reason='logout'):
    if not token:
        return
    with get_db() as db:
        if _table_exists(db, 'auth_sessions'):
            db.execute(
                """UPDATE auth_sessions SET revoked_at=COALESCE(revoked_at,?), revoke_reason=?
                   WHERE token_hash=?""",
                (datetime.now().strftime('%Y-%m-%d %H:%M:%S'), reason, _hash_token(token)),
            )
            db.commit()
    _evict_token(token)


def _revoke_user_sessions(db, uid, reason, increment_auth_version=False):
    if increment_auth_version:
        db.execute(
            "UPDATE users SET auth_version=COALESCE(auth_version,1)+1 WHERE id=?", (uid,)
        )
    if _table_exists(db, 'auth_sessions'):
        db.execute(
            """UPDATE auth_sessions SET revoked_at=COALESCE(revoked_at,?), revoke_reason=?
               WHERE user_id=? AND revoked_at IS NULL""",
            (datetime.now().strftime('%Y-%m-%d %H:%M:%S'), reason, uid),
        )
    _evict_user_tokens(uid)


def migrate_default_credentials():
    """Retire known bootstrap passwords without logging replacement secrets."""
    with get_db() as db:
        if not _table_exists(db, 'users'):
            return {'admin_rotated': 0, 'personnel_locked': 0}
        rows = db.execute(
            "SELECT id, username, role, password_hash FROM users WHERE status='active'"
        ).fetchall()
        default_admins = [row for row in rows
                          if row['password_hash'] == _KNOWN_DEFAULT_PASSWORD_HASHES['admin']
                          and (row['role'] == 'admin' or row['username'] == 'admin')]
        replacement = os.environ.get('DEFAULT_ADMIN_REPLACEMENT_PASSWORD', '')
        if default_admins and len(replacement) < 12:
            raise RuntimeError(
                'Unsafe default administrator credential detected. Set '
                'DEFAULT_ADMIN_REPLACEMENT_PASSWORD to a unique value of at least 12 characters, '
                'then restart. The value is never written to logs.'
            )
        admin_rotated = 0
        for row in default_admins:
            db.execute(
                'UPDATE users SET password_hash=?, must_change_password=1 WHERE id=?',
                (_hash_pw(replacement), row['id']),
            )
            _revoke_user_sessions(db, row['id'], 'default_credential_retired', increment_auth_version=True)
            admin_rotated += 1

        personnel_locked = 0
        for row in rows:
            if row['password_hash'] != _KNOWN_DEFAULT_PASSWORD_HASHES['personnel']:
                continue
            db.execute(
                'UPDATE users SET password_hash=?, must_change_password=1 WHERE id=?',
                (_hash_pw(secrets.token_urlsafe(32)), row['id']),
            )
            _revoke_user_sessions(db, row['id'], 'shared_default_credential_retired', increment_auth_version=True)
            personnel_locked += 1
        db.commit()
        return {'admin_rotated': admin_rotated, 'personnel_locked': personnel_locked}


def seed_users():
    with get_db() as db:
        cnt = db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
        if cnt > 0:
            print("[Auth] 用户已存在，跳过")
            return
        initial_password = os.environ.get('INITIAL_ADMIN_PASSWORD', '')
        if len(initial_password) < 12:
            raise RuntimeError(
                'INITIAL_ADMIN_PASSWORD must be set to a unique value of at least 12 characters '
                'when creating a new database.'
            )
        db.execute("""INSERT INTO users
            (username,password_hash,role,real_name,phone,must_change_password)
            VALUES (?,?,?,?,?,1)""",
            ('admin', _hash_pw(initial_password), 'admin', '系统管理员', ''))
        print("[Auth] 初始管理员已创建，首次登录必须修改密码")
        all_ids = [r['id'] for r in db.execute("SELECT id FROM sites").fetchall()]
        for sid in all_ids:
            db.execute("INSERT OR IGNORE INTO user_sites (user_id,site_id) VALUES (?,?)", (1, sid))
        db.commit()
        print("[Auth] 站点分配完成")


