def _filter_site_ids():
    """返回当前用户可见站点；仅管理员为 None（全站），空列表明确表示零站点。"""
    user = getattr(g, 'current_user', None)
    if _has_any_role(user, 'admin'):
        return None
    return list(getattr(g, 'user_site_ids', None) or [])


def _site_access_denied(site_id, action='访问'):
    allowed = _filter_site_ids()
    if allowed is None:
        return None
    try:
        site_id = int(site_id)
    except (TypeError, ValueError):
        return jsonify({'error': '站点参数无效'}), 400
    if site_id not in allowed:
        return jsonify({'error': f'无权限{action}非本人负责站点'}), 403
    return None


def _authorized_site_ids(raw_site_ids, action='访问'):
    """Normalize a site list and validate every site before a write starts."""
    if not isinstance(raw_site_ids, list):
        return None, (jsonify({'error': 'site_ids 必须是数组'}), 400)
    site_ids = []
    for raw_site_id in raw_site_ids:
        try:
            site_id = int(raw_site_id)
        except (TypeError, ValueError):
            return None, (jsonify({'error': '站点参数无效'}), 400)
        denied = _site_access_denied(site_id, action)
        if denied:
            return None, denied
        if site_id not in site_ids:
            site_ids.append(site_id)
    if site_ids:
        placeholders = ','.join('?' * len(site_ids))
        with get_db() as db:
            existing = {row['id'] for row in db.execute(
                f'SELECT id FROM sites WHERE id IN ({placeholders})', site_ids,
            ).fetchall()}
        missing = [site_id for site_id in site_ids if site_id not in existing]
        if missing:
            return None, (jsonify({'error': '站点不存在', 'site_ids': missing}), 404)
    return site_ids, None


def _station_operator(site_id):
    """返回站点责任运维人员姓名（user_sites 为唯一真相源）；无则空串。
    管理员永不作为 assignee；忽略任意前端传入的指派。"""
    with get_db() as db:
        row = db.execute(
            """SELECT u.real_name FROM user_sites us JOIN users u ON u.id=us.user_id
               JOIN user_roles ur ON ur.user_id=u.id AND ur.role='operator'
               WHERE us.site_id=? AND u.status='active' LIMIT 1""", (site_id,)).fetchone()
        return row['real_name'] if row else ''


# ===================== 全局 API 鉴权门禁 =====================
@app.before_request
def global_api_auth():
    """全局 API 鉴权：除白名单外，所有 /api/ 请求必须携带有效 Bearer token。
    一次性封堵所有"未加 @login_required"的匿名端点；同时注入 g.current_user / g.user_site_ids，
    供各路由及 _filter_site_ids 复用（含此前无鉴权的列表端点与待办审核）。"""
    # 非 API 路径（前端页面、静态资源）放行
    if not request.path.startswith('/api/'):
        return
    # 预检请求放行（CORS）
    if request.method == 'OPTIONS':
        return
    # 白名单：登录、健康检查
    if request.path in ('/api/auth/login', '/api/health'):
        return
    # 校验 token 并注入用户上下文
    auth = request.headers.get('Authorization', '')
    token = auth.replace('Bearer ', '').strip() if auth.startswith('Bearer ') else ''
    user, site_ids, error_code = _authenticate_token(token)
    if not user:
        return jsonify({'error': '未登录或登录已过期', 'code': error_code}), 401
    g.current_user = user
    g.user_site_ids = site_ids
    if user.get('must_change_password') and request.path not in _PASSWORD_CHANGE_PATHS:
        return jsonify({
            'error': '当前使用的是临时密码，请先设置新密码',
            'code': 'PASSWORD_CHANGE_REQUIRED',
        }), 403
    return None


@app.before_request
def gate_public_station_monitoring():
    if request.method == 'OPTIONS':
        return None
    if (request.path == '/api/station-monitoring' or
            request.path.startswith('/api/station-monitoring/')):
        if not _station_monitoring_access_allowed(getattr(g, 'current_user', None)):
            mode = _station_monitoring_access_mode()
            return jsonify({
                'error': ('站点监测管理员预览仅管理员可用' if mode == 'admin'
                          else '站点监测能力尚未启用'),
                'code': ('STATION_MONITORING_ADMIN_ONLY' if mode == 'admin'
                         else 'STATION_MONITORING_PUBLIC_DISABLED'),
            }), 403
    return None


@app.before_request
def retire_legacy_inspection_plan_writes():
    """旧 inspection-v2 仅保留历史读取/审核兼容，禁止继续生成第二条计划主链。"""
    if request.method in ('POST', 'PUT', 'PATCH', 'DELETE') and request.path.startswith('/api/inspection-v2/plans'):
        return jsonify({
            'error': '旧版巡检计划链路已停用，请使用“计划调度”创建和审批巡检任务',
            'code': 'LEGACY_PLAN_RETIRED',
        }), 410
    if request.method in ('POST', 'PUT', 'PATCH', 'DELETE') and request.path.startswith('/api/inspection-v2/schedules'):
        return jsonify({
            'error': '旧版巡检排程已停用，请使用“计划调度”',
            'code': 'LEGACY_PLAN_RETIRED',
        }), 410

# ===================== 通知系统辅助函数 =====================

def _create_notification(user_id, source_type, source_id, title, content='', db=None,
                         payload_json=''):
    """创建通知（内部函数）。db 可传入以复用现有连接（避免嵌套写锁）"""
    own = db is None
    if own:
        db = get_db()
    try:
        if payload_json and _table_has_column(db, 'notifications', 'payload_json'):
            cursor = db.execute("""INSERT INTO notifications
                (user_id,source_type,source_id,title,content,payload_json)
                VALUES (?,?,?,?,?,?)""",
                (user_id, source_type, source_id, title, content, payload_json))
        else:
            cursor = db.execute(
                "INSERT INTO notifications (user_id, source_type, source_id, title, content) VALUES (?,?,?,?,?)",
                (user_id, source_type, source_id, title, content)
            )
        if own:
            db.commit()
        return cursor.lastrowid
    except Exception:
        if own:
            try: db.rollback()
            except Exception: pass
        raise


def _ensure_notification_unread_dedupe_invariant(db):
    """Keep one current notification per user/dedupe key without deleting history."""
    if not (_table_exists(db, 'notifications')
            and _table_has_column(db, 'notifications', 'is_read')
            and _table_has_column(db, 'notifications', 'dedupe_key')):
        return False
    db.execute("""UPDATE notifications SET is_read=1
        WHERE is_read=0 AND COALESCE(dedupe_key,'')!=''
          AND id NOT IN (
              SELECT MAX(id) FROM notifications
              WHERE is_read=0 AND COALESCE(dedupe_key,'')!=''
              GROUP BY user_id,dedupe_key
          )""")
    db.execute("""CREATE UNIQUE INDEX IF NOT EXISTS uq_notifications_unread_dedupe
        ON notifications(user_id,dedupe_key)
        WHERE is_read=0 AND COALESCE(dedupe_key,'')!=''""")
    return True


def _upsert_unread_notification(db, user_id, source_type, source_id, title, content,
                                dedupe_key='', payload_json=''):
    """Create or refresh the single unread notification represented by dedupe_key."""
    supports_dedupe = (dedupe_key
                       and _table_has_column(db, 'notifications', 'is_read')
                       and _table_has_column(db, 'notifications', 'dedupe_key')
                       and _table_has_column(db, 'notifications', 'payload_json'))
    if not supports_dedupe:
        _create_notification(user_id, source_type, source_id, title, content, db=db)
        return None
    db.execute("""INSERT OR IGNORE INTO notifications
        (user_id,source_type,source_id,title,content,dedupe_key,payload_json)
        VALUES (?,?,?,?,?,?,?)""",
        (user_id, source_type, source_id, title, content, dedupe_key, payload_json))
    existing = db.execute("""SELECT id FROM notifications
        WHERE user_id=? AND dedupe_key=? AND is_read=0 ORDER BY id DESC LIMIT 1""",
        (user_id, dedupe_key)).fetchone()
    if existing:
        db.execute("""UPDATE notifications
            SET source_type=?,source_id=?,title=?,content=?,payload_json=? WHERE id=?""",
            (source_type, source_id, title, content, payload_json, existing['id']))
        return existing['id']
    return None


def _notify_workorder_reviewers(db, site_id, order_no, title):
    """Notify admins and reviewers assigned to the work-order site."""
    recipients = []
    try:
        rows = db.execute("""SELECT DISTINCT u.id,
                    CASE WHEN u.role='admin' OR EXISTS (
                        SELECT 1 FROM user_roles ar WHERE ar.user_id=u.id AND ar.role='admin'
                    ) THEN 1 ELSE 0 END AS is_admin
                FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
                WHERE u.status='active'
                  AND (u.role IN ('admin','reviewer','inspector')
                       OR ur.role IN ('admin','reviewer'))""").fetchall()
        for row in rows:
            if not row['is_admin'] and not db.execute(
                'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?', (row['id'], site_id)
            ).fetchone():
                continue
            recipients.append(row['id'])
            existing = db.execute("""SELECT 1 FROM notifications
                WHERE user_id=? AND source_type='workorder_review' AND source_id=? AND is_read=0""",
                (row['id'], order_no)).fetchone()
            if not existing:
                _create_notification(
                    row['id'], 'workorder_review', order_no, '工单待核验',
                    f'{order_no} · {title or "现场处置已提交"}', db=db,
                )
    except sqlite3.OperationalError as exc:
        print(f'[Workorder review notify] 跳过：{exc}')
    return sorted(set(recipients))


def _retire_workorder_review_notifications(db, order_no):
    """Archive every current reviewer reminder for a completed review decision."""
    if not _table_has_column(db, 'notifications', 'is_read'):
        return 0
    result = db.execute("""UPDATE notifications SET is_read=1
        WHERE source_type='workorder_review' AND source_id=? AND is_read=0""",
        (order_no,))
    return result.rowcount


def _notify_attachment_reviewers(db, site_id, attachment_id, title):
    """Retire legacy photo-only reminders; inspection items own current review work."""
    try:
        if _table_has_column(db, 'notifications', 'is_read'):
            db.execute("""UPDATE notifications SET is_read=1
                WHERE source_type IN ('attachment_review','attachment_review_batch')
                  AND is_read=0""")
    except sqlite3.OperationalError as exc:
        print(f'[Attachment review notify] 跳过：{exc}')


def _coalesce_pending_attachment_notifications(db):
    """Archive obsolete photo-only reminders; current work uses inspection batches."""
    try:
        db.execute("""UPDATE notifications SET is_read=1
            WHERE source_type IN ('attachment_review','attachment_review_batch') AND is_read=0""")
    except sqlite3.OperationalError as exc:
        print(f'[Attachment review coalesce] 跳过：{exc}')


