@app.route('/api/sites/<int:site_id>')
def get_site(site_id):
    allowed = _filter_site_ids()
    if allowed is not None and site_id not in allowed:
        return jsonify({'error': '无权限访问该站点'}), 403
    with get_db() as db:
        site = db.execute("SELECT * FROM sites WHERE id=?", (site_id,)).fetchone()
        if not site:
            return jsonify({'error': 'not found'}), 404
        devices = db.execute("SELECT * FROM device_shadows WHERE site_id=?", (site_id,)).fetchall()
        alerts_count = db.execute("SELECT COUNT(*) as c FROM alerts WHERE site_id=? AND status='pending'", (site_id,)).fetchone()['c']
        orders_count = db.execute("SELECT COUNT(*) as c FROM work_orders WHERE site_id=? AND status NOT IN ('closed')", (site_id,)).fetchone()['c']
        site_dict = dict(site)
        # Calculate status from devices, not from sites.status
        offline_devices = [d for d in devices if d['status'] == 'offline']
        site_dict['status'] = 'offline' if len(offline_devices) > 0 else 'online'
        site_dict['devices'] = [dict(d) for d in devices]
        site_dict['active_alerts'] = alerts_count
        site_dict['open_orders'] = orders_count
        # 水库额外信息
        reservoir_extra = {
            1: {'capacity': 1280, 'flood_level': 49.5, 'critical_level': 51.5, 'normal_level': 48.0},
            2: {'capacity': 860, 'flood_level': 48.0, 'critical_level': 50.0, 'normal_level': 47.0},
        }
        if site['type'] == 'reservoir':
            extra = reservoir_extra.get(site['id'], {})
            site_dict['capacity'] = extra.get('capacity')
            site_dict['flood_level'] = extra.get('flood_level')
            site_dict['critical_level'] = extra.get('critical_level')
            site_dict['normal_level'] = extra.get('normal_level')
        return jsonify(site_dict)

@app.route('/api/sites/archive/upload-calibration', methods=['POST'])
def upload_site_calibration():
    """上传站点校准附件（照片/PDF/文档），统一归口 operation_attachments（source_type='calibration'）。"""
    file = request.files.get('file')
    site_id = request.form.get('site_id', type=int)
    allowed = _filter_site_ids()
    if allowed is not None and (not site_id or site_id not in allowed):
        return jsonify({'error': '无权限操作非本人站点档案'}), 403
    if not file or not site_id:
        return jsonify({'error': '请选择文件并指定站点'}), 400
    ext = os.path.splitext(file.filename or '.jpg')[1].lower() or '.jpg'
    img_exts = {'.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp'}
    document_exts = {'.pdf', '.doc', '.docx', '.xls', '.xlsx'}
    if ext not in img_exts | document_exts:
        return jsonify({'error': '仅支持图片、PDF、Word或Excel附件'}), 400
    file_data = file.read()
    if len(file_data) > 20 * 1024 * 1024:
        return jsonify({'error': '文件大小超过20MB限制'}), 400
    import json as _json
    cal_type = request.form.get('cal_type', '校准照片')
    result = request.form.get('result', '合格')
    valid_until = request.form.get('valid_until', '')
    fname = str(uuid.uuid4())[:12] + ext
    now = datetime.now()
    subdir = now.strftime('calibration/%Y/%m')
    stored_dir = os.path.join(UPLOAD_DIR, subdir)
    os.makedirs(stored_dir, exist_ok=True)
    stored_path = os.path.join(stored_dir, fname)
    url = f'/uploads/{subdir}/{fname}'
    extra = _json.dumps({'cal_type': cal_type, 'result': result, 'valid_until': valid_until}, ensure_ascii=False)
    # 智能识别：按文件名/说明关键词匹配照片类型配置（水印/场景自动归类，接入审核链）
    _match = match_photo_requirement('', site_id, file.filename or '', f'{cal_type}（{result}）')
    _req_id = _match['requirement_id'] if _match else None
    _rec_cat = _match['recognized_category'] if _match else ''
    _match_status = _match['match_status'] if _match else 'manual'
    _match_conf = _match['match_confidence'] if _match else None
    _review_required = _match['review_required'] if _match else 0
    with get_db() as db:
        cur = db.execute("""INSERT INTO operation_attachments
            (filename, stored_path, file_type, mime_type, file_size, description,
             source_type, source_id, site_id, category, extra_json, created_at,
             watermark_text, recognized_category, match_status, match_confidence,
             review_required, requirement_id)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (file.filename or fname, url, 'file', ext, len(file_data),
             f'{cal_type}（{result}）', 'calibration', site_id, site_id, '校准报告', extra,
             now.strftime('%Y-%m-%d %H:%M:%S'),
             '', _rec_cat, _match_status, _match_conf,
             _review_required, _req_id))
        new_id = cur.lastrowid
        db.commit()
    return jsonify({'id': new_id, 'url': url, 'success': True})

@app.route('/api/sites/<int:site_id>/archive')
@login_required
def get_site_archive(site_id):
    """站点档案：聚合基本信息、设备、故障记录、巡检记录等"""
    denied = _site_access_denied(site_id)
    if denied:
        return denied
    try:
        with get_db() as db:
            site = db.execute("SELECT * FROM sites WHERE id=?", (site_id,)).fetchone()
            if not site:
                return jsonify({'error': '站点不存在'}), 404

            site_dict = dict(site)
            site_type = site_dict.get('type', '')

            if _station_monitoring_access_allowed(g.current_user):
                # 档案页不得用前端模拟曲线冒充采集结果。真实时序由数据接入后再展示。
                sensor_rows = db.execute(
                    """SELECT metric, value, recorded_at FROM sensor_data
                       WHERE site_id=? AND recorded_at >= datetime('now', '-24 hours')
                       ORDER BY recorded_at ASC""",
                    (site_id,),
                ).fetchall()
                trend_data = {}
                for row in sensor_rows:
                    item = dict(row)
                    trend_data.setdefault(item['metric'], []).append({
                        'hour': (item['recorded_at'] or '')[11:16] or item['recorded_at'],
                        'value': item['value'],
                    })
                site_dict['has_sensor_data'] = bool(sensor_rows)
                site_dict['trend_data'] = trend_data
    
            # 设备列表（从 device_shadows 取，与 device 表同步）
            devices = db.execute("SELECT * FROM device_shadows WHERE site_id=?", (site_id,)).fetchall()
            site_dict['equipment'] = [dict(d) for d in devices]
    
            # 故障记录 → 从 alerts 表取真实告警（时序上最近50条）
            fault_alerts = db.execute(
                "SELECT id, message, level, status, created_at FROM alerts WHERE site_id=? ORDER BY created_at DESC LIMIT 50",
                (site_id,)
            ).fetchall()
            fault_records = [
                {
                    'id': f['id'],
                    'date': f['created_at'],
                    'title': f['message'][:60],
                    'event': f['level'],
                    'description': f['message'],
                    'detail': f['message'],
                    'severity': f['level'],
                    'operator': '系统',
                }
                for f in [dict(r) for r in fault_alerts]
            ]
            site_dict['fault_records'] = fault_records
    
            # 设备更换/维护记录 → 从 device_shadows 的 install_date 推断 + 告警转换
            dev_replacements = db.execute(
                "SELECT id, device_name, device_type, install_date, status FROM device_shadows WHERE site_id=? ORDER BY install_date DESC",
                (site_id,)
            ).fetchall()
            replacement_records = [
                {
                    'id': r['id'],
                    'date': r['install_date'] or '—',
                    'old_equipment': '—',
                    'new_equipment': r['device_name'],
                    'reason': f'初始安装/{r.get("status","运行")}',
                    'operator': '—',
                }
                for r in [dict(r) for r in dev_replacements]
            ]
            site_dict['replacement_records'] = replacement_records
    
            # 巡检记录 → 从 insp_plans + insp_plan_items 取
            insp_plans = db.execute(
                "SELECT DISTINCT p.id, p.plan_name, p.period, p.status, p.created_at, p.generate_date "
                "FROM insp_plans p "
                "JOIN insp_plan_items i ON i.plan_id = p.id "
                "WHERE i.site_id = ? "
                "ORDER BY p.created_at DESC LIMIT 50",
                (site_id,)
            ).fetchall()
            site_dict['inspection_records'] = [
                {
                    'id': p['id'],
                    'date': p.get('generate_date') or p.get('created_at', ''),
                    'type': {'weekly':'每周巡检','monthly':'每月巡检'}.get(p.get('period',''), p.get('period','—')),
                    'result': {'draft':'草稿','active':'执行中','completed':'已完成'}.get(p.get('status',''), p.get('status','—')),
                    'issues': p.get('plan_name', '') or '—',
                    'inspector': '—',
                }
                for p in [dict(r) for r in insp_plans]
            ]
    
            # 校准报告只来自真实上传附件；缺失时保持空集合，不能生成合规结论。
            import json as _json
            real_cals = db.execute(
                "SELECT id, filename, stored_path, extra_json, created_at FROM operation_attachments "
                "WHERE source_type='calibration' AND source_id=? AND is_deleted=0 ORDER BY created_at DESC",
                (site_id,)
            ).fetchall()
            site_dict['calibration_reports'] = [
                    {
                        'id': c['id'],
                        'date': (c['created_at'] or '')[:10],
                        'type': (_json.loads(c['extra_json']).get('cal_type', '校准照片') if c['extra_json'] else '校准照片'),
                        'result': (_json.loads(c['extra_json']).get('result', '') if c['extra_json'] else ''),
                        'valid_until': (_json.loads(c['extra_json']).get('valid_until', '') if c['extra_json'] else ''),
                        'file': {'url': c['stored_path'], 'name': c['filename'] or (c['stored_path'].split('/')[-1])},
                    }
                    for c in [dict(r) for r in real_cals]
                ]
    
            # 试剂使用及更换记录
            reagent_records = db.execute(
                "SELECT * FROM reagent_records WHERE site_id=? ORDER BY created_at DESC",
                (site_id,)
            ).fetchall()
            site_dict['reagent_records'] = [
                {
                    'id': r['id'],
                    'reagent_name': r['reagent_name'],
                    'reagent_type': r['reagent_type'] or '—',
                    'usage_date': r['usage_date'] or '—',
                    'replacement_date': r['replacement_date'] or '—',
                    'operator': _actor_display_name(
                        db, r['operator'], r['operator_id'] if 'operator_id' in r.keys() else None, '—'
                    ),
                    'notes': r['notes'] or '—',
                }
                for r in reagent_records
            ]
    
            # 历史记录
            history = []
            for f in site_dict['fault_records']:
                history.append({'date': f['date'], 'event': f['title'], 'operator': f['operator']})
            for r in site_dict['replacement_records']:
                history.append({'date': r['date'], 'event': "设备更换: " + r['old_equipment'], 'operator': r['operator']})
            history.sort(key=lambda x: x['date'] or '', reverse=True)
            site_dict['history_records'] = history[:20]
    
            return jsonify(site_dict)
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/sites/<int:site_id>/archive/export')
@login_required
def export_site_archive(site_id):
    """Export a readable multi-sheet Chinese site archive, including empty datasets."""
    denied = _site_access_denied(site_id)
    if denied:
        return denied
    if not _HAS_OPENPYXL:
        return jsonify({'error': '缺少 openpyxl，无法导出站点档案'}), 500
    with get_db() as db:
        site = db.execute('SELECT * FROM sites WHERE id=?', (site_id,)).fetchone()
        if not site:
            return jsonify({'error': '站点不存在'}), 404
        devices = db.execute('SELECT * FROM device_shadows WHERE site_id=? ORDER BY id', (site_id,)).fetchall()
        inspection_summary = db.execute("""SELECT COUNT(*) AS total,
                SUM(CASE WHEN result IS NOT NULL THEN 1 ELSE 0 END) AS completed,
                SUM(CASE WHEN result='abnormal' THEN 1 ELSE 0 END) AS abnormal
            FROM insp_plan_items WHERE site_id=?""", (site_id,)).fetchone()
        workorder_summary = db.execute("""SELECT COUNT(*) AS total,
                SUM(CASE WHEN status='closed' THEN 1 ELSE 0 END) AS closed,
                SUM(CASE WHEN status!='closed' THEN 1 ELSE 0 END) AS open
            FROM work_orders WHERE site_id=?""", (site_id,)).fetchone()
        alerts = db.execute("""SELECT level, status, message, created_at FROM alerts
            WHERE site_id=? AND status='pending' ORDER BY created_at DESC""", (site_id,)).fetchall()
    station_type_labels = {'water_quality': '水质监测站'}
    station_status_labels = {
        'normal': '正常', 'online': '在线', 'offline': '离线', 'maintenance': '维护中',
        'retired': '已停用', 'deleted': '已删除',
    }
    device_type_labels = {
        'multi_param_analyzer': '多参数水质分析仪', 'ph_meter': 'pH计',
        'do_sensor': '溶解氧传感器', 'turbidity_meter': '浊度仪',
        'ammonia_analyzer': '氨氮分析仪', 'codmn_analyzer': '高锰酸盐分析仪',
        'tp_analyzer': '总磷分析仪', 'tn_analyzer': '总氮分析仪',
        'conductivity_meter': '电导率仪', 'thermometer': '温度计',
        'submersible_pump': '潜水泵', 'sample_float': '采样浮筒',
        'dtu': '数据采集传输终端', 'fire_extinguisher': '灭火器',
        'lighting': '照明设备', 'rainfall_gauge': '翻斗雨量计',
        'water_level_meter': '水位计', 'hydro_collector': '数据采集器',
        'pressure_water_level': '压力式水位计', 'current_meter': '流速仪',
        'radar_water_level': '雷达水位计', 'station_facility': '站房设施',
        'cod_analyzer': 'COD分析仪',
    }
    device_status_labels = {
        'normal': '正常', 'online': '在线', 'offline': '离线', 'fault': '故障',
        'maintenance': '维护中', 'retired': '已退役', 'deleted': '已删除',
    }

    def archive_label(value, labels):
        raw = str(value or '').strip()
        return labels.get(raw, f'{raw}（需维护）') if raw else ''

    workbook = Workbook(); overview = workbook.active; overview.title = '站点概况'
    overview.append(['字段', '内容'])
    labels = [('站点编码', 'code'), ('站点名称', 'name'), ('站点类型', 'type'),
              ('状态', 'status'), ('区县', 'district'), ('河流', 'river'),
              ('负责人', 'manager'), ('联系电话', 'phone'), ('纬度', 'gps_lat'), ('经度', 'gps_lng')]
    for label, key in labels:
        value = site[key] if key in site.keys() else ''
        if key == 'type': value = archive_label(value, station_type_labels)
        if key == 'status': value = archive_label(value, station_status_labels)
        overview.append([label, value])
    device_sheet = workbook.create_sheet('设备')
    device_sheet.append(['设备编码', '设备名称', '设备类型', '型号', '厂商', '状态', '最后数据时间'])
    for row in devices:
        device_sheet.append([
            str(row['device_code'] or ''), row['device_name'] or '',
            archive_label(row['device_type'], device_type_labels), row['device_model'] or '',
            row['manufacturer'] or '', archive_label(row['status'], device_status_labels),
            row['last_data_time'] or '',
        ])
    summary = workbook.create_sheet('巡检工单摘要')
    summary.append(['业务', '总数', '已完成/闭环', '异常/未闭环'])
    summary.append(['巡检检查项', inspection_summary['total'] or 0,
                    inspection_summary['completed'] or 0, inspection_summary['abnormal'] or 0])
    summary.append(['工单', workorder_summary['total'] or 0,
                    workorder_summary['closed'] or 0, workorder_summary['open'] or 0])
    risk = workbook.create_sheet('风险信息')
    risk.append(['等级', '状态', '风险说明', '发生时间'])
    for row in alerts: risk.append([row['level'], row['status'], row['message'], row['created_at']])
    if not alerts: risk.append(['', '', '当前无待处理告警', ''])
    for sheet in workbook.worksheets:
        for cell in sheet[1]: _set_header_style(cell)
        sheet.freeze_panes = 'A2'
        for column in sheet.columns:
            sheet.column_dimensions[get_column_letter(column[0].column)].width = min(
                48, max(12, max(len(str(cell.value or '')) for cell in column) + 3))
        for row in sheet.iter_rows():
            for cell in row:
                cell.alignment = Alignment(
                    horizontal=cell.alignment.horizontal,
                    vertical='center', wrap_text=True)
    overview.column_dimensions['A'].width = 18
    overview.column_dimensions['B'].width = 32
    overview['B2'].number_format = '@'
    for column, width in {'A': 18, 'B': 28, 'C': 24, 'D': 18, 'E': 20, 'F': 14, 'G': 22}.items():
        device_sheet.column_dimensions[column].width = width
    for row_index in range(2, device_sheet.max_row + 1):
        device_sheet.cell(row_index, 1).number_format = '@'
    output = BytesIO(); workbook.save(output); output.seek(0)
    safe_name = re.sub(r'[\\/:*?"<>|]+', '_', site['name'] or site['code'] or str(site_id))
    return send_file(output, as_attachment=True, download_name=f'站点档案_{safe_name}.xlsx',
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')


@app.route('/api/sites/<int:site_id>/profile', methods=['PUT'])
@login_required
def update_site_profile(site_id):
    """更新站点基础档案。仅管理员可维护，不伪造缺失的现场信息。"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    allowed_fields = {
        'district', 'address', 'basin', 'gps_lat', 'gps_lng',
        'operation_frequency', 'elevation', 'build_date',
    }
    updates = {key: data[key] for key in allowed_fields if key in data}
    if not updates:
        return jsonify({'error': '没有可保存的档案信息'}), 400
    for key in ('gps_lat', 'gps_lng', 'elevation'):
        if key in updates and updates[key] not in ('', None):
            try:
                updates[key] = float(updates[key])
            except (TypeError, ValueError):
                return jsonify({'error': f'{key} 必须为数字'}), 400
    with get_db() as db:
        exists = db.execute('SELECT id FROM sites WHERE id=?', (site_id,)).fetchone()
        if not exists:
            return jsonify({'error': '站点不存在'}), 404
        fields = ', '.join(f'{key}=?' for key in updates)
        db.execute(f'UPDATE sites SET {fields} WHERE id=?', (*updates.values(), site_id))
        db.commit()
    return jsonify({'success': True, 'message': '站点档案已保存'})


def _generate_mock_fault_records(site_type, site_name):
    """生成模拟故障记录"""
    from datetime import datetime, timedelta
    now = datetime.now()
    templates = {
        'water_quality': [
            {'title': 'pH计读数异常', 'severity': 'high', 'desc': 'pH计读数持续偏低，经检查为电极老化，已更换新电极'},
            {'title': '氨氮分析仪试剂不足', 'severity': 'medium', 'desc': '氨氮分析仪试剂余量低于20%，已补充试剂并重新校准'},
            {'title': '采水泵运行异常', 'severity': 'medium', 'desc': '采水泵噪音增大，流量下降，已清理过滤器并润滑轴承'},
            {'title': '通信模块信号弱', 'severity': 'low', 'desc': '4G通信模块信号强度低于阈值，已调整天线位置'},
        ],
    }
    records = templates.get(site_type, templates['water_quality'])
    result = []
    for i, t in enumerate(records):
        days_ago = (i + 1) * 15 + i * 7
        dt = now - timedelta(days=days_ago)
        result.append({
            'id': f'mock_fault_{i+1}',
            'date': dt.strftime('%Y-%m-%d'),
            'title': t['title'],
            'event': t['title'],
            'description': t['desc'],
            'detail': t['desc'],
            'severity': t['severity'],
            'operator': '张工' if i % 2 == 0 else '李工',
        })
    return result


def _generate_mock_replacement_records(site_type, site_name):
    """生成模拟设备更换记录"""
    from datetime import datetime, timedelta
    now = datetime.now()
    templates = {
        'water_quality': [
            {'old': 'PHG-2088 pH计（2020款）', 'new': 'PHG-2099 pH计（2024款）', 'reason': '电极老化，测量精度下降'},
            {'old': 'NH3N-2000 氨氮分析仪', 'new': 'NH3N-3000 氨氮分析仪', 'reason': '设备升级，提高测量灵敏度'},
        ],
    }
    records = templates.get(site_type, templates['water_quality'])
    result = []
    for i, t in enumerate(records):
        days_ago = (i + 1) * 120 + i * 60
        dt = now - timedelta(days=days_ago)
        result.append({
            'id': f'mock_replace_{i+1}',
            'date': dt.strftime('%Y-%m-%d'),
            'old_equipment': t['old'],
            'new_equipment': t['new'],
            'reason': t['reason'],
            'operator': '王工' if i % 2 == 0 else '赵工',
        })
    return result


