@app.route('/api/alerts/<int:alert_id>/acknowledge', methods=['POST'])
def acknowledge_alert(alert_id):
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    with get_db() as db:
        alert = db.execute("SELECT id,status FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['status'] != 'pending':
            return jsonify({'error': '仅待处理告警可以受理，请刷新后重试'}), 409
        db.execute("UPDATE alerts SET status='acknowledged' WHERE id=? AND status='pending'", (alert_id,))
        # 记录时间线
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'acknowledged', operator, '确认告警'))
        db.commit()
        return jsonify({'success': True})

@app.route('/api/alerts/<int:alert_id>/resolve', methods=['POST'])
def resolve_alert(alert_id):
    """办结告警，支持办结原因（reason）"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    reason_code = (data.get('reason') or '').strip()
    reason_labels = {
        'normal_deviation': '正常偏差',
        'manual_review': '人工复核',
        'false_alarm': '误报',
        'equipment_maintenance': '设备维护',
        'environmental_factor': '环境因素',
        'other': '其他',
    }
    if reason_code not in reason_labels:
        return jsonify({'error': '请选择有效的办结原因'}), 400
    remark = (data.get('remark') or '').strip()
    conclusion = (data.get('conclusion') or '').strip()
    full_remark = reason_labels[reason_code]
    if conclusion:
        full_remark += f'；现场结论：{conclusion}'
    if remark:
        full_remark += f'；备注：{remark}'
    with get_db() as db:
        alert = db.execute(
            "SELECT id,status,related_order_no,review_id FROM alerts WHERE id=?", (alert_id,)
        ).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['status'] not in ('pending', 'acknowledged'):
            return jsonify({'error': '该告警已办结，请刷新后查看'}), 409
        if alert['related_order_no']:
            order = db.execute(
                "SELECT status FROM work_orders WHERE order_no=?", (alert['related_order_no'],)
            ).fetchone()
            if order and order['status'] not in ('closed', 'resolved'):
                return jsonify({'error': '该告警已转工单，请先完成关联工单后再闭环'}), 409
        db.execute(
            "UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime'), resolve_reason=? WHERE id=? AND status IN ('pending','acknowledged')",
            (full_remark, alert_id),
        )
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'resolved', operator, full_remark))
        # 闭环：直接办结告警时，一并归档关联数据审核项
        if alert['review_id']:
            _archive_linked_review(db, None, None, full_remark, review_id=alert['review_id'])
        db.commit()
        summary = db.execute("SELECT COUNT(*) FROM alerts WHERE status='pending'").fetchone()[0]
        return jsonify({'success': True, 'summary': {'alerts_pending': summary}})

@app.route('/api/alerts/<int:alert_id>/ack-resolve', methods=['POST'])
def ack_resolve_alert(alert_id):
    """一键确认并办结（跳过已确认状态，直接pending→resolved）"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    remark = (data.get('remark') or '').strip()
    if not remark:
        return jsonify({'error': '请填写办结说明'}), 400
    with get_db() as db:
        alert = db.execute("SELECT id,status,related_order_no FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['status'] != 'pending' or alert['related_order_no']:
            return jsonify({'error': '仅未转工单的待处理告警可以一键办结'}), 409
        db.execute("UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime'), resolve_reason=? WHERE id=? AND status='pending'", (remark, alert_id))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'acknowledged', operator, '确认告警'))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'resolved', operator, remark))
        db.commit()
        return jsonify({'success': True})

@app.route('/api/alerts/<int:alert_id>/urge', methods=['POST'])
def urge_alert(alert_id):
    """告警督办，支持时限、督办人、督办意见"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    remark = (data.get('opinion') or data.get('remark') or '').strip()
    deadline = (data.get('deadline') or '').strip()
    supervisor = (data.get('supervisor') or '').strip()
    cooperator = (data.get('cooperator') or '').strip()
    if not remark:
        return jsonify({'error': '请填写督办意见'}), 400
    # 将额外信息拼入remark
    extra = []
    if supervisor: extra.append('督办人:'+supervisor)
    if deadline: extra.append('限办:'+deadline)
    if cooperator: extra.append('协办:'+cooperator)
    full_remark = remark + (' | ' + '; '.join(extra) if extra else '')
    # 更新数据库中的response_deadline字段
    with get_db() as db:
        alert = db.execute("SELECT id,status FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['status'] == 'resolved':
            return jsonify({'error': '已办结告警不能督办'}), 409
        db.execute("UPDATE alerts SET urge_count=COALESCE(urge_count,0)+1, last_urged_at=datetime('now','localtime') WHERE id=?", (alert_id,))
        if deadline:
            db.execute("UPDATE alerts SET response_deadline=? WHERE id=?", (deadline, alert_id))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'urged', supervisor or operator, full_remark))
        db.commit()
        return jsonify({'success': True})

@app.route('/api/alerts/<int:alert_id>/undo-acknowledge', methods=['POST'])
def undo_acknowledge_alert(alert_id):
    """撤销告警确认，将状态改回pending"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    remark = (data.get('remark') or '').strip()
    if not remark:
        return jsonify({'error': '请填写撤销原因'}), 400
    with get_db() as db:
        alert = db.execute("SELECT id,status FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['status'] != 'acknowledged':
            return jsonify({'error': '仅处理中的告警可以撤销受理'}), 409
        db.execute("UPDATE alerts SET status='pending', resolved_at=NULL WHERE id=? AND status='acknowledged'", (alert_id,))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'undo_acknowledge', operator, remark))
        db.commit()
        return jsonify({'success': True})

# === 告警流转（A级自动转 / B级人工复核）===

@app.route('/api/alerts/pending-review', methods=['GET'])
@login_required
def get_pending_review_alerts():
    """获取所有待复核的B级告警及其已等待时间"""
    site_ids = _filter_site_ids()
    with get_db() as db:
        q = """
            SELECT a.id, a.site_id, a.metric, a.level, a.message, a.created_at,
                   s.name as site_name, s.code as site_code,
                   ROUND((julianday('now','localtime') - julianday(a.created_at)) * 24 * 60) as wait_minutes
            FROM alerts a LEFT JOIN sites s ON a.site_id=s.id
            WHERE a.flow_type='manual' AND a.flow_status='pending_review'
        """
        params = []
        if site_ids is not None:
            ph = ','.join('?' * len(site_ids))
            q += f" AND a.site_id IN ({ph})"
            params.extend(site_ids)
        q += " ORDER BY a.created_at ASC"
        rows = db.execute(q, params).fetchall()
        return jsonify([dict(r) for r in rows])

@app.route('/api/alerts/<int:alert_id>/confirm-convert', methods=['POST'])
@login_required
def confirm_convert_alert(alert_id):
    """B级告警人工复核确认转工单或关闭"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    action = data.get('action', 'convert')  # 'convert' 或 'dismiss'
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    with get_db() as db:
        alert = db.execute("SELECT * FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': '告警不存在'}), 404
        if alert['flow_status'] in ('converted', 'dismissed'):
            return jsonify({'error': '该告警已处理，无法重复操作'}), 400
        if action == 'dismiss':
            remark_txt = data.get('remark', '').strip() or '人工复核后关闭'
            db.execute("UPDATE alerts SET flow_status='dismissed', status='resolved', resolved_at=datetime('now','localtime') WHERE id=?", (alert_id,))
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                       ('alert', alert_id, 'dismissed', operator, remark_txt))
            db.commit()
            summary = db.execute("SELECT COUNT(*) FROM alerts WHERE status='pending'").fetchone()[0]
            return jsonify({'success': True, 'action': 'dismissed', 'summary': {'alerts_pending': summary}})
        else:
            # 转工单
            now = datetime.now()
            order_no = f"WO-{now.strftime('%Y%m%d')}-{random.randint(100,999)}"
            order_level = 'critical' if alert['level'] == 'red' else ('urgent' if alert['level'] == 'orange' else 'normal')
            sla_hours = {'normal': 72, 'urgent': 24, 'critical': 2}.get(order_level, 72)
            sla_deadline = (now + timedelta(hours=sla_hours)).strftime('%Y-%m-%d %H:%M')
            site = db.execute("SELECT manager FROM sites WHERE id=?", (alert['site_id'],)).fetchone()
            assignee = _station_operator(alert['site_id']) if site else ''
            db.execute("""
                INSERT INTO work_orders (order_no,site_id,source,event_type,level,title,description,assignee,status,sla_deadline)
                VALUES (?,?,?,?,?,?,?,?,?,?)
            """, (
                order_no, alert['site_id'], 'alert_convert', '告警复核转工单',
                order_level, _generated_workorder_title(
                    'alert_convert', alert['message'], '告警复核转工单'), alert['message'],
                assignee, 'in_progress', sla_deadline
            ))
            db.execute("UPDATE alerts SET flow_status='converted', related_order_no=?, status='pending' WHERE id=?",
                       (order_no, alert_id))
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                       ('alert', alert_id, 'manual_converted', operator, f'人工复核转工单 {order_no}'))
            # 自动流转时间线
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                       ('order', 0, 'accepted', '系统', f'工单{order_no} → 已受理（自动）'))
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                       ('order', 0, 'dispatched', assignee or '系统', f'工单{order_no} → 已派发（自动）'))
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                       ('order', 0, 'in_progress', '系统', f'工单{order_no} → 处置中（自动）'))
            db.commit()
            summary = db.execute("SELECT COUNT(*) FROM alerts WHERE status='pending'").fetchone()[0]
            return jsonify({'success': True, 'order_no': order_no, 'summary': {'alerts_pending': summary}})

@app.route('/api/alerts/<int:alert_id>/convert-order', methods=['POST'])
def convert_alert_to_order(alert_id):
    """告警转工单"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    with get_db() as db:
        alert = db.execute("SELECT * FROM alerts WHERE id=?", (alert_id,)).fetchone()
        if not alert:
            return jsonify({'error': 'not found'}), 404
        if alert['flow_status'] in ('converted', 'dismissed'):
            return jsonify({'error': '该告警已处理，无法重复操作'}), 400
        now = datetime.now()
        order_no = f"WO-{now.strftime('%Y%m%d')}-{random.randint(100,999)}"
        level = data.get('level', alert['level'])
        if level == 'red':
            order_level = 'critical'
        elif level == 'orange':
            order_level = 'urgent'
        else:
            order_level = 'normal'
        sla_hours = {'normal': 72, 'urgent': 24, 'critical': 2}.get(order_level, 72)
        sla_deadline = (now + timedelta(hours=sla_hours)).strftime('%Y-%m-%d %H:%M')
        site = db.execute("SELECT manager FROM sites WHERE id=?", (alert['site_id'],)).fetchone()
        assignee = _station_operator(alert['site_id']) if site else ''
        db.execute("""
            INSERT INTO work_orders (order_no,site_id,source,event_type,level,title,description,assignee,status,sla_deadline)
            VALUES (?,?,?,?,?,?,?,?,?,?)
        """, (
            order_no, alert['site_id'], 'auto', '告警转工单',
            order_level, _generated_workorder_title('auto', alert['message'], '告警转工单'), alert['message'],
            assignee, 'in_progress', sla_deadline
        ))
        # 更新告警关联工单号
        db.execute("UPDATE alerts SET related_order_no=?, flow_status='converted', status='pending' WHERE id=?", (order_no, alert_id))
        # 记录时间线
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('alert', alert_id, 'converted', operator, f'转工单 {order_no}'))
        # 自动流转时间线
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'accepted', '系统', f'工单{order_no} → 已受理（自动）'))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'dispatched', assignee or '系统', f'工单{order_no} → 已派发（自动）'))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'in_progress', '系统', f'工单{order_no} → 处置中（自动）'))
        db.commit()
        summary = db.execute("SELECT COUNT(*) FROM alerts WHERE status='pending'").fetchone()[0]
        return jsonify({'success': True, 'order_no': order_no, 'summary': {'alerts_pending': summary}})

@app.route('/api/alerts/batch', methods=['POST'])
def batch_alert_operations():
    """告警批量操作: acknowledge/resolve/urge/convert"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    raw_ids = data.get('ids', [])
    action = (data.get('action') or '').strip()
    if not isinstance(raw_ids, list) or not raw_ids:
        return jsonify({'error': '请选择需要处理的告警'}), 400
    if len(raw_ids) > 100:
        return jsonify({'error': '单次最多处理 100 条告警'}), 400
    try:
        ids = list(dict.fromkeys(int(alert_id) for alert_id in raw_ids))
    except (TypeError, ValueError):
        return jsonify({'error': '告警编号格式无效'}), 400
    if action not in ('acknowledge', 'resolve', 'urge', 'convert'):
        return jsonify({'error': '不支持的批量操作'}), 400
    reason_labels = {
        'normal_deviation': '正常偏差',
        'manual_review': '人工复核',
        'false_alarm': '误报',
        'equipment_maintenance': '设备维护',
        'environmental_factor': '环境因素',
        'other': '其他',
    }
    reason_code = (data.get('reason') or '').strip()
    remark = (data.get('remark') or '').strip()
    if action == 'resolve' and reason_code not in reason_labels:
        return jsonify({'error': '请选择有效的批量办结原因'}), 400
    if action == 'urge' and not remark:
        return jsonify({'error': '请填写批量督办要求'}), 400
    operator = g.current_user.get('real_name') or g.current_user.get('username') or '管理员'
    completed = 0
    skipped = 0
    with get_db() as db:
        for alert_id in ids:
            alert = db.execute("SELECT * FROM alerts WHERE id=?", (alert_id,)).fetchone()
            if not alert:
                skipped += 1
                continue

            if action == 'acknowledge':
                if alert['status'] != 'pending':
                    skipped += 1
                    continue
                db.execute("UPDATE alerts SET status='acknowledged' WHERE id=?", (alert_id,))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('alert', alert_id, 'acknowledged', operator, '批量受理'))
            elif action == 'resolve':
                if alert['status'] not in ('pending', 'acknowledged') or alert['related_order_no']:
                    skipped += 1
                    continue
                reason = reason_labels[reason_code]
                db.execute(
                    "UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime'), resolve_reason=? WHERE id=?",
                    (reason, alert_id),
                )
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('alert', alert_id, 'resolved', operator, f'批量办结：{reason}'))
                if alert['review_id']:
                    _archive_linked_review(db, None, None, reason, review_id=alert['review_id'])
            elif action == 'urge':
                if alert['status'] == 'resolved':
                    skipped += 1
                    continue
                db.execute("UPDATE alerts SET urge_count=COALESCE(urge_count,0)+1, last_urged_at=datetime('now','localtime') WHERE id=?", (alert_id,))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('alert', alert_id, 'urged', operator, f'批量督办：{remark}'))
            else:
                if (alert['status'] == 'resolved' or alert['related_order_no']
                        or alert['flow_status'] in ('converted', 'dismissed')):
                    skipped += 1
                    continue
                now = datetime.now()
                order_no = f"WO-{now.strftime('%Y%m%d')}-{random.randint(100,999)}"
                level = alert['level']
                order_level = 'critical' if level == 'red' else ('urgent' if level == 'orange' else 'normal')
                sla_hours = {'normal': 72, 'urgent': 24, 'critical': 2}.get(order_level, 72)
                sla_deadline = (now + timedelta(hours=sla_hours)).strftime('%Y-%m-%d %H:%M')
                assignee_row = db.execute(
                    """SELECT u.real_name FROM user_sites us JOIN users u ON u.id=us.user_id
                       JOIN user_roles ur ON ur.user_id=u.id AND ur.role='operator'
                       WHERE us.site_id=? AND u.status='active' LIMIT 1""",
                    (alert['site_id'],),
                ).fetchone()
                assignee = assignee_row['real_name'] if assignee_row else ''
                db.execute("""
                    INSERT INTO work_orders (order_no,site_id,source,event_type,level,title,description,assignee,status,sla_deadline)
                    VALUES (?,?,?,?,?,?,?,?,?,?)
                """, (order_no, alert['site_id'], 'auto', '告警批量转工单', order_level,
                      _generated_workorder_title('auto', alert['message'], '告警批量转工单'),
                      alert['message'], assignee, 'in_progress', sla_deadline))
                db.execute("UPDATE alerts SET related_order_no=?, flow_status='converted', status='pending' WHERE id=?", (order_no, alert_id))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('alert', alert_id, 'converted', operator, f'批量转工单 {order_no}'))
                # 自动流转时间线
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'accepted', '系统', f'工单{order_no} → 已受理（自动）'))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'dispatched', assignee or '系统', f'工单{order_no} → 已派发（自动）'))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'in_progress', '系统', f'工单{order_no} → 处置中（自动）'))
            completed += 1
        db.commit()
        summary = db.execute("SELECT COUNT(*) FROM alerts WHERE status='pending'").fetchone()[0]
        return jsonify({
            'success': True,
            'count': completed,
            'skipped': skipped,
            'summary': {'alerts_pending': summary},
        })

@app.route('/api/timeline')
def get_timeline():
    """时间线查询，可按来源过滤"""
    source_type = request.args.get('source_type', '')
    source_id = request.args.get('source_id', '', type=int) if request.args.get('source_id') else None
    limit = request.args.get('limit', 50, type=int)
    with get_db() as db:
        q = "SELECT * FROM timeline_events WHERE 1=1"
        params = []
        if source_type:
            q += " AND source_type=?"
            params.append(source_type)
        if source_id is not None:
            q += " AND source_id=?"
            params.append(source_id)
        q += " ORDER BY created_at DESC LIMIT ?"
        params.append(limit)
        return jsonify([dict(r) for r in db.execute(q, params).fetchall()])

@app.route('/api/alerts/statistics')
@login_required
def alert_statistics():
    site_ids = _filter_site_ids()
    status = request.args.get('status', '')
    where = []
    params = []
    if site_ids is not None:
        if not site_ids:
            return jsonify({
                'total': 0,
                'by_level': {level: 0 for level in ('red', 'orange', 'yellow', 'blue')},
                'by_status': {state: 0 for state in ('pending', 'acknowledged', 'resolved')},
                'pending_review': 0,
                'auto_converted': 0,
            })
        placeholders = ','.join('?' * len(site_ids))
        where.append(f'site_id IN ({placeholders})')
        params.extend(site_ids)
    if status:
        where.append('status=?')
        params.append(status)
    where_sql = f" WHERE {' AND '.join(where)}" if where else ''
    with get_db() as db:
        total = db.execute(f"SELECT COUNT(*) as c FROM alerts{where_sql}", params).fetchone()['c']
        by_level = {}
        for lv in ['red','orange','yellow','blue']:
            level_where = where + ['level=?']
            by_level[lv] = db.execute(
                f"SELECT COUNT(*) as c FROM alerts WHERE {' AND '.join(level_where)}",
                params + [lv],
            ).fetchone()['c']
        by_status = {}
        if not status:
            for st in ['pending','acknowledged','resolved']:
                state_where = where + ['status=?']
                by_status[st] = db.execute(
                    f"SELECT COUNT(*) as c FROM alerts WHERE {' AND '.join(state_where)}",
                    params + [st],
                ).fetchone()['c']
        else:
            by_status[status] = total
        # 待复核告警统计
        scope_where = [] if site_ids is None else [f"site_id IN ({','.join('?' * len(site_ids))})"]
        scope_params = [] if site_ids is None else list(site_ids)
        pending_review_where = scope_where + ["flow_type='manual'", "flow_status='pending_review'"]
        auto_converted_where = scope_where + ["flow_type='auto'", "flow_status='converted'"]
        pending_review = db.execute(
            f"SELECT COUNT(*) as c FROM alerts WHERE {' AND '.join(pending_review_where)}",
            scope_params,
        ).fetchone()['c']
        auto_converted = db.execute(
            f"SELECT COUNT(*) as c FROM alerts WHERE {' AND '.join(auto_converted_where)}",
            scope_params,
        ).fetchone()['c']
        return jsonify({'total':total, 'by_level':by_level, 'by_status':by_status,
                        'pending_review': pending_review, 'auto_converted': auto_converted})

# --- Simulate Alert (for demo/rule engine) ---
@app.route('/api/alerts/simulate', methods=['POST'])
@login_required
def simulate_alert():
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    site_id = data.get('site_id')
    metric = (data.get('metric') or 'data_spike').strip()
    value = data.get('value', 0)
    level = (data.get('level') or 'blue').strip()
    raw_message = (data.get('message') or f'站点 {site_id} 触发 {metric} 告警').strip()
    if not site_id:
        return jsonify({'error': '缺少 site_id'}), 400
    if level not in ('blue', 'yellow', 'orange', 'red'):
        return jsonify({'error': '告警等级无效'}), 400
    if not metric or len(metric) > 64:
        return jsonify({'error': '监测指标无效'}), 400
    try:
        value = float(value)
    except (TypeError, ValueError):
        return jsonify({'error': '触发值必须是数字'}), 400
    if raw_message.startswith('[模拟]'):
        raw_message = raw_message[4:].strip()
    msg = f'[模拟] {raw_message}'[:500]
    with get_db() as db:
        site = db.execute("SELECT name FROM sites WHERE id=?", (site_id,)).fetchone()
        if not site:
            return jsonify({'error': '站点不存在'}), 404
        site_name = site['name']
        cur = db.execute(
            """INSERT INTO alerts
               (site_id, metric, value, level, message, status, flow_type, flow_status)
               VALUES (?,?,?,?,?,'pending','simulation','test')""",
            (site_id, metric, value, level, msg),
        )
        alert_id = cur.lastrowid
        db.execute(
            """INSERT INTO timeline_events
               (source_type,source_id,event_type,operator,remark)
               VALUES ('alert',?,'simulated',?,?)""",
            (
                alert_id,
                g.current_user.get('real_name') or g.current_user.get('username') or '管理员',
                f'模拟触发 {level} 级告警：{metric}={value}',
            ),
        )
        db.commit()
        return jsonify({'id': alert_id, 'site_name': site_name, 'level': level, 'message': msg})

# --- Work Orders ---
def _workorder_flow_events(db, order):
    """Project only events provably belonging to this work order for mobile detail."""
    order_no = str(order.get('order_no') or '').strip()
    order_id = order.get('id')
    if not order_no or not order_id:
        return []
    labels = {
        'created': '创建工单', 'accepted': '接单', 'dispatched': '派发',
        'in_progress': '开始处置', 'submit_review': '提交核验',
        'approved': '审核通过', 'rejected': '审核退回', 'closed': '完成工单',
    }
    events = [{
        'type': 'created', 'label': labels['created'],
        'operator': order.get('creator') or '系统', 'time': order.get('created_at') or '',
        'remark': '工单创建', '_event_id': 0,
    }]
    columns = {row['name'] for row in db.execute('PRAGMA table_info(timeline_events)').fetchall()}
    if {'source_type', 'source_id', 'event_type'}.issubset(columns):
        time_sql = 'created_at' if 'created_at' in columns else "''"
        id_sql = 'id' if 'id' in columns else 'rowid'
        rows = db.execute(f"""SELECT source_type,source_id,event_type,operator,remark,
                   {time_sql} AS created_at,{id_sql} AS event_id
            FROM timeline_events
            WHERE (source_type='workorder' AND source_id=?)
               OR (source_type='order' AND source_id=0)
            ORDER BY {time_sql},{id_sql}""", (order_id,)).fetchall()
        exact_legacy_marker = re.compile(r'工单' + re.escape(order_no) + r'(?![A-Za-z0-9_-])')
        for row in rows:
            source_type = str(row['source_type'] or '')
            remark = str(row['remark'] or '')
            if source_type == 'order' and not exact_legacy_marker.search(remark):
                continue
            event_type = str(row['event_type'] or '')
            if event_type not in labels:
                continue
            events.append({
                'type': event_type, 'label': labels[event_type],
                'operator': row['operator'] or '系统', 'time': row['created_at'] or '',
                'remark': remark, '_event_id': row['event_id'],
            })
    if order.get('check_in_time'):
        events.append({
            'type': 'check_in', 'label': '到场签到',
            'operator': order.get('check_in_user') or order.get('assignee') or '现场人员',
            'time': order.get('check_in_time') or '', 'remark': '已到场签到', '_event_id': 0,
        })
    order_status = str(order.get('status') or '').strip().lower()
    if (order_status in ('resolved', 'closed') and order.get('resolved_at')
            and not any(event['type'] in ('approved', 'closed') for event in events)):
        events.append({
            'type': 'closed', 'label': labels['closed'], 'operator': '系统',
            'time': order.get('resolved_at') or '', 'remark': '工单已完成', '_event_id': 0,
        })
    business_order = {
        'created': 0, 'accepted': 10, 'dispatched': 20, 'check_in': 30,
        'in_progress': 40, 'submit_review': 50, 'rejected': 60,
        'approved': 70, 'closed': 80,
    }

    def event_sort_key(event):
        event_type = event.get('type') or ''
        event_time = str(event.get('time') or '').strip()
        # Creation is always the origin. Dated facts then follow real time; facts
        # without time are stable after them by business phase and persisted id.
        bucket = 0 if event_type == 'created' else (1 if event_time else 2)
        return (bucket, event_time, business_order.get(event_type, 999),
                int(event.get('_event_id') or 0))

    events.sort(key=event_sort_key)
    terminal = order_status in ('resolved', 'closed')
    for index, event in enumerate(events):
        event['tone'] = 'completed' if terminal or index < len(events) - 1 else 'current'
        event.pop('_event_id', None)
    return events

@app.route('/api/workorders')
@login_required
def get_workorders():
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权查看工单列表'}), 403
    status = request.args.get('status', '')
    limit = request.args.get('limit', 50, type=int)
    site_ids = _filter_site_ids()
    with get_db() as db:
        q = """
            SELECT w.*, s.name as site_name
            FROM work_orders w LEFT JOIN sites s ON w.site_id=s.id
            WHERE 1=1
        """
        params = []
        if site_ids is not None:
            ph = ','.join('?' * len(site_ids))
            q += f" AND w.site_id IN ({ph})"
            params.extend(site_ids)
        if status:
            q += " AND w.status=?"
            params.append(status)
        q += " ORDER BY w.created_at DESC LIMIT ?"
        params.append(limit)
        rows = [dict(r) for r in db.execute(q, params).fetchall()]
        for row in rows:
            row['display_title'] = _workorder_display_title(row)
            row['can_operate'] = _workorder_user_can_operate(row, g.current_user, db)
            row['can_dismiss_auto_alert'] = _workorder_can_dismiss_auto_alert(
                row, g.current_user, db)
            effective_checkin = _workorder_effective_checkin_time(db, row, g.current_user)
            row['effective_check_in_time'] = effective_checkin or ''
            row['checked_in'] = bool(effective_checkin)
            row['flow_events'] = _workorder_flow_events(db, row)
        return jsonify(rows)


@app.route('/api/workorders/<order_no>')
@login_required
def get_workorder_detail(order_no):
    """Read one work order with its authoritative mobile action contract."""
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权查看工单详情', 'code': 'WORKORDER_VIEW_FORBIDDEN'}), 403
    with get_db() as db:
        order = db.execute('''SELECT w.*, s.name AS site_name
                              FROM work_orders w LEFT JOIN sites s ON s.id=w.site_id
                              WHERE w.order_no=?''', (order_no,)).fetchone()
        if not order:
            return jsonify({'error': '工单不存在', 'code': 'WORKORDER_NOT_FOUND'}), 404
        denied = _site_access_denied(order['site_id'], '访问工单')
        if denied:
            return denied
        return jsonify(_project_workorder_detail(db, dict(order), g.current_user))

@app.route('/api/workorders', methods=['POST'])
def create_workorder():
    """创建工单 — 直接进入处置中（跳过待受理/已受理/已派发，系统自动完成）"""
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '审核角色不能创建工单'}), 403
    data = request.get_json(force=True, silent=True)
    if not data:
        return jsonify({'error': '无效的请求数据'}), 400

    # ---- 字段规范化：移动端可能写入非标准值，统一映射为Web端标准值 ----
    # 来源规范化
    _source_map = {
        'inspection': 'inspection', '巡检': 'inspection',
        'patrol': 'patrol', '巡查': 'patrol',
        'auto': 'auto', '自动': 'auto',
        'manual': 'manual', '人工': 'manual',
        'superior': 'superior', '上级': 'superior',
        'hotline': 'hotline', '热线': 'hotline',
        'alert_convert': 'alert_convert', '告警转工单': 'alert_convert',
        'alert_auto': 'alert_auto',
    }
    raw_source = (data.get('source') or 'manual').strip().lower()
    data['source'] = _source_map.get(raw_source, raw_source if raw_source in _source_map.values() else 'manual')

    # 级别规范化
    _level_map = {
        'normal': 'normal', '一般': 'normal', 'blue': 'normal', 'yellow': 'normal',
        'medium': 'normal',
        'urgent': 'urgent', '紧急': 'urgent', 'orange': 'urgent',
        'critical': 'critical', '重大': 'critical', 'red': 'critical',
    }
    raw_level = (data.get('level') or 'normal').strip().lower()
    data['level'] = _level_map.get(raw_level, raw_level if raw_level in _level_map.values() else 'normal')

    # ---- 去重：同站点+同来源+相似标题的未关闭工单已存在则返回已有工单 ----
    title = _normalize_manual_workorder_title(data.get('title'))
    if not title:
        return jsonify({'error': '请填写工单标题'}), 400
    if len(title) > 40:
        return jsonify({'error': '工单标题最长40个字符'}), 400
    data['title'] = title
    site_id = data.get('site_id')
    if not site_id:
        return jsonify({'error': '请选择工单所属站点'}), 400
    denied = _site_access_denied(site_id, '创建工单到')
    if denied:
        return denied
    is_admin = _has_any_role(g.current_user, 'admin')
    assignee = (data.get('assignee') or '').strip() if is_admin else (
        g.current_user.get('real_name') or g.current_user.get('login_name') or ''
    )
    source = data.get('source', 'manual')
    if not is_admin and source not in ('manual', 'inspection', 'patrol'):
        return jsonify({'error': '现场人员不能使用该工单来源'}), 403
    if site_id and title:
        with get_db() as db:
            existing = db.execute(
                "SELECT order_no, title FROM work_orders WHERE site_id=? AND source=? AND status NOT IN ('closed') ORDER BY id DESC LIMIT 5",
                (site_id, source)
            ).fetchall()
            for ex in existing:
                # 标题相似度判断：前20个字符相同即视为重复
                if ex['title'] and ex['title'][:20] == title[:20]:
                    return jsonify({'success': True, 'order_no': ex['order_no'], 'duplicate': True})

    max_retries = 3
    for attempt in range(max_retries):
        try:
            with get_db() as db:
                now = datetime.now()
                order_no = f"WO-{now.strftime('%Y%m%d')}-{random.randint(100,999)}"
                sla_hours = {'normal': 72, 'urgent': 24, 'critical': 2}.get(data.get('level','normal'), 72)
                sla_deadline = (now + timedelta(hours=sla_hours)).strftime('%Y-%m-%d %H:%M')
                # 直接创建为 in_progress（待受理→已受理→已派发→处置中，系统瞬间完成）
                db.execute("""
                    INSERT INTO work_orders (order_no,site_id,source,event_type,level,title,description,images,assignee,status,sla_deadline)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                """, (
                    order_no, data.get('site_id'), data.get('source','manual'),
                    data.get('event_type',''), data.get('level','normal'),
                    title, data.get('description',''),
                    data.get('images',''), assignee,
                    'in_progress', sla_deadline
                ))
                # 时间线记录：记录完整的自动流转链路
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'accepted', '系统', f'工单{order_no} → 已受理（自动）'))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'dispatched', '系统' if not assignee else assignee, f'工单{order_no} → 已派发（自动）'))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('order', 0, 'in_progress', '系统', f'工单{order_no} → 处置中（自动）'))
                db.commit()
                return jsonify({'success': True, 'order_no': order_no})
        except Exception as e:
            if 'database is locked' in str(e) and attempt < max_retries - 1:
                import time as _t
                _t.sleep(0.3 * (attempt + 1))  # 退避: 0.3s, 0.6s
                continue
            return jsonify({'error': str(e)}), 500

def _workorder_user_can_operate(order, user, db):
    """工单现场操作只允许实际负责人且必须仍有目标站点权限。"""
    if not user:
        return False
    assignee = (order['assignee'] or '').strip() if order and 'assignee' in order.keys() else ''
    identity_matches = bool(assignee and assignee in {
        str(user.get('real_name') or '').strip(), str(user.get('username') or '').strip()
    })
    if not identity_matches:
        return False
    if not order or 'site_id' not in order.keys():
        return False
    try:
        site_id = int(order['site_id'])
        user_id = int(user.get('id'))
    except (TypeError, ValueError):
        return False
    return db.execute(
        'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?', (user_id, site_id)
    ).fetchone() is not None


def _transaction_user_can_operate_workorder(db, order, user_id):
    """Re-read the operator role, identity and site scope inside a write transaction."""
    user = db.execute(
        'SELECT id,username,real_name,role,status FROM users WHERE id=?', (user_id,)
    ).fetchone()
    if not user or user['status'] != 'active':
        return False
    roles = _roles_for_user(db, user_id, user['role'])
    if 'operator' not in roles:
        return False
    assignee = str(order['assignee'] or '').strip()
    if not assignee or assignee not in {
            str(user['real_name'] or '').strip(), str(user['username'] or '').strip()}:
        return False
    return db.execute(
        'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?',
        (user_id, order['site_id']),
    ).fetchone() is not None


def _workorder_can_dismiss_auto_alert(order, user, db):
    """Return a display hint only; the mutation endpoint revalidates every fact."""
    if (not order or order['source'] != 'auto' or order['status'] != 'pending'
            or not order['related_alert_id'] or not _workorder_user_can_operate(order, user, db)
            or not _has_any_role(user, 'operator')):
        return False
    alert = db.execute(
        'SELECT status,related_order_no FROM alerts WHERE id=?',
        (order['related_alert_id'],),
    ).fetchone()
    return bool(alert and alert['status'] == 'pending'
                and str(alert['related_order_no'] or '') == str(order['order_no'] or ''))


AUTO_ALERT_DISMISS_CONCLUSIONS = {
    'false_alarm': '误报',
    'normal_deviation': '正常偏差',
    'other': '其他',
}


@app.route('/api/workorders/<order_no>/dismiss-auto-alert', methods=['POST'])
@login_required
def dismiss_auto_alert_workorder(order_no):
    data = request.get_json(silent=True) or {}
    conclusion = str(data.get('conclusion') or '').strip()
    reason = str(data.get('reason') or '').strip()
    if conclusion not in AUTO_ALERT_DISMISS_CONCLUSIONS:
        return jsonify({
            'error': '请选择误报、正常偏差或其他',
            'code': 'AUTO_ALERT_DISMISS_CONCLUSION_INVALID',
        }), 400
    if not reason:
        return jsonify({
            'error': '请填写无需处置原因',
            'code': 'AUTO_ALERT_DISMISS_REASON_REQUIRED',
        }), 400
    if len(reason) > 500:
        return jsonify({
            'error': '无需处置原因不能超过 500 字',
            'code': 'AUTO_ALERT_DISMISS_REASON_TOO_LONG',
        }), 400

    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        order = db.execute('SELECT * FROM work_orders WHERE order_no=?', (order_no,)).fetchone()
        if not order:
            return jsonify({'error': '工单不存在', 'code': 'WORKORDER_NOT_FOUND'}), 404
        if (order['status'] == 'closed' and order['source'] == 'auto'
                and order['conclusion'] == conclusion and order['remark'] == reason
                and order['related_alert_id']):
            alert = db.execute(
                'SELECT status,related_order_no,resolve_reason FROM alerts WHERE id=?',
                (order['related_alert_id'],),
            ).fetchone()
            if (alert and alert['status'] == 'resolved'
                    and alert['resolve_reason'] == conclusion
                    and str(alert['related_order_no'] or '') == order_no):
                return jsonify({
                    'success': True, 'status': 'closed', 'already_dismissed': True,
                    'conclusion': conclusion,
                })
        if order['source'] != 'auto' or not order['related_alert_id']:
            return jsonify({
                'error': '仅系统自动预警生成的工单可判定无需处置',
                'code': 'AUTO_ALERT_WORKORDER_REQUIRED',
            }), 409
        if order['status'] != 'pending':
            return jsonify({
                'error': '工单已接单、处置或关闭，不能再判定无需处置',
                'code': 'AUTO_ALERT_WORKORDER_NOT_PENDING',
            }), 409
        if not _transaction_user_can_operate_workorder(
                db, order, g.current_user.get('id')):
            return jsonify({
                'error': '仅对应负责运维人员可判定该预警工单',
                'code': 'AUTO_ALERT_DISMISS_FORBIDDEN',
            }), 403
        alert = db.execute('SELECT * FROM alerts WHERE id=?', (order['related_alert_id'],)).fetchone()
        if (not alert or str(alert['related_order_no'] or '') != order_no):
            return jsonify({
                'error': '工单与告警关联不一致，请联系管理员核对',
                'code': 'AUTO_ALERT_LINK_MISMATCH',
            }), 409
        if alert['status'] != 'pending':
            return jsonify({
                'error': '关联告警已处理或状态已变更，请刷新后重试',
                'code': 'AUTO_ALERT_NOT_PENDING',
            }), 409

        actor = _current_actor_name()
        conclusion_label = AUTO_ALERT_DISMISS_CONCLUSIONS[conclusion]
        try:
            changed_order = db.execute(
                """UPDATE work_orders SET status='closed',conclusion=?,remark=?,
                   resolved_at=datetime('now','localtime')
                   WHERE id=? AND status='pending'""",
                (conclusion, reason, order['id']),
            )
            changed_alert = db.execute(
                """UPDATE alerts SET status='resolved',resolve_reason=?,
                   resolved_at=datetime('now','localtime')
                   WHERE id=? AND status='pending' AND related_order_no=?""",
                (conclusion, alert['id'], order_no),
            )
            if changed_order.rowcount != 1 or changed_alert.rowcount != 1:
                raise sqlite3.IntegrityError('auto alert disposition changed concurrently')
            event_remark = f'判定无需处置（{conclusion_label}）：{reason}'
            db.execute(
                """INSERT INTO timeline_events
                   (source_type,source_id,event_type,operator,remark)
                   VALUES ('order',?,'auto_alert_dismissed',?,?)""",
                (order['id'], actor, event_remark),
            )
            db.execute(
                """INSERT INTO timeline_events
                   (source_type,source_id,event_type,operator,remark)
                   VALUES ('alert',?,'dismissed',?,?)""",
                (alert['id'], actor, f'关联工单{order_no}{event_remark}'),
            )
            db.commit()
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '判定未完成，数据未发生变化，请刷新后重试',
                'code': 'AUTO_ALERT_DISMISS_ROLLED_BACK',
            }), 503
        return jsonify({
            'success': True, 'status': 'closed', 'alert_status': 'resolved',
            'conclusion': conclusion,
        })


def _inspection_effective_checkin_time(db, site_id, user_id):
    """Return the authoritative station visit for an inspection operation."""
    if not _table_exists(db, 'inspection_checkins'):
        return None
    today = datetime.now().strftime('%Y-%m-%d')
    row = db.execute("""SELECT check_time FROM inspection_checkins
        WHERE site_id=? AND user_id=? AND date(check_time)=?
        ORDER BY datetime(check_time) DESC LIMIT 1""",
        (site_id, user_id, today)).fetchone()
    checkin_time = row['check_time'] if row else None
    checkin_at = _parse_dt(checkin_time)
    if not checkin_at:
        return None
    # Older isolated schemas have no checkout fact and retain the historical
    # same-day behavior. Production visits close when this operator checks out
    # any active plan at the same station.
    if (not _table_exists(db, 'insp_plan_items')
            or not _table_exists(db, 'insp_plans')
            or not _table_has_column(db, 'insp_plan_items', 'check_out_time')):
        return checkin_time
    checkout = db.execute("""SELECT i.check_out_time
        FROM insp_plan_items i
        JOIN insp_plans p ON p.id=i.plan_id
        WHERE p.assignee_id=? AND i.site_id=?
          AND i.check_out_time IS NOT NULL AND date(i.check_out_time)=?
          AND COALESCE(i.execution_status,'active')='active'
        ORDER BY datetime(i.check_out_time) DESC LIMIT 1""",
        (user_id, site_id, today)).fetchone()
    checkout_at = _parse_dt(checkout['check_out_time']) if checkout else None
    if checkout_at and checkin_at <= checkout_at:
        return None
    return checkin_time


def _inspection_rework_checkin_time(db, plan_id, site_id, user_id, required_at):
    """Reuse only an arrival from the execution window that produced this rework."""
    if not required_at or not _table_exists(db, 'inspection_checkins'):
        return None
    if _table_has_column(db, 'insp_plans', 'rework_of_plan_id'):
        plan = db.execute(
            'SELECT generate_date, rework_of_plan_id FROM insp_plans WHERE id=?',
            (plan_id,),
        ).fetchone()
        if plan and plan['rework_of_plan_id'] is not None:
            original = db.execute(
                'SELECT generate_date FROM insp_plans WHERE id=?',
                (plan['rework_of_plan_id'],),
            ).fetchone()
            if original:
                plan = original
    else:
        plan = db.execute('SELECT generate_date FROM insp_plans WHERE id=?', (plan_id,)).fetchone()
    if not plan or not plan['generate_date']:
        return None
    row = db.execute("""SELECT check_time FROM inspection_checkins
        WHERE site_id=? AND user_id=?
          AND datetime(check_time)>=datetime(?)
          AND datetime(check_time)<=datetime(?)
        ORDER BY datetime(check_time) DESC LIMIT 1""",
        (site_id, user_id, str(plan['generate_date'])[:10], required_at)).fetchone()
    return row['check_time'] if row and _parse_dt(row['check_time']) else None


def _inspection_item_checkin_time(db, item, user_id):
    """Resolve the arrival that may authorize this specific inspection item."""
    if not item:
        return None
    keys = set(item.keys())
    required_at = item['rework_required_at'] if 'rework_required_at' in keys else None
    review_status = int(item['review_status'] or 0) if 'review_status' in keys else 0
    evidence_status = (item['evidence_status'] or '') if 'evidence_status' in keys else ''
    is_rework = bool(required_at and (
        review_status == 3 or evidence_status in ('supplement_required', 'replacement_submitted')
    ))
    if is_rework:
        return _inspection_rework_checkin_time(
            db, item['plan_id'], item['site_id'], user_id, required_at)
    return _inspection_effective_checkin_time(db, item['site_id'], user_id)


def _workorder_effective_checkin_time(db, order, user):
    """Resolve one station-arrival fact for the assigned operator.

    A work order can be linked after the operator has already checked in for a
    same-day inspection at the same site.  Requiring a second GPS check-in for
    every linked work order creates contradictory station states, so field
    gates accept either the work-order check-in or that same station visit.
    """
    if not order or not user or not _workorder_user_can_operate(order, user, db):
        return None
    direct = order['check_in_time'] if 'check_in_time' in order.keys() else None
    parsed_direct = _parse_dt(direct)
    if parsed_direct and parsed_direct.date() == datetime.now().date():
        return direct
    return _inspection_effective_checkin_time(db, order['site_id'], user['id'])


def _workorder_arrival_resource_state(db, order_no, user_id):
    """Determine whether this operator has an approved, executable arrival resource."""
    applications = db.execute("""SELECT id, vehicle_id, status, no_vehicle_required,
                                      vehicle_exception_reason
                               FROM vehicle_applications
                               WHERE work_order_no=? AND applicant_id=?
                               ORDER BY id DESC""", (order_no, user_id)).fetchall()
    if not applications:
        return False, 'WORKORDER_RESOURCE_PREPARATION_REQUIRED', '请先为该工单准备本人用车申请或登记无车例外'

    approved_vehicle = []
    has_unapproved = False
    for application in applications:
        if application['status'] != 'approved':
            # Pending and rejected requests can be resolved by the approval flow;
            # terminal history (returned/cancelled/archived) needs a new preparation.
            if application['status'] in ('pending', 'rejected'):
                has_unapproved = True
            continue
        if application['no_vehicle_required']:
            if str(application['vehicle_exception_reason'] or '').strip():
                return True, None, None
            has_unapproved = True
            continue
        if application['vehicle_id']:
            approved_vehicle.append(application['id'])

    for application_id in approved_vehicle:
        active_use = db.execute("""SELECT 1 FROM vehicle_use_records
                                  WHERE application_id=? AND returned_at IS NULL
                                  LIMIT 1""", (application_id,)).fetchone()
        if active_use:
            return True, None, None
    if approved_vehicle:
        return False, 'WORKORDER_VEHICLE_CHECKOUT_REQUIRED', '已批准用车申请尚未出车，完成出车登记后方可到场'
    if has_unapproved:
        return False, 'WORKORDER_RESOURCE_APPROVAL_REQUIRED', '工单用车或无车例外尚未获批'
    return False, 'WORKORDER_RESOURCE_PREPARATION_REQUIRED', '请准备可执行的工单用车或无车例外'


def _rework_arrival_resource_state(db, plan_id, user_id):
    """A remediation package needs a newly approved resource, never its old trip."""
    if not _table_has_column(db, 'insp_plans', 'rework_of_plan_id'):
        return True, None, None
    plan = db.execute("""SELECT rework_of_plan_id, resource_state FROM insp_plans
        WHERE id=? AND assignee_id=?""", (plan_id, user_id)).fetchone()
    if not plan or plan['rework_of_plan_id'] is None:
        return True, None, None
    applications = db.execute("""SELECT id, vehicle_id, status, no_vehicle_required,
            vehicle_exception_reason FROM vehicle_applications
        WHERE rework_plan_id=? AND applicant_id=? ORDER BY id DESC""",
        (plan_id, user_id)).fetchall()
    if not applications:
        return False, 'REWORK_RESOURCE_PREPARATION_REQUIRED', '请先重新安排车辆或登记无车例外'
    has_unapproved = False
    approved_vehicle = []
    for application in applications:
        if application['status'] != 'approved':
            if application['status'] in ('pending', 'rejected'):
                has_unapproved = True
            continue
        if application['no_vehicle_required']:
            if str(application['vehicle_exception_reason'] or '').strip():
                return True, None, None
            has_unapproved = True
        elif application['vehicle_id']:
            approved_vehicle.append(application['id'])
    for application_id in approved_vehicle:
        active_use = db.execute("""SELECT 1 FROM vehicle_use_records
            WHERE application_id=? AND returned_at IS NULL LIMIT 1""", (application_id,)).fetchone()
        if active_use:
            return True, None, None
    if approved_vehicle:
        return False, 'REWORK_VEHICLE_CHECKOUT_REQUIRED', '整改补检车辆已批准，完成出车登记后方可到站'
    if has_unapproved:
        return False, 'REWORK_RESOURCE_APPROVAL_REQUIRED', '整改补检资源尚未获批'
    return False, 'REWORK_RESOURCE_PREPARATION_REQUIRED', '请重新安排车辆或登记无车例外'


def _inspection_arrival_resource_state(db, plan_id, user_id):
    """Resolve the authoritative vehicle gate for one inspection package."""
    rework_supported = _table_has_column(db, 'insp_plans', 'rework_of_plan_id')
    rework_select = ', rework_of_plan_id' if rework_supported else ', NULL AS rework_of_plan_id'
    plan = db.execute(f"""SELECT plan_schedule_id, generate_date{rework_select}
        FROM insp_plans WHERE id=? AND assignee_id=?""", (plan_id, user_id)).fetchone()
    if not plan:
        return False, 'EXECUTION_TARGET_UNAVAILABLE', '当前执行包已不可用，请刷新后重试'
    if plan['rework_of_plan_id'] is not None:
        return _rework_arrival_resource_state(db, plan_id, user_id)
    if plan['plan_schedule_id'] is None:
        return True, None, None

    schedule_columns = {
        row['name'] for row in db.execute('PRAGMA table_info(plan_schedules)').fetchall()
    }
    if 'vehicle_days' not in schedule_columns:
        # Pre-resource compatibility schemas cannot express a planned vehicle.
        return True, None, None
    schedule = db.execute("""SELECT status, vehicle_days FROM plan_schedules
        WHERE id=?""", (plan['plan_schedule_id'],)).fetchone()
    if not schedule or schedule['status'] != 'approved':
        return False, 'EXECUTION_TARGET_UNAVAILABLE', '当前计划已不可执行，请刷新后重试'
    try:
        vehicle_days = json.loads(schedule['vehicle_days'] or '{}')
        if not isinstance(vehicle_days, dict):
            raise ValueError('vehicle_days must be an object')
        vehicle_id = vehicle_days.get(str(plan['generate_date'])[:10])
        vehicle_id = int(vehicle_id) if vehicle_id not in (None, '') else None
        if vehicle_id is not None and vehicle_id <= 0:
            raise ValueError('invalid vehicle id')
    except (TypeError, ValueError, json.JSONDecodeError):
        return False, 'ARRIVAL_RESOURCE_STATE_UNAVAILABLE', '车辆安排状态暂不可用，请刷新后重试'
    if vehicle_id is None:
        return True, None, None
    if (not _table_exists(db, 'vehicle_applications')
            or not _table_exists(db, 'vehicle_use_records')):
        return False, 'ARRIVAL_RESOURCE_STATE_UNAVAILABLE', '车辆履约状态暂不可用，请刷新后重试'

    work_date = str(plan['generate_date'])[:10]
    application = db.execute("""SELECT * FROM vehicle_applications
        WHERE vehicle_id=? AND applicant_id=?
          AND date(start_at)<=? AND date(end_at)>=?
          AND reason LIKE ?
        ORDER BY id DESC LIMIT 1""", (
            vehicle_id, user_id, work_date, work_date,
            _ps_vehicle_reason_like(plan['plan_schedule_id']),
        )).fetchone()
    if not application:
        return False, 'VEHICLE_APPLICATION_REQUIRED', '当前计划车辆尚无可用的用车申请，请先完成用车安排'
    if str(application['status'] or '').strip().lower() != 'approved':
        return False, 'VEHICLE_APPLICATION_INVALID', '当前用车申请已失效，请重新安排后再到站'
    application_state = _vehicle_plan_application_state(db, application)
    if application_state.get('needs_extension'):
        return False, 'VEHICLE_EXTENSION_REQUIRED', '连续行程的用车安排已超期，请先延续用车'
    active_use = db.execute("""SELECT 1 FROM vehicle_use_records
        WHERE application_id=? AND returned_at IS NULL
          AND COALESCE(status, 'checked_out')!='returned'
        LIMIT 1""", (application['id'],)).fetchone()
    if not active_use:
        return False, 'VEHICLE_CHECKOUT_REQUIRED', '计划车辆尚未完成出车登记，出车后方可到站'
    return True, None, None


def _inspection_arrival_gate(db, plan_id, user_id):
    allowed, code, message = _inspection_arrival_resource_state(db, plan_id, user_id)
    return {'allowed': bool(allowed), 'code': code, 'message': message}


@app.route('/api/workorders/<order_no>/status', methods=['PUT'])
@login_required
def update_workorder_status(order_no):
    data = request.get_json(silent=True) or {}
    new_status = data.get('status')
    if 'images' in data:
        return jsonify({
            'error': '工单照片只能通过照片上传或删除入口维护',
            'code': 'WORKORDER_IMAGES_READ_ONLY',
        }), 400
    # 关单必须通过专用核验接口完成。该接口会校验证据、记录核验人并联动处理
    # 关联的异常上报；不能让通用状态更新绕开这些业务门禁。
    if new_status == 'closed':
        return jsonify({'error': '请通过“核验通过并办结”完成关单，系统会先校验处置证据'}), 400
    if new_status == 'reviewing':
        return jsonify({'error': '请通过“提交审核”提交工单，系统会先校验处置影像'}), 400
    valid_transitions = {
        'pending': ['accepted'],
        'accepted': ['in_progress', 'dispatched'],
        'dispatched': ['in_progress'],
        'in_progress': ['accepted'],
        'reviewing': ['in_progress'],
    }
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        cur = db.execute("SELECT status, related_alert_id, used_parts, site_id, check_in_time, assignee FROM work_orders WHERE order_no=?", (order_no,)).fetchone()
        if not cur:
            return jsonify({'error': 'not found'}), 404
        if not _workorder_user_can_operate(cur, g.current_user, db):
            return jsonify({'error': '只能操作分配给自己的工单'}), 403
        if new_status not in valid_transitions.get(cur['status'], []):
            return jsonify({'error': f'invalid transition from {cur["status"]} to {new_status}'}), 400
        # 流程门禁（移动端强制）：到场签到后方可开始处置，防办公室内远程空转
        if (data.get('client') == 'mobile' and new_status == 'in_progress'
                and not _workorder_effective_checkin_time(db, cur, g.current_user)):
            return jsonify({'error': '请先到场签到后再开始处置'}), 400
        updates = ["status=?"]
        params = [new_status]
        if new_status == 'closed':
            updates.append("resolved_at=datetime('now','localtime')")
        if 'remark' in data:
            updates.append("remark=?")
            params.append(data['remark'])
        if 'conclusion' in data:
            updates.append("conclusion=?")
            params.append(data['conclusion'])
        if 'satisfaction' in data:
            updates.append("satisfaction=?")
            params.append(data['satisfaction'])
        params.append(order_no)
        db.execute(f"UPDATE work_orders SET {','.join(updates)} WHERE order_no=?", params)
        # 时间线记录
        operator = _current_actor_name()
        status_cn = {'pending':'待受理','accepted':'已受理','dispatched':'已派发','in_progress':'处置中','reviewing':'审核中','closed':'已完成'}
        event_label = status_cn.get(new_status, new_status)
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, new_status, operator, f'工单{order_no} → {event_label}'))

        # === 数据自洽性修复：工单关闭时联动更新 ===
        if new_status == 'closed':
            # 1. 关联告警自动办结（带回写结论）
            if cur['related_alert_id']:
                concl = data.get('conclusion') or 'false_alarm'
                db.execute(
                    "UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime'), resolve_reason=? WHERE id=? AND status != 'resolved'",
                    (concl, cur['related_alert_id'])
                )
                db.execute(
                    "INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                    ('alert', cur['related_alert_id'], 'resolved', '系统', f'关联工单{order_no}完成，告警自动办结（{concl}）')
                )
                # 闭环：关联数据审核项一并归档
                a = db.execute("SELECT site_id, metric FROM alerts WHERE id=?", (cur['related_alert_id'],)).fetchone()
                if a:
                    _archive_linked_review(db, a['site_id'], a['metric'], concl, order_no=order_no)
            # 2. 关联热线事件自动关闭
            db.execute(
                "UPDATE hotline_events SET status='closed' WHERE related_order_no=? AND status != 'closed'",
                (order_no,)
            )
            _mark_manual_reports_resolved(db, order_no)
            # 3. 备件库存扣减（used_parts为JSON格式: [{part_id, quantity}]）
            if cur['used_parts']:
                try:
                    import json as _json
                    parts = _json.loads(cur['used_parts'])
                    for part in parts:
                        part_id = part.get('part_id')
                        qty = part.get('quantity', 0)
                        if part_id and qty > 0:
                            db.execute(
                                "UPDATE spare_parts_inventory SET quantity=MAX(0, quantity-?), updated_at=datetime('now','localtime') WHERE id=?",
                                (qty, part_id)
                            )
                            db.execute(
                                """INSERT INTO inventory_logs
                                   (part_id,type,quantity,ref_type,ref_id,operator,operator_id,remark)
                                   VALUES (?,'out',?,'workorder',?,?,?,'工单领料')""",
                                (part_id, qty, 0, _current_actor_name(), g.current_user.get('id')),
                            )
                except Exception as e:
                    print(f'[WO] 备件扣减失败: {e}')

        db.commit()
        return jsonify({'success': True, 'status': new_status})

# --- Work Order Verification ---
@app.route('/api/workorders/<order_no>/submit-review', methods=['POST'])
@login_required
def submit_workorder_review(order_no):
    data = request.get_json(silent=True) or {}
    if 'images' in data:
        return jsonify({
            'error': '工单照片只能通过照片上传或删除入口维护',
            'code': 'WORKORDER_IMAGES_READ_ONLY',
        }), 400
    resolution_note = (data.get('resolution_note') or data.get('remark') or '').strip()
    if not resolution_note:
        return jsonify({'error': '请填写现场处置说明后再提交核验'}), 400
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        if not _table_has_column(db, 'work_orders', 'review_submitter_id'):
            db.execute('ALTER TABLE work_orders ADD COLUMN review_submitter_id INTEGER')
        if not _table_has_column(db, 'work_orders', 'review_cycle'):
            db.execute('ALTER TABLE work_orders ADD COLUMN review_cycle INTEGER DEFAULT 0')
        cur = db.execute("SELECT id, status, images, assignee, site_id, title, check_in_time FROM work_orders WHERE order_no=?", (order_no,)).fetchone()
        if not cur:
            return jsonify({'error': '工单不存在'}), 404
        if not _workorder_user_can_operate(cur, g.current_user, db):
            return jsonify({'error': '只能提交分配给自己的工单核验'}), 403
        if cur['status'] == 'reviewing':
            return jsonify({'success': True, 'status': 'reviewing', 'already_submitted': True})
        if cur['status'] == 'closed':
            return jsonify({'success': True, 'status': 'closed', 'already_closed': True})
        if (cur['status'] != 'closed'
                and not _workorder_effective_checkin_time(db, cur, g.current_user)):
            return jsonify({
                'error': '请先完成现场到场签到后再提交核验',
                'code': 'WORKORDER_CHECKIN_REQUIRED',
            }), 409
        if cur['status'] != 'in_progress':
            return jsonify({'error': f'当前状态 {cur["status"]} 不允许提交核验'}), 400
        # 提交核验前必须有处置影像。不能因来源是 Web 就绕过证据要求。
        gate = _evidence_gate(db, 'workorder', cur['id'], 1)
        if gate:
            return jsonify(gate), 409
        submitted_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')
        db.execute("""UPDATE work_orders
                      SET status='reviewing', remark=?, review_submitted_at=?,
                          review_submitter_id=?,review_cycle=COALESCE(review_cycle,0)+1
                      WHERE order_no=?""",
                   (resolution_note, submitted_at, g.current_user['id'], order_no))
        review_cycle = db.execute('SELECT review_cycle FROM work_orders WHERE order_no=?',
                                  (order_no,)).fetchone()['review_cycle']
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'submit_review', _current_actor_name(), f'工单{order_no} 提交核验'))
        recipients = _notify_workorder_reviewers(db, cur['site_id'], order_no, cur['title'])
        outbox_ids = _wx_queue_pending_approval(
            db, 'workorder', order_no, 'reviewing', recipients, g.current_user['id'],
            '工单核验', cur['title'] or order_no, order_no,
            submitted_at, site_id=cur['site_id'], cycle_key=f'review:{review_cycle}',
            page=_wx_page('/pages/review/view', target_type='workorder_review',
                          target_id=order_no, cycle_key=f'review:{review_cycle}'))
        db.commit()
        return jsonify({'success': True, 'status': 'reviewing'})


def _workorder_linked_alerts_for_close(db, order, order_no):
    """Validate both structured link directions before a close writes anything."""
    related_alert_id = order.get('related_alert_id')
    params = [order_no]
    condition = 'related_order_no=?'
    if related_alert_id not in (None, '', 0, '0'):
        condition = f'(related_order_no=? OR id=?)'
        params.append(related_alert_id)
    alerts = [dict(row) for row in db.execute(
        f"""SELECT id,site_id,metric,status,related_order_no,resolved_at,resolve_reason
            FROM alerts WHERE {condition} ORDER BY id""", params).fetchall()]

    if related_alert_id not in (None, '', 0, '0') and not any(
            str(alert['id']) == str(related_alert_id) for alert in alerts):
        return None, ('WORKORDER_ALERT_LINK_CONFLICT', '工单关联的告警不存在，请联系管理员核对')

    for alert in alerts:
        reverse_order_no = str(alert.get('related_order_no') or '').strip()
        if str(alert.get('site_id')) != str(order.get('site_id')):
            return None, ('WORKORDER_ALERT_LINK_CONFLICT', '工单与关联告警站点不一致，无法办结')
        if (str(alert['id']) == str(related_alert_id)
                and reverse_order_no and reverse_order_no != order_no):
            return None, ('WORKORDER_ALERT_LINK_CONFLICT', '工单与告警关联指向冲突，请联系管理员核对')
        if str(alert.get('status') or '').strip().lower() not in ('pending', 'acknowledged', 'resolved'):
            return None, ('WORKORDER_ALERT_STATE_CONFLICT', '关联告警状态已变化，请刷新后重试')
    return alerts, None


def _resolve_workorder_linked_alerts(db, alerts, order_no, conclusion, actor):
    """Resolve each still-open linked alert exactly once inside the close transaction."""
    for alert in alerts:
        prior_status = str(alert.get('status') or '').strip().lower()
        if prior_status == 'resolved':
            continue
        changed = db.execute(
            """UPDATE alerts SET status='resolved',resolved_at=datetime('now','localtime'),
                      resolve_reason=? WHERE id=? AND status=?""",
            (conclusion, alert['id'], prior_status),
        )
        if changed.rowcount != 1:
            raise sqlite3.IntegrityError('linked alert state changed during work-order close')
        db.execute(
            """INSERT INTO timeline_events
               (source_type,source_id,event_type,operator,remark)
               VALUES ('alert',?,'resolved',?,?)""",
            (alert['id'], actor, f'关联工单{order_no}核验通过，告警同步办结（{conclusion}）'),
        )
        if _table_exists(db, 'data_reviews'):
            _archive_linked_review(
                db, alert.get('site_id'), alert.get('metric'), conclusion, order_no=order_no)

@app.route('/api/workorders/<order_no>/approve', methods=['POST'])
@login_required
def approve_workorder(order_no):
    # 工单核验属于审核职责，管理员与审核员均可执行。
    denied = require_reviewer()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        cur = db.execute("SELECT * FROM work_orders WHERE order_no=?", (order_no,)).fetchone()
        if not cur:
            return jsonify({'error': '工单不存在'}), 404
        cur = dict(cur)
        denied = _site_access_denied(cur['site_id'], '审核')
        if denied:
            return denied
        if cur['status'] == 'closed':
            return jsonify({'success': True, 'status': 'closed', 'already_closed': True})
        if cur['status'] != 'reviewing':
            return jsonify({'error': f'当前状态 {cur["status"]} 不允许核验通过'}), 400
        gate = _evidence_gate(db, 'workorder', cur['id'], 1)
        if gate:
            return jsonify(gate), 409
        risky_evidence = db.execute("""
            SELECT id, flag_reason, taken_at, duplicate_of_id
            FROM operation_attachments
            WHERE source_type='workorder' AND source_id=? AND file_type='image' AND is_deleted=0
              AND evidence_qualification='qualified'
              AND (is_flagged=1 OR duplicate_of_id IS NOT NULL)
        """, (cur['id'],)).fetchall()
        if risky_evidence:
            return jsonify({
                'error': f'该工单有 {len(risky_evidence)} 张已标记风险的影像，不能通过普通审核放行',
                'code': 'EVIDENCE_RISK_REVIEW_REQUIRED',
                'evidence_risks': [dict(row) for row in risky_evidence],
            }), 409
        linked_alerts, link_error = _workorder_linked_alerts_for_close(db, cur, order_no)
        if link_error:
            code, message = link_error
            return jsonify({'error': message, 'code': code}), 409
        changed_order = db.execute(
            """UPDATE work_orders SET status='closed',resolved_at=datetime('now','localtime')
               WHERE id=? AND status='reviewing'""", (cur['id'],))
        if changed_order.rowcount != 1:
            db.rollback()
            return jsonify({
                'error': '工单状态已变化，办结未生效，请刷新后重试',
                'code': 'WORKORDER_CLOSE_STATE_CONFLICT',
            }), 409
        _retire_workorder_review_notifications(db, order_no)
        # 工单审核即为其处置影像的审核结论，不再额外产生独立照片待办。
        db.execute("""UPDATE operation_attachments
                      SET review_status='approved', reviewer_id=?, reviewed_at=datetime('now','localtime'), reject_reason=NULL
                      WHERE source_type='workorder' AND source_id=(SELECT id FROM work_orders WHERE order_no=?)
                        AND is_deleted=0 AND evidence_qualification='qualified'
                        AND COALESCE(review_status,'pending')='pending'""",
                   (g.current_user.get('id'), order_no))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'approved', _current_actor_name(), f'工单{order_no} 核验通过'))
        # Both relation directions are authoritative. Validation happened before
        # the order write; any alert update/audit failure rolls the whole close back.
        concl = data.get('conclusion') or 'false_alarm'
        try:
            _resolve_workorder_linked_alerts(
                db, linked_alerts, order_no, concl, _current_actor_name())
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '工单办结未完成，数据未发生变化，请刷新后重试',
                'code': 'WORKORDER_CLOSE_ROLLED_BACK',
            }), 503
        db.execute(
            "UPDATE hotline_events SET status='closed' WHERE related_order_no=? AND status != 'closed'",
            (order_no,)
        )
        _mark_manual_reports_resolved(db, order_no)
        if cur['used_parts']:
            try:
                import json as _json
                parts = _json.loads(cur['used_parts'])
                for part in parts:
                    part_id = part.get('part_id')
                    qty = part.get('quantity', 0)
                    if part_id and qty > 0:
                        db.execute(
                            "UPDATE spare_parts_inventory SET quantity=MAX(0, quantity-?), updated_at=datetime('now','localtime') WHERE id=?",
                            (qty, part_id)
                        )
                        db.execute(
                            """INSERT INTO inventory_logs
                               (part_id,type,quantity,ref_type,ref_id,operator,operator_id,remark)
                               VALUES (?,'out',?,'workorder',?,?,?,'工单领料')""",
                            (part_id, qty, 0, _current_actor_name(), g.current_user.get('id')),
                        )
            except Exception as e:
                print(f'[WO] 备件扣减失败: {e}')
        result_notice_id = None
        if cur.get('review_submitter_id'):
            result_notice_id = _upsert_unread_notification(
                db, cur['review_submitter_id'], 'workorder', order_no,
                '工单核验通过', f'{order_no} 已核验通过并闭环',
                dedupe_key=f'workorder_result:{order_no}:review:{cur.get("review_cycle") or 0}')
        result_id = _wx_queue_approval_result(
            db, 'workorder', order_no, 'closed', cur.get('review_submitter_id'),
            '工单核验', cur.get('title') or order_no, '已通过',
            datetime.now().strftime('%Y-%m-%d %H:%M:%S'), '工单已闭环',
            cycle_key=f'review:{cur.get("review_cycle") or 0}',
            page=_wx_page('/pages/workorder/workorder', order_no=order_no,
                          notification_id=result_notice_id))
        db.commit()
        return jsonify({'success': True, 'status': 'closed'})

@app.route('/api/workorders/<order_no>/reject', methods=['POST'])
@login_required
def reject_workorder(order_no):
    # 工单核验属于审核职责，管理员与审核员均可执行。
    denied = require_reviewer()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    reason = (data.get('reason') or data.get('comment') or '').strip()
    if not reason:
        return jsonify({'error': '请填写退回原因，便于现场人员补充整改'}), 400
    with get_db() as db:
        cur = db.execute("SELECT * FROM work_orders WHERE order_no=?", (order_no,)).fetchone()
        if not cur:
            return jsonify({'error': '工单不存在'}), 404
        denied = _site_access_denied(cur['site_id'], '审核')
        if denied:
            return denied
        if cur['status'] != 'reviewing':
            return jsonify({'error': f'当前状态 {cur["status"]} 不允许退回'}), 400
        db.execute("UPDATE work_orders SET status='in_progress' WHERE order_no=?", (order_no,))
        _retire_workorder_review_notifications(db, order_no)
        db.execute("""UPDATE operation_attachments
                      SET review_status='rejected', reviewer_id=?, reviewed_at=datetime('now','localtime'), reject_reason=?
                      WHERE source_type='workorder' AND source_id=(SELECT id FROM work_orders WHERE order_no=?)
                        AND is_deleted=0""", (g.current_user.get('id'), reason, order_no))
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('order', 0, 'rejected', _current_actor_name(), f'工单{order_no} 核验退回：{reason}'))
        result_recipient_id = cur['review_submitter_id'] if 'review_submitter_id' in cur.keys() else None
        result_notice_id = None
        if result_recipient_id:
            result_notice_id = _upsert_unread_notification(
                db, result_recipient_id, 'workorder', order_no,
                '工单核验退回', f'{order_no}：{reason}',
                dedupe_key=f'workorder_result:{order_no}:review:{cur["review_cycle"] if "review_cycle" in cur.keys() else 0}')
        result_id = _wx_queue_approval_result(
            db, 'workorder', order_no, 'in_progress',
            result_recipient_id,
            '工单核验', cur['title'] if 'title' in cur.keys() else order_no, '已退回',
            datetime.now().strftime('%Y-%m-%d %H:%M:%S'), reason,
            cycle_key=f'review:{cur["review_cycle"] if "review_cycle" in cur.keys() else 0}',
            page=_wx_page('/pages/workorder/workorder', order_no=order_no,
                          notification_id=result_notice_id))
        db.commit()
        return jsonify({'success': True, 'status': 'in_progress'})

@app.route('/api/workorders/<order_no>/used-parts', methods=['PUT'])
@login_required
def update_workorder_used_parts(order_no):
    """更新工单使用的备件列表（JSON格式: [{part_id, quantity}]）"""
    data = request.get_json(silent=True) or {}
    used_parts = data.get('used_parts', [])
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        cur = db.execute("SELECT id, status, site_id, assignee FROM work_orders WHERE order_no=?", (order_no,)).fetchone()
        if not cur:
            return jsonify({'error': '工单不存在'}), 404
        if not _workorder_user_can_operate(cur, g.current_user, db):
            return jsonify({'error': '只能登记分配给自己的工单备件'}), 403
        if cur['status'] == 'closed':
            return jsonify({'error': '工单已关闭，无法修改备件'}), 400
        import json as _json
        db.execute("UPDATE work_orders SET used_parts=? WHERE order_no=?",
                   (_json.dumps(used_parts, ensure_ascii=False), order_no))
        db.commit()
        return jsonify({'success': True})


