def _attachment_business_filter(business_type, table_alias='oa'):
    """Return an exclusive business-scope predicate for attachment queries.

    source_type is authoritative. category is only used to classify legacy rows
    whose source is missing or unknown, so one attachment never belongs to two
    user-facing groups.
    """
    prefix = f'{table_alias}.' if table_alias else ''
    all_sources = tuple(
        source
        for group in ATTACHMENT_BUSINESS_GROUPS.values()
        for source in group['sources']
    )
    all_categories = tuple(
        category
        for group in ATTACHMENT_BUSINESS_GROUPS.values()
        for category in group['legacy_categories']
    )
    unknown_source_sql = (
        f"COALESCE({prefix}source_type,'') NOT IN "
        f"({','.join('?' * len(all_sources))})"
    )
    if business_type == 'other':
        return (
            f"({unknown_source_sql} AND COALESCE({prefix}category,'') NOT IN "
            f"({','.join('?' * len(all_categories))}))",
            [*all_sources, *all_categories],
        )

    group = ATTACHMENT_BUSINESS_GROUPS.get(business_type)
    if not group:
        return None, []

    clauses = []
    params = []
    if group['sources']:
        clauses.append(f"{prefix}source_type IN ({','.join('?' * len(group['sources']))})")
        params.extend(group['sources'])
    if group['legacy_categories']:
        clauses.append(
            f"({unknown_source_sql} AND {prefix}category IN "
            f"({','.join('?' * len(group['legacy_categories']))}))"
        )
        params.extend(all_sources)
        params.extend(group['legacy_categories'])
    return f"({' OR '.join(clauses)})", params


ATTACHMENT_REVIEW_STATUS_LABELS = {
    'pending': '待审核',
    'approved': '已通过',
    'rejected': '已驳回',
    'voided': '已作废',
    'superseded': '已替换',
}


def _attachment_status_payload(attachment):
    """Return one mutually exclusive primary status plus an independent risk hint."""
    status = str(attachment.get('review_status') or 'pending').strip().lower()
    if attachment.get('voided_at') or status == 'voided':
        status = 'voided'
    if status not in ATTACHMENT_REVIEW_STATUS_LABELS:
        status = 'pending'
    flagged = bool(attachment.get('is_flagged'))
    if status == 'approved' and flagged:
        risk_label = '曾触发风险/人工已核对'
    elif status == 'pending' and flagged:
        risk_label = '风险标记'
    else:
        risk_label = ''
    qualification = str(attachment.get('evidence_qualification') or 'review').lower()
    qualification_labels = {
        'qualified': '计入有效证据',
        'review': '待核对，不计入有效证据',
        'ineligible': '不计入有效证据',
    }
    return {
        'review_status': status,
        'review_status_label': ATTACHMENT_REVIEW_STATUS_LABELS[status],
        'primary_status': status,
        'primary_status_label': ATTACHMENT_REVIEW_STATUS_LABELS[status],
        'risk_label': risk_label,
        'risk_notice': risk_label,
        'evidence_qualification': qualification,
        'evidence_qualification_label': qualification_labels.get(qualification, qualification_labels['review']),
        'is_effective_evidence': int(
            qualification == 'qualified' and status not in ('rejected', 'voided', 'superseded')
            and not attachment.get('is_deleted')),
        'is_valid_evidence': int(
            qualification == 'qualified' and status not in ('rejected', 'voided', 'superseded')
            and not attachment.get('is_deleted')),
    }


def _persist_inspection_attachment_link(db, attachment_id, item):
    """Persist a server-resolved inspection link on the attachment row.

    Older test fixtures and legacy databases may not have the additive columns
    yet; source_type/source_id remains the compatibility link in that case.
    """
    columns = {row['name'] for row in db.execute(
        'PRAGMA table_info(operation_attachments)').fetchall()}
    fields = {
        'plan_id': item['plan_id'],
        'item_id': item['id'],
        'item_name': item['item_name'] or f'检查项#{item["id"]}',
    }
    updates = [(name, value) for name, value in fields.items() if name in columns]
    if updates:
        db.execute(
            f"UPDATE operation_attachments SET {','.join(f'{name}=?' for name, _ in updates)} WHERE id=?",
            [value for _, value in updates] + [attachment_id],
        )


def _attachment_presentation(db, attachment):
    """Decorate an attachment using only server-owned inspection associations."""
    item = None
    plan = None
    source_type = str(attachment.get('source_type') or '').strip().lower()
    source_id = attachment.get('source_id')
    stored_item_id = attachment.get('item_id')
    stored_plan_id = attachment.get('plan_id')
    stored_item_name = (attachment.get('item_name') or '').strip()
    if _table_exists(db, 'insp_plan_items'):
        lookup_id = stored_item_id or (source_id if source_type == 'inspection' and source_id not in (None, '', 0, '0') else None)
        if lookup_id:
            item = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (lookup_id,)).fetchone()
            item_site_id = item['site_id'] if item and 'site_id' in item.keys() else None
            item_plan_id = item['plan_id'] if item and 'plan_id' in item.keys() else None
            if (not item or item_site_id is None or attachment.get('site_id') != item_site_id
                    or (stored_plan_id not in (None, '', 0, '0')
                        and item_plan_id != stored_plan_id)):
                item = None
        if item:
            stored_item_id = item['id']
            stored_plan_id = item['plan_id'] if 'plan_id' in item.keys() else stored_plan_id
            stored_item_name = item['item_name'] if 'item_name' in item.keys() else stored_item_name

        plan_id_for_lookup = stored_plan_id or (item['plan_id'] if item and 'plan_id' in item.keys() else None)
        if plan_id_for_lookup and _table_exists(db, 'insp_plans'):
            plan_columns = {row['name'] for row in db.execute('PRAGMA table_info(insp_plans)').fetchall()}
            plan_select = ['id']
            if 'plan_name' in plan_columns:
                plan_select.append('plan_name')
            if 'status' in plan_columns:
                plan_select.append('status')
            plan = db.execute(
                f"SELECT {','.join(plan_select)} FROM insp_plans WHERE id=?", (plan_id_for_lookup,)
            ).fetchone()

    site_id = attachment.get('site_id')
    site_name = attachment.get('site_name') or (f'站点#{site_id}' if site_id else '未关联站点')
    item_name = stored_item_name or (item['item_name'] if item and 'item_name' in item.keys() else '') or '检查项待确认'
    linked = bool(item or (stored_item_id not in (None, '', 0, '0') and stored_plan_id not in (None, '', 0, '0')))
    image_type = (attachment.get('recognized_category') or attachment.get('category') or '影像').strip()
    record_time = attachment.get('taken_at') or '拍摄时间待确认'
    result = {
        'original_filename': attachment.get('filename') or '',
        'archive_name': (item_name if item_name != '检查项待确认' else
                         (attachment.get('description') or '').strip() or image_type or
                         f'影像 #{attachment.get("id")}'),
        'item_id': stored_item_id if linked else None,
        'item_name': item_name,
        'plan_id': stored_plan_id if linked else None,
        'plan_name': (plan['plan_name'] if plan and 'plan_name' in plan.keys() else '') or '',
        'business_source': source_type or '未记录',
        'association_status': 'linked' if linked else 'unlinked',
    }
    issue = None
    if not linked and _table_exists(db, 'attachment_link_migration_issues'):
        issue = db.execute(
            'SELECT reason, candidate_item_ids FROM attachment_link_migration_issues WHERE attachment_id=?',
            (attachment.get('id'),),
        ).fetchone()
    if issue:
        reason_labels = {
            'no_unique_url_match': '历史关联缺失',
            'multiple_url_matches': '历史关联存在多个候选检查项',
            'existing_association_conflict': '历史关联与现有归属冲突',
        }
        result.update({
            'association_status': 'migration_issue',
            'association_issue_code': issue['reason'],
            'association_issue_label': reason_labels.get(issue['reason'], '历史关联异常'),
            'association_candidate_item_ids': json.loads(issue['candidate_item_ids'] or '[]'),
        })
    result.update(_attachment_status_payload(attachment))
    return result


def _decorate_attachment(db, attachment):
    result = dict(attachment)
    if result.get('uploader_real_name'):
        result['uploader_name'] = result['uploader_real_name']
    result.update(_attachment_presentation(db, result))
    result.pop('uploader_real_name', None)
    return result


def _actionable_evidence_issue_sql(alias='oa'):
    """SQL predicate for qualification issues that still require an action."""
    return (
        f"COALESCE({alias}.is_deleted, 0)=0 "
        f"AND COALESCE({alias}.review_status, 'pending') NOT IN ('rejected', 'voided', 'superseded') "
        f"AND COALESCE({alias}.evidence_qualification, 'review') != 'qualified' "
        f"AND COALESCE(json_extract(CASE WHEN json_valid({alias}.extra_json) "
        f"THEN {alias}.extra_json ELSE '{{}}' END, '$.material_role'),'formal')!='supplement'"
    )


def _current_attachment_archive_sql(db, alias='oa', require_primary_file=False):
    """Return the authoritative predicate for current business evidence."""
    source = f'{alias}.source_type'
    source_id = f'{alias}.source_id'
    site_id = f'{alias}.site_id'
    associations = []

    if _table_exists(db, 'insp_plan_items'):
        checks = [f'i.id={source_id}', f'i.site_id={site_id}']
        if _table_has_column(db, 'operation_attachments', 'item_id'):
            checks.append(f'({alias}.item_id IS NULL OR {alias}.item_id=i.id)')
        if (_table_has_column(db, 'operation_attachments', 'plan_id')
                and _table_has_column(db, 'insp_plan_items', 'plan_id')):
            checks.append(f'({alias}.plan_id IS NULL OR {alias}.plan_id=i.plan_id)')
        associations.append(
            f"({source}='inspection' AND EXISTS (SELECT 1 FROM insp_plan_items i "
            f"WHERE {' AND '.join(checks)}))"
        )
    if _table_exists(db, 'work_orders'):
        associations.append(
            f"({source}='workorder' AND EXISTS (SELECT 1 FROM work_orders w "
            f"WHERE w.id={source_id} AND w.site_id={site_id}))"
        )
    if _table_exists(db, 'sites'):
        associations.append(
            f"({source}='calibration' AND EXISTS (SELECT 1 FROM sites s "
            f"WHERE s.id={source_id} AND s.id={site_id}))"
        )
    if _table_exists(db, 'reagent_records'):
        associations.append(
            f"({source}='reagent' AND EXISTS (SELECT 1 FROM reagent_records r "
            f"WHERE r.id={source_id} AND r.site_id={site_id}))"
        )
    if _table_exists(db, 'device_shadows'):
        associations.append(
            f"({source}='maintenance' AND EXISTS (SELECT 1 FROM device_shadows d "
            f"WHERE d.id={source_id} AND d.site_id={site_id}))"
        )
    if _table_exists(db, 'vehicle_maintenance_records'):
        associations.append(
            f"({source}='vehicle' AND {alias}.category='养护记录' AND EXISTS "
            f"(SELECT 1 FROM vehicle_maintenance_records vm WHERE vm.id={source_id}))"
        )
    if _table_exists(db, 'vehicle_refueling_records'):
        associations.append(
            f"({source}='vehicle' AND {alias}.category='车辆加油' AND EXISTS "
            f"(SELECT 1 FROM vehicle_refueling_records vr WHERE vr.id={source_id}))"
        )
    if _table_exists(db, 'manual_reports'):
        associations.append(
            f"({source}='manual_report' AND EXISTS (SELECT 1 FROM manual_reports mr "
            f"WHERE mr.id={source_id} AND mr.site_id={site_id}))"
        )

    association_sql = ' OR '.join(associations) if associations else '0'
    primary_file_sql = (
        f' AND archive_primary_file_exists({alias}.stored_path)=1'
        if require_primary_file else ''
    )
    return f"""(
        COALESCE({alias}.is_deleted,0)=0
        AND COALESCE({alias}.review_status,'pending')='approved'
        AND COALESCE({alias}.evidence_qualification,'review')='qualified'
        AND COALESCE(json_extract(CASE WHEN json_valid({alias}.extra_json)
            THEN {alias}.extra_json ELSE '{{}}' END, '$.material_role'),'formal')!='supplement'
        AND ({association_sql})
        {primary_file_sql}
    )"""


def _item_attachment_history(db, item):
    """Return item-owned evidence, including voided rows for history views.

    The attachment row is the durable association.  The item's photo_urls is a
    compatibility projection and must not be used to reconstruct a voided link.
    """
    item_id = item['id'] if item else None
    if not item_id or not _table_exists(db, 'operation_attachments'):
        return [], []
    attachment_columns = {
        row['name'] for row in db.execute('PRAGMA table_info(operation_attachments)').fetchall()
    }
    item_plan_id = item['plan_id'] if 'plan_id' in item.keys() else None
    item_site_id = item['site_id'] if 'site_id' in item.keys() else None
    link_terms = []
    params = []
    if 'item_id' in attachment_columns:
        link_terms.append("""(oa.item_id=? AND oa.site_id=?
            AND (oa.plan_id IS NULL OR oa.plan_id=0 OR oa.plan_id=?))"""
                          if 'plan_id' in attachment_columns
                          else "(oa.item_id=? AND oa.site_id=?)")
        params.extend((item_id, item_site_id))
        if 'plan_id' in attachment_columns:
            params.append(item_plan_id)
    link_terms.append("""(oa.source_type='inspection' AND oa.source_id=? AND oa.site_id=?
        AND (oa.plan_id IS NULL OR oa.plan_id=0 OR oa.plan_id=?))"""
                      if 'plan_id' in attachment_columns
                      else "(oa.source_type='inspection' AND oa.source_id=? AND oa.site_id=?)")
    params.extend((item_id, item_site_id))
    if 'plan_id' in attachment_columns:
        params.append(item_plan_id)
    if 'extra_json' in attachment_columns and item_plan_id is not None:
        link_terms.append("""(oa.source_type IN ('inspection','site_photo') AND oa.site_id=?
            AND json_valid(oa.extra_json)
            AND CAST(json_extract(oa.extra_json,'$.plan_id') AS INTEGER)=?
            AND CAST(json_extract(oa.extra_json,'$.item_id') AS INTEGER)=?
            AND COALESCE(json_extract(oa.extra_json,'$.material_role'),'formal')!='pending_inspection')""")
        params.extend((item_site_id, item_plan_id, item_id))
    rows = db.execute("""
        SELECT oa.*, s.name AS site_name,
               COALESCE(oa.uploader_name, u.real_name, '') AS uploader_real_name
        FROM operation_attachments oa
        LEFT JOIN sites s ON s.id=oa.site_id
        LEFT JOIN users u ON u.id=oa.uploader_id
        WHERE (""" + ' OR '.join(link_terms) + """)
          AND COALESCE(oa.is_deleted, 0)=0
        ORDER BY oa.created_at ASC, oa.id ASC
    """, params).fetchall()
    all_rows = [_decorate_attachment(db, row) for row in rows]
    if _table_exists(db, 'attachment_void_audits'):
        for row in all_rows:
            if row.get('review_status') == 'voided':
                audit = db.execute(
                    'SELECT * FROM attachment_void_audits WHERE attachment_id=?', (row['id'],)
                ).fetchone()
                row['void_audit'] = dict(audit) if audit else None
    effective = [row for row in all_rows if row.get('is_effective_evidence')]
    return all_rows, effective


@app.route('/api/attachments', methods=['GET'])
def list_attachments():
    """影像档案列表，支持多维筛选"""
    site_id = request.args.get('site_id', type=int)
    source_type = request.args.get('source_type')
    business_type = request.args.get('business_type')
    source_id = request.args.get('source_id', type=int)
    category = request.args.get('category')
    uploader = request.args.get('uploader')
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')
    upload_date_from = request.args.get('upload_date_from')
    upload_date_to = request.args.get('upload_date_to')
    evidence_issue = request.args.get('evidence_issue') == '1'
    keyword = request.args.get('keyword')
    archived = request.args.get('archived')  # '0' / '1' / None(全部)
    review_status = request.args.get('review_status')
    include_voided = request.args.get('include_voided') == '1'
    current_archive = request.args.get('current_archive') == '1'
    history_archive = request.args.get('history_archive') == '1'
    page = request.args.get('page', 1, type=int)
    limit = request.args.get('limit', 30, type=int)
    offset = (page - 1) * limit

    with get_db() as db:
        db.create_function('archive_primary_file_exists', 1, _attachment_primary_file_exists)
        current_archive_sql = _current_attachment_archive_sql(
            db, 'oa', require_primary_file=True)
        # History is the exact complement of the current archive, including
        # soft-deleted records. Other attachment queries keep hiding deletions.
        where = [] if history_archive else ["COALESCE(oa.is_deleted,0)=0"]
        non_date_where = list(where)
        if not history_archive and not include_voided and review_status != 'voided':
            where.append("COALESCE(oa.review_status, 'pending')!='voided'")
        params = []
        if current_archive:
            where.append(current_archive_sql)
        elif history_archive:
            where.append(f'NOT {current_archive_sql}')
        if site_id:
            where.append("oa.site_id=?"); params.append(site_id)
        if source_type:
            where.append("oa.source_type=?"); params.append(source_type)
        if business_type:
            business_sql, business_params = _attachment_business_filter(business_type)
            if not business_sql:
                return jsonify({'error': '无效的业务归属'}), 400
            where.append(business_sql)
            params.extend(business_params)
        if source_id:
            where.append("oa.source_id=?"); params.append(source_id)
        if category:
            where.append("oa.category=?"); params.append(category)
        if uploader:
            where.append("oa.uploader_name LIKE ?"); params.append(f'%{uploader}%')
        non_date_where = list(where)
        non_date_params = list(params)
        if date_from:
            where.append("oa.evidence_qualification='qualified' AND oa.taken_at>=?"); params.append(date_from)
        if date_to:
            where.append("oa.evidence_qualification='qualified' AND oa.taken_at<=?"); params.append(date_to + ' 23:59:59')
        if upload_date_from:
            where.append("oa.created_at>=?"); params.append(upload_date_from)
            non_date_where.append("oa.created_at>=?"); non_date_params.append(upload_date_from)
        if upload_date_to:
            upload_date_end = upload_date_to + ' 23:59:59'
            where.append("oa.created_at<=?"); params.append(upload_date_end)
            non_date_where.append("oa.created_at<=?"); non_date_params.append(upload_date_end)
        if evidence_issue:
            where.append(_actionable_evidence_issue_sql('oa'))
        if keyword:
            keyword_columns = ['description', 'filename']
            for optional_column in ('item_name', 'archive_name', 'category'):
                if _table_has_column(db, 'operation_attachments', optional_column):
                    keyword_columns.append(optional_column)
            keyword_sql = '(' + ' OR '.join(f'oa.{column} LIKE ?' for column in keyword_columns) + ')'
            keyword_params = [f'%{keyword}%'] * len(keyword_columns)
            where.append(keyword_sql)
            params.extend(keyword_params)
            non_date_where.append(keyword_sql)
            non_date_params.extend(keyword_params)
        if archived in ('0', '1'):
            where.append("oa.archived=?")
            params.append(int(archived))
            non_date_where.append("oa.archived=?")
            non_date_params.append(int(archived))
        if review_status:
            where.append("oa.review_status=?")
            params.append(review_status)
            non_date_where.append("oa.review_status=?")
            non_date_params.append(review_status)

        # 范围隔离：操作员仅见本人站点影像。站点为 0/NULL 视为未绑定资料（多为测试/种子数据），
        # 不展示给受限角色，避免跨站点照片泄露；仅管理员/经理（scope=None）可见全部。
        scope = _filter_site_ids()
        if scope is not None:
            if not scope:
                return jsonify({'total': 0, 'page': page, 'limit': limit, 'items': []})
            where.append("oa.site_id IN (%s)" % ','.join('?' * len(scope)))
            params.extend(scope)
            non_date_where.append("oa.site_id IN (%s)" % ','.join('?' * len(scope)))
            non_date_params.extend(scope)

        where_sql = ' AND '.join(where) if where else '1=1'
        total = db.execute(f"SELECT COUNT(*) FROM operation_attachments oa WHERE {where_sql}", params).fetchone()[0]
        issue_count = 0 if current_archive else db.execute(
            f"SELECT COUNT(*) FROM operation_attachments oa WHERE {' AND '.join(non_date_where)} "
            f"AND {_actionable_evidence_issue_sql('oa')}",
            non_date_params).fetchone()[0]
        rows = db.execute(f"""
            SELECT oa.*, s.name as site_name, u.real_name AS uploader_real_name,
                   w.order_no AS order_no
            FROM operation_attachments oa
            LEFT JOIN sites s ON oa.site_id=s.id
            LEFT JOIN users u ON oa.uploader_id=u.id
            LEFT JOIN work_orders w ON oa.source_type='workorder' AND w.id=oa.source_id
            WHERE {where_sql}
            ORDER BY oa.created_at DESC LIMIT ? OFFSET ?
        """, params + [limit, offset]).fetchall()

        result = []
        for r in rows:
            result.append(_decorate_attachment(db, r))
        return jsonify({
            'total': total,
            'page': page,
            'limit': limit,
            'items': result,
            'evidence_issue_count': issue_count,
        })


@app.route('/api/attachments', methods=['POST'])
def create_attachment():
    """手动创建附件记录（配合已有图片路径使用）"""
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '审核角色不能创建现场影像'}), 403
    data = request.get_json(silent=True) or {}
    required = ['filename', 'stored_path']
    source_type = str(data.get('source_type') or '').strip().lower()
    source_id = data.get('source_id')
    inspection_item = None
    if source_type == 'inspection' and source_id not in (None, '', 0, '0'):
        with get_db() as db:
            item = db.execute(
                'SELECT id, plan_id, site_id, item_name, category FROM insp_plan_items WHERE id=?',
                (source_id,),
            ).fetchone()
            if not item:
                return jsonify({'error': '检查项不存在，不能伪造影像归属', 'code': 'INSPECTION_ITEM_NOT_FOUND'}), 404
            if data.get('site_id') not in (None, '', item['site_id']):
                return jsonify({'error': '影像站点与检查项不一致', 'code': 'INSPECTION_SITE_MISMATCH'}), 400
            data['source_id'] = item['id']
            data['site_id'] = item['site_id']
            data['description'] = item['item_name'] or data.get('description') or ''
            data['category'] = item['category'] or data.get('category') or '巡检现场照片'
            inspection_item = dict(item)
            data['extra_json'] = json.dumps({
                'plan_id': item['plan_id'], 'item_id': item['id'],
                'item_name': item['item_name'] or '',
                'classification_source': 'inspection_item',
            }, ensure_ascii=False)
    elif source_type == 'inspection':
        return jsonify({'error': '巡检影像必须绑定具体检查项', 'code': 'INSPECTION_ITEM_REQUIRED'}), 400
    for f in required:
        if f not in data:
            return jsonify({'error': f'缺少必填字段: {f}'}), 400
    if not _has_any_role(g.current_user, 'admin'):
        denied = _site_access_denied(data.get('site_id'), '添加影像到')
        if denied:
            return denied
        data['uploader_id'] = g.current_user['id']
        data['uploader_name'] = g.current_user.get('real_name') or ''
    with get_db() as db:
        db.execute("""INSERT INTO operation_attachments
            (filename, stored_path, thumbnail_path, file_type, mime_type, file_size,
             description, source_type, source_id, site_id, uploader_id, uploader_name,
             gps_lat, gps_lng, taken_at, category)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (data['filename'], data['stored_path'], data.get('thumbnail_path',''),
             data.get('file_type','image'), data.get('mime_type',''), data.get('file_size',0),
             data.get('description',''), data.get('source_type',''), data.get('source_id',0),
             data.get('site_id'), g.current_user.get('id'), _current_actor_name('未知用户'),
             data.get('gps_lat'), data.get('gps_lng'), data.get('taken_at'),
             data.get('category','')))
        if inspection_item:
            _persist_inspection_attachment_link(db, db.execute("SELECT last_insert_rowid()").fetchone()[0], inspection_item)
        db.commit()
        aid = db.execute("SELECT last_insert_rowid()").fetchone()[0]
    return jsonify({'success': True, 'id': aid})


@app.route('/api/attachments/<int:aid>')
def get_attachment(aid):
    """获取单个附件详情"""
    with get_db() as db:
        row = db.execute("""
            SELECT oa.*, s.name as site_name, w.order_no AS order_no
            FROM operation_attachments oa
            LEFT JOIN sites s ON oa.site_id=s.id
            LEFT JOIN work_orders w ON oa.source_type='workorder' AND w.id=oa.source_id
            WHERE oa.id=? AND oa.is_deleted=0
        """, (aid,)).fetchone()
        if not row:
            return jsonify({'error': '附件不存在'}), 404
        denied = _site_access_denied(row['site_id'])
        if denied:
            return denied
        result = _decorate_attachment(db, row)
        if result.get('review_status') == 'voided' and _table_exists(db, 'attachment_void_audits'):
            audit = db.execute(
                'SELECT * FROM attachment_void_audits WHERE attachment_id=?', (aid,)
            ).fetchone()
            result['void_audit'] = dict(audit) if audit else None
        return jsonify(result)


