@app.route('/api/attachments/<int:aid>', methods=['PUT'])
def update_attachment(aid):
    """更新附件元信息（描述、分类等）"""
    denied = require_admin()
    if denied:
        return denied
    data = request.json
    allowed = ['description', 'category', 'source_type', 'source_id', 'site_id']
    with get_db() as db:
        existing = db.execute("SELECT id FROM operation_attachments WHERE id=? AND is_deleted=0", (aid,)).fetchone()
        if not existing:
            return jsonify({'error': '附件不存在'}), 404
        updates = []
        params = []
        for key in allowed:
            if key in data:
                updates.append(f"{key}=?")
                params.append(data[key])
        if updates:
            params.append(aid)
            db.execute(f"UPDATE operation_attachments SET {','.join(updates)} WHERE id=?", params)
            db.commit()
    return jsonify({'success': True})


ATTACHMENT_DELETE_FORMAL_SOURCE_TYPES = frozenset({
    'workorder', 'inspection', 'patrol', 'site_photo',
    'calibration', 'reagent', 'vehicle', 'maintenance', 'manual_report',
})
ATTACHMENT_DELETE_BLOCKED_MESSAGE = '该影像已作为业务证据，不能删除'


def _positive_business_id(value):
    """Return a positive persisted business identifier, never a sentinel 0."""
    try:
        return int(value) if int(value) > 0 else None
    except (TypeError, ValueError):
        return None


def _attachment_delete_related_rows(db, attachment):
    """Read stored business links for deletion safety; never trust DELETE payload fields."""
    stored_path = (attachment.get('stored_path') or '').strip()
    source_type = (attachment.get('source_type') or '').strip().lower()
    source_id = _positive_business_id(attachment.get('source_id'))
    inspection_items = []
    workorder_links = []

    if _table_exists(db, 'insp_plan_items'):
        item_columns = {row['name'] for row in db.execute('PRAGMA table_info(insp_plan_items)').fetchall()}
        if 'photo_urls' in item_columns:
            if source_type == 'inspection' and source_id:
                rows = db.execute(
                    'SELECT * FROM insp_plan_items WHERE id=?', (source_id,)
                ).fetchall()
            elif stored_path and not (source_type == 'test' and source_id is None):
                rows = db.execute(
                    'SELECT * FROM insp_plan_items WHERE photo_urls LIKE ?', ('%' + stored_path + '%',)
                ).fetchall()
            else:
                rows = []
            for row in rows:
                item = dict(row)
                plan_status = ''
                if item.get('plan_id') and _table_exists(db, 'insp_plans'):
                    plan = db.execute('SELECT * FROM insp_plans WHERE id=?', (item['plan_id'],)).fetchone()
                    plan_status = (dict(plan).get('status') or '').lower() if plan else ''
                item['_plan_status'] = plan_status
                inspection_items.append(item)

    if _table_exists(db, 'work_orders'):
        order_columns = {row['name'] for row in db.execute('PRAGMA table_info(work_orders)').fetchall()}
        clauses = []
        params = []
        if source_type == 'workorder' and source_id:
            clauses.append('id=?')
            params.append(source_id)
        if stored_path and 'images' in order_columns and not (source_type == 'test' and source_id is None):
            clauses.append('images LIKE ?')
            params.append('%' + stored_path + '%')
        if clauses:
            workorder_links = [dict(row) for row in db.execute(
                f"SELECT * FROM work_orders WHERE {' OR '.join(clauses)}", params
            ).fetchall()]

    return inspection_items, workorder_links


def _attachment_delete_check(db, attachment):
    """Return the server-owned eligibility decision and the user-facing impact."""
    source_type = (attachment.get('source_type') or '').strip().lower()
    source_id = _positive_business_id(attachment.get('source_id'))
    inspection_items, workorder_links = _attachment_delete_related_rows(db, attachment)

    formal_inspection = False
    for item in inspection_items:
        review_status = str(item.get('review_status') or '').lower()
        plan_status = item.get('_plan_status') or ''
        if review_status in {'1', '2', '3', 'pending', 'approved', 'rejected', 'reviewed'} \
                or plan_status in {'submitted', 'approved', 'reviewing', 'completed', 'archived', 'closed'} \
                or item.get('submitted_at'):
            formal_inspection = True
            break

    if source_type in ATTACHMENT_DELETE_FORMAL_SOURCE_TYPES or workorder_links or formal_inspection:
        return {
            'can_delete': False,
            'block_reason': ATTACHMENT_DELETE_BLOCKED_MESSAGE,
            'impact': '这是正式业务证据，删除会破坏巡检、审核或工单闭环，服务端已阻止操作。',
            'inspection_items': inspection_items,
        }

    # Only an explicit test classification with no stored business id is removable.
    # Blank/unknown source values are intentionally not inferred as test data.
    if source_type != 'test' or source_id is not None:
        return {
            'can_delete': False,
            'block_reason': '仅明确标记为测试/误传且未绑定正式业务的影像可以删除',
            'impact': '当前影像没有满足受控删除条件，未对任何数据做修改。',
            'inspection_items': inspection_items,
        }

    draft_warning = ''
    if inspection_items:
        draft_warning = '删除后关联的未提交检查项可能出现照片不足；检查记录不会删除，物理文件也不会清理。'
    return {
        'can_delete': True,
        'block_reason': '',
        'impact': draft_warning or '仅从正常影像档案、统计和待审提醒中移除；不删除物理文件、消息历史或业务记录。',
        'inspection_items': inspection_items,
    }


def _attachment_delete_response_row(row):
    item = dict(row)
    if item.get('uploader_real_name'):
        item['uploader_name'] = item['uploader_real_name']
    item.pop('uploader_real_name', None)
    return item


def _sync_attachment_review_notifications_after_delete(db, site_id, attachment_id):
    """Retire stale photo reminders and rebuild the current site batch when needed."""
    if not site_id or not _table_exists(db, 'notifications') \
            or not _table_has_column(db, 'notifications', 'is_read'):
        return
    pending = db.execute("""SELECT id FROM operation_attachments
        WHERE site_id=? AND is_deleted=0 AND review_required=1
          AND (review_status='pending' OR review_status IS NULL)
          AND source_type!='workorder' ORDER BY id""", (site_id,)).fetchall()
    if pending:
        _notify_attachment_reviewers(db, site_id, pending[0]['id'], '')
        return
    db.execute("""UPDATE notifications SET is_read=1
        WHERE is_read=0 AND source_type='attachment_review'
          AND (source_id=? OR source_id IN (
              SELECT id FROM operation_attachments WHERE site_id=?
          ))""", (attachment_id, site_id))
    db.execute("""UPDATE notifications SET is_read=1
        WHERE is_read=0 AND source_type='attachment_review_batch' AND source_id=?""", (site_id,))


@app.route('/api/attachments/<int:aid>/delete-check')
def attachment_delete_check(aid):
    denied = require_admin()
    if denied:
        return denied
    with get_db() as db:
        row = db.execute("""SELECT oa.*, s.name AS site_name,
                                  COALESCE(oa.uploader_name, u.real_name, '') AS uploader_real_name
                           FROM operation_attachments oa
                           LEFT JOIN sites s ON oa.site_id=s.id
                           LEFT JOIN users u ON oa.uploader_id=u.id
                           WHERE oa.id=? AND oa.is_deleted=0""", (aid,)).fetchone()
        if not row:
            return jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404
        attachment = _attachment_delete_response_row(row)
        decision = _attachment_delete_check(db, attachment)
        attachment.update({key: value for key, value in decision.items() if key != 'inspection_items'})
        attachment['inspection_item_ids'] = [item.get('id') for item in decision['inspection_items']]
        return jsonify(attachment)


@app.route('/api/attachments/<int:aid>', methods=['DELETE'])
def delete_attachment(aid):
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    reason = data.get('reason', '')
    if not isinstance(reason, str):
        reason = str(reason or '')
    reason = reason.strip()
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        row = db.execute("""SELECT oa.*, s.name AS site_name,
                                  COALESCE(oa.uploader_name, u.real_name, '') AS uploader_real_name
                           FROM operation_attachments oa
                           LEFT JOIN sites s ON oa.site_id=s.id
                           LEFT JOIN users u ON oa.uploader_id=u.id
                           WHERE oa.id=?""", (aid,)).fetchone()
        if not row:
            return jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404
        if row['is_deleted']:
            return jsonify({
                'success': True,
                'already_deleted': True,
                'code': 'ATTACHMENT_ALREADY_DELETED',
                'message': '影像已删除',
            })
        if not reason:
            return jsonify({'success': False, 'error': '删除原因不能为空', 'code': 'DELETE_REASON_REQUIRED'}), 400
        if len(reason) > 200:
            return jsonify({'success': False, 'error': '删除原因不能超过200字', 'code': 'DELETE_REASON_TOO_LONG'}), 400

        attachment = _attachment_delete_response_row(row)
        decision = _attachment_delete_check(db, attachment)
        if not decision['can_delete']:
            return jsonify({
                'success': False,
                'error': decision['block_reason'],
                'code': 'ATTACHMENT_DELETE_BLOCKED',
                'impact': decision['impact'],
            }), 409

        deleted_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        before_state = dict(attachment)
        changed = db.execute("""UPDATE operation_attachments
            SET is_deleted=1, deleted_at=?, deleted_by=?, delete_reason=?
            WHERE id=? AND is_deleted=0""", (
                deleted_at, g.current_user.get('id'), reason, aid,
        ))
        if changed.rowcount != 1:
            return jsonify({
                'success': True,
                'already_deleted': True,
                'code': 'ATTACHMENT_ALREADY_DELETED',
                'message': '影像已删除',
            })

        operator_name = _current_actor_name()
        if _table_exists(db, 'attachment_deletion_audits'):
            db.execute("""INSERT INTO attachment_deletion_audits
                (attachment_id, original_filename, original_stored_path,
                 source_type, source_id, site_id, operator_id, operator_name,
                 reason, deleted_at, delete_before_state)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)""", (
                aid, attachment.get('filename') or '', attachment.get('stored_path') or '',
                attachment.get('source_type') or '', attachment.get('source_id'),
                attachment.get('site_id'), g.current_user.get('id'), operator_name,
                reason, deleted_at, json.dumps(before_state, ensure_ascii=False, sort_keys=True),
            ))
        if _table_exists(db, 'operation_logs'):
            db.execute("""INSERT INTO operation_logs
                (module, action, target_type, target_id, operator, operator_id, details)
                VALUES (?,?,?,?,?,?,?)""", (
                'attachment', 'soft_delete', 'attachment', aid, operator_name,
                g.current_user.get('id'), json.dumps({
                    'attachment_id': aid,
                    'original_filename': attachment.get('filename') or '',
                    'original_stored_path': attachment.get('stored_path') or '',
                    'source_type': attachment.get('source_type') or '',
                    'source_id': attachment.get('source_id'),
                    'site_id': attachment.get('site_id'),
                    'operator_id': g.current_user.get('id'),
                    'operator_name': operator_name,
                    'reason': reason,
                    'deleted_at': deleted_at,
                    'delete_before_state': before_state,
                }, ensure_ascii=False, sort_keys=True),
            ))
        _sync_attachment_review_notifications_after_delete(db, attachment.get('site_id'), aid)
        db.commit()
    return jsonify({
        'success': True,
        'deleted': True,
        'id': aid,
        'message': '已移出影像档案，物理文件未删除',
    })
def _attachment_purge_active_roles(db, user_id):
    columns = _ps_purge_table_columns(db, 'users')
    if not {'id', 'role'}.issubset(columns):
        return set()
    selected = ['role'] + (['status'] if 'status' in columns else [])
    user = db.execute(f"SELECT {','.join(selected)} FROM users WHERE id=?", (user_id,)).fetchone()
    if not user or ('status' in user.keys() and user['status'] != 'active'):
        return set()
    roles = []
    if {'user_id', 'role'}.issubset(_ps_purge_table_columns(db, 'user_roles')):
        roles = [row['role'] for row in db.execute(
            'SELECT role FROM user_roles WHERE user_id=?', (user_id,)).fetchall()]
    return set(_normalize_user_roles(roles or [user['role']], user['role']))


def _attachment_purge_urls(raw_value):
    try:
        values = json.loads(raw_value or '[]')
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    return values if isinstance(values, list) else []


def _attachment_upload_target(stored_path):
    path = str(stored_path or '')
    if not path.startswith('/uploads/'):
        raise OSError('attachment path is outside upload namespace')
    root = os.path.realpath(os.path.abspath(UPLOAD_DIR))
    target = os.path.realpath(os.path.abspath(os.path.join(
        UPLOAD_DIR, path[len('/uploads/'):].replace('/', os.sep))))
    try:
        inside_root = os.path.normcase(os.path.commonpath((root, target))) == os.path.normcase(root)
    except ValueError:
        inside_root = False
    if not inside_root:
        raise OSError('attachment path escapes upload root')
    return target


def _attachment_primary_file_exists(stored_path):
    try:
        target = _attachment_upload_target(stored_path)
    except OSError:
        return 0
    return int(os.path.isfile(target))


def _attachment_purge_physical_plan(db, attachment, aid, excluded_ids=None):
    columns = _ps_purge_table_columns(db, 'operation_attachments')
    targets = []
    paths = set()
    shared = False
    for column in ('stored_path', 'thumbnail_path'):
        if column not in columns:
            continue
        path = str(attachment.get(column) or '')
        if not path or path in paths:
            continue
        target = _attachment_upload_target(path)
        paths.add(path)
        reference_columns = [name for name in ('stored_path', 'thumbnail_path') if name in columns]
        reference_sql = ' OR '.join(f'{name}=?' for name in reference_columns)
        excluded = sorted({_positive_business_id(value) for value in (excluded_ids or [aid])}
                          - {None})
        exclusion_sql = f"id NOT IN ({','.join('?' for _ in excluded)})" if excluded else 'id!=?'
        exclusion_params = excluded or [aid]
        referenced = db.execute(
            f'SELECT 1 FROM operation_attachments WHERE {exclusion_sql} AND ({reference_sql}) LIMIT 1',
            (*exclusion_params, *([path] * len(reference_columns)))).fetchone()
        if referenced:
            shared = True
            continue
        if not os.path.exists(target):
            continue
        if not os.path.isfile(target):
            raise OSError('attachment target is not a regular file')
        targets.append(target)
    return sorted(targets), shared


def _attachment_purge_physical_backups(db, attachment, aid, excluded_ids=None):
    targets, shared = _attachment_purge_physical_plan(db, attachment, aid, excluded_ids)
    backups = []
    for target in targets:
        with open(target, 'rb') as handle:
            backups.append((target, handle.read()))
    return backups, shared


ATTACHMENT_PURGE_BATCH_LIMIT = 50


def _attachment_purge_batch_ids(payload):
    raw_ids = payload.get('attachment_ids')
    if not isinstance(raw_ids, list) or not raw_ids:
        return None, ('请选择至少一条历史影像', 'ATTACHMENT_PURGE_BATCH_EMPTY', 400)
    normalized = []
    for raw_id in raw_ids:
        aid = _positive_business_id(raw_id)
        if aid is None:
            return None, ('影像编号无效，请刷新后重试', 'ATTACHMENT_PURGE_BATCH_ID_INVALID', 400)
        if aid not in normalized:
            normalized.append(aid)
    if len(normalized) > ATTACHMENT_PURGE_BATCH_LIMIT:
        return None, (
            f'单次最多清理 {ATTACHMENT_PURGE_BATCH_LIMIT} 条，请减少选择后重试',
            'ATTACHMENT_PURGE_BATCH_LIMIT_EXCEEDED', 400)
    return sorted(normalized), None


def _attachment_purge_batch_preview(db, attachment_ids):
    rows = db.execute(
        f"SELECT * FROM operation_attachments WHERE id IN ({','.join('?' for _ in attachment_ids)})",
        attachment_ids,
    ).fetchall()
    by_id = {int(row['id']): dict(row) for row in rows}
    items = []
    for aid in attachment_ids:
        attachment = by_id.get(aid)
        if not attachment:
            items.append({
                'attachment_id': aid, 'can_purge': False,
                'block_reason': '影像不存在或已被清理', 'shared_file_retained': False,
            })
            continue
        decision = _archive_attachment_purge_decision(db, attachment)
        shared_file = False
        if decision['can_purge']:
            try:
                _, shared_file = _attachment_purge_physical_plan(
                    db, attachment, aid, excluded_ids=attachment_ids)
            except OSError:
                decision = {
                    'can_purge': False,
                    'block_reason': '物理文件不在允许的上传目录内，不能自动清理',
                    'impact': '记录和物理文件均未改变。',
                }
        items.append({
            'attachment_id': aid,
            'can_purge': bool(decision['can_purge']),
            'block_reason': decision.get('block_reason') or '',
            'qualification_reason': decision.get('qualification_reason') or '',
            'shared_file_retained': shared_file,
        })
    purgeable_count = sum(1 for item in items if item['can_purge'])
    return {
        'requested_count': len(attachment_ids),
        'purgeable_count': purgeable_count,
        'blocked_count': len(attachment_ids) - purgeable_count,
        'can_purge': purgeable_count == len(attachment_ids),
        'batch_limit': ATTACHMENT_PURGE_BATCH_LIMIT,
        'items': items,
    }, by_id


def _attachment_purge_stage_files(targets, batch_id):
    staged = []
    try:
        for index, target in enumerate(sorted(set(targets))):
            temporary = f'{target}.purge-{batch_id}-{index}.tmp'
            if os.path.exists(temporary):
                raise OSError('attachment purge staging target already exists')
            os.replace(target, temporary)
            staged.append((target, temporary))
        return staged
    except OSError:
        for target, temporary in reversed(staged):
            if os.path.exists(temporary):
                os.replace(temporary, target)
        raise


def _attachment_purge_restore_staged(staged):
    for target, temporary in reversed(staged):
        if os.path.exists(temporary):
            os.replace(temporary, target)


def _attachment_purge_discard_staged(staged):
    for _, temporary in staged:
        try:
            os.remove(temporary)
        except FileNotFoundError:
            pass


def _archive_attachment_purge_decision(db, attachment):
    """Authorize irreversible archive cleanup from current server facts only."""
    aid = int(attachment.get('id') or 0)
    decorated = _decorate_attachment(db, attachment)
    current_sql = _current_attachment_archive_sql(db, 'oa')
    is_current_record = bool(db.execute(
        f'SELECT 1 FROM operation_attachments oa WHERE oa.id=? AND {current_sql}', (aid,)
    ).fetchone())
    primary_file_exists = bool(_attachment_primary_file_exists(decorated.get('stored_path')))
    status = str(decorated.get('review_status') or 'pending').strip().lower()
    try:
        metadata = json.loads(decorated.get('extra_json') or '{}')
    except (TypeError, ValueError, json.JSONDecodeError):
        metadata = {}
    material_role = str(metadata.get('material_role') or 'formal').strip().lower()

    if (status == 'pending' and material_role not in {'supplement'}
            and int(decorated.get('is_deleted') or 0) != 1):
        return {
            'can_purge': False,
            'block_reason': '正式待审证据尚未裁决，不能彻底清理',
            'impact': '记录和物理文件均未改变。请先完成所属业务审核。',
        }
    if is_current_record and primary_file_exists:
        return {
            'can_purge': False,
            'block_reason': '当前有效证据仍被业务使用，不能彻底清理',
            'impact': '记录和物理文件均未改变。请先按所属业务完成作废或替换。',
        }

    invalid_history = (
        int(decorated.get('is_deleted') or 0) == 1
        or status in {'rejected', 'voided', 'superseded'}
        or decorated.get('association_status') != 'linked'
        or str(decorated.get('evidence_qualification') or 'review').lower() != 'qualified'
        or material_role == 'supplement'
        or (is_current_record and not primary_file_exists)
    )
    if not invalid_history:
        return {
            'can_purge': False,
            'block_reason': '该记录尚未被服务端确认成可清理的无效历史影像',
            'impact': '记录和物理文件均未改变。',
        }
    if int(decorated.get('is_deleted') or 0) == 1:
        qualification_reason = '记录已移出正常档案，可清理残留记录和无人引用的文件'
    elif status in {'rejected', 'voided', 'superseded'}:
        qualification_reason = {
            'rejected': '内容审核已驳回，不再计入有效证据',
            'voided': '证据已作废，不再计入当前业务',
            'superseded': '证据已被替换，不再计入当前业务',
        }[status]
    elif decorated.get('association_status') != 'linked':
        qualification_reason = '来源或正式业务关联无效'
    elif str(decorated.get('evidence_qualification') or 'review').lower() != 'qualified':
        qualification_reason = '来源资格未通过，不计入有效证据'
    elif not primary_file_exists:
        qualification_reason = '主文件已缺失，不能继续作为当前有效证据'
    else:
        qualification_reason = '补充材料不进入正式证据审核'
    return {
        'can_purge': True,
        'block_reason': '',
        'qualification_reason': qualification_reason,
        'impact': '将删除影像记录；无其他记录引用时，同时删除上传目录内的物理文件。业务记录不会级联删除。',
    }


def _archive_attachment_remove_compatibility_urls(db, attachment):
    """Remove purged paths from compatibility projections without deleting business rows."""
    target_path = _attachment_storage_path(attachment.get('stored_path'))
    if not target_path:
        return
    inspection_items, workorder_links = _attachment_delete_related_rows(db, attachment)
    for item in inspection_items:
        urls = _attachment_purge_urls(item.get('photo_urls'))
        remaining = [value for value in urls if _attachment_storage_path(value) != target_path]
        if remaining == urls:
            continue
        columns = _ps_purge_table_columns(db, 'insp_plan_items')
        updates, params = [], []
        if 'photo_urls' in columns:
            updates.append('photo_urls=?'); params.append(json.dumps(remaining, ensure_ascii=False))
        if 'actual_photos' in columns:
            updates.append('actual_photos=?')
            params.append(_qualified_evidence_count(
                db, 'inspection', item.get('id'), stored_paths=remaining))
        if updates:
            params.append(item.get('id'))
            if db.execute(
                    f"UPDATE insp_plan_items SET {','.join(updates)} WHERE id=?", params
            ).rowcount != 1:
                raise sqlite3.IntegrityError('inspection attachment projection changed during purge')
    for order in workorder_links:
        raw_images = order.get('images')
        images = _attachment_purge_urls(raw_images)
        if not images:
            continue
        remaining = [value for value in images if _attachment_storage_path(value) != target_path]
        if remaining != images and db.execute(
                'UPDATE work_orders SET images=? WHERE id=?',
                (json.dumps(remaining, ensure_ascii=False), order.get('id'))
        ).rowcount != 1:
            raise sqlite3.IntegrityError('work order attachment projection changed during purge')


@app.route('/api/attachments/<int:aid>/purge', methods=['GET', 'POST'])
@login_required
def purge_archive_attachment(aid):
    """Preview or irreversibly purge one server-confirmed invalid historical attachment."""
    denied = require_admin()
    if denied:
        return denied
    is_preview = request.method == 'GET'
    payload = request.get_json(silent=True) or {}
    reason = str(payload.get('reason') or '').strip()
    if not is_preview:
        if not reason:
            return jsonify({'error': '清理原因不能为空', 'code': 'PURGE_REASON_REQUIRED'}), 400
        if len(reason) > 200:
            return jsonify({'error': '清理原因不能超过200字', 'code': 'PURGE_REASON_TOO_LONG'}), 400

    backups = []
    with get_db() as db:
        try:
            if not is_preview:
                db.execute('BEGIN IMMEDIATE')
                user_id = int(g.current_user.get('id') or 0)
                if 'admin' not in _attachment_purge_active_roles(db, user_id):
                    db.rollback()
                    return jsonify({
                        'error': '当前账号已不具备有效管理员权限，未执行清理',
                        'code': 'ATTACHMENT_PURGE_FORBIDDEN',
                    }), 403
            row = db.execute('SELECT * FROM operation_attachments WHERE id=?', (aid,)).fetchone()
            if not row:
                prior = db.execute("""SELECT remark FROM timeline_events
                    WHERE source_type='attachment_archive_purge' AND source_id=?
                      AND event_type='purged' ORDER BY id DESC LIMIT 1""", (aid,)).fetchone() \
                    if _table_exists(db, 'timeline_events') else None
                if prior and not is_preview:
                    db.rollback()
                    return jsonify({'success': True, 'attachment_id': aid, 'already_deleted': True})
                if not is_preview:
                    db.rollback()
                return jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404

            attachment = dict(row)
            decision = _archive_attachment_purge_decision(db, attachment)
            if not decision['can_purge']:
                if not is_preview:
                    db.rollback()
                    return jsonify({'error': decision['block_reason'], 'code': 'ATTACHMENT_PURGE_BLOCKED',
                                    'impact': decision['impact']}), 409
                return jsonify(dict(decision, attachment_id=aid))

            try:
                if is_preview:
                    physical_targets, shared_file = _attachment_purge_physical_plan(
                        db, attachment, aid)
                else:
                    backups, shared_file = _attachment_purge_physical_backups(
                        db, attachment, aid)
            except OSError:
                if not is_preview:
                    db.rollback()
                return jsonify({
                    'can_purge': False,
                    'attachment_id': aid,
                    'block_reason': '物理文件不在允许的上传目录内，不能自动清理',
                    'impact': '记录和物理文件均未改变。',
                    'code': 'ATTACHMENT_PURGE_PATH_BLOCKED',
                }), 409
            if is_preview:
                return jsonify(dict(
                    decision,
                    attachment_id=aid,
                    physical_file_count=len(physical_targets),
                    shared_file_retained=shared_file,
                    reason_required=True,
                ))

            for target, _ in backups:
                os.remove(target)
            _archive_attachment_remove_compatibility_urls(db, attachment)
            before_state = dict(attachment)
            summary = {
                'attachment_id': aid,
                'operator_id': g.current_user.get('id'),
                'operator_name': _current_actor_name(),
                'reason': reason,
                'deleted_at': datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
                'shared_file_retained': shared_file,
                'original_record': before_state,
            }
            if _table_exists(db, 'timeline_events'):
                db.execute("""INSERT INTO timeline_events
                    (source_type,source_id,event_type,operator,remark)
                    VALUES ('attachment_archive_purge',?,'purged',?,?)""",
                    (aid, summary['operator_name'], json.dumps(
                        summary, ensure_ascii=False, sort_keys=True, separators=(',', ':'))))
            if _table_exists(db, 'operation_logs'):
                db.execute("""INSERT INTO operation_logs
                    (module,action,target_type,target_id,operator,operator_id,details)
                    VALUES ('attachment','hard_purge','attachment',?,?,?,?)""",
                    (aid, summary['operator_name'], summary['operator_id'], json.dumps(
                        summary, ensure_ascii=False, sort_keys=True)))
            if _table_exists(db, 'notifications'):
                db.execute("""DELETE FROM notifications
                    WHERE source_type IN ('attachment_review','photo_review','attachment_void',
                                          'replacement_review') AND source_id=?""", (aid,))
            if db.execute('DELETE FROM operation_attachments WHERE id=?', (aid,)).rowcount != 1:
                raise sqlite3.IntegrityError('attachment changed during purge')
            db.commit()
            return jsonify({
                'success': True,
                'attachment_id': aid,
                'already_deleted': False,
                'shared_file_retained': shared_file,
            })
        except OSError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '影像文件删除失败，数据未发生变化，请重试',
                            'code': 'ATTACHMENT_PURGE_FILE_FAILED'}), 503
        except sqlite3.DatabaseError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '彻底清理未完成，数据未发生变化，请重试',
                            'code': 'ATTACHMENT_PURGE_FAILED'}), 503


