@app.route('/api/attachments/purge-batch', methods=['POST'])
@login_required
def purge_archive_attachment_batch():
    denied = require_admin()
    if denied:
        return denied
    payload = request.get_json(silent=True) or {}
    attachment_ids, error = _attachment_purge_batch_ids(payload)
    if error:
        message, code, status = error
        return jsonify({'error': message, 'code': code}), status
    reason = str(payload.get('reason') or '').strip()
    idempotency_key = str(payload.get('idempotency_key') or '').strip()
    if not reason:
        return jsonify({'error': '清理原因不能为空',
                        'code': 'ATTACHMENT_PURGE_BATCH_REASON_REQUIRED'}), 400
    if len(reason) > 200:
        return jsonify({'error': '清理原因不能超过200字',
                        'code': 'ATTACHMENT_PURGE_BATCH_REASON_TOO_LONG'}), 400
    if not idempotency_key or len(idempotency_key) > 160:
        return jsonify({'error': '批量请求标识无效，请重新确认后提交',
                        'code': 'ATTACHMENT_PURGE_BATCH_KEY_REQUIRED'}), 400
    request_hash = hashlib.sha256(json.dumps({
        'attachment_ids': attachment_ids, 'reason': reason,
    }, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
    staged = []
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
            user_id = int(g.current_user.get('id') or 0)
            if 'admin' not in _attachment_purge_active_roles(db, user_id):
                db.rollback()
                return jsonify({
                    'error': '当前账号已不具备有效管理员权限，未执行清理',
                    'code': 'ATTACHMENT_PURGE_BATCH_FORBIDDEN',
                }), 403
            replay = db.execute("""SELECT request_hash,response_json FROM attachment_purge_batches
                WHERE operator_id=? AND idempotency_key=?""", (user_id, idempotency_key)).fetchone()
            if replay:
                db.rollback()
                if replay['request_hash'] != request_hash:
                    return jsonify({
                        'error': '该批量请求标识已用于其他清理内容，请重新确认',
                        'code': 'ATTACHMENT_PURGE_BATCH_KEY_CONFLICT',
                    }), 409
                response = json.loads(replay['response_json'])
                response['idempotent_replay'] = True
                return jsonify(response)

            preview, attachments = _attachment_purge_batch_preview(db, attachment_ids)
            if not preview['can_purge']:
                db.rollback()
                return jsonify({
                    'error': '所选影像包含不可清理项，未执行任何清理',
                    'code': 'ATTACHMENT_PURGE_BATCH_BLOCKED',
                    **preview,
                }), 409

            physical_targets = []
            shared_by_id = {}
            for aid in attachment_ids:
                targets, shared_file = _attachment_purge_physical_plan(
                    db, attachments[aid], aid, excluded_ids=attachment_ids)
                physical_targets.extend(targets)
                shared_by_id[aid] = shared_file
            batch_id = f'APB-{datetime.now().strftime("%Y%m%d%H%M%S")}-{secrets.token_hex(4)}'
            staged = _attachment_purge_stage_files(physical_targets, batch_id)
            deleted_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
            operator_name = _current_actor_name()
            for aid in attachment_ids:
                attachment = attachments[aid]
                _archive_attachment_remove_compatibility_urls(db, attachment)
                summary = {
                    'attachment_id': aid,
                    'batch_id': batch_id,
                    'operator_id': user_id,
                    'operator_name': operator_name,
                    'reason': reason,
                    'deleted_at': deleted_at,
                    'shared_file_retained': shared_by_id[aid],
                    'original_record': dict(attachment),
                }
                if _table_exists(db, 'timeline_events'):
                    db.execute("""INSERT INTO timeline_events
                        (source_type,source_id,event_type,operator,remark)
                        VALUES ('attachment_archive_purge',?,'purged',?,?)""",
                        (aid, operator_name, json.dumps(
                            summary, ensure_ascii=False, sort_keys=True, separators=(',', ':'))))
                if _table_exists(db, 'operation_logs'):
                    db.execute("""INSERT INTO operation_logs
                        (module,action,target_type,target_id,operator,operator_id,details)
                        VALUES ('attachment','hard_purge_batch','attachment',?,?,?,?)""",
                        (aid, operator_name, user_id, json.dumps(
                            summary, ensure_ascii=False, sort_keys=True)))
                if _table_exists(db, 'notifications'):
                    db.execute("""DELETE FROM notifications
                        WHERE source_type IN ('attachment_review','photo_review','attachment_void',
                                              'replacement_review') AND source_id=?""", (aid,))
                if db.execute('DELETE FROM operation_attachments WHERE id=?', (aid,)).rowcount != 1:
                    raise sqlite3.IntegrityError('attachment changed during batch purge')

            response = {
                'success': True,
                'batch_id': batch_id,
                'purged_count': len(attachment_ids),
                'attachment_ids': attachment_ids,
                'shared_file_retained_count': sum(1 for value in shared_by_id.values() if value),
                'idempotent_replay': False,
            }
            db.execute("""INSERT INTO attachment_purge_batches
                (batch_id,operator_id,idempotency_key,request_hash,response_json)
                VALUES (?,?,?,?,?)""", (
                    batch_id, user_id, idempotency_key, request_hash,
                    json.dumps(response, ensure_ascii=False, sort_keys=True, separators=(',', ':')),
                ))
            db.commit()
            cleanup_pending = 0
            for _, temporary in staged:
                try:
                    os.remove(temporary)
                except FileNotFoundError:
                    pass
                except OSError:
                    cleanup_pending += 1
            response['temporary_cleanup_pending'] = cleanup_pending
            return jsonify(response)
        except OSError:
            db.rollback()
            _attachment_purge_restore_staged(staged)
            return jsonify({
                'error': '批量影像文件处理失败，数据未发生变化，请重试',
                'code': 'ATTACHMENT_PURGE_BATCH_FILE_FAILED',
            }), 503
        except sqlite3.DatabaseError:
            db.rollback()
            _attachment_purge_restore_staged(staged)
            return jsonify({
                'error': '批量清理未完成，数据与文件均未发生变化，请刷新后重试',
                'code': 'ATTACHMENT_PURGE_BATCH_FAILED',
            }), 503


def _rejected_attachment_batch_context(db, aid, user_id, roles):
    row = db.execute('SELECT * FROM operation_attachments WHERE id=?', (aid,)).fetchone()
    if not row:
        if 'admin' not in roles:
            return None, (jsonify({'error': '当前账号无权访问该整改包',
                                   'code': 'REJECTED_ATTACHMENT_PURGE_FORBIDDEN'}), 403)
        return None, (jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404)
    anchor = dict(row)
    anchor_item_id = _positive_business_id(anchor.get('source_id'))
    anchor_item_row = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (anchor_item_id,)).fetchone() \
        if anchor_item_id else None
    anchor_item = dict(anchor_item_row) if anchor_item_row else None
    plan_id = _positive_business_id(anchor_item.get('plan_id')) if anchor_item else None
    site_id = _positive_business_id(anchor_item.get('site_id')) if anchor_item else None
    plan_row = db.execute('SELECT * FROM insp_plans WHERE id=?', (plan_id,)).fetchone() if plan_id else None
    plan = dict(plan_row) if plan_row else None
    if 'admin' not in roles:
        anchor_site_id = _positive_business_id(anchor.get('site_id'))
        assigned = bool(plan and int(plan.get('assignee_id') or 0) == user_id)
        uploaded = int(anchor.get('uploader_id') or 0) == user_id
        has_item_site = bool(site_id and db.execute(
            'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?', (user_id, site_id)).fetchone())
        has_anchor_site = bool(anchor_site_id and db.execute(
            'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?',
            (user_id, anchor_site_id)).fetchone())
        if not (assigned and uploaded and has_item_site and has_anchor_site):
            return None, (jsonify({'error': '当前账号无权访问该整改包',
                                   'code': 'REJECTED_ATTACHMENT_PURGE_FORBIDDEN'}), 403)
    if (int(anchor.get('is_deleted') or 0)
            or str(anchor.get('source_type') or '').lower() != 'inspection'
            or str(anchor.get('review_status') or '').lower() != 'rejected'):
        return None, (jsonify({'error': '仅已驳回且不再计有效证据的巡检影像可以整包清理',
                               'code': 'REJECTED_ATTACHMENT_PURGE_STATE_INVALID'}), 409)
    if not plan or site_id != _positive_business_id(anchor.get('site_id')):
        return None, (jsonify({'error': '影像与计划、检查项或站点关联不一致，未执行清理',
                               'code': 'REJECTED_ATTACHMENT_PURGE_LINK_INVALID'}), 409)
    rows = db.execute("""SELECT a.*, i.plan_id AS linked_plan_id, i.site_id AS linked_site_id,
                                i.execution_status AS linked_execution_status,
                                i.evidence_status AS linked_evidence_status,
                                i.supplement_required_at AS linked_supplement_required_at,
                                i.rework_required_at AS linked_rework_required_at,
                                i.item_name AS linked_item_name
                         FROM operation_attachments a
                         LEFT JOIN insp_plan_items i ON a.source_type='inspection' AND a.source_id=i.id
                         WHERE COALESCE(a.is_deleted,0)=0 AND a.source_type='inspection'
                           AND a.review_status='rejected'
                           AND ((i.plan_id=? AND i.site_id=?) OR (a.plan_id=? AND a.site_id=?))
                         ORDER BY a.id""", (plan_id, site_id, plan_id, site_id)).fetchall()
    attachments = [dict(candidate) for candidate in rows]
    if not any(int(candidate['id']) == aid for candidate in attachments):
        return None, (jsonify({'error': '锚点不属于当前整改包',
                               'code': 'REJECTED_ATTACHMENT_PURGE_LINK_INVALID'}), 409)
    for candidate in attachments:
        candidate_id = int(candidate['id'])
        item_id = _positive_business_id(candidate.get('source_id'))
        explicit_plan_valid = candidate.get('plan_id') in (None, '', 0, '0', plan_id)
        explicit_item_valid = candidate.get('item_id') in (None, '', 0, '0', item_id)
        link_valid = (explicit_plan_valid and explicit_item_valid
                      and _positive_business_id(candidate.get('site_id')) == site_id
                      and _positive_business_id(candidate.get('linked_plan_id')) == plan_id
                      and _positive_business_id(candidate.get('linked_site_id')) == site_id)
        modern_link = (_positive_business_id(candidate.get('plan_id')) == plan_id
                       and _positive_business_id(candidate.get('item_id')) == item_id
                       and _positive_business_id(candidate.get('site_id')) == site_id)
        try:
            metadata = json.loads(candidate.get('extra_json') or '{}')
        except (TypeError, ValueError, json.JSONDecodeError):
            metadata = None
        if not link_valid:
            return None, (jsonify({'error': '整改包内影像关联不一致，未执行任何清理',
                                   'attachment_id': candidate_id,
                                   'code': 'REJECTED_ATTACHMENT_PURGE_LINK_INVALID'}), 409)
        if 'admin' not in roles and not modern_link:
            return None, (jsonify({'error': '仅当前整改包执行人可清理本人上传的全部已驳回照片',
                                   'code': 'REJECTED_ATTACHMENT_PURGE_FORBIDDEN'}), 403)
        if (not isinstance(metadata, dict)
                or str(metadata.get('material_role') or 'formal') != 'formal'):
            return None, (jsonify({'error': '整改包包含补充或元数据异常材料，未执行任何清理',
                                   'attachment_id': candidate_id,
                                   'code': 'REJECTED_ATTACHMENT_PURGE_MATERIAL_PROTECTED'}), 409)
    if 'admin' not in roles:
        has_site = bool(db.execute('SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?',
                                   (user_id, site_id)).fetchone())
        plan_current = str(plan.get('status') or '') in ('active', 'completed')
        schedule_current = True
        schedule_id = _positive_business_id(plan.get('plan_schedule_id'))
        if schedule_id:
            schedule = db.execute('SELECT status FROM plan_schedules WHERE id=?', (schedule_id,)).fetchone()
            schedule_current = bool(schedule and schedule['status'] == 'approved')
        all_owned = int(plan.get('assignee_id') or 0) == user_id and has_site
        for candidate in attachments:
            rework = (str(candidate.get('linked_evidence_status') or '') == 'supplement_required'
                      or bool(candidate.get('linked_supplement_required_at'))
                      or bool(candidate.get('linked_rework_required_at')))
            all_owned = (all_owned and int(candidate.get('uploader_id') or 0) == user_id
                         and str(candidate.get('linked_execution_status') or 'active') == 'active'
                         and rework)
        if not (all_owned and plan_current and schedule_current):
            return None, (jsonify({'error': '仅当前整改包执行人可清理本人上传的全部已驳回照片',
                                   'code': 'REJECTED_ATTACHMENT_PURGE_FORBIDDEN'}), 403)
    return {'anchor': anchor, 'plan': plan, 'plan_id': plan_id, 'site_id': site_id,
            'attachments': attachments}, None


def _rejected_attachment_item_snapshots(db, item_ids, plan_id, site_id):
    normalized_ids = sorted({_positive_business_id(value) for value in item_ids} - {None})
    if not normalized_ids:
        return []
    rows = db.execute(f"""SELECT id,photo_urls,actual_photos,evidence_status
        FROM insp_plan_items WHERE plan_id=? AND site_id=?
          AND id IN ({','.join('?' for _ in normalized_ids)}) ORDER BY id""",
                      (plan_id, site_id, *normalized_ids)).fetchall()
    return [{'item_id': int(row['id']),
             'photo_urls': _attachment_purge_urls(row['photo_urls']),
             'actual_photos': max(0, int(row['actual_photos'] or 0)),
             'evidence_status': row['evidence_status'] or ''} for row in rows]


@app.route('/api/attachments/<int:aid>/purge-rejected-batch', methods=['GET', 'POST'])
@login_required
def purge_rejected_attachment_batch(aid):
    backups = []
    with get_db() as db:
        try:
            if request.method == 'POST':
                db.execute('BEGIN IMMEDIATE')
            user_id = int(g.current_user.get('id') or 0)
            roles = _attachment_purge_active_roles(db, user_id)
            if not roles:
                if request.method == 'POST': db.rollback()
                return jsonify({'error': '账号状态或权限已变化，请重新登录', 'code': 'FORBIDDEN'}), 403
            context, error = _rejected_attachment_batch_context(db, aid, user_id, roles)
            if error:
                if request.method == 'POST':
                    # A missing anchor may be an idempotent replay of one completed batch.
                    prior = db.execute("""SELECT remark FROM timeline_events
                        WHERE source_type='rejected_attachment_purge' AND source_id=?
                          AND event_type='purged' ORDER BY rowid DESC LIMIT 1""", (aid,)).fetchone() \
                        if _table_exists(db, 'timeline_events') else None
                    if prior:
                        summary = json.loads(prior['remark'] or '{}')
                        batch_key = str(summary.get('batch_key') or '')
                        raw_member_ids = summary.get('batch_attachment_ids') or []
                        member_ids = (sorted({_positive_business_id(value) for value in raw_member_ids} - {None})
                                      if isinstance(raw_member_ids, list) else [])
                        allowed = ('admin' in roles or (int(summary.get('uploader_id') or 0) == user_id
                                                       and int(summary.get('assignee_id') or 0) == user_id))
                        remaining = db.execute(
                            f"SELECT COUNT(*) FROM operation_attachments WHERE id IN ({','.join('?' for _ in member_ids)})",
                            member_ids).fetchone()[0] if member_ids else 1
                        if batch_key and allowed and not remaining:
                            placeholders = ','.join('?' for _ in member_ids)
                            batch_summaries = []
                            for row in db.execute(f"""SELECT source_id,remark FROM timeline_events
                                WHERE source_type='rejected_attachment_purge' AND event_type='purged'
                                  AND source_id IN ({placeholders})""", member_ids).fetchall():
                                try:
                                    member_summary = json.loads(row['remark'] or '{}')
                                except (TypeError, ValueError, json.JSONDecodeError):
                                    continue
                                if (str(member_summary.get('batch_key') or '') == batch_key
                                        and _positive_business_id(member_summary.get('plan_id'))
                                            == _positive_business_id(summary.get('plan_id'))
                                        and _positive_business_id(member_summary.get('site_id'))
                                            == _positive_business_id(summary.get('site_id'))):
                                    batch_summaries.append(member_summary)
                            if len(batch_summaries) != len(member_ids):
                                db.rollback()
                                return error
                            item_results = _rejected_attachment_item_snapshots(
                                db, [value.get('item_id') for value in batch_summaries],
                                _positive_business_id(summary.get('plan_id')),
                                _positive_business_id(summary.get('site_id')))
                            db.rollback()
                            return jsonify({'success': True, 'already_deleted': True,
                                            'batch_key': batch_key, 'count': len(member_ids),
                                            'attachment_ids': member_ids, 'items': item_results})
                    db.rollback()
                return error
            attachments = context['attachments']
            if request.method == 'GET':
                return jsonify({'attachment_id': aid, 'plan_id': context['plan_id'],
                                'site_id': context['site_id'], 'count': len(attachments)})
            attachment_ids = [int(candidate['id']) for candidate in attachments]
            batch_key = (f"rejected_attachment_batch:{context['plan_id']}:{context['site_id']}:"
                         + '-'.join(str(value) for value in attachment_ids))
            shared_by_id = {}
            backup_map = {}
            for candidate in attachments:
                candidate_backups, shared = _attachment_purge_physical_backups(
                    db, candidate, int(candidate['id']), excluded_ids=attachment_ids)
                shared_by_id[int(candidate['id'])] = shared
                for target, content in candidate_backups:
                    backup_map[target] = content
            backups = sorted(backup_map.items())
            for target, _ in backups:
                os.remove(target)
            grouped = {}
            for candidate in attachments:
                grouped.setdefault(int(candidate['source_id']), []).append(candidate)
            affected_item_ids = []
            for item_id, candidates in grouped.items():
                item = db.execute('SELECT * FROM insp_plan_items WHERE id=? AND plan_id=? AND site_id=?',
                                  (item_id, context['plan_id'], context['site_id'])).fetchone()
                if not item:
                    raise sqlite3.IntegrityError('inspection item changed during batch purge')
                target_paths = {_attachment_storage_path(candidate.get('stored_path') or '')
                                for candidate in candidates}
                remaining_urls = [url for url in _attachment_purge_urls(item['photo_urls'])
                                  if _attachment_storage_path(url) not in target_paths]
                effective_count = _qualified_evidence_count(
                    db, 'inspection', item_id, stored_paths=remaining_urls)
                if db.execute("""UPDATE insp_plan_items SET photo_urls=?,actual_photos=?
                    WHERE id=? AND plan_id=? AND site_id=?""",
                    (json.dumps(remaining_urls, ensure_ascii=False), effective_count,
                     item_id, context['plan_id'], context['site_id'])).rowcount != 1:
                    raise sqlite3.IntegrityError('inspection item changed during batch purge')
                affected_item_ids.append(item_id)
            for child in ('attachment_evidence_evaluations', 'attachment_deletion_audits',
                          'attachment_void_audits', 'attachment_link_migration_issues',
                          'evidence_quality_remediations', 'photo_capture_sessions'):
                _ps_purge_delete_ids(db, child, 'attachment_id', attachment_ids)
            placeholders = ','.join('?' for _ in attachment_ids)
            if {'source_type', 'source_id'}.issubset(_ps_purge_table_columns(db, 'notifications')):
                db.execute(f"""DELETE FROM notifications
                    WHERE source_type IN ('attachment_review','photo_review','attachment_void','replacement_review')
                      AND source_id IN ({placeholders})""", attachment_ids)
            if db.execute(f"""DELETE FROM operation_attachments
                WHERE id IN ({placeholders}) AND COALESCE(is_deleted,0)=0
                  AND source_type='inspection' AND review_status='rejected'""",
                attachment_ids).rowcount != len(attachment_ids):
                raise sqlite3.IntegrityError('attachment batch changed during purge')
            for candidate in attachments:
                attachment_id = int(candidate['id'])
                summary = {
                    'attachment_id': attachment_id, 'plan_id': context['plan_id'],
                    'item_id': int(candidate['source_id']), 'site_id': context['site_id'],
                    'item_name': candidate.get('linked_item_name') or '',
                    'uploader_id': candidate.get('uploader_id'),
                    'assignee_id': context['plan'].get('assignee_id'), 'operator_id': user_id,
                    'reason': str(candidate.get('reject_reason') or '').strip() or '清理已驳回影像',
                    'shared_file_retained': shared_by_id[attachment_id],
                    'batch_key': batch_key, 'batch_attachment_ids': attachment_ids,
                }
                db.execute("""INSERT INTO timeline_events
                    (source_type,source_id,event_type,operator,remark)
                    VALUES ('rejected_attachment_purge',?,'purged',?,?)""",
                    (attachment_id, _current_actor_name(),
                     json.dumps(summary, ensure_ascii=False, separators=(',', ':'))))
            item_results = _rejected_attachment_item_snapshots(
                db, affected_item_ids, context['plan_id'], context['site_id'])
            db.commit()
            return jsonify({'success': True, 'already_deleted': False, 'batch_key': batch_key,
                            'count': len(attachment_ids), 'attachment_ids': attachment_ids,
                            'items': item_results})
        except OSError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '整改包影像文件删除失败，数据未发生变化，请重试',
                            'code': 'REJECTED_ATTACHMENT_PURGE_FILE_FAILED'}), 503
        except sqlite3.DatabaseError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '整改包清理未完成，数据未发生变化，请刷新后重试',
                            'code': 'REJECTED_ATTACHMENT_PURGE_FAILED'}), 503


@app.route('/api/attachments/<int:aid>/purge-rejected', methods=['POST'])
@login_required
def purge_rejected_attachment(aid):
    backups = []
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
            user_id = int(g.current_user.get('id') or 0)
            roles = _attachment_purge_active_roles(db, user_id)
            if not roles:
                db.rollback()
                return jsonify({'error': '账号状态或权限已变化，请重新登录', 'code': 'FORBIDDEN'}), 403
            row = db.execute('SELECT * FROM operation_attachments WHERE id=?', (aid,)).fetchone()
            if not row:
                prior = db.execute("""SELECT remark FROM timeline_events
                    WHERE source_type='rejected_attachment_purge' AND source_id=?
                      AND event_type='purged' LIMIT 1""", (aid,)).fetchone() \
                    if _table_exists(db, 'timeline_events') else None
                if prior:
                    summary = json.loads(prior['remark'] or '{}')
                    if ('admin' in roles or (int(summary.get('uploader_id') or 0) == user_id
                                             and int(summary.get('assignee_id') or 0) == user_id)):
                        db.rollback()
                        return jsonify({'success': True, 'attachment_id': aid,
                                        'already_deleted': True})
                db.rollback()
                return jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404
            attachment = dict(row)
            if (int(attachment.get('is_deleted') or 0)
                    or str(attachment.get('source_type') or '').lower() != 'inspection'
                    or str(attachment.get('review_status') or '').lower() != 'rejected'):
                db.rollback()
                return jsonify({'error': '仅已驳回且不再计有效证据的巡检影像可以彻底删除',
                                'code': 'REJECTED_ATTACHMENT_PURGE_STATE_INVALID'}), 409
            reason = str(attachment.get('reject_reason') or '').strip() or '清理已驳回影像'
            try:
                metadata = json.loads(attachment.get('extra_json') or '{}')
            except (TypeError, ValueError, json.JSONDecodeError):
                metadata = None
            if (not isinstance(metadata, dict)
                    or str(metadata.get('material_role') or 'formal') != 'formal'):
                db.rollback()
                return jsonify({'error': '补充或元数据异常的材料不能彻底删除',
                                'code': 'REJECTED_ATTACHMENT_PURGE_MATERIAL_PROTECTED'}), 409
            item_id = _positive_business_id(attachment.get('source_id'))
            item_row = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (item_id,)).fetchone() \
                if item_id else None
            item = dict(item_row) if item_row else None
            plan_row = db.execute('SELECT * FROM insp_plans WHERE id=?', (item.get('plan_id'),)).fetchone() \
                if item else None
            plan = dict(plan_row) if plan_row else None
            link_valid = bool(item and plan
                              and int(item.get('site_id') or 0) == int(attachment.get('site_id') or 0)
                              and attachment.get('item_id') in (None, '', 0, '0', item_id)
                              and attachment.get('plan_id') in (None, '', 0, '0', item.get('plan_id')))
            if not link_valid:
                db.rollback()
                return jsonify({'error': '影像与计划、检查项或站点关联不一致，未执行删除',
                                'code': 'REJECTED_ATTACHMENT_PURGE_LINK_INVALID'}), 409
            if 'admin' not in roles:
                exact_link = (_positive_business_id(attachment.get('plan_id'))
                              == _positive_business_id(item.get('plan_id'))
                              and _positive_business_id(attachment.get('item_id')) == item_id)
                assigned = int(plan.get('assignee_id') or 0) == user_id
                uploaded = int(attachment.get('uploader_id') or 0) == user_id
                has_site = bool(db.execute('SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?',
                                           (user_id, item.get('site_id'))).fetchone())
                rework = (str(item.get('evidence_status') or '') == 'supplement_required'
                          or bool(item.get('supplement_required_at'))
                          or bool(item.get('rework_required_at')))
                plan_current = str(plan.get('status') or '') in ('active', 'completed')
                item_current = str(item.get('execution_status') or 'active') == 'active'
                schedule_current = True
                schedule_id = _positive_business_id(plan.get('plan_schedule_id'))
                if schedule_id:
                    schedule = db.execute(
                        'SELECT status FROM plan_schedules WHERE id=?', (schedule_id,)).fetchone()
                    schedule_current = bool(schedule and schedule['status'] == 'approved')
                if not (exact_link and assigned and uploaded and has_site and rework
                        and plan_current and item_current and schedule_current):
                    db.rollback()
                    return jsonify({'error': '仅当前返场检查项的执行人可删除本人上传的已驳回照片',
                                    'code': 'REJECTED_ATTACHMENT_PURGE_FORBIDDEN'}), 403
            stored_path = str(attachment.get('stored_path') or '')
            backups, shared_file = _attachment_purge_physical_backups(db, attachment, aid)
            for target, _ in backups:
                os.remove(target)
            prior_urls = _attachment_purge_urls(item.get('photo_urls'))
            target_path = _attachment_storage_path(stored_path)
            remaining_urls = [url for url in prior_urls if _attachment_storage_path(url) != target_path]
            effective_count = _qualified_evidence_count(
                db, 'inspection', item_id, stored_paths=remaining_urls)
            updates, params = [], []
            item_columns = _ps_purge_table_columns(db, 'insp_plan_items')
            if 'photo_urls' in item_columns:
                updates.append('photo_urls=?'); params.append(json.dumps(remaining_urls, ensure_ascii=False))
            if 'actual_photos' in item_columns:
                updates.append('actual_photos=?'); params.append(effective_count)
            if updates:
                params.extend((item_id, item.get('plan_id')))
                if db.execute(f"UPDATE insp_plan_items SET {','.join(updates)} WHERE id=? AND plan_id=?",
                              params).rowcount != 1:
                    raise sqlite3.IntegrityError('inspection item changed during purge')
            for child in ('attachment_evidence_evaluations', 'attachment_deletion_audits',
                          'attachment_void_audits', 'attachment_link_migration_issues',
                          'evidence_quality_remediations', 'photo_capture_sessions'):
                _ps_purge_delete_ids(db, child, 'attachment_id', [aid])
            if {'source_type', 'source_id'}.issubset(_ps_purge_table_columns(db, 'notifications')):
                db.execute("""DELETE FROM notifications
                    WHERE source_type IN ('attachment_review','photo_review',
                                          'attachment_void','replacement_review') AND source_id=?""", (aid,))
            if db.execute("""DELETE FROM operation_attachments
                WHERE id=? AND COALESCE(is_deleted,0)=0 AND source_type='inspection'
                  AND review_status='rejected'""", (aid,)).rowcount != 1:
                raise sqlite3.IntegrityError('attachment changed during purge')
            summary = {
                'attachment_id': aid, 'plan_id': item.get('plan_id'), 'item_id': item_id,
                'site_id': item.get('site_id'), 'item_name': item.get('item_name') or '',
                'uploader_id': attachment.get('uploader_id'), 'assignee_id': plan.get('assignee_id'),
                'operator_id': user_id, 'reason': reason, 'shared_file_retained': shared_file,
            }
            db.execute("""INSERT INTO timeline_events
                (source_type,source_id,event_type,operator,remark)
                VALUES ('rejected_attachment_purge',?,'purged',?,?)""",
                (aid, _current_actor_name(), json.dumps(summary, ensure_ascii=False, separators=(',', ':'))))
            db.commit()
            return jsonify({'success': True, 'attachment_id': aid, 'already_deleted': False,
                            'photo_urls': remaining_urls, 'actual_photos': effective_count,
                            'evidence_status': item.get('evidence_status') or '',
                            'shared_file_retained': shared_file})
        except OSError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '影像文件删除失败，数据未发生变化，请重试',
                            'code': 'REJECTED_ATTACHMENT_PURGE_FILE_FAILED'}), 503
        except sqlite3.DatabaseError:
            db.rollback(); _ps_restore_purge_files(backups)
            return jsonify({'error': '彻底删除未完成，数据未发生变化，请刷新后重试',
                            'code': 'REJECTED_ATTACHMENT_PURGE_FAILED'}), 503


@app.route('/api/attachments/<int:aid>/void', methods=['POST'])
def void_attachment(aid):
    """Void approved evidence and open replacement state for its exact item."""
    denied = require_reviewer()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    reason = data.get('reason', '')
    if not isinstance(reason, str):
        return jsonify({'error': '作废理由必须是文本', 'code': 'VOID_REASON_INVALID'}), 400
    reason = reason.strip()
    if not reason:
        return jsonify({'error': '作废理由不能为空', 'code': 'VOID_REASON_REQUIRED'}), 400
    if len(reason) > 500:
        return jsonify({'error': '作废理由不能超过500字', 'code': 'VOID_REASON_TOO_LONG'}), 400

    with get_db() as db:
        if not _table_exists(db, 'attachment_void_audits'):
            return jsonify({'error': '作废审计表不可用', 'code': 'VOID_AUDIT_UNAVAILABLE'}), 500
        db.execute('BEGIN IMMEDIATE')
        row = db.execute("""SELECT oa.*, s.name AS site_name,
                                  COALESCE(oa.uploader_name, u.real_name, '') AS uploader_real_name
                           FROM operation_attachments oa
                           LEFT JOIN sites s ON s.id=oa.site_id
                           LEFT JOIN users u ON u.id=oa.uploader_id
                           WHERE oa.id=?""", (aid,)).fetchone()
        if not row:
            return jsonify({'error': '影像不存在', 'code': 'ATTACHMENT_NOT_FOUND'}), 404
        att = dict(row)
        denied = _site_access_denied(att.get('site_id'), '作废影像')
        if denied:
            return denied

        if str(att.get('review_status') or '').lower() == 'voided' or att.get('voided_at'):
            audit = db.execute(
                'SELECT * FROM attachment_void_audits WHERE attachment_id=?', (aid,)
            ).fetchone()
            return jsonify({
                'success': True, 'idempotent': True, 'status': 'voided',
                'attachment_id': aid,
                'audit_id': audit['id'] if audit else None,
                'replacement_item_id': audit['replacement_item_id'] if audit else None,
            })
        if att.get('is_deleted'):
            return jsonify({'error': '影像已移出档案，不能再作废', 'code': 'ATTACHMENT_DELETED'}), 409
        if str(att.get('review_status') or '').lower() != 'approved':
            return jsonify({
                'error': '仅已通过影像可以作废并要求补传',
                'code': 'ATTACHMENT_VOID_STATUS_INVALID',
                'review_status': att.get('review_status') or 'pending',
            }), 409
        if att.get('archived'):
            return jsonify({'error': '已归档影像不能静默修改历史', 'code': 'ATTACHMENT_ARCHIVED'}), 409
        if str(att.get('source_type') or '').lower() == 'workorder':
            return jsonify({'error': '工单证据必须通过工单纠错流程处理', 'code': 'WORKORDER_EVIDENCE_LOCKED'}), 409

        item = None
        if str(att.get('source_type') or '').lower() == 'inspection' and att.get('source_id'):
            item = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (att['source_id'],)).fetchone()
            if item and item['site_id'] != att.get('site_id'):
                item = None
        if not item:
            return jsonify({
                'error': '影像没有可靠的检查项关联，不能作废后伪造补传目标',
                'code': 'ATTACHMENT_ASSOCIATION_REQUIRED',
            }), 409
        plan = db.execute('SELECT id, plan_name, status FROM insp_plans WHERE id=?', (item['plan_id'],)).fetchone()
        if not plan:
            return jsonify({'error': '关联巡检计划不存在', 'code': 'INSPECTION_PLAN_NOT_FOUND'}), 409
        if str(plan['status'] or '').lower() in ('closed', 'archived', 'cancelled'):
            return jsonify({'error': '已归档或关单业务不得修改历史证据', 'code': 'INSPECTION_HISTORY_LOCKED'}), 409
        if not all(_table_has_column(db, 'insp_plan_items', column) for column in (
                'evidence_status', 'supplement_required_at',
                'supplement_source_attachment_id', 'supplement_reason')):
            return jsonify({'error': '检查项补传字段不可用', 'code': 'SUPPLEMENT_STATE_UNAVAILABLE'}), 500

        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        before_state = dict(att)
        risk_snapshot = {
            'is_flagged': att.get('is_flagged') or 0,
            'flag_reason': att.get('flag_reason') or '',
            'flag_rule': att.get('flag_rule') or '',
        }
        changed = db.execute("""UPDATE operation_attachments
            SET review_status='voided', voided_at=?, voided_by=?, void_reason=?
            WHERE id=? AND is_deleted=0 AND review_status='approved'""",
            (now, g.current_user.get('id'), reason, aid))
        if changed.rowcount != 1:
            # BEGIN IMMEDIATE serializes the retry; read the committed winner and
            # return the same idempotent result without another audit/notification.
            current = db.execute('SELECT review_status FROM operation_attachments WHERE id=?', (aid,)).fetchone()
            if current and current['review_status'] == 'voided':
                audit = db.execute('SELECT id, replacement_item_id FROM attachment_void_audits WHERE attachment_id=?', (aid,)).fetchone()
                return jsonify({'success': True, 'idempotent': True, 'status': 'voided',
                                'attachment_id': aid, 'audit_id': audit['id'] if audit else None,
                                'replacement_item_id': audit['replacement_item_id'] if audit else None})
            return jsonify({'error': '影像状态已变化，请刷新后重试', 'code': 'ATTACHMENT_STATE_CHANGED'}), 409

        # Keep the original item relation intact while rebuilding only the
        # current effective-photo projection.  The voided attachment remains
        # discoverable through operation_attachments.source_id.
        try:
            prior_urls = json.loads(item['photo_urls'] or '[]') if item['photo_urls'] else []
        except (TypeError, json.JSONDecodeError):
            prior_urls = []
        prior_urls = prior_urls if isinstance(prior_urls, list) else []
        qualification_clause = (
            " AND COALESCE(evidence_qualification,'review')='qualified'"
            if _table_has_column(db, 'operation_attachments', 'evidence_qualification') else '')
        valid_rows = db.execute(f"""
            SELECT stored_path FROM operation_attachments
            WHERE source_type='inspection' AND source_id=? AND is_deleted=0
              AND review_status NOT IN ('rejected', 'voided')
              {qualification_clause}
            ORDER BY created_at ASC, id ASC
        """, (item['id'],)).fetchall()
        effective_urls = [url for url in prior_urls if url != att.get('stored_path')]
        for valid_row in valid_rows:
            if valid_row['stored_path'] and valid_row['stored_path'] not in effective_urls:
                effective_urls.append(valid_row['stored_path'])
        db.execute("""UPDATE insp_plan_items
            SET evidence_status='supplement_required', supplement_required_at=?,
                supplement_source_attachment_id=?, supplement_reason=?,
                photo_urls=?, actual_photos=?
            WHERE id=? AND plan_id=?""", (
                now, aid, reason, json.dumps(effective_urls, ensure_ascii=False),
                len(valid_rows), item['id'], item['plan_id']))
        try:
            db.execute("""INSERT INTO attachment_void_audits
                (attachment_id, original_source_type, original_source_id, original_site_id,
                 original_plan_id, original_item_id, original_item_name, original_site_name,
                 original_uploader_id, original_uploader_name, original_archive_name,
                 original_review_status, original_reviewer_id, original_reviewed_at,
                 original_risk_snapshot, original_state, replacement_item_id,
                 replacement_plan_id, operator_id, operator_name, reason, voided_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
                aid, att.get('source_type') or '', att.get('source_id'), att.get('site_id'),
                item['plan_id'], item['id'], item['item_name'] or '',
                att.get('site_name') or '', att.get('uploader_id'),
                att.get('uploader_name') or att.get('uploader_real_name') or '',
                att.get('archive_name') or '',
                att.get('review_status') or '', att.get('reviewer_id'), att.get('reviewed_at'),
                json.dumps(risk_snapshot, ensure_ascii=False, sort_keys=True),
                json.dumps(before_state, ensure_ascii=False, sort_keys=True), item['id'], item['plan_id'],
                g.current_user.get('id'), _current_actor_name(''), reason, now,
            ))
        except sqlite3.IntegrityError:
            audit = db.execute('SELECT id, replacement_item_id FROM attachment_void_audits WHERE attachment_id=?', (aid,)).fetchone()
            if audit:
                return jsonify({'success': True, 'idempotent': True, 'status': 'voided',
                                'attachment_id': aid, 'audit_id': audit['id'],
                                'replacement_item_id': audit['replacement_item_id']})
            raise

        if _table_exists(db, 'operation_logs'):
            db.execute("""INSERT INTO operation_logs
                (module, action, target_type, target_id, operator, operator_id, details)
                VALUES (?,?,?,?,?,?,?)""", (
                'attachment', 'void', 'attachment', aid, _current_actor_name(''), g.current_user.get('id'),
                json.dumps({'attachment_id': aid, 'item_id': item['id'], 'plan_id': item['plan_id'],
                            'reason': reason, 'voided_at': now}, ensure_ascii=False, sort_keys=True)))
        if att.get('uploader_id') and _table_exists(db, 'notifications'):
            notification_reason = reason if reason.endswith(('。', '！', '？', '!', '?')) else reason + '。'
            content = (f'{item["item_name"] or "检查项"}的影像已作废：{notification_reason}'
                       '请补传新的现场影像，补传审核通过前该检查项不会恢复有效闭环。')
            _upsert_unread_notification(
                db, att['uploader_id'], 'attachment_void', aid,
                '影像作废，请补传', content, f'attachment_void:{aid}',
                json.dumps({'attachment_id': aid, 'site_id': att.get('site_id'),
                            'plan_id': item['plan_id'], 'item_id': item['id'],
                            'item_name': item['item_name'] or '', 'reason': reason}, ensure_ascii=False),
            )
        db.commit()
        return jsonify({
            'success': True, 'status': 'voided', 'attachment_id': aid,
            'audit_id': db.execute('SELECT id FROM attachment_void_audits WHERE attachment_id=?', (aid,)).fetchone()['id'],
            'replacement_item_id': item['id'], 'replacement_plan_id': item['plan_id'],
            'replacement_status': 'supplement_required',
        })


@app.route('/api/attachments/<int:aid>/archive', methods=['POST'])
def archive_attachment(aid):
    """归档影像资料：标记为已归档，便于长期留存与独立检索"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    reason = data.get('archive_reason', '')
    archived_by = g.current_user.get('id')
    with get_db() as db:
        att = db.execute(
            "SELECT id FROM operation_attachments WHERE id=? AND is_deleted=0", (aid,)
        ).fetchone()
        if not att:
            return jsonify({'error': '附件不存在'}), 404
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        db.execute(
            """UPDATE operation_attachments
               SET archived=1, archived_at=?, archived_by=?, archive_reason=?
               WHERE id=?""",
            (now, archived_by, reason, aid))
        db.commit()
    return jsonify({'success': True})


@app.route('/api/attachments/<int:aid>/unarchive', methods=['POST'])
def unarchive_attachment(aid):
    """取消归档"""
    denied = require_admin()
    if denied:
        return denied
    with get_db() as db:
        att = db.execute(
            "SELECT id FROM operation_attachments WHERE id=? AND is_deleted=0", (aid,)
        ).fetchone()
        if not att:
            return jsonify({'error': '附件不存在'}), 404
        db.execute(
            """UPDATE operation_attachments
               SET archived=0, archived_at=NULL, archived_by=NULL, archive_reason=''
               WHERE id=?""",
            (aid,))
        db.commit()
    return jsonify({'success': True})


@app.route('/api/attachments/stats')
def attachment_stats():
    """影像档案统计：总数、按类型统计、按月统计"""
    scope = _filter_site_ids()
    if scope == []:
        return jsonify({'total': 0, 'all_records': 0, 'rejected_or_voided': 0,
                        'evidence_issues': 0, 'archived': 0, 'review_pending': 0,
                        'by_category': {}, 'by_source': {}, 'by_month': []})
    scope_sql = '' if scope is None else f" AND site_id IN ({','.join('?' * len(scope))})"
    scope_params = [] if scope is None else list(scope)
    with get_db() as db:
        current_sql = _current_attachment_archive_sql(db, 'oa')
        current_scope_sql = '' if scope is None else f" AND oa.site_id IN ({','.join('?' * len(scope))})"
        all_records = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments WHERE is_deleted=0{scope_sql}",
            scope_params).fetchone()[0]
        total = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments oa WHERE {current_sql}{current_scope_sql}",
            scope_params).fetchone()[0]
        rejected_or_voided = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments WHERE is_deleted=0 AND review_status IN ('rejected','voided'){scope_sql}",
            scope_params).fetchone()[0]
        evidence_issues = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments oa WHERE oa.is_deleted=0 "
            f"AND {_actionable_evidence_issue_sql('oa')}"
            f"{scope_sql.replace('site_id', 'oa.site_id')}",
            scope_params).fetchone()[0]
        archived_count = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments oa WHERE {current_sql} "
            f"AND oa.archived=1{current_scope_sql}", scope_params).fetchone()[0]
        review_pending = db.execute(
            f"SELECT COUNT(*) FROM operation_attachments oa WHERE oa.is_deleted=0 "
            f"AND oa.review_required=1 AND oa.review_status='pending'{current_scope_sql}",
            scope_params,
        ).fetchone()[0]
        by_category = {}
        for row in db.execute(
                f"SELECT oa.category, COUNT(*) as cnt FROM operation_attachments oa "
                f"WHERE {current_sql}{current_scope_sql} GROUP BY oa.category", scope_params):
            by_category[row['category']] = row['cnt']
        by_source = {}
        for row in db.execute(
                f"SELECT oa.source_type, COUNT(*) as cnt FROM operation_attachments oa "
                f"WHERE {current_sql}{current_scope_sql} GROUP BY oa.source_type", scope_params):
            by_source[row['source_type']] = row['cnt']
        by_month = []
        for row in db.execute(
                f"SELECT substr(oa.created_at,1,7) as ym, COUNT(*) as cnt "
                f"FROM operation_attachments oa WHERE {current_sql}{current_scope_sql} "
                f"GROUP BY ym ORDER BY ym DESC LIMIT 12", scope_params):
            by_month.append({'month': row['ym'], 'count': row['cnt']})
        return jsonify({
            'total': total,
            'all_records': all_records,
            'rejected_or_voided': rejected_or_voided,
            'evidence_issues': evidence_issues,
            'archived': archived_count,
            'review_pending': review_pending,
            'by_category': by_category,
            'by_source': by_source,
            'by_month': by_month,
        })


def match_photo_requirement(watermark_text='', site_id=None, filename='', description=''):
    """按水印文字/文件名关键词匹配照片类型配置（v1 轻量方案，无需 OCR）。
    返回 dict 或 None。v2 可替换为多模态模型识别，仅改此函数即可。
    匹配逻辑：把水印文字+文件名+说明拼成一个字符串，逐条比对 photo_requirements.watermark_keyword
    （支持用 | 分隔多关键词）。命中即返回该配置，自动带出是否需要审核。"""
    text = f'{watermark_text or ""} {(filename or "")} {(description or "")}'.lower()
    if not text.strip():
        return None
    with get_db() as db:
        rows = db.execute(
            "SELECT id, item_name, review_required, watermark_keyword, category "
            "FROM photo_requirements WHERE watermark_keyword IS NOT NULL AND watermark_keyword != ''"
        ).fetchall()
        for r in rows:
            kw = (r['watermark_keyword'] or '').strip().lower()
            if not kw:
                continue
            hit = any(k.strip() and k.strip() in text for k in kw.split('|'))
            if hit:
                return {
                    'requirement_id': r['id'],
                    'recognized_category': r['item_name'],
                    'review_required': r['review_required'] or 0,
                    'category': r['category'] or '',
                    'match_status': 'auto',
                    'match_confidence': 0.8,
                }
    return None


@app.route('/api/upload/attachment', methods=['POST'])
def upload_attachment():
    """上传影像附件（带完善元信息）"""
    file = request.files.get('file')
    if not file:
        return jsonify({'error': '请选择文件'}), 400

    ext = os.path.splitext(file.filename or '.jpg')[1].lower() or '.jpg'
    image_exts = {'.jpg', '.jpeg', '.png', '.webp', '.bmp', '.gif'}
    if ext not in image_exts:
        return jsonify({'error': '仅支持图片格式'}), 400
    file_data = file.read()
    if len(file_data) > 20 * 1024 * 1024:
        return jsonify({'error': '文件大小超过20MB限制'}), 400

    # 生成唯一文件名
    fname = str(uuid.uuid4())[:12] + ext
    now = datetime.now()
    subdir = now.strftime('attachments/%Y/%m')
    stored_dir = os.path.join(UPLOAD_DIR, subdir)
    os.makedirs(stored_dir, exist_ok=True)
    stored_path = os.path.join(stored_dir, fname)
    with open(stored_path, 'wb') as f:
        f.write(file_data)
    url = f'/uploads/{subdir}/{fname}'

    # 水印解析 + 自动归类（v1：关键词匹配，无需 OCR）
    watermark_text = request.form.get('watermark_text', '') or ''
    match = match_photo_requirement(
        watermark_text,
        request.form.get('site_id', type=int),
        file.filename or '',
        request.form.get('description', ''))
    req_id = match['requirement_id'] if match else None
    rec_cat = match['recognized_category'] if match else ''
    match_status = match['match_status'] if match else 'manual'
    match_conf = match['match_confidence'] if match else None
    review_required = match['review_required'] if match else 0
    auto_category = match['category'] if match else request.form.get('category', '')

    # 流程外资料（试剂配置/车辆里程加油/养护记录）仅归档，不强制进审核队列
    # 即便水印关键词命中配置，也不置 review_required，避免与在流程照片审核链混淆
    _src_type = request.form.get('source_type', '') or ''
    if _src_type in ('reagent', 'vehicle', 'maintenance'):
        review_required = 0
        req_id = None
        rec_cat = ''
        match_status = 'manual'
        match_conf = None
        auto_category = request.form.get('category', '') or ''

    # 写入数据库
    # 清洗乱码：替换字符 U+FFFD 或控制字符直接置空，避免污染档案展示
    def _clean_text(s):
        if not s:
            return ''
        return ''.join(c for c in s if c not in {'\x00', '\x01', '\x02', '\x03', '\x04', '\x05', '\x06', '\x07', '\x08', '\x0b', '\x0c', '\x0e', '\x0f', '\x10', '\x11', '\x12', '\x13', '\x14', '\x15', '\x16', '\x17', '\x18', '\x19', '\x1a', '\x1b', '\x1c', '\x1d', '\x1e', '\x1f'} and ord(c) != 0xFFFD)

    description = _clean_text(request.form.get('description', ''))
    watermark_text = _clean_text(watermark_text)

    with get_db() as db:
        attachment_source_type = request.form.get('source_type', '') or ''
        attachment_source_id = request.form.get('source_id', 0, type=int)
        attachment_site_id = request.form.get('site_id', type=int)
        inspection_item = None
        if attachment_source_type == 'inspection':
            # A multipart caller may select the item, but the server owns the
            # item/plan/site values written to the attachment record.
            requested_item_id = request.form.get('item_id', type=int) or attachment_source_id
            if not requested_item_id:
                return jsonify({'error': '巡检影像必须绑定具体检查项', 'code': 'INSPECTION_ITEM_REQUIRED'}), 400
            inspection_item = db.execute(
                'SELECT id, plan_id, site_id, item_name, category FROM insp_plan_items WHERE id=?',
                (requested_item_id,),
            ).fetchone()
            if not inspection_item:
                return jsonify({'error': '检查项不存在，不能伪造影像归属', 'code': 'INSPECTION_ITEM_NOT_FOUND'}), 404
            if attachment_site_id not in (None, inspection_item['site_id']):
                return jsonify({'error': '影像站点与检查项不一致', 'code': 'INSPECTION_SITE_MISMATCH'}), 400
            requested_plan_id = request.form.get('plan_id', type=int)
            if requested_plan_id not in (None, inspection_item['plan_id']):
                return jsonify({'error': '影像计划与检查项不一致', 'code': 'INSPECTION_PLAN_MISMATCH'}), 400
            attachment_source_id = inspection_item['id']
            attachment_site_id = inspection_item['site_id']
            description = inspection_item['item_name'] or description
            auto_category = inspection_item['category'] or auto_category or '巡检现场照片'
        capture_source = request.form.get('capture_source', '') or 'web_upload'
        effective_uploader_id = g.current_user.get('id') if getattr(g, 'current_user', None) else None
        effective_uploader_name = _current_actor_name('未知用户')
        assessment = _assess_attachment_evidence(
            db, source_type=attachment_source_type, source_id=attachment_source_id,
            site_id=attachment_site_id, uploader_id=effective_uploader_id,
            received_at=now.strftime('%Y-%m-%d %H:%M:%S'),
            capture_source=capture_source, client_taken_at=request.form.get('taken_at'),
            gps_lat=request.form.get('gps_lat', type=float),
            gps_lng=request.form.get('gps_lng', type=float),
        )
        db.execute("""INSERT INTO operation_attachments
            (filename, stored_path, file_type, mime_type, file_size, description,
             source_type, source_id, site_id, uploader_id, uploader_name,
             gps_lat, gps_lng, taken_at, category,
             watermark_text, recognized_category, match_status, match_confidence,
             review_required, requirement_id)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (file.filename or fname, url,
             'video' if ext in ('.mp4','.mov') else 'image',
             ext, len(file_data),
             description,
             attachment_source_type,
             attachment_source_id,
             attachment_site_id,
             effective_uploader_id,
             effective_uploader_name,
             request.form.get('gps_lat', type=float),
             request.form.get('gps_lng', type=float),
             assessment.get('taken_at'),
             auto_category,
             watermark_text, rec_cat, match_status, match_conf,
             review_required, req_id))
        aid = db.execute("SELECT last_insert_rowid()").fetchone()[0]
        _record_attachment_evaluation(
            db, aid, assessment, actor_id=effective_uploader_id,
            actor_name=effective_uploader_name)
        if inspection_item:
            _persist_inspection_attachment_link(db, aid, inspection_item)
        db.commit()

    return jsonify({'success': True, 'id': aid, 'url': url,
                   'match': match, 'review_required': review_required})


@app.route('/api/sites/<int:site_id>/schemes')
def get_site_schemes(site_id):
    with get_db() as db:
        schemes = db.execute("SELECT s.*,(SELECT COUNT(*) FROM inspection_scheme_items i WHERE i.scheme_id=s.id) as item_count FROM inspection_schemes s WHERE s.site_id=? ORDER BY CASE s.period WHEN 'daily' THEN 1 WHEN 'weekly' THEN 2 ELSE 3 END",(site_id,)).fetchall()
