@app.route('/api/global-search')
@login_required
def global_search():
    """按当前角色和站点范围检索可访问的业务对象。"""
    keyword = (request.args.get('q') or '').strip()
    if not keyword:
        return jsonify({'results': []})
    keyword = keyword[:80]
    like = f'%{keyword}%'
    roles = set(g.current_user.get('roles') or [g.current_user.get('role')])
    allowed_sites = _filter_site_ids()
    results = []

    with get_db() as db:
        if roles & {'admin', 'reviewer'} and allowed_sites != []:
            site_scope = ''
            if allowed_sites is not None:
                marks = ','.join('?' * len(allowed_sites))
                site_scope = f' AND id IN ({marks})'
            rows = db.execute(f"""
                SELECT id, name, code FROM sites
                WHERE (name LIKE ? OR code LIKE ?){site_scope}
                ORDER BY CASE WHEN name=? THEN 0 WHEN code=? THEN 0 ELSE 1 END, name
                LIMIT ?
            """, [like, like, *([] if allowed_sites is None else allowed_sites), keyword, keyword, 8]).fetchall()
            results.extend({
                'type': 'site', 'id': row['id'], 'identifier': row['id'],
                'title': row['name'] or f'站点 {row["id"]}',
                'subtitle': row['code'] or '站点资料',
            } for row in rows)

        if roles & {'admin', 'operator'} and allowed_sites != []:
            params = [like, like, like]
            order_scope = ''
            if allowed_sites is not None:
                marks = ','.join('?' * len(allowed_sites))
                order_scope = f' AND w.site_id IN ({marks})'
                params.extend(allowed_sites)
            params.append(8)
            rows = db.execute(f"""
                SELECT w.id, w.order_no, w.title, s.name AS site_name
                FROM work_orders w LEFT JOIN sites s ON s.id=w.site_id
                WHERE (w.order_no LIKE ? OR w.title LIKE ? OR s.name LIKE ?){order_scope}
                ORDER BY w.created_at DESC LIMIT ?
            """, params).fetchall()
            results.extend({
                'type': 'workorder', 'id': row['id'], 'identifier': row['order_no'],
                'title': row['title'] or row['order_no'],
                'subtitle': ' · '.join(part for part in [row['order_no'], row['site_name']] if part),
            } for row in rows)

        if 'admin' in roles:
            rows = db.execute("""
                SELECT d.id, d.device_code, d.device_name, s.name AS site_name
                FROM device_shadows d LEFT JOIN sites s ON s.id=d.site_id
                WHERE d.device_code LIKE ? OR d.device_name LIKE ? OR s.name LIKE ?
                ORDER BY CASE WHEN d.device_code=? THEN 0 ELSE 1 END, d.device_code
                LIMIT 8
            """, (like, like, like, keyword,)).fetchall()
            results.extend({
                'type': 'device', 'id': row['id'], 'identifier': row['device_code'],
                'title': row['device_name'] or row['device_code'],
                'subtitle': ' · '.join(part for part in [row['device_code'], row['site_name']] if part),
            } for row in rows)

    return jsonify({'results': results[:20]})

def _pagination_args(default_limit=50, max_limit=100):
    """Parse bounded pagination values before they reach SQLite OFFSET/LIMIT."""
    def parse(name, default):
        raw = request.args.get(name)
        if raw in (None, ''):
            return default
        try:
            value = int(raw)
        except (TypeError, ValueError):
            raise ValueError(name)
        if value < 1:
            raise ValueError(name)
        return value

    try:
        page = parse('page', 1)
        limit = parse('limit', default_limit)
    except ValueError as exc:
        return None, None, (jsonify({'error': f'{exc.args[0]} 必须为正整数'}), 400)
    return page, min(limit, max_limit), None


def _plan_notification_state(db, item):
    """Resolve whether a plan reminder still represents pending business work."""
    item['is_stale'] = False
    item['current_status'] = None
    if item.get('source_type') != 'plan_schedule' or not item.get('source_id'):
        return item
    schedule = db.execute(
        "SELECT status FROM plan_schedules WHERE id=?", (item['source_id'],)
    ).fetchone()
    current_status = schedule['status'] if schedule else 'deleted'
    item['current_status'] = current_status
    title = item.get('title') or ''
    try:
        payload = json.loads(item.get('payload_json') or '{}')
    except (TypeError, ValueError, json.JSONDecodeError):
        payload = {}
    is_pending_notice = (
        payload.get('notification_target') == 'review'
        and payload.get('review_type') == 'plan_schedule'
    ) or '待审' in title or '待审批' in title or '已提交' in title
    item['is_stale'] = not schedule or (is_pending_notice and current_status not in ('submitted', 'change_submitted'))
    return item


def _retire_stale_plan_notifications(db, user_id):
    """Move all stale unread plan notices to history before paginating current work."""
    rows = db.execute(
        "SELECT * FROM notifications WHERE user_id=? AND source_type='plan_schedule' AND is_read=0",
        (user_id,),
    ).fetchall()
    stale_ids = []
    for row in rows:
        item = _plan_notification_state(db, dict(row))
        if item['is_stale']:
            stale_ids.append(item['id'])
    if stale_ids:
        db.executemany(
            "UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?",
            [(nid, user_id) for nid in stale_ids],
        )


@app.route('/api/notifications')
@login_required
def get_notifications():
    """获取当前用户通知；status=unread/read/all 用于当前与历史消息分栏。"""
    user = g.current_user
    page, limit, pagination_error = _pagination_args(default_limit=50, max_limit=100)
    if pagination_error:
        return pagination_error
    status = request.args.get('status', 'all')
    if status not in ('all', 'unread', 'read'):
        return jsonify({'error': '消息状态参数无效'}), 400
    offset = (page - 1) * limit
    notification_id = request.args.get('notification_id', type=int)
    with get_db() as db:
        _coalesce_pending_attachment_notifications(db)
        _retire_redundant_inspection_photo_notifications(db, user['id'])
        _retire_stale_plan_notifications(db, user['id'])
        db.commit()
        status_sql = ''
        exact_sql = ''
        exact_params = []
        if notification_id is not None:
            if notification_id <= 0:
                return jsonify({'error': '消息编号参数无效'}), 400
            exact_sql = ' AND id=?'
            exact_params.append(notification_id)
        if status == 'unread':
            status_sql = ' AND is_read=0'
        elif status == 'read':
            status_sql = ' AND is_read=1'
        total = db.execute(
            f"SELECT COUNT(*) FROM notifications WHERE user_id=?{exact_sql}{status_sql if not exact_sql else ''}",
            (user['id'], *exact_params),
        ).fetchone()[0]
        rows = db.execute(
            f"SELECT * FROM notifications WHERE user_id=?{exact_sql}{status_sql if not exact_sql else ''} ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?",
            (user['id'], *exact_params, limit, offset)
        ).fetchall()
        notifications = []
        for row in rows:
            notifications.append(_plan_notification_state(db, dict(row)))
        unread = db.execute(
            "SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0",
            (user['id'],)
        ).fetchone()[0]
        return jsonify({
            'notifications': notifications,
            'unread_count': unread,
            'total': total,
            'has_more': offset + len(notifications) < total,
            'page': page,
            'limit': limit,
        })

