@app.route('/api/inspection-v2/configs/match')
@login_required
def v2_match_configs():
    """Return the same site/frequency item set used by plan validation."""
    site_id = request.args.get('site_id', type=int)
    schedule_type = request.args.get('schedule_type', '')
    if not site_id:
        return jsonify({'error': '缺少site_id参数'}), 400
    try:
        schedule_type = _inspection_frequency(schedule_type)
    except ValueError:
        return jsonify({'error': 'schedule_type参数无效',
                        'code': 'PLAN_SCHEDULE_TYPE_INVALID'}), 400
    with get_db() as db:
        site = db.execute("SELECT id, type, name FROM sites WHERE id=?", (site_id,)).fetchone()
        if not site:
            return jsonify({'error': '站点不存在'}), 404
        if not _has_any_role(g.current_user, 'admin') and not db.execute(
                'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=? LIMIT 1',
                (g.current_user['id'], site_id)).fetchone():
            return jsonify({'error': '无权配置该站点的检查项',
                            'code': 'PLAN_EXECUTION_SITE_FORBIDDEN'}), 403
        items = _ps_site_template_items(
            db, site_id, schedule_type, include_weekly_optional=(schedule_type == 'weekly'))
        due_by_item = {}
        schedule_columns = ({row['name'] for row in db.execute(
            'PRAGMA table_info(inspection_schedules)').fetchall()}
            if _table_exists(db, 'inspection_schedules') else set())
        if {'site_id', 'template_item_id', 'next_due_date'}.issubset(schedule_columns):
            item_ids = [int(item['id']) for item in items if item.get('id') is not None]
            if item_ids:
                status_clause = " AND status='active'" if 'status' in schedule_columns else ''
                rows = db.execute(
                    f"SELECT template_item_id,MIN(next_due_date) AS next_due_date "
                    f"FROM inspection_schedules WHERE site_id=?{status_clause} "
                    f"AND template_item_id IN ({','.join('?' * len(item_ids))}) "
                    f"GROUP BY template_item_id", [site_id, *item_ids]).fetchall()
                due_by_item = {int(row['template_item_id']): row['next_due_date'] for row in rows}
        today = datetime.now().date()
        for item in items:
            due_date = due_by_item.get(int(item['id'])) if item.get('id') is not None else None
            item['frequency'] = item.get('template_frequency') or schedule_type
            item['required_photos'] = _inspection_required_photos(item)
            item['next_due_date'] = due_date
            item['due_status'] = None
            item['due_label'] = ''
            if due_date:
                try:
                    due = datetime.strptime(str(due_date)[:10], '%Y-%m-%d').date()
                    if due < today:
                        item['due_status'], item['due_label'] = 'overdue', f'已超过计划日期 {due.isoformat()}'
                    elif (due - today).days <= 7:
                        item['due_status'], item['due_label'] = 'due_soon', f'临近计划日期 {due.isoformat()}'
                except ValueError:
                    pass
        template_ids = list(dict.fromkeys(
            int(item['template_id']) for item in items if item.get('template_id')))
        template_map = {}
        if template_ids:
            placeholders = ','.join('?' for _ in template_ids)
            template_map = {int(row['id']): dict(row) for row in db.execute(
                f"SELECT id, template_name, category, frequency, description "
                f"FROM inspection_templates WHERE id IN ({placeholders})", template_ids).fetchall()}
        result = []
        for template_id in template_ids:
            template = template_map.get(template_id, {})
            result.append({
                'template_id': template_id,
                'template_name': template.get('template_name', ''),
                'category': template.get('category', ''),
                'frequency': 'yearly' if template.get('frequency') == 'annual' else template.get('frequency', schedule_type),
                'description': template.get('description', ''),
                'items': [item for item in items if int(item.get('template_id') or 0) == template_id],
            })
        return jsonify({
            'site_id': site_id,
            'site_name': site['name'],
            'site_type': site['type'],
            'schedule_type': schedule_type,
            'device_types': [],
            'items': items,
            'matched_templates': result,
            'total_items': len(items),
        })

# --- 排程管理 ---

@app.route('/api/inspection-v2/schedules')
def v2_get_schedules():
    """获取排程列表"""
    site_id = request.args.get('site_id', type=int)
    status = request.args.get('status', '')  # due/upcoming/overdue
    user_id = request.args.get('user_id', type=int)
    date_from = request.args.get('date_from', '')
    date_to = request.args.get('date_to', '')
    with get_db() as db:
        today = datetime.now().strftime('%Y-%m-%d')
        q = """
            SELECT s.*, st.name as site_name, st.type as site_type,
                   it.template_name, iti.item_name, iti.category as item_category,
                   iti.frequency_level, iti.photo_required
            FROM inspection_schedules s
            JOIN sites st ON s.site_id = st.id
            JOIN inspection_templates it ON s.template_id = it.id
            JOIN inspection_template_items iti ON s.template_item_id = iti.id
            WHERE s.status='active'
        """
        params = []
        if site_id:
            q += " AND s.site_id=?"
            params.append(site_id)
        if user_id:
            q += " AND s.site_id IN (SELECT site_id FROM user_sites WHERE user_id=?)"
            params.append(user_id)
        if status == 'due':
            q += " AND s.next_due_date<=?"
            params.append(today)
        elif status == 'overdue':
            q += " AND s.next_due_date<?"
            params.append(today)
        elif status == 'upcoming':
            q += " AND s.next_due_date>? AND s.next_due_date<=date(?, '+7 days')"
            params.extend([today, today])
        if date_from:
            q += " AND s.next_due_date>=?"
            params.append(date_from)
        if date_to:
            q += " AND s.next_due_date<=?"
            params.append(date_to)
        q += " ORDER BY s.next_due_date, st.name"
        rows = db.execute(q, params).fetchall()
        return jsonify([dict(r) for r in rows])

