@app.route('/api/inspection-v2/items/pending', methods=['GET'])
def v2_pending_review_items():
    """获取待审核的巡检检查项列表（按站点范围隔离）"""
    denied = require_reviewer()
    if denied:
        return denied
    allowed = _filter_site_ids()
    site_clause = ''
    sp = []
    if allowed is not None:
        site_clause = f' AND i.site_id IN ({",".join("?" * len(allowed))})'
        sp = list(allowed)
    with get_db() as db:
        items = db.execute(f"""
            SELECT i.id, i.item_name, i.site_id, s.name as site_name,
                   i.plan_id, p.plan_name, i.actual_photos, i.required_photos,
                   i.remark, i.check_time, i.photo_urls, i.calibration_values
            FROM insp_plan_items i
            JOIN sites s ON i.site_id = s.id
            JOIN insp_plans p ON i.plan_id = p.id
            WHERE i.review_status = 1{site_clause}
            ORDER BY i.check_time DESC
        """, sp).fetchall()
        return jsonify([dict(r) for r in items])

@app.route('/api/inspection-v2/items/<int:item_id>/review', methods=['PUT'])
def v2_review_item(item_id):
    """审核通过或驳回检查项"""
    denied = require_reviewer()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    action = data.get('action')
    if not action:
        status = data.get('status', '')
        action = 'reject' if status in ('rejected', 'reject') else 'approve'
    if action not in ('approve', 'reject'):
        return jsonify({'error': '无效审核动作'}), 400
    comment = data.get('comment', data.get('review_comment', '')) or ''
    if not isinstance(comment, str):
        return jsonify({'error': '审核意见格式无效'}), 400
    reviewer_id = g.current_user.get('id', 0) if hasattr(g, 'current_user') else 0

    with get_db() as db:
        item = db.execute("SELECT * FROM insp_plan_items WHERE id=?", (item_id,)).fetchone()
        if not item:
            return jsonify({'error': '检查项不存在'}), 404
        if item['site_id'] is None:
            return jsonify({'error': '检查项未绑定有效站点，无法审核'}), 403
        denied = _site_access_denied(item['site_id'], '审核')
        if denied:
            return denied
        if item['review_status'] != 1:
            return jsonify({'error': '该检查项已审核，无需重复提交', 'code': 'REVIEW_ALREADY_PROCESSED'}), 409
        if action == 'approve':
            gate = _evidence_gate(
                db, 'inspection', item_id,
                item['required_photos'] if 'required_photos' in item.keys() else 0)
            if gate:
                return jsonify(gate), 409
            db.execute("""
                UPDATE insp_plan_items SET review_status=2, review_comment=?, reviewer_id=?, review_time=?
                WHERE id=?
            """, (comment, reviewer_id, datetime.now().strftime('%Y-%m-%d %H:%M:%S'), item_id))
            msg = '审核通过'
        else:
            if not comment.strip():
                return jsonify({'error': '驳回需填写需补充或整改的内容'}), 400
            now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            rejection = _reject_inspection_items(
                db, [(item_id, comment)], reviewer_id, now, f'item-review:{item_id}')
            msg = '审核驳回'
        db.commit()
        response = {'success': True, 'message': msg}
        if action != 'approve':
            outcome = rejection.get(item_id, {})
            response.update(outcome)
        return jsonify(response)

@app.route('/api/inspection-v2/items/batch-review', methods=['POST'])
def v2_batch_review_items():
    """异常驱动批量审核：一次调用完成"通过N项 + 驳回M项"。
    body: { approve_ids: [id,...], reject_items: [{id, reason},...] }
    设计意图：审核者只标记异常项，其余一键通过，减少逐条点击。"""
    denied = require_reviewer()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    approve_ids = data.get('approve_ids') or []
    reject_items = data.get('reject_items') or []
    if not isinstance(approve_ids, list) or not isinstance(reject_items, list):
        return jsonify({'error': '审核 ID 格式无效'}), 400
    normalized_approve_ids = []
    for raw_id in approve_ids:
        try:
            item_id = int(raw_id)
        except (TypeError, ValueError):
            return jsonify({'error': '审核 ID 格式无效'}), 400
        if item_id <= 0:
            return jsonify({'error': '审核 ID 格式无效'}), 400
        if item_id not in normalized_approve_ids:
            normalized_approve_ids.append(item_id)
    normalized_reject_items = []
    normalized_reject_ids = []
    for raw_item in reject_items:
        if not isinstance(raw_item, dict):
            return jsonify({'error': '驳回项格式无效'}), 400
        try:
            item_id = int(raw_item.get('id'))
        except (TypeError, ValueError):
            return jsonify({'error': '审核 ID 格式无效'}), 400
        if item_id <= 0:
            return jsonify({'error': '审核 ID 格式无效'}), 400
        if item_id in normalized_reject_ids:
            continue
        if 'reason' not in raw_item or raw_item.get('reason') is None:
            reason = '照片不合格'
        else:
            reason = raw_item.get('reason')
            if not isinstance(reason, str) or not reason.strip():
                return jsonify({'error': '驳回需填写原因'}), 400
            reason = reason.strip()
        normalized_reject_ids.append(item_id)
        normalized_reject_items.append({'id': item_id, 'reason': reason})
    if set(normalized_approve_ids).intersection(normalized_reject_ids):
        return jsonify({'error': '同一检查项不能同时通过和驳回'}), 400
    approve_ids = normalized_approve_ids
    reject_items = normalized_reject_items
    if not approve_ids and not reject_items:
        return jsonify({'error': '无审核内容'}), 400
    reviewer_id = g.current_user.get('id', 0) if hasattr(g, 'current_user') else 0
    now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    approved_count, rejected_count = 0, 0
    with get_db() as db:
        all_ids = approve_ids + normalized_reject_ids
        placeholders = ','.join('?' * len(all_ids))
        rows = db.execute(
            f'SELECT id, site_id, review_status, required_photos FROM insp_plan_items WHERE id IN ({placeholders})',
            all_ids).fetchall()
        row_map = {row['id']: row for row in rows}
        missing_ids = [item_id for item_id in all_ids if item_id not in row_map]
        if missing_ids:
            return jsonify({'error': '检查项不存在', 'item_ids': missing_ids}), 404
        for item_id in all_ids:
            if row_map[item_id]['site_id'] is None:
                return jsonify({'error': '检查项未绑定有效站点，无法审核'}), 403
            denied = _site_access_denied(row_map[item_id]['site_id'], '审核')
            if denied:
                return denied
            if row_map[item_id]['review_status'] != 1:
                return jsonify({
                    'error': '存在已审核或不可处理的检查项',
                    'item_id': item_id,
                    'code': 'REVIEW_ALREADY_PROCESSED',
                }), 409
        for item_id in approve_ids:
            gate = _evidence_gate(db, 'inspection', item_id, row_map[item_id]['required_photos'])
            if gate:
                gate['item_id'] = item_id
                return jsonify(gate), 409
        # 驳回会撤销现场提交结果。记录受影响执行包，稍后统一回算完成率，
        # 避免全部项目曾完成时，移动端仍把该包误显示为已完成。
        rejected_rows = []
        # 批量通过
        if approve_ids:
            ph = ','.join('?' * len(approve_ids))
            db.execute(f"""
                UPDATE insp_plan_items SET review_status=2, reviewer_id=?, review_time=?, review_comment='批量通过'
                WHERE id IN ({ph}) AND review_status=1
            """, [reviewer_id, now_str] + list(approve_ids))
            approved_count = db.execute("SELECT changes()").fetchone()[0]
        # 逐项驳回（各有原因）
        for ri in reject_items:
            rejected_rows.append((ri['id'], ri['reason']))
        rejection = _reject_inspection_items(db, rejected_rows, reviewer_id, now_str, 'batch-review')
        rejected_count = len(rejection)
        db.commit()
    rework_plan_ids = sorted({outcome['rework_plan_id'] for outcome in rejection.values()
                              if outcome.get('rework_plan_id')})
    return jsonify({'success': True, 'approved': approved_count, 'rejected': rejected_count,
                    'resource_replan_required': bool(rework_plan_ids), 'rework_plan_ids': rework_plan_ids,
                    'message': f'通过 {approved_count} 项，驳回 {rejected_count} 项'})

@app.route('/api/inspection-v2/plans/<int:plan_id>/stats')
def v2_plan_stats(plan_id):
    """计划统计（按站点范围隔离）"""
    allowed = _filter_site_ids()
    with get_db() as db:
        plan = db.execute("SELECT * FROM insp_plans WHERE id=?", (plan_id,)).fetchone()
        if not plan:
            return jsonify({'error': '计划不存在'}), 404
        if allowed is not None:
            plan_sites = [r['site_id'] for r in db.execute(
                "SELECT DISTINCT site_id FROM insp_plan_items WHERE plan_id=?", (plan_id,)).fetchall()]
            if not (set(plan_sites) & set(allowed)):
                return jsonify({'error': '无权限访问该计划'}), 403
        total = db.execute("SELECT COUNT(*) FROM insp_plan_items WHERE plan_id=? AND COALESCE(execution_status, 'active')='active'", (plan_id,)).fetchone()[0]
        done = db.execute("SELECT COUNT(*) FROM insp_plan_items WHERE plan_id=? AND result IS NOT NULL AND COALESCE(execution_status, 'active')='active'", (plan_id,)).fetchone()[0]
        normal = db.execute("SELECT COUNT(*) FROM insp_plan_items WHERE plan_id=? AND result='normal' AND COALESCE(execution_status, 'active')='active'", (plan_id,)).fetchone()[0]
        abnormal = db.execute("SELECT COUNT(*) FROM insp_plan_items WHERE plan_id=? AND result='abnormal' AND COALESCE(execution_status, 'active')='active'", (plan_id,)).fetchone()[0]
        sites = db.execute("SELECT COUNT(DISTINCT site_id) FROM insp_plan_items WHERE plan_id=? AND COALESCE(execution_status, 'active')='active'", (plan_id,)).fetchone()[0]
        return jsonify({
            'total_items': total, 'completed_items': done,
            'normal_count': normal, 'abnormal_count': abnormal,
            'site_count': sites,
            'completion_rate': round(done / total * 100, 1) if total > 0 else 0,
        })

@app.route('/api/inspection-v2/stats')
def v2_overall_stats():
    """总体统计（按站点范围隔离）"""
    today = datetime.now().strftime('%Y-%m-%d')
    allowed = _filter_site_ids()
    sc = ''
    sp = []
    if allowed is not None:
        sc = f' AND site_id IN ({",".join("?" * len(allowed))})'
        sp = list(allowed)
    plan_filter = ''
    pf = []
    if allowed is not None:
        ph = ','.join('?' * len(allowed))
        plan_filter = f" AND id IN (SELECT plan_id FROM insp_plan_items WHERE site_id IN ({ph}))"
        pf = list(allowed)
    with get_db() as db:
        total_schedules = db.execute(f"SELECT COUNT(*) FROM inspection_schedules WHERE status='active'{sc}", sp).fetchone()[0]
        due_items = db.execute(f"SELECT COUNT(*) FROM inspection_schedules WHERE status='active' AND next_due_date<=?{sc}", (today,) + tuple(sp)).fetchone()[0]
        overdue_items = db.execute(f"SELECT COUNT(*) FROM inspection_schedules WHERE status='active' AND next_due_date<?{sc}", (today,) + tuple(sp)).fetchone()[0]
        upcoming_items = db.execute(f"""
            SELECT COUNT(*) FROM inspection_schedules
            WHERE status='active' AND next_due_date>? AND next_due_date<=date(?, '+7 days'){sc}
        """, (today, today) + tuple(sp)).fetchone()[0]
        total_plans = db.execute(f"SELECT COUNT(*) FROM insp_plans{plan_filter}", pf).fetchone()[0]
        active_plans = db.execute(f"SELECT COUNT(*) FROM insp_plans WHERE status='active'{plan_filter}", pf).fetchone()[0]
        completed_plans = db.execute(f"SELECT COUNT(*) FROM insp_plans WHERE status='completed'{plan_filter}", pf).fetchone()[0]
        total_templates = db.execute("SELECT COUNT(*) FROM inspection_templates WHERE status='active'").fetchone()[0]
        return jsonify({
            'total_schedules': total_schedules,
            'due_items': due_items,
            'overdue_items': overdue_items,
            'upcoming_items': upcoming_items,
            'total_plans': total_plans,
            'active_plans': active_plans,
            'completed_plans': completed_plans,
            'total_templates': total_templates,
            'total_configs': 0,
        })

# ===== 统一待办审核（巡检质控审核 + 工单影像审核） =====
def require_admin():
    """纵深防御：系统级管理动作仅管理员可执行；非管理员直接 403。
    用于补足前端角色门禁（路由守卫 + 菜单隐藏），即使绕过前端直调接口也调不通。"""
    u = g.get('current_user')
    if not _has_any_role(u, 'admin'):
        return jsonify({'success': False, 'error': '需要管理员权限'}), 403
    return None

def require_approver():
    """资源与计划审批仅限管理员。"""
    u = g.get('current_user')
    if not _has_any_role(u, 'admin'):
        return jsonify({'success': False, 'error': '需要管理员权限'}), 403
    return None

def _resolve_period(period, custom_start=None, custom_end=None):
    """统一考核周期解析。返回 (start, end, label, days)。
    支持 month(默认自然月) / 7d / 30d / quarter(本季度) / year(本年度) / custom。"""
    now = datetime.now()
    if period == '7d':
        start_dt = now - timedelta(days=6)
        start = start_dt.strftime('%Y-%m-%d 00:00:00'); end = now.strftime('%Y-%m-%d 23:59:59')
        label = '近7天'
    elif period == '30d':
        start_dt = now - timedelta(days=29)
        start = start_dt.strftime('%Y-%m-%d 00:00:00'); end = now.strftime('%Y-%m-%d 23:59:59')
        label = '近30天'
    elif period == 'quarter':
        q = (now.month - 1) // 3           # 0..3
        qm = q * 3 + 1                      # 季度首月
        start = now.strftime(f'%Y-{qm:02d}-01 00:00:00'); end = now.strftime('%Y-%m-%d 23:59:59')
        label = f'{now.year}年第{q+1}季度'
    elif period == 'year':
        start = now.strftime('%Y-01-01 00:00:00'); end = now.strftime('%Y-%m-%d 23:59:59')
        label = f'{now.year}年度'
    elif period == 'custom' and custom_start and custom_end:
        start = custom_start + ' 00:00:00'; end = custom_end + ' 23:59:59'
        label = custom_start + '~' + custom_end
    else:  # month
        start = now.strftime('%Y-%m-01 00:00:00'); end = now.strftime('%Y-%m-%d 23:59:59')
        label = now.strftime('%Y-%m')
    d0 = datetime.strptime(start[:10], '%Y-%m-%d'); d1 = datetime.strptime(end[:10], '%Y-%m-%d')
    return start, end, label, (d1 - d0).days + 1


_ACTIVE_OPERATOR_WHERE = """u.status='active'
    AND (u.role IN ('operator','inspector') OR ur.role='operator')
    AND COALESCE(u.real_name,'') NOT LIKE '%测试%'
    AND COALESCE(u.real_name,'') NOT LIKE '%体验%'
    AND lower(COALESCE(u.real_name,'')) NOT LIKE '%test%'
    AND lower(COALESCE(u.real_name,'')) NOT LIKE '%demo%'"""


def _active_operator_rows(db, user_id=None):
    """统一返回正式、启用且实际具备运维职责的人员。"""
    where = _ACTIVE_OPERATOR_WHERE
    params = []
    if user_id is not None:
        where += ' AND u.id=?'
        params.append(user_id)
    return db.execute(f"""SELECT DISTINCT u.id, u.real_name, 'operator' AS role
        FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
        WHERE {where} ORDER BY u.real_name""", params).fetchall()


def _report_scope_context(db):
    """Return authorized site ids and a human-readable label for reports."""
    allowed = _filter_site_ids()
    if allowed is None:
        return None, '全部在册站点'
    allowed = sorted({int(site_id) for site_id in allowed})
    if not allowed:
        return [], '未分配站点（无业务数据）'
    placeholders = ','.join('?' for _ in allowed)
    names = [row['name'] for row in db.execute(
        f'SELECT name FROM sites WHERE id IN ({placeholders}) ORDER BY name', allowed,
    ).fetchall()]
    if len(names) <= 5:
        return allowed, '、'.join(names) if names else '已分配站点（当前档案不存在）'
    return allowed, f'已分配 {len(names)} 个站点'


def _site_scope_clause(alias, allowed_site_ids):
    if allowed_site_ids is None:
        return ''
    if not allowed_site_ids:
        return ' AND 1=0'
    ids = ','.join(str(int(site_id)) for site_id in allowed_site_ids)
    return f' AND {alias}.site_id IN ({ids})'


def _operator_scope_clause(allowed_site_ids):
    if allowed_site_ids is None:
        return ''
    if not allowed_site_ids:
        return ' AND 1=0'
    ids = ','.join(str(int(site_id)) for site_id in allowed_site_ids)
    return f''' AND EXISTS (SELECT 1 FROM user_sites report_us
        WHERE report_us.user_id=u.id AND report_us.site_id IN ({ids}))'''


@app.route('/api/evaluation/personnel')
@login_required
def evaluation_personnel():
    """人员评估（运维口径，多维指标）：按人员管理(users.real_name)归一聚合。
    维度：工单处理量/闭环数/闭环率、平均响应时长(h)、平均处理时长(天)、
          SLA超时数、SLA达标率、巡检执行数、巡检审核数。
    已关闭工单按 resolved_at 归期，未关闭工单按 created_at 归期。"""
    period = request.args.get('period', 'month')
    denied = require_reviewer()
    if denied:
        return denied
    start, end, period_label, days = _resolve_period(
        period, request.args.get('start'), request.args.get('end'))
    now_s = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    with get_db() as db:
        allowed_sites, scope_label = _report_scope_context(db)
        wo_scope = _site_scope_clause('w', allowed_sites)
        item_scope = _site_scope_clause('i', allowed_sites)
        operator_scope = _operator_scope_clause(allowed_sites)
        rows = db.execute(f"""
            SELECT DISTINCT u.id, u.real_name, 'operator' AS role, u.phone,
                   -- 已关闭按关单时间归期，未关闭按创建时间归期
                   (SELECT COUNT(*) FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND
                        (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS wo_total,
                   (SELECT COUNT(*) FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed'
                        AND w.resolved_at BETWEEN ? AND ?) AS wo_closed,
                   -- 平均响应时长(小时)：到场签到 - 创建
                   (SELECT AVG((julianday(w.check_in_time)-julianday(w.created_at))*24.0)
                      FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.check_in_time IS NOT NULL
                        AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS response_hours,
                   -- 平均处理时长(天)：关单 - 创建
                   (SELECT AVG(julianday(w.resolved_at)-julianday(w.created_at))
                      FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.resolved_at IS NOT NULL
                        AND w.resolved_at BETWEEN ? AND ?) AS wo_avg_days,
                   -- 已关单 SLA 样本与达标数：只对已经形成结果的工单计算达标率
                   (SELECT COUNT(*) FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed'
                        AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ?) AS closed_sla_sample,
                   (SELECT COUNT(*) FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed'
                        AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ?
                        AND w.resolved_at <= w.sla_deadline) AS closed_sla_met,
                   -- 开放逾期单独作为当前风险，不混入已关单 SLA 达标率
                   (SELECT COUNT(*) FROM work_orders w
                      WHERE w.assignee=u.real_name {wo_scope} AND w.status!='closed'
                        AND w.sla_deadline IS NOT NULL AND w.created_at BETWEEN ? AND ?
                        AND ? > w.sla_deadline) AS open_overdue,
                   -- 巡检执行数：本人负责计划下已完成检查项
                   (SELECT COUNT(*) FROM insp_plan_items i
                      JOIN insp_plans p ON i.plan_id=p.id
                      WHERE p.assignee_id=u.id {item_scope} AND i.completed_at BETWEEN ? AND ?) AS insp_done,
                   -- 巡检审核数
                   (SELECT COUNT(*) FROM insp_plan_items i
                      WHERE i.reviewer_id=u.id {item_scope} AND i.review_time BETWEEN ? AND ?) AS insp_reviewed
            FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
            WHERE {_ACTIVE_OPERATOR_WHERE} {operator_scope}
            ORDER BY u.real_name
        """, (start, end, start, end, start, end, start, end,
              start, end, start, end, start, end, now_s,
              start, end, start, end)).fetchall()

    result = []
    for r in rows:
        d = dict(r)
        total = d.get('wo_total') or 0
        closed = d.get('wo_closed') or 0
        sla_sample = d.get('closed_sla_sample') or 0
        sla_met = d.get('closed_sla_met') or 0
        closed_breach = max(0, sla_sample - sla_met)
        open_overdue = d.get('open_overdue') or 0
        d['wo_closed_rate'] = round(closed / total * 100, 1) if total else None
        d['on_time_rate'] = round(sla_met / sla_sample * 100, 1) if sla_sample else None
        d['response_hours'] = round(d['response_hours'], 1) if d.get('response_hours') is not None else None
        d['wo_avg_days'] = round(d['wo_avg_days'], 1) if d.get('wo_avg_days') is not None else None
        d['closed_sla_breach'] = closed_breach
        d['sla_breach'] = closed_breach + open_overdue
        result.append(d)

    # 人均概览
    n = len(result) or 1
    overview = {
        'staff_count': len(result),
        'wo_total': sum(d['wo_total'] for d in result),
        'wo_closed': sum(d['wo_closed'] for d in result),
        'closed_sla_sample': sum(d['closed_sla_sample'] for d in result),
        'closed_sla_met': sum(d['closed_sla_met'] for d in result),
        'closed_sla_breach': sum(d['closed_sla_breach'] for d in result),
        'open_overdue': sum(d['open_overdue'] for d in result),
        'sla_breach': sum(d['sla_breach'] for d in result),
        'insp_done': sum(d['insp_done'] for d in result),
    }
    overview['closed_rate'] = round(overview['wo_closed'] / overview['wo_total'] * 100, 1) if overview['wo_total'] else None
    overview['on_time_rate'] = round(overview['closed_sla_met'] / overview['closed_sla_sample'] * 100, 1) if overview['closed_sla_sample'] else None
    _resp = [d['response_hours'] for d in result if d['response_hours'] is not None]
    overview['avg_response_hours'] = round(sum(_resp) / len(_resp), 1) if _resp else None

    return jsonify({
        'period': period, 'period_label': period_label, 'days': days,
        'scope_label': scope_label, 'overview': overview, 'list': result,
    })


# =============================================================================
# Excel 导出（xlsx）+ 季度/年度运维报告
# =============================================================================
def _xlsx_send(wb, filename):
    """将 openpyxl Workbook 作为 xlsx 文件下载返回。"""
    if not _HAS_OPENPYXL:
        return jsonify({'success': False, 'error': '缺少 openpyxl，无法导出'}), 500
    tmp_path = os.path.join(tempfile.gettempdir(), filename)
    wb.save(tmp_path)
    return send_file(tmp_path, mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                     as_attachment=True, download_name=filename)


def _set_header_style(cell):
    cell.font = Font(bold=True, color='FFFFFF')
    cell.fill = PatternFill('solid', fgColor='2B6CFF')
    cell.alignment = Alignment(horizontal='center', vertical='center')


def _init_report_table(ws, title, start, end, column_count, scope='当前账号权限范围'):
    ws.append([title])
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=column_count)
    ws['A1'].font = Font(bold=True, size=16, color='1F2937')
    ws['A1'].alignment = Alignment(horizontal='center')
    ws.append(['统计周期', f'{start[:10]} 至 {end[:10]}'])
    ws.append(['生成时间', datetime.now().strftime('%Y-%m-%d %H:%M:%S')])
    ws.append(['统计范围', scope])
    ws.append(['工单归期口径', '已关闭按关单时间，未关闭按创建时间'])
    ws.append([])
    ws.freeze_panes = 'A7'
    ws.sheet_view.showGridLines = False
    ws.page_setup.orientation = 'landscape'
    ws.page_setup.fitToWidth = 1
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    return 7


def _finish_report_table(ws, header_row, max_width=36):
    if ws.max_row >= header_row:
        ws.auto_filter.ref = f'A{header_row}:{get_column_letter(ws.max_column)}{ws.max_row}'
        ws.print_title_rows = f'1:{header_row}'
        ws.print_area = f'A1:{get_column_letter(ws.max_column)}{ws.max_row}'
    for index, column in enumerate(ws.columns, start=1):
        values = [len(str(cell.value or '')) for cell in column]
        ws.column_dimensions[get_column_letter(index)].width = min(max_width, max(10, max(values, default=0) + 2))


def _build_work_orders_export(db, start, end, site_id=None, status=None, assignee=None,
                              allowed_site_ids=None):
    """构造工单导出数据：已关闭按关单时间，未关闭按创建时间归期。"""
    params = [start, end]
    where = """WHERE (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL
                       THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?"""
    where += _site_scope_clause('w', allowed_site_ids)
    if site_id:
        where += " AND w.site_id=?"; params.append(int(site_id))
    if status:
        where += " AND w.status=?"; params.append(status)
    if assignee:
        where += " AND w.assignee=?"; params.append(assignee)
    rows = db.execute(f"""
        SELECT w.order_no, s.name as site_name, w.title, w.event_type, w.level,
               w.assignee, w.status, w.created_at, w.check_in_time, w.resolved_at,
               w.sla_deadline, w.description
        FROM work_orders w LEFT JOIN sites s ON w.site_id=s.id
        {where} ORDER BY w.created_at DESC
    """, params).fetchall()
    data = [dict(r) for r in rows]
    status_cn = {'pending':'待处理','accepted':'已接受','dispatched':'已派发','in_progress':'处理中',
                 'reviewing':'审核中','acceptance':'验收中','resolved':'已解决','closed':'已关闭'}
    level_cn = {'normal':'普通','urgent':'紧急','critical':'严重'}
    for d in data:
        d['status_cn'] = status_cn.get(d['status'], d['status'])
        d['level_cn'] = level_cn.get(d['level'], d['level'])
    return data


@app.route('/api/export/work-orders')
@login_required
def export_work_orders():
    """导出工单列表为 xlsx。参数：period(default month)/start/end/site_id/status/assignee。"""
    if not _HAS_OPENPYXL:
        return jsonify({'success': False, 'error': '缺少 openpyxl'}), 500
    period = request.args.get('period', 'month')
    start, end, label, _ = _resolve_period(period, request.args.get('start'), request.args.get('end'))
    site_id = request.args.get('site_id')
    status = request.args.get('status')
    assignee = request.args.get('assignee')

    with get_db() as db:
        allowed_sites, _ = _report_scope_context(db)
        if site_id and allowed_sites is not None and int(site_id) not in allowed_sites:
            return jsonify({'error': '无权限导出非本人负责站点工单'}), 403
        data = _build_work_orders_export(
            db, start, end, site_id, status, assignee, allowed_site_ids=allowed_sites)

    wb = Workbook()
    ws = wb.active
    ws.title = '工单明细'
    headers = ['工单编号','站点','标题','事件类型','等级','负责人','状态','创建时间','到场时间','关单时间','SLA截止','描述']
    keys = ['order_no','site_name','title','event_type','level_cn','assignee','status_cn','created_at','check_in_time','resolved_at','sla_deadline','description']
    ws.append(headers)
    for c in ws[1]: _set_header_style(c)
    for d in data:
        ws.append([d.get(k, '') or '' for k in keys])
    for col in ws.columns:
        ws.column_dimensions[col[0].column_letter].width = min(36, max(10, len(str(col[0].value)) + 4))
    filename = f"工单明细_{label}.xlsx"
    return _xlsx_send(wb, filename)


@app.route('/api/export/inspection-records')
@login_required
def export_inspection_records():
    """导出巡检记录为 xlsx。参数：period(default month)/start/end。"""
    if not _HAS_OPENPYXL:
        return jsonify({'success': False, 'error': '缺少 openpyxl'}), 500
    period = request.args.get('period', 'month')
    start, end, label, _ = _resolve_period(period, request.args.get('start'), request.args.get('end'))
    with get_db() as db:
        allowed_sites, _ = _report_scope_context(db)
        item_scope = _site_scope_clause('i', allowed_sites)
        rows = db.execute(f"""
            SELECT p.plan_name, s.name as site_name, i.item_name, i.category, i.frequency,
                   i.result, i.check_time, i.completed_at, i.review_status, i.actual_photos,
                   i.remark
            FROM insp_plan_items i
            JOIN insp_plans p ON i.plan_id=p.id
            JOIN sites s ON i.site_id=s.id
            WHERE ((i.completed_at BETWEEN ? AND ?) OR (i.check_time BETWEEN ? AND ?))
              {item_scope}
            ORDER BY i.completed_at DESC, i.check_time DESC
        """, (start, end, start, end)).fetchall()
        data = [dict(r) for r in rows]
    review_cn = {1:'待审核',2:'已通过',3:'已驳回'}
    result_cn = {'normal':'正常','abnormal':'异常'}
    for d in data:
        d['review_status_cn'] = review_cn.get(d.get('review_status'), d.get('review_status') or '—')
        d['result_cn'] = result_cn.get(d.get('result'), d.get('result') or '—')

    wb = Workbook(); ws = wb.active; ws.title = '巡检记录'
    headers = ['巡检计划','站点','检查项','分类','频次','结果','检查时间','完成时间','审核状态','拍照数','备注']
    keys = ['plan_name','site_name','item_name','category','frequency','result_cn','check_time','completed_at','review_status_cn','actual_photos','remark']
    ws.append(headers)
    for c in ws[1]: _set_header_style(c)
    for d in data: ws.append([d.get(k, '') or '' for k in keys])
    for col in ws.columns:
        ws.column_dimensions[col[0].column_letter].width = min(36, max(10, len(str(col[0].value)) + 4))
    filename = f"巡检记录_{label}.xlsx"
    return _xlsx_send(wb, filename)


@app.route('/api/export/evaluation')
@login_required
def export_evaluation():
    denied = require_reviewer()
    if denied: return denied
    """导出人员评估报表为 xlsx。参数：period(default month)。"""
    if not _HAS_OPENPYXL:
        return jsonify({'success': False, 'error': '缺少 openpyxl'}), 500
    period = request.args.get('period', 'month')
    start, end, label, _ = _resolve_period(period, request.args.get('start'), request.args.get('end'))
    now_s = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    role_order = {'manager':0,'operator':1,'inspector':2}
    with get_db() as db:
        allowed_sites, scope_label = _report_scope_context(db)
        wo_scope = _site_scope_clause('w', allowed_sites)
        item_scope = _site_scope_clause('i', allowed_sites)
        operator_scope = _operator_scope_clause(allowed_sites)
        rows = db.execute(f"""
            SELECT DISTINCT u.id, u.real_name, 'operator' AS role, u.phone,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS wo_total,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.resolved_at BETWEEN ? AND ?) AS wo_closed,
                   (SELECT AVG((julianday(w.check_in_time)-julianday(w.created_at))*24.0)
                      FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.check_in_time IS NOT NULL AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS response_hours,
                   (SELECT AVG(julianday(w.resolved_at)-julianday(w.created_at))
                      FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.resolved_at BETWEEN ? AND ?) AS wo_avg_days,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ?) AS closed_sla_sample,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ? AND w.resolved_at <= w.sla_deadline) AS closed_sla_met,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status!='closed' AND w.sla_deadline IS NOT NULL AND w.created_at BETWEEN ? AND ? AND ? > w.sla_deadline) AS open_overdue,
                   (SELECT COUNT(*) FROM insp_plan_items i JOIN insp_plans p ON i.plan_id=p.id
                      WHERE p.assignee_id=u.id {item_scope} AND i.completed_at BETWEEN ? AND ?) AS insp_done,
                   (SELECT COUNT(*) FROM insp_plan_items i
                      WHERE i.reviewer_id=u.id {item_scope} AND i.review_time BETWEEN ? AND ?) AS insp_reviewed
            FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
            WHERE {_ACTIVE_OPERATOR_WHERE} {operator_scope}
            ORDER BY u.real_name
        """, (start, end, start, end, start, end, start, end,
              start, end, start, end, start, end, now_s,
              start, end, start, end)).fetchall()
        data = []
        for r in rows:
            d = dict(r)
            total = d.get('wo_total') or 0
            closed = d.get('wo_closed') or 0
            sla_sample = d.get('closed_sla_sample') or 0
            sla_met = d.get('closed_sla_met') or 0
            d['wo_closed_rate'] = round(closed / total * 100, 1) if total else None
            d['closed_sla_breach'] = max(0, sla_sample - sla_met)
            d['on_time_rate'] = round(sla_met / sla_sample * 100, 1) if sla_sample else None
            data.append(d)

    role_cn = {'manager':'主管','operator':'运维员','inspector':'审核员'}
    wb = Workbook(); ws = wb.active; ws.title = '人员评估'
    header_row = _init_report_table(ws, '人员运维绩效评估', start, end, 13, scope_label)
    headers = ['姓名','角色','工单处理','闭环数','闭环率(%)','平均响应(h)','平均处理(天)','已关单SLA样本','已关单超时','SLA达标率(%)','开放已逾期','巡检执行','巡检审核']
    ws.append(headers)
    for c in ws[header_row]: _set_header_style(c)
    for d in data:
        ws.append([
            d['real_name'], role_cn.get(d['role'], d['role']), d['wo_total'], d['wo_closed'],
            d['wo_closed_rate'] if d['wo_closed_rate'] is not None else '无样本', d['response_hours'] if d['response_hours'] is not None else '—',
            d['wo_avg_days'] if d['wo_avg_days'] is not None else '—',
            d['closed_sla_sample'], d['closed_sla_breach'], d['on_time_rate'] if d['on_time_rate'] is not None else '无样本',
            d['open_overdue'], d['insp_done'], d['insp_reviewed']
        ])
    _finish_report_table(ws, header_row, max_width=24)
    for column, width in {'E': 14, 'F': 16, 'G': 17, 'H': 18, 'I': 14, 'J': 16, 'K': 14}.items():
        ws.column_dimensions[column].width = width
    filename = f"人员评估_{label}.xlsx"
    return _xlsx_send(wb, filename)


@app.route('/api/export/ops-report')
@login_required
def export_ops_report():
    denied = require_reviewer()
    if denied: return denied
    """Generate one deterministic Chinese Word report; no model-generated conclusions."""
    if not _HAS_PYTHON_DOCX:
        return jsonify({'success': False, 'error': '缺少 python-docx，无法生成工作报告'}), 500
    period = request.args.get('period', 'quarter')
    start, end, label, days = _resolve_period(
        period, request.args.get('start'), request.args.get('end'))
    with get_db() as db:
        allowed_sites, scope_label = _report_scope_context(db)
        if allowed_sites is None:
            site_scope = ''
        elif allowed_sites:
            site_scope = ' AND s.id IN ({})'.format(
                ','.join(str(int(site_id)) for site_id in allowed_sites))
        else:
            site_scope = ' AND 1=0'
        wo_scope = _site_scope_clause('w', allowed_sites)
        item_scope = _site_scope_clause('i', allowed_sites)
        site_total = db.execute(f'SELECT COUNT(*) FROM sites s WHERE 1=1 {site_scope}').fetchone()[0]
        wo_total = db.execute("""SELECT COUNT(*) FROM work_orders w
            WHERE (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL
                        THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?""" + wo_scope,
            (start, end)).fetchone()[0]
        wo_closed = db.execute(
            f"SELECT COUNT(*) FROM work_orders w WHERE w.status='closed' AND w.resolved_at BETWEEN ? AND ? {wo_scope}",
            (start, end)).fetchone()[0]
        open_orders = db.execute(
            f"SELECT COUNT(*) FROM work_orders w WHERE w.status!='closed' {wo_scope}").fetchone()[0]
        inspection_done = db.execute(
            f'SELECT COUNT(*) FROM insp_plan_items i WHERE i.completed_at BETWEEN ? AND ? {item_scope}',
            (start, end)).fetchone()[0]
        abnormal = db.execute(
            f"SELECT COUNT(*) FROM insp_plan_items i WHERE i.result='abnormal' AND i.completed_at BETWEEN ? AND ? {item_scope}",
            (start, end)).fetchone()[0]
        pending_alerts = db.execute(
            'SELECT COUNT(*) FROM alerts a WHERE a.status=\'pending\'' + _site_scope_clause('a', allowed_sites)).fetchone()[0]
        people = db.execute(f"""SELECT DISTINCT u.real_name,
                (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope}
                 AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS workorders,
                (SELECT COUNT(*) FROM insp_plan_items i JOIN insp_plans p ON p.id=i.plan_id
                 WHERE p.assignee_id=u.id {item_scope} AND i.completed_at BETWEEN ? AND ?) AS inspections
            FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
            WHERE {_ACTIVE_OPERATOR_WHERE} ORDER BY u.real_name""",
            (start, end, start, end)).fetchall()

    document = Document()
    title = document.add_heading('水质运维工作报告', 0)
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    subtitle = document.add_paragraph(f'{label}\n{start[:10]} 至 {end[:10]}\n{scope_label}')
    subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER
    document.add_page_break()

    document.add_heading('一、工作摘要', level=1)
    document.add_paragraph(
        f'本周期共 {days} 天，覆盖 {site_total} 个授权站点；完成巡检 {inspection_done} 项，'
        f'记录工单 {wo_total} 张，其中闭环 {wo_closed} 张。')
    document.add_heading('二、巡检情况', level=1)
    document.add_paragraph(f'已完成检查项 {inspection_done} 项，其中异常结果 {abnormal} 项。')
    document.add_heading('三、工单与异常', level=1)
    document.add_paragraph(f'周期内工单 {wo_total} 张，已闭环 {wo_closed} 张；当前未闭环 {open_orders} 张。')
    document.add_heading('四、站点风险', level=1)
    document.add_paragraph(f'当前待处理告警 {pending_alerts} 条；该数字仅表示系统内仍未处理记录。')
    document.add_heading('五、人员客观指标', level=1)
    table = document.add_table(rows=1, cols=3)
    table.style = 'Table Grid'
    for cell, value in zip(table.rows[0].cells, ('人员', '周期工单', '完成巡检项')):
        cell.text = value
    for person in people:
        cells = table.add_row().cells
        cells[0].text = person['real_name'] or '未命名'
        cells[1].text = str(person['workorders'] or 0)
        cells[2].text = str(person['inspections'] or 0)
    document.add_heading('六、未闭环事项', level=1)
    document.add_paragraph(f'未闭环工单 {open_orders} 张；待处理告警 {pending_alerts} 条。')
    document.add_heading('七、下周期建议', level=1)
    deterministic = []
    if open_orders: deterministic.append('逐项确认未闭环工单的负责人、下一动作和截止时间。')
    if pending_alerts: deterministic.append('优先复核仍处于待处理状态的告警。')
    if abnormal: deterministic.append('对本周期异常检查项确认工单或复查闭环。')
    document.add_paragraph(''.join(deterministic) or '当前数据未触发额外处置建议，按既定计划执行。')
    document.add_heading('八、指标口径附录', level=1)
    document.add_paragraph('工单按已关闭记录的关单时间、未关闭记录的创建时间归期；巡检按检查项完成时间归期；所有数量均受当前账号站点权限约束。')
    for style in document.styles:
        if style.name.startswith('Heading') or style.name == 'Normal':
            style.font.name = 'Microsoft YaHei'
            style.font.size = Pt(10.5 if style.name == 'Normal' else 14)
    output = BytesIO(); document.save(output); output.seek(0)
    return send_file(output, as_attachment=True, download_name='水质运维工作报告.docx',
                     mimetype='application/vnd.openxmlformats-officedocument.wordprocessingml.document')


@app.route('/api/export/ops-report-details')
@login_required
def export_ops_report_details():
    denied = require_reviewer()
    if denied: return denied
    """Optional detailed Excel attachment for the work report."""
    if not _HAS_OPENPYXL:
        return jsonify({'success': False, 'error': '缺少 openpyxl'}), 500
    period = request.args.get('period', 'quarter')
    start, end, label, days = _resolve_period(period, request.args.get('start'), request.args.get('end'))
    now_s = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    wb = Workbook()
    # 移除默认 sheet，后续按需创建
    wb.remove(wb.active)

    with get_db() as db:
        allowed_sites, scope_label = _report_scope_context(db)
        if allowed_sites is None:
            site_scope = ''
        elif allowed_sites:
            site_scope = ' AND s.id IN ({})'.format(','.join(str(site_id) for site_id in allowed_sites))
        else:
            site_scope = ' AND 1=0'
        alert_scope = _site_scope_clause('alerts', allowed_sites)
        wo_scope = _site_scope_clause('w', allowed_sites)
        item_scope = _site_scope_clause('insp_plan_items', allowed_sites)
        operator_scope = _operator_scope_clause(allowed_sites)
        # ---- Sheet 1: 概览 ----
        ws1 = wb.create_sheet('概览')
        site_total = db.execute(f"SELECT COUNT(*) FROM sites s WHERE 1=1 {site_scope}").fetchone()[0]
        sites_online = db.execute(f"SELECT COUNT(*) FROM sites s WHERE status='normal' {site_scope}").fetchone()[0]
        alerts_total = db.execute(f"SELECT COUNT(*) FROM alerts WHERE created_at BETWEEN ? AND ? {alert_scope}", (start, end)).fetchone()[0]
        alerts_pending = db.execute(f"SELECT COUNT(*) FROM alerts WHERE status='pending' AND created_at BETWEEN ? AND ? {alert_scope}", (start, end)).fetchone()[0]
        wo_total = db.execute("""SELECT COUNT(*) FROM work_orders
            w WHERE (CASE WHEN status='closed' AND resolved_at IS NOT NULL THEN resolved_at ELSE created_at END) BETWEEN ? AND ?""" + wo_scope, (start, end)).fetchone()[0]
        wo_closed = db.execute(f"SELECT COUNT(*) FROM work_orders w WHERE status='closed' AND resolved_at BETWEEN ? AND ? {wo_scope}", (start, end)).fetchone()[0]
        insp_done = db.execute(f"SELECT COUNT(*) FROM insp_plan_items WHERE completed_at BETWEEN ? AND ? {item_scope}", (start, end)).fetchone()[0]
        overview_rows = [
            [f'水质智慧运维报告（{label}）', ''],
            ['统计周期', f'{start[:10]} 至 {end[:10]}'],
            ['生成时间', datetime.now().strftime('%Y-%m-%d %H:%M:%S')],
            ['统计范围', scope_label],
            ['工单归期口径', '已关闭按关单时间，未关闭按创建时间'],
            ['统计周期天数', days],
            ['站点总数', site_total],
            ['在线站点', sites_online],
            ['告警总数', alerts_total],
            ['待处理告警', alerts_pending],
            ['工单总数', wo_total],
            ['已闭环工单', wo_closed],
            ['闭环率(%)', round(wo_closed / wo_total * 100, 1) if wo_total else 0],
            ['巡检完成项', insp_done],
        ]
        for r in overview_rows:
            ws1.append(r)
        ws1.merge_cells('A1:B1')
        ws1['A1'].font = Font(bold=True, size=16)
        ws1['A1'].alignment = Alignment(horizontal='center')
        ws1.sheet_view.showGridLines = False
        ws1.column_dimensions['A'].width = 22
        ws1.column_dimensions['B'].width = 48
        ws1.print_area = f'A1:B{ws1.max_row}'

        # ---- Sheet 2: 人员绩效 ----
        ws2 = wb.create_sheet('人员绩效')
        header_row2 = _init_report_table(ws2, '人员运维绩效', start, end, 13, scope_label)
        headers2 = ['姓名','角色','工单处理','闭环数','闭环率(%)','平均响应(h)','平均处理(天)','已关单SLA样本','已关单超时','SLA达标率(%)','开放已逾期','巡检执行','巡检审核']
        ws2.append(headers2)
        for c in ws2[header_row2]: _set_header_style(c)
        rows = db.execute(f"""
            SELECT DISTINCT u.real_name, 'operator' AS role,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS wo_total,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.resolved_at BETWEEN ? AND ?) AS wo_closed,
                   (SELECT AVG((julianday(w.check_in_time)-julianday(w.created_at))*24.0)
                      FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.check_in_time IS NOT NULL AND (CASE WHEN w.status='closed' AND w.resolved_at IS NOT NULL THEN w.resolved_at ELSE w.created_at END) BETWEEN ? AND ?) AS response_hours,
                   (SELECT AVG(julianday(w.resolved_at)-julianday(w.created_at))
                      FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.resolved_at BETWEEN ? AND ?) AS wo_avg_days,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ?) AS closed_sla_sample,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status='closed' AND w.sla_deadline IS NOT NULL AND w.resolved_at BETWEEN ? AND ? AND w.resolved_at <= w.sla_deadline) AS closed_sla_met,
                   (SELECT COUNT(*) FROM work_orders w WHERE w.assignee=u.real_name {wo_scope} AND w.status!='closed' AND w.sla_deadline IS NOT NULL AND w.created_at BETWEEN ? AND ? AND ? > w.sla_deadline) AS open_overdue,
                   (SELECT COUNT(*) FROM insp_plan_items i JOIN insp_plans p ON i.plan_id=p.id
                      WHERE p.assignee_id=u.id {_site_scope_clause('i', allowed_sites)} AND i.completed_at BETWEEN ? AND ?) AS insp_done,
                   (SELECT COUNT(*) FROM insp_plan_items i
                      WHERE i.reviewer_id=u.id {_site_scope_clause('i', allowed_sites)} AND i.review_time BETWEEN ? AND ?) AS insp_reviewed
            FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
            WHERE {_ACTIVE_OPERATOR_WHERE} {operator_scope}
            ORDER BY u.real_name
        """, (start, end, start, end, start, end, start, end,
              start, end, start, end, start, end, now_s,
              start, end, start, end)).fetchall()
        role_cn = {'manager':'主管','operator':'运维员','inspector':'审核员'}
        for r in rows:
            d = dict(r); total = d['wo_total'] or 0; closed = d['wo_closed'] or 0
            sla_sample = d['closed_sla_sample'] or 0
            sla_met = d['closed_sla_met'] or 0
            closed_breach = max(0, sla_sample - sla_met)
            ws2.append([
                d['real_name'], role_cn.get(d['role'], d['role']), total, closed,
                round(closed / total * 100, 1) if total else '无样本',
                round(d['response_hours'], 1) if d['response_hours'] is not None else '—',
                round(d['wo_avg_days'], 1) if d['wo_avg_days'] is not None else '—',
                sla_sample, closed_breach,
                round(sla_met / sla_sample * 100, 1) if sla_sample else '无样本',
                d['open_overdue'] or 0,
                d['insp_done'] or 0, d['insp_reviewed'] or 0
            ])
        _finish_report_table(ws2, header_row2, max_width=24)
        for column, width in {'E': 14, 'F': 16, 'G': 17, 'H': 18, 'I': 14, 'J': 16, 'K': 14}.items():
            ws2.column_dimensions[column].width = width

        # ---- Sheet 3: 工单明细 ----
        ws3 = wb.create_sheet('工单明细')
        wo_data = _build_work_orders_export(db, start, end, allowed_site_ids=allowed_sites)
        header_row3 = _init_report_table(ws3, '工单明细', start, end, 11, scope_label)
        headers3 = ['工单编号','站点','标题','事件类型','等级','负责人','状态','创建时间','到场时间','关单时间','SLA截止']
        ws3.append(headers3)
        for c in ws3[header_row3]: _set_header_style(c)
        for d in wo_data:
            ws3.append([d.get(k, '') or '' for k in ['order_no','site_name','title','event_type','level_cn','assignee','status_cn','created_at','check_in_time','resolved_at','sla_deadline']])
        _finish_report_table(ws3, header_row3)

        # ---- Sheet 4: 站点健康度（按阈值实时判定异常/超限） ----
        ws4 = wb.create_sheet('站点健康度')
        header_row4 = _init_report_table(ws4, '站点数据健康度', start, end, 8, scope_label)
        ws4.append(['站点','负责人','应报数','异常数','正常数','缺失','超限','健康度(%)'])
        for c in ws4[header_row4]: _set_header_style(c)
        site_rows = db.execute(f"SELECT id, name, manager, type FROM sites s WHERE 1=1 {site_scope} ORDER BY id").fetchall()
        report_start = datetime.strptime(start, '%Y-%m-%d %H:%M:%S')
        report_end = datetime.strptime(end, '%Y-%m-%d %H:%M:%S')
        actual_rows = db.execute(f"""SELECT site_id, metric, COUNT(*) AS actual
            FROM sensor_data sd WHERE recorded_at BETWEEN ? AND ? {_site_scope_clause('sd', allowed_sites)} GROUP BY site_id, metric""", (start, end)).fetchall()
        actual_map = {(row['site_id'], row['metric']): row['actual'] for row in actual_rows}
        over_rows = db.execute(f"""SELECT sd.site_id, sd.metric, COUNT(*) AS over_count
            FROM sensor_data sd JOIN param_thresholds pt ON pt.metric=sd.metric
            WHERE sd.recorded_at BETWEEN ? AND ? {_site_scope_clause('sd', allowed_sites)} AND (sd.value < pt.low OR sd.value > pt.high)
            GROUP BY sd.site_id, sd.metric""", (start, end)).fetchall()
        over_map = {(row['site_id'], row['metric']): row['over_count'] for row in over_rows}
        monitored_sites, observed_metrics = _monitoring_metric_context(db)
        for s in site_rows:
            expected = 0
            missing = 0
            over_limit = 0
            site_metrics = set(observed_metrics.get(s['id'], set())) if s['id'] in monitored_sites else set()
            for metric in site_metrics:
                frequency = _STANDARD_DAILY_COUNT.get((s['type'], metric), 12)
                metric_expected = _expected_samples_for_period(
                    frequency, report_start, report_end, datetime.now())
                metric_actual = actual_map.get((s['id'], metric), 0)
                expected += metric_expected
                missing += max(0, metric_expected - metric_actual)
                over_limit += over_map.get((s['id'], metric), 0)
            abnormal = min(expected, missing + over_limit)
            normal = max(0, expected - abnormal)
            rate = (
                round(normal / expected * 100, 1) if expected else
                '参数未配置' if s['id'] in monitored_sites else
                '未启用监测'
            )
            ws4.append([s['name'], s['manager'] or '—', expected, abnormal, normal, missing, over_limit, rate])
        _finish_report_table(ws4, header_row4, max_width=24)

        # ---- Sheet 5: 告警统计 ----
        ws5 = wb.create_sheet('告警统计')
        header_row5 = _init_report_table(ws5, '告警统计', start, end, 4, scope_label)
        ws5.append(['指标','等级','状态','数量'])
        for c in ws5[header_row5]: _set_header_style(c)
        alert_rows = db.execute(f"""
            SELECT metric, level, status, COUNT(*) as cnt
            FROM alerts WHERE created_at BETWEEN ? AND ? {alert_scope}
            GROUP BY metric, level, status
            ORDER BY cnt DESC
        """, (start, end)).fetchall()
        metric_cn = {'codmn':'高锰酸盐指数','ammonia':'氨氮','total_phosphorus':'总磷','total_nitrogen':'总氮',
                     'water_temp':'水温','dissolved_oxygen':'溶解氧','ph':'pH','turbidity':'浊度',
                     'conductivity':'电导率','device_status':'设备状态','data_gap':'数据缺失','data_freeze':'数据冻结','data_spike':'数据突变'}
        level_cn = {'red':'红色','orange':'橙色','yellow':'黄色','blue':'蓝色'}
        status_cn = {'pending':'待处理','acknowledged':'已确认','resolved':'已解决'}
        for r in alert_rows:
            d = dict(r)
            ws5.append([metric_cn.get(d['metric'], d['metric']), level_cn.get(d['level'], d['level']),
                        status_cn.get(d['status'], d['status']), d['cnt']])
        _finish_report_table(ws5, header_row5, max_width=24)

    filename = f"运维报告_{label}.xlsx"
    return _xlsx_send(wb, filename)


def _vehicle_application_audit_association(db, application):
    """Return only verified work, remediation, and schedule links for an application."""
    row = dict(application or {})
    association = {
        'work_order_no': row.get('work_order_no') or '',
        'rework_plan_id': row.get('rework_plan_id'),
        'plan_schedule_id': None,
        'plan_name': '',
    }
    if association['rework_plan_id']:
        try:
            plan = db.execute(
                'SELECT plan_name FROM insp_plans WHERE id=?',
                (association['rework_plan_id'],),
            ).fetchone()
        except sqlite3.OperationalError:
            plan = None
        if plan:
            association['plan_name'] = plan['plan_name'] or ''

    schedule_id = _vehicle_application_schedule_id(db, row)
    if schedule_id:
        try:
            schedule = db.execute(
                'SELECT id FROM plan_schedules WHERE id=?', (schedule_id,)
            ).fetchone()
        except sqlite3.OperationalError:
            schedule = None
        if schedule:
            association['plan_schedule_id'] = schedule['id']
    return association


def _plan_schedule_requester_name(db, schedule_id):
    """Return the user who submitted the current plan approval request."""
    try:
        row = db.execute("""
            SELECT u.real_name
            FROM plan_schedule_events pse
            LEFT JOIN users u ON u.id=pse.operator_id
            WHERE pse.schedule_id=? AND pse.event_type IN ('submitted', 'change_submitted')
            ORDER BY pse.id DESC LIMIT 1
        """, (schedule_id,)).fetchone()
    except sqlite3.OperationalError:
        row = None
    return (row['real_name'] or '') if row else ''


def _plan_schedule_requester(db, schedule_id):
    try:
        return db.execute("""SELECT pse.id,pse.operator_id,u.real_name,pse.created_at
            FROM plan_schedule_events pse LEFT JOIN users u ON u.id=pse.operator_id
            WHERE pse.schedule_id=? AND pse.event_type IN ('submitted','change_submitted')
            ORDER BY pse.id DESC LIMIT 1""", (schedule_id,)).fetchone()
    except sqlite3.OperationalError:
        return None


def _wx_plan_project(row, schedule_id):
    value = dict(row or {})
    frequency = _PS_FREQ_CN.get(value.get('schedule_type'), '巡检')
    period = '~'.join(part for part in (
        str(value.get('period_start') or '').strip(),
        str(value.get('period_end') or '').strip()) if part)
    return _wx_trim(f'{frequency}计划 {period}'.strip() or f'巡检计划{schedule_id}', 20)


def _legacy_spare_part_audit_items(db, allowed_site_ids):
    """Expose pending legacy requests with the same shape as parts_requests."""
    try:
        rows = db.execute("""
            SELECT spr.*, s.name AS site_name
            FROM spare_part_requests spr
            LEFT JOIN sites s ON s.id=spr.site_id
            WHERE spr.status='pending'
            ORDER BY spr.created_at DESC, spr.id DESC
        """).fetchall()
    except sqlite3.OperationalError:
        return []

    items = []
    for row in rows:
        item = dict(row)
        site_id = item.get('site_id')
        if allowed_site_ids is not None and site_id not in allowed_site_ids:
            continue
        part = None
        spare_part_id = item.get('spare_part_id')
        if spare_part_id:
            try:
                part = db.execute(
                    "SELECT part_code, manufacturer, model FROM spare_parts_inventory WHERE id=?",
                    (spare_part_id,),
                ).fetchone()
            except sqlite3.OperationalError:
                part = None
        part = dict(part) if part else {}
        part_sku = part.get('part_code') or item.get('part_name') or ''
        part_detail = {
            'part_sku': part_sku,
            'part_name': item.get('part_name') or part_sku,
            'manufacturer': part.get('manufacturer') or '',
            'model': part.get('model') or '',
            'quantity': int(item.get('quantity') or 0),
        }
        request_no = item.get('request_no') or f'备件申请#{item.get("id")}'
        items.append({
            **item,
            'source_type': 'spare_part_request',
            'source_label': '备件申请',
            'id': f'spr_{item["id"]}',
            'request_id': item['id'],
            'title': f'库存领用（{item.get("part_name") or "备件"}）',
            'source_name': request_no,
            'requester_name': item.get('applicant') or '',
            'applicant': item.get('applicant') or '',
            'fulfillment_type': 'stock',
            'fulfillment_label': '库存领用',
            'part_sku': part_sku,
            'parts_detail': [part_detail],
            'actual_photos': 0,
            'required_photos': 0,
            'remark': item.get('reason') or '',
            'submit_time': item.get('created_at') or '',
        })
    return items


def _parts_request_audit_item(db, request_id):
    """Build one pending v2 request in the same shape as /audit/pending."""
    row = db.execute("""
        SELECT pr.id, pr.plan_id, pr.site_id, pr.work_order_no, pr.request_no, pr.reason,
               pr.fulfillment_type, pr.requested_part_name, pr.specification, pr.estimated_amount,
               pr.requester_id, pr.created_at as submit_time, p.plan_name, s.name AS site_name,
               u.real_name as requester_name
        FROM parts_requests pr
        LEFT JOIN insp_plans p ON pr.plan_id = p.id
        LEFT JOIN sites s ON s.id=pr.site_id
        LEFT JOIN users u ON pr.requester_id = u.id
        WHERE pr.id=? AND pr.status='pending'
    """, (request_id,)).fetchone()
    if not row:
        return None

    item = dict(row)
    site_row = db.execute("""
        SELECT s.id as site_id, s.name FROM insp_plan_items i JOIN sites s ON i.site_id = s.id
        WHERE i.plan_id = ? LIMIT 1
    """, (item['plan_id'],)).fetchone()
    effective_site_id = item.get('site_id') or (site_row['site_id'] if site_row else None)
    item['site_id'] = effective_site_id
    item['site_name'] = item.get('site_name') or (site_row['name'] if site_row else '')
    parts = db.execute("""
        SELECT pri.part_sku, pri.quantity,
               COALESCE(spi.part_name, pri.part_sku) AS part_name,
               spi.manufacturer, COALESCE(spi.model, ?) AS model
        FROM parts_request_items pri
        LEFT JOIN spare_parts_inventory spi ON pri.part_sku = spi.part_code
        WHERE pri.request_id=?
    """, (item.get('specification') or '', item['id'])).fetchall()
    item['parts_detail'] = [dict(part) for part in parts]
    item['source_type'] = 'parts_request'
    item['source_label'] = '备件申请'
    item['request_id'] = item['id']
    item['id'] = f'pr_{item["id"]}'
    fulfillment_labels = {
        'stock': '库存领用', 'local_purchase': '附近急购', 'vendor_order': '厂家订购',
    }
    item['fulfillment_label'] = fulfillment_labels.get(item.get('fulfillment_type'), '备件需求')
    item['title'] = f'{item["fulfillment_label"]}（{len(parts)}项）'
    item['source_name'] = item['work_order_no'] or item['plan_name'] or item['request_no'] or f'计划#{item["plan_id"]}'
    item['requester_name'] = item.get('requester_name') or ''
    item['actual_photos'] = 0
    item['required_photos'] = 0
    item['remark'] = ''
    item['submit_time'] = item['submit_time'] or ''
    return item


@app.route('/api/audit/locate')
def audit_locate():
    """Locate one typed parts request without deriving its state from the pending list."""
    request_type = (request.args.get('request_type') or '').strip()
    if request_type not in ('parts_request', 'spare_part_request'):
        return jsonify({'error': 'request_type must be parts_request or spare_part_request'}), 400
    try:
        request_id = int((request.args.get('id') or '').strip())
    except (TypeError, ValueError):
        return jsonify({'error': 'id must be a positive integer'}), 400
    if request_id <= 0:
        return jsonify({'error': 'id must be a positive integer'}), 400

    table = 'parts_requests' if request_type == 'parts_request' else 'spare_part_requests'
    with get_db() as db:
        row = db.execute(
            f'SELECT id, site_id, status FROM {table} WHERE id=?', (request_id,)
        ).fetchone()
        base = {
            'request_type': request_type,
            'source_type': request_type,
            'request_id': request_id,
        }
        if not row:
            return jsonify({**base, 'resolution': 'missing', 'status': 'missing', 'found': False})

        # Resource approvals are admin-only, matching /audit/pending and the action APIs.
        if not _has_any_role(g.current_user, 'admin'):
            return jsonify({**base, 'resolution': 'forbidden', 'status': 'forbidden', 'found': False})

        current_status = str(row['status'] or '').strip().lower()
        if current_status != 'pending':
            return jsonify({
                **base, 'resolution': 'processed', 'status': 'processed',
                'state': current_status or 'processed', 'found': True,
            })

        item = (_parts_request_audit_item(db, request_id)
                if request_type == 'parts_request'
                else next((item for item in _legacy_spare_part_audit_items(db, None)
                           if item.get('request_id') == request_id), None))
        if item is None:
            # Keep the response conservative if a partially migrated database cannot be rendered.
            return jsonify({**base, 'resolution': 'missing', 'status': 'missing', 'found': False})
        return jsonify({
            **base, 'resolution': 'found', 'status': 'pending', 'state': 'pending',
            'found': True, 'item': item,
        })


@app.route('/api/audit/pending')
def audit_pending():
    """返回按业务单元组织的待审核项（计划、站点巡检、工单、备件、用车、影像）。"""
    g_ = require_reviewer()
    if g_:
        return g_
    result = []
    allowed = _filter_site_ids()  # 非管理员/有站点绑定 → 仅本人站点待办
    include_resource_approvals = _has_any_role(g.current_user, 'admin')
    with get_db() as db:
        attachment_columns = {
            row['name'] for row in db.execute('PRAGMA table_info(operation_attachments)').fetchall()
        }
        evidence_qualification_sql = (
            "a.evidence_qualification" if 'evidence_qualification' in attachment_columns else "'review'"
        )
        evidence_basis_sql = "a.evidence_basis" if 'evidence_basis' in attachment_columns else "'unknown'"
        evidence_reason_sql = "a.evidence_reason" if 'evidence_reason' in attachment_columns else "''"
        evidence_next_action_sql = (
            "a.evidence_next_action" if 'evidence_next_action' in attachment_columns
            else "'请补传原图或现场重拍'"
        )
        # 0. 巡检排程审批：计划通知与审核待办必须使用同一状态口径。
        if include_resource_approvals:
            schedules = db.execute("""
                SELECT ps.*,
                       u.real_name AS executor_name
                FROM plan_schedules ps LEFT JOIN users u ON u.id=ps.user_id
                WHERE ps.status IN ('submitted', 'change_submitted')
                ORDER BY ps.submitted_at DESC, ps.id DESC
            """).fetchall()
            for schedule in schedules:
                parsed_schedule = _ps_parse_row(schedule)
                plan_data = parsed_schedule.get('plan_data') or {}
                schedule_site_ids = {
                    int(site_id) for day in plan_data.values() if isinstance(day, dict)
                    for site_id in (day.get('sites') or []) if str(site_id).isdigit()
                }
                if allowed is not None and schedule_site_ids and not schedule_site_ids.intersection(allowed):
                    continue
                site_map = {}
                if schedule_site_ids:
                    marks = ','.join('?' * len(schedule_site_ids))
                    site_map = {row['id']: row['name'] for row in db.execute(
                        f"SELECT id, name FROM sites WHERE id IN ({marks})", list(schedule_site_ids)).fetchall()}
                plan_days = []
                for date_str, day_data in sorted(plan_data.items() if isinstance(plan_data, dict) else []):
                    if not isinstance(day_data, dict):
                        continue
                    day_sites = [int(site_id) for site_id in (day_data.get('sites') or []) if str(site_id).isdigit()]
                    plan_days.append({
                        'date': date_str,
                        'sites': [{'id': site_id, 'name': site_map.get(site_id, f'站点#{site_id}')} for site_id in day_sites],
                        'notes': day_data.get('notes') or '',
                    })
                previous_plan_days = []
                previous_plan_data = parsed_schedule.get('previous_plan_data') or {}
                for date_str, day_data in sorted(previous_plan_data.items() if isinstance(previous_plan_data, dict) else []):
                    if not isinstance(day_data, dict):
                        continue
                    day_sites = [int(site_id) for site_id in (day_data.get('sites') or []) if str(site_id).isdigit()]
                    previous_plan_days.append({
                        'date': date_str,
                        'sites': [{'id': site_id, 'name': site_map.get(site_id, f'站点#{site_id}')} for site_id in day_sites],
                        'notes': day_data.get('notes') or '',
                    })
                vehicle_ids = {int(vehicle_id) for vehicle_id in (parsed_schedule.get('vehicle_days') or {}).values()
                               if str(vehicle_id).isdigit()}
                vehicle_map = {}
                if vehicle_ids:
                    marks = ','.join('?' * len(vehicle_ids))
                    vehicle_map = {row['id']: dict(row) for row in db.execute(
                        f"SELECT id, plate_no, model FROM vehicles WHERE id IN ({marks})", list(vehicle_ids)).fetchall()}
                vehicle_days = [{
                    'date': date_str,
                    'vehicle_id': int(vehicle_id),
                    'plate_no': (vehicle_map.get(int(vehicle_id)) or {}).get('plate_no', ''),
                    'model': (vehicle_map.get(int(vehicle_id)) or {}).get('model', ''),
                } for date_str, vehicle_id in sorted((parsed_schedule.get('vehicle_days') or {}).items())
                    if str(vehicle_id).isdigit()]
                schedule_type_cn = _PS_FREQ_CN.get(schedule['schedule_type'], '巡检')
                result.append({
                    'source_type': 'plan_schedule',
                    'source_label': '巡检计划审批',
                    'id': f'ps_{schedule["id"]}',
                    'schedule_id': schedule['id'],
                    'title': f'{schedule_type_cn}计划（{schedule["period_start"]} ~ {schedule["period_end"]}）',
                    'source_name': f'计划#{schedule["id"]}',
                    'site_name': ', '.join(dict.fromkeys(site_map.values())),
                    'site_ids': sorted(schedule_site_ids),
                    'site_names': [site_map[site_id] for site_id in sorted(schedule_site_ids) if site_id in site_map],
                    'plan_days': plan_days,
                    'previous_plan_days': previous_plan_days,
                    'vehicle_days_detail': vehicle_days,
                    'spare_parts': parsed_schedule.get('spare_parts') or [],
                    'plan_data': plan_data,
                    'is_change': schedule['status'] == 'change_submitted',
                    'change_reason': schedule['change_reason'] or '',
                    'previous_plan_data': parsed_schedule.get('previous_plan_data'),
                    'previous_vehicle_days': parsed_schedule.get('previous_vehicle_days'),
                    'previous_spare_parts': parsed_schedule.get('previous_spare_parts'),
                    'executor_name': schedule['executor_name'] or '',
                    'requester_name': _plan_schedule_requester_name(db, schedule['id']),
                    'submit_time': schedule['submitted_at'] or '',
                    'remark': schedule['change_reason'] or schedule['remarks'] or '',
                    'status': schedule['status'],
                    'actual_photos': 0,
                    'required_photos': 0,
                })

        # 1. 巡检待审项：按“执行计划 + 站点”聚合，一站一张审核卡片。
        need_review_select = ('i.need_review' if _table_has_column(db, 'insp_plan_items', 'need_review')
                              else 'NULL AS need_review')
        insp_items = db.execute(f"""
            SELECT i.id, i.item_name, i.site_id, s.name as site_name,
                   i.plan_id, p.plan_name as source_name, i.actual_photos, i.required_photos,
                   i.remark, i.result, i.check_time as submit_time, i.photo_urls,
                   {need_review_select}
            FROM insp_plan_items i
            JOIN sites s ON i.site_id = s.id
            JOIN insp_plans p ON i.plan_id = p.id
            WHERE i.review_status = 1 AND COALESCE(i.execution_status, 'active')='active'
              AND NOT EXISTS (
                    SELECT 1 FROM insp_plan_items unfinished
                    WHERE unfinished.plan_id=i.plan_id AND unfinished.site_id=i.site_id
                      AND COALESCE(unfinished.execution_status,'active')='active'
                      AND unfinished.result IS NULL
              )
            ORDER BY i.check_time DESC
        """).fetchall()
        inspection_batches = {}
        for r in insp_items:
            if allowed is not None and r['site_id'] not in allowed:
                continue
            key = (r['plan_id'], r['site_id'])
            batch = inspection_batches.setdefault(key, {
                'source_type': 'inspection_batch',
                'source_label': '巡检站点审核',
                'id': f'insp_batch_{r["plan_id"]}_{r["site_id"]}',
                'plan_id': r['plan_id'],
                'site_id': r['site_id'],
                'site_name': r['site_name'] or '',
                'source_name': r['source_name'] or f'计划#{r["plan_id"]}',
                'title': f'{r["site_name"] or "站点"}巡检审核',
                'item_ids': [],
                'item_details': [],
                'photo_urls': [],
                'attachment_ids': [],
                'attachment_details': [],
                'pending_photo_count': 0,
                'flagged_count': 0,
                'is_flagged': 0,
                'flag_reason': '',
                'actual_photos': 0,
                'required_photos': 0,
                'pending_item_count': 0,
                'submit_time': r['submit_time'] or '',
                'remark': '',
            })
            try:
                photos = json.loads(r['photo_urls']) if isinstance(r['photo_urls'], str) else (r['photo_urls'] or [])
            except Exception:
                photos = []
            photos = photos if isinstance(photos, list) else []
            batch['item_ids'].append(r['id'])
            batch['pending_item_count'] += 1
            batch['actual_photos'] += int(r['actual_photos'] or 0)
            batch['required_photos'] += int(r['required_photos'] or 0)
            batch['submit_time'] = max(batch['submit_time'], r['submit_time'] or '')
            batch['photo_urls'].extend([path for path in photos if path not in batch['photo_urls']])
            batch['item_details'].append({
                'id': r['id'], 'item_name': r['item_name'] or '', 'result': r['result'] or '',
                'remark': r['remark'] or '', 'actual_photos': int(r['actual_photos'] or 0),
                'required_photos': int(r['required_photos'] or 0), 'photo_urls': photos,
                'need_review': int(r['need_review'] or 0) if r['need_review'] is not None else None,
            })
        for batch in inspection_batches.values():
            batch['remark'] = f'{batch["pending_item_count"]} 个检查项待审核'

        # 2. 工单审核：只以“待办结工单”为审核单元，照片是该单据的证据，
        # 不再拆成独立照片审核，避免照片审核完成后工单从审核队列消失。
        wos = db.execute("""
            SELECT w.id, w.order_no, w.site_id, s.name as site_name, w.event_type,
                   w.title, w.description, w.remark, w.status, w.images, w.assignee,
                   w.created_at, w.check_in_time, w.review_submitted_at
            FROM work_orders w
            LEFT JOIN sites s ON w.site_id = s.id
            WHERE w.status = 'reviewing'
            ORDER BY w.created_at DESC
        """).fetchall()
        for wo in wos:
            wo_dict = dict(wo)
            if allowed is not None and wo_dict.get('site_id') not in allowed:
                continue
            # 取工单全部有效照片，供管理员在同一审核弹窗内判断是否办结。
            photo_rows = db.execute(f"""
                SELECT id, filename, stored_path, description, category, created_at, uploader_name,
                       review_status, reject_reason, taken_at, capture_source, is_flagged,
                       flag_reason, flag_rule, duplicate_of_id,
                       {evidence_qualification_sql.replace('a.', '')} AS evidence_qualification,
                       {evidence_basis_sql.replace('a.', '')} AS evidence_basis,
                       {evidence_reason_sql.replace('a.', '')} AS evidence_reason,
                       {evidence_next_action_sql.replace('a.', '')} AS evidence_next_action
                FROM operation_attachments a
                WHERE a.source_type='workorder' AND a.source_id=?
                  AND file_type='image' AND is_deleted=0
                  AND COALESCE(evidence_qualification,'review')='qualified'
                  AND COALESCE(json_extract(CASE WHEN json_valid(extra_json)
                        THEN extra_json ELSE '{{}}' END, '$.material_role'),'formal')!='supplement'
                ORDER BY created_at DESC
            """, (wo_dict['id'],)).fetchall()
            total_photos = len(photo_rows)
            workorder_attachment_details = []
            for photo in photo_rows:
                detail = dict(photo)
                detail.update(_attachment_status_payload(detail))
                workorder_attachment_details.append(detail)
            result.append({
                'source_type': 'workorder_review',
                'source_label': '工单办结审核',
                'id': f'wo_{wo_dict["id"]}',
                'title': wo_dict.get('title', '') or '待核验工单',
                'site_id': wo_dict.get('site_id'),
                'site_name': wo_dict.get('site_name') or '',
                'source_name': wo_dict.get('order_no', ''),
                'source_title': wo_dict.get('title', ''),
                'actual_photos': total_photos,
                'required_photos': 1,
                'original_description': wo_dict.get('description', '') or '',
                'resolution_note': wo_dict.get('remark', '') or '',
                'created_at': wo_dict.get('created_at', '') or '',
                'check_in_time': wo_dict.get('check_in_time', '') or '',
                'submit_time': wo_dict.get('review_submitted_at', '') or '',
                'photo_urls': json.dumps([p['stored_path'] for p in photo_rows], ensure_ascii=False),
                'order_no': wo_dict.get('order_no', ''),
                'attachment_details': workorder_attachment_details,
                'status': wo_dict.get('status', ''),
                'assignee': wo_dict.get('assignee', ''),
            })
        
        # 3. 巡检备件预申报待审项（parts_requests, status='pending'）
        prs = db.execute("""
            SELECT pr.id, pr.plan_id, pr.site_id, pr.work_order_no, pr.request_no, pr.reason,
                   pr.fulfillment_type, pr.requested_part_name, pr.specification, pr.estimated_amount,
                   pr.requester_id, pr.created_at as submit_time, p.plan_name, s.name AS site_name,
                   u.real_name as requester_name
            FROM parts_requests pr
            LEFT JOIN insp_plans p ON pr.plan_id = p.id
            LEFT JOIN sites s ON s.id=pr.site_id
            LEFT JOIN users u ON pr.requester_id = u.id
            WHERE pr.status = 'pending'
            ORDER BY pr.created_at DESC
        """).fetchall()
        for pr in prs:
            if not include_resource_approvals:
                continue
            pd = dict(pr)
            site_row = db.execute("""
                SELECT s.id as site_id, s.name FROM insp_plan_items i JOIN sites s ON i.site_id = s.id
                WHERE i.plan_id = ? LIMIT 1
            """, (pd['plan_id'],)).fetchone()
            effective_site_id = pd.get('site_id') or (site_row['site_id'] if site_row else None)
            pd['site_id'] = effective_site_id
            pd['site_name'] = pd.get('site_name') or (site_row['name'] if site_row else '')
            if allowed is not None and effective_site_id not in allowed:
                continue
            items = db.execute("""
                SELECT pri.part_sku, pri.quantity,
                       COALESCE(spi.part_name, pri.part_sku) AS part_name,
                       spi.manufacturer, COALESCE(spi.model, ?) AS model
                FROM parts_request_items pri
                LEFT JOIN spare_parts_inventory spi ON pri.part_sku = spi.part_code
                WHERE pri.request_id=?
            """, (pd.get('specification') or '', pd['id'])).fetchall()
            pd['parts_detail'] = [dict(x) for x in items]
            pd['source_type'] = 'parts_request'
            pd['source_label'] = '备件申请'
            pd['id'] = f'pr_{pd["id"]}'
            fulfillment_labels = {'stock': '库存领用', 'local_purchase': '附近急购', 'vendor_order': '厂家订购'}
            pd['fulfillment_label'] = fulfillment_labels.get(pd.get('fulfillment_type'), '备件需求')
            pd['title'] = f'{pd["fulfillment_label"]}（{len(items)}项）'
            pd['source_name'] = pd['work_order_no'] or pd['plan_name'] or pd['request_no'] or f'计划#{pd["plan_id"]}'
            pd['requester_name'] = pd.get('requester_name') or ''
            pd['actual_photos'] = 0
            pd['required_photos'] = 0
            pd['remark'] = ''
            pd['submit_time'] = pd['submit_time'] or ''
            result.append(pd)

        # 3b. 历史 spare_part_requests：只保留仍处于 pending 的兼容申请，
        # 使用独立 source_type，避免与 parts_requests 的同编号申请混淆。
        if include_resource_approvals:
            result.extend(_legacy_spare_part_audit_items(db, allowed))

        # 4. 用车申请待审项（vehicle_applications, status='pending'）
        vas = db.execute("""
            SELECT va.*,
                   va.created_at as submit_time,
                   v.plate_no, v.model, u.real_name as applicant_name
            FROM vehicle_applications va
            LEFT JOIN vehicles v ON va.vehicle_id = v.id
            LEFT JOIN users u ON va.applicant_id = u.id
            WHERE va.status = 'pending'
            ORDER BY va.created_at DESC
        """).fetchall()
        for va in vas:
            if not include_resource_approvals:
                continue
            vd = dict(va)
            vd['source_type'] = 'vehicle_application'
            vd['source_label'] = '用车审批'
            vd['id'] = f'va_{vd["id"]}'
            vd['title'] = f'用车申请：{vd.get("plate_no") or ""}'
            vd['source_name'] = vd.get('plate_no') or ''
            vd['site_name'] = ''
            vd['site_id'] = vd.get('site_id')
            vd['actual_photos'] = 0
            vd['required_photos'] = 0
            vd['remark'] = vd.get('reason') or ''
            vd['submit_time'] = vd['submit_time'] or ''
            vd['applicant_name'] = vd.get('applicant_name') or ''
            vd['start_at'] = vd.get('start_at') or ''
            vd['end_at'] = vd.get('end_at') or ''
            vd['destination'] = vd.get('destination') or ''
            vd.update(_vehicle_application_audit_association(db, vd))
            result.append(vd)

        # 5. 内容审核只处理已明确绑定检查项的正式照片。无归属历史附件保留只读，
        # 但没有内容标准，不能进入主审核队列让审核员兜底。
        photo_reviews = db.execute(f"""
            SELECT a.id as aid, a.description, a.watermark_text, a.recognized_category, a.extra_json,
                   a.site_id, s.name as site_name, a.source_type, a.source_id,
                   a.created_at as submit_time, a.stored_path, a.filename, a.taken_at,
                   a.is_flagged, a.flag_reason, a.flag_rule, a.capture_source,
                   a.review_status, a.uploader_id, a.uploader_name,
                   {evidence_qualification_sql} AS evidence_qualification,
                   {evidence_basis_sql} AS evidence_basis,
                   {evidence_reason_sql} AS evidence_reason,
                   {evidence_next_action_sql} AS evidence_next_action,
                   i.id AS item_id, i.item_name, i.plan_id, p.plan_name
            FROM operation_attachments a
            LEFT JOIN sites s ON a.site_id = s.id
            LEFT JOIN insp_plan_items i ON a.source_type='inspection' AND a.source_id=i.id
            LEFT JOIN insp_plans p ON p.id=i.plan_id
            WHERE a.is_deleted=0 AND a.review_status='pending'
              AND COALESCE(a.evidence_qualification,'review')='qualified'
              AND COALESCE(json_extract(CASE WHEN json_valid(a.extra_json)
                    THEN a.extra_json ELSE '{{}}' END, '$.material_role'),'formal')!='supplement'
              AND a.source_type='inspection' AND a.source_id>0
              AND i.id IS NOT NULL AND i.review_status=1
              AND EXISTS (
                    SELECT 1 FROM json_each(CASE WHEN json_valid(i.photo_urls)
                                                THEN i.photo_urls ELSE '[]' END) selected
                    WHERE selected.value=a.stored_path
                       OR (selected.value LIKE '%://%'
                           AND substr(selected.value, -length(a.stored_path))=a.stored_path)
              )
            ORDER BY a.is_flagged DESC, a.created_at DESC
        """).fetchall()
        for pr in photo_reviews:
            if allowed is not None and pr['site_id'] not in allowed:
                continue
            pd = dict(pr)
            try:
                photo_extra = json.loads(pd.get('extra_json') or '{}')
            except (TypeError, json.JSONDecodeError):
                photo_extra = {}
            plan_id = pd.get('plan_id')
            inspection_batch = inspection_batches.get((plan_id, pd['site_id'])) if plan_id else None
            if inspection_batch is not None:
                raw_id = pd['aid']
                if raw_id not in inspection_batch['attachment_ids']:
                    inspection_batch['attachment_ids'].append(raw_id)
                    inspection_batch['pending_photo_count'] += 1
                    inspection_batch['submit_time'] = max(
                        inspection_batch['submit_time'], pd.get('submit_time') or '')
                    if pd.get('is_flagged'):
                        inspection_batch['is_flagged'] = 1
                        inspection_batch['flagged_count'] += 1
                        if pd.get('flag_reason') and pd['flag_reason'] not in inspection_batch['flag_reason']:
                            inspection_batch['flag_reason'] = '；'.join(filter(None, [
                                inspection_batch['flag_reason'], pd['flag_reason']]))
                    attachment_detail = {
                        'id': raw_id, 'filename': pd.get('filename'), 'stored_path': pd.get('stored_path'),
                        'description': pd.get('description'), 'watermark_text': pd.get('watermark_text'),
                        'taken_at': pd.get('taken_at'), 'uploader_name': pd.get('uploader_name'),
                        'capture_source': pd.get('capture_source'),
                        'is_flagged': pd.get('is_flagged') or 0,
                        'flag_reason': pd.get('flag_reason') or '', 'flag_rule': pd.get('flag_rule') or '',
                        'item_id': pd.get('item_id'), 'item_name': pd.get('item_name') or '检查项待确认',
                        'plan_id': pd.get('plan_id'), 'plan_name': pd.get('plan_name') or '',
                        'site_id': pd.get('site_id'), 'site_name': pd.get('site_name') or '',
                        'archive_name': f'{pd.get("site_name") or "未关联站点"} · {pd.get("item_name") or "检查项待确认"} · {pd.get("recognized_category") or "影像"} · {pd.get("taken_at") or "拍摄时间待确认"}',
                        'original_filename': pd.get('filename') or '',
                        'review_status': pd.get('review_status') or 'pending',
                        'review_status_label': ATTACHMENT_REVIEW_STATUS_LABELS.get(pd.get('review_status') or 'pending', '待审核'),
                        'risk_label': '风险标记' if pd.get('is_flagged') else '',
                        'recognized_category': pd.get('recognized_category') or '影像',
                        'classification_source': photo_extra.get('classification_source') or ('inspection_item' if pd.get('item_id') else 'unlinked_legacy'),
                        'watermark_status': photo_extra.get('ocr_status') or 'unknown',
                        'evidence_basis': pd.get('evidence_basis') or 'unknown',
                        'evidence_reason': pd.get('evidence_reason') or '',
                        'evidence_next_action': pd.get('evidence_next_action') or '',
                    }
                    attachment_detail.update(_attachment_status_payload(pd))
                    inspection_batch['attachment_details'].append(attachment_detail)
                continue
        for batch in inspection_batches.values():
            if batch['attachment_ids']:
                batch['remark'] = (
                    f'{batch["pending_item_count"]} 个检查项、'
                    f'{batch["pending_photo_count"]} 张照片待审核')
                result.append(batch)
                _notify_inspection_batch_reviewers(db, batch)

        db.commit()

        # 补充工单的站点名称（历史兼容分支）
        site_names = {}
        for item in result:
            if item['source_type'] == 'workorder' and not item['site_name'] and item.get('site_id'):
                if item['site_id'] not in site_names:
                    s = db.execute("SELECT name FROM sites WHERE id=?", (item['site_id'],)).fetchone()
                    site_names[item['site_id']] = s['name'] if s else ''
                item['site_name'] = site_names[item['site_id']]

    # 按提交时间降序（巡检在前，工单在后）
    result.sort(key=lambda x: x.get('submit_time') or '', reverse=True)
    return jsonify(result)


@app.route('/api/audit/target-status')
@login_required
def audit_target_status():
    """Resolve an exact audit deep link without leaking a processed object to an unauthorized user."""
    denied = require_reviewer()
    if denied:
        return denied
    target_type = str(request.args.get('target_type') or '').strip()
    target_id = str(request.args.get('target_id') or '').strip()
    cycle_key = str(request.args.get('cycle_key') or '').strip()
    if not target_type or not target_id:
        return jsonify({'error': '审核目标参数不完整'}), 400
    with get_db() as db:
        is_admin = _has_any_role(g.current_user, 'admin')
        row = None
        if target_type == 'plan_schedule':
            if not is_admin:
                return jsonify({'error': '当前账号无权查看该审批事项'}), 403
            reason_field = 'reject_reason' if _table_has_column(db, 'plan_schedules', 'reject_reason') else "''"
            row = db.execute(f'SELECT status,{reason_field} AS reject_reason FROM plan_schedules WHERE id=?', (target_id,)).fetchone()
        elif target_type == 'vehicle_application':
            if not is_admin:
                return jsonify({'error': '当前账号无权查看该审批事项'}), 403
            reason_field = 'reject_reason' if _table_has_column(db, 'vehicle_applications', 'reject_reason') else "''"
            row = db.execute(f'SELECT status,{reason_field} AS reject_reason FROM vehicle_applications WHERE id=?', (target_id,)).fetchone()
        elif target_type == 'parts_request':
            if not is_admin:
                return jsonify({'error': '当前账号无权查看该审批事项'}), 403
            reason_field = 'approve_comment' if _table_has_column(db, 'parts_requests', 'approve_comment') else "''"
            row = db.execute(f'SELECT status,{reason_field} AS reject_reason FROM parts_requests WHERE id=?', (target_id,)).fetchone()
        elif target_type == 'workorder_review':
            cycle_field = 'review_cycle' if _table_has_column(db, 'work_orders', 'review_cycle') else '0'
            row = db.execute(f'SELECT status,site_id,remark,{cycle_field} AS review_cycle FROM work_orders WHERE order_no=?', (target_id,)).fetchone()
            if row:
                denied = _site_access_denied(row['site_id'], '审核')
                if denied:
                    return denied
        else:
            return jsonify({'error': '不支持的审核目标类型'}), 400
        if not row:
            return jsonify({'error': '该审核事项不存在'}), 404
        status = str(row['status'] or '')
        if cycle_key:
            business_type = {
                'plan_schedule': 'plan_schedule',
                'vehicle_application': 'vehicle_application',
                'parts_request': 'parts_request',
                'workorder_review': 'workorder',
            }[target_type]
            if not _table_exists(db, 'wx_subscription_outbox'):
                return jsonify({'error': '审核周期信息不可用，请刷新后重试'}), 409
            pending_intent = db.execute("""SELECT id FROM wx_subscription_outbox
                WHERE purpose='approval_pending' AND business_type=? AND business_id=? AND cycle_key=?
                ORDER BY id DESC LIMIT 1""", (business_type, target_id, cycle_key)).fetchone()
            result_intent = db.execute("""SELECT payload_json FROM wx_subscription_outbox
                WHERE purpose='approval_result' AND business_type=? AND business_id=? AND cycle_key=?
                ORDER BY id DESC LIMIT 1""", (business_type, target_id, cycle_key)).fetchone()
            if not pending_intent and not result_intent:
                return jsonify({'error': '该审核周期不存在或当前账号无权访问'}), 404
            if result_intent:
                try:
                    payload = json.loads(result_intent['payload_json'] or '{}')
                except (TypeError, ValueError, json.JSONDecodeError):
                    payload = {}
                return jsonify({
                    'state': 'processed', 'status': status,
                    'result_label': (payload.get('thing5') or {}).get('value') or '已处理',
                    'result_detail': (payload.get('thing4') or {}).get('value') or '',
                    'cycle_key': cycle_key,
                })
            same_cycle_pending = True
            if target_type == 'plan_schedule':
                latest = db.execute("""SELECT id FROM plan_schedule_events
                    WHERE schedule_id=? AND event_type IN ('submitted','change_submitted')
                    ORDER BY id DESC LIMIT 1""", (target_id,)).fetchone()
                same_cycle_pending = bool(latest and cycle_key == f'event:{latest["id"]}')
            elif target_type == 'workorder_review':
                same_cycle_pending = cycle_key == f'review:{int(row["review_cycle"] or 0)}'
            elif target_type == 'vehicle_application':
                same_cycle_pending = cycle_key == f'application:{target_id}'
            elif target_type == 'parts_request':
                same_cycle_pending = cycle_key == f'request:{target_id}'
            if not same_cycle_pending:
                return jsonify({'state': 'processed', 'status': status,
                                'result_label': '已处理',
                                'result_detail': '该审核周期已结束，当前对象已进入后续状态。',
                                'cycle_key': cycle_key})
        pending = (target_type == 'plan_schedule' and status in ('submitted', 'change_submitted')) \
            or (target_type == 'vehicle_application' and status == 'pending') \
            or (target_type == 'parts_request' and status == 'pending') \
            or (target_type == 'workorder_review' and status == 'reviewing')
        if pending:
            return jsonify({'state': 'pending', 'status': status, 'cycle_key': cycle_key})
        labels = {'approved': '已通过', 'closed': '已通过', 'rejected': '已退回',
                  'in_progress': '已退回', 'cancelled': '已取消'}
        reason = row['reject_reason'] if 'reject_reason' in row.keys() else row['remark'] if 'remark' in row.keys() else ''
        return jsonify({'state': 'processed', 'status': status,
                        'result_label': labels.get(status, '已处理'),
                        'result_detail': _wx_trim(reason, 80)})


# ---------- 操作附件审核（照片驳回/通过）----------
def _table_has_column(db, table, column):
    try:
        return any(
            row['name'] == column
            for row in db.execute(f'PRAGMA table_info({table})').fetchall()
        )
    except sqlite3.OperationalError:
        return False


def _sync_replacement_evidence_state(db, attachment, now):
    """Close an item-level supplement only after a replacement is approved."""
    if not (_table_exists(db, 'insp_plan_items')
            and _table_has_column(db, 'insp_plan_items', 'evidence_status')
            and str(attachment.get('source_type') or '').lower() == 'inspection'
            and attachment.get('source_id')):
        return None
    item = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (attachment['source_id'],)).fetchone()
    if not item or item['evidence_status'] != 'replacement_submitted':
        return None
    pending = db.execute("""SELECT 1 FROM operation_attachments
        WHERE source_type='inspection' AND source_id=? AND is_deleted=0
          AND review_required=1 AND review_status='pending'
          AND COALESCE(evidence_qualification,'review')='qualified'
          AND COALESCE(json_extract(CASE WHEN json_valid(extra_json)
                THEN extra_json ELSE '{}' END, '$.material_role'),'formal')!='supplement'""",
        (item['id'],)).fetchone()
    if pending:
        return None
    approved = db.execute("""SELECT COUNT(*) AS c FROM operation_attachments
        WHERE source_type='inspection' AND source_id=? AND is_deleted=0
          AND review_status='approved'
          AND COALESCE(evidence_qualification,'review')='qualified'
          AND COALESCE(json_extract(CASE WHEN json_valid(extra_json)
                THEN extra_json ELSE '{}' END, '$.material_role'),'formal')!='supplement'""",
        (item['id'],)).fetchone()['c']
    if not approved:
        return None
    updates = ["evidence_status='effective'"]
    params = []
    if _table_has_column(db, 'insp_plan_items', 'review_status'):
        updates.append('review_status=2')
    if _table_has_column(db, 'insp_plan_items', 'reviewer_id'):
        updates.append('reviewer_id=?')
        params.append(attachment.get('reviewer_id'))
    if _table_has_column(db, 'insp_plan_items', 'review_time'):
        updates.append('review_time=?')
        params.append(now)
    if _table_has_column(db, 'insp_plan_items', 'review_comment'):
        updates.append("review_comment='替代证据审核通过'")
    if _table_has_column(db, 'insp_plan_items', 'actual_photos'):
        updates.append('actual_photos=?')
        params.append(approved)
    params.append(item['id'])
    db.execute(f"UPDATE insp_plan_items SET {','.join(updates)} WHERE id=?", params)
    return item['id']


def _keep_replacement_required_after_rejection(db, attachment, reviewer_id, reason, now):
    """Keep a rejected replacement actionable without rewriting the original completion."""
    if not (_table_exists(db, 'insp_plan_items')
            and str(attachment.get('source_type') or '').lower() == 'inspection'
            and attachment.get('source_id')):
        return None
    if not _table_has_column(db, 'insp_plan_items', 'evidence_status'):
        return None
    item = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (attachment['source_id'],)).fetchone()
    if not item or item['evidence_status'] != 'replacement_submitted':
        return None
    updates = ["evidence_status='supplement_required'"]
    params = []
    if _table_has_column(db, 'insp_plan_items', 'review_status'):
        # A replacement rejection is an item-level retake request, not a new reviewer task.
        updates.append('review_status=3')
    if _table_has_column(db, 'insp_plan_items', 'reviewer_id'):
        updates.append('reviewer_id=?')
        params.append(reviewer_id)
    if _table_has_column(db, 'insp_plan_items', 'review_time'):
        updates.append('review_time=?')
        params.append(now)
    if _table_has_column(db, 'insp_plan_items', 'review_comment'):
        updates.append('review_comment=?')
        params.append(reason or '替代证据未通过审核')
    if _table_has_column(db, 'insp_plan_items', 'rework_required_at'):
        updates.append('rework_required_at=?')
        params.append(now)
    params.append(item['id'])
    db.execute(f"UPDATE insp_plan_items SET {','.join(updates)} WHERE id=?", params)
    return item['id']


def _terminal_plan_vehicle_exists(db, schedule_id):
    """Whether a schedule's original vehicle arrangement has already closed."""
    if not schedule_id:
        return False
    try:
        clause = " AND rework_plan_id IS NULL" if _table_has_column(db, 'vehicle_applications', 'rework_plan_id') else ''
        return bool(db.execute(f"""SELECT 1 FROM vehicle_applications
            WHERE reason LIKE ? AND status IN ('returned','archived'){clause} LIMIT 1""",
            (_ps_vehicle_reason_like(schedule_id),)).fetchone())
    except sqlite3.OperationalError:
        return False


def _inspection_rejection_supports_resource_replan(db):
    return all((
        _table_has_column(db, 'insp_plans', 'rework_of_plan_id'),
        _table_has_column(db, 'insp_plans', 'rework_batch_key'),
        _table_has_column(db, 'insp_plans', 'resource_state'),
        _table_has_column(db, 'insp_plan_items', 'rework_source_item_id'),
        _table_has_column(db, 'vehicle_applications', 'rework_plan_id'),
    ))


def _inspection_rejection_rows(db, item_reasons):
    rows = []
    seen_item_ids = set()
    notification_groups = {}
    for item_id, reason in item_reasons:
        if item_id in seen_item_ids:
            continue
        item = db.execute('SELECT * FROM insp_plan_items WHERE id=?', (item_id,)).fetchone()
        if not item:
            continue
        plan = db.execute('SELECT * FROM insp_plans WHERE id=?', (item['plan_id'],)).fetchone()
        if plan:
            seen_item_ids.add(item_id)
            rows.append((item, plan, reason))
    return rows


def _notify_inspection_rework(db, assignee_id, target_plan_id, site_id, item_count,
                              resource_replan_required):
    if not assignee_id or not target_plan_id:
        return None
    try:
        site = db.execute('SELECT name FROM sites WHERE id=?', (site_id,)).fetchone()
    except sqlite3.OperationalError:
        site = None
    site_name = site['name'] if site else f'站点#{site_id}'
    summary = db.execute("""SELECT COUNT(DISTINCT i.id) AS item_count,
            COUNT(DISTINCT a.id) AS photo_count
        FROM insp_plan_items i
        LEFT JOIN operation_attachments a
          ON a.source_type='inspection' AND a.source_id=i.id
         AND a.review_status='rejected' AND COALESCE(a.is_deleted,0)=0
        WHERE i.plan_id=? AND i.site_id=? AND COALESCE(i.review_status,0)=3
          AND COALESCE(i.execution_status,'active')='active'""",
        (target_plan_id, site_id)).fetchone()
    item_count = max(int(item_count or 0), int(summary['item_count'] or 0) if summary else 0)
    photo_count = int(summary['photo_count'] or 0) if summary else 0
    summary_text = f'{item_count} 个检查项、{photo_count} 张照片被驳回'
    if resource_replan_required:
        title = '巡检整改待安排资源'
        content = (f'{site_name}有 {summary_text}，整改补检包#{target_plan_id}已生成；'
                   '当前资源状态为待安排，请先申请车辆或登记并审批无车例外。')
        resource_state = 'arrangement_required'
    else:
        title = '巡检整改待执行'
        content = (f'{site_name}有 {summary_text}，执行包#{target_plan_id}已重新开放整改；'
                   '请返回站点300米范围内补拍，并按审核意见提交证据。无需重复整站签到。')
        resource_state = 'ready'
    dedupe_key = f'inspection_rework:{target_plan_id}:{site_id}'
    payload = json.dumps({
        'plan_id': target_plan_id,
        'site_id': site_id,
        'item_count': item_count,
        'photo_count': photo_count,
        'resource_state': resource_state,
    }, ensure_ascii=False, separators=(',', ':'))
    notification_id = _upsert_unread_notification(
        db, assignee_id, 'inspection_rework', target_plan_id,
        title, content, dedupe_key, payload)
    _retire_redundant_inspection_photo_notifications(db, assignee_id)
    return notification_id


def _retire_redundant_inspection_photo_notifications(db, user_id=None):
    """Hide legacy per-photo reminders only when one current site rework owns them."""
    required = (
        _table_exists(db, 'notifications'),
        _table_exists(db, 'operation_attachments'),
        _table_exists(db, 'insp_plan_items'),
        _table_exists(db, 'insp_plans'),
        _table_has_column(db, 'notifications', 'is_read'),
        _table_has_column(db, 'notifications', 'dedupe_key'),
    )
    if not all(required):
        return 0
    user_clause = ' AND redundant.user_id=?' if user_id is not None else ''
    params = [user_id] if user_id is not None else []
    result = db.execute(f"""UPDATE notifications AS redundant SET is_read=1
        WHERE redundant.is_read=0
          AND redundant.source_type IN ('photo_review','replacement_review')
          {user_clause}
          AND EXISTS (
            SELECT 1
            FROM operation_attachments a
            JOIN insp_plan_items i
              ON a.source_type='inspection' AND a.source_id=i.id
            JOIN insp_plans p ON p.id=i.plan_id
            JOIN notifications rework
              ON rework.user_id=redundant.user_id
             AND rework.source_type='inspection_rework'
             AND rework.is_read=0
             AND rework.dedupe_key='inspection_rework:' || i.plan_id || ':' || i.site_id
            WHERE CAST(a.id AS TEXT)=CAST(redundant.source_id AS TEXT)
              AND p.assignee_id=redundant.user_id
          )""", params)
    return result.rowcount


def _reject_inspection_items(db, item_reasons, reviewer_id, now, batch_key):
    """Reject items without reopening a returned vehicle's historical trip.

    A terminal original vehicle creates one resource-gated remediation package per
    source execution package/site batch. All other cases retain the legacy
    in-place rework behavior.
    """
    rows = _inspection_rejection_rows(db, item_reasons)
    outcomes = {}
    if not rows:
        return outcomes
    # Content rejection is an item-level retake request. Keep the original visit,
    # result, checkout and plan progress intact; only this item returns to the
    # operator for replacement photos.
    seen_item_ids = set()
    notification_groups = {}
    for item, plan, reason in rows:
        if item['id'] in seen_item_ids:
            continue
        seen_item_ids.add(item['id'])
        updates = [
            'review_status=3', 'review_comment=?', 'reviewer_id=?',
            'review_time=?', 'rework_required_at=?',
        ]
        params = [reason, reviewer_id, now, now]
        if _table_has_column(db, 'insp_plan_items', 'evidence_status'):
            updates.append("evidence_status='supplement_required'")
        if _table_has_column(db, 'insp_plan_items', 'supplement_reason'):
            updates.append('supplement_reason=?')
            params.append(reason)
        params.append(item['id'])
        db.execute(f"UPDATE insp_plan_items SET {','.join(updates)} WHERE id=?", params)
        notification_groups.setdefault(
            (plan['assignee_id'], plan['id'], item['site_id']), 0)
        notification_groups[(plan['assignee_id'], plan['id'], item['site_id'])] += 1
        outcomes[item['id']] = {
            'resource_replan_required': False,
            'rework_plan_id': None,
            'item_retake': True,
        }
    for (assignee_id, plan_id, site_id), item_count in notification_groups.items():
        _notify_inspection_rework(db, assignee_id, plan_id, site_id, item_count, False)
    return outcomes

    # Legacy whole-plan rework is intentionally unreachable for content review.
    supports_replan = _inspection_rejection_supports_resource_replan(db)
    terminal_groups = {}
    for item, plan, reason in rows:
        schedule_id = plan['plan_schedule_id'] if 'plan_schedule_id' in plan.keys() else None
        if supports_replan and _terminal_plan_vehicle_exists(db, schedule_id):
            terminal_groups.setdefault((plan['id'], item['site_id']), []).append((item, plan, reason))

    terminal_item_ids = {item['id'] for group in terminal_groups.values() for item, _, _ in group}
    for (source_plan_id, site_id), group in terminal_groups.items():
        source_plan = group[0][1]
        item_ids = sorted(item['id'] for item, _, _ in group)
        group_key = f'{batch_key}:{source_plan_id}:{site_id}:{"-".join(str(item_id) for item_id in item_ids)}'
        rework = db.execute("""SELECT id FROM insp_plans
            WHERE rework_of_plan_id=? AND rework_batch_key=? LIMIT 1""",
            (source_plan_id, group_key)).fetchone()
        if rework:
            rework_plan_id = rework['id']
        else:
            plan_name = f'{source_plan["plan_name"] or "巡检"}·整改补检'
            cur = db.execute("""INSERT INTO insp_plans
                (plan_name, assignee, assignee_id, period, generate_date, status,
                 plan_schedule_id, schedule_version, plan_snapshot,
                 rework_of_plan_id, rework_batch_key, resource_state)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""", (
                    plan_name, source_plan['assignee'], source_plan['assignee_id'],
                    source_plan['period'], datetime.now().strftime('%Y-%m-%d'), 'active',
                    source_plan['plan_schedule_id'], source_plan['schedule_version'],
                    source_plan['plan_snapshot'], source_plan_id, group_key,
                    'arrangement_required'))
            rework_plan_id = cur.lastrowid
        for item, _, reason in group:
            # Keep the source item's submitted evidence and checkout as immutable
            # historical facts. The new item is the only item that can be edited.
            db.execute("""UPDATE insp_plan_items
                SET review_status=3, review_comment=?, reviewer_id=?, review_time=?,
                    rework_required_at=? WHERE id=?""",
                (reason, reviewer_id, now, now, item['id']))
            db.execute("""INSERT OR IGNORE INTO insp_plan_items
                (plan_id, site_id, template_id, item_name, category, frequency,
                 required_photos, rework_source_item_id, review_status,
                 rework_required_at, photo_urls, remark)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""", (
                    rework_plan_id, item['site_id'], item['template_id'], item['item_name'],
                    item['category'], item['frequency'], item['required_photos'], item['id'],
                    3, now, '[]', ''))
            outcomes[item['id']] = {'resource_replan_required': True, 'rework_plan_id': rework_plan_id}
        _ps_mark_field_rework(db, source_plan['plan_schedule_id'])
        _notify_inspection_rework(
            db, source_plan['assignee_id'], rework_plan_id, site_id, len(item_ids), True)

    legacy_groups = {}
    for item, plan, reason in rows:
        if item['id'] in terminal_item_ids:
            continue
        updates = "review_status=3, review_comment=?, reviewer_id=?, review_time=?, result=NULL, completed_at=NULL"
        params = [reason, reviewer_id, now]
        if _table_has_column(db, 'insp_plan_items', 'rework_required_at'):
            updates += ', rework_required_at=?'
            params.append(now)
        if _table_has_column(db, 'insp_plan_items', 'check_out_time'):
            updates += ', check_out_time=NULL'
        params.append(item['id'])
        db.execute(f'UPDATE insp_plan_items SET {updates} WHERE id=?', params)
        if _table_has_column(db, 'insp_plan_items', 'check_out_time'):
            db.execute("""UPDATE insp_plan_items SET check_out_time=NULL
                WHERE plan_id=? AND site_id=? AND COALESCE(execution_status, 'active')='active'""",
                (item['plan_id'], item['site_id']))
        _ps_mark_field_rework(db, plan['plan_schedule_id'] if 'plan_schedule_id' in plan.keys() else None)
        try:
            _ps_recalculate_field_execution(db, item['plan_id'])
        except sqlite3.OperationalError:
            pass
        outcomes[item['id']] = {'resource_replan_required': False, 'rework_plan_id': None}
        legacy_groups.setdefault((plan['id'], item['site_id']), []).append((item, plan))
    for (plan_id, site_id), group in legacy_groups.items():
        _notify_inspection_rework(
            db, group[0][1]['assignee_id'], plan_id, site_id, len(group), False)
    return outcomes


def _notify_inspection_batch_reviewers(db, batch, strict=False):
    """Keep one open reviewer notification for each inspection plan/site unit."""
    try:
        active_clause = " AND u.status='active'" \
            if _table_has_column(db, 'users', 'status') else ''
        if _table_exists(db, 'user_roles'):
            rows = db.execute(f"""SELECT DISTINCT u.id,
                    CASE WHEN u.role='admin' OR EXISTS (
                        SELECT 1 FROM user_roles ar WHERE ar.user_id=u.id AND ar.role='admin'
                    ) THEN 1 ELSE 0 END AS is_admin
                FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
                WHERE (u.role IN ('admin','reviewer','inspector') OR ur.role IN ('admin','reviewer'))
                  {active_clause}""").fetchall()
        else:
            rows = db.execute(f"""SELECT u.id,
                    CASE WHEN u.role='admin' THEN 1 ELSE 0 END AS is_admin
                FROM users u WHERE u.role IN ('admin','reviewer','inspector')
                  {active_clause}""").fetchall()
        unread_clause = ' AND is_read=0' \
            if _table_has_column(db, 'notifications', 'is_read') else ''
        for row in rows:
            if not row['is_admin'] and not db.execute(
                'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=?',
                (row['id'], batch['site_id'])
            ).fetchone():
                continue
            existing = db.execute(f"""SELECT 1 FROM notifications
                WHERE user_id=? AND source_type='inspection_review_batch'
                  AND source_id=? {unread_clause} LIMIT 1""",
                (row['id'], batch['id'])).fetchone()
            if not existing:
                db.execute("""INSERT INTO notifications
                    (user_id, source_type, source_id, title, content)
                    VALUES (?,?,?,?,?)""", (
                    row['id'], 'inspection_review_batch', batch['id'], '巡检站点待审核',
                    f'{batch["site_name"] or "站点"}有 {batch["pending_item_count"]} 个检查项待审核'))
    except sqlite3.OperationalError as exc:
        if strict:
            raise
        print(f'[Inspection batch review notify] skipped: {exc}')


def _open_inspection_site_review(db, plan_id, site_id):
    """Open one existing plan/site review unit when its last active item is submitted."""
    if not _table_has_column(db, 'insp_plan_items', 'review_status'):
        return None
    field_completed = _inspection_field_completion_sql(db)
    unfinished = db.execute(f"""SELECT 1 FROM insp_plan_items
        WHERE plan_id=? AND site_id=? AND COALESCE(execution_status,'active')='active'
          AND NOT {field_completed} LIMIT 1""", (plan_id, site_id)).fetchone()
    if unfinished:
        return None
    auto_approved = 'review_status=2'
    if _table_has_column(db, 'insp_plan_items', 'reviewer_id'):
        auto_approved += ' AND reviewer_id IS NULL'
    if _table_has_column(db, 'insp_plan_items', 'review_time'):
        auto_approved += " AND COALESCE(review_time,'')=''"
    db.execute(f"""UPDATE insp_plan_items SET review_status=1
        WHERE plan_id=? AND site_id=? AND {field_completed}
          AND COALESCE(execution_status,'active')='active'
          AND (COALESCE(review_status,0) IN (0,1) OR ({auto_approved}))""", (plan_id, site_id))
    row = db.execute("""SELECT COUNT(*) AS item_count FROM insp_plan_items
        WHERE plan_id=? AND site_id=? AND review_status=1
          AND COALESCE(execution_status,'active')='active'""", (plan_id, site_id)).fetchone()
    if not row or not int(row['item_count'] or 0):
        return None
    plan_name = ''
    if _table_has_column(db, 'insp_plans', 'plan_name'):
        plan = db.execute('SELECT plan_name FROM insp_plans WHERE id=?', (plan_id,)).fetchone()
        plan_name = (plan['plan_name'] if plan else '') or ''
    site_name = ''
    if _table_exists(db, 'sites') and _table_has_column(db, 'sites', 'name'):
        site = db.execute('SELECT name FROM sites WHERE id=?', (site_id,)).fetchone()
        site_name = (site['name'] if site else '') or ''
    batch = {
        'id': f'insp_batch_{plan_id}_{site_id}',
        'plan_id': plan_id,
        'site_id': site_id,
        'site_name': site_name,
        'source_name': plan_name or f'计划#{plan_id}',
        'pending_item_count': int(row['item_count'] or 0),
    }
    _notify_inspection_batch_reviewers(db, batch, strict=True)
    return batch


def _reopen_items_for_rejected_attachment(db, attachment, reviewer_id, reason, now):
    """Return inspection items affected by a rejected field image."""
    if not _table_has_column(db, 'insp_plan_items', 'rework_required_at'):
        return []
    stored_path = attachment['stored_path'] or ''
    if not stored_path:
        return []
    # Production rows have source_type/source_id.  A legacy fixture/database
    # without those columns may retain the old compatibility path lookup, but
    # rows with an explicit unlinked source are never classified by filename.
    has_source_columns = 'source_type' in attachment.keys() and 'source_id' in attachment.keys()
    attachment_source_type = attachment['source_type'] if 'source_type' in attachment.keys() else ''
    attachment_source_id = attachment['source_id'] if 'source_id' in attachment.keys() else 0
    if has_source_columns and not (
            attachment_source_type == 'inspection' and attachment_source_id not in (None, '', 0, '0')):
        return []
    if has_source_columns:
        items = db.execute("""SELECT i.id, i.plan_id, i.site_id, i.item_name, p.assignee_id
            FROM insp_plan_items i JOIN insp_plans p ON p.id=i.plan_id
            WHERE i.site_id=? AND i.id=?
              AND COALESCE(i.execution_status, 'active')='active'""",
            (attachment['site_id'], attachment_source_id)).fetchall()
        return [(item['id'], reason) for item in items]
    items = db.execute("""SELECT i.id, i.plan_id, i.site_id, i.item_name, p.assignee_id
        FROM insp_plan_items i JOIN insp_plans p ON p.id=i.plan_id
        WHERE i.site_id=? AND (
              (?='inspection' AND ?>0 AND i.id=?)
              OR (NOT (?='inspection' AND ?>0) AND i.photo_urls LIKE ?))
          AND COALESCE(i.execution_status, 'active')='active'""",
        (attachment['site_id'], attachment_source_type, attachment_source_id, attachment_source_id,
         attachment_source_type, attachment_source_id, '%' + stored_path + '%')).fetchall()
    return [(item['id'], reason) for item in items]


@app.route('/api/operation-attachments/review', methods=['POST'])
def api_operation_attachments_review():
    """审核操作附件；支持勾选驳回、其余一次通过的批次提交。"""
    g_ = require_reviewer()
    if g_:
        return g_
    data = request.get_json() or {}
    attachment_ids = data.get('attachment_ids', [])
    action = data.get('action', 'approve')  # approve | reject
    approve_ids = data.get('approve_ids')
    reject_ids = data.get('reject_ids')
    approve_item_ids = data.get('approve_item_ids') or []
    reviewer_id = g.current_user.get('id')
    reject_reason = data.get('reject_reason', '')

    selective = approve_ids is not None or reject_ids is not None
    if selective:
        if approve_ids is not None and not isinstance(approve_ids, list):
            return jsonify({'error': 'approve_ids 格式无效'}), 400
        if reject_ids is not None and not isinstance(reject_ids, list):
            return jsonify({'error': 'reject_ids 格式无效'}), 400
        approve_ids = approve_ids or []
        reject_ids = reject_ids or []
        try:
            approve_ids = list(dict.fromkeys(int(aid) for aid in approve_ids))
            reject_ids = list(dict.fromkeys(int(aid) for aid in reject_ids))
        except (TypeError, ValueError):
            return jsonify({'error': '附件 ID 格式无效'}), 400
        if any(aid <= 0 for aid in approve_ids + reject_ids):
            return jsonify({'error': '附件 ID 格式无效'}), 400
        if set(approve_ids).intersection(reject_ids):
            return jsonify({'error': '同一照片不能同时通过和驳回'}), 400
        if reject_ids and (not isinstance(reject_reason, str) or not reject_reason.strip()):
            return jsonify({'error': '勾选驳回照片后必须填写驳回原因'}), 400
        decisions = [(aid, 'approve') for aid in approve_ids] + [(aid, 'reject') for aid in reject_ids]
    else:
        if not isinstance(attachment_ids, list) or not isinstance(approve_item_ids, list):
            return jsonify({'error': '附件 ID 格式无效'}), 400
        if action not in ('approve', 'reject'):
            return jsonify({'error': '无效审核动作'}), 400
        try:
            attachment_ids = list(dict.fromkeys(int(aid) for aid in attachment_ids))
            approve_item_ids = list(dict.fromkeys(int(item_id) for item_id in approve_item_ids))
        except (TypeError, ValueError):
            return jsonify({'error': '附件 ID 格式无效'}), 400
        if any(item_id <= 0 for item_id in attachment_ids + approve_item_ids):
            return jsonify({'error': '附件 ID 格式无效'}), 400
        decisions = [(aid, action) for aid in attachment_ids]
        if action == 'reject' and (not isinstance(reject_reason, str) or not reject_reason.strip()):
            return jsonify({'error': '驳回附件必须填写驳回原因'}), 400
    if not isinstance(approve_item_ids, list):
        return jsonify({'error': '检查项 ID 格式无效'}), 400
    if selective:
        try:
            approve_item_ids = list(dict.fromkeys(int(item_id) for item_id in approve_item_ids))
        except (TypeError, ValueError):
            return jsonify({'error': '检查项 ID 格式无效'}), 400
        if any(item_id <= 0 for item_id in approve_item_ids):
            return jsonify({'error': '检查项 ID 格式无效'}), 400
    if not decisions:
        if not approve_item_ids:
            return jsonify({'error': '缺少 attachment_ids'}), 400

    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    approved_count = 0
    rejected_count = 0
    approved_item_count = 0
    affected_sites = set()
    rejected_item_rows = []
    affected_inspection_batches = set()
    with get_db() as db:
        attachment_decision_ids = list(dict.fromkeys(aid for aid, _ in decisions))
        attachment_map = {}
        if attachment_decision_ids:
            placeholders = ','.join('?' for _ in attachment_decision_ids)
            attachment_rows = db.execute(
                f'SELECT * FROM operation_attachments WHERE id IN ({placeholders})',
                attachment_decision_ids).fetchall()
            attachment_map = {row['id']: row for row in attachment_rows}
            missing_ids = [aid for aid in attachment_decision_ids if aid not in attachment_map]
            if missing_ids:
                return jsonify({'error': '附件不存在', 'attachment_ids': missing_ids}), 404
            for aid in attachment_decision_ids:
                att = attachment_map[aid]
                if att['site_id'] is None:
                    return jsonify({'error': '附件未绑定有效站点，无法审核'}), 403
                denied = _site_access_denied(att['site_id'], '审核')
                if denied:
                    return denied
            for aid in attachment_decision_ids:
                att = attachment_map[aid]
                if 'source_type' in att.keys() and att['source_type'] == 'workorder':
                    return jsonify({
                        'error': '工单附件必须通过工单审核链路处理',
                        'attachment_id': aid,
                        'code': 'ATTACHMENT_TYPE_NOT_REVIEWABLE',
                    }), 400
                if ('source_type' in att.keys() and 'source_id' in att.keys()
                        and not (att['source_type'] == 'inspection' and att['source_id'])):
                    return jsonify({
                        'error': '未关联检查项的附件没有内容审核标准，仅保留为历史附件',
                        'attachment_id': aid,
                        'code': 'ATTACHMENT_ITEM_REQUIRED',
                    }), 409
                if 'source_type' in att.keys() and 'source_id' in att.keys():
                    linked_item = db.execute(
                        'SELECT id,photo_urls FROM insp_plan_items WHERE id=? AND site_id=?',
                        (att['source_id'], att['site_id']),
                    ).fetchone()
                    if not linked_item:
                        return jsonify({
                            'error': '附件关联检查项不存在，不能进入内容审核',
                            'attachment_id': aid,
                            'code': 'ATTACHMENT_ITEM_REQUIRED',
                        }), 409
                    try:
                        selected_paths = {
                            _attachment_storage_path(value)
                            for value in json.loads(linked_item['photo_urls'] or '[]')
                            if isinstance(value, str)
                        }
                    except (TypeError, json.JSONDecodeError):
                        selected_paths = set()
                    if att['stored_path'] not in selected_paths:
                        return jsonify({
                            'error': '附件不在检查项当前提交照片集合中，不能审核',
                            'attachment_id': aid,
                            'code': 'ATTACHMENT_NOT_IN_ITEM_SUBMISSION',
                        }), 409
                if 'is_deleted' in att.keys() and att['is_deleted']:
                    return jsonify({'error': '附件已删除，无法审核', 'attachment_id': aid}), 409
                if att['review_status'] not in (None, 'pending'):
                    return jsonify({
                        'error': '存在已处理或不可处理的附件',
                        'attachment_id': aid,
                        'code': 'REVIEW_ALREADY_PROCESSED',
                    }), 409

        item_map = {}
        if approve_item_ids:
            placeholders = ','.join('?' for _ in approve_item_ids)
            item_rows = db.execute(
                f'SELECT id, site_id, review_status, required_photos FROM insp_plan_items WHERE id IN ({placeholders})',
                approve_item_ids).fetchall()
            item_map = {row['id']: row for row in item_rows}
            missing_item_ids = [item_id for item_id in approve_item_ids if item_id not in item_map]
            if missing_item_ids:
                return jsonify({'error': '检查项不存在', 'item_ids': missing_item_ids}), 404
            for item_id in approve_item_ids:
                item = item_map[item_id]
                if item['site_id'] is None:
                    return jsonify({'error': '检查项未绑定有效站点，无法审核'}), 403
                denied = _site_access_denied(item['site_id'], '审核')
                if denied:
                    return denied
            for item_id in approve_item_ids:
                item = item_map[item_id]
                if item['review_status'] != 1:
                    return jsonify({
                        'error': '存在已审核或不可处理的检查项',
                        'item_id': item_id,
                        'code': 'REVIEW_ALREADY_PROCESSED',
                    }), 409

        # Qualification details are evaluated only after every requested object has passed
        # existence, type, scope, deletion and stale-state checks. This prevents a mixed-site
        # request from learning evidence state for an object the reviewer cannot access.
        for aid in attachment_decision_ids:
            att = attachment_map[aid]
            if dict(decisions).get(aid) == 'approve' and (
                    'evidence_qualification' not in att.keys()
                    or att['evidence_qualification'] != 'qualified'):
                return jsonify({
                    'error': att['evidence_reason'] if 'evidence_reason' in att.keys() and att['evidence_reason']
                    else '该照片尚不具备正式证据资格，普通审核不能放行',
                    'attachment_id': aid,
                    'code': 'EVIDENCE_NOT_QUALIFIED',
                    'next_action': att['evidence_next_action'] if 'evidence_next_action' in att.keys()
                    else '请补传原图或现场重拍',
                }), 409
        for item_id in approve_item_ids:
            item = item_map[item_id]
            gate = _evidence_gate(db, 'inspection', item_id, item['required_photos'])
            if gate:
                gate['item_id'] = item_id
                return jsonify(gate), 409

        for aid, decision in decisions:
            att = attachment_map[aid]
            new_status = 'approved' if decision == 'approve' else 'rejected'
            db.execute(
                '''UPDATE operation_attachments
                   SET review_status=?, reviewer_id=?, reviewed_at=?, reject_reason=?
                   WHERE id=? AND (review_status='pending' OR review_status IS NULL)''',
                (new_status, reviewer_id, now, reject_reason if decision == 'reject' else None, aid))
            changed = db.execute('SELECT changes()').fetchone()[0]
            if not changed:
                continue
            affected_sites.add(att['site_id'])
            attachment_source_type = att['source_type'] if 'source_type' in att.keys() else ''
            attachment_source_id = att['source_id'] if 'source_id' in att.keys() else 0
            if ('source_type' in att.keys() and 'source_id' in att.keys()
                    and attachment_source_type == 'inspection'
                    and attachment_source_id not in (None, '', 0, '0')):
                linked_items = db.execute(
                    'SELECT plan_id, site_id FROM insp_plan_items WHERE site_id=? AND id=?',
                    (att['site_id'], attachment_source_id)).fetchall()
            elif 'source_type' in att.keys() and 'source_id' in att.keys():
                linked_items = []
            else:
                linked_items = db.execute("""SELECT plan_id, site_id FROM insp_plan_items
                    WHERE site_id=? AND photo_urls LIKE ?""",
                    (att['site_id'], '%' + (att['stored_path'] or '') + '%')).fetchall()
            affected_inspection_batches.update((row['plan_id'], row['site_id']) for row in linked_items)
            approved_count += 1 if decision == 'approve' else 0
            rejected_count += 1 if decision == 'reject' else 0
            if decision == 'approve':
                _sync_replacement_evidence_state(db, dict(att, reviewer_id=reviewer_id), now)
            if decision == 'reject':
                rejection_reason = reject_reason or '现场照片未通过审核'
                replacement_item_id = _keep_replacement_required_after_rejection(
                    db, dict(att), reviewer_id, rejection_reason, now)
                linked_rejections = [] if replacement_item_id else _reopen_items_for_rejected_attachment(
                    db, att, reviewer_id, rejection_reason, now)
                rejected_item_rows.extend(linked_rejections)
                # Linked inspection evidence is actionable only through its plan/site
                # rework package. A per-photo reminder has no executable destination.
                if replacement_item_id:
                    replacement = db.execute("""SELECT i.plan_id,i.site_id,p.assignee_id
                        FROM insp_plan_items i JOIN insp_plans p ON p.id=i.plan_id
                        WHERE i.id=?""", (replacement_item_id,)).fetchone()
                    if replacement:
                        _notify_inspection_rework(
                            db, replacement['assignee_id'], replacement['plan_id'],
                            replacement['site_id'], 1, False)
                elif not linked_rejections and att['uploader_id']:
                    name = att['description'] or att['filename'] or f'照片#{aid}'
                    db.execute(
                        'INSERT INTO notifications (user_id, source_type, source_id, title, content) VALUES (?,?,?,?,?)',
                        (att['uploader_id'], 'photo_review', aid,
                         '照片被驳回',
                         f'「{name}」被驳回，原因：{reject_reason or "未达标"}。请重新拍摄上传。'))
        for item_id in approve_item_ids:
            item = db.execute('SELECT plan_id, site_id FROM insp_plan_items WHERE id=?', (item_id,)).fetchone()
            affected_inspection_batches.add((item['plan_id'], item['site_id']))
            db.execute("""UPDATE insp_plan_items
                SET review_status=2, reviewer_id=?, review_time=?
                WHERE id=? AND review_status=1""", (reviewer_id, now, item_id))
            approved_item_count += db.execute('SELECT changes()').fetchone()[0]
        rejection = _reject_inspection_items(
            db, rejected_item_rows, reviewer_id, now, 'attachment-review')
        for plan_id, site_id in affected_inspection_batches:
            pending_item = db.execute("""SELECT 1 FROM insp_plan_items
                WHERE plan_id=? AND site_id=? AND review_status=1
                  AND COALESCE(execution_status, 'active')='active' LIMIT 1""",
                (plan_id, site_id)).fetchone()
            attachment_conditions = ["a.review_status='pending'"]
            if _table_has_column(db, 'operation_attachments', 'is_deleted'):
                attachment_conditions.append('a.is_deleted=0')
            if _table_has_column(db, 'operation_attachments', 'review_required'):
                attachment_conditions.append('a.review_required=1')
            if _table_has_column(db, 'operation_attachments', 'source_type'):
                attachment_join = "a.source_type='inspection' AND a.source_id=i.id"
            else:
                attachment_join = "i.photo_urls LIKE '%' || a.stored_path || '%'"
            pending_attachment = db.execute(f"""SELECT 1 FROM operation_attachments a
                JOIN insp_plan_items i ON i.site_id=a.site_id AND (
                    {attachment_join}
                )
                WHERE i.plan_id=? AND i.site_id=? AND {' AND '.join(attachment_conditions)} LIMIT 1""",
                (plan_id, site_id)).fetchone()
            if not pending_item and not pending_attachment and _table_has_column(db, 'notifications', 'is_read'):
                db.execute("""UPDATE notifications SET is_read=1
                    WHERE source_type='inspection_review_batch' AND source_id=? AND is_read=0""",
                    (f'insp_batch_{plan_id}_{site_id}',))
        for site_id in affected_sites:
            pending_clauses = ["site_id=?", "(review_status='pending' OR review_status IS NULL)"]
            if _table_has_column(db, 'operation_attachments', 'is_deleted'):
                pending_clauses.append('is_deleted=0')
            if _table_has_column(db, 'operation_attachments', 'review_required'):
                pending_clauses.append('review_required=1')
            if _table_has_column(db, 'operation_attachments', 'source_type'):
                pending_clauses.append("source_type!='workorder'")
            remaining = db.execute(f"""SELECT 1 FROM operation_attachments
                WHERE {' AND '.join(pending_clauses)} LIMIT 1""", (site_id,)).fetchone()
            if not remaining and _table_has_column(db, 'notifications', 'is_read'):
                db.execute("""UPDATE notifications SET is_read=1
                    WHERE source_type IN ('attachment_review','attachment_review_batch')
                      AND source_id=?""", (site_id,))
        db.commit()
    return jsonify({'ok': True, 'count': approved_count + rejected_count,
                    'approved': approved_count, 'rejected': rejected_count,
                    'approved_items': approved_item_count,
                    'resource_replan_required': any(item.get('resource_replan_required') for item in rejection.values()),
                    'rework_plan_ids': sorted({item['rework_plan_id'] for item in rejection.values()
                                               if item.get('rework_plan_id')}),
                    'status': 'mixed' if approved_count and rejected_count else
                              ('rejected' if rejected_count else 'approved')})


def migrate_rejected_photo_rework():
    """Backfill rework state for rejected field photos created before this workflow."""
    with get_db() as db:
        rows = db.execute("""SELECT * FROM operation_attachments
            WHERE is_deleted=0 AND review_status='rejected' AND source_type='site_photo'""").fetchall()
        migrated = 0
        for attachment in rows:
            path = attachment['stored_path'] or ''
            if not path or not _table_has_column(db, 'insp_plan_items', 'rework_required_at'):
                continue
            if ('source_type' in attachment.keys() and 'source_id' in attachment.keys()
                    and not (attachment['source_type'] == 'inspection'
                             and attachment['source_id'] not in (None, '', 0, '0'))):
                continue
            pending = db.execute("""SELECT 1 FROM insp_plan_items
                WHERE site_id=? AND photo_urls LIKE ? AND COALESCE(review_status, 0)!=3
                  AND COALESCE(execution_status, 'active')='active' LIMIT 1""",
                (attachment['site_id'], '%' + path + '%')).fetchone()
            if not pending:
                continue
            reason = attachment['reject_reason'] or '现场照片未通过审核'
            reopened = _reopen_items_for_rejected_attachment(
                db, attachment, attachment['reviewer_id'] or 0,
                reason, attachment['reviewed_at'] or datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
            migrated += len(reopened)
        if migrated:
            db.commit()
    return migrated


def _legacy_photo_url_path(value):
    """Normalize a legacy photo URL to its full, decoded URL path only."""
    if not isinstance(value, str) or not value.strip():
        return ''
    parsed = urlsplit(value.strip())
    path = (parsed.path or value.strip().split('?', 1)[0].split('#', 1)[0]).replace('\\', '/')
    if not path.startswith('/'):
        path = '/' + path
    return unquote(path)


def _backfill_legacy_attachment_item_links(db):
    """Backfill only unique, JSON-photo_urls based historical associations."""
    if not (_table_has_column(db, 'insp_plan_items', 'photo_urls')
            and all(_table_has_column(db, 'operation_attachments', column)
                    for column in ('stored_path', 'filename', 'site_id', 'plan_id', 'item_id', 'item_name'))):
        return 0
    db.execute('''CREATE TABLE IF NOT EXISTS attachment_link_migration_issues (
        attachment_id INTEGER PRIMARY KEY, reason TEXT NOT NULL,
        candidate_item_ids TEXT DEFAULT '[]', created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP)''')
    references = {}
    items_by_id = {}
    for row in db.execute('SELECT id, plan_id, site_id, item_name, photo_urls FROM insp_plan_items').fetchall():
        items_by_id[row['id']] = dict(row)
        try:
            urls = json.loads(row['photo_urls'] or '[]')
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(urls, list):
            continue
        for url in urls:
            key = _legacy_photo_url_path(url)
            if key:
                references.setdefault(key, []).append(dict(row))
    changed = 0
    rows = db.execute("""SELECT id, stored_path, filename, site_id, plan_id, item_id, item_name
        FROM operation_attachments WHERE COALESCE(is_deleted, 0)=0""").fetchall()
    for attachment in rows:
        key = _legacy_photo_url_path(attachment['stored_path'])
        matches = {item['id']: item for item in references.get(key, [])
                   if attachment['site_id'] in (None, 0, item['site_id'])}
        if not matches:
            db.execute("""INSERT INTO attachment_link_migration_issues
                (attachment_id, reason, candidate_item_ids, updated_at) VALUES (?, 'no_unique_url_match', '[]', CURRENT_TIMESTAMP)
                ON CONFLICT(attachment_id) DO UPDATE SET reason=excluded.reason, candidate_item_ids=excluded.candidate_item_ids, updated_at=excluded.updated_at""", (attachment['id'],))
            continue
        if len(matches) != 1:
            db.execute("""INSERT INTO attachment_link_migration_issues
                (attachment_id, reason, candidate_item_ids, updated_at) VALUES (?, 'multiple_url_matches', ?, CURRENT_TIMESTAMP)
                ON CONFLICT(attachment_id) DO UPDATE SET reason=excluded.reason, candidate_item_ids=excluded.candidate_item_ids, updated_at=excluded.updated_at""",
                (attachment['id'], json.dumps(sorted(matches))))
            continue
        item = next(iter(matches.values()))
        existing_item = items_by_id.get(attachment['item_id'])
        if existing_item:
            if existing_item['id'] == item['id'] and attachment['plan_id'] == item['plan_id']:
                continue
            db.execute("""INSERT INTO attachment_link_migration_issues
                (attachment_id, reason, candidate_item_ids, updated_at) VALUES (?, 'existing_association_conflict', ?, CURRENT_TIMESTAMP)
                ON CONFLICT(attachment_id) DO UPDATE SET reason=excluded.reason, candidate_item_ids=excluded.candidate_item_ids, updated_at=excluded.updated_at""",
                (attachment['id'], json.dumps([item['id']])))
            continue
        # Never overwrite an existing non-empty contradictory association.
        if attachment['plan_id'] not in (None, 0, item['plan_id']):
            db.execute("""INSERT INTO attachment_link_migration_issues
                (attachment_id, reason, candidate_item_ids, updated_at) VALUES (?, 'existing_association_conflict', ?, CURRENT_TIMESTAMP)
                ON CONFLICT(attachment_id) DO UPDATE SET reason=excluded.reason, candidate_item_ids=excluded.candidate_item_ids, updated_at=excluded.updated_at""",
                (attachment['id'], json.dumps([item['id']])))
            continue
        db.execute("""UPDATE operation_attachments
            SET plan_id=?, item_id=?, item_name=?, site_id=?
            WHERE id=? AND COALESCE(item_id, 0)=0
              AND (plan_id IS NULL OR plan_id=0 OR plan_id=?)""",
            (item['plan_id'], item['id'], item['item_name'] or '', item['site_id'], attachment['id'], item['plan_id']))
        changed += db.execute('SELECT changes()').fetchone()[0]
        if changed:
            db.execute('DELETE FROM attachment_link_migration_issues WHERE attachment_id=?', (attachment['id'],))
    return changed


def migrate_attachment_evidence_closure():
    """Additive migration for voided evidence and item-level replacement state."""
    with get_db() as db:
        try:
            attachment_columns = {
                'archive_name': "TEXT DEFAULT ''",
                'voided_at': 'TEXT',
                'voided_by': 'INTEGER',
                'void_reason': "TEXT DEFAULT ''",
                'plan_id': 'INTEGER',
                'item_id': 'INTEGER',
                'item_name': "TEXT DEFAULT ''",
            }
            item_columns = {
                'evidence_status': "TEXT DEFAULT ''",
                'supplement_required_at': "TEXT DEFAULT ''",
                'supplement_source_attachment_id': 'INTEGER',
                'supplement_reason': "TEXT DEFAULT ''",
            }
            for column, column_type in attachment_columns.items():
                if not _table_has_column(db, 'operation_attachments', column):
                    db.execute(f'ALTER TABLE operation_attachments ADD COLUMN {column} {column_type}')
            for column, column_type in item_columns.items():
                if not _table_has_column(db, 'insp_plan_items', column):
                    db.execute(f'ALTER TABLE insp_plan_items ADD COLUMN {column} {column_type}')
            db.execute('''CREATE TABLE IF NOT EXISTS attachment_void_audits (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                attachment_id INTEGER NOT NULL UNIQUE,
                original_source_type TEXT DEFAULT '',
                original_source_id INTEGER,
                original_site_id INTEGER,
                original_plan_id INTEGER,
                original_item_id INTEGER,
                original_item_name TEXT DEFAULT '',
                original_site_name TEXT DEFAULT '',
                original_uploader_id INTEGER,
                original_uploader_name TEXT DEFAULT '',
                original_archive_name TEXT DEFAULT '',
                original_review_status TEXT DEFAULT '',
                original_reviewer_id INTEGER,
                original_reviewed_at TEXT,
                original_risk_snapshot TEXT DEFAULT '{}',
                original_state TEXT NOT NULL DEFAULT '{}',
                replacement_item_id INTEGER,
                replacement_plan_id INTEGER,
                replacement_required INTEGER NOT NULL DEFAULT 1,
                operator_id INTEGER NOT NULL,
                operator_name TEXT DEFAULT '',
                reason TEXT NOT NULL,
                voided_at TEXT NOT NULL,
                created_at TEXT DEFAULT (datetime('now','localtime'))
            )''')
            for column, column_type in {
                'original_plan_id': 'INTEGER', 'original_item_id': 'INTEGER',
                'original_item_name': "TEXT DEFAULT ''", 'original_site_name': "TEXT DEFAULT ''",
                'original_uploader_id': 'INTEGER', 'original_uploader_name': "TEXT DEFAULT ''",
                'original_archive_name': "TEXT DEFAULT ''",
            }.items():
                if not _table_has_column(db, 'attachment_void_audits', column):
                    db.execute(f'ALTER TABLE attachment_void_audits ADD COLUMN {column} {column_type}')
            # Only source_type/source_id is allowed to establish a legacy link.
            # Filenames, descriptions and photo_urls are deliberately excluded.
            if (_table_exists(db, 'operation_attachments')
                    and _table_exists(db, 'insp_plan_items')
                    and all(_table_has_column(db, 'operation_attachments', column)
                            for column in ('source_type', 'source_id', 'plan_id', 'item_id', 'item_name'))):
                db.execute("""UPDATE operation_attachments
                    SET plan_id=(SELECT i.plan_id FROM insp_plan_items i
                                 WHERE i.id=operation_attachments.source_id),
                        item_id=source_id,
                        item_name=COALESCE((SELECT i.item_name FROM insp_plan_items i
                                           WHERE i.id=operation_attachments.source_id), '检查项待确认')
                    WHERE source_type='inspection' AND COALESCE(source_id, 0) != 0
                      AND EXISTS (SELECT 1 FROM insp_plan_items i
                                  WHERE i.id=operation_attachments.source_id)""")
                db.execute("""UPDATE operation_attachments
                    SET item_name='检查项待确认'
                    WHERE source_type='inspection' AND COALESCE(source_id, 0)=0
                      AND COALESCE(item_name, '')=''""")
                _backfill_legacy_attachment_item_links(db)
            db.execute('CREATE INDEX IF NOT EXISTS idx_attachment_void_audit_item '
                       'ON attachment_void_audits(replacement_item_id)')
            db.execute('CREATE INDEX IF NOT EXISTS idx_attachment_void_audit_site '
                       'ON attachment_void_audits(original_site_id)')
            db.commit()
        except Exception as exc:
            # Startup migrations are intentionally additive and must not prevent a
            # legacy read-only database from booting; the write endpoint still
            # returns a clear server error when its required table is unavailable.
            print(f'[Migrate] attachment evidence closure skipped: {exc}')


@app.route('/api/operation-attachments/reevaluate', methods=['POST'])
def api_attachments_reevaluate():
    """回填历史照片的标红字段（迁移/规则变更后一次性执行）"""
    g_ = require_admin()
    if g_:
        return g_
    with get_db() as db:
        rows = db.execute(
            "SELECT id, site_id, source_type, source_id, gps_lat, gps_lng, taken_at "
            "FROM operation_attachments WHERE is_deleted=0").fetchall()
        updated = 0
