# ===================== 影像抽样审核：标红规则引擎 =====================
SITE_GEOFENCE_M = 300         # 到站、离站及正式现场证据共用围栏（米）
GPS_DEVIATION_M = SITE_GEOFENCE_M
FUTURE_SKEW_S = 300           # 拍摄时间"未来"容差（秒），防时钟抖动误判
STALE_REF_DAYS = 3            # 拍摄时间与关联任务日期的偏差阈值（天）
EVIDENCE_TIME_TOLERANCE_S = 5 * 60
EVIDENCE_CAMERA_SESSION_S = 15 * 60
EVIDENCE_DELAY_REVIEW_S = 24 * 60 * 60
EVIDENCE_WATERMARK_CONFIDENCE = 0.85
EVIDENCE_RULE_VERSION = 'evidence-v1'


def _ratio_float(value):
    try:
        return float(value)
    except (TypeError, ValueError, ZeroDivisionError):
        try:
            return float(value[0]) / float(value[1])
        except (TypeError, ValueError, ZeroDivisionError, IndexError):
            return None


def _gps_dms_to_decimal(values, ref):
    if not values or len(values) < 3:
        return None
    parts = [_ratio_float(value) for value in values[:3]]
    if any(value is None for value in parts):
        return None
    result = parts[0] + parts[1] / 60 + parts[2] / 3600
    if str(ref or '').upper() in ('S', 'W'):
        result = -result
    return round(result, 7)


def _extract_image_capture_metadata(image_bytes):
    """Read capture metadata from the original image before any server compression."""
    result = {'taken_at': None, 'gps_lat': None, 'gps_lng': None, 'metadata_source': ''}
    try:
        from PIL import Image
        import io
        with Image.open(io.BytesIO(image_bytes)) as image:
            exif = image.getexif()
            taken = exif.get(36867) or exif.get(36868) or exif.get(306)
            parsed = _parse_dt(str(taken).replace(':', '-', 2)) if taken else None
            if parsed:
                result['taken_at'] = parsed.strftime('%Y-%m-%d %H:%M:%S')
            gps = {}
            try:
                gps = exif.get_ifd(34853) or {}
            except (AttributeError, KeyError, TypeError):
                raw_exif = image._getexif() or {}
                gps = raw_exif.get(34853) or {}
            result['gps_lat'] = _gps_dms_to_decimal(gps.get(2), gps.get(1))
            result['gps_lng'] = _gps_dms_to_decimal(gps.get(4), gps.get(3))
            if result['taken_at'] or result['gps_lat'] is not None:
                result['metadata_source'] = 'exif'
    except Exception:
        pass
    return result


def _compress_site_photo(image_bytes):
    """Create the stored copy after metadata/hash extraction; fall back to the original."""
    try:
        from PIL import Image
        import io
        with Image.open(io.BytesIO(image_bytes)) as image:
            if image.mode not in ('RGB', 'L'):
                image = image.convert('RGB')
            max_side = 1920
            if max(image.size) > max_side:
                ratio = max_side / max(image.size)
                image = image.resize(
                    (max(1, int(image.size[0] * ratio)), max(1, int(image.size[1] * ratio))),
                    Image.LANCZOS,
                )
            buffer = io.BytesIO()
            image.save(buffer, format='JPEG', quality=78, optimize=True)
            return buffer.getvalue()
    except Exception:
        return image_bytes


def _image_difference_hash(image_bytes):
    """64-bit dHash: resilient to resizing and JPEG recompression, used only for review hints."""
    try:
        from PIL import Image
        import io
        with Image.open(io.BytesIO(image_bytes)) as image:
            resized = image.convert('L').resize((9, 8), Image.LANCZOS)
            getter = getattr(resized, 'get_flattened_data', resized.getdata)
            pixels = list(getter())
        bits = 0
        for y in range(8):
            row = y * 9
            for x in range(8):
                bits = (bits << 1) | int(pixels[row + x] > pixels[row + x + 1])
        return f'{bits:016x}'
    except Exception:
        return ''


def _hash_distance(left, right):
    try:
        return (int(left, 16) ^ int(right, 16)).bit_count()
    except (TypeError, ValueError):
        return 65


_WATERMARK_OCR = None
_WATERMARK_OCR_UNAVAILABLE = False
import threading as _threading
_WATERMARK_OCR_LOCK = _threading.Lock()


def _recognize_watermark(image_bytes):
    """Try the common watermark band first, then the full image as a fallback."""
    global _WATERMARK_OCR, _WATERMARK_OCR_UNAVAILABLE
    result = {'text': '', 'confidence': None, 'status': 'unavailable'}
    if _WATERMARK_OCR_UNAVAILABLE:
        return result
    try:
        from rapidocr_onnxruntime import RapidOCR
        from PIL import Image
        import io
        import numpy as np
        with Image.open(io.BytesIO(image_bytes)) as image:
            image = image.convert('RGB')
            band_array = np.asarray(image.crop((0, int(image.height * 0.65), image.width, image.height)))
            full_array = np.asarray(image)
        with _WATERMARK_OCR_LOCK:
            if _WATERMARK_OCR is None:
                _WATERMARK_OCR = RapidOCR()
            rows, _ = _WATERMARK_OCR(band_array)
            if not rows:
                rows, _ = _WATERMARK_OCR(full_array)
        rows = rows or []
        texts = [str(row[1]).strip() for row in rows if len(row) > 2 and str(row[1]).strip()]
        scores = [float(row[2]) for row in rows if len(row) > 2]
        result.update({
            'text': '\n'.join(texts),
            'confidence': round(sum(scores) / len(scores), 3) if scores else None,
            'status': 'recognized' if texts else 'unreadable',
        })
    except ImportError:
        _WATERMARK_OCR_UNAVAILABLE = True
    except Exception:
        result['status'] = 'error'
    return result


def _parse_watermark_fields(text):
    import re
    result = {'taken_at': None, 'gps_lat': None, 'gps_lng': None, 'code': ''}
    raw = str(text or '')
    date_match = re.search(
        r'(20\d{2})[.\-/年](\d{1,2})[.\-/月](\d{1,2})日?\s*(\d{1,2})\s*[:：]\s*(\d{2})', raw)
    if date_match:
        values = [int(value) for value in date_match.groups()]
        try:
            result['taken_at'] = datetime(*values).strftime('%Y-%m-%d %H:%M:%S')
        except ValueError:
            pass
    gps_match = re.search(
        r'(\d{1,2}\.\d{4,})\s*[^\dA-Z]{0,3}[NS]?\s*[,，、 ]+\s*(\d{2,3}\.\d{4,})', raw, re.I)
    if gps_match:
        result['gps_lat'] = float(gps_match.group(1))
        result['gps_lng'] = float(gps_match.group(2))
    codes = re.findall(
        r'(?<![A-Z0-9])(?=[A-Z0-9]{10,24}(?![A-Z0-9]))(?=[A-Z0-9]*[A-Z])(?=[A-Z0-9]*\d)[A-Z0-9]+(?![A-Z0-9])',
        raw.upper())
    if codes:
        result['code'] = codes[-1]
    return result


def _attachment_business_window(db, source_type, source_id, site_id, uploader_id, now=None,
                                session=None, rework_required_at=None):
    """Resolve the server-owned arrival/work window for formal evidence."""
    now = now or datetime.now()
    source = str(source_type or '').lower()
    if source == 'inspection' and source_id and _table_exists(db, 'insp_plan_items'):
        item = db.execute('SELECT * FROM insp_plan_items WHERE id=? AND site_id=?',
                          (source_id, site_id)).fetchone()
        if not item:
            return None
        if session and session.get('rework_required_at'):
            required_at = _parse_dt(session.get('rework_required_at'))
            issued_at = _parse_dt(session.get('issued_at'))
            expires_at = _parse_dt(session.get('expires_at'))
            if required_at and issued_at:
                return {'start': max(required_at, issued_at - timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S)),
                        'end': expires_at or now,
                        'business_type': 'inspection_retake', 'business_id': str(source_id)}
        required_at = _parse_dt(rework_required_at)
        if required_at:
            return {'start': required_at, 'end': now,
                    'business_type': 'inspection_retake', 'business_id': str(source_id)}
        start = _parse_dt(item['check_in_time']) if 'check_in_time' in item.keys() else None
        if not start:
            checkin = db.execute("""SELECT check_time FROM inspection_checkins
                WHERE site_id=? AND user_id=? ORDER BY datetime(check_time) DESC LIMIT 1""",
                (site_id, uploader_id)).fetchone() if _table_exists(db, 'inspection_checkins') else None
            start = _parse_dt(checkin['check_time']) if checkin else None
        upper = next((item[key] for key in ('check_out_time', 'completed_at', 'check_time')
                      if key in item.keys() and item[key]), None)
        return {'start': start, 'end': _parse_dt(upper) or now,
                'business_type': 'inspection', 'business_id': str(source_id)}
    if source == 'workorder' and source_id and _table_exists(db, 'work_orders'):
        order = db.execute('SELECT * FROM work_orders WHERE id=? AND site_id=?',
                           (source_id, site_id)).fetchone()
        if not order:
            return None
        start = _parse_dt(order['check_in_time']) if 'check_in_time' in order.keys() else None
        upper = next((order[key] for key in ('review_submitted_at', 'resolved_at')
                      if key in order.keys() and order[key]), None)
        return {'start': start, 'end': _parse_dt(upper) or now,
                'business_type': 'workorder', 'business_id': str(source_id)}
    return None


def _capture_session_row(db, token, *, user_id, site_id, plan_id=None, item_id=None,
                         work_order_id=None, received_at=None, capture_source=None,
                         rework_required_at=None):
    if not token or not _table_exists(db, 'photo_capture_sessions'):
        return None
    row = db.execute('SELECT * FROM photo_capture_sessions WHERE token_hash=?',
                     (_hash_token(str(token)),)).fetchone()
    if not row or row['used_at'] or row['user_id'] != user_id or row['site_id'] != site_id:
        return None
    if item_id and row['item_id'] != int(item_id):
        return None
    if plan_id and row['plan_id'] != int(plan_id):
        return None
    if work_order_id and row['work_order_id'] != int(work_order_id):
        return None
    if capture_source and 'capture_source' in row.keys() and row['capture_source'] \
            and row['capture_source'] != capture_source:
        return None
    if rework_required_at is not None:
        stored_required = row['rework_required_at'] if 'rework_required_at' in row.keys() else None
        if str(stored_required or '') != str(rework_required_at or ''):
            return None
    if (received_at or datetime.now()) > (_parse_dt(row['expires_at']) or datetime.min):
        return None
    return dict(row)


def _reserve_capture_session(db, session, used_at):
    """Atomically reserve a one-time session inside the upload transaction."""
    if not session:
        return None
    db.execute("""UPDATE photo_capture_sessions SET used_at=?,attachment_id=-1
        WHERE id=? AND used_at IS NULL""", (used_at, session['id']))
    return session if db.execute('SELECT changes()').fetchone()[0] == 1 else None


def _assess_attachment_evidence(db, *, source_type, source_id, site_id, uploader_id,
                                received_at, capture_source='', client_taken_at=None,
                                exif_taken_at=None, watermark_fields=None,
                                watermark_confidence=None, watermark_status='', gps_lat=None,
                                gps_lng=None, duplicate_of_id=None, session=None,
                                manual_basis=None, manual_taken_at=None, manual_reference='',
                                rework_required_at=None):
    """Compute evidence qualification from server-verifiable facts."""
    received = _parse_dt(received_at) or datetime.now()
    exif_time = _parse_dt(exif_taken_at)
    watermark_fields = watermark_fields or {}
    watermark_time = _parse_dt(watermark_fields.get('taken_at'))
    client_time = _parse_dt(client_taken_at)
    manual_time = _parse_dt(manual_taken_at)
    facts = {
        'capture_source': capture_source or 'unknown', 'client_taken_at': client_taken_at,
        'exif_taken_at': exif_taken_at, 'watermark_taken_at': watermark_fields.get('taken_at'),
        'watermark_gps': [watermark_fields.get('gps_lat'), watermark_fields.get('gps_lng')],
        'watermark_code': watermark_fields.get('code') or '',
        'watermark_confidence': watermark_confidence, 'watermark_status': watermark_status or '',
        'received_at': received.strftime('%Y-%m-%d %H:%M:%S'), 'gps': [gps_lat, gps_lng],
        'duplicate_of_id': duplicate_of_id, 'capture_session_id': session.get('id') if session else None,
        'manual_reference': manual_reference or '',
        'source_type': source_type, 'source_id': source_id, 'site_id': site_id,
        'uploader_id': uploader_id, 'rework_required_at': rework_required_at or '',
    }

    def result(qualification, basis, taken_at, reason, next_action):
        return {'qualification': qualification, 'basis': basis,
                'taken_at': taken_at.strftime('%Y-%m-%d %H:%M:%S') if taken_at else None,
                'reason': reason, 'next_action': next_action, 'facts': facts}

    if capture_source == 'camera' and not session:
        return result('ineligible', 'unknown', None,
                      '未取得服务端现场拍摄授权，不能作为必需现场照片',
                      '请从检查项重新发起现场拍摄')
    if capture_source not in ('camera', 'watermark_album') and not manual_basis:
        return result('ineligible', 'unknown', None,
                      '普通相册或网页上传只能作为补充材料，不能满足强制现场证据',
                      '请使用现场拍摄或选择可验证的水印原图')
    if duplicate_of_id:
        return result('ineligible', 'duplicate', None,
                      f'与影像#{duplicate_of_id}重复，不能作为新的正式证据', '请现场重拍不同照片')

    supplied_coords = _parse_gps_pair(gps_lat, gps_lng)
    watermark_lat = watermark_fields.get('gps_lat')
    watermark_lng = watermark_fields.get('gps_lng')
    watermark_coords = _parse_gps_pair(watermark_lat, watermark_lng)
    if ((gps_lat is not None or gps_lng is not None) and supplied_coords is None):
        return result('ineligible', 'location_conflict', None,
                      '照片中的经纬度格式或范围无效，不能作为正式证据',
                      '请改用现场拍照，或选择包含有效位置的水印原图')
    if ((watermark_lat is not None or watermark_lng is not None) and watermark_coords is None):
        return result('ineligible', 'location_conflict', None,
                      '水印中的经纬度格式或范围无效，不能作为正式证据',
                      '请改用现场拍照，或选择包含有效位置的水印原图')
    if supplied_coords and watermark_coords:
        coordinate_conflict_m = _haversine(*supplied_coords, *watermark_coords)
        facts['coordinate_conflict_m'] = (round(coordinate_conflict_m, 1)
                                          if coordinate_conflict_m is not None else None)
        if coordinate_conflict_m is None or coordinate_conflict_m > GPS_DEVIATION_M:
            return result('ineligible', 'location_conflict', None,
                          'EXIF与水印位置冲突，不能作为正式证据',
                          '请改用来源信息一致的原图或现场重拍')

    window = _attachment_business_window(
        db, source_type, source_id, site_id, uploader_id, now=received, session=session,
        rework_required_at=rework_required_at)
    facts['work_window'] = {
        'start': window['start'].strftime('%Y-%m-%d %H:%M:%S') if window and window['start'] else None,
        'end': window['end'].strftime('%Y-%m-%d %H:%M:%S') if window and window['end'] else None,
    }
    if not window or not window['start']:
        return result('ineligible', 'unknown', None,
                      '没有可验证的到站记录或作业窗口，不计入有效证据', '请完成到站签到后现场重拍')

    complete_watermark = (
        watermark_status == 'recognized' and watermark_time is not None
        and watermark_confidence is not None and float(watermark_confidence) >= EVIDENCE_WATERMARK_CONFIDENCE
        and ((watermark_fields.get('gps_lat') is not None and watermark_fields.get('gps_lng') is not None)
             or bool(watermark_fields.get('code'))))
    candidate = None
    basis = 'unknown'
    if manual_basis in ('visible_watermark', 'exif', 'resolved_conflict') and manual_time and manual_reference:
        candidate, basis = manual_time, f'manual_{manual_basis}'
    elif session and capture_source == 'camera':
        issued_at = _parse_dt(session.get('issued_at'))
        if exif_time and issued_at and exif_time < window['start'] - timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S):
            return result('ineligible', 'time_conflict', exif_time,
                          '原图拍摄时间早于本轮返场补拍，不能作为替代证据', '请在现场重新拍摄')
        issued_at = _parse_dt(session.get('issued_at'))
        candidate = (client_time if client_time and
                     issued_at - timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S) <= client_time <=
                     received + timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S) else issued_at)
        basis = 'camera_session'
    elif exif_time and watermark_time and complete_watermark:
        if abs((exif_time - watermark_time).total_seconds()) > EVIDENCE_TIME_TOLERANCE_S:
            return result('ineligible', 'time_conflict', None,
                          'EXIF与完整水印时间冲突，不计入有效证据',
                          '请由管理员核对原图和独立依据，或现场重拍')
        candidate, basis = exif_time, 'exif_watermark'
    elif exif_time:
        candidate, basis = exif_time, 'exif'
    elif complete_watermark:
        candidate, basis = watermark_time, 'watermark'
    else:
        next_action = ('请管理员从原图人工核录清晰水印，或现场重拍'
                       if watermark_status in ('unreadable', 'error') else '请选择原图或现场重拍')
        return result('ineligible', 'unknown', None,
                      '拍摄时间缺少可确认依据，不计入有效证据', next_action)

    required_retake_time = _parse_dt(rework_required_at)
    if required_retake_time and candidate < required_retake_time:
        return result('ineligible', 'time_conflict', candidate,
                      '照片拍摄时间早于本轮补拍要求，不能作为本次替代证据',
                      '请改用现场拍照，或选择本轮退回后拍摄的水印原图')

    if candidate > received + timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S):
        return result('ineligible', 'time_conflict', candidate,
                      '拍摄时间晚于服务器接收时间超过5分钟，不计入有效证据',
                      '请核对原图时间设置或现场重拍')
    if candidate < window['start'] - timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S):
        return result('ineligible', basis, candidate,
                      '拍摄时间早于到站签到超过5分钟，不计入有效证据',
                      '请使用到站后的原图或现场重拍')
    if candidate > window['end'] + timedelta(seconds=EVIDENCE_TIME_TOLERANCE_S):
        return result('ineligible', basis, candidate,
                      '拍摄时间超出本次作业窗口，不计入有效证据', '请核对业务归属或现场重拍')
    if not manual_basis and received - candidate > timedelta(seconds=EVIDENCE_DELAY_REVIEW_S):
        return result('review', basis, candidate, '首次上传距拍摄超过24小时，需管理员核对原图',
                      '请管理员核对延迟原因和原图后人工确认依据')
    if gps_lat is None or gps_lng is None:
        return result('review', basis, candidate, '缺少可核对的位置，暂不计入有效证据',
                      '请补传含位置的原图，或由管理员核对原图中的位置依据')
    site = db.execute('SELECT gps_lat,gps_lng FROM sites WHERE id=?', (site_id,)).fetchone()
    if not site or site['gps_lat'] is None or site['gps_lng'] is None:
        return result('review', basis, candidate, '站点基准位置缺失，暂不能核对证据位置',
                      '请管理员先维护站点基准位置')
    site_coords = _parse_gps_pair(site['gps_lat'], site['gps_lng'])
    if supplied_coords is None or site_coords is None:
        return result('ineligible', 'location_conflict', candidate,
                      '照片或站点经纬度无效，不能作为正式证据',
                      '请核对站点位置后重新拍摄或选择原图')
    distance = _haversine(*supplied_coords, *site_coords)
    if distance is None:
        return result('ineligible', 'location_conflict', candidate,
                      '无法核对照片与站点的位置，不能作为正式证据',
                      '请核对站点位置后重新拍摄或选择原图')
    facts['distance_m'] = round(distance, 1)
    if distance > GPS_DEVIATION_M:
        return result('ineligible', basis, candidate,
                      f'照片位置偏离站点{distance:.0f}米，超过300米范围',
                      '请核对业务归属或在站点范围内重拍')
    return result('qualified', basis, candidate, '时间、作业窗口、位置与重复性检查均通过', '')


def _record_attachment_evaluation(db, attachment_id, assessment, *, evaluation_type='automatic',
                                  actor_id=None, actor_name='', replaces_evaluation_id=None):
    if not _table_exists(db, 'attachment_evidence_evaluations'):
        return None
    cur = db.execute("""INSERT INTO attachment_evidence_evaluations
        (attachment_id,qualification,basis,verified_taken_at,reason,next_action,facts_json,
         evaluation_type,rule_version,actor_id,actor_name,replaces_evaluation_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""", (
        attachment_id, assessment['qualification'], assessment['basis'], assessment.get('taken_at'),
        assessment.get('reason') or '', assessment.get('next_action') or '',
        json.dumps(assessment.get('facts') or {}, ensure_ascii=False), evaluation_type,
        EVIDENCE_RULE_VERSION, actor_id, actor_name or '', replaces_evaluation_id,
    ))
    evaluation_id = cur.lastrowid
    if _table_has_column(db, 'operation_attachments', 'evidence_qualification'):
        db.execute("""UPDATE operation_attachments SET
            evidence_qualification=?, evidence_basis=?, evidence_reason=?, evidence_next_action=?,
            evidence_evaluated_at=datetime('now','localtime'), evidence_evaluation_id=?,
            taken_at=? WHERE id=?""", (
            assessment['qualification'], assessment['basis'], assessment.get('reason') or '',
            assessment.get('next_action') or '', evaluation_id, assessment.get('taken_at'), attachment_id,
        ))
    return evaluation_id


def _qualified_attachment_sql(alias='operation_attachments'):
    return (f"COALESCE({alias}.is_deleted,0)=0 AND "
            f"COALESCE({alias}.review_status,'pending') NOT IN ('rejected','voided') AND "
            f"COALESCE({alias}.evidence_qualification,'review')='qualified' AND "
            f"COALESCE(json_extract(CASE WHEN json_valid({alias}.extra_json) "
            f"THEN {alias}.extra_json ELSE '{{}}' END, '$.material_role'),'formal')!='supplement'")


def _qualified_evidence_count(db, source_type, source_id, stored_paths=None):
    if not _table_has_column(db, 'operation_attachments', 'evidence_qualification'):
        return 0
    where = ['source_type=?', 'source_id=?', "evidence_qualification='qualified'"]
    if _table_has_column(db, 'operation_attachments', 'is_deleted'):
        where.append('COALESCE(is_deleted,0)=0')
    if _table_has_column(db, 'operation_attachments', 'review_status'):
        where.append("COALESCE(review_status,'pending') NOT IN ('rejected','voided')")
    if _table_has_column(db, 'operation_attachments', 'extra_json'):
        where.append("COALESCE(json_extract(CASE WHEN json_valid(extra_json) "
                     "THEN extra_json ELSE '{}' END, '$.material_role'),'formal')!='supplement'")
    params = [source_type, source_id]
    if stored_paths is not None:
        normalized = list(dict.fromkeys(_attachment_storage_path(path) for path in stored_paths if path))
        if not normalized:
            return 0
        where.append(f"stored_path IN ({','.join('?' * len(normalized))})")
        params.extend(normalized)
    return db.execute(f"SELECT COUNT(*) FROM operation_attachments WHERE {' AND '.join(where)}",
                      params).fetchone()[0]


def _watermark_retake_evaluation_matches(db, attachment, required_cycle):
    """Verify a watermark retake from the immutable automatic evaluation facts."""
    keys = set(attachment.keys())
    if ('capture_source' not in keys or attachment['capture_source'] != 'watermark_album'
            or 'evidence_evaluation_id' not in keys or not attachment['evidence_evaluation_id']
            or not _table_exists(db, 'attachment_evidence_evaluations')):
        return False
    evaluation = db.execute("""SELECT * FROM attachment_evidence_evaluations
        WHERE id=? AND attachment_id=?""",
        (attachment['evidence_evaluation_id'], attachment['id'])).fetchone()
    if (not evaluation or evaluation['qualification'] != 'qualified'
            or evaluation['evaluation_type'] != 'automatic'
            or evaluation['basis'] not in ('exif', 'watermark', 'exif_watermark')):
        return False
    try:
        facts = json.loads(evaluation['facts_json'] or '{}')
        attachment_extra = json.loads(attachment['extra_json'] or '{}') \
            if 'extra_json' in keys else {}
    except (TypeError, json.JSONDecodeError):
        return False
    required_at = _parse_dt(required_cycle)
    verified_at = _parse_dt(evaluation['verified_taken_at'])
    try:
        distance_m = float(facts.get('distance_m'))
        fact_source_id = int(facts.get('source_id'))
        fact_site_id = int(facts.get('site_id'))
        fact_uploader_id = int(facts.get('uploader_id'))
    except (TypeError, ValueError):
        return False
    return bool(
        required_at and verified_at and verified_at >= required_at
        and str(facts.get('rework_required_at') or '') == str(required_cycle or '')
        and facts.get('capture_source') == 'watermark_album'
        and not facts.get('capture_session_id')
        and not facts.get('duplicate_of_id')
        and distance_m <= GPS_DEVIATION_M
        and facts.get('source_type') == 'inspection'
        and fact_source_id == int(
            attachment['source_id'] or attachment_extra.get('item_id') or 0)
        and fact_site_id == int(attachment['site_id'] or 0)
        and fact_uploader_id == int(attachment['uploader_id'] or 0)
    )


def _attachment_original_file(attachment):
    path = _attachment_storage_path(attachment.get('stored_path'))
    if not path.startswith('/uploads/'):
        return None
    target = os.path.abspath(os.path.join(UPLOAD_DIR, path[len('/uploads/'):].replace('/', os.sep)))
    root = os.path.abspath(UPLOAD_DIR)
    return target if os.path.commonpath([root, target]) == root and os.path.isfile(target) else None


def _historical_attachment_assessment(db, attachment):
    original_path = _attachment_original_file(attachment)
    extracted = {}
    if original_path:
        try:
            with open(original_path, 'rb') as source:
                extracted = _extract_image_capture_metadata(source.read())
        except OSError:
            extracted = {}
    try:
        extra = json.loads(attachment.get('extra_json') or '{}')
    except (TypeError, json.JSONDecodeError):
        extra = {}
    watermark_fields = extra.get('watermark_fields') or _parse_watermark_fields(
        attachment.get('watermark_text'))
    return _assess_attachment_evidence(
        db, source_type=attachment.get('source_type'), source_id=attachment.get('source_id'),
        site_id=attachment.get('site_id'), uploader_id=attachment.get('uploader_id'),
        received_at=attachment.get('created_at') or datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        capture_source=attachment.get('capture_source'), exif_taken_at=extracted.get('taken_at'),
        watermark_fields=watermark_fields, watermark_confidence=extra.get('ocr_confidence'),
        watermark_status=extra.get('ocr_status') or '',
        gps_lat=extracted.get('gps_lat') if extracted.get('gps_lat') is not None else attachment.get('gps_lat'),
        gps_lng=extracted.get('gps_lng') if extracted.get('gps_lng') is not None else attachment.get('gps_lng'),
        duplicate_of_id=attachment.get('duplicate_of_id'))


def _create_evidence_remediation(db, attachment, reason):
    source_type = str(attachment.get('source_type') or '')
    source_id = attachment.get('source_id')
    if not source_id or source_type not in ('inspection', 'workorder'):
        return None
    if source_type == 'inspection':
        active = db.execute("""SELECT 1 FROM insp_plan_items i JOIN insp_plans p ON p.id=i.plan_id
            WHERE i.id=? AND (i.result IS NOT NULL OR p.status IN ('active','completed','submitted','approved'))""",
            (source_id,)).fetchone()
    else:
        active = db.execute("""SELECT 1 FROM work_orders
            WHERE id=? AND status IN ('in_progress','reviewing','closed','resolved')""",
            (source_id,)).fetchone()
    if not active:
        return None
    due_at = (datetime.now() + timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
    db.execute("""INSERT INTO evidence_quality_remediations
        (attachment_id,business_type,business_id,status,reason,due_at,resolution,resolved_at)
        VALUES (?,?,?,'open',?,?,'',NULL)
        ON CONFLICT(attachment_id,business_type,business_id) DO UPDATE SET
            status='open',reason=excluded.reason,due_at=excluded.due_at,
            resolution='',resolved_at=NULL""",
        (attachment['id'], source_type, str(source_id), reason, due_at))
    return db.execute("""SELECT id FROM evidence_quality_remediations
        WHERE attachment_id=? AND business_type=? AND business_id=?""",
        (attachment['id'], source_type, str(source_id))).fetchone()


def migrate_attachment_evidence_qualification():
    """Append one conservative assessment for historical rows; never infer from upload time."""
    with get_db() as db:
        if not (_table_exists(db, 'operation_attachments')
                and _table_has_column(db, 'operation_attachments', 'evidence_qualification')):
            return {'evaluated': 0, 'remediations': 0}
        rows = db.execute("""SELECT * FROM operation_attachments
            WHERE COALESCE(is_deleted,0)=0 AND evidence_evaluation_id IS NULL""").fetchall()
        evaluated = 0
        remediations = 0
        for raw in rows:
            attachment = dict(raw)
            assessment = _historical_attachment_assessment(db, attachment)
            _record_attachment_evaluation(db, attachment['id'], assessment,
                                          evaluation_type='historical_scan')
            evaluated += 1
            # Historical qualification remains an internal, append-only assessment.
            # It must not create a user-facing remediation queue or reopen closed work.
        db.commit()
        return {'evaluated': evaluated, 'remediations': remediations}


def _evidence_gate(db, source_type, source_id, required=1, stored_paths=None):
    required = max(0, int(required or 0))
    qualified = _qualified_evidence_count(db, source_type, source_id, stored_paths)
    if qualified >= required:
        return None
    return {
        'error': f'有效现场证据不足：要求 {required} 张，当前 {qualified} 张',
        'code': 'QUALIFIED_EVIDENCE_REQUIRED',
        'required': required,
        'qualified': qualified,
        'next_action': '请补传具备可信拍摄时间、有效作业窗口和站点位置的原图，或由管理员核录原图依据',
    }


def _inspection_plan_evidence_gate(db, plan_id):
    """Apply the same server-owned evidence rule before a plan can close."""
    rows = db.execute("""SELECT id,item_name,COALESCE(required_photos,0) AS required_photos
        FROM insp_plan_items WHERE plan_id=? AND COALESCE(execution_status,'active')='active'""",
        (plan_id,)).fetchall()
    failures = []
    for item in rows:
        gate = _evidence_gate(db, 'inspection', item['id'], item['required_photos'])
        if gate:
            failures.append({
                'item_id': item['id'], 'item_name': item['item_name'],
                'required': gate['required'], 'qualified': gate['qualified'],
            })
    if not failures:
        return None
    return {
        'error': f'仍有 {len(failures)} 个检查项的有效现场证据不足，无法完成计划',
        'code': 'PLAN_QUALIFIED_EVIDENCE_REQUIRED',
        'items': failures,
        'next_action': '请补传具备可信拍摄时间、有效作业窗口和站点位置的原图，或由管理员核录原图依据',
    }


def _watermark_consistency_reasons(taken_at, gps_lat, gps_lng, fields):
    reasons = []
    photo_time = _parse_dt(taken_at)
    watermark_time = _parse_dt(fields.get('taken_at'))
    if photo_time and watermark_time and abs((photo_time - watermark_time).total_seconds()) > EVIDENCE_TIME_TOLERANCE_S:
        reasons.append('水印时间与原图拍摄时间不一致')
    if all(value is not None for value in (
            gps_lat, gps_lng, fields.get('gps_lat'), fields.get('gps_lng'))):
        distance = _haversine(gps_lat, gps_lng, fields['gps_lat'], fields['gps_lng'])
        if distance is None:
            reasons.append('水印位置或原图位置无效')
        elif distance > GPS_DEVIATION_M:
            reasons.append(f'水印位置与原图位置偏差{distance:.0f}米')
    return reasons


def _attachment_storage_path(value):
    """Normalize the absolute URL used by the mini program back to the stored upload path."""
    from urllib.parse import urlparse
    raw = str(value or '')
    parsed = urlparse(raw)
    return parsed.path if parsed.scheme and parsed.netloc else raw


def _inspection_submission_attachments(db, item, uploader_id, photo_urls):
    """Resolve every submitted URL to one qualified attachment without writing."""
    required_columns = ('source_type', 'source_id', 'extra_json', 'recognized_category', 'category')
    if not all(_table_has_column(db, 'operation_attachments', column) for column in required_columns):
        return None, '当前附件结构无法安全核对，请联系管理员'
    resolved = []
    seen_ids = set()
    for value in photo_urls:
        stored_path = _attachment_storage_path(value)
        if not stored_path:
            return None, '照片地址无效，请重新上传'
        rows = db.execute("""SELECT * FROM operation_attachments
            WHERE stored_path=? AND site_id=? AND uploader_id=? AND is_deleted=0
              AND COALESCE(evidence_qualification,'review')='qualified'
              AND review_status NOT IN ('rejected','voided','superseded')
              AND ((source_type='site_photo' AND COALESCE(source_id,0)=0
                    AND json_extract(CASE WHEN json_valid(extra_json) THEN extra_json ELSE '{}' END,
                                     '$.material_role')='pending_inspection'
                    AND CAST(json_extract(extra_json,'$.plan_id') AS INTEGER)=?
                    AND CAST(json_extract(extra_json,'$.item_id') AS INTEGER)=?)
                   OR (source_type='inspection' AND source_id=?))
            ORDER BY id""",
            (stored_path, item['site_id'], uploader_id, item['plan_id'], item['id'], item['id'])).fetchall()
        if len(rows) != 1 or rows[0]['id'] in seen_ids:
            return None, '照片与当前检查项不匹配，请重新上传后再提交'
        seen_ids.add(rows[0]['id'])
        resolved.append(rows[0])
    return resolved, None


def _bind_inspection_attachments(db, item, uploader_id, photo_urls, resolved_rows=None):
    """Promote already-validated temporary photos to evidence owned by one item."""
    rows = resolved_rows
    if rows is None:
        rows, error = _inspection_submission_attachments(db, item, uploader_id, photo_urls)
        if error:
            return False
    item_name = item['item_name'] or f'检查项#{item["id"]}'
    category = item['category'] if 'category' in item.keys() else ''
    for row in rows:
        try:
            extra = json.loads(row['extra_json'] or '{}')
        except (TypeError, json.JSONDecodeError):
            extra = {}
        extra.update({
            'plan_id': item['plan_id'], 'item_id': item['id'], 'item_name': item_name,
            'classification_source': 'inspection_item', 'material_role': 'formal',
        })
        db.execute("""UPDATE operation_attachments SET source_type='inspection', source_id=?,
                   description=?, category=?, recognized_category=?, extra_json=?,
                   review_required=1, review_status='pending' WHERE id=?""",
                   (item['id'], item_name, category or '巡检现场照片', item_name,
                    json.dumps(extra, ensure_ascii=False), row['id']))
        _persist_inspection_attachment_link(db, row['id'], item)
    return True

def _haversine(lat1, lng1, lat2, lng2):
    """两点球面距离（米）"""
    first = _parse_gps_pair(lat1, lng1)
    second = _parse_gps_pair(lat2, lng2)
    if first is None or second is None:
        return None
    lat1, lng1 = first
    lat2, lng2 = second
    dlat = math.radians(lat2 - lat1)
    dlng = math.radians(lng2 - lng1)
    a = math.sin(dlat / 2) ** 2 + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(dlng / 2) ** 2
    a = min(1.0, max(0.0, a))
    return 6371000 * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))


def _parse_dt(value):
    """宽松解析日期时间字符串为 datetime；失败返回 None"""
    if not value:
        return None
    s = str(value).strip().replace('T', ' ').replace('Z', '')
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%d'):
        try:
            return datetime.strptime(s[:19] if (':' in s) else s[:10], fmt)
        except ValueError:
            continue
    return None


def _attachment_ref_date(db, att):
    """返回照片关联任务的参考日期（用于"早于任务N天"判定）；无关联返回 None。
    注意：工单照片的拍摄时间本就晚于工单创建，不以工单日期为参考，避免误标红。"""
    st = att.get('source_type')
    sid = att.get('source_id')
    if not sid:
        return None
    if st in ('inspection', 'insp', 'insp_item', 'insp_plan_item') and sid:
        r = db.execute('SELECT plan_id FROM insp_plan_items WHERE id=?', (sid,)).fetchone()
        if r and r['plan_id']:
            p = db.execute('SELECT start_date, plan_date FROM insp_plans WHERE id=?', (r['plan_id'],)).fetchone()
            if p:
                for k in ('start_date', 'plan_date'):
                    d = _parse_dt(p[k])
                    if d:
                        return d
    return None


def _evaluate_attachment_flag(db, att):
    """纯函数：根据 GPS 偏离 / 时间异常 / 关联异常项 判定照片是否需人工标红。
    返回 {'is_flagged':0/1, 'flag_reason':str, 'flag_rule':str}。
    设计目标：正常照片不标红→可一键通过；仅系统判定可疑的照片进入人工复核。"""
    reasons = []
    rule = ''
    # 1) GPS 偏离站点
    try:
        alat = float(att['gps_lat']) if att.get('gps_lat') is not None else None
        alng = float(att['gps_lng']) if att.get('gps_lng') is not None else None
    except (TypeError, ValueError):
        alat = alng = None
    site = None
    if att.get('site_id'):
        site = db.execute('SELECT gps_lat, gps_lng FROM sites WHERE id=?', (att['site_id'],)).fetchone()
    if alat is not None and alng is not None and site and site['gps_lat'] is not None:
        d = _haversine(alat, alng, float(site['gps_lat']), float(site['gps_lng']))
        if d is None:
            reasons.append('GPS坐标无效')
            rule = 'gps'
        elif d > GPS_DEVIATION_M:
            reasons.append(f'GPS偏离站点{d:.0f}米')
            rule = 'gps'
    # 2) 时间异常：未来 或 与任务参考日期偏差超阈值
    ta = att.get('taken_at')
    t = _parse_dt(ta)
    if ta:
        t = _parse_dt(ta)
        if t:
            now = datetime.now()
            if t > now + timedelta(seconds=FUTURE_SKEW_S):
                reasons.append('拍摄时间在未来')
                rule = rule or 'time'
            else:
                ref = _attachment_ref_date(db, att)
                if ref:
                    if t < ref - timedelta(days=STALE_REF_DAYS) or t > ref + timedelta(days=STALE_REF_DAYS):
                        reasons.append('拍摄时间与任务日期偏差超3天')
                        rule = rule or 'time'
    if (alat is None or alng is None or t is None) and att.get('capture_source') != 'watermark_album':
        reasons.append('\u7f3a\u5c11\u73b0\u573a\u62cd\u6444GPS\u6216\u65f6\u95f4\u4fe1\u606f')
        rule = rule or 'metadata_missing'
    # 3) 关联巡检项标记为异常
    if att.get('source_type') in ('inspection', 'insp', 'insp_item', 'insp_plan_item') and att.get('source_id'):
        it = db.execute('SELECT result FROM insp_plan_items WHERE id=?', (att['source_id'],)).fetchone()
        if it and (it['result'] or '').lower() == 'abnormal':
            reasons.append('关联巡检项标记为异常')
            rule = rule or 'abnormal'
    if reasons:
        return {'is_flagged': 1, 'flag_reason': '；'.join(reasons), 'flag_rule': rule}
    return {'is_flagged': 0, 'flag_reason': '', 'flag_rule': ''}


def _flag_attachment(db, att_id, site_id, source_type, source_id, gps_lat, gps_lng, taken_at,
                     commit=True, capture_source=''):
    """上传后即时计算并落库标红字段（自带提交兜底）"""
    try:
        fl = _evaluate_attachment_flag(db, {
            'site_id': site_id, 'source_type': source_type, 'source_id': source_id,
            'gps_lat': gps_lat, 'gps_lng': gps_lng, 'taken_at': taken_at,
            'capture_source': capture_source,
        })
        db.execute(
            'UPDATE operation_attachments SET is_flagged=?, flag_reason=?, flag_rule=? WHERE id=?',
            (fl['is_flagged'], fl['flag_reason'], fl['flag_rule'], att_id))
        if commit:
            db.commit()
    except Exception:
        if commit:
            try:
                db.rollback()
            except Exception:
                pass


@app.route('/api/audit/stats')
def audit_stats():
    """待审核统计：按计划/站点审核单元统计巡检，其余按业务单据统计。"""
    g_ = require_reviewer()
    if g_:
        return g_
    total = 0
    insp_pending = 0
    wo_pending = 0
    parts_pending = 0
    vehicle_pending = 0
    plan_pending = 0
    with get_db() as db:
        allowed = _filter_site_ids()

        def scoped_count(table_name, condition):
            params = []
            site_clause = ''
            if allowed is not None:
                if not allowed:
                    return 0
                site_clause = f" AND site_id IN ({','.join('?' for _ in allowed)})"
                params.extend(allowed)
            return db.execute(
                f"SELECT COUNT(*) as c FROM {table_name} WHERE {condition}{site_clause}",
                params,
            ).fetchone()['c']

        if allowed is None:
            insp_pending = db.execute("""SELECT COUNT(*) AS c FROM (
                SELECT i.plan_id, i.site_id FROM insp_plan_items i WHERE i.review_status=1
                  AND COALESCE(i.execution_status,'active')='active'
                  AND NOT EXISTS (
                        SELECT 1 FROM insp_plan_items unfinished
                        WHERE unfinished.plan_id=i.plan_id AND unfinished.site_id=i.site_id
                          AND COALESCE(unfinished.execution_status,'active')='active'
                          AND unfinished.result IS NULL
                  )
                GROUP BY i.plan_id, i.site_id
            )""").fetchone()['c']
        elif allowed:
            ph = ','.join('?' for _ in allowed)
            insp_pending = db.execute(f"""SELECT COUNT(*) AS c FROM (
                SELECT i.plan_id, i.site_id FROM insp_plan_items i
                WHERE i.review_status=1 AND COALESCE(i.execution_status,'active')='active'
                  AND i.site_id IN ({ph})
                  AND NOT EXISTS (
                        SELECT 1 FROM insp_plan_items unfinished
                        WHERE unfinished.plan_id=i.plan_id AND unfinished.site_id=i.site_id
                          AND COALESCE(unfinished.execution_status,'active')='active'
                          AND unfinished.result IS NULL
                  )
                GROUP BY i.plan_id, i.site_id
            )""", list(allowed)).fetchone()['c']
        else:
            insp_pending = 0
        # 工单待审数按待办结工单计数，一张工单只出现一次。
        wo_pending = scoped_count('work_orders', "status='reviewing'")
        # 审核员只处理材料与影像；资源审批属于管理者决策，不能作为审核员待办。
        if _has_any_role(g.current_user, 'admin'):
            if _table_exists(db, 'plan_schedules'):
                plan_pending = db.execute("SELECT COUNT(*) as c FROM plan_schedules WHERE status IN ('submitted','change_submitted')").fetchone()['c']
            parts_pending = db.execute("SELECT COUNT(*) as c FROM parts_requests WHERE status='pending'").fetchone()['c']
            if _table_exists(db, 'spare_part_requests'):
                parts_pending += db.execute(
                    "SELECT COUNT(*) as c FROM spare_part_requests WHERE status='pending'"
                ).fetchone()['c']
            vehicle_pending = db.execute("SELECT COUNT(*) as c FROM vehicle_applications WHERE status='pending'").fetchone()['c']
        photo_scope_sql = ''
        photo_scope_params = []
        if allowed is not None:
            if allowed:
                photo_scope_sql = f" AND a.site_id IN ({','.join('?' for _ in allowed)})"
                photo_scope_params = list(allowed)
            else:
                photo_scope_sql = ' AND 1=0'
        has_attachment_source = (_table_has_column(db, 'operation_attachments', 'source_type')
                                 and _table_has_column(db, 'operation_attachments', 'source_id'))
        photo_join_sql = ("""JOIN insp_plan_items i ON a.source_type='inspection'
                AND a.source_id=i.id AND i.site_id=a.site_id""" if has_attachment_source else '')
        reviewable_photo_sql = " AND i.review_status=1" if has_attachment_source else " AND 1=0"
        # Inspection photos are reviewed inside the inspection item batch and must not
        # create a second tab count. This field remains for old clients as an inert zero.
        photo_pending = 0
        photo_flagged = 0
        total = plan_pending + insp_pending + wo_pending + parts_pending + vehicle_pending + photo_pending
    return jsonify({
        'total': total,
        'inspection_pending': insp_pending,
        'plan_pending': plan_pending,
        'workorder_pending': wo_pending,
        'parts_pending': parts_pending,
        'vehicle_pending': vehicle_pending,
        'photo_pending': photo_pending,
        'photo_flagged': photo_flagged,
    })

