@app.route('/api/auth/change-password', methods=['POST'])
@login_required
def api_change_password():
    data = request.get_json(silent=True) or {}
    current_password = data.get('current_password') or ''
    new_password = data.get('new_password') or ''
    if not current_password:
        return jsonify({'error': '请输入当前密码'}), 400
    if len(new_password) < 8:
        return jsonify({'error': '新密码至少8位'}), 400
    if current_password == new_password:
        return jsonify({'error': '新密码不能与当前密码相同'}), 400
    with get_db() as db:
        user_row = db.execute("SELECT * FROM users WHERE id=?", (g.current_user['id'],)).fetchone()
        if not user_row or user_row['password_hash'] != _hash_pw(current_password):
            return jsonify({'error': '当前密码不正确'}), 400
        db.execute(
            "UPDATE users SET password_hash=?, must_change_password=0 WHERE id=?",
            (_hash_pw(new_password), g.current_user['id']),
        )
        _revoke_user_sessions(db, g.current_user['id'], 'password_changed', increment_auth_version=True)
        refreshed_row = db.execute("SELECT * FROM users WHERE id=?", (g.current_user['id'],)).fetchone()
        token, session_user = _issue_session(db, refreshed_row)
        db.commit()
    return jsonify({'success': True, 'token': token, 'user': session_user})


# ===================== 用户管理API（管理员） =====================

USER_ROLES = {'admin', 'operator', 'reviewer'}


def _normalize_user_roles(raw_roles, fallback='operator'):
    """Normalize the only three supported roles, keeping legacy values readable."""
    if not isinstance(raw_roles, (list, tuple, set)):
        raw_roles = [raw_roles] if raw_roles else []
    aliases = {'manager': 'admin', 'inspector': 'reviewer'}
    roles = {aliases.get(str(role).strip(), str(role).strip()) for role in raw_roles}
    roles &= USER_ROLES
    if not roles:
        roles = {aliases.get(fallback, fallback)} & USER_ROLES or {'operator'}
    return sorted(roles)


def _primary_role(roles):
    roles = set(roles)
    if 'admin' in roles:
        return 'admin'
    if 'operator' in roles:
        return 'operator'
    return 'reviewer'


def _roles_for_user(db, uid, fallback='operator'):
    rows = db.execute('SELECT role FROM user_roles WHERE user_id=?', (uid,)).fetchall()
    return _normalize_user_roles([row['role'] for row in rows], fallback)


def _has_any_role(user, *required_roles):
    if not user:
        return False
    roles = _normalize_user_roles(user.get('roles') or [user.get('role')])
    return bool(set(roles) & set(required_roles))


def _clear_user_site_cache(uid):
    for token, user in list(_tokens.items()):
        if user.get('id') == uid:
            _site_ids_cache.pop(token, None)


def _user_pending_work(db, uid, real_name):
    schedule_where = "user_id=? AND status IN ('draft','submitted','approved','change_submitted','modifying')"
    if _table_has_column(db, 'plan_schedules', 'field_status'):
        schedule_where += " AND COALESCE(field_status, 'active')!='completed'"
    checks = [
        ('巡检计划', 'insp_plans', "assignee_id=? AND status NOT IN ('completed','rejected','cancelled')", (uid,)),
        ('巡检排程', 'plan_schedules', schedule_where, (uid,)),
        ('开放工单', 'work_orders', "assignee=? AND status NOT IN ('closed','resolved')", (real_name,)),
        ('用车申请', 'vehicle_applications', "applicant_id=? AND status NOT IN ('returned','cancelled','rejected')", (uid,)),
    ]
    pending = {}
    for label, table, where, params in checks:
        if not _table_exists(db, table):
            continue
        try:
            count = db.execute(f'SELECT COUNT(*) FROM {table} WHERE {where}', params).fetchone()[0]
        except sqlite3.OperationalError:
            # 兼容升级中的旧库和只包含部分字段的专项测试库。
            continue
        if count:
            pending[label] = count
    return pending


@app.route('/api/users')
@login_required
def api_users():
    if not _has_any_role(g.current_user, 'admin'):
        return jsonify({'error': '无权限'}), 403
    search, role, status = (request.args.get('search') or '').strip(), (request.args.get('role') or '').strip(), (request.args.get('status') or '').strip()
    with get_db() as db:
        if 'deleted_at' not in {row['name'] for row in db.execute('PRAGMA table_info(users)').fetchall()}:
            db.execute('ALTER TABLE users ADD COLUMN deleted_at TEXT')
        sql = '''SELECT u.id, u.username, u.login_name, u.role, u.real_name, u.phone, u.status, u.deleted_at, u.created_at,
                        CASE WHEN TRIM(COALESCE(u.openid,''))<>'' THEN 1 ELSE 0 END AS wechat_bound,
                        GROUP_CONCAT(DISTINCT s.name) AS site_names, GROUP_CONCAT(DISTINCT s.id) AS site_ids,
                        GROUP_CONCAT(DISTINCT ur.role) AS roles
                 FROM users u LEFT JOIN user_sites us ON us.user_id=u.id LEFT JOIN sites s ON s.id=us.site_id WHERE 1=1'''
        sql = sql.replace('FROM users u LEFT', 'FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT')
        params = []
        if search:
            like = '%' + search + '%'; sql += ' AND (u.username LIKE ? OR u.login_name LIKE ? OR u.real_name LIKE ? OR u.phone LIKE ?)'; params += [like, like, like, like]
        if role in USER_ROLES:
            sql += ' AND EXISTS (SELECT 1 FROM user_roles fur WHERE fur.user_id=u.id AND fur.role=?)'; params.append(role)
        if status in ('active', 'inactive'): sql += ' AND u.status=?'; params.append(status)
        sql += ' GROUP BY u.id ORDER BY u.id'
        rows = db.execute(sql, params).fetchall()
    users = [{**dict(r), 'roles': _normalize_user_roles((r['roles'] or '').split(','), r['role']),
              'site_ids': [int(x) for x in (r['site_ids'] or '').split(',') if x],
              'sites': [x for x in (r['site_names'] or '').split(',') if x]} for r in rows]
    return jsonify(users)


@app.route('/api/users/<int:uid>/wechat-binding', methods=['DELETE'])
@login_required
def api_unbind_user_wechat(uid):
    """管理员显式解除一个业务账号的微信绑定，不删除任何业务或消息历史。"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    reason = str(data.get('reason') or '').strip()
    if not reason:
        return jsonify({'error': '请填写解除微信绑定原因'}), 400
    if len(reason) > 500:
        return jsonify({'error': '解除微信绑定原因不能超过500字'}), 400
    try:
        with get_db() as db:
            db.execute('BEGIN IMMEDIATE')
            if not _table_exists(db, 'operation_logs'):
                db.rollback()
                return jsonify({'error': '解绑审计暂不可用，请稍后重试'}), 503
            has_auth_version = _table_has_column(db, 'users', 'auth_version')
            user = db.execute(
                'SELECT id,real_name,openid,auth_version FROM users WHERE id=?' if has_auth_version
                else 'SELECT id,real_name,openid,1 AS auth_version FROM users WHERE id=?',
                (uid,)).fetchone()
            if not user:
                db.rollback()
                return jsonify({'error': '用户不存在'}), 404
            bound_openid = str(user['openid'] or '').strip()
            if not bound_openid:
                db.rollback()
                return jsonify({'error': '该用户尚未绑定微信', 'code': 'WECHAT_NOT_BOUND'}), 409
            changed = db.execute("""UPDATE users SET openid='' WHERE id=? AND openid=?""",
                                 (uid, bound_openid))
            if changed.rowcount != 1:
                db.rollback()
                return jsonify({'error': '微信绑定状态已变化，请刷新后重试',
                                'code': 'WECHAT_BINDING_STALE'}), 409
            _revoke_user_sessions(db, uid, 'wechat_binding_removed', increment_auth_version=True)
            db.execute("""INSERT INTO operation_logs
                (module,action,target_type,target_id,operator,operator_id,details)
                VALUES ('user','wechat_binding_removed','user',?,?,?,?)""",
                (uid, _current_actor_name(), g.current_user.get('id') or 0,
                 json.dumps({'reason': reason, 'wechat_bound': False}, ensure_ascii=False)))
            db.commit()
        _clear_user_site_cache(uid)
        return jsonify({
            'success': True,
            'id': uid,
            'wechat_bound': False,
            'current_session_revoked': uid == g.current_user.get('id'),
        })
    except sqlite3.DatabaseError:
        return jsonify({'error': '解除微信绑定暂未完成，请稍后重试'}), 503


@app.route('/api/users', methods=['POST'])
@login_required
def api_users_create():
    denied = require_admin()
    if denied: return denied
    data = request.get_json(silent=True) or {}
    login_name = (data.get('login_name') or data.get('username') or '').strip()
    username, password, real_name = (data.get('username') or f'user_{uuid.uuid4().hex[:12]}').strip(), data.get('password') or '', (data.get('real_name') or '').strip()
    roles = _normalize_user_roles(data.get('roles') or data.get('role'), data.get('role') or 'operator')
    if not username or len(login_name) < 1 or len(password) < 6 or not real_name:
        return jsonify({'error': '请填写中文登录名、至少6位初始密码和姓名'}), 400
    site_ids = data.get('site_ids') or []
    if not isinstance(site_ids, list): return jsonify({'error': '站点授权格式错误'}), 400
    with get_db() as db:
        try:
            cur = db.execute('''INSERT INTO users
                (username,login_name,password_hash,role,real_name,phone,status,must_change_password)
                VALUES (?,?,?,?,?,?,?,1)''',
                (username, login_name, _hash_pw(password), _primary_role(roles), real_name,
                 (data.get('phone') or '').strip(), data.get('status', 'active')))
        except sqlite3.IntegrityError:
            return jsonify({'error': '用户名已存在'}), 409
        uid = cur.lastrowid
        for user_role in roles:
            db.execute('INSERT INTO user_roles (user_id,role) VALUES (?,?)', (uid, user_role))
        for sid in set(site_ids):
            if db.execute('SELECT 1 FROM sites WHERE id=?', (sid,)).fetchone(): db.execute('INSERT OR IGNORE INTO user_sites (user_id,site_id) VALUES (?,?)', (uid, sid))
        db.commit()
    return jsonify({'success': True, 'id': uid, 'must_change_password': True}), 201


@app.route('/api/users/<int:uid>', methods=['PUT', 'DELETE'])
@login_required
def api_user_detail(uid):
    denied = require_admin()
    if denied: return denied
    if uid == g.current_user['id'] and request.method == 'DELETE': return jsonify({'error': '不能注销当前登录账号'}), 409
    with get_db() as db:
        if 'deleted_at' not in {row['name'] for row in db.execute('PRAGMA table_info(users)').fetchall()}:
            db.execute('ALTER TABLE users ADD COLUMN deleted_at TEXT')
        user = db.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
        if not user: return jsonify({'error': '用户不存在'}), 404
        if request.method == 'DELETE':
            pending = _user_pending_work(db, uid, user['real_name'])
            if pending:
                summary = '、'.join(f'{name}{count}项' for name, count in pending.items())
                return jsonify({
                    'error': f'该账号仍有未结束的{summary}，请先转交、归档或取消后再注销',
                    'pending_work': pending,
                }), 409
            # Soft cancellation preserves the user, roles, site history and WeChat binding.
            _revoke_user_sessions(db, uid, 'account_deleted', increment_auth_version=True)
            db.execute("UPDATE users SET status='inactive', deleted_at=datetime('now','localtime') WHERE id=?", (uid,))
            db.commit()
            _clear_user_site_cache(uid)
            return jsonify({'success': True, 'deleted': False, 'soft_deleted': True})
        data = request.get_json(silent=True) or {}
        roles = _normalize_user_roles(data.get('roles') or data.get('role'), user['role'])
        real_name = (data.get('real_name') if 'real_name' in data else user['real_name']) or ''
        if not real_name.strip(): return jsonify({'error': '姓名不能为空'}), 400
        login_name = (data.get('login_name') if 'login_name' in data else user['login_name']) or real_name.strip()
        if not login_name.strip():
            return jsonify({'error': '中文登录名不能为空'}), 400
        try:
            db.execute('UPDATE users SET login_name=?, real_name=?, role=?, phone=?, status=? WHERE id=?',
                       (login_name.strip(), real_name.strip(), _primary_role(roles), (data.get('phone') if 'phone' in data else user['phone']) or '', data.get('status', user['status']), uid))
        except sqlite3.IntegrityError:
            return jsonify({'error': '中文登录名已存在'}), 409
        db.execute('DELETE FROM user_roles WHERE user_id=?', (uid,))
        for user_role in roles:
            db.execute('INSERT INTO user_roles (user_id,role) VALUES (?,?)', (uid, user_role))
        if 'site_ids' in data:
            if not isinstance(data['site_ids'], list): return jsonify({'error': '站点授权格式错误'}), 400
            db.execute('DELETE FROM user_sites WHERE user_id=?', (uid,))
            for sid in set(data['site_ids']):
                if db.execute('SELECT 1 FROM sites WHERE id=?', (sid,)).fetchone(): db.execute('INSERT OR IGNORE INTO user_sites (user_id,site_id) VALUES (?,?)', (uid, sid))
        _revoke_user_sessions(db, uid, 'account_permissions_changed', increment_auth_version=True)
        db.commit()
    _clear_user_site_cache(uid)
    return jsonify({'success': True})

