@app.route('/api/users/<int:uid>/transfer-work', methods=['POST'])
@login_required
def api_user_transfer_work(uid):
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    target_id = data.get('target_user_id')
    try:
        target_id = int(target_id)
    except (TypeError, ValueError):
        return jsonify({'error': '请选择接收人员'}), 400
    if target_id == uid:
        return jsonify({'error': '接收人员不能是本人'}), 400
    with get_db() as db:
        source = db.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
        target = db.execute("""SELECT DISTINCT u.* FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id
            WHERE u.id=? AND u.status='active' AND (u.role='operator' OR ur.role='operator')""", (target_id,)).fetchone()
        if not source or not target:
            return jsonify({'error': '原人员不存在，或接收人员不是在岗运维人员'}), 400
        pending = _user_pending_work(db, uid, source['real_name'])
        if pending.get('用车申请'):
            return jsonify({'error': '该人员仍有未结束的用车申请；个人用车记录不能转交，请先归还或取消'}), 409
        counts = {'巡检计划': 0, '巡检排程': 0, '开放工单': 0}
        if _table_exists(db, 'insp_plans'):
            cursor = db.execute("""UPDATE insp_plans SET assignee_id=?, assignee=?
                WHERE assignee_id=? AND status NOT IN ('completed','rejected','cancelled')""",
                (target_id, target['real_name'], uid))
            counts['巡检计划'] = cursor.rowcount
        if _table_exists(db, 'plan_schedules'):
            cursor = db.execute("""UPDATE plan_schedules SET user_id=? WHERE user_id=?
                AND status IN ('draft','submitted','approved','change_submitted','modifying')""", (target_id, uid))
            counts['巡检排程'] = cursor.rowcount
        if _table_exists(db, 'work_orders'):
            cursor = db.execute("""UPDATE work_orders SET assignee=? WHERE assignee=?
                AND status NOT IN ('closed','resolved')""", (target['real_name'], source['real_name']))
            counts['开放工单'] = cursor.rowcount
        if _table_exists(db, 'user_sites'):
            db.execute("""INSERT OR IGNORE INTO user_sites (user_id, site_id)
                SELECT ?, site_id FROM user_sites WHERE user_id=?""", (target_id, uid))
        if _table_exists(db, 'operation_logs'):
            db.execute("""INSERT INTO operation_logs
                (module, action, target_type, target_id, operator, operator_id, details)
                VALUES ('user', 'transfer_work', 'user', ?, ?, ?, ?)""",
                (uid, g.current_user.get('real_name') or '', g.current_user.get('id') or 0,
                 f'将「{source["real_name"]}」未完成工作转交给「{target["real_name"]}」：{json.dumps(counts, ensure_ascii=False)}'))
        if _table_exists(db, 'notifications'):
            summary = '、'.join(f'{name}{count}项' for name, count in counts.items() if count) or '站点权限'
            _create_notification(
                target_id, 'user_work_transfer', uid, '收到未完成工作转交',
                f'管理员已将「{source["real_name"]}」的{summary}转交给你，请在今日任务、计划调度和工单中逐项确认。', db=db,
            )
        db.commit()
    _clear_user_site_cache(uid)
    _clear_user_site_cache(target_id)
    return jsonify({'success': True, 'transferred': counts, 'target_name': target['real_name']})


# ===================== 设备管理 API =====================

_IMPORT_DEVICE_TYPES = {
    'multi_param_analyzer', 'ph_meter', 'do_sensor', 'turbidity_meter',
    'ammonia_analyzer', 'codmn_analyzer', 'tp_analyzer', 'tn_analyzer',
    'conductivity_meter', 'submersible_pump', 'sample_float', 'dtu',
    'fire_extinguisher', 'lighting',
}
_IMPORT_DEVICE_TYPE_CN = {
    '多参数分析仪': 'multi_param_analyzer', 'pH计': 'ph_meter', 'pH 计': 'ph_meter',
    '溶解氧传感器': 'do_sensor', '浊度仪': 'turbidity_meter', '氨氮分析仪': 'ammonia_analyzer',
    '高锰酸盐指数分析仪': 'codmn_analyzer', '总磷分析仪': 'tp_analyzer', '总氮分析仪': 'tn_analyzer',
    '电导率仪': 'conductivity_meter', '潜水泵': 'submersible_pump', '采样浮标': 'sample_float',
    '数据传输终端': 'dtu', '灭火器': 'fire_extinguisher', '照明设备': 'lighting',
}
_IMPORT_DEVICE_STATUS_CN = {'正常': 'normal', '离线': 'offline', '故障': 'fault', '维护中': 'maintenance'}


def _import_text(value):
    """Normalize Excel cell input without converting identifiers to numbers."""
    if value is None:
        return ''
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d')
    return str(value).strip()


def _import_number(value, field, integer=False):
    try:
        number = int(value) if integer else float(value)
    except (TypeError, ValueError):
        raise ValueError(f'{field}必须是有效数字')
    if number < 0:
        raise ValueError(f'{field}不能小于0')
    return number


def _import_excel_rows(kind):
    file = request.files.get('file')
    if not file or not file.filename:
        return None, ('请选择要导入的 Excel 文件', 400)
    if not file.filename.lower().endswith(('.xlsx', '.xlsm')):
        return None, ('仅支持 .xlsx 格式的文件', 400)
    if not _HAS_OPENPYXL:
        return None, ('缺少 openpyxl，无法读取 Excel 文件', 500)
    try:
        workbook = load_workbook(file, read_only=True, data_only=True)
        sheet = workbook.active
        raw = list(sheet.iter_rows(values_only=True))
    except Exception as exc:
        return None, (f'Excel 文件无法读取：{exc}', 400)
    if not raw:
        return None, ('Excel 文件为空', 400)
    headers = [_import_text(cell) for cell in raw[0]]
    expected = (['站点编码', '设备编码', '设备名称', '设备类型'] if kind == 'devices'
                else ['备件编码', '备件名称', '单位', '初始库存'])
    missing = [name for name in expected if name not in headers]
    if missing:
        return None, (f'缺少必填列：{ "、".join(missing) }。请使用系统下载的模板。', 400)
    return [(index + 2, dict(zip(headers, row))) for index, row in enumerate(raw[1:])
            if any(_import_text(cell) for cell in row)], None


def _validate_import_rows(kind, source_rows, db):
    """Return client-readable preview rows. Database writes happen only at commit."""
    site_by_code = {str(r['code']).strip(): r['id'] for r in db.execute('SELECT id, code FROM sites').fetchall()}
    existing_table, code_column = ('device_shadows', 'device_code') if kind == 'devices' else ('spare_parts_inventory', 'part_code')
    existing_codes = {str(r[0]).strip() for r in db.execute(f'SELECT {code_column} FROM {existing_table}').fetchall()}
    seen = set()
    result = []
    for row_no, raw in source_rows:
        errors = []
        warnings = []
        try:
            if kind == 'devices':
                site_code = _import_text(raw.get('站点编码'))
                code = _import_text(raw.get('设备编码'))
                name = _import_text(raw.get('设备名称'))
                device_type_raw = _import_text(raw.get('设备类型'))
                device_type = _IMPORT_DEVICE_TYPE_CN.get(device_type_raw, device_type_raw)
                normalized = {
                    'site_code': site_code, 'site_id': site_by_code.get(site_code),
                    'device_code': code, 'device_name': name, 'device_type': device_type,
                    'device_model': _import_text(raw.get('设备型号')),
                    'manufacturer': _import_text(raw.get('厂商')),
                    'install_date': _import_text(raw.get('安装日期')),
                    'status': _IMPORT_DEVICE_STATUS_CN.get(
                        _import_text(raw.get('状态')), _import_text(raw.get('状态'))) or 'normal',
                    'remark': _import_text(raw.get('备注')),
                }
                if not site_code or normalized['site_id'] is None:
                    errors.append('站点编码不存在')
                if not code:
                    errors.append('设备编码不能为空')
                if not name:
                    errors.append('设备名称不能为空')
                if not device_type:
                    errors.append('设备类型不能为空')
                elif device_type not in _IMPORT_DEVICE_TYPES:
                    errors.append('设备类型不在系统允许范围内')
                if normalized['install_date']:
                    try:
                        datetime.strptime(normalized['install_date'], '%Y-%m-%d')
                    except ValueError:
                        errors.append('安装日期应为 YYYY-MM-DD')
                if normalized['status'] not in ('normal', 'offline', 'fault', 'maintenance'):
                    errors.append('状态应为 normal、offline、fault 或 maintenance')
            else:
                code = _import_text(raw.get('备件编码'))
                name = _import_text(raw.get('备件名称'))
                unit = _import_text(raw.get('单位'))
                quantity = _import_number(raw.get('初始库存'), '初始库存', integer=True)
                min_quantity = _import_number(raw.get('最低库存') or 0, '最低库存', integer=True)
                normalized = {
                    'part_code': code, 'part_name': name, 'unit': unit,
                    'quantity': quantity, 'min_quantity': min_quantity,
                    'category': _import_text(raw.get('分类')) or '其他',
                    'remark': _import_text(raw.get('备注')),
                }
                if not code:
                    errors.append('备件编码不能为空')
                if not name:
                    errors.append('备件名称不能为空')
                if not unit:
                    errors.append('单位不能为空')
        except ValueError as exc:
            normalized = {}
            code = _import_text(raw.get('设备编码' if kind == 'devices' else '备件编码'))
            errors.append(str(exc))
        if code in seen and code:
            errors.append('文件内编码重复')
        seen.add(code)
        if code and code in existing_codes:
            errors.append('编码已存在于系统，批量导入不会覆盖现有记录')
        status = 'error' if errors else ('warning' if warnings else 'valid')
        result.append({
            'row_no': row_no, 'status': status, 'messages': errors + warnings,
            'data': normalized,
        })
    return result


def _import_template_response(kind):
    denied = require_admin()
    if denied:
        return denied
    if not _HAS_OPENPYXL:
        return jsonify({'error': '缺少 openpyxl，无法生成 Excel 模板'}), 500
    workbook = Workbook()
    sheet = workbook.active
    sheet.title = '设备导入' if kind == 'devices' else '备件导入'
    if kind == 'devices':
        headers = ['站点编码', '设备编码', '设备名称', '设备类型', '设备型号', '厂商', '安装日期', '状态', '备注']
        reference = workbook.create_sheet('站点参考')
        reference.append(['站点编码', '站点名称', '负责人'])
        with get_db() as db:
            for site in db.execute('SELECT code, name, manager FROM sites ORDER BY code').fetchall():
                reference.append([site['code'], site['name'], site['manager'] or ''])
        reference.freeze_panes = 'A2'
        reference.auto_filter.ref = reference.dimensions
        widths = [16, 24, 16]
        for index, width in enumerate(widths, 1):
            reference.column_dimensions[chr(64 + index)].width = width
        type_reference = workbook.create_sheet('设备类型参考')
        type_reference.append(['设备类型代码', '设备类型名称'])
        type_labels = {
            'multi_param_analyzer': '多参数分析仪', 'ph_meter': 'pH 计', 'do_sensor': '溶解氧传感器',
            'turbidity_meter': '浊度仪', 'ammonia_analyzer': '氨氮分析仪', 'codmn_analyzer': '高锰酸盐指数分析仪',
            'tp_analyzer': '总磷分析仪', 'tn_analyzer': '总氮分析仪', 'conductivity_meter': '电导率仪',
            'submersible_pump': '潜水泵', 'sample_float': '采样浮标', 'dtu': '数据传输终端',
            'fire_extinguisher': '灭火器', 'lighting': '照明设备',
        }
        for type_code in sorted(_IMPORT_DEVICE_TYPES):
            type_reference.append([type_code, type_labels[type_code]])
        type_reference.freeze_panes = 'A2'
        type_reference.auto_filter.ref = type_reference.dimensions
        type_reference.column_dimensions['A'].width = 28
        type_reference.column_dimensions['B'].width = 22
        type_validation = DataValidation(
            type='list', formula1="'设备类型参考'!$B$2:$B$%d" % type_reference.max_row,
            allow_blank=False)
        sheet.add_data_validation(type_validation)
        type_validation.add('D2:D1001')
        status_reference = workbook.create_sheet('状态参考')
        status_reference.append(['设备状态'])
        for label in _IMPORT_DEVICE_STATUS_CN:
            status_reference.append([label])
        status_validation = DataValidation(
            type='list', formula1="'状态参考'!$A$2:$A$%d" % status_reference.max_row,
            allow_blank=True)
        sheet.add_data_validation(status_validation)
        status_validation.add('H2:H1001')
        for cell in type_reference[1]:
            cell.font = Font(bold=True, color='FFFFFF')
            cell.fill = PatternFill('solid', fgColor='1677FF')
    else:
        headers = ['备件编码', '备件名称', '分类', '单位', '初始库存', '最低库存', '备注']
        reference = workbook.create_sheet('填写说明')
        reference.append(['字段', '填写要求'])
        reference.append(['备件编码', '必填；全系统唯一，导入不会覆盖同编码库存。'])
        reference.append(['初始库存', '必填；非负整数，导入后生成“批量建账入库”流水。'])
        reference.append(['最低库存', '选填；非负整数，未填默认为 0。'])
        reference.freeze_panes = 'A2'
        reference.column_dimensions['A'].width = 16
        reference.column_dimensions['B'].width = 56
    sheet.append(headers)
    sheet.freeze_panes = 'A2'
    sheet.auto_filter.ref = f'A1:{chr(64 + len(headers))}1'
    for cell in sheet[1]:
        cell.font = Font(bold=True, color='FFFFFF')
        cell.fill = PatternFill('solid', fgColor='1677FF')
        cell.alignment = Alignment(horizontal='center')
    for cell in reference[1]:
        cell.font = Font(bold=True, color='FFFFFF')
        cell.fill = PatternFill('solid', fgColor='1677FF')
    for index, header in enumerate(headers, 1):
        sheet.column_dimensions[chr(64 + index)].width = max(14, min(24, len(header) * 3 + 6))
    output = BytesIO()
    workbook.save(output)
    output.seek(0)
    filename = '设备批量导入模板.xlsx' if kind == 'devices' else '备品备件批量导入模板.xlsx'
    return send_file(output, as_attachment=True, download_name=filename,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')


@app.route('/api/import-templates/<kind>')
@login_required
def api_import_template(kind):
    if kind not in ('devices', 'parts'):
        return jsonify({'error': '不支持的模板类型'}), 404
    return _import_template_response(kind)


@app.route('/api/imports/<kind>/validate', methods=['POST'])
@login_required
def api_import_validate(kind):
    denied = require_admin()
    if denied:
        return denied
    if kind not in ('devices', 'parts'):
        return jsonify({'error': '不支持的导入类型'}), 404
    source_rows, error = _import_excel_rows(kind)
    if error:
        return jsonify({'error': error[0]}), error[1]
    if len(source_rows) > 1000:
        return jsonify({'error': '单次最多导入 1000 行'}), 400
    with get_db() as db:
        rows = _validate_import_rows(kind, source_rows, db)
    valid_count = sum(row['status'] == 'valid' for row in rows)
    return jsonify({'rows': rows, 'total': len(rows), 'valid_count': valid_count,
                    'error_count': len(rows) - valid_count})


@app.route('/api/imports/<kind>/commit', methods=['POST'])
@login_required
def api_import_commit(kind):
    denied = require_admin()
    if denied:
        return denied
    if kind not in ('devices', 'parts'):
        return jsonify({'error': '不支持的导入类型'}), 404
    supplied_rows = (request.get_json(silent=True) or {}).get('rows') or []
    if not isinstance(supplied_rows, list) or not supplied_rows:
        return jsonify({'error': '没有可导入的数据'}), 400
    source_rows = [(row.get('row_no', index + 2), row.get('data') or {}) for index, row in enumerate(supplied_rows)]
    # Convert the normalized browser payload back to the Excel-like keys for the same server-side validation.
    if kind == 'devices':
        source_rows = [(no, {'站点编码': row.get('site_code'), '设备编码': row.get('device_code'),
                             '设备名称': row.get('device_name'), '设备类型': row.get('device_type'),
                             '设备型号': row.get('device_model'), '厂商': row.get('manufacturer'),
                             '安装日期': row.get('install_date'), '状态': row.get('status'), '备注': row.get('remark')})
                       for no, row in source_rows]
    else:
        source_rows = [(no, {'备件编码': row.get('part_code'), '备件名称': row.get('part_name'),
                             '分类': row.get('category'), '单位': row.get('unit'), '初始库存': row.get('quantity'),
                             '最低库存': row.get('min_quantity'), '备注': row.get('remark')})
                       for no, row in source_rows]
    with get_db() as db:
        rows = _validate_import_rows(kind, source_rows, db)
        invalid = [row for row in rows if row['status'] != 'valid']
        if invalid:
            return jsonify({'error': '数据已变化或仍有错误，未写入任何记录', 'rows': invalid}), 409
        try:
            for row in rows:
                data = row['data']
                if kind == 'devices':
                    cur = db.execute("""INSERT INTO device_shadows
                        (device_code, device_name, device_type, site_id, device_model, manufacturer, install_date, status, management_scope, monitoring_enabled)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)""",
                        (data['device_code'], data['device_name'], data['device_type'], data['site_id'],
                         data['device_model'], data['manufacturer'], data['install_date'] or None, data['status'],
                         'managed'))
                    db.execute("""INSERT INTO operation_logs (module, action, target_type, target_id, operator, operator_id, details)
                        VALUES ('device', 'batch_import', 'device', ?, ?, ?, ?)""",
                        (cur.lastrowid, _current_actor_name(), g.current_user['id'],
                         f"批量导入设备「{data['device_name']}」({data['device_code']})"))
                else:
                    cur = db.execute("""INSERT INTO spare_parts_inventory
                        (part_code, part_name, category, unit, quantity, min_quantity, remark)
                        VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (data['part_code'], data['part_name'], data['category'], data['unit'],
                         data['quantity'], data['min_quantity'], data['remark']))
                    if data['quantity']:
                        db.execute("""INSERT INTO inventory_logs
                            (part_id, type, quantity, ref_type, operator, operator_id, remark)
                            VALUES (?, 'in', ?, 'batch_import', ?, ?, '批量建账入库')""",
                            (cur.lastrowid, data['quantity'], _current_actor_name(), g.current_user.get('id')))
            db.commit()
        except Exception as exc:
            db.rollback()
            return jsonify({'error': f'导入失败，未写入任何记录：{exc}'}), 500
    return jsonify({'success': True, 'imported_count': len(rows), 'message': f'已成功导入 {len(rows)} 条记录'})

@app.route('/api/devices/monitoring-summary')
@login_required
def api_monitoring_devices_summary():
    """Return only real telemetry devices visible to the current user."""
    allowed = _filter_site_ids()
    if allowed == []:
        return jsonify([])
    params = []
    site_clause = ''
    if allowed is not None:
        site_clause = f" AND d.site_id IN ({','.join('?' * len(allowed))})"
        params.extend(allowed)
    with get_db() as db:
        rows = db.execute(f"""SELECT d.id, d.device_code, d.device_name,
                d.device_type, d.device_model, d.status, d.last_data_time,
                d.site_id, s.code AS site_code
            FROM device_shadows d
            JOIN sites s ON s.id=d.site_id
            WHERE d.management_scope='managed'
              AND d.monitoring_enabled=1
              AND d.last_data_time IS NOT NULL
              AND TRIM(d.last_data_time)!=''{site_clause}
            ORDER BY d.site_id, d.id""", params).fetchall()
    return jsonify([dict(row) for row in rows])


@app.route('/api/devices')
@login_required
def api_devices_list():
    """设备台账列表，支持按站点/类型筛选"""
    denied = require_admin()
    if denied:
        return denied
    site_id = request.args.get('site_id', '').strip()
    device_type = request.args.get('type', '').strip()
    search = request.args.get('search', '').strip()
    with get_db() as db:
        device_columns = {row['name'] for row in db.execute('PRAGMA table_info(device_shadows)').fetchall()}
        status_field = 'd.status' if 'status' in device_columns else "'online' AS status"
        scope_field = 'd.management_scope' if 'management_scope' in device_columns else "'managed' AS management_scope"
        monitoring_field = 'd.monitoring_enabled' if 'monitoring_enabled' in device_columns else '0 AS monitoring_enabled'
        last_data_field = 'd.last_data_time' if 'last_data_time' in device_columns else 'NULL AS last_data_time'
        has_recycle = _table_exists(db, 'device_recycle')
        recycle_fields = """, dr.recycle_date, dr.destination AS recycle_destination,
                        dr.reason AS recycle_reason""" if has_recycle else """,
                        NULL AS recycle_date, NULL AS recycle_destination, NULL AS recycle_reason"""
        recycle_join = """LEFT JOIN device_recycle dr ON dr.id=(
                    SELECT dr2.id FROM device_recycle dr2
                    WHERE dr2.device_id=d.id AND dr2.status='recycled'
                    ORDER BY dr2.id DESC LIMIT 1
                 )""" if has_recycle else ''
        sql = """SELECT d.id, d.device_code, d.device_name, d.device_type, d.device_model, d.manufacturer, d.install_date,
                        {status_field}, {scope_field}, {monitoring_field},
                        {last_data_field},
                        s.name as site_name, s.code as site_code, s.id as site_id
                        {recycle_fields}
                 FROM device_shadows d LEFT JOIN sites s ON d.site_id=s.id
                 {recycle_join} WHERE 1=1""".format(
                    status_field=status_field, scope_field=scope_field,
                    monitoring_field=monitoring_field, last_data_field=last_data_field,
                    recycle_fields=recycle_fields, recycle_join=recycle_join)
        params = []
        if site_id:
            sql += " AND d.site_id=?"
            params.append(site_id)
        if device_type:
            sql += " AND d.device_type=?"
            params.append(device_type)
        if search:
            sql += " AND (d.device_name LIKE ? OR d.device_code LIKE ? OR s.name LIKE ?)"
            like = f"%{search}%"
            params.extend([like, like, like])
        sql += " ORDER BY d.id"
        rows = db.execute(sql, params).fetchall()
    return jsonify([dict(r) for r in rows])


@app.route('/api/devices/<int:device_id>')
@login_required
def api_device_detail(device_id):
    """设备详情 + 维护记录"""
    denied = require_admin()
    if denied:
        return denied
    with get_db() as db:
        dev = db.execute("""SELECT d.*, s.name as site_name, s.code as site_code,
                                   s.district, s.manager, dr.recycle_date,
                                   dr.destination AS recycle_destination, dr.reason AS recycle_reason
                            FROM device_shadows d LEFT JOIN sites s ON d.site_id=s.id
                            LEFT JOIN device_recycle dr ON dr.id=(
                                SELECT dr2.id FROM device_recycle dr2
                                WHERE dr2.device_id=d.id AND dr2.status='recycled'
                                ORDER BY dr2.id DESC LIMIT 1
                            )
                            WHERE d.id=?""", (device_id,)).fetchone()
        if not dev:
            return jsonify({'error': '设备不存在'}), 404
        logs = db.execute("""SELECT * FROM inventory_logs
                             WHERE ref_type='maintenance' AND ref_id=?
                             ORDER BY created_at DESC LIMIT 20""", (device_id,)).fetchall()
        # 增加设备操作日志（CRUD）
        op_logs = db.execute("""SELECT * FROM operation_logs
                                WHERE target_type='device' AND target_id=?
                                ORDER BY created_at DESC LIMIT 20""", (device_id,)).fetchall()
    return jsonify({'device': dict(dev),
                    'logs': [dict(l) for l in logs],
                    'operation_logs': [dict(o) for o in op_logs]})


@app.route('/api/devices', methods=['POST'])
@login_required
def api_device_create():
    """注册新设备"""
    g_ = require_admin()
    if g_:
        return g_
    data = request.get_json(force=True)
    device_code = (data.get('device_code') or '').strip()
    device_name = (data.get('device_name') or '').strip()
    device_type = (data.get('device_type') or '').strip()
    site_id = data.get('site_id')

    if not device_code or not device_name:
        return jsonify({'error': '设备编码和名称不能为空'}), 400

    with get_db() as db:
        existing = db.execute("SELECT id FROM device_shadows WHERE device_code=?", (device_code,)).fetchone()
        if existing:
            return jsonify({'error': '设备编码已存在'}), 409
        cur = db.execute(
            """INSERT INTO device_shadows
               (device_code, device_name, device_type, site_id, device_model, manufacturer, install_date)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (device_code, device_name, device_type, site_id,
             (data.get('device_model') or '').strip(),
             (data.get('manufacturer') or '').strip(),
             (data.get('install_date') or '').strip() or None)
        )
        new_id = cur.lastrowid
        db.execute("""INSERT INTO operation_logs (module, action, target_type, target_id, operator, operator_id, details)
            VALUES (?, ?, ?, ?, ?, ?, ?)""",
            ('device', 'create', 'device', new_id,
             _current_actor_name(), g.current_user['id'],
             f"注册设备「{device_name}」({device_code})"))
        db.commit()
    return jsonify({'success': True, 'id': new_id, 'message': '设备注册成功'})


@app.route('/api/devices/<int:device_id>', methods=['PUT'])
@login_required
def api_device_update(device_id):
    """编辑设备信息"""
    g_ = require_admin()
    if g_:
        return g_
    data = request.get_json(force=True)
    with get_db() as db:
        dev = db.execute("SELECT id,status,management_scope FROM device_shadows WHERE id=?", (device_id,)).fetchone()
        if not dev:
            return jsonify({'error': '设备不存在'}), 404
        if dev['management_scope'] == 'retired':
            return jsonify({'error': '该设备已退出运维管理，不能继续移站或编辑'}), 409

        fields = []
        values = []
        for col in ['device_code', 'device_name', 'device_type', 'site_id', 'device_model', 'manufacturer', 'install_date']:
            if col in data:
                fields.append(f"{col}=?")
                values.append(data[col])
        if not fields:
            return jsonify({'error': '没有可更新的字段'}), 400

        # 如果修改了编码，检查唯一性
        if 'device_code' in data:
            dup = db.execute("SELECT id FROM device_shadows WHERE device_code=? AND id!=?",
                             (data['device_code'], device_id)).fetchone()
            if dup:
                return jsonify({'error': '设备编码已存在'}), 409

        values.append(device_id)
        db.execute(f"UPDATE device_shadows SET {', '.join(fields)} WHERE id=?", values)
        # 记录操作日志
        changed = [f"{k}→{data[k]}" for k in data if k in ['device_code','device_name','device_type','site_id','device_model','manufacturer','install_date']]
        db.execute("""INSERT INTO operation_logs (module, action, target_type, target_id, operator, operator_id, details)
            VALUES (?, ?, ?, ?, ?, ?, ?)""",
            ('device', 'update', 'device', device_id,
             _current_actor_name(), g.current_user['id'],
             '设备更新: ' + '; '.join(changed) if changed else '设备信息更新'))
        db.commit()
    return jsonify({'success': True, 'message': '设备信息已更新'})


@app.route('/api/devices/<int:device_id>', methods=['DELETE'])
@login_required
def api_device_delete(device_id):
    """删除设备（直接从台账移除。如需回收流程请走 /api/device-recycle POST）"""
    g_ = require_admin()
    if g_:
        return g_
    try:
        with get_db() as db:
            dev = db.execute("SELECT * FROM device_shadows WHERE id=?", (device_id,)).fetchone()
            if not dev:
                return jsonify({'error': '设备不存在'}), 404
            if dev['management_scope'] == 'retired':
                return jsonify({'error': '已回收设备必须保留审计档案，不能永久删除'}), 409
            db.execute("DELETE FROM device_shadows WHERE id=?", (device_id,))
            db.execute("""INSERT INTO operation_logs (module, action, target_type, target_id, operator, operator_id, details)
                VALUES (?, ?, ?, ?, ?, ?, ?)""",
                ('device', 'delete', 'device', device_id,
                 _current_actor_name(), g.current_user['id'],
                 f"删除设备「{dev['device_name']}」({dev['device_code']})"))
            db.commit()
        return jsonify({'success': True, 'message': '设备已删除'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


# --- 操作日志 ---

@app.route('/api/operation-logs')
@login_required
def api_operation_logs():
    """操作日志列表（设备管理全部操作记录）"""
    module = request.args.get('module', '').strip()
    target_type = request.args.get('target_type', '').strip()
    target_id = request.args.get('target_id', type=int)
    limit = min(int(request.args.get('limit', 50)), 200)
    with get_db() as db:
        sql = """SELECT ol.*
                 FROM operation_logs ol
                 WHERE 1=1"""
        params = []
        if module:
            sql += " AND ol.module=?"
            params.append(module)
        if target_type:
            sql += " AND ol.target_type=?"
            params.append(target_type)
        if target_id:
            sql += " AND ol.target_id=?"
            params.append(target_id)
        sql += " ORDER BY ol.created_at DESC LIMIT ?"
        params.append(limit)
        rows = db.execute(sql, params).fetchall()
        result = []
        for r in rows:
            d = dict(r)
            d['operator'] = _actor_display_name(db, d.get('operator'), d.get('operator_id'))
            result.append(d)
        # 回收台账早于统一操作日志上线，读取时补齐历史事件；新记录仍以
        # operation_logs 为准，并按设备 ID 去重，避免迁移旧库时丢失审计链。
        include_recycle = module in ('', 'device') and target_type in ('', 'device')
        if include_recycle and _table_exists(db, 'device_recycle'):
            logged_recycle_ids = {
                item.get('target_id') for item in result
                if item.get('action') == 'recycle'
            }
            recycle_sql = "SELECT * FROM device_recycle WHERE 1=1"
            recycle_params = []
            if target_id:
                recycle_sql += " AND device_id=?"
                recycle_params.append(target_id)
            recycle_sql += " ORDER BY created_at DESC LIMIT ?"
            recycle_params.append(limit)
            for row in db.execute(recycle_sql, recycle_params).fetchall():
                item = dict(row)
                if item.get('device_id') in logged_recycle_ids:
                    continue
                destination_label = {
                    'repair': '维修', 'replace': '更换', 'scrap': '报废', 'return': '退回',
                }.get(item.get('destination'), item.get('destination') or '未记录')
                result.append({
                    'id': f"recycle-{item['id']}",
                    'module': 'device',
                    'action': 'recycle',
                    'target_type': 'device',
                    'target_id': item.get('device_id'),
                    'operator': _actor_display_name(db, item.get('operator'), item.get('operator_id')),
                    'operator_id': item.get('operator_id'),
                    'details': (
                        f"回收设备「{item.get('device_name') or '-'}」"
                        f"({item.get('device_code') or '-'})；方式：{destination_label}；"
                        f"原因：{item.get('reason') or '未记录'}"
                    ),
                    'created_at': item.get('created_at') or item.get('recycle_date'),
                })
        result.sort(key=lambda item: item.get('created_at') or '', reverse=True)
        result = result[:limit]
    return jsonify(result)


# --- 设备回收 ---

@app.route('/api/device-recycle')
@login_required
def api_device_recycle_list():
    """设备回收记录列表，支持按设备/站点搜索"""
    search = request.args.get('search', '').strip()
    status = request.args.get('status', '').strip()
    with get_db() as db:
        sql = """SELECT dr.*,
                    COALESCE(
                        NULLIF(TRIM(operator_user.real_name), ''),
                        NULLIF(TRIM(legacy_user.real_name), ''),
                        NULLIF(TRIM(dr.operator), ''),
                        '系统'
                    ) AS operator_name
                 FROM device_recycle dr
                 LEFT JOIN users operator_user ON operator_user.id=dr.operator_id
                 LEFT JOIN users legacy_user ON dr.operator_id IS NULL
                    AND (legacy_user.username=dr.operator OR legacy_user.real_name=dr.operator)
                 WHERE 1=1"""
        params = []
        if search:
            sql += " AND (dr.device_code LIKE ? OR dr.device_name LIKE ? OR dr.site_name LIKE ? OR dr.destination LIKE ?)"
            like = f"%{search}%"
            params.extend([like, like, like, like])
        if status:
            sql += " AND dr.status=?"
            params.append(status)
        sql += " ORDER BY dr.created_at DESC"
        rows = db.execute(sql, params).fetchall()
        records = [dict(r) for r in rows]
        return jsonify(records)

@app.route('/api/device-recycle', methods=['POST'])
@login_required
def api_device_recycle_create():
    """登记设备回收"""
    g_ = require_admin()
    if g_:
        return g_
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        # 验证设备是否存在
        device_id = data.get('device_id')
        device = db.execute("SELECT * FROM device_shadows WHERE id=?", (device_id,)).fetchone()
        if not device:
            return jsonify({'error': '设备不存在'}), 404
        if device['management_scope'] == 'retired':
            return jsonify({'error': '该设备已回收，不能重复登记'}), 409
        existing = db.execute("""SELECT id FROM device_recycle
            WHERE device_id=? AND status='recycled' ORDER BY id DESC LIMIT 1""", (device_id,)).fetchone()
        if existing:
            return jsonify({'error': '该设备已有有效回收记录，不能重复登记'}), 409
        recycle_date = (data.get('recycle_date') or '').strip()
        reason = (data.get('reason') or '').strip()
        destination = (data.get('destination') or '').strip()
        if not recycle_date or not reason or destination not in ('repair', 'replace', 'scrap', 'return'):
            return jsonify({'error': '请完整填写回收日期、回收方式和回收原因'}), 400
        # 插入回收记录
        site = db.execute("SELECT name FROM sites WHERE id=?", (device['site_id'],)).fetchone()
        operator_id = g.current_user.get('id')
        operator_name = g.current_user.get('real_name') or g.current_user.get('username') or '系统'
        db.execute("""
            INSERT INTO device_recycle (device_id, device_code, device_name, device_type,
                site_id, site_name, recycle_date, reason, destination, operator, operator_id,
                remark, status, work_order_no)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (device_id, device['device_code'], device['device_name'], device['device_type'],
              device['site_id'], site['name'] if site else '',
              recycle_date, reason, destination, operator_name, operator_id,
              data.get('remark', ''), 'recycled', (data.get('work_order_no') or '').strip()))
        # 同时将设备状态设为 offline（已回收）
        db.execute("UPDATE device_shadows SET status='offline', management_scope='retired' WHERE id=?", (device_id,))
        # 记录时间线事件
        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                   ('device', device_id, 'recycled', operator_name,
                    f'设备回收-{device["device_name"]}({device["device_code"]})->{destination}'))
        db.execute("""INSERT INTO operation_logs
            (module,action,target_type,target_id,operator,operator_id,details)
            VALUES ('device','recycle','device',?,?,?,?)""",
            (device_id, g.current_user.get('real_name') or g.current_user.get('username'),
             g.current_user.get('id'),
             f'登记设备回收处置「{device["device_name"]}」({device["device_code"]})；方式：{destination}；原因：{reason}'))
        db.commit()
        return jsonify({'success': True, 'message': '设备已退出运维管理，回收处置已记入操作日志'})

@app.route('/api/device-recycle/<int:rec_id>', methods=['PUT'])
@login_required
def api_device_recycle_update(rec_id):
    """更新回收记录（如去向变更）"""
