@app.route('/api/sites/import', methods=['POST'])
@login_required
def import_sites():
    """批量导入站点：整批校验、整批提交，不接受部分成功。"""
    denied = require_admin()
    if denied:
        return denied
    if 'file' not in request.files:
        return jsonify({'error': '请上传站点导入文件'}), 400
    f = request.files['file']
    filename = (f.filename or '').lower()
    import csv as csv_mod, io
    if filename.endswith(('.xlsx', '.xlsm')):
        if not _HAS_OPENPYXL:
            return jsonify({'error': '缺少 openpyxl，无法读取 Excel 文件'}), 500
        try:
            workbook = load_workbook(f, read_only=True, data_only=True)
            sheet = workbook['站点导入'] if '站点导入' in workbook.sheetnames else workbook.active
            values = list(sheet.iter_rows(values_only=True))
            headers = [_import_text(value) for value in (values[0] if values else [])]
            raw_rows = [dict(zip(headers, row)) for row in values[1:]
                        if any(_import_text(value) for value in row)]
        except Exception as exc:
            return jsonify({'error': f'Excel 文件无法读取：{exc}'}), 400
    elif filename.endswith('.csv'):
        try:
            content = f.read().decode('utf-8-sig')
        except UnicodeDecodeError:
            return jsonify({'error': 'CSV文件必须使用UTF-8编码'}), 400
        reader = csv_mod.DictReader(io.StringIO(content))
        if not reader.fieldnames:
            return jsonify({'error': 'CSV缺少表头，请使用下载模板'}), 400
        raw_rows = list(reader)
    else:
        return jsonify({'error': '仅支持 .xlsx 或历史 .csv 站点文件'}), 400
    if not raw_rows:
        return jsonify({'error': 'CSV没有站点数据，请至少填写一行'}), 400

    def pick(row, *names):
        for name in names:
            value = row.get(name)
            if value is not None and str(value).strip():
                return str(value).strip()
        return ''

    prepared = []
    errors = []
    seen_codes = set()
    for row_number, row in enumerate(raw_rows, 2):
        code = pick(row, 'code', '编码', '站点编码')
        name = pick(row, 'name', '名称', '站点名称')
        stype = pick(row, 'type', '类型', '站点类型')
        row_errors = []
        if not code or not name or not stype:
            row_errors.append('缺少必填列：站点编码、站点名称或站点类型')
        if stype in ('水质站', '水质监测站'):
            stype = 'water_quality'
        if stype and stype != 'water_quality':
            row_errors.append('type 仅支持 water_quality（水质监测站）')
        if code and code in seen_codes:
            row_errors.append('站点编码在文件内重复')
        seen_codes.add(code)

        coordinates = []
        for label, raw in (
            ('纬度', pick(row, 'lat', 'gps_lat', '纬度')),
            ('经度', pick(row, 'lng', 'gps_lng', '经度')),
        ):
            if not raw:
                coordinates.append(None)
                continue
            try:
                value = float(raw)
                if (label == '纬度' and not -90 <= value <= 90) or (label == '经度' and not -180 <= value <= 180):
                    raise ValueError()
                coordinates.append(value)
            except (TypeError, ValueError):
                row_errors.append(f'{label}格式或范围无效')
                coordinates.append(None)

        if row_errors:
            errors.append(f'第{row_number}行{f"({code})" if code else ""}: {"；".join(row_errors)}')
            continue
        prepared.append({
            'row_number': row_number,
            'code': code,
            'name': name,
            'type': stype,
            'gps_lat': coordinates[0],
            'gps_lng': coordinates[1],
            'district': pick(row, 'district', '区域', '区县'),
            'river': pick(row, 'river', '河流'),
            'manager': pick(row, 'manager', '负责人'),
            'phone': pick(row, 'phone', '电话'),
        })

    with get_db() as db:
        if prepared:
            placeholders = ','.join('?' for _ in prepared)
            existing = {
                row['code'] for row in db.execute(
                    f'SELECT code FROM sites WHERE code IN ({placeholders})',
                    [item['code'] for item in prepared],
                ).fetchall()
            }
            for item in prepared:
                if item['code'] in existing:
                    errors.append(f'第{item["row_number"]}行({item["code"]}): 站点编码已存在')

        if errors:
            return jsonify({
                'success': False,
                'error': '导入已取消：存在无效记录，数据库未写入任何站点',
                'imported': 0,
                'failed': len(errors),
                'total': len(raw_rows),
                'rolled_back': True,
                'errors': errors[:50],
            }), 422

        batch_id = f'SITEIMP-{datetime.now().strftime("%Y%m%d%H%M%S")}-{uuid.uuid4().hex[:6].upper()}'
        try:
            db.execute(
                "INSERT INTO site_import_batches (batch_id,filename,total_rows,imported_count,created_by) VALUES (?,?,?,?,?)",
                (batch_id, f.filename or 'sites.csv', len(prepared), len(prepared), g.current_user.get('id')),
            )
            for item in prepared:
                cur = db.execute(
                    "INSERT INTO sites (code,name,type,gps_lat,gps_lng,district,river,manager,phone) VALUES (?,?,?,?,?,?,?,?,?)",
                    (item['code'], item['name'], item['type'], item['gps_lat'], item['gps_lng'],
                     item['district'], item['river'], item['manager'], item['phone']),
                )
                db.execute(
                    "INSERT INTO site_import_rows (batch_id,row_number,site_id,site_code,status,message) VALUES (?,?,?,?,?,?)",
                    (batch_id, item['row_number'], cur.lastrowid, item['code'], 'imported', ''),
                )
            db.commit()
        except Exception:
            db.rollback()
            return jsonify({
                'success': False,
                'error': '导入写入失败，整批数据已回滚，请检查文件后重试',
                'imported': 0,
                'failed': len(prepared),
                'total': len(prepared),
                'rolled_back': True,
            }), 500

    return jsonify({
        'success': True,
        'batch_id': batch_id,
        'imported': len(prepared),
        'failed': 0,
        'total': len(prepared),
        'errors': [],
    })

@app.route('/api/sites', methods=['POST'])
@login_required
def create_site():
    """Create one water-quality site and assign its responsible operator atomically."""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    code = str(data.get('code') or '').strip()
    name = str(data.get('name') or '').strip()
    manager_id = data.get('manager_id', data.get('assignee_id'))
    if not code or not name or manager_id in (None, ''):
        return jsonify({'error': '请填写站点编码、站点名称和负责人', 'code': 'SITE_REQUIRED_FIELDS'}), 400
    try:
        manager_id = int(manager_id)
    except (TypeError, ValueError):
        return jsonify({'error': '负责人无效', 'code': 'SITE_MANAGER_INVALID'}), 400
    if not 1 <= len(code) <= 80 or not 1 <= len(name) <= 120:
        return jsonify({'error': '站点编码或名称长度无效', 'code': 'SITE_FIELD_INVALID'}), 400
    try:
        lat = float(data.get('gps_lat'))
        lng = float(data.get('gps_lng'))
    except (TypeError, ValueError):
        return jsonify({'error': '请填写有效的经纬度', 'code': 'SITE_COORDINATES_REQUIRED'}), 400
    if not -90 <= lat <= 90 or not -180 <= lng <= 180:
        return jsonify({'error': '经纬度超出有效范围', 'code': 'SITE_COORDINATES_INVALID'}), 400
    with get_db() as db:
        manager = db.execute("SELECT id, real_name, phone, status, role FROM users WHERE id=?", (manager_id,)).fetchone()
        if not manager or manager['status'] != 'active':
            return jsonify({'error': '负责人不存在或已停用', 'code': 'SITE_MANAGER_UNAVAILABLE'}), 409
        manager_roles = {
            str(row['role'] or '').strip()
            for row in db.execute('SELECT role FROM user_roles WHERE user_id=?', (manager_id,)).fetchall()
        }
        if manager['role']:
            manager_roles.add(str(manager['role']).strip())
        if 'operator' not in manager_roles:
            return jsonify({'error': '负责人不是可执行运维人员', 'code': 'SITE_MANAGER_ROLE_INVALID'}), 409
        if db.execute("SELECT 1 FROM sites WHERE code=?", (code,)).fetchone():
            return jsonify({'error': '站点编码已存在', 'code': 'SITE_CODE_EXISTS'}), 409
        try:
            cur = db.execute("""INSERT INTO sites
                (code,name,type,gps_lat,gps_lng,district,address,river,manager,phone,status)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)""", (
                code, name, 'water_quality', lat, lng,
                str(data.get('district') or '').strip(), str(data.get('address') or '').strip(),
                str(data.get('river') or '').strip(), manager['real_name'] or '', manager['phone'] or '',
                'normal'))
            site_id = cur.lastrowid
            db.execute("INSERT INTO user_sites (user_id,site_id) VALUES (?,?)", (manager_id, site_id))
            db.commit()
        except sqlite3.IntegrityError:
            db.rollback()
            return jsonify({'error': '站点编码已存在或负责人授权写入失败', 'code': 'SITE_CREATE_CONFLICT'}), 409
        row = db.execute("SELECT * FROM sites WHERE id=?", (site_id,)).fetchone()
    return jsonify({'success': True, 'site': dict(row), 'manager_id': manager_id}), 201

