@app.route('/api/inspection/photos/<int:site_id>/check', methods=['GET'])
def api_inspection_photos_check(site_id):
    denied = _site_access_denied(site_id)
    if denied:
        return denied
    """检查某站点某周期照片是否传齐，返回缺项列表"""
    period = request.args.get('period', 'weekly')
    with get_db() as db:
        site = db.execute('SELECT type FROM sites WHERE id=?', (site_id,)).fetchone()
        site_type = site['type'] if site else 'water_quality'
        requirements = db.execute(
            'SELECT * FROM photo_requirements WHERE site_type=? AND period=? ORDER BY seq',
            (site_type, period)).fetchall()
        missing = []
        for req in requirements:
            count = db.execute(
                """SELECT COUNT(*) as cnt FROM operation_attachments
                   WHERE site_id=? AND requirement_id=? AND is_deleted=0
                     AND source_type='inspection'
                     AND COALESCE(review_status, 'pending') NOT IN ('rejected', 'voided')
                     AND COALESCE(evidence_qualification,'review')='qualified'""",
                (site_id, req['id'])).fetchone()['cnt']
            if count < req['photo_count']:
                missing.append({
                    'requirement_id': req['id'],
                    'item_name': req['item_name'],
                    'required': req['photo_count'],
                    'uploaded': count,
                    'missing': req['photo_count'] - count
                })
        return jsonify({'site_id': site_id, 'period': period, 'complete': len(missing) == 0, 'missing': missing})


# ---------- 试剂状态计算（纯手动，不预测）----------
def compute_reagent_status(inv):
    """根据库存行计算试剂状态与剩余可用天数。
    剩余使用时间完全由运维人员经验手动填写（expected_duration_days），系统不做预测。
    触发预警的两类：剩余天数 <= 临期阈值（warning_days）或 余量 <= 低余量阈值。
    """
    expected = inv.get('expected_duration_days')
    last = inv.get('last_replaced_at')
    warning = inv.get('warning_days') or 7
    qty = inv.get('current_qty')
    threshold = inv.get('low_stock_threshold')
    remaining = None
    expires_at = None
    flags = []
    if expected is not None and last:
        try:
            ld = datetime.strptime(last[:19], '%Y-%m-%d %H:%M:%S')
        except ValueError:
            try:
                ld = datetime.strptime(last[:10], '%Y-%m-%d')
            except ValueError:
                ld = None
        if ld:
            exp = ld + timedelta(days=expected)
            expires_at = exp.strftime('%Y-%m-%d')
            remaining = (exp.date() - datetime.now().date()).days
            if remaining <= 0:
                flags.append('已过期')
            elif remaining <= warning:
                flags.append('临期')
    if qty is not None and threshold is not None and qty <= threshold:
        flags.append('低余量')
    if not flags:
        status = '未设置' if (expected is None and last is None) else '正常'
    else:
        status = '已过期' if '已过期' in flags else ('临期' if '临期' in flags else '低余量')
    return {'remaining_days': remaining, 'expires_at': expires_at, 'status': status}


# ---------- 3.1 试剂主数据 ----------
def _reagent_master_fields(data, existing=None):
    existing = dict(existing) if existing is not None else {}
    name = str(data.get('name', existing.get('name', '')) or '').strip()
    manufacturer = str(data.get('manufacturer', existing.get('manufacturer', '')) or '').strip()
    spec = str(data.get('spec', existing.get('spec', '')) or '').strip()
    unit = str(data.get('unit', existing.get('unit', '瓶')) or '').strip()
    raw_shelf_life = data.get('shelf_life_days', existing.get('shelf_life_days', 365))
    if not name:
        return None, ('请填写试剂名称', 'REAGENT_NAME_REQUIRED')
    if len(name) > 50:
        return None, ('试剂名称不能超过50个字符', 'REAGENT_NAME_TOO_LONG')
    if len(manufacturer) > 50 or len(spec) > 50:
        return None, ('生产厂家和规格均不能超过50个字符', 'REAGENT_FIELD_TOO_LONG')
    if not unit or len(unit) > 10:
        return None, ('计量单位不能为空且不能超过10个字符', 'REAGENT_UNIT_INVALID')
    if isinstance(raw_shelf_life, bool):
        return None, ('保质期必须是1至3650天的整数', 'REAGENT_SHELF_LIFE_INVALID')
    try:
        shelf_life_days = int(raw_shelf_life)
    except (ValueError, TypeError):
        return None, ('保质期必须是1至3650天的整数', 'REAGENT_SHELF_LIFE_INVALID')
    if isinstance(raw_shelf_life, float) and not raw_shelf_life.is_integer():
        return None, ('保质期必须是1至3650天的整数', 'REAGENT_SHELF_LIFE_INVALID')
    if not 1 <= shelf_life_days <= 3650:
        return None, ('保质期必须在1至3650天之间', 'REAGENT_SHELF_LIFE_INVALID')
    return {
        'name': name,
        'manufacturer': manufacturer,
        'spec': spec,
        'unit': unit,
        'shelf_life_days': shelf_life_days,
    }, None


