# ---------- 1.1 车辆全生命周期 ----------
VEHICLE_INSPECTION_ITEMS = [
    '驾驶证随车', '保险与年检', '大灯及远近光', '转向灯', '尾灯/雾灯/刹车灯/倒车灯',
    '空调', '喇叭', '左右后视镜', '前漆面外观', '后漆面外观', '左漆面外观', '右漆面外观',
    '四轮磨损及胎压', '车内卫生',
]
VEHICLE_BLOCKING_STATUSES = {'maintenance', 'restricted', 'retired'}


def _vehicle_expiry_date(value):
    """月份型有效期表示该月最后一天，完整日期保持原值。"""
    text = str(value or '').strip()
    if re.fullmatch(r'\d{4}-\d{2}', text):
        year, month = (int(part) for part in text.split('-'))
        try:
            return f'{text}-{calendar.monthrange(year, month)[1]:02d}'
        except ValueError:
            return text
    return text


def _vehicle_document_state(db, vehicle_id):
    """汇总证照到期状态。过期证照不允许被安排或出车。"""
    today = datetime.now().strftime('%Y-%m-%d')
    due_date = (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')
    rows = db.execute('''SELECT document_type, valid_until FROM vehicle_documents
                       WHERE vehicle_id=? AND valid_until IS NOT NULL AND valid_until!='' ''', (vehicle_id,)).fetchall()
    expired = [r['document_type'] for r in rows if _vehicle_expiry_date(r['valid_until']) < today]
    due_soon = [r['document_type'] for r in rows
                if today <= _vehicle_expiry_date(r['valid_until']) <= due_date]
    vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (vehicle_id,)).fetchone()
    if vehicle:
        for field, document_type in (
            ('insurance_expiry', 'insurance'),
            ('annual_inspection_expiry', 'annual_inspection'),
            ('registration_expiry', 'registration'),
        ):
            if field not in vehicle.keys() or not vehicle[field]:
                continue
            valid_until = _vehicle_expiry_date(vehicle[field])
            if valid_until < today and document_type not in expired:
                expired.append(document_type)
            elif today <= valid_until <= due_date and document_type not in due_soon:
                due_soon.append(document_type)
    return {'expired': expired, 'due_soon': due_soon}


def _plan_schedule_has_open_execution(db, schedule_id):
    """A plan vehicle remains reserved until every active item is complete and checked out."""
    if not schedule_id:
        return False
    try:
        checkout_sql = " OR pi.check_out_time IS NULL" if _mobile_checkout_supported(db) else ""
        row = db.execute(f"""SELECT 1 FROM insp_plans ip
            JOIN insp_plan_items pi ON pi.plan_id=ip.id
            WHERE ip.plan_schedule_id=? AND ip.status IN ('active','completed')
              AND COALESCE(pi.execution_status,'active')='active'
              AND (pi.result IS NULL{checkout_sql}) LIMIT 1""", (schedule_id,)).fetchone()
        return bool(row)
    except sqlite3.OperationalError:
        try:
            row = db.execute("""SELECT 1 FROM insp_plans
                WHERE plan_schedule_id=? AND status!='completed' LIMIT 1""", (schedule_id,)).fetchone()
            return bool(row)
        except sqlite3.OperationalError:
            return False


def _vehicle_schedule_id(reason):
    match = re.search(r'巡检计划#(\d+)', str(reason or ''))
    return int(match.group(1)) if match else None


def _vehicle_application_schedule_id(db, application_row):
    """Resolve a plan schedule for normal and remediation vehicle applications."""
    row = dict(application_row or {})
    schedule_id = _vehicle_schedule_id(row.get('reason'))
    if schedule_id:
        return schedule_id
    rework_plan_id = row.get('rework_plan_id')
    if not rework_plan_id:
        return None
    try:
        plan = db.execute("SELECT plan_schedule_id FROM insp_plans WHERE id=?", (rework_plan_id,)).fetchone()
    except sqlite3.OperationalError:
        return None
    return plan['plan_schedule_id'] if plan and plan['plan_schedule_id'] else None


def _vehicle_can_dispatch(db, vehicle, exclude_application_id=None, exclude_schedule_id=None):
    if not vehicle:
        return False, '车辆不存在'
    if vehicle['status'] in VEHICLE_BLOCKING_STATUSES:
        return False, '车辆处于维修、限制使用或已报废状态'
    # A checked-out vehicle remains occupied even if its application end time
    # has passed or a legacy record left the vehicle status as idle.
    try:
        rework_column = ', va.rework_plan_id' if _table_has_column(db, 'vehicle_applications', 'rework_plan_id') else ''
        active = db.execute(f'''SELECT r.id, va.reason{rework_column}
                               FROM vehicle_use_records r
                               JOIN vehicle_applications va ON va.id=r.application_id
                               WHERE va.vehicle_id=? AND r.returned_at IS NULL
                                 AND (? IS NULL OR va.id!=?)
                               ORDER BY r.id DESC LIMIT 1''',
                            (vehicle['id'], exclude_application_id, exclude_application_id)).fetchone()
    except sqlite3.OperationalError:
        active = None
    if active and _vehicle_application_schedule_id(db, active) != exclude_schedule_id:
        return False, '车辆仍在使用中，请先归还或延续当前安排'
    # An overdue plan reservation does not silently release the vehicle while its
    # execution packages remain open, even if a legacy merge left no active use row.
    try:
        rework_supported = _table_has_column(db, 'vehicle_applications', 'rework_plan_id')
        rework_column = ', rework_plan_id' if rework_supported else ''
        schedule_filter = "(reason LIKE '%巡检计划#%' OR rework_plan_id IS NOT NULL)" if rework_supported else "reason LIKE '%巡检计划#%'"
        reservations = db.execute(f"""SELECT id,reason{rework_column} FROM vehicle_applications
            WHERE vehicle_id=? AND status='approved' AND date(end_at)<date('now','localtime')
              AND (? IS NULL OR id!=?) AND {schedule_filter}""",
            (vehicle['id'], exclude_application_id, exclude_application_id)).fetchall()
        for reservation in reservations:
            schedule_id = _vehicle_application_schedule_id(db, reservation)
            if schedule_id == exclude_schedule_id:
                continue
            if _plan_schedule_has_open_execution(db, schedule_id):
                return False, '车辆仍被未完成巡检计划占用，请先延续安排或完成计划'
    except sqlite3.OperationalError:
        pass
    doc_state = _vehicle_document_state(db, vehicle['id'])
    if doc_state['expired']:
        labels = {
            'insurance': '保险', 'annual_inspection': '年检',
            'registration': '行驶证', 'driving_license': '驾驶证',
        }
        return False, f"证照已到期：{'、'.join(labels.get(item, item) for item in doc_state['expired'])}"
    # 兼容历史上只维护在车辆主表的保险/年检日期。
    today = datetime.now().strftime('%Y-%m-%d')
    for field, label in (('insurance_expiry', '保险'), ('annual_inspection_expiry', '年检')):
        if field in vehicle.keys() and vehicle[field] and _vehicle_expiry_date(vehicle[field]) < today:
            return False, f'{label}已到期'
    return True, ''


def _vehicle_plan_use_state(db, use_row):
    """Return the effective state of a use record, including overdue plan trips."""
    row = dict(use_row or {})
    schedule_id = _vehicle_application_schedule_id(db, row)
    is_plan_trip = bool(schedule_id)
    plan_vehicle_replaced = False
    plan_status = None
    if schedule_id:
        if _plan_schedule_has_open_execution(db, schedule_id):
            plan_status = 'active'
        else:
            try:
                schedule_exists = db.execute(
                    'SELECT 1 FROM plan_schedules WHERE id=? LIMIT 1', (schedule_id,)).fetchone()
            except sqlite3.OperationalError:
                schedule_exists = None
            plan_status = 'completed' if schedule_exists else 'unknown'
        try:
            schedule_columns = {
                item['name'] for item in db.execute('PRAGMA table_info(plan_schedules)').fetchall()
            }
            vehicle_column = ', vehicle_id' if 'vehicle_id' in schedule_columns else ''
            schedule = db.execute(
                f'SELECT status, vehicle_days{vehicle_column} FROM plan_schedules WHERE id=?',
                (schedule_id,)).fetchone()
            if schedule and schedule['status'] == 'approved':
                current_vehicle_id = schedule['vehicle_id'] if vehicle_column else None
                current_vehicle_known = True
                if current_vehicle_id in (None, ''):
                    current_days = json.loads(schedule['vehicle_days'] or '{}')
                    if not isinstance(current_days, dict):
                        current_vehicle_known = False
                    else:
                        current_ids = set()
                        for value in current_days.values():
                            if value in (None, ''):
                                continue
                            parsed = int(value)
                            if parsed <= 0:
                                raise ValueError('invalid current vehicle')
                            current_ids.add(parsed)
                        if len(current_ids) > 1:
                            current_vehicle_known = False
                        else:
                            current_vehicle_id = next(iter(current_ids), None)
                if current_vehicle_known:
                    plan_vehicle_replaced = current_vehicle_id in (None, '') \
                        or int(current_vehicle_id) != int(row.get('vehicle_id'))
        except (TypeError, ValueError, json.JSONDecodeError, sqlite3.OperationalError):
            plan_vehicle_replaced = False
    trip_end = str(row.get('end_at') or '')[:10]
    today = datetime.now().strftime('%Y-%m-%d')
    expired = bool(trip_end and trip_end < today)
    plan_completed = bool(is_plan_trip and plan_status == 'completed')
    active = not row.get('returned_at') and row.get('status') != 'returned'
    needs_extension = bool(active and is_plan_trip and expired and not plan_completed)
    can_return = bool(active and (
        not is_plan_trip or plan_completed or plan_vehicle_replaced
        or row.get('vehicle_status') == 'restricted'))
    row.update({
        'plan_schedule_id': schedule_id,
        'is_plan_trip': is_plan_trip,
        'trip_end_date': trip_end or None,
        'plan_status': plan_status,
        'plan_completed': plan_completed,
        'plan_vehicle_replaced': plan_vehicle_replaced,
        'use_expired': expired,
        'needs_extension': needs_extension,
        'can_return': can_return,
    })
    return row


def _vehicle_plan_application_state(db, application_row):
    """Evaluate a plan reservation even when no checkout record exists."""
    row = dict(application_row or {})
    schedule_id = _vehicle_application_schedule_id(db, row)
    trip_end = str(row.get('end_at') or '')[:10]
    today = datetime.now().strftime('%Y-%m-%d')
    plan_open = bool(schedule_id and _plan_schedule_has_open_execution(db, schedule_id))
    try:
        use = db.execute("""SELECT id,returned_at,status FROM vehicle_use_records
            WHERE application_id=? ORDER BY id DESC LIMIT 1""", (row.get('id'),)).fetchone()
    except sqlite3.OperationalError:
        use = None
    active_use = bool(use and not use['returned_at'] and use['status'] != 'returned')
    expired = bool(trip_end and trip_end < today)
    can_checkout = False
    checkout_block_reason = ''
    if row.get('status') != 'approved':
        checkout_block_reason = '用车申请尚未获批'
    elif not row.get('vehicle_id'):
        checkout_block_reason = '该安排尚未指定车辆'
    elif active_use:
        checkout_block_reason = '该安排已完成出车登记'
    elif row.get('status') == 'approved' and plan_open and expired:
        checkout_block_reason = '用车安排已超期，请先延续安排'
    else:
        vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (row['vehicle_id'],)).fetchone()
        can_checkout, checkout_block_reason = _vehicle_can_dispatch(
            db, vehicle, exclude_application_id=row.get('id'))
        if can_checkout and vehicle and vehicle['status'] == 'in_use':
            can_checkout, checkout_block_reason = False, '车辆正在使用'
    row.update({
        'plan_schedule_id': schedule_id,
        'is_plan_trip': bool(schedule_id),
        'trip_end_date': trip_end or None,
        'plan_completed': bool(schedule_id and not plan_open),
        'use_expired': expired,
        'needs_extension': bool(row.get('status') == 'approved' and plan_open and expired),
        'reserves_vehicle': bool(row.get('status') == 'approved' and plan_open),
        'has_active_use': active_use,
        'use_id': use['id'] if use else None,
        'can_checkout': bool(can_checkout),
        'checkout_block_reason': checkout_block_reason or '',
    })
    return row


def _notify_vehicle_expiry(db, state):
    """Create one unread expiry reminder per active planned use."""
    if not state.get('needs_extension') or not state.get('applicant_id'):
        return
    try:
        source_id = state.get('application_id') or state['id']
        existing = db.execute(
            "SELECT id FROM notifications WHERE user_id=? AND source_type='vehicle_use_expiry' AND source_id=? LIMIT 1",
            (state['applicant_id'], source_id),
        ).fetchone()
        if not existing:
            _create_notification(
                state['applicant_id'], 'vehicle_use_expiry', source_id,
                '车辆使用安排已超期',
                f"车辆 {state.get('plate_no') or ''} 的安排已于 {state.get('trip_end_date') or '计划结束日'} 到期，关联巡检计划尚未完成，请及时延续用车安排。",
                db=db,
            )
    except sqlite3.OperationalError:
        # Small isolated test databases may not include the notification table.
        pass


def _vehicle_user_can_operate(application, user):
    return user and (_has_any_role(user, 'admin') or int(application['applicant_id'] or 0) == int(user['id']))


@app.route('/api/vehicles', methods=['GET'])
@login_required
def api_vehicles():
    """车辆列表，可按状态过滤"""
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权查看车辆台账'}), 403
    status = request.args.get('status')
    with get_db() as db:
        if status:
            rows = db.execute('SELECT * FROM vehicles WHERE status=? ORDER BY plate_no', (status,)).fetchall()
        else:
            rows = db.execute("SELECT * FROM vehicles WHERE status<>'retired' ORDER BY plate_no").fetchall()
        result = []
        for row in rows:
            item = dict(row)
            item['document_state'] = _vehicle_document_state(db, row['id'])
            item['dispatchable'], item['dispatch_block_reason'] = _vehicle_can_dispatch(db, row)
            try:
                active = db.execute('''SELECT r.*, va.applicant_id, va.end_at, va.reason,
                                             v.plate_no, v.status AS vehicle_status
                                      FROM vehicle_use_records r
                                      JOIN vehicle_applications va ON va.id=r.application_id
                                      JOIN vehicles v ON v.id=va.vehicle_id
                                      WHERE va.vehicle_id=? AND r.returned_at IS NULL
                                      ORDER BY r.id DESC LIMIT 1''', (row['id'],)).fetchone()
            except sqlite3.OperationalError:
                active = None
            if active:
                state = _vehicle_plan_use_state(db, active)
                item.update({
                    'active_use_id': state['id'],
                    'active_use_applicant_id': state.get('applicant_id'),
                    'active_use_expired': state['use_expired'],
                    'active_use_needs_extension': state['needs_extension'],
                    'active_plan_completed': state['plan_completed'],
                    'active_use_status': 'overdue' if state['needs_extension'] else 'in_use',
                })
                _notify_vehicle_expiry(db, state)
                item['dispatchable'] = False
                item['dispatch_block_reason'] = ('使用中且计划已超期，待延续安排' if state['needs_extension']
                                                  else '车辆正在使用中，归还后方可再次安排')
            else:
                item['active_use_id'] = None
                item['active_use_expired'] = False
                item['active_use_needs_extension'] = False
                item['active_plan_completed'] = False
                try:
                    reservations = db.execute("""SELECT va.*,v.plate_no
                        FROM vehicle_applications va JOIN vehicles v ON v.id=va.vehicle_id
                        WHERE va.vehicle_id=? AND va.status='approved'
                          AND va.reason LIKE '%巡检计划#%'
                        ORDER BY va.id DESC""", (row['id'],)).fetchall()
                except sqlite3.OperationalError:
                    reservations = []
                reservation_state = next((state for state in
                    (_vehicle_plan_application_state(db, reservation) for reservation in reservations)
                    if state['reserves_vehicle']), None)
                if reservation_state:
                    item['active_arrangement_id'] = reservation_state['id']
                    item['active_use_expired'] = reservation_state['use_expired']
                    item['active_use_needs_extension'] = reservation_state['needs_extension']
                    item['active_plan_completed'] = reservation_state['plan_completed']
                    item['dispatchable'] = False
                    item['dispatch_block_reason'] = ('计划用车安排已超期，待延续安排'
                                                      if reservation_state['needs_extension']
                                                      else '车辆已被未完成巡检计划预留')
                    _notify_vehicle_expiry(db, reservation_state)
                else:
                    item['active_arrangement_id'] = None
            result.append(item)
        db.commit()
        return jsonify(result)


@app.route('/api/vehicles', methods=['POST'])
@login_required
def api_vehicles_create():
    """新增车辆"""
    g_ = require_admin()
    if g_:
        return g_
    data = request.get_json() or {}
    plate_no = (data.get('plate_no') or '').strip().upper()
    if not plate_no:
        return jsonify({'error': '请填写车牌号'}), 400
    model = data.get('model', '')
    seats = data.get('seats', 5)
    with get_db() as db:
        try:
            cur = db.execute(
                '''INSERT INTO vehicles (plate_no, model, seats, vehicle_name, department, fuel_type,
                                        purchase_date, insurance_expiry, annual_inspection_expiry)
                   VALUES (?,?,?,?,?,?,?,?,?)''',
                (plate_no, model, seats, data.get('vehicle_name', ''), data.get('department', ''),
                 data.get('fuel_type', ''), data.get('purchase_date'), data.get('insurance_expiry'),
                 data.get('annual_inspection_expiry')))
        except sqlite3.IntegrityError:
            return jsonify({'error': f'车牌号 {plate_no} 已存在，请勿重复新增', 'code': 'DUPLICATE_PLATE_NO'}), 409
        db.commit()
        row = db.execute('SELECT * FROM vehicles WHERE id=?', (cur.lastrowid,)).fetchone()
        return jsonify(dict(row)), 201

@app.route('/api/vehicles/<int:vid>', methods=['PUT'])
@login_required
def api_vehicles_update(vid):
    """更新车辆信息（管理员限定）"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    protected_fields = [field for field in ('current_mileage', 'next_maintenance_mileage') if field in data]
    if protected_fields:
        return jsonify({
            'error': '当前里程和下次保养里程由行程及维保流程维护，不能在车辆编辑中直接修改',
            'code': 'VEHICLE_MILEAGE_MANAGED',
        }), 400
    with get_db() as db:
        existing = db.execute('SELECT * FROM vehicles WHERE id=?', (vid,)).fetchone()
        if not existing:
            return jsonify({'error': '车辆不存在'}), 404
        # 通用字段更新
        for k in ['model', 'seats', 'plate_no', 'status', 'vehicle_name',
                  'department', 'fuel_type', 'purchase_date', 'insurance_expiry',
                  'annual_inspection_expiry', 'registration_expiry']:
            if k in data:
                db.execute(f'UPDATE vehicles SET {k}=? WHERE id=?', (data[k], vid))
        db.commit()
        row = db.execute('SELECT * FROM vehicles WHERE id=?', (vid,)).fetchone()
        return jsonify(dict(row))


@app.route('/api/vehicles/<int:vid>', methods=['DELETE'])
@login_required
def api_vehicles_delete(vid):
    """仅删除从未产生业务记录的误建台账，其他车辆应归档而非删历史。"""
    denied = require_admin()
    if denied:
        return denied
    with get_db() as db:
        if not db.execute('SELECT id FROM vehicles WHERE id=?', (vid,)).fetchone():
            return jsonify({'error': '车辆不存在'}), 404
        relations = ('vehicle_applications', 'vehicle_refueling_records', 'vehicle_maintenance_records', 'vehicle_inspections', 'vehicle_documents')
        if any(db.execute(f'SELECT 1 FROM {table} WHERE vehicle_id=? LIMIT 1', (vid,)).fetchone() for table in relations):
            return jsonify({'error': '该车辆已有业务记录，不能删除；请设为已报废归档以保留审计记录'}), 409
        db.execute('DELETE FROM vehicles WHERE id=?', (vid,))
        db.commit()
    return jsonify({'ok': True})


