# ---------- 1.2 用车申请 ----------
def _vehicle_application_datetime(value):
    """Strictly parse a client vehicle time and return the canonical stored value."""
    if value is None:
        return None
    raw = str(value).strip().replace('T', ' ')
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M'):
        try:
            parsed = datetime.strptime(raw, fmt)
        except ValueError:
            continue
        if parsed.strftime(fmt) == raw:
            return parsed, parsed.strftime('%Y-%m-%d %H:%M:%S')
    return None


def _vehicle_application_admin_ids(db):
    """Return every active user whose primary or secondary role includes admin."""
    role_clause = "u.role='admin'"
    if _table_exists(db, 'user_roles'):
        role_clause += " OR EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id=u.id AND ur.role='admin')"
    status_clause = " AND u.status='active'" if _table_has_column(db, 'users', 'status') else ''
    rows = db.execute(
        f"SELECT DISTINCT u.id FROM users u WHERE ({role_clause}){status_clause} ORDER BY u.id"
    ).fetchall()
    return [row['id'] for row in rows]


def _notify_vehicle_application_admins(db, application):
    """Create one current review reminder per eligible admin in the caller's transaction."""
    applicant = db.execute(
        'SELECT real_name FROM users WHERE id=?', (application['applicant_id'],)
    ).fetchone()
    applicant_name = (applicant['real_name'] or '').strip() if applicant else ''
    parts = [f'申请人：{applicant_name or "用户#" + str(application["applicant_id"])}']

    if application['vehicle_id']:
        vehicle = db.execute(
            'SELECT plate_no,model FROM vehicles WHERE id=?', (application['vehicle_id'],)
        ).fetchone()
        vehicle_facts = []
        if vehicle:
            vehicle_facts = [str(value).strip() for value in (vehicle['plate_no'], vehicle['model'])
                             if value is not None and str(value).strip()]
        parts.append('车辆：' + (' '.join(vehicle_facts) or f'车辆#{application["vehicle_id"]}'))
    elif application['no_vehicle_required']:
        exception_reason = str(application['vehicle_exception_reason'] or '').strip()
        parts.append('无车例外' + (f'：{exception_reason}' if exception_reason else ''))

    start_at = str(application['start_at'] or '').strip()
    end_at = str(application['end_at'] or '').strip()
    if start_at and end_at:
        parts.append(f'使用时段：{start_at} 至 {end_at}')
    elif start_at:
        parts.append(f'开始时间：{start_at}')
    elif end_at:
        parts.append(f'结束时间：{end_at}')
    destination = str(application['destination'] or '').strip()
    if destination:
        parts.append(f'目的地：{destination}')

    application_id = application['id']
    dedupe_key = f'vehicle_application:{application_id}'
    for user_id in _vehicle_application_admin_ids(db):
        _upsert_unread_notification(
            db, user_id, 'vehicle_application', application_id,
            '用车申请待审核', '；'.join(parts), dedupe_key=dedupe_key,
        )


def _archive_vehicle_application_notifications(db, application_id):
    """Archive, but never delete, all unread review reminders for an application."""
    if not (_table_exists(db, 'notifications')
            and _table_has_column(db, 'notifications', 'is_read')):
        return 0
    updated = db.execute("""UPDATE notifications SET is_read=1
        WHERE source_type='vehicle_application' AND source_id=? AND is_read=0""",
                         (application_id,))
    return updated.rowcount


@app.route('/api/vehicle/applications', methods=['GET'])
@login_required
def api_vehicle_applications():
    """用车申请列表"""
    status = request.args.get('status')
    applicant_id = request.args.get('applicant_id', type=int)
    application_id_raw = request.args.get('application_id')
    application_id = None
    if application_id_raw is not None:
        try:
            application_id = int(application_id_raw)
        except (TypeError, ValueError):
            return jsonify({'error': '用车申请编号参数无效', 'code': 'VEHICLE_APPLICATION_ID_INVALID'}), 400
        if application_id <= 0 or str(application_id).strip() != str(application_id_raw).strip():
            return jsonify({'error': '用车申请编号参数无效', 'code': 'VEHICLE_APPLICATION_ID_INVALID'}), 400
    scope = request.args.get('scope', 'all')
    if scope not in ('all', 'current', 'history'):
        return jsonify({'error': '用车申请范围参数无效'}), 400
    page, limit, pagination_error = _pagination_args(default_limit=50, max_limit=100)
    if pagination_error:
        return pagination_error
    offset = max(request.args.get('offset', (page - 1) * limit, type=int) or 0, 0)
    with get_db() as db:
        q = '''SELECT va.*, v.plate_no, v.model, u.real_name as applicant_name
               FROM vehicle_applications va
               LEFT JOIN vehicles v ON va.vehicle_id = v.id
               LEFT JOIN users u ON va.applicant_id = u.id WHERE 1=1'''
        count_q = 'SELECT COUNT(*) FROM vehicle_applications va WHERE 1=1'
        params = []
        if application_id is not None:
            q += ' AND va.id=?'; count_q += ' AND va.id=?'; params.append(application_id)
        if status:
            q += ' AND va.status=?'; count_q += ' AND va.status=?'; params.append(status)
        if scope == 'current':
            q += " AND COALESCE(va.status, 'pending') IN ('pending','approved')"
            count_q += " AND COALESCE(va.status, 'pending') IN ('pending','approved')"
        elif scope == 'history':
            q += " AND COALESCE(va.status, 'pending') NOT IN ('pending','approved')"
            count_q += " AND COALESCE(va.status, 'pending') NOT IN ('pending','approved')"
        if _has_any_role(g.current_user, 'admin', 'manager') and applicant_id is not None:
            q += ' AND va.applicant_id=?'; count_q += ' AND va.applicant_id=?'; params.append(applicant_id)
        elif not _has_any_role(g.current_user, 'admin', 'manager'):
            q += ' AND va.applicant_id=?'; count_q += ' AND va.applicant_id=?'; params.append(g.current_user['id'])
        count_params = list(params)
        total = db.execute(count_q, count_params).fetchone()[0]
        q += ' ORDER BY va.created_at DESC, va.id DESC LIMIT ? OFFSET ?'
        params.extend([limit, offset])
        rows = db.execute(q, params).fetchall()
        result = []
        for row in rows:
            item = _vehicle_plan_application_state(db, row)
            _notify_vehicle_expiry(db, item)
            result.append(item)
        db.commit()
        if scope != 'all':
            return jsonify({
                'items': result,
                'total': total,
                'has_more': offset + len(result) < total,
                'page': page,
                'limit': limit,
                'scope': scope,
            })
        return jsonify(result)


@app.route('/api/vehicle/applications', methods=['POST'])
@login_required
def api_vehicle_applications_create():
    """新建用车申请；工单无车执行必须显式登记例外原因。"""
    data = request.get_json() or {}
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权申请用车'}), 403
    vehicle_id_raw = data.get('vehicle_id')
    vehicle_id = None
    if vehicle_id_raw not in (None, ''):
        try:
            vehicle_id = int(vehicle_id_raw)
        except (TypeError, ValueError):
            return jsonify({'error': '车辆参数无效'}), 400
        if vehicle_id <= 0:
            return jsonify({'error': '车辆参数无效'}), 400
    applicant_id = g.current_user['id']
    start_value = _vehicle_application_datetime(data.get('start_at'))
    end_value = _vehicle_application_datetime(data.get('end_at'))
    destination = str(data.get('destination') or '').strip()
    destination_mode = str(data.get('destination_mode') or '').strip()
    if destination_mode not in ('', 'site', 'other'):
        return jsonify({'error': '目的地类型无效'}), 400
    reason = str(data.get('reason') or '').strip()
    site_id_raw = data.get('site_id')
    site_id = None
    if site_id_raw not in (None, ''):
        try:
            site_id = int(site_id_raw)
        except (TypeError, ValueError):
            return jsonify({'error': '站点参数无效'}), 400
        if site_id <= 0:
            return jsonify({'error': '站点参数无效'}), 400
    if destination_mode == 'site' and site_id is None:
        return jsonify({'error': '请选择授权站点'}), 400
    if destination_mode == 'other' and site_id is not None:
        return jsonify({'error': '其他地点不能同时关联站点'}), 400
    work_order_no = str(data.get('work_order_no') or '').strip()
    no_vehicle_required = data.get('no_vehicle_required') in (True, 1, '1', 'true')
    vehicle_exception_reason = (data.get('vehicle_exception_reason') or '').strip()
    idempotency_key = str(data.get('_idempotency_key') or '').strip()
    if len(idempotency_key) > 160:
        return jsonify({'error': '重复提交标识无效'}), 400
    if destination_mode and not idempotency_key:
        return jsonify({'error': '缺少有效的重复提交标识'}), 400

    if not reason:
        return jsonify({'error': '用车事由不能为空'}), 400
    if not vehicle_id:
        if not no_vehicle_required:
            return jsonify({'error': '请选择车辆；如该工单确实无需用车，请登记例外原因'}), 400
        if not work_order_no:
            return jsonify({'error': '无需用车例外只能用于已关联的具体工单'}), 400
        if not vehicle_exception_reason:
            return jsonify({'error': '请填写无需用车的例外原因'}), 400
    elif no_vehicle_required:
        return jsonify({'error': '已选择车辆时不能同时标记为无需用车'}), 400

    # 工单现有入口仍可沿用其既有无时间资源申请；“我的用车”普通申请必须提供完整区间。
    if vehicle_id and not work_order_no:
        if start_value is None or end_value is None:
            return jsonify({'error': '请填写有效的开始和结束时间'}), 400
        if end_value[0] <= start_value[0]:
            return jsonify({'error': '结束时间必须晚于开始时间'}), 400
    start_at = start_value[1] if start_value else None
    end_at = end_value[1] if end_value else None
    if destination_mode == 'other' and vehicle_id and not work_order_no:
        if not destination:
            return jsonify({'error': '请填写其他地点'}), 400
        if len(destination) > 100:
            return jsonify({'error': '其他地点不能超过100字'}), 400

    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': '用车申请正在处理，请稍后重试', 'code': 'VEHICLE_APPLICATION_BUSY'}), 409
        endpoint = 'vehicle-application:create'
        cached = _mobile_idempotency_get(db, idempotency_key, endpoint)
        if cached is not None:
            db.rollback()
            return jsonify(cached)
        if site_id is not None:
            site = db.execute('SELECT id,name FROM sites WHERE id=?', (site_id,)).fetchone()
            if not site:
                db.rollback()
                return jsonify({'error': '站点不存在'}), 404
            allowed_site_ids = _filter_site_ids()
            if allowed_site_ids is not None and site_id not in allowed_site_ids:
                db.rollback()
                return jsonify({'error': '无权将用车申请关联到该站点'}), 403
            destination = site['name']
        if vehicle_id:
            vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (vehicle_id,)).fetchone()
            available, reason_text = _vehicle_can_dispatch(db, vehicle)
            if not available:
                db.rollback()
                return jsonify({'error': f'该车辆不可申请：{reason_text}'}), 409
        # 完整形态（含车辆/时间）才校验时间冲突；极简形态（仅事由）跳过
        if vehicle_id and applicant_id and start_at and end_at:
            conflict = db.execute(
                '''SELECT id FROM vehicle_applications
                   WHERE vehicle_id=? AND status IN ('pending','approved')
                   AND NOT (end_at <= ? OR start_at >= ?)''',
                (vehicle_id, start_at, end_at)).fetchone()
            if conflict:
                db.rollback()
                return jsonify({'error': '车辆时间冲突', 'conflict_id': conflict['id']}), 409
            applicant_conflict = db.execute(
                '''SELECT id FROM vehicle_applications
                   WHERE applicant_id=? AND status IN ('pending','approved')
                   AND NOT (end_at <= ? OR start_at >= ?)''',
                (applicant_id, start_at, end_at)).fetchone()
            if applicant_conflict:
                db.rollback()
                return jsonify({'error': '申请人时间冲突', 'conflict_id': applicant_conflict['id']}), 409

        cur = db.execute(
            '''INSERT INTO vehicle_applications
               (vehicle_id, applicant_id, start_at, end_at, destination, reason, site_id,
                work_order_no, no_vehicle_required, vehicle_exception_reason)
               VALUES (?,?,?,?,?,?,?,?,?,?)''',
            (vehicle_id, applicant_id, start_at, end_at, destination, reason, site_id,
             work_order_no, int(no_vehicle_required), vehicle_exception_reason))
        row = db.execute('SELECT * FROM vehicle_applications WHERE id=?', (cur.lastrowid,)).fetchone()
        response = _decorate_attachment(db, row)
        try:
            _mobile_idempotency_store(db, idempotency_key, endpoint, response)
            _notify_vehicle_application_admins(db, row)
            outbox_ids = _wx_queue_pending_approval(
                db, 'vehicle_application', row['id'], 'pending',
                _vehicle_application_admin_ids(db), applicant_id, '车辆申请',
                reason or destination or f'车辆申请{row["id"]}', f'VEH-{row["id"]}',
                row['created_at'] if 'created_at' in row.keys() and row['created_at'] else datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                site_id=site_id, cycle_key=f'application:{row["id"]}',
                page=_wx_page('/pages/review/view', target_type='vehicle_application',
                              target_id=row['id'], cycle_key=f'application:{row["id"]}'))
            db.commit()
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '用车申请暂未提交成功，请稍后重试',
                'code': 'VEHICLE_APPLICATION_RETRYABLE',
            }), 503
        return jsonify(response), 201


@app.route('/api/inspection-v2/rework-plans/<int:plan_id>/resource-request', methods=['POST'])
@login_required
def api_rework_plan_resource_request(plan_id):
    """Create the replacement vehicle or no-vehicle request for a remediation package."""
    data = request.get_json(silent=True) or {}
    vehicle_id = data.get('vehicle_id')
    no_vehicle_required = data.get('no_vehicle_required') in (True, 1, '1', 'true')
    exception_reason = (data.get('vehicle_exception_reason') or '').strip()
    start_at = data.get('start_at') or datetime.now().strftime('%Y-%m-%d 08:00:00')
    end_at = data.get('end_at') or datetime.now().strftime('%Y-%m-%d 18:00:00')
    if bool(vehicle_id) == bool(no_vehicle_required):
        return jsonify({'error': '请选择整改车辆，或登记有理由的无车例外'}), 400
    if no_vehicle_required and not exception_reason:
        return jsonify({'error': '请填写无车例外原因'}), 400
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': '整改资源申请正在处理，请稍后重试',
                            'code': 'REWORK_RESOURCE_REQUEST_BUSY'}), 409
        plan = db.execute("""SELECT * FROM insp_plans WHERE id=? AND rework_of_plan_id IS NOT NULL""",
                          (plan_id,)).fetchone()
        if not plan:
            db.rollback()
            return jsonify({'error': '整改补检执行包不存在'}), 404
        if not (_has_any_role(g.current_user, 'admin') or plan['assignee_id'] == g.current_user['id']):
            db.rollback()
            return jsonify({'error': '仅整改执行人可以申请资源'}), 403
        if (plan['resource_state'] or 'arrangement_required') != 'arrangement_required':
            db.rollback()
            return jsonify({
                'error': '整改资源申请已提交或已批准，请勿重复申请',
                'code': 'REWORK_RESOURCE_REQUEST_EXISTS',
                'resource_state': plan['resource_state'],
            }), 409
        if vehicle_id:
            vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (vehicle_id,)).fetchone()
            available, reason_text = _vehicle_can_dispatch(db, vehicle)
            if not available:
                db.rollback()
                return jsonify({'error': f'该车辆不可申请：{reason_text}'}), 409
            conflict = db.execute("""SELECT id FROM vehicle_applications
                WHERE vehicle_id=? AND status IN ('pending','approved')
                  AND NOT (end_at <= ? OR start_at >= ?) LIMIT 1""",
                (vehicle_id, start_at, end_at)).fetchone()
            if conflict:
                db.rollback()
                return jsonify({'error': '车辆时间冲突', 'conflict_id': conflict['id']}), 409
        try:
            cur = db.execute("""INSERT INTO vehicle_applications
                (vehicle_id, applicant_id, start_at, end_at, destination, reason, status,
                 no_vehicle_required, vehicle_exception_reason, rework_plan_id)
                VALUES (?,?,?,?,?,?,?,?,?,?)""", (
                    vehicle_id, plan['assignee_id'], start_at, end_at, '整改补检',
                    f'整改补检#{plan_id}用车', 'pending', int(no_vehicle_required),
                    exception_reason, plan_id))
            db.execute("UPDATE insp_plans SET resource_state='pending_approval' WHERE id=?", (plan_id,))
            application = db.execute(
                'SELECT * FROM vehicle_applications WHERE id=?', (cur.lastrowid,)
            ).fetchone()
            _notify_vehicle_application_admins(db, application)
            outbox_ids = _wx_queue_pending_approval(
                db, 'vehicle_application', application['id'], 'pending',
                _vehicle_application_admin_ids(db), plan['assignee_id'], '车辆申请',
                f'整改补检#{plan_id}用车', f'VEH-{application["id"]}',
                application['created_at'] if 'created_at' in application.keys() and application['created_at'] else datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                site_id=plan['site_id'] if 'site_id' in plan.keys() else None,
                cycle_key=f'application:{application["id"]}',
                page=_wx_page('/pages/review/view', target_type='vehicle_application',
                              target_id=application['id'], cycle_key=f'application:{application["id"]}'))
            db.commit()
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '整改资源申请暂未提交成功，请稍后重试',
                'code': 'REWORK_RESOURCE_REQUEST_RETRYABLE',
            }), 503
        return jsonify({'success': True, 'rework_plan_id': plan_id,
                        'resource_state': 'pending_approval', 'application': dict(application)}), 201


@app.route('/api/vehicle/applications/<int:app_id>/approve', methods=['POST'])
@login_required
def api_vehicle_application_approve(app_id):
    """主管审批用车申请"""
    denied = require_approver()
    if denied: return denied
    data = request.get_json() or {}
    action = data.get('action', 'approve')
    approver_id = g.current_user['id']
    reject_reason = data.get('reject_reason', '')
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    if action not in ('approve', 'reject'):
        return jsonify({'error': '无效的审批动作'}), 400
    status = 'approved' if action == 'approve' else 'rejected'
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': 'Vehicle approval is busy; refresh and retry.',
                            'code': 'VEHICLE_APPROVAL_BUSY'}), 409
        app_row = db.execute('SELECT * FROM vehicle_applications WHERE id=?', (app_id,)).fetchone()
        if not app_row:
            db.rollback()
            return jsonify({'error': '申请不存在'}), 404
        if app_row['status'] != 'pending':
            db.rollback()
            return jsonify({'error': '该申请已处理', 'code': 'VEHICLE_APPROVAL_STALE'}), 409
        if status == 'approved' and app_row['vehicle_id']:
            vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (app_row['vehicle_id'],)).fetchone()
            available, reason_text = _vehicle_can_dispatch(db, vehicle)
            if not available:
                db.rollback()
                return jsonify({'error': f'该车辆不可批准：{reason_text}'}), 409
            if app_row['start_at'] and app_row['end_at']:
                vehicle_conflict = db.execute("""SELECT id FROM vehicle_applications
                    WHERE vehicle_id=? AND id!=? AND status IN ('pending','approved')
                      AND start_at IS NOT NULL AND end_at IS NOT NULL
                      AND NOT (end_at<=? OR start_at>=?) LIMIT 1""",
                    (app_row['vehicle_id'], app_id, app_row['start_at'], app_row['end_at'])).fetchone()
                applicant_conflict = db.execute("""SELECT id FROM vehicle_applications
                    WHERE applicant_id=? AND id!=? AND status IN ('pending','approved')
                      AND start_at IS NOT NULL AND end_at IS NOT NULL
                      AND NOT (end_at<=? OR start_at>=?) LIMIT 1""",
                    (app_row['applicant_id'], app_id, app_row['start_at'], app_row['end_at'])).fetchone()
                if vehicle_conflict or applicant_conflict:
                    db.rollback()
                    return jsonify({
                        'error': 'Vehicle application conflicts with a current arrangement.',
                        'code': 'VEHICLE_APPROVAL_REVALIDATION_FAILED',
                        'conflict_id': (vehicle_conflict or applicant_conflict)['id'],
                    }), 409
        transitioned = db.execute(
            "UPDATE vehicle_applications SET status=?, approver_id=?, approved_at=?, reject_reason=? WHERE id=? AND status='pending'",
            (status, approver_id, now, reject_reason, app_id))
        if not transitioned.rowcount:
            db.rollback()
            return jsonify({'error': 'Vehicle application state changed; refresh and retry.',
                            'code': 'VEHICLE_APPROVAL_STALE'}), 409
        if (_table_has_column(db, 'vehicle_applications', 'rework_plan_id')
                and app_row['rework_plan_id']):
            db.execute("""UPDATE insp_plans SET resource_state=? WHERE id=?
                AND rework_of_plan_id IS NOT NULL""",
                ('ready' if status == 'approved' else 'arrangement_required', app_row['rework_plan_id']))
        try:
            _archive_vehicle_application_notifications(db, app_id)
            result_notice_id = _upsert_unread_notification(
                db, app_row['applicant_id'], 'vehicle_application_result', app_id,
                '车辆申请已通过' if status == 'approved' else '车辆申请被退回',
                '请按安排用车' if status == 'approved' else (reject_reason or '请修改后重新申请'),
                dedupe_key=f'vehicle_application_result:{app_id}:{status}')
            result_id = _wx_queue_approval_result(
                db, 'vehicle_application', app_id, status, app_row['applicant_id'],
                '车辆申请', app_row['reason'] or app_row['destination'] or f'车辆申请{app_id}',
                '已通过' if status == 'approved' else '已退回', now,
                '请按安排用车' if status == 'approved' else (reject_reason or '请修改后重新申请'),
                cycle_key=f'application:{app_id}',
                page=_wx_page('/pages/vehicle/vehicle', application_id=app_id,
                              source='approval_result', notification_id=result_notice_id))
            db.commit()
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '用车申请审批暂未完成，请稍后重试',
                'code': 'VEHICLE_APPROVAL_RETRYABLE',
            }), 503
        row = db.execute('SELECT * FROM vehicle_applications WHERE id=?', (app_id,)).fetchone()
        if not row:
            return jsonify({'error': '申请不存在'}), 404
        return jsonify(_decorate_attachment(db, row))


@app.route('/api/vehicle/applications/<int:app_id>/extend', methods=['POST'])
@login_required
def api_vehicle_application_extend(app_id):
    """延续尚未闭环巡检计划的车辆占用截止日期。"""
    data = request.get_json(silent=True) or {}
    end_date = str(data.get('end_date') or '')[:10]
    try:
        parsed_end = datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        return jsonify({'error': '请选择有效的延续截止日期'}), 400
    if parsed_end.date() < datetime.now().date():
        return jsonify({'error': '延续截止日期不能早于今天'}), 400
    new_end_at = parsed_end.strftime('%Y-%m-%d') + ' 18:00:00'
    with get_db() as db:
        application = db.execute('SELECT * FROM vehicle_applications WHERE id=?', (app_id,)).fetchone()
        if not application:
            return jsonify({'error': '用车安排不存在'}), 404
        if not _vehicle_user_can_operate(application, g.current_user):
            return jsonify({'error': '仅申请人或管理者可以延续用车安排'}), 403
        if application['status'] != 'approved' or not application['vehicle_id']:
            return jsonify({'error': '仅已批准且已指定车辆的安排可以延续'}), 409
        schedule_id = _vehicle_application_schedule_id(db, application)
        if not schedule_id:
            return jsonify({'error': '只有巡检计划车辆安排可以从此入口延续'}), 409
        if not _plan_schedule_has_open_execution(db, schedule_id):
            return jsonify({'error': '关联巡检计划已闭环，无需延续车辆安排'}), 409
        current_end_at = str(application['end_at'] or '')
        if current_end_at and new_end_at <= current_end_at:
            return jsonify({'error': '新的截止时间必须晚于当前安排'}), 400
        conflict = db.execute("""SELECT id FROM vehicle_applications
            WHERE vehicle_id=? AND id!=? AND status IN ('pending','approved')
              AND start_at IS NOT NULL AND end_at IS NOT NULL
              AND datetime(start_at)<datetime(?) AND datetime(end_at)>datetime(?)
            ORDER BY id LIMIT 1""",
            (application['vehicle_id'], app_id, new_end_at, current_end_at)).fetchone()
        if conflict:
            return jsonify({'error': '延续时段与其他用车安排冲突', 'conflict_id': conflict['id']}), 409
        applicant_conflict = db.execute("""SELECT id FROM vehicle_applications
            WHERE applicant_id=? AND id!=? AND status IN ('pending','approved')
              AND start_at IS NOT NULL AND end_at IS NOT NULL
              AND datetime(start_at)<datetime(?) AND datetime(end_at)>datetime(?)
            ORDER BY id LIMIT 1""",
            (application['applicant_id'], app_id, new_end_at, current_end_at)).fetchone()
        if applicant_conflict:
            return jsonify({'error': '延续时段与申请人的其他用车安排冲突',
                            'conflict_id': applicant_conflict['id']}), 409
        db.execute('UPDATE vehicle_applications SET end_at=? WHERE id=?', (new_end_at, app_id))
        try:
            db.execute("""UPDATE notifications SET is_read=1
                WHERE user_id=? AND source_type='vehicle_use_expiry' AND source_id=?""",
                (application['applicant_id'], app_id))
        except sqlite3.OperationalError:
            pass
        db.commit()
        row = db.execute("""SELECT va.*, v.plate_no, v.model
            FROM vehicle_applications va LEFT JOIN vehicles v ON v.id=va.vehicle_id
            WHERE va.id=?""", (app_id,)).fetchone()
        return jsonify(_vehicle_plan_application_state(db, row))


# ---------- 1.3 出车/还车 ----------
@app.route('/api/vehicle/use-records', methods=['GET', 'POST'])
@login_required
def api_vehicle_use_records():
    """出车/还车记录列表（GET）或出车登记（POST）"""
    if request.method == 'GET':
        vehicle_id = request.args.get('vehicle_id', type=int)
        applicant_id = request.args.get('applicant_id', type=int)
        scope = request.args.get('scope', 'all')
        if scope not in ('all', 'current', 'history'):
            return jsonify({'error': '车辆行程范围参数无效'}), 400
        page, limit, pagination_error = _pagination_args(default_limit=100, max_limit=200)
        if pagination_error:
            return pagination_error
        offset = max(request.args.get('offset', (page - 1) * limit, type=int) or 0, 0)
        with get_db() as db:
            q = '''SELECT r.*, v.id AS vehicle_id, v.plate_no, v.model, v.fuel_type, v.status AS vehicle_status, va.applicant_id, va.start_at, va.end_at, va.destination, va.reason,
                          u.real_name as applicant_name
                   FROM vehicle_use_records r
                   JOIN vehicle_applications va ON r.application_id = va.id
                   JOIN vehicles v ON va.vehicle_id = v.id
                   LEFT JOIN users u ON va.applicant_id = u.id
                   WHERE 1=1'''
            count_q = '''SELECT COUNT(*) FROM vehicle_use_records r
                         JOIN vehicle_applications va ON r.application_id = va.id
                         JOIN vehicles v ON va.vehicle_id = v.id
                         WHERE 1=1'''
            params = []
            if _has_any_role(g.current_user, 'admin', 'manager') and applicant_id is not None:
                q += ' AND va.applicant_id=?'; count_q += ' AND va.applicant_id=?'; params.append(applicant_id)
            elif not _has_any_role(g.current_user, 'admin', 'manager'):
                q += ' AND va.applicant_id=?'; count_q += ' AND va.applicant_id=?'; params.append(g.current_user['id'])
            if vehicle_id:
                q += ' AND v.id=?'; count_q += ' AND v.id=?'; params.append(vehicle_id)
            if scope == 'current':
                q += " AND r.returned_at IS NULL AND COALESCE(r.status, 'checked_out')!='returned'"
                count_q += " AND r.returned_at IS NULL AND COALESCE(r.status, 'checked_out')!='returned'"
                order_sql = ' ORDER BY r.checked_out_at DESC, r.id DESC'
            elif scope == 'history':
                q += " AND (r.returned_at IS NOT NULL OR r.status='returned')"
                count_q += " AND (r.returned_at IS NOT NULL OR r.status='returned')"
                order_sql = ' ORDER BY COALESCE(r.returned_at, r.checked_out_at) DESC, r.id DESC'
            else:
                order_sql = ' ORDER BY r.id DESC'
            count_params = list(params)
            total = db.execute(count_q, count_params).fetchone()[0]
            q += order_sql + ' LIMIT ? OFFSET ?'
            params.extend([limit, offset])
            rows = db.execute(q, params).fetchall()
            result = []
            for row in rows:
                item = dict(row)
                match = re.search(r'巡检计划#(\d+)', str(item.get('reason') or ''))
                item['plan_schedule_id'] = int(match.group(1)) if match else None
                item = _vehicle_plan_use_state(db, item)
                _notify_vehicle_expiry(db, item)
                result.append(item)
            db.commit()
            if scope != 'all':
                return jsonify({
                    'items': result,
                    'total': total,
                    'has_more': offset + len(result) < total,
                    'page': page,
                    'limit': limit,
                    'scope': scope,
                })
            return jsonify(result)

    data = request.get_json() or {}
    application_id = data.get('application_id')
    idempotency_key = str(data.get('_idempotency_key') or '').strip()
    start_mileage = data.get('start_mileage')
    try:
        start_mileage = float(start_mileage)
    except (TypeError, ValueError):
        return jsonify({'error': '请填写有效的出车里程'}), 400
    with get_db() as db:
        endpoint = 'vehicle-checkout:' + str(application_id or '')
        cached = _mobile_idempotency_get(db, idempotency_key, endpoint)
        if cached is not None:
            return jsonify(cached)
        application = db.execute('SELECT * FROM vehicle_applications WHERE id=?', (application_id,)).fetchone()
        if not application:
            return jsonify({'error': '用车申请不存在'}), 404
        if not _vehicle_user_can_operate(application, g.current_user):
            return jsonify({'error': '仅申请人或管理者可以出车'}), 403
        if application['status'] != 'approved' or not application['vehicle_id']:
            return jsonify({'error': '仅已批准且已指定车辆的申请可以出车'}), 409
        application_state = _vehicle_plan_application_state(db, application)
        if application_state['needs_extension']:
            return jsonify({
                'error': '该巡检计划的用车安排已超期，请先变更计划并延续用车时间',
                'code': 'VEHICLE_ARRANGEMENT_EXTENSION_REQUIRED',
                'plan_schedule_id': application_state['plan_schedule_id'],
            }), 409
        if db.execute('SELECT id FROM vehicle_use_records WHERE application_id=?', (application_id,)).fetchone():
            return jsonify({'error': '该申请已完成出车登记，不能重复登记'}), 409
        vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (application['vehicle_id'],)).fetchone()
        dispatchable, reason_text = _vehicle_can_dispatch(db, vehicle, exclude_application_id=application_id)
        if not dispatchable or vehicle['status'] == 'in_use':
            return jsonify({'error': f'车辆当前不可出车：{reason_text or "车辆正在使用"}'}), 409
        if start_mileage < float(vehicle['current_mileage'] or 0):
            return jsonify({'error': '出车里程不能小于车辆当前里程'}), 400
        inspection_id = data.get('out_inspection_id')
        if not inspection_id:
            return jsonify({'error': '出车前须提交车辆检查'}), 400
        inspection = db.execute('''SELECT * FROM vehicle_inspections
                                   WHERE id=? AND vehicle_id=? AND inspection_type='dispatch' ''',
                                (inspection_id, vehicle['id'])).fetchone()
        if not inspection:
            return jsonify({'error': '未找到本次出车前检查记录'}), 400
        if inspection['overall_status'] == 'blocked':
            return jsonify({'error': '出车前检查为不合格，车辆已限制使用'}), 409
        cur = db.execute(
            '''INSERT INTO vehicle_use_records (application_id, start_mileage, checked_out_at, status,
                                                out_inspection_id, checkout_operator_id)
               VALUES (?,?,datetime('now','localtime'),'checked_out',?,?)''',
            (application_id, start_mileage, inspection_id, g.current_user['id']))
        db.execute('UPDATE vehicles SET status="in_use" WHERE id=(SELECT vehicle_id FROM vehicle_applications WHERE id=?)', (application_id,))
        response = {'id': cur.lastrowid}
        _mobile_idempotency_store(db, idempotency_key, endpoint, response)
        db.commit()
        return jsonify(response), 201


@app.route('/api/vehicle/use-records/<int:rec_id>/return', methods=['POST'])
@login_required
def api_vehicle_use_record_return(rec_id):
    """还车登记"""
    data = request.get_json() or {}
    idempotency_key = str(data.get('_idempotency_key') or '').strip()
    end_mileage = data.get('end_mileage')
    try:
        end_mileage = float(end_mileage)
    except (TypeError, ValueError):
        return jsonify({'error': '请填写有效的还车里程'}), 400
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    with get_db() as db:
        endpoint = 'vehicle-return:' + str(rec_id)
        cached = _mobile_idempotency_get(db, idempotency_key, endpoint)
        if cached is not None:
            return jsonify(cached)
        rec = db.execute('''SELECT r.*, va.vehicle_id, va.applicant_id, va.end_at, va.reason,
                            v.status AS vehicle_status FROM vehicle_use_records r
                            JOIN vehicle_applications va ON va.id=r.application_id
                            JOIN vehicles v ON v.id=va.vehicle_id WHERE r.id=?''', (rec_id,)).fetchone()
        if not rec:
            return jsonify({'error': '出车记录不存在'}), 404
        if not _vehicle_user_can_operate(rec, g.current_user):
            return jsonify({'error': '仅申请人或管理者可以还车'}), 403
        if rec['returned_at']:
            return jsonify({'error': '该车辆已经归还'}), 409
        # 巡检排程的同车多站/多日安排是一段行程，不能在中途被任意入口提前归档。
        # 车辆已因故障受限时保留安全还车的例外，其他突发情况应先走计划变更。
        use_state = _vehicle_plan_use_state(db, rec)
        trip_end = str(rec['end_at'] or '')[:10]
        is_plan_trip = '巡检计划#' in str(rec['reason'] or '')
        if (is_plan_trip and not use_state['plan_completed']
                and not use_state['plan_vehicle_replaced']
                and rec['vehicle_status'] != 'restricted'):
            return jsonify({'error': '本巡检计划行程尚未结束；如需提前结束，请先发起计划变更'}), 409
        if end_mileage < float(rec['start_mileage'] or 0):
            return jsonify({'error': '还车里程不能小于出车里程'}), 400
        inspection_id = data.get('return_inspection_id')
        if not inspection_id:
            return jsonify({'error': '还车时须提交车辆检查'}), 400
        inspection = db.execute('''SELECT * FROM vehicle_inspections
                                   WHERE id=? AND vehicle_id=? AND inspection_type='return' ''',
                                (inspection_id, rec['vehicle_id'])).fetchone()
        if not inspection:
            return jsonify({'error': '未找到本次还车检查记录'}), 400
        vehicle = db.execute('SELECT status FROM vehicles WHERE id=?', (rec['vehicle_id'],)).fetchone()
        # 行程中已上报的故障会把车辆置为 restricted；正常还车检查不能清掉这项限制。
        next_status = 'restricted' if inspection['overall_status'] == 'blocked' or (vehicle and vehicle['status'] == 'restricted') else 'idle'
        db.execute('''UPDATE vehicle_use_records SET end_mileage=?, returned_at=?, status='returned',
                      return_inspection_id=?, return_operator_id=? WHERE id=?''',
                   (end_mileage, now, inspection_id, g.current_user['id'], rec_id))
        # The application is the reservation state; returning the car must release it
        # as well, otherwise completed trips remain in personal active-work counters.
        db.execute("UPDATE vehicle_applications SET status='returned' WHERE id=? AND status='approved'",
                   (rec['application_id'],))
        db.execute('UPDATE vehicles SET status=?, current_mileage=? WHERE id=?',
                   (next_status, end_mileage, rec['vehicle_id']))
        response = {'ok': True, 'vehicle_status': next_status}
        _mobile_idempotency_store(db, idempotency_key, endpoint, response)
        db.commit()
        return jsonify(response)


def _mobile_active_vehicle_use(db, rec_id, user):
    rec = db.execute('''SELECT r.*, va.vehicle_id, va.applicant_id
                        FROM vehicle_use_records r
                        JOIN vehicle_applications va ON va.id=r.application_id
                        WHERE r.id=?''', (rec_id,)).fetchone()
    if not rec:
        return None, (jsonify({'error': '出车记录不存在'}), 404)
    if not _vehicle_user_can_operate(rec, user):
        return None, (jsonify({'error': '只能操作自己的用车记录'}), 403)
    if rec['returned_at'] or rec['status'] == 'returned':
        return None, (jsonify({'error': '车辆已归还，不能再补记途中事项'}), 409)
    return rec, None


@app.route('/api/mobile/vehicle-use-records/<int:rec_id>/refueling', methods=['POST'])
@login_required
def mobile_vehicle_use_refueling(rec_id):
    """将途中补给绑定到本人当前未归还的用车行程。"""
    data = request.get_json(silent=True) or {}
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权登记途中补给'}), 403
    idempotency_key = str(data.get('_idempotency_key') or '').strip()
    if not idempotency_key or len(idempotency_key) > 160:
        return jsonify({'error': '缺少有效的重复提交标识'}), 400
    try:
        quantity = float(data.get('energy_quantity', data.get('liters')))
        mileage_at = float(data.get('mileage_at'))
        amount = float(data.get('amount'))
    except (TypeError, ValueError):
        return jsonify({'error': '请填写有效的补给量、金额和当前里程'}), 400
    if not all(math.isfinite(value) for value in (quantity, amount, mileage_at)):
        return jsonify({'error': '请填写有效的补给量、金额和当前里程'}), 400
    if quantity <= 0 or amount <= 0 or mileage_at < 0:
        return jsonify({'error': '补给量和金额必须大于0，里程不能为负数'}), 400
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': '途中补给正在处理，请稍后重试', 'code': 'VEHICLE_REFUELING_BUSY'}), 409
        endpoint = f'vehicle-use-refueling:{rec_id}'
        cached = _mobile_idempotency_get(db, idempotency_key, endpoint)
        if cached is not None:
            db.rollback()
            return jsonify(cached)
        rec, error = _mobile_active_vehicle_use(db, rec_id, g.current_user)
        if error:
            db.rollback()
            return error
        if mileage_at < float(rec['start_mileage'] or 0):
            db.rollback()
            return jsonify({'error': '补给里程不能小于本次出车里程'}), 400
        vehicle = db.execute('SELECT fuel_type,status FROM vehicles WHERE id=?', (rec['vehicle_id'],)).fetchone()
        if not vehicle:
            db.rollback()
            return jsonify({'error': '关联车辆不存在'}), 409
        fuel_type = vehicle['fuel_type'] or ''
        energy_unit = 'kWh' if fuel_type == 'electric' else 'L'
        unit_price = round(amount / quantity, 4)
        if not math.isfinite(unit_price):
            db.rollback()
            return jsonify({'error': '补给量或金额超出有效范围'}), 400
        cur = db.execute('''INSERT INTO vehicle_refueling_records
            (vehicle_id, liters, amount, mileage_at, remark, unit_price, operator_id, operator_name, fuel_type, energy_quantity, energy_unit)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)''',
            (rec['vehicle_id'], quantity, amount, mileage_at, (data.get('remark') or '').strip()[:300], unit_price,
             g.current_user['id'], g.current_user.get('real_name') or g.current_user.get('username', ''),
             fuel_type, quantity, energy_unit))
        response = {'ok': True, 'id': cur.lastrowid, 'energy_unit': energy_unit}
        _mobile_idempotency_store(db, idempotency_key, endpoint, response)
        db.commit()
    return jsonify(response), 201


@app.route('/api/mobile/vehicle-use-records/<int:rec_id>/faults', methods=['POST'])
@login_required
def mobile_vehicle_use_fault_report(rec_id):
    """现场故障上报：按明确安全判断决定是否限制车辆。"""
    data = request.get_json(silent=True) or {}
    if not _has_any_role(g.current_user, 'admin', 'operator'):
        return jsonify({'error': '当前角色无权上报车辆故障'}), 403
    idempotency_key = str(data.get('_idempotency_key') or '').strip()
    if not idempotency_key or len(idempotency_key) > 160:
        return jsonify({'error': '缺少有效的重复提交标识'}), 400
    description = (data.get('description') or '').strip()
    if not description:
        return jsonify({'error': '请填写车辆故障说明'}), 400
    affects_safe_operation = data.get('affects_safe_operation')
    if type(affects_safe_operation) is not bool:
        return jsonify({'error': '请选择故障是否影响安全行驶'}), 400
    try:
        mileage_at = float(data.get('mileage_at'))
    except (TypeError, ValueError):
        return jsonify({'error': '请填写有效的故障里程'}), 400
    if not math.isfinite(mileage_at) or mileage_at < 0:
        return jsonify({'error': '请填写有效的故障里程'}), 400
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': '故障上报正在处理，请稍后重试', 'code': 'VEHICLE_FAULT_BUSY'}), 409
        endpoint = f'vehicle-use-fault:{rec_id}'
        cached = _mobile_idempotency_get(db, idempotency_key, endpoint)
        if cached is not None:
            db.rollback()
            return jsonify(cached)
        rec, error = _mobile_active_vehicle_use(db, rec_id, g.current_user)
        if error:
            db.rollback()
            return error
        if mileage_at < float(rec['start_mileage'] or 0):
            db.rollback()
            return jsonify({'error': '故障里程不能小于本次出车里程'}), 400
        vehicle = db.execute('SELECT status FROM vehicles WHERE id=?', (rec['vehicle_id'],)).fetchone()
        if not vehicle:
            db.rollback()
            return jsonify({'error': '关联车辆不存在'}), 409
        cur = db.execute('''INSERT INTO vehicle_maintenance_records
            (vehicle_id, maint_type, mileage_at, items, remark, maint_status, fault_description, affects_safe_operation)
            VALUES (?,?,?,?,?,'open',?,?)''',
            (rec['vehicle_id'], 'fault', mileage_at, (data.get('fault_type') or '现场故障').strip()[:80],
             (data.get('remark') or '').strip()[:300], description[:500], int(affects_safe_operation)))
        if affects_safe_operation:
            db.execute("UPDATE vehicles SET status='restricted' WHERE id=?", (rec['vehicle_id'],))
        actual_vehicle = db.execute('SELECT status FROM vehicles WHERE id=?', (rec['vehicle_id'],)).fetchone()
        response = {
            'ok': True,
            'id': cur.lastrowid,
            'affects_safe_operation': affects_safe_operation,
            'vehicle_status': actual_vehicle['status'],
        }
        _mobile_idempotency_store(db, idempotency_key, endpoint, response)
        db.commit()
    return jsonify(response), 201


# ---------- 1.4 加油 ----------
@app.route('/api/vehicle/refueling', methods=['GET', 'POST'])
@login_required
def api_vehicle_refueling():
    """加油记录列表（GET）或登记加油（POST）"""
    if request.method == 'GET':
        vehicle_id = request.args.get('vehicle_id', type=int)
        with get_db() as db:
            q = '''SELECT r.*, v.plate_no, v.model, v.fuel_type AS vehicle_fuel_type
                     FROM vehicle_refueling_records r
                     JOIN vehicles v ON r.vehicle_id = v.id
                     WHERE 1=1'''
            params = []
            if vehicle_id:
                q += ' AND r.vehicle_id=?'; params.append(vehicle_id)
            q += ' ORDER BY r.refuel_at DESC'
            rows = db.execute(q, params).fetchall()
            return jsonify([dict(r) for r in rows])

    data = request.get_json() or {}
    vehicle_id = data.get('vehicle_id')
    quantity = data.get('energy_quantity', data.get('liters'))
    amount = data.get('amount')
    mileage_at = data.get('mileage_at')
    remark = data.get('remark', '')
    evidence_expected_count = max(0, int(data.get('evidence_expected_count') or 0))
    evidence_status = 'pending' if evidence_expected_count else 'not_required'
    with get_db() as db:
        vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (vehicle_id,)).fetchone()
        if not vehicle:
            return jsonify({'error': '车辆不存在'}), 404
        authoritative_mileage = float(vehicle['current_mileage'] or 0)
        if mileage_at is not None:
            try:
                requested_mileage = float(mileage_at)
            except (TypeError, ValueError):
                return jsonify({'error': '请填写有效的加油里程'}), 400
            if requested_mileage != authoritative_mileage:
                return jsonify({
                    'error': f'当前里程已由车辆台账锁定为 {authoritative_mileage:g} km，请刷新后重试',
                    'code': 'VEHICLE_MILEAGE_MISMATCH',
                }), 409
        mileage_at = authoritative_mileage
        try:
            quantity = float(quantity)
            if quantity <= 0:
                raise ValueError
        except (TypeError, ValueError):
            return jsonify({'error': '请填写有效的加油量和里程'}), 400
        if mileage_at is not None and db.execute(
            'SELECT id FROM vehicle_refueling_records WHERE vehicle_id=? AND mileage_at=? LIMIT 1',
            (vehicle_id, mileage_at),
        ).fetchone():
            return jsonify({
                'error': '该车辆在此里程已登记能源补给，请勿重复提交',
                'code': 'DUPLICATE_VEHICLE_MILEAGE',
            }), 409
        amount_value = float(amount) if amount is not None else None
        unit_price = data.get('unit_price')
        if unit_price is None and amount_value is not None:
            unit_price = round(amount_value / quantity, 4)
        try:
            cur = db.execute(
                '''INSERT INTO vehicle_refueling_records
                   (vehicle_id, liters, amount, mileage_at, remark, unit_price, operator_id, operator_name, fuel_type,
                    energy_quantity, energy_unit, evidence_expected_count, evidence_status)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)''',
                (vehicle_id, quantity, amount_value, mileage_at, remark, unit_price, g.current_user['id'],
                 g.current_user.get('real_name') or g.current_user.get('username', ''), data.get('fuel_type') or vehicle['fuel_type'],
                 quantity, 'kWh' if vehicle['fuel_type'] == 'electric' else 'L', evidence_expected_count, evidence_status))
        except sqlite3.IntegrityError:
            return jsonify({
                'error': '该车辆在此里程已登记能源补给，请勿重复提交',
                'code': 'DUPLICATE_VEHICLE_MILEAGE',
            }), 409
        db.commit()
        rid = cur.lastrowid
        return jsonify({'ok': True, 'id': rid}), 201


# ---------- 1.5 保养 ----------
@app.route('/api/vehicle/maintenance', methods=['GET', 'POST'])
@login_required
def api_vehicle_maintenance():
    """保养记录列表（GET）或登记保养（POST）"""
    if request.method == 'GET':
        vehicle_id = request.args.get('vehicle_id', type=int)
        with get_db() as db:
            q = '''SELECT r.*, v.plate_no, v.model
                     FROM vehicle_maintenance_records r
                     JOIN vehicles v ON r.vehicle_id = v.id
                     WHERE 1=1'''
            params = []
            if vehicle_id:
                q += ' AND r.vehicle_id=?'; params.append(vehicle_id)
            q += ' ORDER BY r.maint_at DESC'
            rows = db.execute(q, params).fetchall()
            return jsonify([dict(r) for r in rows])

    data = request.get_json() or {}
    vehicle_id = data['vehicle_id']
    maint_type = data['maint_type']
    mileage_at = data.get('mileage_at')
    items = data.get('items', '')
    cost = data.get('cost')
    evidence_expected_count = max(0, int(data.get('evidence_expected_count') or 0))
    evidence_status = 'pending' if evidence_expected_count else 'not_required'
    with get_db() as db:
        denied = require_admin()
        if denied: return denied
        vehicle = db.execute('SELECT * FROM vehicles WHERE id=?', (vehicle_id,)).fetchone()
        if not vehicle:
            return jsonify({'error': '车辆不存在'}), 404
        authoritative_mileage = float(vehicle['current_mileage'] or 0)
        if mileage_at is not None:
            try:
                requested_mileage = float(mileage_at)
            except (TypeError, ValueError):
                return jsonify({'error': '请填写有效的维保里程'}), 400
            if requested_mileage != authoritative_mileage:
                return jsonify({
                    'error': f'当前里程已由车辆台账锁定为 {authoritative_mileage:g} km，请刷新后重试',
                    'code': 'VEHICLE_MILEAGE_MISMATCH',
                }), 409
        mileage_at = authoritative_mileage
        if db.execute(
            'SELECT id FROM vehicle_maintenance_records WHERE vehicle_id=? AND mileage_at=? LIMIT 1',
            (vehicle_id, mileage_at),
        ).fetchone():
            return jsonify({
                'error': '该车辆在此里程已登记维保，请勿重复提交',
                'code': 'DUPLICATE_VEHICLE_MILEAGE',
            }), 409
        maint_status = data.get('maint_status', 'completed')
        if maint_status not in ('open', 'in_progress', 'completed'):
            return jsonify({'error': '无效的维保状态'}), 400
        next_maint_mileage = authoritative_mileage + 5000 if maint_status == 'completed' else vehicle['next_maintenance_mileage']
        try:
            cur = db.execute(
                '''INSERT INTO vehicle_maintenance_records
                   (vehicle_id, maint_type, mileage_at, items, cost, next_maint_mileage, remark, maint_status,
                    vendor, expected_return_at, actual_return_at, fault_description,
                    evidence_expected_count, evidence_status)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',
                (vehicle_id, maint_type, mileage_at, items, cost, next_maint_mileage, data.get('remark', ''),
                 maint_status, data.get('vendor', ''), data.get('expected_return_at'),
                 datetime.now().strftime('%Y-%m-%d %H:%M:%S') if maint_status == 'completed' else None,
                 data.get('fault_description', ''), evidence_expected_count, evidence_status))
        except sqlite3.IntegrityError:
            return jsonify({
                'error': '该车辆在此里程已登记维保，请勿重复提交',
                'code': 'DUPLICATE_VEHICLE_MILEAGE',
            }), 409
        if maint_status == 'completed':
            db.execute(
                '''UPDATE vehicles SET last_maintenance_at=datetime('now','localtime'),
                   next_maintenance_mileage=?, status='idle' WHERE id=?''',
                (next_maint_mileage, vehicle_id))
        else:
            db.execute("UPDATE vehicles SET status='maintenance' WHERE id=?", (vehicle_id,))
        db.commit()
        mid = cur.lastrowid
        return jsonify({'ok': True, 'id': mid}), 201


@app.route('/api/vehicle/<record_type>/<int:record_id>/evidence-status', methods=['PUT'])
@login_required
def api_vehicle_evidence_status(record_type, record_id):
    """按真实附件数更新车辆保养/能源记录的证据状态，支持失败后补传。"""
    denied = require_admin()
    if denied:
        return denied
    config = {
        'maintenance': ('vehicle_maintenance_records', '养护记录'),
        'refueling': ('vehicle_refueling_records', '车辆加油'),
    }.get(record_type)
    if not config:
        return jsonify({'error': '不支持的车辆记录类型'}), 400
    table, category = config
    with get_db() as db:
        row = db.execute(
            f'SELECT id, evidence_expected_count FROM {table} WHERE id=?', (record_id,),
        ).fetchone()
        if not row:
            return jsonify({'error': '车辆记录不存在'}), 404
        uploaded = db.execute(
            """SELECT COUNT(*) FROM operation_attachments
               WHERE source_type='vehicle' AND source_id=? AND category=? AND is_deleted=0""",
            (record_id, category),
        ).fetchone()[0]
        expected = int(row['evidence_expected_count'] or 0)
        status = 'not_required' if expected == 0 else 'complete' if uploaded >= expected else 'partial' if uploaded > 0 else 'pending'
        db.execute(f'UPDATE {table} SET evidence_status=? WHERE id=?', (status, record_id))
        db.commit()
    return jsonify({'ok': True, 'evidence_status': status, 'uploaded': uploaded, 'expected': expected})


# ---------- 4.1 周巡检计划 ----------
@app.route('/api/weekly-plans', methods=['GET'])
def api_weekly_plans():
    """周计划列表，可按用户/周筛选"""
    user_id = request.args.get('user_id')
    week_start = request.args.get('week_start')
    status = request.args.get('status')
    with get_db() as db:
        q = '''SELECT wp.*, u.real_name as user_name, approver.real_name as approver_name
               FROM weekly_inspection_plans wp
               LEFT JOIN users u ON wp.user_id = u.id
               LEFT JOIN users approver ON wp.approver_id = approver.id WHERE 1=1'''
        params = []
        if user_id:
            q += ' AND wp.user_id=?'; params.append(user_id)
        if week_start:
            q += ' AND wp.week_start=?'; params.append(week_start)
        if status:
            q += ' AND wp.status=?'; params.append(status)
        q += ' ORDER BY wp.week_start DESC'
        rows = []
        for row in db.execute(q, params).fetchall():
            item = dict(row)
            try:
                import json as _json
                item['plan_data'] = _json.loads(item['plan_data']) if item.get('plan_data') else {}
            except:
                pass
            rows.append(item)
        return jsonify(rows)


@app.route('/api/weekly-plans', methods=['POST'])
def api_weekly_plans_create():
    """新建/提交周计划"""
    data = request.get_json(silent=True) or {}
    current_user = g.current_user
    try:
        user_id = int(data['user_id'])
    except (KeyError, TypeError, ValueError):
        return jsonify({'error': '缺少有效的 user_id'}), 400
    if not _has_any_role(current_user, 'admin') and user_id != int(current_user['id']):
        return jsonify({'error': '只能为自己创建周计划'}), 403
    week_start = data.get('week_start')
    if not week_start:
        return jsonify({'error': '缺少 week_start'}), 400
    plan_data = data.get('plan_data', {})
    if not isinstance(plan_data, dict):
        return jsonify({'error': 'plan_data 格式无效'}), 400
    normalized_plan_data = {}
    for day, raw_site_ids in plan_data.items():
        site_ids, denied = _authorized_site_ids(raw_site_ids, '创建巡检计划涉及')
        if denied:
            return denied
        normalized_plan_data[day] = site_ids
    plan_data = normalized_plan_data
    vehicle_id = data.get('vehicle_id')
    submit = data.get('submit', False)
    remarks = data.get('remarks', '')

    import json as _json
    plan_json = _json.dumps(plan_data, ensure_ascii=False) if isinstance(plan_data, dict) else plan_data

    status = 'submitted' if submit else 'draft'
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    with get_db() as db:
        cur = db.execute(
            '''INSERT INTO weekly_inspection_plans (user_id, week_start, plan_data, vehicle_id, status, remarks, submitted_at)
               VALUES (?,?,?,?,?,?,?)''',
            (user_id, week_start, plan_json, vehicle_id, status, remarks, now if submit else None))
        db.commit()
        # 如果勾选了车辆且提交，自动创建用车申请
        if submit and vehicle_id:
            for day, site_ids in plan_data.items():
                if site_ids and isinstance(site_ids, list) and len(site_ids) > 0:
                    # 简单处理：为整周创建一条用车申请
                    db.execute(
                        '''INSERT INTO vehicle_applications (vehicle_id, applicant_id, start_at, end_at, destination, reason, status)
                           VALUES (?,?,?,?,?,"周巡检用车","approved")''',
                        (vehicle_id, user_id, week_start + ' 08:00:00', week_start + ' 18:00:00', '巡检'))
                    break
        db.commit()
        row = db.execute('SELECT * FROM weekly_inspection_plans WHERE id=?', (cur.lastrowid,)).fetchone()
        r = dict(row)
        try: r['plan_data'] = _json.loads(r['plan_data']) if r.get('plan_data') else {}
        except: pass
        return jsonify(r), 201


@app.route('/api/weekly-plans/<int:plan_id>/approve', methods=['POST'])
def api_weekly_plan_approve(plan_id):
    """主管审批周计划"""
    data = request.get_json() or {}
    approver_id = g.current_user.get('id')
    action = data.get('action', 'approve')
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    if action == 'submit':
        status = 'submitted'
        with get_db() as db:
            db.execute(
                'UPDATE weekly_inspection_plans SET status=?, submitted_at=? WHERE id=?',
                (status, now, plan_id))
            db.commit()
        return jsonify({'ok': True, 'status': status})
    status = 'approved' if action == 'approve' else ('rejected' if action == 'reject' else 'draft')
    with get_db() as db:
        db.execute(
            'UPDATE weekly_inspection_plans SET status=?, approver_id=?, approved_at=? WHERE id=?',
            (status, approver_id, now if action == 'approve' else None, plan_id))
        db.commit()
        return jsonify({'ok': True, 'status': status})


# ===================== 巡检计划调度层（周/月/季/年统一） =====================
# 设计依据：《巡检计划体系设计》——调度层（排程+资源协调+审核）
# plan_schedules 为调度层计划；审批通过后生成 insp_plans/insp_plan_items（执行层）。
# 注：表名不叫 inspection_schedules（该名已被"检查项到期排程"表占用）。

_PS_FREQ_CN = {'weekly': '周检', 'monthly': '月检', 'quarterly': '季检', 'yearly': '年检'}
_PS_EDITABLE = ('draft', 'rejected')  # 仅这两个状态可编辑/重新提交


def _ps_parse_row(row):
    """plan_schedules 行 → dict，解析 JSON 字段"""
    r = dict(row)
    for f, empty in (('plan_data', {}), ('vehicle_days', {}), ('spare_parts', []),
                     ('work_order_ids', []), ('previous_plan_data', None),
                     ('previous_vehicle_days', None), ('previous_spare_parts', None),
                     ('previous_work_order_ids', None)):
        v = r.get(f)
        if v:
            try:
                r[f] = json.loads(v)
            except Exception:
                r[f] = empty if empty is not None else v
        else:
            r[f] = empty if empty is not None else None
    # New plans may store one plan-level vehicle; expose it while preserving
    # legacy per-day vehicle_days for existing schedules and execution packages.
    if r.get('vehicle_id') in ('', 0):
        r['vehicle_id'] = None
    if r.get('vehicle_id') is None and r.get('vehicle_days'):
        values = {str(v) for v in r['vehicle_days'].values() if v not in (None, '')}
        if len(values) == 1:
            try:
                r['vehicle_id'] = int(next(iter(values)))
            except (TypeError, ValueError):
                r['vehicle_id'] = None
    r['no_vehicle_required'] = bool(r.get('no_vehicle_required'))
    return r


def _ensure_plan_schedule_vehicle_column(db):
    """Ensure the explicit plan vehicle contract is available."""
    if not _table_exists(db, 'plan_schedules'):
        return False
    try:
        if not _table_has_column(db, 'plan_schedules', 'vehicle_id'):
            db.execute('ALTER TABLE plan_schedules ADD COLUMN vehicle_id INTEGER')
        if not _table_has_column(db, 'plan_schedules', 'no_vehicle_required'):
            db.execute('ALTER TABLE plan_schedules ADD COLUMN no_vehicle_required INTEGER NOT NULL DEFAULT 0')
            # One-time compatibility for records created before the explicit choice existed.
            db.execute("""UPDATE plan_schedules SET no_vehicle_required=1
                WHERE vehicle_id IS NULL AND COALESCE(vehicle_days,'{}') IN ('','{}')""")
        if not _table_has_column(db, 'plan_schedules', 'previous_no_vehicle_required'):
            db.execute('ALTER TABLE plan_schedules ADD COLUMN previous_no_vehicle_required INTEGER')
    except sqlite3.OperationalError:
        return False
    return True


def _inspection_field_completion_sql(db, alias=''):
    """Return the shared predicate for an item's current field completion."""
    prefix = f'{alias}.' if alias else ''
    terms = [f"TRIM(COALESCE({prefix}result,''))<>''"]
    if _table_has_column(db, 'insp_plan_items', 'review_status'):
        terms.append(f'COALESCE({prefix}review_status,0)<>3')
    if _table_has_column(db, 'insp_plan_items', 'evidence_status'):
        terms.append(f"COALESCE({prefix}evidence_status,'')<>'supplement_required'")
    return '(' + ' AND '.join(terms) + ')'


def _inspection_active_rework_sql(db, alias=''):
    """Return the current-item predicate for an unresolved field remediation."""
    prefix = f'{alias}.' if alias else ''
    terms = []
    if _table_has_column(db, 'insp_plan_items', 'review_status'):
        terms.append(f'COALESCE({prefix}review_status,0)=3')
    if _table_has_column(db, 'insp_plan_items', 'evidence_status'):
        terms.append(f"COALESCE({prefix}evidence_status,'')='supplement_required'")
    return '(' + ' OR '.join(terms) + ')' if terms else '0'


def _inspection_field_item_completed(item):
    """Apply the current field-completion contract to one sqlite row."""
    keys = set(item.keys())
    return bool(
        str(item['result'] or '').strip() != ''
        and ('review_status' not in keys or int(item['review_status'] or 0) != 3)
        and ('evidence_status' not in keys
             or str(item['evidence_status'] or '') != 'supplement_required')
    )


def _ps_expand_plan_vehicle(plan_data, vehicle_id, vehicle_days):
    """Normalize every writable plan to one vehicle or no vehicle."""
    if vehicle_days is None:
        vehicle_days = {}
    if not isinstance(vehicle_days, dict):
        raise PlanScheduleSiteScopeError('vehicle_days 格式无效', code='PLAN_RESOURCE_DATA_INVALID')
    planned_dates = [
        str(date_str) for date_str, day_data in (plan_data or {}).items()
        if isinstance(day_data, dict) and day_data.get('sites')
    ]
    normalized_id = None
    if vehicle_id not in (None, ''):
        try:
            normalized_id = int(vehicle_id)
        except (TypeError, ValueError):
            raise PlanScheduleSiteScopeError('vehicle_id 无效', code='PLAN_VEHICLE_INVALID')
        if normalized_id <= 0:
            raise PlanScheduleSiteScopeError('vehicle_id 无效', code='PLAN_VEHICLE_INVALID')
    else:
        legacy_ids = set()
        for raw_id in vehicle_days.values():
            if raw_id in (None, ''):
                continue
            try:
                legacy_id = int(raw_id)
            except (TypeError, ValueError):
                raise PlanScheduleSiteScopeError('vehicle_days 包含无效车辆', code='PLAN_VEHICLE_INVALID')
            if legacy_id <= 0:
                raise PlanScheduleSiteScopeError('vehicle_days 包含无效车辆', code='PLAN_VEHICLE_INVALID')
            legacy_ids.add(legacy_id)
        if len(legacy_ids) > 1:
            raise PlanScheduleSiteScopeError(
                '同一巡检计划只能使用一辆车；请选择计划车辆或明确无需用车',
                code='PLAN_MULTIPLE_VEHICLES_NOT_ALLOWED')
        normalized_id = next(iter(legacy_ids), None)
    return {date_str: normalized_id for date_str in planned_dates} if normalized_id else {}


def _ps_plan_vehicle_id(vehicle_days):
    """Return the single normalized vehicle id from daily compatibility data."""
    if not isinstance(vehicle_days, dict):
        raise PlanScheduleSiteScopeError(
            'vehicle_days 格式无效', code='PLAN_RESOURCE_DATA_INVALID')
    values = set()
    for value in vehicle_days.values():
        if value in (None, ''):
            continue
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            raise PlanScheduleSiteScopeError(
                'vehicle_days 包含无效车辆', code='PLAN_VEHICLE_INVALID')
        if parsed <= 0:
            raise PlanScheduleSiteScopeError(
                'vehicle_days 包含无效车辆', code='PLAN_VEHICLE_INVALID')
        values.add(parsed)
    if len(values) > 1:
        raise PlanScheduleSiteScopeError(
            '同一巡检计划只能使用一辆车',
            code='PLAN_MULTIPLE_VEHICLES_NOT_ALLOWED')
    return next(iter(values), None)


def _ps_normalize_vehicle_exception_reason(vehicle_id, raw_reason):
    """Keep the no-vehicle explanation mutually exclusive with a vehicle assignment."""
    return '' if vehicle_id is not None else (raw_reason or '').strip()


def _ps_persisted_vehicle_id(vehicle_days):
    """Reject invalid persisted vehicle state as a state conflict, not a new payload error."""
    try:
        return _ps_plan_vehicle_id(vehicle_days)
    except PlanScheduleSiteScopeError as exc:
        raise PlanScheduleSiteScopeError(
            str(exc), status=409, code=exc.code, site_ids=exc.site_ids) from exc


def _ps_vehicle_reason_like(schedule_id):
    """Match the stable plan vehicle token without #1/#10 prefix collisions."""
    return f'%巡检计划#{int(schedule_id)}用车%'


class PlanScheduleResourceConflict(Exception):
    """Raised when an approval cannot atomically reserve its required vehicle."""


class PlanScheduleSiteScopeError(Exception):
    """Plan data contains a site outside the execution user's explicit scope."""

    def __init__(self, message, *, status=400, code='PLAN_SITE_SCOPE_INVALID', site_ids=None):
        super().__init__(message)
        self.status = status
        self.code = code
        self.site_ids = list(site_ids or [])


def _ps_site_scope_error_response(exc):
    payload = {'error': str(exc), 'code': exc.code}
    if exc.site_ids:
        payload['site_ids'] = exc.site_ids
    return jsonify(payload), exc.status


def _ps_approver_ids(db):
    """Return active administrators using both primary and secondary roles."""
    has_status = _table_has_column(db, 'users', 'status')
    rows = db.execute(
        'SELECT id, role, status FROM users' if has_status
        else 'SELECT id, role, NULL AS status FROM users'
    ).fetchall()
    secondary_roles = {}
    if _table_exists(db, 'user_roles'):
        for role_row in db.execute('SELECT user_id, role FROM user_roles').fetchall():
            secondary_roles.setdefault(role_row['user_id'], []).append(role_row['role'])
    approver_ids = []
    for row in rows:
        if has_status and row['status'] != 'active':
            continue
        roles = _normalize_user_roles(
            [row['role'], *secondary_roles.get(row['id'], [])], row['role'] or 'operator')
        if 'admin' in roles:
            approver_ids.append(row['id'])
    return sorted(set(approver_ids))


def _ps_decode_plan_data(raw_plan_data):
    if isinstance(raw_plan_data, dict):
        return raw_plan_data
    try:
        plan_data = json.loads(raw_plan_data or '{}')
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise PlanScheduleSiteScopeError(
            'Plan site data is invalid', code='PLAN_DATA_INVALID') from exc
    if not isinstance(plan_data, dict):
        raise PlanScheduleSiteScopeError(
            'plan_data must be an object', code='PLAN_DATA_INVALID')
    return plan_data


def _ps_day_has_business_content(day_data):
    if not isinstance(day_data, dict):
        return False
    selections = day_data.get('inspection_items')
    has_selections = isinstance(selections, dict) and any(
        bool(value) for value in selections.values())
    return bool(day_data.get('sites') or str(day_data.get('notes') or '').strip()
                or has_selections)


def _ps_validate_date_contract(period_start, period_end, plan_data, vehicle_days=None):
    """Strictly validate writable plan dates and return out-of-period business dates."""
    start_text, end_text = str(period_start or ''), str(period_end or '')
    try:
        start_date = datetime.strptime(start_text, '%Y-%m-%d').date()
        end_date = datetime.strptime(end_text, '%Y-%m-%d').date()
    except (TypeError, ValueError) as exc:
        raise PlanScheduleSiteScopeError(
            '计划周期日期无效，请使用 YYYY-MM-DD', code='PLAN_PERIOD_INVALID') from exc
    if start_date.isoformat() != start_text or end_date.isoformat() != end_text:
        raise PlanScheduleSiteScopeError(
            '计划周期日期无效，请使用 YYYY-MM-DD', code='PLAN_PERIOD_INVALID')
    if start_date > end_date:
        raise PlanScheduleSiteScopeError(
            '计划周期开始日期不能晚于结束日期', code='PLAN_PERIOD_INVALID')
    vehicle_days = vehicle_days if isinstance(vehicle_days, dict) else {}
    outside = []
    date_keys = set((plan_data or {}).keys()) | set(vehicle_days.keys())
    for raw_date in date_keys:
        day_data = (plan_data or {}).get(raw_date, {})
        date_text = str(raw_date)
        if not (_ps_day_has_business_content(day_data) or vehicle_days.get(raw_date)
                or vehicle_days.get(date_text)):
            continue
        try:
            work_date = datetime.strptime(date_text, '%Y-%m-%d').date()
        except (TypeError, ValueError) as exc:
            raise PlanScheduleSiteScopeError(
                f'执行日期 {date_text} 无效，请使用 YYYY-MM-DD',
                code='PLAN_DATE_INVALID') from exc
        if work_date.isoformat() != date_text:
            raise PlanScheduleSiteScopeError(
                f'执行日期 {date_text} 无效，请使用 YYYY-MM-DD',
                code='PLAN_DATE_INVALID')
        if work_date < start_date or work_date > end_date:
            outside.append(date_text)
    return start_text, end_text, sorted(set(outside))


def _ps_validate_execution_sites(db, user_id, plan_data):
    """Validate and normalize plan sites against the target execution user."""
    try:
        execution_user_id = int(user_id)
    except (TypeError, ValueError):
        raise PlanScheduleSiteScopeError(
            '计划执行人参数无效', code='PLAN_EXECUTION_USER_INVALID')
    if execution_user_id <= 0:
        raise PlanScheduleSiteScopeError(
            '计划执行人参数无效', code='PLAN_EXECUTION_USER_INVALID')

    user_status_column = _table_has_column(db, 'users', 'status')
    execution_user = db.execute(
        "SELECT id, status FROM users WHERE id=?" if user_status_column
        else "SELECT id, NULL AS status FROM users WHERE id=?",
        (execution_user_id,)).fetchone()
    if not execution_user:
        raise PlanScheduleSiteScopeError(
            '计划执行人不存在', status=404, code='PLAN_EXECUTION_USER_NOT_FOUND')
    if user_status_column and execution_user['status'] != 'active':
        raise PlanScheduleSiteScopeError(
            '计划执行人账号不可用', status=409, code='PLAN_EXECUTION_USER_INACTIVE')
    if not isinstance(plan_data, dict):
        raise PlanScheduleSiteScopeError(
            'plan_data 必须是 日期→安排 的对象', code='PLAN_DATA_INVALID')

    normalized = {}
    all_site_ids = []
    for date_str, day_data in plan_data.items():
        if not isinstance(day_data, dict):
            raise PlanScheduleSiteScopeError(
                f'{date_str} 的计划安排必须是对象', code='PLAN_DATA_INVALID')
        raw_site_ids = day_data.get('sites') or []
        if not isinstance(raw_site_ids, list):
            raise PlanScheduleSiteScopeError(
                f'{date_str} 的站点必须是数组', code='PLAN_DATA_INVALID')
        site_ids = []
        for raw_site_id in raw_site_ids:
            try:
                site_id = int(raw_site_id)
            except (TypeError, ValueError):
                raise PlanScheduleSiteScopeError(
                    f'{date_str} 包含无效站点参数', code='PLAN_DATA_INVALID')
            if site_id <= 0:
                raise PlanScheduleSiteScopeError(
                    f'{date_str} 包含无效站点参数', code='PLAN_DATA_INVALID')
            if site_id not in site_ids:
                site_ids.append(site_id)
            if site_id not in all_site_ids:
                all_site_ids.append(site_id)
        normalized[str(date_str)] = {**day_data, 'sites': site_ids}

    if all_site_ids:
        placeholders = ','.join('?' * len(all_site_ids))
        existing = {row['id'] for row in db.execute(
            f'SELECT id FROM sites WHERE id IN ({placeholders})', all_site_ids).fetchall()}
        missing = [site_id for site_id in all_site_ids if site_id not in existing]
        if missing:
            raise PlanScheduleSiteScopeError(
                '计划包含不存在的站点', status=404,
                code='PLAN_SITE_NOT_FOUND', site_ids=missing)

        allowed = {row['site_id'] for row in db.execute(
            'SELECT site_id FROM user_sites WHERE user_id=?', (execution_user_id,)).fetchall()}
        unauthorized = [site_id for site_id in all_site_ids if site_id not in allowed]
        if unauthorized:
            raise PlanScheduleSiteScopeError(
                '计划包含执行人未负责的站点', status=403,
                code='PLAN_EXECUTION_SITE_FORBIDDEN', site_ids=unauthorized)
    return normalized


def _ps_site_template_items(db, site_id, schedule_type, include_weekly_optional=False):
    """Return all active template items for a site's plan frequency.

    This is used only while drafting/generating a new plan. Generated item rows
    remain snapshots and are never rewritten by later template changes.
    """
    try:
        schedule_type = _inspection_frequency(schedule_type)
    except ValueError:
        return []
    site = db.execute('SELECT id FROM sites WHERE id=?', (site_id,)).fetchone()
    if (not site or not _table_exists(db, 'inspection_templates')
            or not _table_exists(db, 'inspection_template_items')):
        return []
    template_columns = {row['name'] for row in db.execute('PRAGMA table_info(inspection_templates)').fetchall()}
    item_columns = {row['name'] for row in db.execute('PRAGMA table_info(inspection_template_items)').fetchall()}
    template_order = 't.sort_order, t.id' if 'sort_order' in template_columns else 't.id'
    item_order = 'iti.sort_order, iti.id' if 'sort_order' in item_columns else 'iti.id'
    item_status = " AND COALESCE(iti.status, 'active')='active'" if 'status' in item_columns else ''
    frequencies = ([schedule_type, 'monthly', 'quarterly']
                   if schedule_type == 'weekly' and include_weekly_optional else [schedule_type])
    frequency_marks = ','.join('?' * len(frequencies))
    rows = db.execute(f"""
        SELECT iti.*,
               CASE WHEN LOWER(COALESCE(t.frequency,''))='annual' THEN 'yearly'
                    ELSE LOWER(COALESCE(t.frequency,'')) END AS template_frequency
        FROM inspection_templates t
        JOIN inspection_template_items iti ON iti.template_id=t.id{item_status}
        WHERE t.status='active'
          AND CASE WHEN LOWER(COALESCE(t.frequency,''))='annual' THEN 'yearly'
                   ELSE LOWER(COALESCE(t.frequency,'')) END IN ({frequency_marks})
        ORDER BY {template_order}, {item_order}
    """, frequencies).fetchall()
    return [dict(row) for row in rows]


def _ps_validate_item_selections(db, plan_data, schedule_type):
    """Validate optional per-site selections against active templates of the frequency."""
    normalized = {}
    for date_str, day_data in (plan_data or {}).items():
        if not isinstance(day_data, dict):
            normalized[str(date_str)] = day_data
            continue
        day = dict(day_data)
        selection_keys = [key for key in ('inspection_items', 'site_items') if key in day]
        if not selection_keys:
            normalized[str(date_str)] = day
            continue
        if len(selection_keys) > 1 and day.get(selection_keys[0]) != day.get(selection_keys[1]):
            raise PlanScheduleSiteScopeError('检查项选择字段不一致', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
        selection_key = selection_keys[0]
        raw_selection = day.get(selection_key)
        if not isinstance(raw_selection, dict):
            raise PlanScheduleSiteScopeError('检查项选择必须按站点填写', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
        canonical = {}
        for raw_site_id, raw_ids in raw_selection.items():
            try:
                site_id = int(raw_site_id)
            except (TypeError, ValueError):
                raise PlanScheduleSiteScopeError('检查项选择包含无效站点', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
            if site_id <= 0 or site_id not in [int(value) for value in (day.get('sites') or [])]:
                raise PlanScheduleSiteScopeError('检查项选择站点不在本日安排中', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
            if not isinstance(raw_ids, list):
                raise PlanScheduleSiteScopeError('检查项选择必须是数组', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
            applicable = _ps_site_template_items(
                db, site_id, schedule_type, include_weekly_optional=(schedule_type == 'weekly'))
            by_id = {int(item['id']): item for item in applicable if item.get('id') is not None}
            ids = []
            for raw_id in raw_ids:
                item_id = None
                if isinstance(raw_id, dict):
                    raw_id = raw_id.get('id', raw_id.get('template_item_id'))
                try:
                    if isinstance(raw_id, bool) or not isinstance(raw_id, (int, str)):
                        raise ValueError('invalid item id')
                    item_id = int(raw_id)
                except (TypeError, ValueError):
                    item_id = None
                if not item_id or item_id not in by_id:
                    raise PlanScheduleSiteScopeError(
                        '检查项不属于当前频次的有效模板', code='PLAN_INSPECTION_ITEM_SELECTION_INVALID',
                        site_ids=[site_id])
                if item_id not in ids:
                    ids.append(item_id)
            canonical[str(site_id)] = ids
        for scheduled_site_id in day.get('sites') or []:
            site_id = int(scheduled_site_id)
            key = str(site_id)
            if key not in canonical:
                canonical[key] = [
                    int(item['id']) for item in _ps_site_template_items(db, site_id, schedule_type)
                    if item.get('id') is not None
                ]
        day['inspection_items'] = canonical
        if selection_key == 'site_items':
            day.pop('site_items', None)
        normalized[str(date_str)] = day
    return normalized


def _ps_prune_vehicle_days(plan_data, vehicle_days, period_start, period_end):
    """Remove vehicle allocations that no longer belong to an arranged plan day."""
    if not isinstance(vehicle_days, dict):
        raise PlanScheduleSiteScopeError(
            'vehicle_days 必须是日期到车辆的对象', code='PLAN_RESOURCE_DATA_INVALID')
    valid_dates = {
        str(date_str) for date_str, day_data in (plan_data or {}).items()
        if str(period_start) <= str(date_str) <= str(period_end)
        and isinstance(day_data, dict) and day_data.get('sites')
    }
    normalized = {}
    pruned_dates = []
    for raw_date, vehicle_id in vehicle_days.items():
        date_str = str(raw_date)
        if date_str not in valid_dates:
            pruned_dates.append(date_str)
            continue
        if vehicle_id not in (None, ''):
            normalized[date_str] = vehicle_id
    return normalized, sorted(set(pruned_dates))


def _ps_execution_completed(db, schedule_id):
    """Return whether every generated execution package completed its field loop."""
    try:
        checkout_condition = ' OR pi.check_out_time IS NULL' if _mobile_checkout_supported(db) else ''
        summary = db.execute(f"""SELECT COUNT(*) AS total,
                SUM(CASE WHEN ip.status!='completed' OR EXISTS (
                    SELECT 1 FROM insp_plan_items pi
                    WHERE pi.plan_id=ip.id
                      AND COALESCE(pi.execution_status, 'active')='active'
                      AND (pi.result IS NULL{checkout_condition})
                ) THEN 1 ELSE 0 END) AS incomplete
            FROM insp_plans ip
            WHERE ip.plan_schedule_id=? AND ip.status!='cancelled'""", (schedule_id,)).fetchone()
    except sqlite3.OperationalError:
        # Narrow legacy schemas may not yet have item/checkout tables. Keep the
        # historical status-only behavior there; migrated schemas use the
        # stronger field-loop predicate above.
        try:
            summary = db.execute("""SELECT COUNT(*) AS total,
                    SUM(CASE WHEN status='completed' THEN 0 ELSE 1 END) AS incomplete
                FROM insp_plans WHERE plan_schedule_id=?""", (schedule_id,)).fetchone()
        except sqlite3.OperationalError:
            return False
    return bool(summary and int(summary['total'] or 0) > 0 and int(summary['incomplete'] or 0) == 0)


def _ps_active_rework_exists(db, schedule_id):
    """Return whether a schedule still owns an active item requiring remediation."""
    if not schedule_id:
        return False
    try:
        rework_sql = _inspection_active_rework_sql(db, 'pi')
        if rework_sql == '0':
            return False
        return bool(db.execute(f"""SELECT 1
            FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id
            WHERE ip.plan_schedule_id=? AND ip.status!='cancelled'
              AND COALESCE(pi.execution_status,'active')='active'
              AND {rework_sql}
            LIMIT 1""", (schedule_id,)).fetchone())
    except sqlite3.OperationalError:
        return False


def _ps_sync_field_status(db, schedule_id):
    """Persist the field-loop state without changing approval lifecycle state."""
    if not schedule_id or not _table_has_column(db, 'plan_schedules', 'field_status'):
        return 'completed' if _ps_execution_completed(db, schedule_id) else 'active'
    row = db.execute("""SELECT field_status FROM plan_schedules WHERE id=?""",
                     (schedule_id,)).fetchone()
    if not row:
        return 'active'
    # Current remediation facts outrank a historical completed flag. This also
    # repairs schedules completed before the review/evidence state was applied.
    if _ps_active_rework_exists(db, schedule_id):
        if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
            db.execute("""UPDATE plan_schedules
                SET field_status='rework', field_completed_at=NULL WHERE id=?""",
                       (schedule_id,))
        else:
            db.execute("UPDATE plan_schedules SET field_status='rework' WHERE id=?",
                       (schedule_id,))
        return 'rework'
    if _ps_execution_completed(db, schedule_id):
        if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
            db.execute("""UPDATE plan_schedules
                SET field_status='completed',
                    field_completed_at=COALESCE(field_completed_at, datetime('now','localtime'))
                WHERE id=?""", (schedule_id,))
        else:
            db.execute("UPDATE plan_schedules SET field_status='completed' WHERE id=?", (schedule_id,))
        return 'completed'
    # No current remediation remains. Do not preserve a stale rework flag after
    # replacement evidence has satisfied the shared completion predicate.
    status = 'active'
    if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
        db.execute("""UPDATE plan_schedules SET field_status=?, field_completed_at=NULL WHERE id=?""",
                   (status, schedule_id))
    else:
        db.execute("UPDATE plan_schedules SET field_status=? WHERE id=?", (status, schedule_id))
    return status


def _ps_mark_field_rework(db, schedule_id):
    """Inspection review code calls this after reopening a completed field loop."""
    if not schedule_id or not _table_has_column(db, 'plan_schedules', 'field_status'):
        return False
    if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
        updated = db.execute("""UPDATE plan_schedules
            SET field_status='rework', field_completed_at=NULL WHERE id=?""", (schedule_id,))
    else:
        updated = db.execute("UPDATE plan_schedules SET field_status='rework' WHERE id=?", (schedule_id,))
    return bool(updated.rowcount)


def _ps_period_overlap(db, user_id, schedule_type, period_start, period_end):
    """Find an unfinished schedule occupying a proposed planning period."""
    sql = """SELECT id, period_start, period_end FROM plan_schedules
        WHERE user_id=? AND schedule_type=? AND status NOT IN ('rejected','archived','cancelled')
          AND period_start<=? AND period_end>=?"""
    if _table_has_column(db, 'plan_schedules', 'field_status'):
        sql += " AND COALESCE(field_status, 'active')!='completed'"
    return db.execute(sql + ' LIMIT 1',
                      (user_id, schedule_type, period_end, period_start)).fetchone()


def _ps_recalculate_field_execution(db, plan_id):
    """Update one execution package only after all active items have left the site."""
    checkout_condition = ' OR check_out_time IS NULL' if _mobile_checkout_supported(db) else ''
    summary = db.execute(f"""SELECT COUNT(*) AS total,
            SUM(CASE WHEN result IS NOT NULL THEN 1 ELSE 0 END) AS submitted,
            SUM(CASE WHEN result IS NULL{checkout_condition} THEN 1 ELSE 0 END) AS field_open
        FROM insp_plan_items
        WHERE plan_id=? AND COALESCE(execution_status, 'active')='active'""", (plan_id,)).fetchone()
    total = int(summary['total'] or 0) if summary else 0
    submitted = int(summary['submitted'] or 0) if summary else 0
    field_open = int(summary['field_open'] or 0) if summary else 0
    status = 'completed' if total and field_open == 0 else 'active'
    if _table_has_column(db, 'insp_plans', 'completion_rate'):
        db.execute("""UPDATE insp_plans SET completion_rate=?, status=?
            WHERE id=? AND status!='cancelled'""",
                   (round(submitted / total * 100, 1) if total else 0, status, plan_id))
    else:
        db.execute("UPDATE insp_plans SET status=? WHERE id=? AND status!='cancelled'",
                   (status, plan_id))
    schedule = db.execute("SELECT plan_schedule_id FROM insp_plans WHERE id=?", (plan_id,)).fetchone()
    field_status = _ps_sync_field_status(db, schedule['plan_schedule_id'] if schedule else None)
    return {'total': total, 'submitted': submitted, 'field_open': field_open,
            'status': status, 'field_status': field_status}


def _ps_favorite_snapshot(schedule):
    parsed = _ps_parse_row(schedule)
    start = datetime.strptime(str(parsed['period_start'])[:10], '%Y-%m-%d')
    end = datetime.strptime(str(parsed['period_end'])[:10], '%Y-%m-%d')
    relative_plan = {}
    for date_str, day in (parsed.get('plan_data') or {}).items():
        try:
            offset = (datetime.strptime(str(date_str)[:10], '%Y-%m-%d') - start).days
        except (TypeError, ValueError):
            continue
        if 0 <= offset <= (end - start).days and isinstance(day, dict):
            relative_day = {
                'sites': [int(site_id) for site_id in (day.get('sites') or []) if str(site_id).isdigit()],
                'notes': (day.get('notes') or '').strip(),
            }
            if 'inspection_items' in day:
                selection = day.get('inspection_items')
                if not isinstance(selection, dict):
                    raise PlanScheduleSiteScopeError(
                        '常用计划中的检查项选择无效',
                        code='PLAN_INSPECTION_ITEM_SELECTION_INVALID')
                relative_day['inspection_items'] = {
                    str(site_id): list(selection.get(str(site_id), []))
                    for site_id in relative_day['sites'] if str(site_id) in selection
                }
            relative_plan[str(offset)] = relative_day
    normalized_vehicle_days = _ps_expand_plan_vehicle(
        parsed.get('plan_data') or {}, parsed.get('vehicle_id'), parsed.get('vehicle_days') or {})
    plan_vehicle_id = _ps_plan_vehicle_id(normalized_vehicle_days)
    return {
        'schedule_type': parsed['schedule_type'],
        'source_period_start': parsed['period_start'],
        'source_period_end': parsed['period_end'],
        'duration_days': max(1, (end - start).days + 1),
        'plan_data': relative_plan,
        'vehicle_id': plan_vehicle_id,
        'no_vehicle_required': bool(parsed.get('no_vehicle_required')),
        'vehicle_exception_reason': parsed.get('vehicle_exception_reason') or '',
        'spare_parts': parsed.get('spare_parts') or [],
        'remarks': parsed.get('remarks') or '',
    }


def _ps_favorite_response(row):
    result = dict(row)
    try:
        snapshot = json.loads(result.pop('snapshot') or '{}')
    except (TypeError, ValueError):
        snapshot = {}
    site_ids = {
        int(site_id) for day in (snapshot.get('plan_data') or {}).values()
        if isinstance(day, dict) for site_id in (day.get('sites') or []) if str(site_id).isdigit()
    }
    result.update({
        'schedule_type': snapshot.get('schedule_type', 'weekly'),
        'duration_days': int(snapshot.get('duration_days') or 1),
        'day_count': sum(1 for day in (snapshot.get('plan_data') or {}).values()
                         if isinstance(day, dict) and day.get('sites')),
        'site_count': len(site_ids),
        'vehicle_day_count': (
            sum(1 for day in (snapshot.get('plan_data') or {}).values()
                if isinstance(day, dict) and day.get('sites'))
            if snapshot.get('vehicle_id') else len(snapshot.get('vehicle_days') or {})
        ),
        'part_count': len(snapshot.get('spare_parts') or []),
    })
    return result


def _ps_next_favorite_start(db, user_id, snapshot):
    duration = max(1, int(snapshot.get('duration_days') or 1))
    latest_sql = """SELECT MAX(period_end) AS period_end FROM plan_schedules
        WHERE user_id=? AND schedule_type=? AND status NOT IN ('rejected','archived','cancelled')"""
    if _table_has_column(db, 'plan_schedules', 'field_status'):
        latest_sql += " AND COALESCE(field_status, 'active')!='completed'"
    latest = db.execute(latest_sql, (user_id, snapshot.get('schedule_type', 'weekly'))).fetchone()
    today = datetime.now().date()
    if latest and latest['period_end']:
        try:
            return max(today, datetime.strptime(str(latest['period_end'])[:10], '%Y-%m-%d').date()
                       + timedelta(days=1)).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return today.strftime('%Y-%m-%d')


def _require_plan_favorite_operator():
    if not _has_any_role(g.current_user, 'operator'):
        return jsonify({'error': '常用计划仅供承担现场巡检职责的运维人员使用'}), 403
    return None


@app.route('/api/plan-schedule-favorites', methods=['GET'])
@login_required
def api_plan_schedule_favorites_list():
    denied = _require_plan_favorite_operator()
    if denied:
        return denied
    with get_db() as db:
        rows = db.execute("""SELECT * FROM plan_schedule_favorites
            WHERE user_id=? ORDER BY created_at DESC, id DESC""", (g.current_user['id'],)).fetchall()
        result = []
        for row in rows:
            item = _ps_favorite_response(row)
            try:
                snapshot = json.loads(row['snapshot'] or '{}')
            except (TypeError, ValueError):
                snapshot = {}
            item['suggested_period_start'] = _ps_next_favorite_start(db, g.current_user['id'], snapshot)
            result.append(item)
        return jsonify(result)


@app.route('/api/plan-schedule-favorites', methods=['POST'])
@login_required
def api_plan_schedule_favorites_create():
    denied = _require_plan_favorite_operator()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    schedule_id = data.get('schedule_id')
    if not schedule_id:
        return jsonify({'error': '请选择要收藏的巡检计划'}), 400
    with get_db() as db:
        schedule = db.execute('SELECT * FROM plan_schedules WHERE id=?', (schedule_id,)).fetchone()
        if not schedule:
            return jsonify({'error': '巡检计划不存在'}), 404
        if int(schedule['user_id']) != int(g.current_user['id']):
            return jsonify({'error': '只能收藏自己的巡检计划'}), 403
        try:
            snapshot = _ps_favorite_snapshot(schedule)
        except PlanScheduleSiteScopeError as exc:
            if exc.code == 'PLAN_MULTIPLE_VEHICLES_NOT_ALLOWED':
                exc.status = 409
            return _ps_site_scope_error_response(exc)
        except (TypeError, ValueError):
            return jsonify({'error': '计划周期数据不完整，无法收藏'}), 400
        site_count = len({site_id for day in snapshot['plan_data'].values() for site_id in day['sites']})
        if not site_count:
            return jsonify({'error': '空排程不能收藏'}), 400
        name = (data.get('name') or '').strip()[:60]
        if not name:
            start_label = str(schedule['period_start'] or '')[5:10]
            name = f'{_PS_FREQ_CN.get(schedule["schedule_type"], "巡检")}常用计划 · {site_count}站'
            if start_label:
                name += f' · {start_label}'
        duplicate = None
        for existing in db.execute("""SELECT id, snapshot FROM plan_schedule_favorites
                WHERE user_id=?""", (g.current_user['id'],)).fetchall():
            try:
                if json.loads(existing['snapshot'] or '{}') == snapshot:
                    duplicate = existing
                    break
            except (TypeError, ValueError):
                continue
        if duplicate:
            return jsonify({'error': '相同内容的计划已收藏，可直接从常用计划生成草稿', 'favorite_id': duplicate['id']}), 409
        cursor = db.execute("""INSERT INTO plan_schedule_favorites
            (user_id, source_schedule_id, name, snapshot) VALUES (?,?,?,?)""",
            (g.current_user['id'], schedule_id, name,
             json.dumps(snapshot, ensure_ascii=False, sort_keys=True, separators=(',', ':'))))
        db.commit()
        row = db.execute('SELECT * FROM plan_schedule_favorites WHERE id=?', (cursor.lastrowid,)).fetchone()
        return jsonify(_ps_favorite_response(row)), 201


@app.route('/api/plan-schedule-favorites/<int:favorite_id>', methods=['DELETE'])
@login_required
def api_plan_schedule_favorites_delete(favorite_id):
    denied = _require_plan_favorite_operator()
    if denied:
        return denied
    with get_db() as db:
        cursor = db.execute('DELETE FROM plan_schedule_favorites WHERE id=? AND user_id=?',
                            (favorite_id, g.current_user['id']))
        if not cursor.rowcount:
            return jsonify({'error': '常用计划不存在'}), 404
        db.commit()
    return jsonify({'success': True, 'id': favorite_id})


@app.route('/api/plan-schedule-favorites/<int:favorite_id>/draft', methods=['POST'])
@login_required
def api_plan_schedule_favorite_create_draft(favorite_id):
    denied = _require_plan_favorite_operator()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        favorite = db.execute('SELECT * FROM plan_schedule_favorites WHERE id=? AND user_id=?',
                              (favorite_id, g.current_user['id'])).fetchone()
        if not favorite:
            return jsonify({'error': '常用计划不存在'}), 404
        try:
            snapshot = json.loads(favorite['snapshot'] or '{}')
            period_start_date = datetime.strptime(str(data.get('period_start') or '')[:10], '%Y-%m-%d')
            duration = max(1, min(366, int(snapshot.get('duration_days') or 1)))
        except (TypeError, ValueError):
            return jsonify({'error': '请选择新计划的开始日期'}), 400
        schedule_type = snapshot.get('schedule_type', 'weekly')
        if schedule_type not in _PS_FREQ_CN:
            return jsonify({'error': '收藏中的计划类型已失效'}), 400
        period_start = period_start_date.strftime('%Y-%m-%d')
        period_end = (period_start_date + timedelta(days=duration - 1)).strftime('%Y-%m-%d')
        overlap = _ps_period_overlap(db, g.current_user['id'], schedule_type, period_start, period_end)
        if overlap:
            return jsonify({'error': f'该周期已有计划（{overlap["period_start"]} ~ {overlap["period_end"]}），请更换日期'}), 409
        plan_data, vehicle_days = {}, {}
        for offset_text, day in (snapshot.get('plan_data') or {}).items():
            try:
                offset = int(offset_text)
            except (TypeError, ValueError):
                continue
            if 0 <= offset < duration and isinstance(day, dict):
                date_str = (period_start_date + timedelta(days=offset)).strftime('%Y-%m-%d')
                plan_data[date_str] = {
                    'sites': day.get('sites') or [], 'notes': day.get('notes') or ''}
                if 'inspection_items' in day:
                    plan_data[date_str]['inspection_items'] = json.loads(
                        json.dumps(day.get('inspection_items'), ensure_ascii=False))
        for offset_text, vehicle_id in (snapshot.get('vehicle_days') or {}).items():
            try:
                offset = int(offset_text)
            except (TypeError, ValueError):
                continue
            if 0 <= offset < duration and str(vehicle_id).isdigit():
                vehicle_days[(period_start_date + timedelta(days=offset)).strftime('%Y-%m-%d')] = int(vehicle_id)
        try:
            plan_data = _ps_validate_execution_sites(db, g.current_user['id'], plan_data)
            plan_data = _ps_validate_item_selections(db, plan_data, schedule_type)
            vehicle_days = _ps_expand_plan_vehicle(
                plan_data, snapshot.get('vehicle_id'), vehicle_days)
            vehicle_id = _ps_plan_vehicle_id(vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        no_vehicle_required = snapshot.get('no_vehicle_required') in (True, 1, '1', 'true')
        validation = _ps_validate(db, g.current_user['id'], schedule_type, period_start, period_end,
                                  plan_data, vehicle_days,
                                  no_vehicle_required=no_vehicle_required)
        cursor = db.execute("""INSERT INTO plan_schedules
            (user_id, schedule_type, period_start, period_end, plan_data, vehicle_days, vehicle_id,
             spare_parts, work_order_ids, status, remarks, vehicle_exception_reason,
             no_vehicle_required, tasks_generated)
            VALUES (?,?,?,?,?,?,?,?,?, 'draft', ?, ?, ?, 0)""",
            (g.current_user['id'], schedule_type, period_start, period_end,
             json.dumps(plan_data, ensure_ascii=False), json.dumps(vehicle_days, ensure_ascii=False), vehicle_id,
             json.dumps(snapshot.get('spare_parts') or [], ensure_ascii=False), '[]', snapshot.get('remarks') or '',
             snapshot.get('vehicle_exception_reason') or '', int(no_vehicle_required)))
        schedule_id = cursor.lastrowid
        _ps_record_event(db, schedule_id, 1, 'created_from_favorite', g.current_user['id'], {
            'favorite_id': favorite_id, 'source_schedule_id': favorite['source_schedule_id'],
            'validation': validation, 'excluded_fields': ['work_order_ids', 'approval', 'execution_records'],
        })
        db.commit()
        row = db.execute('SELECT * FROM plan_schedules WHERE id=?', (schedule_id,)).fetchone()
        return jsonify({'success': True, 'schedule': _ps_parse_row(row), 'validation': validation}), 201


@app.route('/api/plan-schedules/draft-recommendations', methods=['GET', 'POST'])
@login_required
def api_plan_schedule_draft_recommendations_retired():
    """拒绝旧客户端继续读取或执行已停用的到期巡检建议。"""
    return jsonify({
        'error': '到期巡检建议功能已停用，请直接创建巡检计划或从常用计划生成草稿',
        'code': 'INSPECTION_DUE_SUGGESTION_RETIRED',
    }), 410


def _ps_check_vehicle_conflicts(db, user_id, vehicle_days, exclude_schedule_id=None,
                                include_submitted_plan_conflicts=True):
    """用车冲突检测（三层交叉）：
    1. vehicle_applications 中他人已占用的时间段
    2. 他人计划（submitted/approved）的 vehicle_days 同日同车
    3. 车辆自身处于维保状态
    返回冲突列表 [{date, vehicle_id, plate_no, reason}]"""
    conflicts = []
    if not vehicle_days:
        return conflicts
    for date_str, vid in (vehicle_days or {}).items():
        if not vid:
            continue
        veh = db.execute("SELECT id, plate_no, status, insurance_expiry, annual_inspection_expiry FROM vehicles WHERE id=?", (vid,)).fetchone()
        plate = veh['plate_no'] if veh else f'车辆{vid}'
        if not veh:
            conflicts.append({'date': date_str, 'vehicle_id': vid, 'plate_no': plate,
                              'reason': '车辆不存在，无法安排'})
            continue
        dispatchable, dispatch_reason = _vehicle_can_dispatch(
            db, veh, exclude_schedule_id=exclude_schedule_id)
        if not dispatchable:
            conflicts.append({'date': date_str, 'vehicle_id': vid, 'plate_no': plate,
                              'reason': f'{plate} {dispatch_reason}，不可安排'})
            continue
        # 1. 他人用车申请占用当天
        occ = db.execute("""
            SELECT va.id, u.real_name FROM vehicle_applications va
            LEFT JOIN users u ON va.applicant_id = u.id
            WHERE va.vehicle_id=? AND va.status IN ('pending','approved')
              AND va.applicant_id IS NOT NULL AND va.applicant_id != ?
              AND date(va.start_at) <= ? AND date(va.end_at) >= ?
            LIMIT 1
        """, (vid, user_id, date_str, date_str)).fetchone()
        if occ:
            conflicts.append({'date': date_str, 'vehicle_id': vid, 'plate_no': plate,
                              'reason': f'{plate} 当天已被{occ["real_name"] or "他人"}预约'})
            continue
        # 2. 他人计划的 vehicle_days 占用
        plan_statuses = "'submitted','approved'" if include_submitted_plan_conflicts else "'approved'"
        others = db.execute(f"""
            SELECT id, user_id, vehicle_days, period_start, period_end FROM plan_schedules
            WHERE status IN ({plan_statuses}) AND user_id != ?
              AND period_start <= ? AND period_end >= ?
        """, (user_id, date_str, date_str)).fetchall()
        hit = None
        for o in others:
            if exclude_schedule_id and o['id'] == exclude_schedule_id:
                continue
            try:
                ovd = json.loads(o['vehicle_days'] or '{}')
            except Exception:
                ovd = {}
            if str(ovd.get(date_str)) == str(vid):
                hit = o
                break
        if hit:
            ou = db.execute("SELECT real_name FROM users WHERE id=?", (hit['user_id'],)).fetchone()
            conflicts.append({'date': date_str, 'vehicle_id': vid, 'plate_no': plate,
                              'reason': f'{plate} 当天已被{ou["real_name"] if ou else "他人"}的计划安排'})
    return conflicts


def _ps_validate(db, user_id, schedule_type, period_start, period_end,
                 plan_data, vehicle_days, exclude_schedule_id=None,
                 vehicle_exception_reason='', include_submitted_plan_conflicts=True,
                 no_vehicle_required=False):
    """计划校验：日期范围 + 周巡检全覆盖 + 用车完整性/冲突。
    errors 阻断提交；warnings 仅提示（审批端同样可见，由人拍板）。"""
    errors, warnings, warning_details = [], [], []
    error_details = []
    pd = plan_data or {}
    # 日期范围校验
    for d in pd.keys():
        if d < str(period_start) or d > str(period_end):
            errors.append(f'日期 {d} 超出周期范围（{period_start} ~ {period_end}）')
            error_details.append({'field': 'plan_data', 'date': d, 'text': errors[-1]})
    planned_dates = sorted(
        str(date_str) for date_str, day_data in pd.items()
        if isinstance(day_data, dict) and day_data.get('sites')
    )
    if not planned_dates:
        errors.append('请至少安排一个巡检日期和站点')
        error_details.append({'field': 'sites', 'text': errors[-1]})
    elif _ps_generatable_item_count(db, pd, schedule_type) == 0:
        errors.append('当前计划未选择任何可执行检查项，请至少为一个站点选择检查项')
        error_details.append({'field': 'plan_data', 'date': planned_dates[0], 'text': errors[-1]})
    if no_vehicle_required and any((vehicle_days or {}).values()):
        errors.append('已选择无需用车，不能同时安排车辆')
        error_details.append({'field': 'no_vehicle_required', 'text': errors[-1]})
    elif not no_vehicle_required and any(not (vehicle_days or {}).get(date_str) for date_str in planned_dates):
        errors.append('已选择需要用车，请先选择计划车辆')
        error_details.append({'field': 'vehicle_id', 'text': errors[-1]})
    # 周巡检全覆盖校验
    if schedule_type == 'weekly':
        user_sites = [r['site_id'] for r in
                      db.execute("SELECT site_id FROM user_sites WHERE user_id=?", (user_id,)).fetchall()]
        planned = set()
        for day_data in pd.values():
            if isinstance(day_data, dict):
                planned.update(day_data.get('sites') or [])
        missing = [sid for sid in user_sites if sid not in planned]
        if missing:
            names = [r['name'] for r in db.execute(
                f"SELECT name FROM sites WHERE id IN ({','.join('?'*len(missing))})", missing).fetchall()]
            text = f'本周未覆盖：{"、".join(names)}（周巡检要求全覆盖，请确认是否遗漏）'
            warnings.append(text)
            warning_details.append({
                'type': 'coverage_missing', 'site_ids': missing, 'site_names': names,
                'text': text
            })
    # 用车冲突
    for c in _ps_check_vehicle_conflicts(
            db, user_id, vehicle_days, exclude_schedule_id,
            include_submitted_plan_conflicts=include_submitted_plan_conflicts):
        errors.append(f'{c["date"]} {c["reason"]}')
        error_details.append({'field': 'plan_data', 'date': c['date'], 'text': errors[-1]})
    # 路线顺序优化建议（仅警告，不代表真实道路导航结果）
    for d in sorted(pd.keys()):
        day_data = pd[d]
        if not isinstance(day_data, dict):
            continue
        site_ids = day_data.get('sites') or []
        if len(site_ids) < 3:
            continue
        ph = ','.join('?' * len(site_ids))
        rows = db.execute(f"SELECT id, name, gps_lat, gps_lng FROM sites WHERE id IN ({ph})", site_ids).fetchall()
        coord_map = {r['id']: (r['gps_lat'], r['gps_lng'], r['name']) for r in rows}
        coords = [(sid, coord_map.get(sid)) for sid in site_ids if coord_map.get(sid) and coord_map[sid][0] and coord_map[sid][1]]
        for i in range(len(coords) - 2):
            a_id, a = coords[i]
            b_id, b = coords[i + 1]
            c_id, c = coords[i + 2]
            dist_ab = ((a[0]-b[0])**2 + (a[1]-b[1])**2) ** 0.5
            dist_ac = ((a[0]-c[0])**2 + (a[1]-c[1])**2) ** 0.5
            if dist_ac < dist_ab * 0.85:  # C 比 B 更靠近 A（留 15% 容差避免误报）
                saved_deg = dist_ab - dist_ac
                saved_km = saved_deg * 111  # 粗略：1度≈111km
                suggested_ids = list(site_ids)
                b_index = suggested_ids.index(b_id)
                c_index = suggested_ids.index(c_id)
                suggested_ids[b_index], suggested_ids[c_index] = suggested_ids[c_index], suggested_ids[b_index]
                suggested_names = [coord_map[site_id][2] for site_id in suggested_ids]
                text = (f'路线顺序可优化：建议顺序：{" → ".join(suggested_names)}；'
                        f'预计少绕行约 {saved_km:.1f} km（按站点位置估算）')
                warnings.append(text)
                warning_details.append({
                    'type': 'route_backtrack', 'date': d,
                    'site_ids': [a_id, b_id, c_id], 'site_names': [a[2], b[2], c[2]],
                    'suggested_site_ids': suggested_ids,
                    'suggested_site_names': suggested_names,
                    'estimated_distance_saved_km': round(saved_km, 1),
                    'text': text
                })
        # 可执行性底线：按每站90分钟、站间45分钟粗估一个8小时工作日。
        # 这是审批提示而非替代现场判断，避免看似顺路但实际无法完成的排程。
        count = len(site_ids)
        estimated_minutes = count * 90 + max(0, count - 1) * 45
        if estimated_minutes > 480:
            text = f'{d} 预计作业{estimated_minutes // 60}小时{estimated_minutes % 60}分，超过8小时作业窗口，建议拆分或说明例外'
            warnings.append(text)
            warning_details.append({
                'type': 'day_overload', 'date': d, 'site_ids': site_ids,
                'estimated_minutes': estimated_minutes, 'text': text
            })
    return {'ok': not errors, 'errors': errors, 'error_details': error_details,
            'warnings': warnings, 'warning_details': warning_details}


def _ps_coverage_exception_required(validation, schedule_type, reason):
    """周检漏站不是普通提醒：必须由排程人说明例外原因，再交由审批人显式放行。"""
    missing = schedule_type == 'weekly' and any('本周未覆盖' in w for w in validation['warnings'])
    if missing and not (reason or '').strip():
        return '周巡检存在未覆盖站点，请填写例外原因后再提交'
    return None


def require_reviewer():
    """材料/影像/结果审核门禁：审核员可审核，不具备排程与资源审批权限。"""
    u = g.get('current_user')
    if not _has_any_role(u, 'admin', 'reviewer'):
        return jsonify({'success': False, 'error': '需要审核员或管理员权限'}), 403
    return None


def _ps_record_event(db, schedule_id, version, event_type, operator_id, payload):
    cursor = db.execute("""INSERT INTO plan_schedule_events
        (schedule_id, version, event_type, operator_id, payload) VALUES (?,?,?,?,?)""",
        (schedule_id, version, event_type, operator_id,
         json.dumps(payload or {}, ensure_ascii=False)))
    return cursor.lastrowid


def _ps_reserve_parts(db, schedule):
    """记录计划需求量但不占用库存；实际领用时按实时库存校验。"""
    try:
        parts = json.loads(schedule['spare_parts'] or '[]')
    except Exception:
        parts = []
    # 同一备件可能在编辑器中被重复添加；先汇总，避免产生重复需求记录。
    requested = {}
    for part in parts:
        if not isinstance(part, dict) or not part.get('part_id'):
            continue
        part_id, qty = int(part['part_id']), max(1, int(part.get('quantity') or 1))
        requested[part_id] = requested.get(part_id, 0) + qty
    planned = 0
    for part_id, planned_qty in requested.items():
        inv = db.execute("SELECT id FROM spare_parts_inventory WHERE id=?", (part_id,)).fetchone()
        if not inv:
            raise ValueError(f'备件#{part_id}不存在')
        existing = db.execute("""SELECT * FROM plan_resource_reservations
            WHERE schedule_id=? AND part_id=? ORDER BY id DESC LIMIT 1""", (schedule['id'], part_id)).fetchone()
        if existing:
            db.execute("""UPDATE plan_resource_reservations SET planned_quantity=?,reserved_quantity=0,
                status=CASE WHEN issued_quantity>0 THEN 'issued' ELSE 'planned' END,
                updated_at=datetime('now','localtime') WHERE id=?""", (planned_qty, existing['id']))
        else:
            db.execute("""INSERT INTO plan_resource_reservations
                (schedule_id, part_id, planned_quantity, reserved_quantity, status)
                VALUES (?,?,?,0,'planned')""", (schedule['id'], part_id, planned_qty))
        planned += 1
    return planned


def _ps_site_scores(db, site_ids):
    """站点优先级评分：未关工单、待处理告警、人工上报和试剂临期。
    评分逻辑透明可解释，供排程建议与审批风险预警共用。"""
    scores = {}
    details = {}
    today = datetime.now()
    for sid in site_ids:
        score, reasons = 0, []
        order_no_select = 'order_no' if _table_has_column(db, 'work_orders', 'order_no') else 'NULL AS order_no'
        # 未关工单
        orders = db.execute(f"""
            SELECT id, title, level, created_at, {order_no_select} FROM work_orders
            WHERE site_id=? AND status NOT IN ('closed')
        """, (sid,)).fetchall()
        active_order_nos = {str(o['order_no']) for o in orders if o['order_no']}
        for o in orders:
            base = {'urgent': 30, 'normal': 10}.get(o['level'], 10)
            try:
                age = (today - datetime.strptime(str(o['created_at'])[:10], '%Y-%m-%d')).days
            except Exception:
                age = 0
            overdue = 10 if age >= 7 else 0
            score += base + overdue
            reasons.append(f'未关工单「{o["title"]}」（{"紧急" if o["level"] == "urgent" else "普通"}，已{age}天）')
        # 待处理告警
        alert_order_select = ('related_order_no' if _table_has_column(db, 'alerts', 'related_order_no')
                              else 'NULL AS related_order_no')
        alerts = db.execute(f"SELECT level, metric, {alert_order_select} FROM alerts "
                            "WHERE site_id=? AND status='pending'", (sid,)).fetchall()
        for a in alerts:
            if a['related_order_no'] and str(a['related_order_no']) in active_order_nos:
                continue
            score += {'red': 20, 'orange': 12, 'yellow': 6}.get(a['level'], 5)
            metric = a['metric'] or ''
            metric_label = ('人工上报' if metric == 'manual_report'
                            else METRIC_CN.get(metric, metric or '指标异常'))
            reasons.append(f'{ALERT_LEVEL_LABEL.get(a["level"], a["level"])}告警（{metric_label}）待处理')
        # 无有效工单承接的人工上报仍是独立排程证据；已有承接工单时折叠到工单。
        try:
            report_order_select = ('order_no' if _table_has_column(db, 'manual_reports', 'order_no')
                                   else 'NULL AS order_no')
            reports = db.execute(f"""
                SELECT id, report_type, description, reported_at, {report_order_select}
                FROM manual_reports
                WHERE site_id=? AND status NOT IN ('resolved', 'archived', 'closed')
                  AND reported_at >= datetime('now', '-30 days')
                ORDER BY reported_at DESC
            """, (sid,)).fetchall()
            for report in reports:
                if report['order_no'] and str(report['order_no']) in active_order_nos:
                    continue
                report_type = report['report_type'] or 'other'
                score += {'pollution': 30, 'violation': 25, 'equipment': 18,
                          'environment': 16, 'sensory': 10}.get(report_type, 10)
                report_type_label = {
                    'sensory': '感官', 'equipment': '设备', 'environment': '环境',
                    'violation': '违规', 'pollution': '污染',
                }.get(report_type, '其他')
                reasons.append(f'人工上报{report_type_label}异常待跟进')
        except Exception:
            pass
        # 试剂临期
        try:
            invs = db.execute("""
                SELECT ri.*, r.name as reagent_name FROM reagent_inventory ri
                LEFT JOIN reagents r ON ri.reagent_id = r.id WHERE ri.site_id=?
            """, (sid,)).fetchall()
            for inv in invs:
                st = compute_reagent_status(dict(inv))
                if st.get('status') in ('临期', '已过期', '低余量'):
                    score += 8
                    reasons.append(f'试剂{inv["reagent_name"] or ""}{st["status"]}（约剩{st.get("remaining_days")}天）')
        except Exception:
            pass
        scores[sid] = score
        details[sid] = reasons
    return scores, details


def _ps_add_site_tasks(db, plan_id, site_id, schedule_type, selected_item_ids=None):
    """按计划频次为一个执行包补齐一个站点的模板检查项，返回新增项数。"""
    items = _ps_site_template_items(
        db, site_id, schedule_type,
        include_weekly_optional=(schedule_type == 'weekly' and selected_item_ids is not None))
    if selected_item_ids is not None:
        selected = {int(item_id) for item_id in selected_item_ids}
        items = [item for item in items if int(item['id']) in selected]
        if not items:
            return 0
    if items:
        item_columns = {row['name'] for row in db.execute('PRAGMA table_info(insp_plan_items)').fetchall()}
        for it in items:
            required_photos = _inspection_required_photos(it)
            values = {
                'plan_id': plan_id, 'site_id': site_id, 'template_id': it['template_id'],
                'item_name': it['item_name'], 'category': it['category'],
                'frequency': it.get('template_frequency') or schedule_type,
                'required_photos': required_photos,
            }
            if 'need_review' in item_columns:
                values['need_review'] = int(it.get('need_review') or 0)
            if 'inspection_standard' in item_columns:
                values['inspection_standard'] = it.get('inspection_standard') or ''
                if required_photos > 0 and (it.get('item_name') == '五参数仪器质控' or it.get('category') in {'质控校准', 'qaqc_calibration', '站房环境'}):
                    values['inspection_standard'] = (values['inspection_standard'] + f'；现场照片至少 {required_photos} 张').lstrip('；')
            columns = list(values)
            db.execute(
                f"INSERT INTO insp_plan_items ({','.join(columns)}) "
                f"VALUES ({','.join('?' for _ in columns)})",
                [values[column] for column in columns])
        return len(items)
    # 无匹配模板仍保留一项可执行任务，避免审批通过后出现空站点。
    db.execute("""
        INSERT INTO insp_plan_items (plan_id, site_id, item_name, category, frequency)
        VALUES (?,?,?,?,?)
    """, (plan_id, site_id, '常规检查', '常规', schedule_type))
    return 1


def _ps_site_task_count(db, site_id, schedule_type, selected_item_ids=None):
    """Count what task generation would create without writing an execution package."""
    items = _ps_site_template_items(
        db, site_id, schedule_type,
        include_weekly_optional=(schedule_type == 'weekly' and selected_item_ids is not None))
    if selected_item_ids is not None:
        selected = {int(item_id) for item_id in selected_item_ids}
        return sum(1 for item in items if int(item['id']) in selected)
    return len(items) if items else 1


def _ps_generatable_item_count(db, plan_data, schedule_type):
    total = 0
    for day_data in (plan_data or {}).values():
        if not isinstance(day_data, dict):
            continue
        selected_by_site = day_data.get('inspection_items')
        for site_id in day_data.get('sites') or []:
            selected = (selected_by_site.get(str(site_id))
                        if isinstance(selected_by_site, dict) else None)
            total += _ps_site_task_count(db, site_id, schedule_type, selected)
    return total


def _ps_generate_tasks(db, schedule):
    """审批通过后生成执行任务：每个有安排的日期生成一个 insp_plan（直接 active，
    因为计划已审批，不再二次审批），按站点类型+频次匹配模板展开检查项。幂等。"""
    plan_data = _ps_decode_plan_data(schedule['plan_data'])
    plan_data = _ps_validate_execution_sites(db, schedule['user_id'], plan_data)
    plan_data = _ps_validate_item_selections(db, plan_data, schedule['schedule_type'])
    user = db.execute("SELECT real_name FROM users WHERE id=?", (schedule['user_id'],)).fetchone()
    op_name = user['real_name'] if user else str(schedule['user_id'])
    freq_cn = _PS_FREQ_CN.get(schedule['schedule_type'], '巡检')
    created, total_items = 0, 0
    for date_str in sorted(plan_data.keys()):
        day_data = plan_data[date_str] or {}
        site_ids = day_data.get('sites') if isinstance(day_data, dict) else day_data
        if not site_ids:
            continue
        selected_by_site = day_data.get('inspection_items') if isinstance(day_data, dict) else None
        day_item_count = sum(
            _ps_site_task_count(
                db, site_id, schedule['schedule_type'],
                selected_by_site.get(str(site_id)) if isinstance(selected_by_site, dict) else None)
            for site_id in site_ids
        )
        if not day_item_count:
            continue
        # 同来源同日期已有可执行包时不重复生成；被替代/取消的历史包仍可保留审计。
        dup = db.execute("SELECT id FROM insp_plans WHERE plan_schedule_id=? AND generate_date=? AND status != 'cancelled'",
                         (schedule['id'], date_str)).fetchone()
        if dup:
            continue
        plan_name = f"{op_name}·{freq_cn}-{date_str.replace('-', '')}"
        cur = db.execute("""
            INSERT INTO insp_plans (plan_name, assignee, assignee_id, period, generate_date, status,
                                    plan_schedule_id, schedule_version, plan_snapshot)
            VALUES (?,?,?,?,?,?,?,?,?)
        """, (plan_name, op_name, schedule['user_id'], schedule['schedule_type'],
              date_str, 'active', schedule['id'], schedule['version'],
              json.dumps({date_str: day_data}, ensure_ascii=False)))
        plan_id = cur.lastrowid
        selected_by_site = day_data.get('inspection_items') or {} if isinstance(day_data, dict) else {}
        for sid in site_ids:
            selected = selected_by_site.get(str(sid)) if isinstance(selected_by_site, dict) else None
            total_items += _ps_add_site_tasks(db, plan_id, sid, schedule['schedule_type'], selected)
        created += 1
    return created, total_items


def _ps_execution_site_rows(db, schedule_id, parent_status=None):
    """User-facing date x site summary over the internal daily execution packages."""
    completion_sql = _inspection_field_completion_sql(db, 'pi')
    rework_sql = _inspection_active_rework_sql(db, 'pi')
    rows = db.execute(f"""SELECT MIN(ip.id) AS plan_id, date(ip.generate_date) AS execution_date, pi.site_id,
               s.name AS site_name, ip.assignee, COUNT(*) AS total_items,
               SUM(CASE WHEN {completion_sql} THEN 1 ELSE 0 END) AS completed_items,
               SUM(CASE WHEN {rework_sql} THEN 1 ELSE 0 END) AS rework_items,
               SUM(CASE WHEN pi.result='abnormal' THEN 1 ELSE 0 END) AS abnormal_items
        FROM insp_plans ip JOIN insp_plan_items pi ON pi.plan_id=ip.id
        LEFT JOIN sites s ON s.id=pi.site_id
        WHERE ip.plan_schedule_id=? AND ip.status!='cancelled'
          AND COALESCE(pi.execution_status,'active')='active'
        GROUP BY date(ip.generate_date), pi.site_id, s.name, ip.assignee
        ORDER BY execution_date, s.name""", (schedule_id,)).fetchall()
    today = datetime.now().strftime('%Y-%m-%d')
    result = []
    for row in rows:
        total = int(row['total_items'] or 0)
        completed = int(row['completed_items'] or 0)
        if parent_status in ('modifying', 'change_submitted'):
            state = 'change_pending'
        elif int(row['rework_items'] or 0):
            state = 'rework'
        elif total and completed >= total:
            state = 'completed'
        elif completed:
            state = 'partial'
        else:
            state = 'pending'
        result.append({
            'id': row['plan_id'], 'plan_id': row['plan_id'], 'date': row['execution_date'], 'site_id': row['site_id'],
            'site_name': row['site_name'] or f'站点#{row["site_id"]}',
            'assignee': row['assignee'] or '', 'total_items': total,
            'completed_items': completed, 'abnormal_items': int(row['abnormal_items'] or 0),
            'completion_rate': round(completed / total * 100, 1) if total else 0,
            'status': state,
            'status_cn': {'pending': '待执行', 'partial': '部分完成',
                          'completed': '已完成', 'change_pending': '变更待审',
                          'rework': '需整改'}[state],
            'overdue': bool(row['execution_date'] and row['execution_date'] < today and state not in ('completed', 'change_pending')),
            'attention': ('计划变更待审核，暂不继续执行' if state == 'change_pending'
                          else ('已逾期且尚未完成' if row['execution_date'] and row['execution_date'] < today and state != 'completed'
                                else ('存在异常检查项' if int(row['abnormal_items'] or 0) else ''))),
        })
    return result


def _ps_rework_execution_capability(db, schedule, execution_status, user):
    """Project one exact, currently authorized remediation target for plan detail."""
    unavailable = lambda reason: {
        'allowed': False, 'reason': reason, 'target': None,
    }
    if execution_status != 'rework' or schedule['status'] != 'approved':
        return unavailable('整改任务已闭环或状态已变化，请刷新计划详情')
    if (schedule['user_id'] != user['id']
            or not _has_any_role(user, 'operator')):
        return unavailable('当前账号无权执行该计划整改')
    required_columns = (
        ('insp_plans', 'plan_schedule_id'),
        ('insp_plans', 'assignee_id'),
        ('insp_plans', 'generate_date'),
        ('insp_plans', 'status'),
        ('insp_plan_items', 'plan_id'),
        ('insp_plan_items', 'site_id'),
        ('insp_plan_items', 'execution_status'),
    )
    if (not _table_exists(db, 'user_sites')
            or not all(_table_has_column(db, table, column)
                       for table, column in required_columns)):
        return unavailable('整改执行信息暂不可用，请刷新后重试')
    rework_sql = _inspection_active_rework_sql(db, 'pi')
    if rework_sql == '0':
        return unavailable('整改执行信息暂不可用，请刷新后重试')
    rework_priority = ('CASE WHEN ip.rework_of_plan_id IS NOT NULL THEN 0 ELSE 1 END'
                       if _table_has_column(db, 'insp_plans', 'rework_of_plan_id') else '1')
    try:
        target = db.execute(f"""SELECT ip.id AS execution_plan_id,
                    date(ip.generate_date) AS work_date, pi.site_id,
                    MIN(pi.id) AS item_id, {rework_priority} AS target_priority
                FROM insp_plans ip
                JOIN insp_plan_items pi ON pi.plan_id=ip.id
                JOIN user_sites us ON us.user_id=? AND us.site_id=pi.site_id
                WHERE ip.plan_schedule_id=? AND ip.assignee_id=?
                  AND ip.status IN ('active','completed')
                  AND COALESCE(pi.execution_status,'active')='active'
                  AND {rework_sql}
                GROUP BY ip.id, date(ip.generate_date), pi.site_id
                ORDER BY target_priority, date(ip.generate_date) DESC,
                         ip.id DESC, MIN(pi.id)
                LIMIT 1""", (user['id'], schedule['id'], user['id'])).fetchone()
    except sqlite3.DatabaseError:
        return unavailable('整改执行信息暂不可用，请刷新后重试')
    if not target:
        return unavailable('整改任务已闭环或执行权限已变化，请刷新计划详情')
    return {
        'allowed': True,
        'reason': '',
        'target': {
            'schedule_id': int(schedule['id']),
            'execution_plan_id': int(target['execution_plan_id']),
            'work_date': target['work_date'],
            'site_id': int(target['site_id']),
            'item_id': int(target['item_id']),
            'source': 'plan_detail_rework',
        },
    }


def _ps_field_execution_capability(db, schedule, execution_status, user):
    """Project an authorized ordinary/carryover target without guessing among candidates."""
    unavailable = lambda reason: {
        'allowed': False, 'reason': reason, 'target': None,
    }
    if execution_status not in ('pending', 'partial') or schedule['status'] != 'approved':
        return unavailable('当前计划没有可继续执行的现场任务')
    if (schedule['user_id'] != user['id']
            or not _has_any_role(user, 'operator')):
        return unavailable('当前账号无权执行该计划')
    required_columns = (
        ('insp_plans', 'plan_schedule_id'),
        ('insp_plans', 'assignee_id'),
        ('insp_plans', 'generate_date'),
        ('insp_plans', 'status'),
        ('insp_plan_items', 'plan_id'),
        ('insp_plan_items', 'site_id'),
        ('insp_plan_items', 'execution_status'),
        ('insp_plan_items', 'check_out_time'),
    )
    if (not _table_exists(db, 'user_sites')
            or not all(_table_has_column(db, table, column)
                       for table, column in required_columns)):
        return unavailable('现场执行信息暂不可用，请刷新后重试')
    completion_sql = _inspection_field_completion_sql(db, 'pi')
    rework_sql = _inspection_active_rework_sql(db, 'pi')
    today = datetime.now().strftime('%Y-%m-%d')
    try:
        candidates = db.execute(f"""SELECT ip.id AS execution_plan_id,
                    date(ip.generate_date) AS work_date, pi.site_id,
                    COUNT(*) AS total_items,
                    SUM(CASE WHEN {completion_sql} THEN 1 ELSE 0 END) AS completed_items,
                    SUM(CASE WHEN pi.check_out_time IS NOT NULL THEN 1 ELSE 0 END)
                        AS checked_out_items,
                    SUM(CASE WHEN {rework_sql} THEN 1 ELSE 0 END) AS rework_items
                FROM insp_plans ip
                JOIN insp_plan_items pi ON pi.plan_id=ip.id
                JOIN user_sites us ON us.user_id=? AND us.site_id=pi.site_id
                WHERE ip.plan_schedule_id=? AND ip.assignee_id=?
                  AND date(ip.generate_date)<=?
                  AND ip.status IN ('active','completed')
                  AND COALESCE(pi.execution_status,'active')='active'
                GROUP BY ip.id, date(ip.generate_date), pi.site_id
                HAVING rework_items=0
                   AND NOT (total_items>0
                            AND completed_items=total_items
                            AND checked_out_items=total_items)
                ORDER BY date(ip.generate_date), ip.id, pi.site_id""",
                (user['id'], schedule['id'], user['id'], today)).fetchall()
    except sqlite3.DatabaseError:
        return unavailable('现场执行信息暂不可用，请刷新后重试')
    if not candidates:
        return unavailable('执行任务已闭环或执行权限已变化，请刷新计划详情')
    target = {
        'schedule_id': int(schedule['id']),
        'source': 'plan_detail_execution',
    }
    if len(candidates) == 1:
        candidate = candidates[0]
        target.update({
            'execution_plan_id': int(candidate['execution_plan_id']),
            'work_date': candidate['work_date'],
            'site_id': int(candidate['site_id']),
        })
    return {
        'allowed': True,
        'reason': '',
        'target': target,
        'requires_selection': len(candidates) > 1,
    }


def _ps_schedule_execution_status(parent_status, field_status, site_rows=None,
                                  item_summary=None):
    """Derive the user-facing plan execution state without changing field state."""
    labels = {
        'pending': '待执行', 'partial': '部分完成', 'completed': '已完成',
        'change_pending': '变更待审', 'rework': '需整改',
    }
    if parent_status in ('modifying', 'change_submitted'):
        status = 'change_pending'
    elif field_status == 'rework' or (
            site_rows and any(row.get('status') == 'rework' for row in site_rows)):
        status = 'rework'
    elif item_summary:
        total = int(item_summary.get('total_items') or 0)
        completed = int(item_summary.get('completed_items') or 0)
        if total and completed >= total:
            status = 'completed'
        elif completed:
            status = 'partial'
        else:
            status = 'pending'
    elif site_rows:
        row_statuses = [row.get('status') for row in site_rows]
        completed = sum(1 for status in row_statuses if status == 'completed')
        if completed == len(row_statuses):
            status = 'completed'
        elif completed or any(status == 'partial' for status in row_statuses):
            status = 'partial'
        else:
            status = 'pending'
    elif field_status == 'completed':
        status = 'completed'
    else:
        status = 'pending'
    return {'execution_status': status, 'execution_status_cn': labels[status]}


def _ps_execution_item_summaries(db, schedule_ids):
    """Return list-safe execution facts with one bounded date x site aggregation.

    ``execution_status`` keeps its historical item-level projection. The card
    summary is deliberately separate: a task is one execution date x site and
    only completes when every active item satisfies the shared field-completion
    predicate. Older schemas keep the status projection but omit this newer
    summary instead of inventing zero counts.
    """
    target_ids = {int(schedule_id) for schedule_id in schedule_ids if schedule_id is not None}
    if not target_ids:
        return {}
    target_params = sorted(target_ids)
    target_placeholders = ','.join('?' for _ in target_params)
    has_card_columns = all(
        _table_has_column(db, table, column)
        for table, column in (
            ('insp_plans', 'generate_date'),
            ('insp_plans', 'status'),
            ('insp_plan_items', 'site_id'),
            ('insp_plan_items', 'evidence_status'),
            ('insp_plan_items', 'supplement_required_at'),
        )
    )
    if has_card_columns:
        try:
            completion_sql = _inspection_field_completion_sql(db, 'pi')
            rows = db.execute(f"""WITH active_items AS (
                    SELECT ip.plan_schedule_id AS schedule_id,
                           date(ip.generate_date) AS execution_date,
                           pi.site_id,
                           pi.evidence_status,
                           CASE WHEN {completion_sql} THEN 1 ELSE 0 END AS field_completed
                    FROM insp_plans ip
                    JOIN insp_plan_items pi ON pi.plan_id=ip.id
                    WHERE ip.plan_schedule_id IN ({target_placeholders})
                      AND ip.status!='cancelled'
                      AND COALESCE(pi.execution_status,'active')='active'
                ), site_tasks AS (
                    SELECT schedule_id, execution_date, site_id,
                           COUNT(*) AS total_items,
                           SUM(field_completed) AS completed_items,
                           SUM(CASE WHEN evidence_status='supplement_required' THEN 1 ELSE 0 END)
                               AS supplement_required_items
                    FROM active_items
                    GROUP BY schedule_id, execution_date, site_id
                ) SELECT schedule_id, SUM(total_items) AS total_items,
                           SUM(completed_items) AS completed_items,
                           COUNT(*) AS total_tasks,
                           SUM(CASE WHEN total_items>0
                                         AND completed_items=total_items
                                    THEN 1 ELSE 0 END) AS completed_tasks,
                           SUM(supplement_required_items) AS supplement_required_items
                    FROM site_tasks
                    GROUP BY schedule_id""", target_params).fetchall()
            return {
                int(row['schedule_id']): {
                    'total_items': int(row['total_items'] or 0),
                    'completed_items': int(row['completed_items'] or 0),
                    'execution_summary': {
                        'available': True,
                        'total_tasks': int(row['total_tasks'] or 0),
                        'completed_tasks': int(row['completed_tasks'] or 0),
                        'supplement_required_items': int(row['supplement_required_items'] or 0),
                    },
                }
                for row in rows if int(row['schedule_id']) in target_ids
            }
        except sqlite3.OperationalError:
            # Keep the established projection, but do not claim a trustworthy
            # date x site count on a legacy database.
            pass
    try:
        rows = db.execute(f"""SELECT ip.plan_schedule_id AS schedule_id,
                    COUNT(*) AS total_items,
                    SUM(CASE WHEN pi.result IS NOT NULL THEN 1 ELSE 0 END) AS completed_items
                FROM insp_plans ip
                JOIN insp_plan_items pi ON pi.plan_id=ip.id
                WHERE ip.plan_schedule_id IN ({target_placeholders})
                  AND COALESCE(pi.execution_status,'active')='active'
                GROUP BY ip.plan_schedule_id""", target_params).fetchall()
    except sqlite3.OperationalError:
        return {}
    return {
        int(row['schedule_id']): {
            'total_items': int(row['total_items'] or 0),
            'completed_items': int(row['completed_items'] or 0),
            'execution_summary': {},
        }
        for row in rows if int(row['schedule_id']) in target_ids
    }


def _ps_auto_flow(db, schedule):
    """审批通过后的自动流转：生成任务 + 锁定车辆 + 记录备件需求 + 通知。
    在审批事务内调用（db 由外部传入并统一 commit）。"""
    result = {'plans_created': 0, 'items_created': 0, 'vehicle_locked': 0, 'parts_reserved': 0, 'parts_planned': 0}
    # 1. 生成执行任务
    if not schedule['tasks_generated']:
        pc, ti = _ps_generate_tasks(db, schedule)
        result['plans_created'], result['items_created'] = pc, ti
        db.execute("UPDATE plan_schedules SET tasks_generated=1 WHERE id=?", (schedule['id'],))
    # 2. 锁定车辆（同一计划同一车辆合并为一条行程，避免多站/多天巡检被切碎归档）
    try:
        vehicle_days = json.loads(schedule['vehicle_days'] or '{}')
    except Exception:
        vehicle_days = {}
    vehicle_ranges = {}
    for date_str, vid in vehicle_days.items():
        if not vid or not date_str:
            continue
        vehicle_ranges.setdefault(int(vid), []).append(str(date_str)[:10])
    for vid, dates in vehicle_ranges.items():
        dates = sorted(set(dates))
        if not dates:
            continue
        start_date, end_date = dates[0], dates[-1]
        exists = db.execute("""
            SELECT id FROM vehicle_applications
            WHERE vehicle_id=? AND applicant_id=? AND reason LIKE ?
            LIMIT 1
        """, (vid, schedule['user_id'], _ps_vehicle_reason_like(schedule["id"]))).fetchone()
        if exists:
            continue
        # Approval holds a SQLite write transaction. This overlap check is the
        # final guard immediately before creating the reservation, including
        # plans owned by the same operator.
        reservation = db.execute("""
            SELECT id FROM vehicle_applications
            WHERE vehicle_id=? AND status='approved'
              AND NOT (end_at < ? OR start_at > ?)
            LIMIT 1
        """, (vid, f'{start_date} 08:00:00', f'{end_date} 18:00:00')).fetchone()
        if reservation:
            raise PlanScheduleResourceConflict('车辆时间已被已批准安排占用')
        db.execute("""
            INSERT INTO vehicle_applications (vehicle_id, applicant_id, start_at, end_at, destination, reason, status)
            VALUES (?,?,?,?,?,?,?)
        """, (vid, schedule['user_id'], f'{start_date} 08:00:00', f'{end_date} 18:00:00',
              '巡检', f'巡检计划#{schedule["id"]}用车（{start_date}至{end_date}）', 'approved'))
        result['vehicle_locked'] += 1
    # 3. 只记录计划需求，不占库；现场确认拿到实物时再扣库存。
    result['parts_planned'] = _ps_reserve_parts(db, schedule)
    # 4. 通知排程人
    requester = _plan_schedule_requester(db, schedule['id'])
    result_recipient_id = requester['operator_id'] if requester else schedule['user_id']
    result['result_notification_id'] = _create_notification(result_recipient_id, 'plan_schedule', schedule['id'],
                         f'巡检计划已通过（{_PS_FREQ_CN.get(schedule["schedule_type"], "巡检")}）',
                         f'已生成{result["plans_created"]}个巡检任务，请按计划执行。', db=db)
    return result


def _ps_rebuild_tasks_on_change(db, schedule):
    """变更通过后的任务同步：保留历史，取消未执行项，并补齐新增站点/日期。"""
    sid = schedule['id']
    kept, cancelled, added_items = 0, 0, 0
    plan_data = _ps_decode_plan_data(schedule['plan_data'])
    plan_data = _ps_validate_execution_sites(db, schedule['user_id'], plan_data)
    plan_data = _ps_validate_item_selections(db, plan_data, schedule['schedule_type'])
    existing = db.execute("SELECT id, generate_date FROM insp_plans WHERE plan_schedule_id=? AND status != 'cancelled'", (sid,)).fetchall()
    for ep in existing:
        day_data = plan_data.get(ep['generate_date']) or {}
        raw_sites = day_data.get('sites') or [] if isinstance(day_data, dict) else day_data or []
        desired_sites = {int(site_id) for site_id in raw_sites if str(site_id).isdigit()}
        started = db.execute(
            "SELECT id FROM insp_plan_items WHERE plan_id=? AND result IS NOT NULL LIMIT 1",
            (ep['id'],)).fetchone()
        if started:
            # 已开始的日执行包继续保留；只取消被移出的、尚未执行的站点检查项。
            if desired_sites:
                placeholders = ','.join('?' * len(desired_sites))
                cur = db.execute(f"UPDATE insp_plan_items SET execution_status='cancelled' WHERE plan_id=? AND result IS NULL AND site_id NOT IN ({placeholders}) AND COALESCE(execution_status,'active')='active'", [ep['id'], *desired_sites])
            else:
                cur = db.execute("UPDATE insp_plan_items SET execution_status='cancelled' WHERE plan_id=? AND result IS NULL", (ep['id'],))
            cancelled += cur.rowcount
            existing_sites = {row['site_id'] for row in db.execute(
                "SELECT DISTINCT site_id FROM insp_plan_items WHERE plan_id=?", (ep['id'],)).fetchall()}
            selected_by_site = day_data.get('inspection_items') or {} if isinstance(day_data, dict) else {}
            for added_site_id in desired_sites - existing_sites:
                selected = selected_by_site.get(str(added_site_id)) if isinstance(selected_by_site, dict) else None
                added_items += _ps_add_site_tasks(db, ep['id'], added_site_id, schedule['schedule_type'], selected)
            db.execute("UPDATE insp_plans SET schedule_version=? WHERE id=?", (schedule['version'], ep['id']))
            kept += 1
            continue
        # 未开始日包仅作废，不物理删除，保留原审批与变更证据。
        db.execute("UPDATE insp_plan_items SET execution_status='cancelled' WHERE plan_id=?", (ep['id'],))
        db.execute("UPDATE insp_plans SET status='cancelled' WHERE id=?", (ep['id'],))
        cancelled += 1
    fresh = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
    created, items = _ps_generate_tasks(db, fresh)
    db.execute("UPDATE plan_schedules SET tasks_generated=1 WHERE id=?", (sid,))
    return {'kept': kept, 'cancelled': cancelled, 'plans_created': created,
            'items_created': items + added_items, 'items_added_to_started_plans': added_items}


@app.route('/api/cockpit/operations-today')
def api_cockpit_operations_today():
    """管理者今日运维视图：以人员为主线聚合到站、巡检和工单事实。"""
    user = g.current_user
    today = datetime.now().strftime('%Y-%m-%d')
    manager_roles = {'admin', 'manager', 'reviewer'}
    with get_db() as db:
        roles = set(_roles_for_user(db, user['id'], user.get('role') or 'operator'))
        people_rows = _active_operator_rows(
            db, None if roles & manager_roles else user['id'])

        people = []
        attention = []
        for person in people_rows:
            user_id = person['id']
            real_name = person['real_name'] or f'人员#{user_id}'
            approved_schedules = db.execute("""SELECT COUNT(*) AS n FROM plan_schedules
                WHERE user_id=? AND status='approved' AND period_start<=? AND period_end>=?""",
                (user_id, today, today)).fetchone()['n']
            execution_rows = db.execute("""SELECT p.id AS plan_id, p.plan_name, p.status AS plan_status,
                       i.id AS item_id, i.site_id, s.name AS site_name, i.result, i.completed_at,
                       COALESCE(i.required_photos,0) AS required_photos,
                       COALESCE(i.actual_photos,0) AS actual_photos
                FROM insp_plans p
                LEFT JOIN insp_plan_items i ON i.plan_id=p.id
                    AND COALESCE(i.execution_status,'active')='active'
                LEFT JOIN sites s ON s.id=i.site_id
                WHERE p.assignee_id=? AND p.generate_date=? AND p.status IN ('active','completed')
                ORDER BY p.id, i.id""", (user_id, today)).fetchall()
            item_rows = [row for row in execution_rows if row['item_id'] is not None]
            total_items = len(item_rows)
            completed_items = sum(1 for row in item_rows if row['result'] is not None)
            abnormal_items = sum(1 for row in item_rows if row['result'] == 'abnormal')
            missing_photos = sum(
                max(int(row['required_photos'] or 0) - int(row['actual_photos'] or 0), 0)
                for row in item_rows if row['result'] is not None
            )
            assigned_sites = {}
            for row in item_rows:
                if row['site_id'] is not None:
                    assigned_sites[row['site_id']] = row['site_name'] or f"站点#{row['site_id']}"

            inspection_checkins = db.execute("""SELECT ic.site_id,
                       COALESCE(NULLIF(ic.site_name,''), s.name, '未知站点') AS site_name,
                       ic.check_time
                FROM inspection_checkins ic LEFT JOIN sites s ON s.id=ic.site_id
                WHERE ic.user_id=? AND date(ic.check_time)=?
                ORDER BY ic.check_time""", (user_id, today)).fetchall()
            workorders = db.execute("""SELECT w.order_no, w.site_id, s.name AS site_name, w.title,
                       w.status, w.created_at, w.check_in_time, w.resolved_at
                FROM work_orders w LEFT JOIN sites s ON s.id=w.site_id
                WHERE w.assignee=? AND (
                    date(w.created_at)=? OR date(w.check_in_time)=? OR date(w.resolved_at)=?
                    OR w.status NOT IN ('closed','resolved'))
                ORDER BY COALESCE(w.check_in_time,w.created_at)""",
                (real_name, today, today, today)).fetchall()
            open_workorders = [row for row in workorders if row['status'] not in ('closed', 'resolved')]

            carryover = db.execute("""SELECT COUNT(*) AS n FROM insp_plans p
                WHERE p.assignee_id=? AND p.generate_date<? AND p.status='active'
                  AND EXISTS (SELECT 1 FROM insp_plan_items i WHERE i.plan_id=p.id
                    AND i.result IS NULL AND COALESCE(i.execution_status,'active')='active')""",
                (user_id, today)).fetchone()['n']

            visit_events = [{
                'event_type': 'inspection_checkin', 'event_label': '到达站点',
                'site_id': row['site_id'], 'site_name': row['site_name'],
                'occurred_at': row['check_time'], 'detail': '巡检现场作业开始',
            } for row in inspection_checkins]
            visit_events.extend({
                'event_type': 'workorder_checkin', 'event_label': '工单到场',
                'site_id': row['site_id'], 'site_name': row['site_name'] or f"站点#{row['site_id']}",
                'occurred_at': row['check_in_time'], 'detail': row['order_no'],
            } for row in workorders if row['check_in_time'] and row['check_in_time'][:10] == today)
            visit_events.sort(key=lambda event: event['occurred_at'] or '')

            completed_by_site = {}
            for row in item_rows:
                if not row['completed_at'] or row['completed_at'][:10] != today:
                    continue
                key = row['site_id']
                current = completed_by_site.get(key)
                if current is None or row['completed_at'] > current['occurred_at']:
                    completed_by_site[key] = {
                        'event_type': 'inspection_progress', 'event_label': '提交巡检项',
                        'site_id': row['site_id'], 'site_name': row['site_name'] or f"站点#{row['site_id']}",
                        'occurred_at': row['completed_at'], 'detail': row['plan_name'],
                    }
            timeline = visit_events + list(completed_by_site.values())
            timeline.extend({
                'event_type': 'workorder_resolved', 'event_label': '工单处理完成',
                'site_id': row['site_id'], 'site_name': row['site_name'] or f"站点#{row['site_id']}",
                'occurred_at': row['resolved_at'], 'detail': row['order_no'],
            } for row in workorders if row['resolved_at'] and row['resolved_at'][:10] == today)
            timeline.sort(key=lambda event: event['occurred_at'] or '')

            first_checkin_at = visit_events[0]['occurred_at'] if visit_events else None
            latest_visit = visit_events[-1] if visit_events else None
            latest_activity = timeline[-1] if timeline else None
            latest_site_id = latest_visit['site_id'] if latest_visit else None
            site_items = [row for row in item_rows if row['site_id'] == latest_site_id]
            site_completed = sum(1 for row in site_items if row['result'] is not None)
            checked_open_order = any(
                row['check_in_time'] and row['check_in_time'][:10] == today
                for row in open_workorders
            )
            inspection_open = total_items > completed_items
            has_task = bool(approved_schedules or total_items or open_workorders)
            if not has_task and carryover:
                status_code, status_label = 'carryover', '仅有历史遗留'
            elif not has_task:
                status_code, status_label = 'no_task', '今日无任务'
            elif not first_checkin_at:
                status_code, status_label = 'no_checkin', '尚无到站记录'
            elif inspection_open and checked_open_order:
                status_code, status_label = 'mixed', '巡检与工单处理中'
            elif checked_open_order:
                status_code, status_label = 'workorder', '工单处理中'
            elif inspection_open:
                status_code, status_label = 'inspection', '巡检中'
            else:
                status_code, status_label = 'completed', '今日完成'

            reasons = []
            if has_task and not first_checkin_at:
                if assigned_sites:
                    no_checkin_detail = f'今日安排 {len(assigned_sites)} 个站点'
                elif open_workorders:
                    no_checkin_detail = f'{len(open_workorders)} 个开放工单待处理'
                else:
                    no_checkin_detail = '已有计划，尚未形成现场记录'
                if carryover:
                    no_checkin_detail += f'；另有 {carryover} 个历史执行包未完成'
                reasons.append({'type': 'no_checkin', 'label': '尚无到站记录',
                                'detail': no_checkin_detail})
            if abnormal_items:
                reasons.append({'type': 'abnormal', 'label': f'{abnormal_items} 个异常检查项',
                                'detail': '请结合关联工单查看处置进度'})
            if missing_photos:
                reasons.append({'type': 'missing_photos', 'label': f'{missing_photos} 张必拍照片未确认',
                                'detail': '以服务器已接收数量为准'})
            if carryover and not (has_task and not first_checkin_at):
                reasons.append({'type': 'carryover', 'label': f'{carryover} 个历史执行包未完成',
                                'detail': '仍有遗留检查项'})
            for reason in reasons:
                attention.append({'user_id': user_id, 'real_name': real_name, **reason})

            people.append({
                'user_id': user_id, 'real_name': real_name, 'role': person['role'],
                'has_task': has_task, 'approved_schedules': int(approved_schedules or 0),
                'assigned_site_count': len(assigned_sites),
                'first_checkin_at': first_checkin_at,
                'status_code': status_code, 'status_label': status_label,
                'latest_site_id': latest_site_id,
                'latest_site_name': latest_visit['site_name'] if latest_visit else None,
                'latest_site_checkin_at': latest_visit['occurred_at'] if latest_visit else None,
                'today_items': total_items, 'completed_items': completed_items,
                'completion_rate': round(completed_items / total_items * 100, 1) if total_items else 0,
                'current_site_items': len(site_items), 'current_site_completed': site_completed,
                'abnormal_items': abnormal_items, 'missing_photos': missing_photos,
                'open_workorders': len(open_workorders),
                'active_workorder': next(({
                    'order_no': row['order_no'], 'title': row['title'], 'status': row['status'],
                    'site_name': row['site_name'] or f"站点#{row['site_id']}"
                } for row in open_workorders if row['check_in_time']), None),
                'carryover_executions': int(carryover or 0),
                'attention_reasons': reasons,
                'route': visit_events,
                'last_activity_at': latest_activity['occurred_at'] if latest_activity else None,
                'last_activity_label': latest_activity['event_label'] if latest_activity else None,
                'timeline': timeline,
            })

        priority = {'mixed': 0, 'workorder': 1, 'inspection': 2, 'no_checkin': 3,
                    'carryover': 4, 'completed': 5, 'no_task': 6}
        people.sort(key=lambda row: (0 if row['attention_reasons'] else 1,
                                     priority.get(row['status_code'], 9), row['real_name']))
        task_people = [row for row in people if row['has_task']]
        summary = {
            'people_total': len(people),
            'people_with_tasks': len(task_people),
            'people_checked_in': sum(1 for row in task_people if row['first_checkin_at']),
            'people_working': sum(1 for row in task_people if row['status_code'] in ('inspection', 'workorder', 'mixed')),
            'people_attention': len({item['user_id'] for item in attention}),
            'people_completed': sum(1 for row in task_people if row['status_code'] == 'completed'),
        }
        return jsonify({'date': today, 'refreshed_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                        'summary': summary, 'attention': attention, 'people': people})


@app.route('/api/plan-schedules/overview')
def api_plan_schedules_overview():
    """管理者团队执行总览：计划安排、现场执行、异常与工单放在同一人员行中。
    非管理者只返回本人，避免为查看总览额外建设第二套看板。"""
    u = g.current_user
    today = datetime.now().strftime('%Y-%m-%d')
    with get_db() as db:
        people = _active_operator_rows(
            db, None if _has_any_role(u, 'admin', 'reviewer') else u['id'])
        rows = []
        for person in people:
            uid = person['id']
            current = db.execute("""SELECT COUNT(*) AS n FROM plan_schedules
                WHERE user_id=? AND status='approved' AND period_start<=? AND period_end>=?""", (uid, today, today)).fetchone()['n']
            pending = db.execute("""SELECT COUNT(*) AS n FROM plan_schedules
                WHERE user_id=? AND status IN ('submitted','change_submitted')""", (uid,)).fetchone()['n']
            execution = db.execute("""SELECT COUNT(*) AS total,
                    COALESCE(SUM(CASE WHEN i.result IS NOT NULL THEN 1 ELSE 0 END),0) AS completed,
                    COALESCE(SUM(CASE WHEN i.result='abnormal' THEN 1 ELSE 0 END),0) AS abnormal
                FROM insp_plans p LEFT JOIN insp_plan_items i ON i.plan_id=p.id
                WHERE p.assignee_id=? AND p.generate_date=? AND p.status IN ('active','completed')
                  AND COALESCE(i.execution_status,'active')='active'""", (uid, today)).fetchone()
            open_orders = db.execute("""SELECT COUNT(*) AS n FROM work_orders
                WHERE assignee=? AND status NOT IN ('closed','resolved')""", (person['real_name'],)).fetchone()['n']
            overdue = db.execute("""SELECT COUNT(*) AS n FROM insp_plans p
                WHERE p.assignee_id=? AND p.generate_date<? AND p.status='active'
                  AND EXISTS (SELECT 1 FROM insp_plan_items i WHERE i.plan_id=p.id
                              AND i.result IS NULL AND COALESCE(i.execution_status, 'active')='active')""",
                (uid, today)).fetchone()['n']
            coverage_exceptions = db.execute("""SELECT COUNT(*) AS n FROM plan_schedules
                WHERE user_id=? AND status IN ('submitted','change_submitted')
                  AND COALESCE(coverage_exception_reason, '') != ''""", (uid,)).fetchone()['n']
            snapshots = db.execute("""SELECT validation_snapshot FROM plan_schedules
                WHERE user_id=? AND status IN ('submitted','change_submitted')
                  AND validation_snapshot IS NOT NULL""", (uid,)).fetchall()
            resource_blocks = 0
            for snapshot in snapshots:
                try:
                    errors = json.loads(snapshot['validation_snapshot'] or '{}').get('errors') or []
                    resource_blocks += sum(1 for error in errors if '车辆' in error or '库存' in error)
                except (TypeError, ValueError):
                    continue
            total, completed = int(execution['total'] or 0), int(execution['completed'] or 0)
            rows.append({
                'user_id': uid, 'real_name': person['real_name'], 'role': person['role'],
                'approved_schedules': current, 'pending_schedules': pending,
                'today_items': total, 'completed_items': completed,
                'completion_rate': round(completed / total * 100, 1) if total else 0,
                'abnormal_items': int(execution['abnormal'] or 0), 'open_workorders': int(open_orders or 0),
                'overdue_executions': int(overdue or 0),
                'coverage_exceptions': int(coverage_exceptions or 0),
                'resource_blocks': resource_blocks,
            })
        summary = {
            'people': len(rows), 'on_schedule': sum(1 for r in rows if r['approved_schedules']),
            'pending_approval': sum(r['pending_schedules'] for r in rows),
            'today_items': sum(r['today_items'] for r in rows),
            'completed_items': sum(r['completed_items'] for r in rows),
            'abnormal_items': sum(r['abnormal_items'] for r in rows),
            'open_workorders': sum(r['open_workorders'] for r in rows),
            'overdue_executions': sum(r['overdue_executions'] for r in rows),
            'coverage_exceptions': sum(r['coverage_exceptions'] for r in rows),
            'resource_blocks': sum(r['resource_blocks'] for r in rows),
        }
        summary['completion_rate'] = round(summary['completed_items'] / summary['today_items'] * 100, 1) if summary['today_items'] else 0
        return jsonify({'date': today, 'summary': summary, 'people': rows})


@app.route('/api/plan-schedules', methods=['GET'])
def api_plan_schedules_list():
    """巡检计划列表（调度层）。管理者看全部，一线只看自己。
    筛选：user_id / schedule_type / status / period_start（周期重叠过滤）"""
    u = g.current_user
    user_id = request.args.get('user_id')
    schedule_type = request.args.get('schedule_type')
    status = request.args.get('status')
    period_start = request.args.get('period_start')
    mine = request.args.get('mine', '').lower() in ('1', 'true', 'yes')
    attention = request.args.get('attention', '')
    if attention not in ('', 'overdue', 'coverage', 'resource'):
        return jsonify({'error': '无效的关注项筛选'}), 400
    q = '''SELECT ps.*, u.real_name as user_name, u2.real_name as approver_name
           FROM plan_schedules ps
           LEFT JOIN users u ON ps.user_id = u.id
           LEFT JOIN users u2 ON ps.approver_id = u2.id WHERE 1=1'''
    params = []
    # The mobile “My plans” view explicitly opts into personal scope, including
    # users who also hold an admin/reviewer role. PC management keeps team scope.
    if mine or not _has_any_role(u, 'admin', 'reviewer'):
        q += ' AND ps.user_id=?'
        params.append(u['id'])
    if user_id:
        q += ' AND ps.user_id=?'; params.append(user_id)
    if schedule_type:
        q += ' AND ps.schedule_type=?'; params.append(schedule_type)
    if status:
        q += ' AND ps.status=?'; params.append(status)
    if attention == 'overdue':
        # 计划本身已审批不代表按时执行。仅展示仍有有效未完成项的逾期执行包。
        q += ''' AND EXISTS (
            SELECT 1 FROM insp_plans ip WHERE ip.plan_schedule_id=ps.id
              AND ip.generate_date < date('now','localtime') AND ip.status='active'
              AND EXISTS (SELECT 1 FROM insp_plan_items pi WHERE pi.plan_id=ip.id
                          AND pi.result IS NULL AND COALESCE(pi.execution_status, 'active')='active')
        )'''
    elif attention == 'coverage':
        q += " AND ps.status IN ('submitted','change_submitted') AND COALESCE(ps.coverage_exception_reason, '') != ''"
    if period_start:
        # 周期重叠：计划的周期与查询周期相交
        q += ' AND ps.period_start <= date(?, "+6 days") AND ps.period_end >= ?'
        params.append(period_start, period_start)
    q += ' ORDER BY ps.period_start DESC, ps.created_at DESC'
    with get_db() as db:
        rows = []
        for raw in db.execute(q, params).fetchall():
            item = _ps_parse_row(raw)
            item['field_status'] = _ps_sync_field_status(db, item['id'])
            if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
                current = db.execute("SELECT field_completed_at FROM plan_schedules WHERE id=?",
                                     (item['id'],)).fetchone()
                item['field_completed_at'] = current['field_completed_at'] if current else None
            item['execution_completed'] = item['field_status'] == 'completed'
            rows.append(item)
        item_summaries = (_ps_execution_item_summaries(db, [item['id'] for item in rows])
                          if rows else {})
        for item in rows:
            item['execution_summary'] = (
                item_summaries.get(item['id'], {}).get('execution_summary') or {})
            item.update(_ps_schedule_execution_status(
                item.get('status'), item['field_status'],
                item_summary=item_summaries.get(item['id'])))
        db.commit()
    if attention == 'resource':
        # 资源冲突以提交时保存的校验快照为准，避免仅凭当前库存造成误判。
        filtered = []
        for row in rows:
            try:
                errors = (row.get('validation_snapshot') or {}).get('errors') or []
            except AttributeError:
                errors = []
            if any('车辆' in error or '库存' in error for error in errors):
                filtered.append(row)
        rows = filtered
    for r in rows:
        # 附加展示用汇总：天数/站点数
        days = [d for d, v in (r.get('plan_data') or {}).items()
                if isinstance(v, dict) and (v.get('sites'))]
        site_set = set()
        for d, v in (r.get('plan_data') or {}).items():
            if isinstance(v, dict):
                site_set.update(v.get('sites') or [])
        r['day_count'] = len(days)
        r['site_count'] = len(site_set)
        r['schedule_type_cn'] = _PS_FREQ_CN.get(r['schedule_type'], r['schedule_type'])
        if attention == 'overdue':
            r['attention_reason'] = '存在逾期且未完成的执行包'
        elif attention == 'coverage':
            r['attention_reason'] = '周巡检漏站，等待管理者确认例外原因'
        elif attention == 'resource':
            r['attention_reason'] = '车辆或库存校验未通过'
    return jsonify(rows)


@app.route('/api/plan-schedules', methods=['POST'])
def api_plan_schedules_create():
    """新建巡检计划（草稿或直接提交）。
    body: {user_id?, schedule_type, period_start, period_end, plan_data, vehicle_days?, spare_parts?, work_order_ids?, remarks?, submit?}"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    intent_key = str(data.get('_idempotency_key') or '').strip()
    if len(intent_key) > 160:
        return jsonify({'error': '创建幂等键无效', 'code': 'PLAN_CREATE_KEY_INVALID'}), 400
    intent_hash = hashlib.sha256(json.dumps(
        {key: value for key, value in data.items() if key != '_idempotency_key'},
        sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')).hexdigest()
    if intent_key:
        with get_db() as intent_db:
            if _table_exists(intent_db, 'plan_creation_intents'):
                prior = intent_db.execute('SELECT * FROM plan_creation_intents WHERE intent_key=?', (intent_key,)).fetchone()
                if prior and (prior['actor_id'] != u['id'] or prior['endpoint'] != 'POST /api/plan-schedules'
                              or prior['payload_hash'] != intent_hash):
                    return jsonify({'error': '创建幂等键与原用户或表单内容不一致',
                                    'code': 'PLAN_CREATE_INTENT_CONFLICT'}), 409
    try:
        schedule_type = _inspection_frequency(data.get('schedule_type'))
    except ValueError as exc:
        return jsonify({'error': str(exc), 'code': 'PLAN_SCHEDULE_TYPE_INVALID'}), 400
    period_start = data.get('period_start')
    period_end = data.get('period_end')
    if not period_start or not period_end:
        return jsonify({'error': '缺少周期起止日期'}), 400
    plan_data = data.get('plan_data') or {}
    if not isinstance(plan_data, dict):
        return jsonify({'error': 'plan_data 必须是日期到安排的对象',
                        'code': 'PLAN_DATA_INVALID'}), 400
    user_id = data.get('user_id') or u['id']
    try:
        user_id = int(user_id)
    except (TypeError, ValueError):
        return jsonify({'error': '计划执行人参数无效', 'code': 'PLAN_EXECUTION_USER_INVALID'}), 400
    # 非管理者只能给自己排程；管理员代排时仍按目标执行人的 user_sites 校验。
    if not _has_any_role(u, 'admin') and user_id != u['id']:
        return jsonify({'error': '只能为自己创建巡检计划'}), 403
    vehicle_id = data.get('vehicle_id')
    vehicle_days = data.get('vehicle_days') if 'vehicle_days' in data else {}
    spare_parts = data.get('spare_parts') or []
    work_order_ids = data.get('work_order_ids') or []
    if not isinstance(spare_parts, list) or not isinstance(work_order_ids, list):
        return jsonify({'error': '计划资源格式无效', 'code': 'PLAN_RESOURCE_DATA_INVALID'}), 400
    coverage_exception_reason = (data.get('coverage_exception_reason') or '').strip()
    vehicle_exception_reason = (data.get('vehicle_exception_reason') or '').strip()
    no_vehicle_required = (data.get('no_vehicle_required') in (True, 1, '1', 'true')
                           if 'no_vehicle_required' in data
                           else bool(vehicle_exception_reason and vehicle_id in (None, '')))
    supplied_vehicle_days = data.get('vehicle_days') if isinstance(data.get('vehicle_days'), dict) else {}
    if no_vehicle_required and (vehicle_id not in (None, '') or any(supplied_vehicle_days.values())):
        return jsonify({'error': '已选择无需用车，不能同时安排车辆',
                        'code': 'PLAN_VEHICLE_MODE_CONFLICT',
                        'field': 'no_vehicle_required'}), 400
    if no_vehicle_required:
        vehicle_id = None
        vehicle_days = {}
    submit = bool(data.get('submit'))
    try:
        period_start, period_end, outside_dates = _ps_validate_date_contract(
            period_start, period_end, plan_data, vehicle_days)
    except PlanScheduleSiteScopeError as exc:
        return _ps_site_scope_error_response(exc)
    if outside_dates:
        return jsonify({
            'error': '执行日期超出计划周期', 'code': 'PLAN_DATES_OUTSIDE_PERIOD',
            'dates': outside_dates,
        }), 400
    with get_db() as db:
        # Serialize creation and replay before overlap checks; commit intent with all effects.
        db.execute('BEGIN IMMEDIATE')
        if intent_key:
            db.execute("""CREATE TABLE IF NOT EXISTS plan_creation_intents (
                intent_key TEXT PRIMARY KEY, actor_id INTEGER NOT NULL,
                endpoint TEXT NOT NULL, payload_hash TEXT NOT NULL,
                schedule_id INTEGER NOT NULL, response_json TEXT NOT NULL)""")
            intent = db.execute('SELECT * FROM plan_creation_intents WHERE intent_key=?', (intent_key,)).fetchone()
            if intent:
                if (intent['actor_id'] != u['id'] or intent['endpoint'] != 'POST /api/plan-schedules'
                        or intent['payload_hash'] != intent_hash):
                    return jsonify({'error': '创建幂等键与原用户或表单内容不一致',
                                    'code': 'PLAN_CREATE_INTENT_CONFLICT'}), 409
                existing = db.execute("""SELECT ps.*, u.real_name AS user_name
                    FROM plan_schedules ps LEFT JOIN users u ON u.id=ps.user_id WHERE ps.id=?""",
                    (intent['schedule_id'],)).fetchone()
                if not existing:
                    return jsonify({'error': '原创建计划已不存在，不能重建，请刷新计划列表',
                                    'code': 'PLAN_CREATE_TARGET_GONE'}), 409
                response = json.loads(intent['response_json'])
                response.update(_ps_parse_row(existing))
                return jsonify(response), 200
        if schedule_type != 'weekly':
            return jsonify({'error': '新建计划仅支持周计划，月检和季检请按需附加',
                            'code': 'PLAN_CREATE_FREQUENCY_INVALID', 'field': 'schedule_type'}), 400
        if not _ensure_plan_schedule_vehicle_column(db):
            return jsonify({'error': '计划数据结构缺少 vehicle_id，无法保存，请先完成数据库迁移',
                            'code': 'PLAN_SCHEMA_UNAVAILABLE'}), 503
        try:
            plan_data = _ps_validate_execution_sites(db, user_id, plan_data)
            plan_data = _ps_validate_item_selections(db, plan_data, schedule_type)
            vehicle_days = _ps_expand_plan_vehicle(plan_data, vehicle_id, vehicle_days)
            vehicle_id = _ps_plan_vehicle_id(vehicle_days)
            vehicle_days, _ = _ps_prune_vehicle_days(
                plan_data, vehicle_days, period_start, period_end)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        vehicle_exception_reason = _ps_normalize_vehicle_exception_reason(
            vehicle_id, vehicle_exception_reason)
        # 同用户同类型周期重叠检查（防止重复排程）
        overlap = _ps_period_overlap(db, user_id, schedule_type, period_start, period_end)
        if overlap:
            return jsonify({'error': f'该周期已有计划（{overlap["period_start"]} ~ {overlap["period_end"]}），请勿重复创建'}), 409
        v = _ps_validate(
            db, user_id, schedule_type, period_start, period_end, plan_data, vehicle_days,
            vehicle_exception_reason=vehicle_exception_reason,
            no_vehicle_required=no_vehicle_required)
        if submit and not v['ok']:
            return jsonify({'error': '；'.join(v['errors']), 'validation': v}), 400
        coverage_error = _ps_coverage_exception_required(v, schedule_type, coverage_exception_reason)
        if submit and coverage_error:
            return jsonify({'error': coverage_error, 'validation': v}), 400
        status = 'submitted' if submit else 'draft'
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        cur = db.execute("""
            INSERT INTO plan_schedules
                (user_id, schedule_type, period_start, period_end, plan_data, vehicle_days, vehicle_id,
                 spare_parts, work_order_ids, status, remarks, submitted_at, coverage_exception_reason,
                 vehicle_exception_reason, no_vehicle_required, validation_snapshot)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (user_id, schedule_type, period_start, period_end,
              json.dumps(plan_data, ensure_ascii=False), json.dumps(vehicle_days, ensure_ascii=False),
              vehicle_id,
              json.dumps(spare_parts, ensure_ascii=False), json.dumps(work_order_ids, ensure_ascii=False),
              status, data.get('remarks', ''), now if submit else None, coverage_exception_reason,
              vehicle_exception_reason, int(no_vehicle_required),
              json.dumps(v, ensure_ascii=False) if submit else None))
        _ps_record_event(db, cur.lastrowid, 1, 'submitted' if submit else 'created', u['id'],
                         {'validation': v, 'coverage_exception_reason': coverage_exception_reason,
                          'vehicle_exception_reason': vehicle_exception_reason,
                          'no_vehicle_required': no_vehicle_required})
        sid = cur.lastrowid
        if submit:
            # 通知审批者
            for approver_id in _ps_approver_ids(db):
                _create_notification(approver_id, 'plan_schedule', sid,
                                     f'有新的巡检计划待审批', f'{_PS_FREQ_CN.get(schedule_type, "巡检")}计划（{period_start} ~ {period_end}）已提交，请审批。', db=db)
        row = db.execute("""
            SELECT ps.*, u.real_name as user_name FROM plan_schedules ps
            LEFT JOIN users u ON ps.user_id=u.id WHERE ps.id=?""", (sid,)).fetchone()
        result = _ps_parse_row(row)
        draft_issues = list(v['errors'])
        if coverage_error:
            draft_issues.append(coverage_error)
        result.update({
            'validation': v,
            'draft_issue_count': 0 if submit else len(draft_issues),
            'draft_issues': [] if submit else draft_issues,
        })
        if intent_key:
            db.execute("""INSERT INTO plan_creation_intents
                (intent_key,actor_id,endpoint,payload_hash,schedule_id,response_json)
                VALUES (?,?,?,?,?,?)""", (intent_key, u['id'], 'POST /api/plan-schedules', intent_hash,
                                         sid, json.dumps(result, ensure_ascii=False)))
        db.commit()
        return jsonify(result), 201


@app.route('/api/plan-schedules/<int:sid>', methods=['GET'])
def api_plan_schedules_detail(sid):
    """计划详情：含站点信息映射（名称/经纬度，供前端渲染站点卡与路线）"""
    with get_db() as db:
        row = db.execute("""
            SELECT ps.*, u.real_name as user_name, u2.real_name as approver_name
            FROM plan_schedules ps
            LEFT JOIN users u ON ps.user_id=u.id
            LEFT JOIN users u2 ON ps.approver_id=u2.id WHERE ps.id=?""", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        r = _ps_parse_row(row)
        r['field_status'] = _ps_sync_field_status(db, sid)
        cancellation = _ps_cancellation_capability(db, row, g.current_user)
        r['can_cancel'] = cancellation['allowed']
        r['cancel_block_reason'] = cancellation['reason']
        r['cancellation'] = None
        if r.get('status') == 'cancelled' and _table_exists(db, 'plan_schedule_events'):
            event = db.execute("""SELECT e.*, u.real_name AS operator_name
                FROM plan_schedule_events e LEFT JOIN users u ON u.id=e.operator_id
                WHERE e.schedule_id=? AND e.event_type='cancelled' ORDER BY e.id DESC LIMIT 1""", (sid,)).fetchone()
            if event:
                try:
                    payload = json.loads(event['payload'] or '{}')
                except (TypeError, ValueError):
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}
                r['cancellation'] = {'reason': payload.get('reason', ''),
                    'operator_id': event['operator_id'], 'operator_name': event['operator_name'] or '',
                    'occurred_at': event['created_at'] if 'created_at' in event.keys() else None}
        if _table_has_column(db, 'plan_schedules', 'field_completed_at'):
            current = db.execute("SELECT field_completed_at FROM plan_schedules WHERE id=?", (sid,)).fetchone()
            r['field_completed_at'] = current['field_completed_at'] if current else None
        r['execution_completed'] = r['field_status'] == 'completed'
        db.commit()
        site_ids = set()
        day_count = 0
        for day_data in (r.get('plan_data') or {}).values():
            if isinstance(day_data, dict):
                day_sites = day_data.get('sites') or []
                if day_sites:
                    day_count += 1
                    site_ids.update(day_sites)
        # 详情接口与列表接口使用相同的排程口径，前端不能据缺失字段误报“未安排站点”。
        r['day_count'] = day_count
        r['site_count'] = len(site_ids)
        site_map = {}
        if site_ids:
            for s in db.execute(
                    f"SELECT id, name, code, gps_lat as lat, gps_lng as lng, type, status FROM sites WHERE id IN ({','.join('?'*len(site_ids))})",
                    list(site_ids)).fetchall():
                site_map[s['id']] = dict(s)
        r['site_map'] = site_map
        # 草稿阶段尚未生成 insp_plan_items，仍返回模板上下文，避免编辑时误以为检查模板丢失。
        template_context = []
        try:
            template_frequency = _inspection_frequency(r.get('schedule_type'))
        except ValueError:
            template_frequency = None
        if site_ids and template_frequency:
            try:
                placeholders = ','.join('?' * len(site_ids))
                item_columns = {
                    column['name'] for column in
                    db.execute('PRAGMA table_info(inspection_template_items)').fetchall()
                }
                item_status = " AND COALESCE(iti.status, 'active')='active'" \
                    if 'status' in item_columns else ''
                rows = db.execute(f"""SELECT s.id AS site_id, s.name AS site_name,
                            t.template_name, t.description, COUNT(iti.id) AS item_count
                        FROM sites s
                        JOIN inspection_templates t ON t.status='active'
                            AND CASE WHEN LOWER(COALESCE(t.frequency,''))='annual' THEN 'yearly'
                                     ELSE LOWER(COALESCE(t.frequency,'')) END=?
                        LEFT JOIN inspection_template_items iti ON iti.template_id=t.id{item_status}
                        WHERE s.id IN ({placeholders})
                        GROUP BY s.id, s.name, t.id
                        ORDER BY s.name, t.sort_order""", [template_frequency] + list(site_ids)).fetchall()
                template_context = [dict(x) for x in rows if x['template_name']]
            except sqlite3.OperationalError:
                pass  # 兼容尚未迁移巡检 V2 模板表的历史库。
        r['template_context'] = template_context
        if r.get('schedule_type') == 'weekly' and r.get('status') in {'draft', 'rejected', 'submitted', 'modifying', 'change_submitted'}:
            selected_context = []
            for date_str, day in (r.get('plan_data') or {}).items():
                if not isinstance(day, dict):
                    continue
                for site_id in day.get('sites') or []:
                    selections = day.get('inspection_items')
                    selected = selections.get(str(site_id)) if isinstance(selections, dict) else None
                    candidates = _ps_site_template_items(db, site_id, 'weekly', include_weekly_optional=selected is not None)
                    selected_ids = set(selected) if selected is not None else None
                    grouped = {}
                    for item in candidates:
                        if selected_ids is not None and int(item['id']) not in selected_ids:
                            continue
                        frequency = item.get('template_frequency') or 'weekly'
                        grouped.setdefault(frequency, []).append(item)
                    for frequency, items in grouped.items():
                        selected_context.append({
                            'date': date_str, 'site_id': site_id,
                            'site_name': (site_map.get(site_id) or {}).get('name', ''),
                            'frequency': frequency, 'frequency_cn': _PS_FREQ_CN.get(frequency, frequency),
                            'template_name': _PS_FREQ_CN.get(frequency, frequency) + '检查内容',
                            'item_count': len(items), 'items': [dict(item, frequency=frequency) for item in items],
                        })
            r['template_context'] = selected_context
        if r.get('status') not in {'draft', 'rejected', 'submitted', 'modifying', 'change_submitted'} and _table_has_column(db, 'insp_plan_items', 'frequency'):
            snapshot_context = db.execute("""SELECT date(ip.generate_date) AS date, pi.site_id,
                    s.name AS site_name, pi.frequency, COUNT(*) AS item_count
                FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id
                LEFT JOIN sites s ON s.id=pi.site_id
                WHERE ip.plan_schedule_id=? AND COALESCE(pi.execution_status,'active')='active'
                    AND ip.status!='cancelled'
                GROUP BY date(ip.generate_date), pi.site_id, pi.frequency
                ORDER BY date(ip.generate_date), pi.site_id, pi.frequency""", (sid,)).fetchall()
            if snapshot_context:
                r['template_context'] = [dict(item, frequency_cn=_PS_FREQ_CN.get(item['frequency'], item['frequency']),
                    template_name=_PS_FREQ_CN.get(item['frequency'], item['frequency'])) for item in snapshot_context]
        # 出发前信息：移动端不能要求一线人员再切换车辆/库存/工单页面核对。
        vehicle_ids = {int(v) for v in (r.get('vehicle_days') or {}).values() if str(v).isdigit()}
        vehicle_map = {}
        if vehicle_ids:
            for vehicle in db.execute(
                    f"SELECT id, plate_no, model, status FROM vehicles WHERE id IN ({','.join('?' * len(vehicle_ids))})",
                    list(vehicle_ids)).fetchall():
                vehicle_map[vehicle['id']] = dict(vehicle)
        r['vehicle_map'] = vehicle_map

        r['resource_parts'] = [dict(part) for part in db.execute("""
            SELECT pr.part_id, pr.planned_quantity, pr.reserved_quantity, pr.issued_quantity,
                   pr.used_quantity, pr.returned_quantity, pr.status, spi.part_name, spi.part_code, spi.unit
            FROM plan_resource_reservations pr
            LEFT JOIN spare_parts_inventory spi ON spi.id=pr.part_id
            WHERE pr.schedule_id=? ORDER BY pr.id
        """, (sid,)).fetchall()]

        work_order_ids = [int(order_id) for order_id in (r.get('work_order_ids') or [])
                          if str(order_id).isdigit()]
        r['linked_workorders'] = []
        if work_order_ids:
            r['linked_workorders'] = [_project_workorder_display(order) for order in db.execute(
                f"""SELECT w.id, w.order_no, w.title, w.status, w.level, s.name AS site_name
                           , w.source, w.event_type
                    FROM work_orders w LEFT JOIN sites s ON s.id=w.site_id
                    WHERE w.id IN ({','.join('?' * len(work_order_ids))})
                    ORDER BY CASE w.level WHEN 'critical' THEN 1 WHEN 'urgent' THEN 2 ELSE 3 END, w.created_at""",
                work_order_ids).fetchall()]
        # 关联的已生成执行任务
        r['generated_plans'] = [dict(p) for p in db.execute(
            "SELECT id, plan_name, generate_date, status, completion_rate FROM insp_plans WHERE plan_schedule_id=?",
            (sid,)).fetchall()]
        r['generated_site_tasks'] = _ps_execution_site_rows(db, sid, r.get('status'))
        r['generated_task_count'] = len(r['generated_site_tasks'])
        r.update(_ps_schedule_execution_status(
            r.get('status'), r.get('field_status'), r['generated_site_tasks']))
        rework_capability = _ps_rework_execution_capability(
            db, row, r.get('execution_status'), g.current_user)
        r['can_continue_rework'] = rework_capability['allowed']
        r['rework_block_reason'] = rework_capability['reason']
        r['rework_execution_target'] = rework_capability['target']
        execution_capability = _ps_field_execution_capability(
            db, row, r.get('execution_status'), g.current_user)
        r['can_continue_execution'] = execution_capability['allowed']
        r['execution_block_reason'] = execution_capability['reason']
        r['execution_target'] = execution_capability['target']
        r['execution_target_requires_selection'] = execution_capability.get(
            'requires_selection', False)
        r['execution_completed'] = r.get('field_status') == 'completed'
        return jsonify(r)


@app.route('/api/insp-plans/<int:plan_id>/overdue-action', methods=['POST'])
@login_required
def api_overdue_execution_action(plan_id):
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    action = data.get('action')
    if action not in ('remind', 'close'):
        return jsonify({'error': '无效的逾期处置动作'}), 400
    reason = (data.get('reason') or '').strip()
    if action == 'close' and not reason:
        return jsonify({'error': '登记未执行原因后才能异常关闭'}), 400
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        plan = db.execute("""SELECT ip.*, ps.status AS parent_schedule_status
            FROM insp_plans ip
            LEFT JOIN plan_schedules ps ON ps.id=ip.plan_schedule_id
            WHERE ip.id=?""", (plan_id,)).fetchone()
        if not plan:
            return jsonify({'error': '执行任务不存在'}), 404
        if plan['plan_schedule_id'] is not None and plan['parent_schedule_status'] != 'approved':
            return jsonify({
                'error': '父计划当前不是已批准状态，不能继续处置执行任务',
                'code': 'PLAN_SCHEDULE_NOT_EXECUTABLE',
            }), 409
        if plan['status'] != 'active' or (plan['generate_date'] or '') >= datetime.now().strftime('%Y-%m-%d'):
            return jsonify({'error': '只有已逾期且仍待执行的任务可以处置'}), 409
        pending_count = db.execute("""SELECT COUNT(*) FROM insp_plan_items WHERE plan_id=?
            AND result IS NULL AND COALESCE(execution_status,'active')='active'""", (plan_id,)).fetchone()[0]
        if not pending_count:
            return jsonify({'error': '该任务已无待执行检查项'}), 409
        if action == 'remind':
            if plan['assignee_id']:
                _create_notification(
                    plan['assignee_id'], 'inspection', plan_id, '逾期巡检催办',
                    f'{plan["plan_name"]}（{plan["generate_date"]}）仍有 {pending_count} 项未完成，请尽快处理或反馈原因。', db=db,
                )
            db.execute("""INSERT INTO timeline_events
                (source_type,source_id,event_type,operator,remark)
                VALUES ('inspection',?,'overdue_reminded',?,?)""",
                (plan_id, g.current_user.get('real_name') or '管理员', f'催办逾期任务，待完成{pending_count}项'))
            db.commit()
            return jsonify({'success': True, 'message': '已向执行人员发送催办通知'})
        db.execute("""UPDATE insp_plan_items SET execution_status='cancelled'
            WHERE plan_id=? AND result IS NULL AND COALESCE(execution_status,'active')='active'""", (plan_id,))
        db.execute("UPDATE insp_plans SET status='cancelled' WHERE id=?", (plan_id,))
        db.execute("""INSERT INTO timeline_events
            (source_type,source_id,event_type,operator,remark)
            VALUES ('inspection',?,'overdue_closed',?,?)""",
            (plan_id, g.current_user.get('real_name') or '管理员', f'异常关闭：{reason}'))
        if plan['assignee_id']:
            _create_notification(plan['assignee_id'], 'inspection', plan_id, '逾期任务已异常关闭', reason, db=db)
        db.commit()
        return jsonify({'success': True, 'cancelled_items': pending_count})


@app.route('/api/plan-schedules/<int:sid>', methods=['PUT'])
def api_plan_schedules_update(sid):
    """修改计划（draft/rejected/modifying 状态；本人或管理员）。
    draft/rejected 修改后回到 draft；modifying（变更中）修改后保持 modifying。"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    vehicle_days = data.get('vehicle_days') if 'vehicle_days' in data else {}
    vehicle_id = data.get('vehicle_id')
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        if not _ensure_plan_schedule_vehicle_column(db):
            db.rollback()
            return jsonify({'error': '计划数据结构缺少 vehicle_id，无法保存，请先完成数据库迁移',
                            'code': 'PLAN_SCHEMA_UNAVAILABLE'}), 503
        row = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        if row['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            return jsonify({'error': '只能修改自己的计划'}), 403
        if row['status'] not in ('draft', 'rejected', 'modifying'):
            return jsonify({'error': f'当前状态（{row["status"]}）不可修改'}), 400
        expected_version = data.get('version')
        if expected_version is None:
            return jsonify({
                'error': '缺少计划版本，请刷新后重新编辑',
                'code': 'PLAN_VERSION_REQUIRED',
                'current_version': int(row['version'] or 1),
            }), 409
        try:
            expected_version = int(expected_version)
        except (TypeError, ValueError):
            return jsonify({'error': '计划版本参数无效', 'code': 'PLAN_VERSION_INVALID'}), 400
        if expected_version != int(row['version'] or 1):
            return jsonify({
                'error': '计划已被其他操作更新，请刷新后重新编辑',
                'code': 'PLAN_VERSION_CONFLICT',
                'current_version': int(row['version'] or 1),
            }), 409
        try:
            current_plan_data = _ps_decode_plan_data(row['plan_data'])
            current_vehicle_days = json.loads(row['vehicle_days'] or '{}')
            current_spare_parts = json.loads(row['spare_parts'] or '[]')
            current_work_order_ids = json.loads(row['work_order_ids'] or '[]')
        except (TypeError, ValueError, json.JSONDecodeError):
            return jsonify({'error': 'Plan resource data is invalid',
                            'code': 'PLAN_RESOURCE_DATA_INVALID'}), 409
        plan_data = data['plan_data'] if 'plan_data' in data else current_plan_data
        vehicle_id = data['vehicle_id'] if 'vehicle_id' in data else (row['vehicle_id'] if 'vehicle_id' in row.keys() else None)
        vehicle_days = data['vehicle_days'] if 'vehicle_days' in data else current_vehicle_days
        spare_parts = data['spare_parts'] if 'spare_parts' in data else current_spare_parts
        work_order_ids = data['work_order_ids'] if 'work_order_ids' in data else current_work_order_ids
        if not isinstance(plan_data, dict):
            return jsonify({'error': 'plan_data 必须是日期到安排的对象',
                            'code': 'PLAN_DATA_INVALID'}), 400
        if not isinstance(spare_parts, list) or not isinstance(work_order_ids, list):
            return jsonify({'error': '计划资源格式无效', 'code': 'PLAN_RESOURCE_DATA_INVALID'}), 400
        try:
            period_start, period_end, outside_dates = _ps_validate_date_contract(
                data.get('period_start') or row['period_start'],
                data.get('period_end') or row['period_end'], plan_data, vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        if outside_dates:
            return jsonify({
                'error': '已有执行日期超出新周期，请先移除或调整这些日期；系统不会静默删除安排',
                'code': 'PLAN_DATES_OUTSIDE_PERIOD',
                'dates': outside_dates,
            }), 409
        remarks = data.get('remarks', row['remarks'])
        coverage_exception_reason = (data.get('coverage_exception_reason', row['coverage_exception_reason'] or '') or '').strip()
        vehicle_exception_reason = (data.get(
            'vehicle_exception_reason', row['vehicle_exception_reason'] or '') or '').strip()
        no_vehicle_required = (data.get('no_vehicle_required') in (True, 1, '1', 'true')
                               if 'no_vehicle_required' in data
                               else bool(row['no_vehicle_required']))
        supplied_vehicle_days = data.get('vehicle_days') if isinstance(data.get('vehicle_days'), dict) else {}
        if no_vehicle_required and (data.get('vehicle_id') not in (None, '')
                                    or any(supplied_vehicle_days.values())):
            return jsonify({'error': '已选择无需用车，不能同时安排车辆',
                            'code': 'PLAN_VEHICLE_MODE_CONFLICT',
                            'field': 'no_vehicle_required'}), 400
        if no_vehicle_required:
            vehicle_id = None
            vehicle_days = {}
        try:
            plan_data = _ps_validate_execution_sites(db, row['user_id'], plan_data)
            schedule_type = row['schedule_type'] if 'schedule_type' in row.keys() else 'weekly'
            plan_data = _ps_validate_item_selections(db, plan_data, schedule_type)
            vehicle_days, pruned_vehicle_dates = _ps_prune_vehicle_days(
                plan_data, vehicle_days, period_start, period_end)
            vehicle_days = _ps_expand_plan_vehicle(plan_data, vehicle_id, vehicle_days)
            vehicle_id = _ps_plan_vehicle_id(vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        vehicle_exception_reason = _ps_normalize_vehicle_exception_reason(
            vehicle_id, vehicle_exception_reason)
        validation = _ps_validate(
            db, row['user_id'], row['schedule_type'], period_start, period_end,
            plan_data, vehicle_days, exclude_schedule_id=sid,
            vehicle_exception_reason=vehicle_exception_reason,
            no_vehicle_required=no_vehicle_required)
        coverage_error = _ps_coverage_exception_required(
            validation, row['schedule_type'], coverage_exception_reason)
        draft_issues = list(validation['errors'])
        if coverage_error:
            draft_issues.append(coverage_error)
        # 变更中保持 modifying；其余回到 draft
        new_status = 'modifying' if row['status'] == 'modifying' else 'draft'
        cursor = db.execute("""
            UPDATE plan_schedules SET period_start=?, period_end=?, plan_data=?, vehicle_days=?, vehicle_id=?, no_vehicle_required=?, spare_parts=?, work_order_ids=?,
                   remarks=?, coverage_exception_reason=?, vehicle_exception_reason=?,
                   status=?, reject_reason=NULL, version=version+1
             WHERE id=? AND version=?
        """, (period_start, period_end,
              json.dumps(plan_data, ensure_ascii=False), json.dumps(vehicle_days, ensure_ascii=False),
              vehicle_id, int(no_vehicle_required),
              json.dumps(spare_parts, ensure_ascii=False), json.dumps(work_order_ids, ensure_ascii=False),
              remarks, coverage_exception_reason, vehicle_exception_reason, new_status, sid,
              int(row['version'] or 1)))
        if cursor.rowcount != 1:
            current = db.execute('SELECT version FROM plan_schedules WHERE id=?', (sid,)).fetchone()
            return jsonify({
                'error': '计划已被其他操作更新，请刷新后重新编辑',
                'code': 'PLAN_VERSION_CONFLICT',
                'current_version': int(current['version'] or 1) if current else None,
            }), 409
        next_version = int(row['version'] or 1) + 1
        _ps_record_event(db, sid, next_version, 'updated', u['id'], {
            'status': new_status, 'vehicle_exception_reason': vehicle_exception_reason,
            'no_vehicle_required': no_vehicle_required,
            'period_start': period_start, 'period_end': period_end,
            'pruned_vehicle_dates': pruned_vehicle_dates})
        db.commit()
        return jsonify({
            'success': True, 'id': sid, 'status': new_status, 'version': next_version,
            'period_start': period_start, 'period_end': period_end,
            'plan_data': plan_data, 'vehicle_days': vehicle_days,
            'no_vehicle_required': no_vehicle_required,
            'vehicle_exception_reason': vehicle_exception_reason,
            'pruned_vehicle_dates': pruned_vehicle_dates,
            'validation': validation, 'draft_issue_count': len(draft_issues),
            'draft_issues': draft_issues,
        })


@app.route('/api/plan-schedules/<int:sid>/submit', methods=['POST'])
def api_plan_schedules_submit(sid):
    """提交审批：draft/rejected → submitted；modifying（变更）→ change_submitted。
    带校验：errors 阻断，warnings 放行但记录。"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        row = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        if row['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            return jsonify({'error': '只能提交自己的计划'}), 403
        expected_version = data.get('version')
        if expected_version is None:
            return jsonify({
                'error': '缺少计划版本，请刷新后重新提交',
                'code': 'PLAN_VERSION_REQUIRED',
                'current_version': int(row['version'] or 1),
            }), 409
        try:
            expected_version = int(expected_version)
        except (TypeError, ValueError):
            return jsonify({'error': '计划版本参数无效', 'code': 'PLAN_VERSION_INVALID'}), 400
        if expected_version != int(row['version'] or 1):
            return jsonify({
                'error': '计划已被其他操作更新，请刷新后重新提交',
                'code': 'PLAN_VERSION_CONFLICT',
                'current_version': int(row['version'] or 1),
            }), 409
        if row['status'] in ('submitted', 'change_submitted'):
            db.rollback()
            return jsonify({
                'success': True, 'id': sid, 'status': row['status'],
                'version': expected_version, 'already_submitted': True,
            })
        is_change = row['status'] == 'modifying'
        if row['status'] not in ('draft', 'rejected', 'modifying'):
            return jsonify({'error': f'当前状态（{row["status"]}）不可提交'}), 400
        approver_ids = _ps_approver_ids(db)
        if not approver_ids:
            db.rollback()
            return jsonify({
                'error': '当前没有可用的计划审批管理员，请稍后重试',
                'code': 'PLAN_APPROVER_UNAVAILABLE',
            }), 409
        try:
            plan_data = _ps_decode_plan_data(row['plan_data'])
            vehicle_days = json.loads(row['vehicle_days'] or '{}')
        except (TypeError, ValueError, json.JSONDecodeError):
            return jsonify({'error': 'Plan resource data is invalid',
                            'code': 'PLAN_RESOURCE_DATA_INVALID'}), 409
        if not isinstance(vehicle_days, dict):
            return jsonify({'error': 'Plan resource data is invalid',
                            'code': 'PLAN_RESOURCE_DATA_INVALID'}), 409
        try:
            plan_data = _ps_validate_execution_sites(db, row['user_id'], plan_data)
            plan_data = _ps_validate_item_selections(db, plan_data, row['schedule_type'])
            _ps_persisted_vehicle_id(vehicle_days)
            stored_vehicle_id = row['vehicle_id'] if 'vehicle_id' in row.keys() else None
            vehicle_days = _ps_expand_plan_vehicle(plan_data, stored_vehicle_id, vehicle_days)
            normalized_vehicle_id = _ps_plan_vehicle_id(vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        vehicle_exception_reason = _ps_normalize_vehicle_exception_reason(
            normalized_vehicle_id, row['vehicle_exception_reason'] or '')
        no_vehicle_required = bool(row['no_vehicle_required'])
        v = _ps_validate(db, row['user_id'], row['schedule_type'],
                         row['period_start'], row['period_end'], plan_data, vehicle_days,
                         exclude_schedule_id=sid,
                         vehicle_exception_reason=vehicle_exception_reason,
                         no_vehicle_required=no_vehicle_required)
        if not v['ok']:
            return jsonify({'error': '；'.join(v['errors']), 'validation': v}), 400
        coverage_error = _ps_coverage_exception_required(v, row['schedule_type'], row['coverage_exception_reason'])
        if coverage_error:
            return jsonify({'error': coverage_error, 'validation': v}), 400
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        if is_change:
            vehicle_sql = ', vehicle_id=?' if _table_has_column(db, 'plan_schedules', 'vehicle_id') else ''
            transition_params = [now, json.dumps(v, ensure_ascii=False),
                                 vehicle_exception_reason, json.dumps(vehicle_days, ensure_ascii=False)]
            if vehicle_sql:
                transition_params.append(normalized_vehicle_id)
            transition_params.extend([sid, expected_version])
            transitioned = db.execute(f"""
                UPDATE plan_schedules SET status='change_submitted', submitted_at=?,
                       reject_reason=NULL, validation_snapshot=?, vehicle_exception_reason=?,
                       vehicle_days=?{vehicle_sql}
                 WHERE id=? AND status='modifying' AND version=?
            """, transition_params)
            new_status = 'change_submitted'
            notif_title, notif_body = '巡检计划变更待审', \
                f'{_PS_FREQ_CN.get(row["schedule_type"], "巡检")}计划（{row["period_start"]} ~ {row["period_end"]}）发起变更（原因：{row["change_reason"] or "未填"}），请审核。'
        else:
            vehicle_sql = ', vehicle_id=?' if _table_has_column(db, 'plan_schedules', 'vehicle_id') else ''
            transition_params = [now, json.dumps(v, ensure_ascii=False),
                                 vehicle_exception_reason, json.dumps(vehicle_days, ensure_ascii=False)]
            if vehicle_sql:
                transition_params.append(normalized_vehicle_id)
            transition_params.extend([sid, expected_version])
            transitioned = db.execute(f"""UPDATE plan_schedules
                SET status='submitted', submitted_at=?, reject_reason=NULL,
                    validation_snapshot=?, vehicle_exception_reason=?, vehicle_days=?{vehicle_sql}
                WHERE id=? AND status IN ('draft','rejected') AND version=?""",
                transition_params)
            new_status = 'submitted'
            notif_title, notif_body = '有新的巡检计划待审批', \
                f'{_PS_FREQ_CN.get(row["schedule_type"], "巡检")}计划（{row["period_start"]} ~ {row["period_end"]}）已提交，请审批。'
        if transitioned.rowcount != 1:
            db.rollback()
            current = db.execute('SELECT status, version FROM plan_schedules WHERE id=?', (sid,)).fetchone()
            return jsonify({
                'error': '计划状态或版本已变化，请刷新后重新提交',
                'code': 'PLAN_VERSION_CONFLICT',
                'current_version': int(current['version'] or 1) if current else None,
            }), 409
        for approver_id in approver_ids:
            _create_notification(
                approver_id, 'plan_schedule', sid, notif_title, notif_body, db=db,
                payload_json=json.dumps({
                    'notification_target': 'review', 'review_type': 'plan_schedule',
                }, ensure_ascii=False, separators=(',', ':')),
            )
        submission_event_id = _ps_record_event(
            db, sid, row['version'], 'change_submitted' if is_change else 'submitted', u['id'],
            {'validation': v, 'coverage_exception_reason': row['coverage_exception_reason'],
             'vehicle_exception_reason': vehicle_exception_reason})
        outbox_ids = _wx_queue_pending_approval(
            db, 'plan_schedule', sid, new_status, approver_ids,
            u['id'], '巡检计划变更' if is_change else '巡检计划审批',
            f'{_PS_FREQ_CN.get(row["schedule_type"], "巡检")}计划 {row["period_start"]}~{row["period_end"]}',
            f'PLAN-{sid}', now, cycle_key=f'event:{submission_event_id}',
            page=_wx_page('/pages/review/view', target_type='plan_schedule',
                          target_id=sid, cycle_key=f'event:{submission_event_id}'))
        db.commit()
        return jsonify({'success': True, 'id': sid, 'status': new_status,
                        'version': expected_version, 'validation': v})


@app.route('/api/plan-schedules/<int:sid>/approve', methods=['POST'])
def api_plan_schedules_approve(sid):
    """审批通过（admin/manager）：状态流转 + 生成任务 + 锁车 + 记录备件需求 + 通知。"""
    denied = require_approver()
    if denied:
        return denied
    u = g.current_user
    with get_db() as db:
        # Serialize validation, state transition, and final vehicle reservation
        # so another approver cannot act on stale resource state.
        try:
            db.execute('BEGIN IMMEDIATE')
        except sqlite3.OperationalError:
            return jsonify({'error': 'Approval resources are busy; retry shortly',
                            'code': 'PLAN_APPROVAL_BUSY'}), 409
        row = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        if row['status'] not in ('submitted', 'change_submitted'):
            return jsonify({'error': f'当前状态（{row["status"]}）不可审批'}), 400
        if row['period_end'] and str(row['period_end'])[:10] < datetime.now().strftime('%Y-%m-%d'):
            db.rollback()
            return jsonify({
                'error': '计划周期已过期，不能通过普通审批生成历史执行包或资源申请，请重新创建排程',
                'code': 'PLAN_EXPIRED',
            }), 409
        is_change = row['status'] == 'change_submitted'
        try:
            plan_data = _ps_decode_plan_data(row['plan_data'])
            vehicle_days = json.loads(row['vehicle_days'] or '{}')
        except (TypeError, ValueError, json.JSONDecodeError):
            db.rollback()
            return jsonify({'error': 'Plan resource data is invalid',
                            'code': 'PLAN_RESOURCE_DATA_INVALID'}), 409
        if not isinstance(vehicle_days, dict):
            db.rollback()
            return jsonify({'error': 'Plan resource data is invalid',
                            'code': 'PLAN_RESOURCE_DATA_INVALID'}), 409
        try:
            plan_data = _ps_validate_execution_sites(db, row['user_id'], plan_data)
            plan_data = _ps_validate_item_selections(db, plan_data, row['schedule_type'])
            _ps_persisted_vehicle_id(vehicle_days)
            stored_vehicle_id = row['vehicle_id'] if 'vehicle_id' in row.keys() else None
            vehicle_days = _ps_expand_plan_vehicle(plan_data, stored_vehicle_id, vehicle_days)
            normalized_vehicle_id = _ps_plan_vehicle_id(vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            db.rollback()
            return _ps_site_scope_error_response(exc)
        vehicle_exception_reason = _ps_normalize_vehicle_exception_reason(
            normalized_vehicle_id, row['vehicle_exception_reason'] or '')
        no_vehicle_required = bool(row['no_vehicle_required'])
        validation = _ps_validate(
            db, row['user_id'], row['schedule_type'], row['period_start'], row['period_end'],
            plan_data, vehicle_days, exclude_schedule_id=sid,
            vehicle_exception_reason=vehicle_exception_reason,
            no_vehicle_required=no_vehicle_required,
            # Submitted plans are requests, not reservations. The immediate
            # transaction and final application guard resolve contenders.
            include_submitted_plan_conflicts=False)
        if not validation['ok']:
            db.rollback()
            return jsonify({'error': '；'.join(validation['errors']), 'validation': validation,
                            'code': 'PLAN_RESOURCE_REVALIDATION_FAILED'}), 409
        coverage_error = _ps_coverage_exception_required(
            validation, row['schedule_type'], row['coverage_exception_reason'])
        if coverage_error:
            db.rollback()
            return jsonify({'error': coverage_error, 'validation': validation,
                            'code': 'PLAN_COVERAGE_EXCEPTION_REQUIRED'}), 409
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        # 审批仅确认计划需求，不占用库存；现场领用时按实时库存决定领用或转外购。
        vehicle_sql = ', vehicle_id=?' if _table_has_column(db, 'plan_schedules', 'vehicle_id') else ''
        transition_params = [u['id'], now, vehicle_exception_reason,
                             json.dumps(vehicle_days, ensure_ascii=False)]
        if vehicle_sql:
            transition_params.append(normalized_vehicle_id)
        transition_params.extend([sid, row['status']])
        transitioned = db.execute(f"""
            UPDATE plan_schedules SET status='approved', approver_id=?, approved_at=?,
                reject_reason=NULL, vehicle_exception_reason=?, vehicle_days=?{vehicle_sql}
            WHERE id=? AND status=?
        """, transition_params)
        if not transitioned.rowcount:
            db.rollback()
            return jsonify({'error': 'Plan status changed; refresh and retry',
                            'code': 'PLAN_APPROVAL_STALE'}), 409
        fresh = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if is_change:
            # 变更后保留已领用事实，其余计划需求按新版本重算，不占库存。
            db.execute("""UPDATE plan_resource_reservations
                SET reserved_quantity=0,
                    planned_quantity=issued_quantity,
                    status=CASE WHEN issued_quantity > 0 THEN 'issued' ELSE 'released' END,
                    updated_at=datetime('now','localtime')
                WHERE schedule_id=? AND status IN ('planned','reserved','issued')""", (sid,))
            try:
                _ps_reserve_parts(db, fresh)
            except (ValueError, sqlite3.Error) as exc:
                db.rollback()
                return jsonify({'error': str(exc),
                                'validation': validation,
                                'code': 'PLAN_PART_RESERVATION_FAILED'}), 409
            # Older return flows could leave a completed trip's application approved.
            # Close only this plan's fully returned history before rebuilding reservations.
            if _table_exists(db, 'vehicle_use_records'):
                db.execute("""UPDATE vehicle_applications SET status='returned'
                    WHERE applicant_id=? AND reason LIKE ? AND status='approved'
                      AND EXISTS (
                          SELECT 1 FROM vehicle_use_records vur
                          WHERE vur.application_id=vehicle_applications.id
                      )
                      AND NOT EXISTS (
                          SELECT 1 FROM vehicle_use_records vur
                          WHERE vur.application_id=vehicle_applications.id
                            AND vur.returned_at IS NULL
                            AND COALESCE(vur.status,'checked_out')!='returned'
                      )""", (fresh['user_id'], _ps_vehicle_reason_like(sid)))
            # 只取消尚未形成出车事实的旧预约；已出车车辆保留 approved 直至完成还车闭环。
            use_record_guard = """AND NOT EXISTS (
                SELECT 1 FROM vehicle_use_records vur
                WHERE vur.application_id=vehicle_applications.id
            )""" if _table_exists(db, 'vehicle_use_records') else ''
            db.execute(f"""UPDATE vehicle_applications SET status='cancelled'
                WHERE applicant_id=? AND reason LIKE ? AND status='approved' {use_record_guard}""",
                       (fresh['user_id'], _ps_vehicle_reason_like(sid)))
            try:
                changed_vehicle_days = json.loads(fresh['vehicle_days'] or '{}')
            except Exception:
                changed_vehicle_days = {}
            changed_ranges = {}
            for date_str, vid in changed_vehicle_days.items():
                if not vid or date_str < datetime.now().strftime('%Y-%m-%d'):
                    continue
                changed_ranges.setdefault(int(vid), []).append(str(date_str)[:10])
            for vid, dates in changed_ranges.items():
                dates = sorted(set(dates))
                if not dates:
                    continue
                start_at = f'{dates[0]} 08:00:00'
                end_at = f'{dates[-1]} 18:00:00'
                active_application = None
                if _table_exists(db, 'vehicle_use_records'):
                    active_application = db.execute("""SELECT va.id,va.start_at,va.end_at
                        FROM vehicle_applications va
                        WHERE va.vehicle_id=? AND va.applicant_id=? AND va.status='approved'
                          AND va.reason LIKE ? AND EXISTS (
                              SELECT 1 FROM vehicle_use_records vur
                              WHERE vur.application_id=va.id AND vur.returned_at IS NULL
                                AND COALESCE(vur.status,'checked_out')!='returned'
                          )
                        ORDER BY va.id DESC LIMIT 1
                    """, (vid, fresh['user_id'], _ps_vehicle_reason_like(sid))).fetchone()
                reservation_start = min(str(active_application['start_at']), start_at) \
                    if active_application else start_at
                reservation_end = max(str(active_application['end_at']), end_at) \
                    if active_application else end_at
                reservation = db.execute("""SELECT id FROM vehicle_applications
                    WHERE vehicle_id=? AND status='approved'
                      AND NOT (end_at < ? OR start_at > ?)
                      AND (? IS NULL OR id!=?)
                    LIMIT 1
                """, (vid, reservation_start, reservation_end,
                      active_application['id'] if active_application else None,
                      active_application['id'] if active_application else None)).fetchone()
                if reservation:
                    db.rollback()
                    return jsonify({
                        'error': '车辆时间已被其他已批准安排占用',
                        'validation': validation,
                        'code': 'PLAN_VEHICLE_RESERVATION_CONFLICT',
                    }), 409
                if active_application:
                    db.execute("""UPDATE vehicle_applications
                        SET start_at=?, end_at=? WHERE id=? AND status='approved'""",
                               (reservation_start, reservation_end, active_application['id']))
                    continue
                db.execute("""INSERT INTO vehicle_applications
                    (vehicle_id, applicant_id, start_at, end_at, destination, reason, status)
                    VALUES (?,?,?,?,?,?,?)""", (vid, fresh['user_id'], start_at,
                    end_at, '巡检', f'巡检计划#{sid}用车（v{fresh["version"]}，{dates[0]}至{dates[-1]}）', 'approved'))
            # 变更审批通过：保留已执行内容，取消未执行旧项并生成新增日执行包。
            try:
                flow = _ps_rebuild_tasks_on_change(db, fresh)
            except PlanScheduleSiteScopeError as exc:
                db.rollback()
                return _ps_site_scope_error_response(exc)
            except (ValueError, sqlite3.Error) as exc:
                db.rollback()
                return jsonify({'error': str(exc),
                                'validation': validation,
                                'code': 'PLAN_TASK_REBUILD_FAILED'}), 409
            requester = _plan_schedule_requester(db, sid)
            result_recipient_id = requester['operator_id'] if requester else fresh['user_id']
            result_notice_id = _create_notification(result_recipient_id, 'plan_schedule', sid, '计划变更已通过',
                                 f'变更原因：{fresh["change_reason"] or "—"}。任务已按新计划同步'
                                 f'（保留{flow["kept"]}个、重建{flow["plans_created"]}个）。', db=db)
            # 二次审批完成后清理临时回滚快照；完整变更事实已写入审计事件。
            db.execute("""UPDATE plan_schedules SET previous_plan_data=NULL, previous_vehicle_days=NULL,
                previous_vehicle_id=NULL, previous_spare_parts=NULL, previous_work_order_ids=NULL,
                previous_remarks=NULL, previous_period_start=NULL, previous_period_end=NULL,
                previous_coverage_exception_reason=NULL, previous_vehicle_exception_reason=NULL,
                previous_no_vehicle_required=NULL,
                change_reason=NULL WHERE id=?""", (sid,))
        else:
            try:
                flow = _ps_auto_flow(db, fresh)
            except PlanScheduleResourceConflict as exc:
                db.rollback()
                return jsonify({'error': str(exc), 'validation': validation,
                                'code': 'PLAN_VEHICLE_RESERVATION_CONFLICT'}), 409
            except PlanScheduleSiteScopeError as exc:
                db.rollback()
                return _ps_site_scope_error_response(exc)
            except (ValueError, sqlite3.Error) as exc:
                db.rollback()
                return jsonify({'error': str(exc), 'validation': validation,
                                'code': 'PLAN_APPROVAL_FLOW_FAILED'}), 409
        try:
            _ps_record_event(db, sid, fresh['version'], 'approved', u['id'],
                             {'is_change': is_change,
                              'coverage_exception_reason': fresh['coverage_exception_reason'],
                              'vehicle_exception_reason': fresh['vehicle_exception_reason'] or ''})
            requester = _plan_schedule_requester(db, sid)
            result_id = _wx_queue_approval_result(
                db, 'plan_schedule', sid,
                f'{"change_approved" if is_change else "approved"}:v{fresh["version"]}',
                requester['operator_id'] if requester else None,
                '巡检计划变更' if is_change else '巡检计划审批',
                f'{_PS_FREQ_CN.get(fresh["schedule_type"], "巡检")}计划 {fresh["period_start"]}~{fresh["period_end"]}',
                '已通过', now, '请按新计划执行' if is_change else '请按计划执行',
                cycle_key=f'event:{requester["id"] if requester else 0}',
                page=_wx_page('/pages/plan-detail/plan-detail', id=sid,
                              notification_id=result_notice_id if is_change else flow.get('result_notification_id')))
            db.commit()
        except (ValueError, sqlite3.Error) as exc:
            db.rollback()
            return jsonify({'error': str(exc), 'validation': validation,
                            'code': 'PLAN_APPROVAL_AUDIT_FAILED'}), 409
        return jsonify({'success': True, 'id': sid, 'status': 'approved', 'is_change': is_change, **flow})


@app.route('/api/plan-schedules/<int:sid>/reject', methods=['POST'])
def api_plan_schedules_reject(sid):
    """审批退回（admin/manager）：必须填写原因，通知排程人"""
    denied = require_approver()
    if denied:
        return denied
    u = g.current_user
    data = request.get_json(silent=True) or {}
    reason = (data.get('reason') or data.get('reject_reason') or '').strip()
    if not reason:
        return jsonify({'error': '请填写退回原因'}), 400
    with get_db() as db:
        row = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        if row['status'] not in ('submitted', 'change_submitted'):
            return jsonify({'error': f'当前状态（{row["status"]}）不可退回'}), 400
        if row['status'] == 'change_submitted':
            # 驳回变更：回滚到变更前的已批准版本，计划整体仍保持 approved
            raw_rollback_vehicle_id = row['previous_vehicle_id'] \
                if 'previous_vehicle_id' in row.keys() else None
            try:
                rollback_vehicle_id = int(raw_rollback_vehicle_id) \
                    if raw_rollback_vehicle_id not in (None, '') else None
                if rollback_vehicle_id is not None and rollback_vehicle_id <= 0:
                    rollback_vehicle_id = None
            except (TypeError, ValueError):
                rollback_vehicle_id = None
            if rollback_vehicle_id is None:
                try:
                    previous_vehicle_days = json.loads(row['previous_vehicle_days'] or '{}')
                    rollback_vehicle_id = _ps_plan_vehicle_id(previous_vehicle_days)
                except (AttributeError, TypeError, ValueError, json.JSONDecodeError,
                        PlanScheduleSiteScopeError):
                    # 历史多车计划保留原逐日事实，但不虚构一个计划级车辆。
                    rollback_vehicle_id = None
            db.execute("""
            UPDATE plan_schedules SET status='approved', approver_id=?, reject_reason=?,
                       period_start=COALESCE(previous_period_start, period_start),
                       period_end=COALESCE(previous_period_end, period_end),
                       plan_data=COALESCE(previous_plan_data, plan_data),
                       vehicle_days=COALESCE(previous_vehicle_days, vehicle_days),
                       vehicle_id=?,
                       spare_parts=COALESCE(previous_spare_parts, spare_parts),
                       work_order_ids=COALESCE(previous_work_order_ids, work_order_ids),
                       remarks=COALESCE(previous_remarks, remarks),
                       coverage_exception_reason=COALESCE(previous_coverage_exception_reason, coverage_exception_reason),
                       vehicle_exception_reason=COALESCE(previous_vehicle_exception_reason, vehicle_exception_reason),
                       no_vehicle_required=COALESCE(previous_no_vehicle_required, no_vehicle_required),
                       previous_plan_data=NULL, previous_vehicle_days=NULL, previous_vehicle_id=NULL,
                       previous_spare_parts=NULL, previous_work_order_ids=NULL, previous_remarks=NULL,
                       previous_period_start=NULL, previous_period_end=NULL,
                       previous_coverage_exception_reason=NULL,
                       previous_vehicle_exception_reason=NULL, previous_no_vehicle_required=NULL,
                       change_reason=NULL
                WHERE id=?
            """, (u['id'], reason, rollback_vehicle_id, sid))
            requester = _plan_schedule_requester(db, sid)
            result_recipient_id = requester['operator_id'] if requester else row['user_id']
            result_notice_id = _create_notification(result_recipient_id, 'plan_schedule', sid, '计划变更被驳回',
                                 f'原因：{reason}。已恢复原计划，请继续按原计划执行。', db=db)
            result_id = _wx_queue_approval_result(
                db, 'plan_schedule', sid, f'change_rejected:v{row["version"]}',
                requester['operator_id'] if requester else None, '巡检计划变更',
                _wx_plan_project(row, sid),
                '已退回', datetime.now().strftime('%Y-%m-%d %H:%M:%S'), '原计划继续有效；' + reason,
                cycle_key=f'event:{requester["id"] if requester else 0}',
                page=_wx_page('/pages/plan-detail/plan-detail', id=sid, notification_id=result_notice_id))
            db.commit()
            return jsonify({'success': True, 'id': sid, 'status': 'approved', 'rolled_back': True})
        db.execute("UPDATE plan_schedules SET status='rejected', approver_id=?, reject_reason=? WHERE id=?",
                   (u['id'], reason, sid))
        requester = _plan_schedule_requester(db, sid)
        result_recipient_id = requester['operator_id'] if requester else row['user_id']
        result_notice_id = _create_notification(result_recipient_id, 'plan_schedule', sid, '巡检计划被退回',
                             f'原因：{reason}。请修改后重新提交。', db=db)
        result_id = _wx_queue_approval_result(
            db, 'plan_schedule', sid, f'rejected:v{row["version"]}',
            requester['operator_id'] if requester else None, '巡检计划审批',
            _wx_plan_project(row, sid),
            '已退回', datetime.now().strftime('%Y-%m-%d %H:%M:%S'), reason,
            cycle_key=f'event:{requester["id"] if requester else 0}',
            page=_wx_page('/pages/plan-detail/plan-detail', id=sid, notification_id=result_notice_id))
        db.commit()
        return jsonify({'success': True, 'id': sid, 'status': 'rejected'})


def _ps_resource_parts(db, schedule_id):
    rows = db.execute("""SELECT pr.part_id, spi.part_name, spi.part_code, spi.unit,
               MAX(pr.planned_quantity) AS planned_quantity,
               0 AS reserved_quantity,
               SUM(pr.issued_quantity) AS issued_quantity
        FROM plan_resource_reservations pr
        LEFT JOIN spare_parts_inventory spi ON spi.id=pr.part_id
        WHERE pr.schedule_id=?
        GROUP BY pr.part_id, spi.part_name, spi.part_code, spi.unit
        ORDER BY spi.part_name, pr.part_id""", (schedule_id,)).fetchall()
    parts = []
    for row in rows:
        item = dict(row)
        item['reserved_quantity'] = int(item['reserved_quantity'] or 0)
        item['planned_quantity'] = int(item['planned_quantity'] or 0)
        item['issued_quantity'] = int(item['issued_quantity'] or 0)
        item['remaining_quantity'] = max(0, item['planned_quantity'] - item['issued_quantity'])
        parts.append(item)
    return parts


def _issue_plan_parts(db, schedule_id, user, requested):
    quantities = {}
    for item in requested:
        try:
            part_id = int(item.get('part_id') or 0)
            quantity = int(item.get('quantity') or 0)
        except (TypeError, ValueError):
            raise ValueError('领用数量必须为正整数')
        if not part_id or quantity <= 0:
            continue
        quantities[part_id] = quantities.get(part_id, 0) + quantity
    if not quantities:
        raise ValueError('请填写本次实际领用数量')

    plan_rows = {}
    for part_id, quantity in quantities.items():
        rows = db.execute("""SELECT id, planned_quantity, issued_quantity
            FROM plan_resource_reservations
            WHERE schedule_id=? AND part_id=? AND status IN ('planned','reserved','issued')
              AND planned_quantity > issued_quantity ORDER BY id DESC LIMIT 1""", (schedule_id, part_id)).fetchall()
        remaining = sum(int(row['planned_quantity'] or 0) - int(row['issued_quantity'] or 0) for row in rows)
        if quantity > remaining:
            raise ValueError(f'备件#{part_id}本次最多可领用{remaining}件')
        inventory = db.execute("SELECT quantity FROM spare_parts_inventory WHERE id=?", (part_id,)).fetchone()
        if not inventory or int(inventory['quantity'] or 0) < quantity:
            raise ValueError(f'备件#{part_id}库存不足')
        plan_rows[part_id] = rows

    operator = user.get('real_name') or user.get('username')
    issued_items = []
    for part_id, quantity in quantities.items():
        pending = quantity
        for reservation in plan_rows[part_id]:
            available = int(reservation['planned_quantity'] or 0) - int(reservation['issued_quantity'] or 0)
            current = min(pending, available)
            if current:
                db.execute("""UPDATE plan_resource_reservations
                    SET issued_quantity=issued_quantity+?, status='issued', updated_at=datetime('now','localtime')
                    WHERE id=?""", (current, reservation['id']))
                pending -= current
            if not pending:
                break
        db.execute("""UPDATE spare_parts_inventory
            SET quantity=quantity-?, updated_at=datetime('now','localtime') WHERE id=?""", (quantity, part_id))
        db.execute("""INSERT INTO inventory_logs
            (part_id, type, quantity, ref_type, ref_id, operator, remark) VALUES (?,?,?,?,?,?,?)""",
            (part_id, 'out', quantity, 'plan_schedule', schedule_id, operator, f'巡检计划#{schedule_id}现场领用'))
        issued_items.append({'part_id': part_id, 'quantity': quantity})
    return {'quantity': sum(quantities.values()), 'items': issued_items}


@app.route('/api/plan-schedules/<int:sid>/parts/issue', methods=['POST'])
@login_required
def api_plan_schedule_issue_parts(sid):
    """现场领料确认：按计划需求与实时库存出库，库存此时才扣减。"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        schedule = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not schedule:
            return jsonify({'error': '计划不存在'}), 404
        if schedule['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            return jsonify({'error': '只能确认自己计划的领料'}), 403
        if schedule['status'] != 'approved':
            return jsonify({'error': '仅已批准计划可领料'}), 400
        try:
            issued = _issue_plan_parts(db, sid, u, data.get('items') or [])
        except ValueError as exc:
            return jsonify({'error': str(exc)}), 400
        _ps_record_event(db, sid, schedule['version'], 'parts_issued', u['id'], {'items': issued['items']})
        db.commit()
        return jsonify({'success': True, 'issued_quantity': issued['quantity'],
                        'resource_parts': _ps_resource_parts(db, sid)})


@app.route('/api/plan-schedules/<int:sid>', methods=['DELETE'])
@login_required
def api_plan_schedules_delete(sid):
    """删除草稿，或由管理员清理从未产生执行内容的空批准排程。"""
    u = g.current_user
    with get_db() as db:
        row = db.execute('SELECT * FROM plan_schedules WHERE id=?', (sid,)).fetchone()
        if not row:
            return jsonify({'error': '排程不存在'}), 404
        if row['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            return jsonify({'error': '只能删除自己的草稿'}), 403
        is_draft_deletion = row['status'] in ('draft', 'rejected') and not row['tasks_generated']
        try:
            is_empty_payload = not any((json.loads(row[field] or fallback) for field, fallback in (
                ('plan_data', '{}'), ('vehicle_days', '{}'), ('spare_parts', '[]'), ('work_order_ids', '[]'),
            )))
        except (TypeError, ValueError):
            is_empty_payload = False
        has_execution_records = any((
            db.execute('SELECT 1 FROM insp_plans WHERE plan_schedule_id=? LIMIT 1', (sid,)).fetchone(),
            db.execute('SELECT 1 FROM plan_resource_reservations WHERE schedule_id=? LIMIT 1', (sid,)).fetchone(),
            db.execute('SELECT 1 FROM plan_departure_confirmations WHERE schedule_id=? LIMIT 1', (sid,)).fetchone(),
            db.execute("SELECT 1 FROM vehicle_applications WHERE reason LIKE ? LIMIT 1", (_ps_vehicle_reason_like(sid),)).fetchone(),
        ))
        is_empty_approved_cleanup = (
            _has_any_role(u, 'admin') and row['status'] == 'approved'
            and is_empty_payload and not has_execution_records
        )
        if not is_draft_deletion and not is_empty_approved_cleanup:
            return jsonify({'error': '仅未提交或已退回、且未生成任务的草稿可以删除'}), 409
        db.execute('DELETE FROM plan_schedule_events WHERE schedule_id=?', (sid,))
        db.execute('DELETE FROM plan_schedules WHERE id=?', (sid,))
        db.commit()
    return jsonify({'success': True, 'id': sid})


def _ps_purge_table_columns(db, table):
    if not _table_exists(db, table):
        return set()
    return {row['name'] for row in db.execute(f'PRAGMA table_info({table})').fetchall()}


def _ps_purge_delete_ids(db, table, column, values):
    columns = _ps_purge_table_columns(db, table)
    values = list(values)
    if not values or column not in columns:
        return 0
    placeholders = ','.join('?' for _ in values)
    return db.execute(f'DELETE FROM {table} WHERE {column} IN ({placeholders})', values).rowcount


def _ps_purge_attachment_rows(db, sid, plan_ids, item_ids):
    columns = _ps_purge_table_columns(db, 'operation_attachments')
    if not columns:
        return []
    predicates, params = [], []
    if {'source_type', 'source_id'}.issubset(columns):
        predicates.append("(source_type='plan_schedule' AND source_id=?)")
        params.append(sid)
        if item_ids:
            predicates.append("(source_type='inspection' AND source_id IN (%s))" %
                              ','.join('?' for _ in item_ids))
            params.extend(item_ids)
    if 'plan_id' in columns and plan_ids:
        predicates.append('plan_id IN (%s)' % ','.join('?' for _ in plan_ids))
        params.extend(plan_ids)
    if 'item_id' in columns and item_ids:
        predicates.append('item_id IN (%s)' % ','.join('?' for _ in item_ids))
        params.extend(item_ids)
    if 'extra_json' in columns:
        predicates.append("(json_valid(extra_json) AND CAST(json_extract(extra_json,'$.schedule_id') AS INTEGER)=?)")
        params.append(sid)
    if not predicates:
        return []
    return db.execute('SELECT * FROM operation_attachments WHERE ' + ' OR '.join(predicates), params).fetchall()


def _ps_purge_file_backups(db, attachments):
    columns = _ps_purge_table_columns(db, 'operation_attachments')
    if 'stored_path' not in columns:
        return []
    attachment_ids = {int(row['id']) for row in attachments}
    backups = []
    for stored_path in sorted({str(row['stored_path'] or '') for row in attachments}):
        if not stored_path.startswith('/uploads/'):
            continue
        shared = db.execute(
            'SELECT id FROM operation_attachments WHERE stored_path=?', (stored_path,)).fetchall()
        if any(int(row['id']) not in attachment_ids for row in shared):
            continue
        target = os.path.abspath(os.path.join(
            UPLOAD_DIR, stored_path[len('/uploads/'):].replace('/', os.sep)))
        root = os.path.abspath(UPLOAD_DIR)
        if os.path.commonpath((root, target)) != root:
            raise OSError('attachment path escapes upload root')
        if not os.path.exists(target):
            continue
        if not os.path.isfile(target):
            raise OSError('attachment target is not a regular file')
        with open(target, 'rb') as handle:
            backups.append((target, handle.read()))
    return backups


def _ps_restore_purge_files(backups):
    for target, contents in backups:
        try:
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, 'wb') as handle:
                handle.write(contents)
        except OSError:
            pass


@app.route('/api/plan-schedules/<int:sid>/purge', methods=['POST'])
@login_required
def api_plan_schedules_purge(sid):
    """Irreversibly remove one invalid schedule while retaining a text-only audit summary."""
    data = request.get_json(silent=True) or {}
    reason = str(data.get('reason') or '').strip()
    if not reason:
        return jsonify({'error': '请填写彻底删除原因', 'code': 'PLAN_PURGE_REASON_REQUIRED'}), 400
    if len(reason) > 500:
        return jsonify({'error': '彻底删除原因不能超过 500 字', 'code': 'PLAN_PURGE_REASON_TOO_LONG'}), 400
    try:
        requested_version = int(data.get('version'))
    except (TypeError, ValueError):
        return jsonify({'error': '计划版本无效，请刷新后重试', 'code': 'PLAN_PURGE_VERSION_REQUIRED'}), 400

    backups = []
    with get_db() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
            if not _transaction_user_is_active_admin(db, g.current_user.get('id')):
                db.rollback()
                return jsonify({'error': '仅管理员可彻底删除无效计划', 'code': 'FORBIDDEN'}), 403
            schedule = db.execute('SELECT * FROM plan_schedules WHERE id=?', (sid,)).fetchone()
            if not schedule:
                prior = None
                if _table_exists(db, 'timeline_events'):
                    prior = db.execute("""SELECT 1 FROM timeline_events
                        WHERE source_type='plan_schedule_purge' AND source_id=?
                          AND event_type='purged' LIMIT 1""", (sid,)).fetchone()
                db.rollback()
                if prior:
                    return jsonify({'success': True, 'id': sid, 'already_deleted': True})
                return jsonify({'error': '计划不存在', 'code': 'PLAN_PURGE_NOT_FOUND'}), 404
            current_version = int(schedule['version'] or 1) if 'version' in schedule.keys() else 1
            if requested_version != current_version:
                db.rollback()
                return jsonify({'error': '计划已发生变化，请刷新详情后重试',
                                'code': 'PLAN_PURGE_VERSION_CONFLICT',
                                'current_version': current_version}), 409

            plan_ids = [int(row['id']) for row in db.execute(
                'SELECT id FROM insp_plans WHERE plan_schedule_id=?', (sid,)).fetchall()]
            item_ids = []
            if plan_ids:
                item_ids = [int(row['id']) for row in db.execute(
                    'SELECT id FROM insp_plan_items WHERE plan_id IN (%s)' %
                    ','.join('?' for _ in plan_ids), plan_ids).fetchall()]
            attachments = _ps_purge_attachment_rows(db, sid, plan_ids, item_ids)
            attachment_ids = [int(row['id']) for row in attachments]
            backups = _ps_purge_file_backups(db, attachments)
            for target, _ in backups:
                os.remove(target)

            # Keep actual inventory and completed vehicle-use history; remove only unused reservations.
            _ps_purge_delete_ids(db, 'plan_resource_reservations', 'schedule_id', [sid])
            _ps_purge_delete_ids(db, 'plan_departure_confirmations', 'schedule_id', [sid])
            vehicle_ids = []
            retained_vehicle_application_count = 0
            retained_vehicle_use_count = 0
            if _table_exists(db, 'vehicle_applications'):
                vehicle_columns = _ps_purge_table_columns(db, 'vehicle_applications')
                vehicle_predicates = ['reason LIKE ?'] if 'reason' in vehicle_columns else []
                vehicle_params = [_ps_vehicle_reason_like(sid)] if vehicle_predicates else []
                if 'rework_plan_id' in vehicle_columns and plan_ids:
                    vehicle_predicates.append('rework_plan_id IN (%s)' %
                                              ','.join('?' for _ in plan_ids))
                    vehicle_params.extend(plan_ids)
                if 'reason' in vehicle_columns:
                    for plan_id in plan_ids:
                        vehicle_predicates.append('reason LIKE ?')
                        vehicle_params.append(f'%整改补检#{plan_id}用车%')
                if vehicle_predicates:
                    vehicle_ids = [int(row['id']) for row in db.execute(
                        'SELECT id FROM vehicle_applications WHERE ' +
                        ' OR '.join(f'({part})' for part in vehicle_predicates),
                        vehicle_params).fetchall()]
            for application_id in vehicle_ids:
                use_count = (int(db.execute(
                    'SELECT COUNT(*) FROM vehicle_use_records WHERE application_id=?',
                    (application_id,)).fetchone()[0] or 0)
                    if _table_exists(db, 'vehicle_use_records') else 0)
                has_use = use_count > 0
                if not has_use:
                    db.execute('DELETE FROM vehicle_applications WHERE id=?', (application_id,))
                else:
                    retained_vehicle_application_count += 1
                    retained_vehicle_use_count += use_count

            retained_parts_request_count = 0
            if _table_exists(db, 'parts_requests') and 'plan_id' in _ps_purge_table_columns(db, 'parts_requests'):
                for request_row in db.execute(
                        'SELECT id,status FROM parts_requests WHERE plan_id IN (%s)' %
                        (','.join('?' for _ in plan_ids) or 'NULL'), plan_ids).fetchall() if plan_ids else []:
                    if str(request_row['status'] or '') in ('issued', 'completed'):
                        db.execute('UPDATE parts_requests SET plan_id=0 WHERE id=?', (request_row['id'],))
                        retained_parts_request_count += 1
                    else:
                        _ps_purge_delete_ids(db, 'parts_request_items', 'request_id', [request_row['id']])
                        db.execute('DELETE FROM parts_requests WHERE id=?', (request_row['id'],))

            for child in ('attachment_evidence_evaluations', 'photo_capture_sessions',
                          'attachment_deletion_audits', 'attachment_void_audits',
                          'attachment_link_migration_issues', 'evidence_quality_remediations'):
                _ps_purge_delete_ids(db, child, 'attachment_id', attachment_ids)
            _ps_purge_delete_ids(db, 'photo_capture_sessions', 'plan_id', plan_ids)
            _ps_purge_delete_ids(db, 'photo_capture_sessions', 'item_id', item_ids)
            _ps_purge_delete_ids(db, 'operation_attachments', 'id', attachment_ids)
            _ps_purge_delete_ids(db, 'inspection_checkins', 'plan_id', plan_ids)
            _ps_purge_delete_ids(db, 'insp_plan_items', 'id', item_ids)
            _ps_purge_delete_ids(db, 'insp_plans', 'id', plan_ids)
            _ps_purge_delete_ids(db, 'plan_schedule_events', 'schedule_id', [sid])

            if _table_exists(db, 'notifications'):
                notification_columns = _ps_purge_table_columns(db, 'notifications')
                if {'source_type', 'source_id'}.issubset(notification_columns):
                    db.execute("DELETE FROM notifications WHERE source_type='plan_schedule' AND source_id=?", (sid,))
                    if plan_ids:
                        db.execute("DELETE FROM notifications WHERE source_type IN ('inspection','inspection_plan') "
                                   "AND source_id IN (%s)" % ','.join('?' for _ in plan_ids), plan_ids)
                    for plan_id in plan_ids:
                        db.execute("""DELETE FROM notifications
                            WHERE source_type='inspection_review_batch'
                              AND CAST(source_id AS TEXT) GLOB ?""", (f'insp_batch_{plan_id}_*',))
                    if plan_ids:
                        db.execute("""DELETE FROM notifications
                            WHERE source_type='inspection_rework'
                              AND source_id IN (%s)""" % ','.join('?' for _ in plan_ids), plan_ids)
                    if attachment_ids:
                        db.execute("""DELETE FROM notifications
                            WHERE source_type IN ('attachment_review','photo_review',
                                                  'attachment_void','replacement_review')
                              AND source_id IN (%s)""" % ','.join('?' for _ in attachment_ids),
                                   attachment_ids)
                if 'payload_json' in notification_columns:
                    db.execute("DELETE FROM notifications WHERE json_valid(payload_json) "
                               "AND CAST(json_extract(payload_json,'$.plan_schedule_id') AS INTEGER)=?", (sid,))

            # Independent work orders/reports/alerts stay intact; remove optional direct schedule links only.
            for table in ('work_orders', 'manual_reports', 'alerts'):
                columns = _ps_purge_table_columns(db, table)
                if 'plan_schedule_id' in columns:
                    db.execute(f'UPDATE {table} SET plan_schedule_id=NULL WHERE plan_schedule_id=?', (sid,))
            if _table_exists(db, 'timeline_events'):
                for source_type, values in (
                        ('plan_schedule', [sid]), ('inspection_plan', plan_ids),
                        ('inspection', plan_ids), ('inspection_item', item_ids)):
                    if values:
                        db.execute("DELETE FROM timeline_events WHERE source_type=? AND source_id IN (%s)" %
                                   ','.join('?' for _ in values), [source_type, *values])
            favorite_columns = _ps_purge_table_columns(db, 'plan_schedule_favorites')
            if 'source_schedule_id' in favorite_columns:
                db.execute('UPDATE plan_schedule_favorites SET source_schedule_id=NULL WHERE source_schedule_id=?',
                           (sid,))

            try:
                plan_data = json.loads(schedule['plan_data'] or '{}')
            except (TypeError, ValueError, json.JSONDecodeError):
                plan_data = {}
            site_ids = sorted({str(site_id) for day in plan_data.values() if isinstance(day, dict)
                               for site_id in (day.get('sites') or [])}) if isinstance(plan_data, dict) else []
            owner_name = ''
            if _table_exists(db, 'users'):
                user_columns = _ps_purge_table_columns(db, 'users')
                owner_column = ('real_name' if 'real_name' in user_columns
                                else 'username' if 'username' in user_columns else None)
                if owner_column:
                    owner = db.execute(f'SELECT {owner_column} AS owner_name FROM users WHERE id=?',
                                       (schedule['user_id'],)).fetchone()
                    owner_name = str(owner['owner_name'] or '') if owner else ''
            retained_inventory_log_count = 0
            inventory_columns = _ps_purge_table_columns(db, 'inventory_logs')
            if {'ref_type', 'ref_id'}.issubset(inventory_columns):
                retained_inventory_log_count = int(db.execute("""SELECT COUNT(*) FROM inventory_logs
                    WHERE ref_type='plan_schedule' AND ref_id=?""", (sid,)).fetchone()[0] or 0)
            summary = {
                'plan_id': sid,
                'plan_name': f"{schedule['schedule_type'] or '巡检'}计划",
                'status': schedule['status'],
                'status_before_delete': schedule['status'],
                'owner_id': schedule['user_id'],
                'owner_name': owner_name,
                'period': f"{schedule['period_start']}~{schedule['period_end']}",
                'period_start': schedule['period_start'],
                'period_end': schedule['period_end'],
                'site_ids': site_ids,
                'execution_plans': len(plan_ids),
                'inspection_items': len(item_ids),
                'attachments': len(attachment_ids),
                'retained_inventory_logs': retained_inventory_log_count,
                'retained_vehicle_applications': retained_vehicle_application_count,
                'retained_vehicle_uses': retained_vehicle_use_count,
                'retained_parts_requests': retained_parts_request_count,
                'reason': reason,
            }
            db.execute('DELETE FROM plan_schedules WHERE id=? AND version=?', (sid, current_version))
            if not db.execute('SELECT changes()').fetchone()[0]:
                raise sqlite3.IntegrityError('schedule changed during purge')
            db.execute("""INSERT INTO timeline_events
                (source_type,source_id,event_type,operator,remark)
                VALUES ('plan_schedule_purge',?,'purged',?,?)""",
                (sid, g.current_user.get('real_name') or g.current_user.get('username') or '管理员',
                 json.dumps(summary, ensure_ascii=False, separators=(',', ':'))))
            db.commit()
            return jsonify({'success': True, 'id': sid, 'already_deleted': False,
                            'deleted': {'execution_plans': len(plan_ids),
                                        'inspection_items': len(item_ids),
                                        'attachments': len(attachment_ids)}})
        except OSError:
            db.rollback()
            _ps_restore_purge_files(backups)
            return jsonify({'error': '影像文件清理失败，计划未删除，请重试',
                            'code': 'PLAN_PURGE_FILE_DELETE_FAILED'}), 503
        except sqlite3.DatabaseError:
            db.rollback()
            _ps_restore_purge_files(backups)
            return jsonify({'error': '彻底删除未完成，数据未发生变化，请刷新后重试',
                            'code': 'PLAN_PURGE_FAILED'}), 503


@app.route('/api/plan-schedules/purge-audits', methods=['GET'])
@login_required
def api_plan_schedule_deletion_records():
    """Administrator-only immutable purge summaries, never restore deleted objects."""
    if not _has_any_role(g.current_user, 'admin'):
        return jsonify({'error': '仅管理员可查看删除记录'}), 403
    try:
        page = int(request.args.get('page', '1'))
        page_size = int(request.args.get('page_size', '20'))
        if page < 1 or page_size < 1 or page_size > 100:
            raise ValueError('invalid pagination')
    except (TypeError, ValueError):
        return jsonify({'error': '分页参数无效', 'code': 'PAGINATION_INVALID'}), 400
    with get_db() as db:
        if not {'id', 'source_type', 'source_id', 'event_type', 'operator', 'remark', 'created_at'}.issubset(
                _ps_purge_table_columns(db, 'timeline_events')):
            return jsonify({'error': '删除审计暂不可用', 'code': 'PLAN_PURGE_AUDIT_UNAVAILABLE'}), 503
        total = db.execute("""SELECT COUNT(*) FROM timeline_events
            WHERE source_type='plan_schedule_purge' AND event_type='purged'""").fetchone()[0]
        rows = db.execute("""SELECT * FROM timeline_events
            WHERE source_type='plan_schedule_purge' AND event_type='purged'
            ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?""",
            (page_size, (page - 1) * page_size)).fetchall()
        records = []
        for row in rows:
            raw = row['remark'] or ''
            try:
                summary = json.loads(raw)
                if not isinstance(summary, dict):
                    raise ValueError('invalid summary')
            except (TypeError, ValueError):
                summary = {'audit_incomplete': True}
            period_start, period_end = summary.get('period_start'), summary.get('period_end')
            if not period_start and not period_end and isinstance(summary.get('period'), str):
                parts = summary['period'].split('~')
                if len(parts) == 2:
                    try:
                        for part in parts:
                            datetime.strptime(part, '%Y-%m-%d')
                        period_start, period_end = parts
                    except ValueError:
                        pass
            record = {key: summary.get(key) for key in (
                'plan_name', 'owner_id', 'owner_name', 'site_ids', 'reason')}
            record.update(plan_id=row['source_id'],
                status_before_delete=summary.get('status_before_delete', summary.get('status')),
                period_start=period_start, period_end=period_end,
                operator_name=row['operator'], purged_at=row['created_at'], raw_summary=raw)
            if summary.get('audit_incomplete'):
                record['audit_incomplete'] = True
            records.append(record)
        return jsonify({'items': records, 'total': total, 'page': page, 'page_size': page_size})


def _ps_schedule_activity_facts(db, schedule):
    """Return one schema-tolerant field/resource fact result for a schedule."""
    sid = int(schedule['id'])
    schedule_keys = set(schedule.keys())
    item_columns = ({row['name'] for row in db.execute(
        'PRAGMA table_info(insp_plan_items)').fetchall()}
        if _table_exists(db, 'insp_plan_items') else set())
    plan_columns = ({row['name'] for row in db.execute(
        'PRAGMA table_info(insp_plans)').fetchall()}
        if _table_exists(db, 'insp_plans') else set())

    execution_records = 0
    completed_execution_records = 0
    if {'id', 'plan_schedule_id'}.issubset(plan_columns):
        plans = db.execute('SELECT * FROM insp_plans WHERE plan_schedule_id=?', (sid,)).fetchall()
        execution_records = len(plans)
        if 'status' in plan_columns:
            completed_execution_records = sum(
                1 for plan in plans if str(plan['status'] or '').lower() == 'completed')

    def item_count(parts):
        if not parts or not {'plan_id'}.issubset(item_columns) or not {'id', 'plan_schedule_id'}.issubset(plan_columns):
            return 0
        return int(db.execute(
            'SELECT COUNT(*) FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id '
            f"WHERE ip.plan_schedule_id=? AND ({' OR '.join(parts)})", (sid,)).fetchone()[0] or 0)

    field_parts = [
        f"TRIM(COALESCE(CAST(pi.{name} AS TEXT),'')) NOT IN ('','[]','{{}}','null')"
        for name in ('result', 'check_time', 'completed_at', 'remark', 'calibrator',
                     'calibration_values', 'part_consumed') if name in item_columns
    ]
    location_parts = [
        f"TRIM(COALESCE(CAST(pi.{name} AS TEXT),''))!=''"
        for name in ('gps_lat', 'gps_lng', 'latitude', 'longitude',
                     'location_lat', 'location_lng') if name in item_columns
    ]
    item_checkin_parts = [
        f"TRIM(COALESCE(CAST(pi.{name} AS TEXT),''))!=''"
        for name in ('check_in_time', 'check_out_time') if name in item_columns
    ]
    photo_parts = []
    if 'photo_urls' in item_columns:
        photo_parts.append("LOWER(TRIM(COALESCE(pi.photo_urls,''))) NOT IN ('','[]','{}','null')")
    if 'actual_photos' in item_columns:
        photo_parts.append('COALESCE(pi.actual_photos,0)>0')
    review_parts = []
    if 'review_status' in item_columns:
        review_parts.append("TRIM(COALESCE(CAST(pi.review_status AS TEXT),'')) NOT IN ('','0')")
    for name in ('review_comment', 'review_time', 'evidence_status',
                 'supplement_required_at', 'supplement_reason', 'rework_required_at'):
        if name in item_columns:
            review_parts.append(f"TRIM(COALESCE(CAST(pi.{name} AS TEXT),''))!=''")
    if 'reviewer_id' in item_columns:
        review_parts.append('pi.reviewer_id IS NOT NULL')

    field_records = item_count(field_parts)
    locations = item_count(location_parts)
    checkins = item_count(item_checkin_parts)
    photos = item_count(photo_parts)
    reviews = item_count(review_parts)

    site_ids = set()
    try:
        plan_data = json.loads(schedule['plan_data'] or '{}') if 'plan_data' in schedule_keys else {}
    except (TypeError, ValueError, json.JSONDecodeError):
        plan_data = {}
    if isinstance(plan_data, dict):
        for day in plan_data.values():
            if isinstance(day, dict):
                for site_id in day.get('sites') or []:
                    try: site_ids.add(int(site_id))
                    except (TypeError, ValueError): pass
    if {'plan_id', 'site_id'}.issubset(item_columns) and {'id', 'plan_schedule_id'}.issubset(plan_columns):
        site_ids.update(int(row['site_id']) for row in db.execute(
            'SELECT DISTINCT pi.site_id FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id '
            'WHERE ip.plan_schedule_id=? AND pi.site_id IS NOT NULL', (sid,)).fetchall())

    if _table_exists(db, 'inspection_checkins'):
        columns = {row['name'] for row in db.execute('PRAGMA table_info(inspection_checkins)').fetchall()}
        rows = []
        relations, params = [], []
        if 'plan_id' in columns and {'id', 'plan_schedule_id'}.issubset(plan_columns):
            relations.append('plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)')
            params.append(sid)
        if site_ids and {'site_id', 'user_id', 'check_time'}.issubset(columns) and 'user_id' in schedule_keys:
            marks = ','.join('?' * len(site_ids))
            prefix = 'COALESCE(plan_id,0)=0 AND ' if 'plan_id' in columns else ''
            relations.append(f'({prefix}user_id=? AND site_id IN ({marks}) AND date(check_time) BETWEEN date(?) AND date(?))')
            params.extend((schedule['user_id'], *sorted(site_ids), schedule['period_start'], schedule['period_end']))
        if relations:
            rows = db.execute('SELECT * FROM inspection_checkins WHERE ' + ' OR '.join(relations), tuple(params)).fetchall()
        checkins += len(rows)
        locations += sum(1 for row in rows if any(
            name in row.keys() and row[name] not in (None, '')
            for name in ('lat', 'lng', 'gps_lat', 'gps_lng')))
        photos += sum(1 for row in rows if
                      'photo_url' in row.keys() and str(row['photo_url'] or '').strip())

    attachments = 0
    if _table_exists(db, 'operation_attachments'):
        columns = {row['name'] for row in db.execute('PRAGMA table_info(operation_attachments)').fetchall()}
        predicates, params = [], []
        if {'source_type', 'source_id'}.issubset(columns):
            links = []
            if {'id', 'plan_id'}.issubset(item_columns) and {'id', 'plan_schedule_id'}.issubset(plan_columns):
                links.append('oa.source_id IN (SELECT pi.id FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id WHERE ip.plan_schedule_id=?)')
                params.append(sid)
                if 'item_id' in columns:
                    links.append('oa.item_id IN (SELECT pi.id FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id WHERE ip.plan_schedule_id=?)')
                    params.append(sid)
            if 'plan_id' in columns and {'id', 'plan_schedule_id'}.issubset(plan_columns):
                links.append('oa.plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)')
                params.append(sid)
            if links:
                predicates.append("(oa.source_type='inspection' AND (" + ' OR '.join(links) + '))')
            predicates.append("(oa.source_type='plan_schedule' AND oa.source_id=?)"); params.append(sid)
        if predicates:
            where = ' OR '.join(predicates)
            attachments = int(db.execute('SELECT COUNT(*) FROM operation_attachments oa WHERE ' + where, tuple(params)).fetchone()[0] or 0)
            if attachments:
                image_parts = []
                if 'file_type' in columns: image_parts.append("LOWER(COALESCE(oa.file_type,''))='image'")
                if 'mime_type' in columns: image_parts.append("LOWER(COALESCE(oa.mime_type,'')) LIKE 'image/%'")
                photos += (int(db.execute('SELECT COUNT(*) FROM operation_attachments oa WHERE (' + where + ') AND (' + ' OR '.join(image_parts) + ')', tuple(params)).fetchone()[0] or 0)
                           if image_parts else attachments)

    notifications = (int(db.execute(
        "SELECT COUNT(*) FROM notifications WHERE source_type='plan_schedule' AND source_id=?", (sid,)).fetchone()[0] or 0)
        if _table_exists(db, 'notifications') and all(_table_has_column(db, 'notifications', name) for name in ('source_type', 'source_id')) else 0)
    resource_records = 0
    actual_resource_facts = False
    if _table_exists(db, 'plan_resource_reservations'):
        columns = {row['name'] for row in db.execute('PRAGMA table_info(plan_resource_reservations)').fetchall()}
        reservations = db.execute('SELECT * FROM plan_resource_reservations WHERE schedule_id=?', (sid,)).fetchall() if 'schedule_id' in columns else []
        resource_records += len(reservations)
        quantities = [name for name in ('issued_quantity', 'used_quantity', 'returned_quantity') if name in columns]
        for reservation in reservations:
            actual_resource_facts = actual_resource_facts or any(int(reservation[name] or 0) > 0 for name in quantities)
            actual_resource_facts = actual_resource_facts or (
                'status' not in columns or reservation['status'] not in ('planned', 'reserved'))
    if _table_exists(db, 'plan_departure_confirmations') and _table_has_column(db, 'plan_departure_confirmations', 'schedule_id'):
        resource_records += int(db.execute('SELECT COUNT(*) FROM plan_departure_confirmations WHERE schedule_id=?', (sid,)).fetchone()[0] or 0)
    if _table_exists(db, 'vehicle_applications'):
        columns = {row['name'] for row in db.execute('PRAGMA table_info(vehicle_applications)').fetchall()}
        parts, params = [], []
        if 'reason' in columns: parts.append('reason LIKE ?'); params.append(_ps_vehicle_reason_like(sid))
        if 'rework_plan_id' in columns: parts.append('rework_plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)'); params.append(sid)
        vehicles = db.execute('SELECT * FROM vehicle_applications WHERE ' + ' OR '.join(parts), tuple(params)).fetchall() if parts else []
        resource_records += len(vehicles)
        for vehicle in vehicles:
            actual_resource_facts = actual_resource_facts or (
                'status' not in columns or vehicle['status'] != 'approved')
            if ('id' in columns and _table_exists(db, 'vehicle_use_records')
                    and _table_has_column(db, 'vehicle_use_records', 'application_id')
                    and db.execute('SELECT 1 FROM vehicle_use_records WHERE application_id=? LIMIT 1', (vehicle['id'],)).fetchone()):
                actual_resource_facts = True

    activity_facts = {'locations': locations, 'checkins': checkins, 'photos': photos,
                      'reviews': reviews, 'attachments': attachments,
                      'notifications': notifications, 'execution_records': execution_records,
                      'resource_records': resource_records}
    return {'activity_facts': activity_facts, 'field_records': field_records,
            'completed_execution_records': completed_execution_records,
            'actual_resource_facts': actual_resource_facts,
            'has_blocking_facts': bool(field_records or locations or checkins or photos or reviews
                                       or attachments or completed_execution_records or actual_resource_facts)}


def _cleanup_candidates(db):
    """Return records safe for physical deletion or auditable anomaly close."""
    candidates = []
    schedules = db.execute("""SELECT ps.id, ps.status, ps.period_start, ps.period_end,
            ps.created_at, ps.tasks_generated, ps.plan_data, ps.vehicle_days,
            ps.spare_parts, ps.work_order_ids, u.real_name AS owner_name
        FROM plan_schedules ps LEFT JOIN users u ON u.id=ps.user_id
        WHERE ps.status='draft' AND COALESCE(ps.tasks_generated,0)=0
        ORDER BY ps.created_at DESC""").fetchall()
    for row in schedules:
        # A saved draft normally has plan_data and lifecycle events.  Neither
        # constitutes field activity and therefore must not hide a recoverable
        # draft from the administrator's explicit cleanup preview.
        if any((db.execute('SELECT 1 FROM insp_plans WHERE plan_schedule_id=? LIMIT 1', (row['id'],)).fetchone(),
                db.execute('SELECT 1 FROM plan_resource_reservations WHERE schedule_id=? LIMIT 1', (row['id'],)).fetchone(),
                db.execute('SELECT 1 FROM plan_departure_confirmations WHERE schedule_id=? LIMIT 1', (row['id'],)).fetchone(),
                db.execute('SELECT 1 FROM vehicle_applications WHERE reason LIKE ? LIMIT 1', (_ps_vehicle_reason_like(row["id"]),)).fetchone())):
            continue
        if _table_exists(db, 'operation_attachments') and db.execute(
                "SELECT 1 FROM operation_attachments WHERE source_type='plan_schedule' AND source_id=? LIMIT 1",
                (row['id'],)).fetchone():
            continue
        notifications = int(db.execute(
            "SELECT COUNT(*) FROM notifications WHERE source_type='plan_schedule' AND source_id=?",
            (row['id'],)).fetchone()[0] or 0) if _table_exists(db, 'notifications') else 0
        candidates.append({'kind': 'plan_schedule', 'id': row['id'], 'label': f'巡检计划#{row["id"]}',
                           'status': row['status'], 'owner_name': row['owner_name'] or '',
                           'period_start': row['period_start'] or '',
                           'period_end': row['period_end'] or '',
                           'cleanup_action': 'physical_delete',
                           'activity_facts': {
                               'locations': 0, 'checkins': 0, 'photos': 0, 'reviews': 0,
                               'attachments': 0, 'notifications': notifications,
                               'execution_records': 0, 'resource_records': 0,
                           },
                           'reason': '草稿/退回且未生成执行任务、资源或现场记录'})
    # Expired generated packages without any field fact are not deleted: they
    # are offered as auditable anomaly-close candidates instead.
    plan_columns = {item['name'] for item in db.execute('PRAGMA table_info(insp_plans)').fetchall()} if _table_exists(db, 'insp_plans') else set()
    item_columns = {item['name'] for item in db.execute('PRAGMA table_info(insp_plan_items)').fetchall()} if _table_exists(db, 'insp_plan_items') else set()
    schedule_columns = {item['name'] for item in db.execute('PRAGMA table_info(plan_schedules)').fetchall()}
    timeline_columns = {item['name'] for item in db.execute('PRAGMA table_info(timeline_events)').fetchall()} if _table_exists(db, 'timeline_events') else set()
    anomaly_close_ready = (
        {'id', 'plan_schedule_id', 'status'}.issubset(plan_columns)
        and {'plan_id', 'execution_status', 'result', 'check_in_time', 'check_out_time',
             'gps_lat', 'gps_lng'}.issubset(item_columns)
        and {'id', 'status'}.issubset(schedule_columns)
        and {'source_type', 'source_id', 'event_type', 'operator', 'remark'}.issubset(timeline_columns)
    )
    if anomaly_close_ready:
        schedule_type_sql = 'ps.schedule_type' if 'schedule_type' in schedule_columns else "''"
        user_columns = ({item['name'] for item in db.execute(
            'PRAGMA table_info(users)').fetchall()} if _table_exists(db, 'users') else set())
        user_role_columns = ({item['name'] for item in db.execute(
            'PRAGMA table_info(user_roles)').fetchall()}
            if _table_exists(db, 'user_roles') else set())
        owner_join_sql = ('LEFT JOIN users u ON u.id=ps.user_id'
                          if 'id' in user_columns else '')
        owner_name_sql = ('u.real_name' if {'id', 'real_name'}.issubset(user_columns)
                          else "''")

        def invalid_owner_reason(user_id):
            if 'id' not in user_columns:
                return '排程人不存在'
            owner = db.execute('SELECT * FROM users WHERE id=?', (user_id,)).fetchone()
            if not owner:
                return '排程人不存在'
            if ('status' in user_columns
                    and str(owner['status'] or '').strip().lower() != 'active'):
                return '排程人已停用'
            roles = set()
            if 'role' in user_columns:
                primary_role = str(owner['role'] or '').strip().lower()
                if primary_role:
                    roles.add(primary_role)
            if {'user_id', 'role'}.issubset(user_role_columns):
                roles.update(
                    str(role_row['role'] or '').strip().lower()
                    for role_row in db.execute(
                        'SELECT role FROM user_roles WHERE user_id=?', (user_id,)).fetchall()
                    if str(role_row['role'] or '').strip()
                )
            return '' if 'operator' in roles else '排程人已失去运维角色'

        generated = db.execute(f"""
            SELECT ps.id, ps.status, ps.user_id, ps.period_start, ps.period_end,
                   ps.created_at, {schedule_type_sql} AS schedule_type,
                   ps.plan_data, {owner_name_sql} AS owner_name,
                   COUNT(DISTINCT ip.id) AS generated_plans,
                   COUNT(DISTINCT CASE WHEN ip.status NOT IN ('completed','cancelled')
                                       THEN ip.id END) AS active_generated_plans
            FROM plan_schedules ps
            LEFT JOIN insp_plans ip ON ip.plan_schedule_id=ps.id
            {owner_join_sql}
            WHERE ps.status IN ('submitted','approved','modifying','change_submitted')
              AND ps.period_end < date('now','localtime')
            GROUP BY ps.id
            HAVING generated_plans=0 OR active_generated_plans>0
        """).fetchall()
        for row in generated:
            invalid_site_rows = db.execute("""SELECT DISTINCT pi.site_id,
                       COALESCE(s.name, '站点已不存在') AS site_name,
                       CASE
                         WHEN s.id IS NULL THEN '站点已不存在'
                         WHEN COALESCE(s.status,'') IN ('deleted','retired') THEN '站点已删除或停用'
                         WHEN us.site_id IS NULL THEN '站点已不再分配给负责人'
                       END AS invalid_reason
                FROM insp_plan_items pi JOIN insp_plans ip ON ip.id=pi.plan_id
                LEFT JOIN sites s ON s.id=pi.site_id
                LEFT JOIN user_sites us ON us.user_id=? AND us.site_id=pi.site_id
                WHERE ip.plan_schedule_id=? AND (s.id IS NULL
                   OR COALESCE(s.status,'') IN ('deleted','retired') OR us.site_id IS NULL)""",
                (row['user_id'], row['id'])).fetchall()
            invalid_sites_by_id = {int(item['site_id']): dict(item) for item in invalid_site_rows}
            try:
                plan_data = json.loads(row['plan_data'] or '{}')
            except (TypeError, ValueError, json.JSONDecodeError):
                plan_data = {}
            planned_site_ids = set()
            if isinstance(plan_data, dict):
                for day in plan_data.values():
                    if not isinstance(day, dict):
                        continue
                    for site_id in day.get('sites') or []:
                        try:
                            planned_site_ids.add(int(site_id))
                        except (TypeError, ValueError):
                            continue
            activity_site_ids = set(planned_site_ids)
            activity_site_ids.update(int(item['site_id']) for item in db.execute(
                """SELECT DISTINCT pi.site_id FROM insp_plan_items pi
                    JOIN insp_plans ip ON ip.id=pi.plan_id
                    WHERE ip.plan_schedule_id=? AND pi.site_id IS NOT NULL""",
                (row['id'],)).fetchall())
            for site_id in planned_site_ids:
                site = db.execute('SELECT id,name,status FROM sites WHERE id=?', (site_id,)).fetchone()
                assigned = db.execute(
                    'SELECT 1 FROM user_sites WHERE user_id=? AND site_id=? LIMIT 1',
                    (row['user_id'], site_id)).fetchone()
                reason = ('站点已不存在' if not site else
                          '站点已删除或停用' if (site['status'] or '') in ('deleted', 'retired') else
                          '站点已不再分配给负责人' if not assigned else '')
                if reason:
                    invalid_sites_by_id[site_id] = {
                        'site_id': site_id,
                        'site_name': site['name'] if site else '站点已不存在',
                        'invalid_reason': reason,
                    }
            owner_reason = invalid_owner_reason(row['user_id'])
            if not invalid_sites_by_id and not owner_reason:
                continue
            invalid_sites = [invalid_sites_by_id[key] for key in sorted(invalid_sites_by_id)]
            fact_result = _ps_schedule_activity_facts(db, row)
            if fact_result['has_blocking_facts']:
                continue
            invalid_reasons = []
            if owner_reason:
                invalid_reasons.append(owner_reason)
            if invalid_sites:
                invalid_reasons.append('包含无效站点安排')
            candidates.append({'kind': 'plan_schedule', 'id': row['id'],
                               'label': f'巡检计划#{row["id"]}', 'status': row['status'],
                               'owner_name': row['owner_name'] or '',
                               'period_start': row['period_start'] or '',
                               'period_end': row['period_end'] or '',
                               'schedule_type': row['schedule_type'] or '',
                               'created_at': row['created_at'] or '',
                               'invalid_sites': invalid_sites,
                               'cleanup_action': 'anomaly_close',
                               'activity_facts': fact_result['activity_facts'],
                               'reason': ('计划已超期且' + '、'.join(invalid_reasons)
                                          + '，未发现现场事实；可异常关闭并保留审计')})
    workorder_columns = {row['name'] for row in db.execute('PRAGMA table_info(work_orders)').fetchall()}
    workorder_conditions = [
        "w.status IN ('pending','accepted')",
        "COALESCE(w.check_in_time,'')=''",
    ]
    if 'related_alert_id' in workorder_columns:
        workorder_conditions.append("COALESCE(w.related_alert_id,0)=0")
    # Empty legacy images are safe; any non-empty or malformed value blocks physical deletion.
    if 'images' in workorder_columns:
        workorder_conditions.append("TRIM(COALESCE(w.images,'')) IN ('','[]')")
    for field in ('check_in_lat', 'check_in_lng'):
        if field in workorder_columns:
            workorder_conditions.append(f'w.{field} IS NULL')
    if 'review_submitted_at' in workorder_columns:
        workorder_conditions.append("TRIM(COALESCE(w.review_submitted_at,''))=''")
    association_tables = (
        ('operation_attachments', "oa.source_type='workorder' AND oa.source_id=w.id"),
        ('timeline_events', "te.source_type='workorder' AND te.source_id=w.id"),
        ('alerts', "a.related_order_no=w.order_no"),
        ('hotline_events', "he.related_order_no=w.order_no"),
        ('parts_requests', "pr.work_order_no=w.order_no"),
        ('spare_part_requests', "spr.work_order_no=w.order_no"),
        ('device_recycle', "dr.work_order_no=w.order_no"),
        ('vehicle_applications', "va.work_order_no=w.order_no"),
        ('inventory_logs', "il.work_order_no=w.order_no"),
    )
    for table, relation in association_tables:
        if not _table_exists(db, table):
            continue
        alias = relation.split('.', 1)[0]
        required_columns = set(re.findall(rf'{re.escape(alias)}\.([A-Za-z_][A-Za-z0-9_]*)', relation))
        table_columns = {row['name'] for row in db.execute(f'PRAGMA table_info({table})').fetchall()}
        if not required_columns.issubset(table_columns):
            continue
        workorder_conditions.append(f'NOT EXISTS (SELECT 1 FROM {table} {alias} WHERE {relation})')
    linked_workorder_ids = set()
    plan_links_safe = True
    if _table_has_column(db, 'plan_schedules', 'work_order_ids'):
        for plan_row in db.execute('SELECT work_order_ids FROM plan_schedules').fetchall():
            raw_links = plan_row['work_order_ids']
            if raw_links in (None, '', '[]'):
                continue
            try:
                parsed_links = json.loads(raw_links)
                if not isinstance(parsed_links, list):
                    raise ValueError
                linked_workorder_ids.update(int(item) for item in parsed_links)
            except (TypeError, ValueError, json.JSONDecodeError):
                plan_links_safe = False
                break
    if not plan_links_safe:
        workorder_conditions.append('0')
    elif linked_workorder_ids:
        placeholders = ','.join('?' for _ in linked_workorder_ids)
        workorder_conditions.append(f'w.id NOT IN ({placeholders})')
    workorders = db.execute(f"""SELECT w.id, w.order_no, w.title, w.status, w.source,
            w.created_at, s.name AS site_name
        FROM work_orders w LEFT JOIN sites s ON s.id=w.site_id
        WHERE {' AND '.join(workorder_conditions)}
        ORDER BY w.created_at DESC""", tuple(sorted(linked_workorder_ids)) if plan_links_safe else ()).fetchall()
    for row in workorders:
        notifications = int(db.execute(
            "SELECT COUNT(*) FROM notifications WHERE source_type='workorder' AND source_id=?",
            (row['id'],)).fetchone()[0] or 0) if _table_exists(db, 'notifications') else 0
        candidates.append({'kind': 'workorder', 'id': row['id'], 'order_no': row['order_no'],
                           'label': f'工单{row["order_no"]}', 'status': row['status'],
                           'title': row['title'] or '', 'site_name': row['site_name'] or '',
                           'cleanup_action': 'physical_delete',
                           'activity_facts': {
                               'locations': 0, 'checkins': 0, 'photos': 0, 'reviews': 0,
                               'attachments': 0, 'notifications': notifications,
                               'execution_records': 0, 'resource_records': 0,
                           },
                           'reason': '未签到、未审核且无附件或其他业务关联'})
    return candidates


@app.route('/api/admin/data-cleanup/candidates', methods=['GET'])
@login_required
def api_data_cleanup_candidates():
    denied = require_admin()
    if denied:
        return denied
    with get_db() as db:
        return jsonify({
            'candidates': _cleanup_candidates(db),
            'policy': '草稿和无业务事实工单可物理删除；已生成但无现场事实的超期计划仅异常关闭并保留审计。确认时会再次复核。',
        })


@app.route('/api/admin/data-cleanup/apply', methods=['POST'])
@login_required
def api_data_cleanup_apply():
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    selected = data.get('items')
    if not isinstance(selected, list) or not selected or len(selected) > 100:
        return jsonify({'error': '请选择1至100条候选记录', 'code': 'CLEANUP_SELECTION_INVALID'}), 400
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        current = {(row['kind'], int(row['id'])): row for row in _cleanup_candidates(db)}
        normalized = []
        for item in selected:
            if not isinstance(item, dict) or item.get('kind') not in ('plan_schedule', 'workorder'):
                db.rollback(); return jsonify({'error': '清理对象格式无效', 'code': 'CLEANUP_SELECTION_INVALID'}), 400
            try: key = (item['kind'], int(item['id']))
            except (TypeError, ValueError):
                db.rollback(); return jsonify({'error': '清理对象编号无效', 'code': 'CLEANUP_SELECTION_INVALID'}), 400
            if key not in current:
                db.rollback(); return jsonify({'error': '候选已变化，请刷新预览后重试', 'code': 'CLEANUP_CANDIDATE_CHANGED'}), 409
            if key in normalized:
                db.rollback(); return jsonify({'error': '清理对象不能重复选择', 'code': 'CLEANUP_SELECTION_DUPLICATE'}), 400
            normalized.append(key)
        deleted = []
        try:
            for kind, record_id in normalized:
                if kind == 'plan_schedule':
                    candidate = current[(kind, record_id)]
                    if candidate.get('cleanup_action') == 'anomaly_close':
                        item_columns = {row['name'] for row in db.execute('PRAGMA table_info(insp_plan_items)').fetchall()}
                        pending_condition = " AND result IS NULL" if 'result' in item_columns else ''
                        db.execute(
                            "UPDATE insp_plan_items SET execution_status='cancelled' "
                            "WHERE plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)"
                            + pending_condition,
                            (record_id,))
                        db.execute("UPDATE insp_plans SET status='cancelled' WHERE plan_schedule_id=? AND status NOT IN ('completed','cancelled')", (record_id,))
                        if _table_exists(db, 'plan_resource_reservations'):
                            reservation_columns = {
                                row['name'] for row in db.execute(
                                    'PRAGMA table_info(plan_resource_reservations)').fetchall()
                            }
                            updates = []
                            if 'planned_quantity' in reservation_columns:
                                updates.append('planned_quantity=0')
                            if 'reserved_quantity' in reservation_columns:
                                updates.append('reserved_quantity=0')
                            if 'status' in reservation_columns:
                                updates.append("status='released'")
                            if 'updated_at' in reservation_columns:
                                updates.append("updated_at=datetime('now','localtime')")
                            if updates:
                                db.execute(
                                    'UPDATE plan_resource_reservations SET ' + ','.join(updates)
                                    + " WHERE schedule_id=? AND status IN ('planned','reserved')",
                                    (record_id,))
                        if _table_exists(db, 'vehicle_applications'):
                            vehicle_columns = {
                                row['name'] for row in db.execute(
                                    'PRAGMA table_info(vehicle_applications)').fetchall()
                            }
                            if {'reason', 'status'}.issubset(vehicle_columns):
                                db.execute(
                                    "UPDATE vehicle_applications SET status='cancelled' "
                                    "WHERE reason LIKE ? AND status='approved'",
                                    (_ps_vehicle_reason_like(record_id),))
                            if {'rework_plan_id', 'status'}.issubset(vehicle_columns):
                                db.execute(
                                    "UPDATE vehicle_applications SET status='cancelled' "
                                    "WHERE rework_plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?) "
                                    "AND status='approved'", (record_id,))
                        db.execute("UPDATE plan_schedules SET status='archived' WHERE id=?", (record_id,))
                        db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                                   ('plan_schedule', record_id, 'anomaly_closed', g.current_user.get('real_name') or '',
                                    '清理操作异常关闭：无现场事实'))
                        deleted.append({'kind': kind, 'id': record_id, 'action': 'anomaly_close'})
                        continue
                    if _table_exists(db, 'plan_schedule_events'):
                        db.execute('DELETE FROM plan_schedule_events WHERE schedule_id=?', (record_id,))
                    if _table_exists(db, 'notifications'):
                        db.execute(
                            "DELETE FROM notifications WHERE source_type='plan_schedule' AND source_id=?",
                            (record_id,))
                    db.execute('DELETE FROM plan_schedules WHERE id=?', (record_id,))
                else:
                    row = db.execute('SELECT order_no FROM work_orders WHERE id=?', (record_id,)).fetchone()
                    db.execute('DELETE FROM timeline_events WHERE source_type=? AND source_id=?', ('workorder', record_id))
                    if _table_exists(db, 'notifications'):
                        db.execute(
                            "DELETE FROM notifications WHERE source_type='workorder' AND source_id=?",
                            (record_id,))
                    db.execute('DELETE FROM work_orders WHERE id=?', (record_id,))
                db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)",
                           ('data_cleanup', record_id, 'physical_delete', g.current_user.get('real_name') or '', f'{kind}:{record_id}'))
                deleted.append({'kind': kind, 'id': record_id, 'action': 'physical_delete'})
            db.commit()
        except Exception:
            app.logger.exception('data cleanup transaction failed')
            db.rollback()
            return jsonify({'error': '清理失败，已回滚且未删除记录', 'code': 'CLEANUP_ROLLED_BACK'}), 500
    return jsonify({'success': True, 'deleted': deleted})


def _ps_cancellation_has_facts(db, schedule):
    return _ps_schedule_activity_facts(db, schedule)['has_blocking_facts']


def _ps_cancellation_mutation_plan(db, schedule, notify_owner):
    """Preflight every cancellation write and return schema-safe updates."""
    sid = int(schedule['id'])

    def columns(table):
        return ({row['name'] for row in db.execute(
            f'PRAGMA table_info({table})').fetchall()}
            if _table_exists(db, table) else set())

    def unavailable(detail):
        return None, detail

    updates = []
    plan_columns = columns('insp_plans')
    generated = bool(schedule['tasks_generated']) if 'tasks_generated' in schedule.keys() else False
    plan_ids = []
    if plan_columns:
        if not {'id', 'plan_schedule_id'}.issubset(plan_columns):
            return unavailable('insp_plans 缺少计划关联列')
        plan_ids = [int(row['id']) for row in db.execute(
            'SELECT id FROM insp_plans WHERE plan_schedule_id=?', (sid,)).fetchall()]
        if plan_ids:
            if 'status' not in plan_columns:
                return unavailable('insp_plans 缺少 status')
            item_columns = columns('insp_plan_items')
            if not {'plan_id', 'execution_status'}.issubset(item_columns):
                return unavailable('insp_plan_items 缺少作废所需列')
            updates.append((
                "UPDATE insp_plan_items SET execution_status='cancelled' "
                'WHERE plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)',
                (sid,),
            ))
            updates.append((
                "UPDATE insp_plans SET status='cancelled' WHERE plan_schedule_id=? "
                "AND status NOT IN ('completed','cancelled')",
                (sid,),
            ))
    elif generated:
        return unavailable('已生成任务但 insp_plans 不可用')

    reservation_columns = columns('plan_resource_reservations')
    if reservation_columns:
        if 'schedule_id' not in reservation_columns:
            return unavailable('plan_resource_reservations 缺少 schedule_id')
        reservation_count = int(db.execute(
            'SELECT COUNT(*) FROM plan_resource_reservations WHERE schedule_id=?',
            (sid,)).fetchone()[0] or 0)
        if reservation_count:
            if 'status' not in reservation_columns:
                return unavailable('plan_resource_reservations 缺少 status')
            assignments = ["status='released'"]
            if 'planned_quantity' in reservation_columns:
                assignments.append('planned_quantity=0')
            if 'reserved_quantity' in reservation_columns:
                assignments.append('reserved_quantity=0')
            if 'updated_at' in reservation_columns:
                assignments.append("updated_at=datetime('now','localtime')")
            updates.append((
                f"UPDATE plan_resource_reservations SET {','.join(assignments)} "
                "WHERE schedule_id=? AND status IN ('planned','reserved')",
                (sid,),
            ))

    vehicle_columns = columns('vehicle_applications')
    if vehicle_columns:
        vehicle_parts, vehicle_params = [], []
        if 'reason' in vehicle_columns:
            vehicle_parts.append('reason LIKE ?')
            vehicle_params.append(_ps_vehicle_reason_like(sid))
        if 'rework_plan_id' in vehicle_columns and {'id', 'plan_schedule_id'}.issubset(plan_columns):
            vehicle_parts.append(
                'rework_plan_id IN (SELECT id FROM insp_plans WHERE plan_schedule_id=?)')
            vehicle_params.append(sid)
        has_vehicle_request = False
        if 'vehicle_id' in schedule.keys() and schedule['vehicle_id'] not in (None, ''):
            has_vehicle_request = True
        if 'vehicle_days' in schedule.keys():
            try:
                has_vehicle_request = has_vehicle_request or bool(json.loads(
                    schedule['vehicle_days'] or '{}'))
            except (TypeError, ValueError, json.JSONDecodeError):
                has_vehicle_request = True
        if not vehicle_parts and has_vehicle_request:
            return unavailable('vehicle_applications 缺少计划关联列')
        if vehicle_parts:
            vehicle_where = ' OR '.join(vehicle_parts)
            vehicles = db.execute(
                'SELECT * FROM vehicle_applications WHERE ' + vehicle_where,
                tuple(vehicle_params)).fetchall()
            if vehicles:
                if 'status' not in vehicle_columns:
                    return unavailable('vehicle_applications 缺少 status')
                if _table_exists(db, 'vehicle_use_records'):
                    use_columns = columns('vehicle_use_records')
                    if 'id' not in vehicle_columns or 'application_id' not in use_columns:
                        return unavailable('vehicle_use_records 缺少车辆申请关联列')
                updates.append((
                    "UPDATE vehicle_applications SET status='cancelled' WHERE ("
                    + vehicle_where + ") AND status='approved'",
                    tuple(vehicle_params),
                ))

    event_columns = columns('plan_schedule_events')
    if not {'schedule_id', 'version', 'event_type', 'operator_id', 'payload'}.issubset(event_columns):
        return unavailable('plan_schedule_events 缺少取消审计列')
    timeline_columns = columns('timeline_events')
    if not {'source_type', 'source_id', 'event_type', 'operator', 'remark'}.issubset(timeline_columns):
        return unavailable('timeline_events 缺少取消审计列')

    notification_columns = columns('notifications')
    if notification_columns:
        if not {'source_type', 'source_id', 'is_read'}.issubset(notification_columns):
            return unavailable('notifications 缺少关闭当前通知所需列')
        updates.append((
            "UPDATE notifications SET is_read=1 WHERE source_type='plan_schedule' "
            'AND source_id=? AND COALESCE(is_read,0)=0',
            (sid,),
        ))
        if notify_owner and not {
                'user_id', 'source_type', 'source_id', 'title', 'content'
        }.issubset(notification_columns):
            return unavailable('notifications 缺少负责人通知所需列')
    elif notify_owner:
        return unavailable('管理员代取消时 notifications 不可用')
    return {'updates': updates}, None


def _ps_cancellation_capability(db, schedule, user):
    """Project the same permission, state, fact and schema gates as cancellation."""
    if schedule['user_id'] != user['id'] and not _has_any_role(user, 'admin'):
        return {'allowed': False, 'reason': '无权取消该计划'}
    if schedule['status'] not in ('approved', 'modifying'):
        return {'allowed': False, 'reason': '当前状态不可取消'}
    try:
        if _ps_cancellation_has_facts(db, schedule):
            return {'allowed': False, 'reason': '计划已有现场或实际资源事实，不能取消'}
        _mutation_plan, schema_error = _ps_cancellation_mutation_plan(
            db, schedule, user['id'] != schedule['user_id'])
    except sqlite3.DatabaseError:
        return {'allowed': False, 'reason': '取消能力暂不可用，请刷新后重试'}
    if schema_error:
        return {'allowed': False, 'reason': '取消能力暂不可用，请刷新后重试'}
    return {'allowed': True, 'reason': ''}


@app.route('/api/plan-schedules/<int:sid>/cancel', methods=['POST'])
def api_plan_schedules_cancel(sid):
    u = g.current_user
    data = request.get_json(silent=True) or {}
    reason = str(data.get('reason') or '').strip()
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        row = db.execute('SELECT * FROM plan_schedules WHERE id=?', (sid,)).fetchone()
        if not row:
            db.rollback()
            return jsonify({'error': '计划不存在'}), 404
        if not {'id', 'user_id', 'status', 'version'}.issubset(row.keys()):
            db.rollback()
            return jsonify({
                'error': '计划取消所需数据结构不可用，请完成数据库迁移后重试',
                'code': 'PLAN_CANCEL_SCHEMA_UNAVAILABLE',
            }), 503
        if row['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            db.rollback()
            return jsonify({'error': '无权取消该计划', 'code': 'PLAN_CANCEL_FORBIDDEN'}), 403
        if row['status'] == 'cancelled':
            db.rollback()
            return jsonify({
                'success': True, 'id': sid, 'version': int(row['version'] or 1),
                'status': 'cancelled', 'current_status': 'cancelled',
                'already_cancelled': True,
            })
        if not reason:
            db.rollback()
            return jsonify({
                'error': '请填写取消原因', 'code': 'PLAN_CANCEL_REASON_REQUIRED',
            }), 400
        if len(reason) > 500:
            db.rollback()
            return jsonify({
                'error': '取消原因不能超过500字', 'code': 'PLAN_CANCEL_REASON_TOO_LONG',
            }), 400
        if data.get('version') is None:
            db.rollback()
            return jsonify({'error': '缺少计划版本', 'code': 'PLAN_VERSION_REQUIRED'}), 409
        try:
            expected = int(data['version'])
        except (TypeError, ValueError):
            db.rollback()
            return jsonify({'error': '计划版本参数无效', 'code': 'PLAN_VERSION_INVALID'}), 400
        if expected != int(row['version'] or 1):
            db.rollback()
            return jsonify({'error': '计划已被其他操作更新', 'code': 'PLAN_VERSION_CONFLICT', 'current_version': row['version']}), 409
        if row['status'] not in ('approved', 'modifying'):
            db.rollback()
            return jsonify({'error': '当前状态不可取消', 'code': 'PLAN_CANCEL_STATUS_INVALID'}), 409
        try:
            if _ps_cancellation_has_facts(db, row):
                db.rollback()
                return jsonify({
                    'error': '计划已有现场或实际资源事实，不能取消',
                    'code': 'PLAN_CANCEL_HAS_FACTS',
                }), 409
            mutation_plan, schema_error = _ps_cancellation_mutation_plan(
                db, row, u['id'] != row['user_id'])
        except sqlite3.DatabaseError:
            app.logger.exception('plan cancellation schema preflight failed')
            db.rollback()
            return jsonify({
                'error': '计划取消所需数据结构不可用，请完成数据库迁移后重试',
                'code': 'PLAN_CANCEL_SCHEMA_UNAVAILABLE',
            }), 503
        if schema_error:
            app.logger.warning('plan cancellation schema unavailable: %s', schema_error)
            db.rollback()
            return jsonify({
                'error': '计划取消所需数据结构不可用，请完成数据库迁移后重试',
                'code': 'PLAN_CANCEL_SCHEMA_UNAVAILABLE',
            }), 503
        next_version = int(row['version'] or 1) + 1
        try:
            for sql, params in mutation_plan['updates']:
                db.execute(sql, params)
            db.execute(
                "UPDATE plan_schedules SET status='cancelled',version=? WHERE id=?",
                (next_version, sid))
            _ps_record_event(db, sid, next_version, 'cancelled', u['id'], {'reason': reason})
            db.execute("INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark) VALUES (?,?,?,?,?)", ('plan_schedule', sid, 'cancelled', u.get('real_name') or '', reason))
            if u['id'] != row['user_id']:
                _create_notification(
                    row['user_id'], 'plan_schedule', sid, '巡检计划已取消', reason, db=db)
            db.commit()
        except Exception:
            app.logger.exception('plan cancellation transaction failed')
            db.rollback()
            return jsonify({
                'error': '取消失败，所有修改已回滚，请重试',
                'code': 'PLAN_CANCEL_ROLLED_BACK',
            }), 500
        return jsonify({'success': True, 'id': sid, 'status': 'cancelled', 'version': next_version})


@app.route('/api/plan-schedules/<int:sid>/request-change', methods=['POST'])
def api_plan_schedules_request_change(sid):
    """发起变更（approved → modifying）：车辆故障/突发事件等场景，运维修改已批准计划。
    快照当前 plan_data/vehicle_days 到 previous_* 字段，变更被驳回时可回滚。"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    reason = (data.get('change_reason') or data.get('reason') or '').strip()
    if not reason:
        return jsonify({'error': '请填写变更原因'}), 400
    with get_db() as db:
        row = db.execute("SELECT * FROM plan_schedules WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({'error': '计划不存在'}), 404
        if row['user_id'] != u['id'] and not _has_any_role(u, 'admin'):
            return jsonify({'error': '只能变更自己的计划'}), 403
        if row['status'] != 'approved':
            return jsonify({'error': f'当前状态（{row["status"]}）不可发起变更，仅已通过的计划可变更'}), 400
        if _ps_execution_completed(db, sid):
            return jsonify({'error': '该计划的巡检任务已全部完成，不能再发起变更',
                            'code': 'PLAN_EXECUTION_COMPLETED'}), 409
        db.execute("""
            UPDATE plan_schedules SET status='modifying', change_reason=?,
                   previous_plan_data=?, previous_vehicle_days=?, previous_vehicle_id=?,
                   previous_spare_parts=?, previous_work_order_ids=?, previous_remarks=?,
                   previous_period_start=?, previous_period_end=?,
                   previous_coverage_exception_reason=?, previous_vehicle_exception_reason=?,
                   previous_no_vehicle_required=?
            WHERE id=?
        """, (reason, row['plan_data'], row['vehicle_days'],
              row['vehicle_id'] if 'vehicle_id' in row.keys() else None,
              row['spare_parts'], row['work_order_ids'], row['remarks'],
              row['period_start'], row['period_end'],
              row['coverage_exception_reason'] or '', row['vehicle_exception_reason'] or '',
              int(bool(row['no_vehicle_required'])), sid))
        _ps_record_event(db, sid, row['version'], 'change_requested', u['id'], {
            'reason': reason,
            'snapshot_fields': [
                'period_start', 'period_end', 'plan_data', 'vehicle_id', 'vehicle_days',
                'spare_parts', 'work_order_ids', 'remarks', 'coverage_exception_reason',
                'vehicle_exception_reason', 'no_vehicle_required',
            ],
        })
        db.commit()
        return jsonify({'success': True, 'id': sid, 'status': 'modifying'})


@app.route('/api/plan-schedules/validate', methods=['POST'])
def api_plan_schedules_validate():
    """实时校验（排程编辑过程中调用）：全覆盖/日期范围/用车冲突。
    body: {user_id?, schedule_type, period_start, period_end, plan_data, vehicle_days, exclude_schedule_id?}"""
    u = g.current_user
    data = request.get_json(silent=True) or {}
    try:
        user_id = int(data.get('user_id') or u['id'])
    except (TypeError, ValueError):
        return jsonify({'error': '计划执行人参数无效',
                        'code': 'PLAN_EXECUTION_USER_INVALID'}), 400
    if not _has_any_role(u, 'admin') and user_id != int(u['id']):
        return jsonify({'error': '只能校验自己的巡检计划'}), 403
    raw_plan_data = data.get('plan_data') or {}
    if not isinstance(raw_plan_data, dict):
        return jsonify({'error': 'plan_data 必须是日期到安排的对象',
                        'code': 'PLAN_DATA_INVALID'}), 400
    vehicle_id = data.get('vehicle_id')
    vehicle_days = data.get('vehicle_days') if 'vehicle_days' in data else {}
    if 'vehicle_id' in data and vehicle_id in (None, '') and (data.get('vehicle_exception_reason') or '').strip():
        vehicle_days = {}
    try:
        schedule_type = _inspection_frequency(data.get('schedule_type'))
        period_start, period_end, outside_dates = _ps_validate_date_contract(
            data.get('period_start'), data.get('period_end'), raw_plan_data, vehicle_days)
    except ValueError as exc:
        return jsonify({'error': str(exc), 'code': 'PLAN_SCHEDULE_TYPE_INVALID'}), 400
    except PlanScheduleSiteScopeError as exc:
        return _ps_site_scope_error_response(exc)
    if outside_dates:
        return jsonify({
            'error': '执行日期超出计划周期', 'code': 'PLAN_DATES_OUTSIDE_PERIOD',
            'dates': outside_dates,
        }), 400
    with get_db() as db:
        try:
            plan_data = _ps_validate_execution_sites(db, user_id, raw_plan_data)
            plan_data = _ps_validate_item_selections(db, plan_data, schedule_type)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        try:
            vehicle_days = _ps_expand_plan_vehicle(plan_data, vehicle_id, vehicle_days)
        except PlanScheduleSiteScopeError as exc:
            return _ps_site_scope_error_response(exc)
        v = _ps_validate(
            db, user_id, schedule_type, period_start, period_end,
            plan_data, vehicle_days,
            data.get('exclude_schedule_id'),
            data.get('vehicle_exception_reason') or '',
            no_vehicle_required=data.get('no_vehicle_required') in (True, 1, '1', 'true'))
        return jsonify(v)


@app.route('/api/plan-schedules/suggestions', methods=['GET'])
def api_plan_schedules_suggestions():
    """智能建议（排程端实时提示 / 审批端风险预警，一套数据双端复用）。
    ?user_id=1 或 ?site_ids=3,7,12。返回各站点的工单顺路/告警复核/试剂临期建议与优先级评分。"""
    u = g.current_user
    site_ids_arg = request.args.get('site_ids')
    user_id = request.args.get('user_id')
    is_manager = _has_any_role(u, 'admin')
    try:
        schedule_type = _inspection_frequency(request.args.get('schedule_type', 'weekly'))
    except ValueError:
        return jsonify({'error': 'schedule_type参数无效',
                        'code': 'PLAN_SCHEDULE_TYPE_INVALID'}), 400
    allowed = _filter_site_ids()
    with get_db() as db:
        if site_ids_arg:
            try:
                site_ids = [int(x) for x in site_ids_arg.split(',') if x.strip()]
            except ValueError:
                return jsonify({'error': 'site_ids 格式错误'}), 400
            if not is_manager and allowed is not None and not set(site_ids).issubset(set(allowed)):
                return jsonify({'error': '无权查看非本人负责站点的排程建议'}), 403
        else:
            uid = user_id or u['id']
            if not is_manager and int(uid) != int(u['id']):
                return jsonify({'error': '只能查看自己的排程建议'}), 403
            site_ids = [r['site_id'] for r in
                        db.execute("SELECT site_id FROM user_sites WHERE user_id=?", (uid,)).fetchall()]
        if not site_ids:
            return jsonify({'suggestions': [], 'site_scores': {}, 'site_reasons': {}, 'template_context': []})
        site_names = {r['id']: r['name'] for r in db.execute(
            f"SELECT id, name FROM sites WHERE id IN ({','.join('?'*len(site_ids))})", site_ids).fetchall()}
        scores, reasons = _ps_site_scores(db, site_ids)
        suggestions = []
        for sid in site_ids:
            sname = site_names.get(sid, f'站点{sid}')
            order_no_select = 'order_no' if _table_has_column(db, 'work_orders', 'order_no') else 'NULL AS order_no'
            # 工单顺路
            orders = db.execute(f"""
                SELECT id, title, level, created_at, {order_no_select} FROM work_orders
                WHERE site_id=? AND status NOT IN ('closed')
            """, (sid,)).fetchall()
            active_order_nos = {str(o['order_no']) for o in orders if o['order_no']}
            for o in orders:
                try:
                    age = (datetime.now() - datetime.strptime(str(o['created_at'])[:10], '%Y-%m-%d')).days
                except Exception:
                    age = 0
                suggestions.append({
                    'type': 'work_order', 'site_id': sid, 'site_name': sname, 'ref_id': o['id'],
                    'level': o['level'],
                    'text': f'{sname}有未关工单「{o["title"]}」（{"紧急" if o["level"] == "urgent" else "普通"}，已{age}天），建议顺路处理并优先安排'})
            # 告警复核
            alert_order_select = ('related_order_no'
                                  if _table_has_column(db, 'alerts', 'related_order_no')
                                  else 'NULL AS related_order_no')
            alerts = db.execute(f"SELECT id, level, metric, {alert_order_select} "
                                "FROM alerts WHERE site_id=? AND status='pending'",
                                (sid,)).fetchall()
            for a in alerts:
                if a['related_order_no'] and str(a['related_order_no']) in active_order_nos:
                    continue
                metric = a['metric'] or ''
                metric_label = ('人工上报' if metric == 'manual_report'
                                else METRIC_CN.get(metric, metric or '指标异常'))
                suggestions.append({
                    'type': 'alert', 'site_id': sid, 'site_name': sname, 'ref_id': a['id'],
                    'level': a['level'],
                    'text': f'{sname}有{ALERT_LEVEL_LABEL.get(a["level"], "")}告警（{metric_label}）待现场复核'})
            # 无有效工单承接时保留人工上报；已有承接工单时只展示工单主入口。
            try:
                report_order_select = ('order_no'
                                       if _table_has_column(db, 'manual_reports', 'order_no')
                                       else 'NULL AS order_no')
                reports = db.execute(f"""
                    SELECT id, report_type, description, reported_at, {report_order_select} FROM manual_reports
                    WHERE site_id=? AND status NOT IN ('resolved', 'archived', 'closed')
                      AND reported_at >= datetime('now', '-30 days')
                    ORDER BY reported_at DESC
                """, (sid,)).fetchall()
                report_type_cn = {'sensory': '感官', 'equipment': '设备', 'environment': '环境',
                                  'violation': '违规', 'pollution': '污染'}
                report_level = {'pollution': 'high', 'violation': 'high', 'equipment': 'orange',
                                'environment': 'orange', 'sensory': 'warning'}
                for report in reports:
                    if report['order_no'] and str(report['order_no']) in active_order_nos:
                        continue
                    rtype = report['report_type'] or 'other'
                    suggestions.append({
                        'type': 'manual_report', 'site_id': sid, 'site_name': sname,
                        'ref_id': report['id'], 'level': report_level.get(rtype, 'warning'),
                        'text': f'{sname}有人工上报的{report_type_cn.get(rtype, "其他")}异常待现场复查'
                    })
            except Exception:
                pass
            # 试剂临期
            try:
                invs = db.execute("""
                    SELECT ri.*, r.name as reagent_name FROM reagent_inventory ri
                    LEFT JOIN reagents r ON ri.reagent_id = r.id WHERE ri.site_id=?
                """, (sid,)).fetchall()
                for inv in invs:
                    st = compute_reagent_status(dict(inv))
                    if st.get('status') in ('临期', '已过期', '低余量'):
                        suggestions.append({
                            'type': 'reagent', 'site_id': sid, 'site_name': sname, 'ref_id': inv['id'],
                            'level': 'warning',
                            'text': f'{sname}试剂{inv["reagent_name"] or ""}{st["status"]}（约剩{st.get("remaining_days")}天），建议本次携带更换'})
            except Exception:
                pass
        template_context = []
        try:
            item_columns = {
                column['name'] for column in
                db.execute('PRAGMA table_info(inspection_template_items)').fetchall()
            }
            item_status = " AND COALESCE(iti.status, 'active')='active'" \
                if 'status' in item_columns else ''
            template_rows = db.execute(f"""SELECT s.id AS site_id, s.name AS site_name,
                        t.template_name, t.description, COUNT(iti.id) AS item_count
                    FROM sites s
                    JOIN inspection_templates t ON t.status='active'
                        AND CASE WHEN LOWER(COALESCE(t.frequency,''))='annual' THEN 'yearly'
                                 ELSE LOWER(COALESCE(t.frequency,'')) END=?
                    LEFT JOIN inspection_template_items iti ON iti.template_id=t.id{item_status}
                    WHERE s.id IN ({','.join('?' * len(site_ids))})
                    GROUP BY s.id, s.name, t.id ORDER BY s.name, t.sort_order""",
                    [schedule_type] + site_ids).fetchall()
            template_context = [dict(x) for x in template_rows if x['template_name']]
        except sqlite3.OperationalError:
            pass  # 兼容尚未迁移巡检 V2 模板表的历史库。
        return jsonify({
            'suggestions': suggestions,
            'site_scores': {str(k): v for k, v in scores.items()},
            'site_reasons': {str(k): v for k, v in reasons.items()},
            'template_context': template_context,
        })


# ---------- 5.1 阈值规则 ----------
@app.route('/api/threshold-rules', methods=['GET'])
def api_threshold_rules():
    """阈值规则列表"""
    site_id = request.args.get('site_id')
    metric = request.args.get('metric')
    with get_db() as db:
        q = 'SELECT * FROM threshold_rules WHERE 1=1'
        params = []
        if site_id:
            q += ' AND (site_id=? OR scope="global")'; params.append(site_id)
        if metric:
            q += ' AND (metric=? OR scope="global")'; params.append(metric)
        q += ' ORDER BY scope, metric'
        rows = db.execute(q, params).fetchall()
        result = []
        for r in rows:
            r = dict(r)
            try:
                import json as _json
                r['conditions'] = _json.loads(r['conditions']) if r.get('conditions') else {}
            except:
                pass
            result.append(r)
        return jsonify(result)


def _normalize_threshold_conditions(value):
    if isinstance(value, dict):
        return {key: _normalize_threshold_conditions(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_threshold_conditions(item) for item in value]
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def _validate_threshold_rule_payload(data, db):
    """Validate and normalize threshold-rule input before it reaches SQLite."""
    name = (data.get('name') or '').strip()
    scope = (data.get('scope') or 'metric').strip()
    rule_type = (data.get('rule_type') or '').strip()
    severity = (data.get('severity') or 'warning').strip()
    site_id = data.get('site_id')
    metric = (data.get('metric') or '').strip() or None
    conditions = data.get('conditions') or {}

    if not name:
        return None, '规则名称不能为空'
    if scope not in {'global', 'metric', 'site'}:
        return None, '作用范围无效'
    if rule_type not in {'static', 'spc'}:
        return None, '该规则类型尚未实现，当前仅支持静态阈值和 SPC 动态规则'
    if severity not in {'info', 'warning', 'critical'}:
        return None, '告警级别无效'
    if not isinstance(conditions, dict):
        return None, '阈值条件格式无效'
    if scope == 'metric' and not metric:
        return None, '按指标规则必须选择适用指标'
    if scope == 'site':
        try:
            site_id = int(site_id)
        except (TypeError, ValueError):
            return None, '按站点规则必须选择站点'
        if not db.execute('SELECT 1 FROM sites WHERE id=?', (site_id,)).fetchone():
            return None, '所选站点不存在'
    else:
        site_id = None
    if scope == 'global':
        metric = None

    def numeric(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    if rule_type == 'static':
        low, high = conditions.get('min'), conditions.get('max')
        if low is None and high is None:
            return None, '静态阈值至少填写一个上限或下限'
        if low is not None and not numeric(low):
            return None, '下限值必须是数字'
        if high is not None and not numeric(high):
            return None, '上限值必须是数字'
        if low is not None and high is not None and low >= high:
            return None, '下限值必须小于上限值'
        conditions = {'min': low, 'max': high}
    else:
        mean, std = conditions.get('mean'), conditions.get('std')
        if not numeric(mean) or not numeric(std):
            return None, 'SPC 规则必须填写有效的均值和标准差'
        if std <= 0:
            return None, '标准差必须大于 0'
        conditions = {
            'mean': mean,
            'std': std,
            'ucl': mean + 3 * std,
            'lcl': mean - 3 * std,
        }
    return {
        'name': name,
        'scope': scope,
        'site_id': site_id,
        'metric': metric,
        'rule_type': rule_type,
        'conditions': _normalize_threshold_conditions(conditions),
        'severity': severity,
    }, None


@app.route('/api/threshold-rules', methods=['POST'])
def api_threshold_rules_create():
    """新增阈值规则"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json() or {}
    import json as _json
    with get_db() as db:
        normalized, error = _validate_threshold_rule_payload(data, db)
        if error:
            return jsonify({'error': error}), 400
        name = normalized['name']
        scope = normalized['scope']
        site_id = normalized['site_id']
        metric = normalized['metric']
        rule_type = normalized['rule_type']
        severity = normalized['severity']
        conditions_json = _json.dumps(
            normalized['conditions'], ensure_ascii=False, sort_keys=True, separators=(',', ':'),
        )
        candidates = db.execute(
            '''SELECT id, conditions FROM threshold_rules
               WHERE lower(trim(name))=lower(?) AND scope=? AND ifnull(site_id,-1)=ifnull(?,-1)
                 AND ifnull(metric,'')=ifnull(?,'') AND rule_type=? AND severity=?''',
            (name, scope, site_id, metric, rule_type, severity),
        ).fetchall()
        for candidate in candidates:
            try:
                existing_conditions = _json.dumps(
                    _normalize_threshold_conditions(_json.loads(candidate['conditions'] or '{}')),
                    ensure_ascii=False, sort_keys=True, separators=(',', ':'),
                )
            except (TypeError, ValueError):
                existing_conditions = candidate['conditions'] or '{}'
            if existing_conditions == conditions_json:
                return jsonify({'error': '已存在完全相同的阈值规则', 'code': 'DUPLICATE_THRESHOLD_RULE'}), 409
        try:
            cur = db.execute(
                '''INSERT INTO threshold_rules (name, scope, site_id, metric, rule_type, conditions, severity, created_by)
                   VALUES (?,?,?,?,?,?,?,?)''',
                (name, scope, site_id, metric, rule_type, conditions_json, severity, data.get('created_by')))
        except sqlite3.IntegrityError:
            return jsonify({'error': '已存在完全相同的阈值规则', 'code': 'DUPLICATE_THRESHOLD_RULE'}), 409
        db.commit()
        row = db.execute('SELECT * FROM threshold_rules WHERE id=?', (cur.lastrowid,)).fetchone()
        r = dict(row)
        try: r['conditions'] = _json.loads(r['conditions']) if r.get('conditions') else {}
        except: pass
        return jsonify(r), 201


@app.route('/api/threshold-rules/<int:rule_id>', methods=['PUT', 'DELETE'])
def api_threshold_rule_change(rule_id):
    denied = require_admin()
    if denied:
        return denied
    import json as _json
    with get_db() as db:
        existing = db.execute('SELECT * FROM threshold_rules WHERE id=?', (rule_id,)).fetchone()
        if not existing:
            return jsonify({'error': '阈值规则不存在'}), 404
        if request.method == 'DELETE':
            db.execute('DELETE FROM threshold_rules WHERE id=?', (rule_id,))
            db.execute(
                '''INSERT INTO operation_logs
                   (module, action, target_type, target_id, operator, operator_id, details)
                   VALUES ('alert_rule', 'delete', 'threshold_rule', ?, ?, ?, ?)''',
                (rule_id, g.current_user.get('real_name') or g.current_user.get('username') or '',
                 g.current_user.get('id') or 0, f'删除阈值规则「{existing["name"]}」'),
            )
            db.commit()
            return jsonify({'success': True, 'message': '阈值规则已删除'})

        current = dict(existing)
        try:
            current['conditions'] = _json.loads(current.get('conditions') or '{}')
        except (TypeError, ValueError):
            current['conditions'] = {}
        current.update(request.get_json(silent=True) or {})
        normalized, error = _validate_threshold_rule_payload(current, db)
        if error:
            return jsonify({'error': error}), 400
        conditions_json = _json.dumps(
            normalized['conditions'], ensure_ascii=False, sort_keys=True, separators=(',', ':'),
        )
        try:
            db.execute(
                '''UPDATE threshold_rules SET name=?, scope=?, site_id=?, metric=?, rule_type=?,
                   conditions=?, severity=? WHERE id=?''',
                (normalized['name'], normalized['scope'], normalized['site_id'], normalized['metric'],
                 normalized['rule_type'], conditions_json, normalized['severity'], rule_id),
            )
        except sqlite3.IntegrityError:
            return jsonify({'error': '已存在完全相同的阈值规则', 'code': 'DUPLICATE_THRESHOLD_RULE'}), 409
        db.execute(
            '''INSERT INTO operation_logs
               (module, action, target_type, target_id, operator, operator_id, details)
               VALUES ('alert_rule', 'update', 'threshold_rule', ?, ?, ?, ?)''',
            (rule_id, g.current_user.get('real_name') or g.current_user.get('username') or '',
             g.current_user.get('id') or 0, f'更新阈值规则「{normalized["name"]}」'),
        )
        db.commit()
        row = dict(db.execute('SELECT * FROM threshold_rules WHERE id=?', (rule_id,)).fetchone())
        row['conditions'] = _json.loads(row['conditions'] or '{}')
        return jsonify(row)


