@app.route('/api/alert-rules', methods=['GET'])
@login_required
def api_alert_rules_get():
    """获取告警规则引擎配置"""
    with get_db() as db:
        rows = db.execute('SELECT * FROM alert_rule_config ORDER BY id').fetchall()
        import json as _j
        result = []
        for r in rows:
            d = dict(r)
            try: d['thresholds'] = _j.loads(d['thresholds']) if d.get('thresholds') else {}
            except: pass
            d['enabled'] = bool(d['enabled'])
            d['isReversed'] = bool(d.get('is_reversed', 0))
            d['flowType'] = d.get('flow_type', 'auto')  # 前端用 camelCase
            d['metricLabel'] = d.get('metric_label', '')
            result.append(d)
        return jsonify(result)

@app.route('/api/alert-rules/<rule_id>', methods=['PUT'])
@login_required
def api_alert_rules_update(rule_id):
    """更新告警规则阈值/启用状态"""
    denied = require_admin()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    with get_db() as db:
        existing = db.execute('SELECT * FROM alert_rule_config WHERE id=?', (rule_id,)).fetchone()
        if not existing:
            return jsonify({'error': '规则不存在'}), 404
        import json as _j
        disabling = 'enabled' in data and not bool(data['enabled']) and bool(existing['enabled'])
        disable_reason = (data.get('disable_reason') or '').strip()
        if disabling and not disable_reason:
            return jsonify({'error': '停用规则必须填写停用原因'}), 400
        thresholds = data.get('thresholds')
        if thresholds is not None:
            db.execute('UPDATE alert_rule_config SET thresholds=? WHERE id=?',
                       (_j.dumps(thresholds, ensure_ascii=False), rule_id))
        if 'enabled' in data:
            db.execute('UPDATE alert_rule_config SET enabled=? WHERE id=?',
                       (1 if data['enabled'] else 0, rule_id))
            action = 'enable' if data['enabled'] else 'disable'
            details = (f'{"启用" if data["enabled"] else "停用"}告警规则'
                       f'「{existing["metric_label"]}」')
            if disable_reason:
                details += f'；原因：{disable_reason}'
            db.execute(
                '''INSERT INTO operation_logs
                   (module, action, target_type, target_id, operator, operator_id, details)
                   VALUES ('alert_rule', ?, 'alert_rule_config', 0, ?, ?, ?)''',
                (action, g.current_user.get('real_name') or g.current_user.get('username') or '',
                 g.current_user.get('id') or 0, details),
            )
        db.commit()
        row = db.execute('SELECT * FROM alert_rule_config WHERE id=?', (rule_id,)).fetchone()
        d = dict(row)
        try: d['thresholds'] = _j.loads(d['thresholds']) if d.get('thresholds') else {}
        except: pass
        d['enabled'] = bool(d['enabled'])
        d['isReversed'] = bool(d.get('is_reversed', 0))
        d['flowType'] = d.get('flow_type', 'auto')
        d['metricLabel'] = d.get('metric_label', '')
        return jsonify(d)


# ---------- 新增：异常主动上报 ----------
@app.route('/api/manual-reports', methods=['GET'])
def api_manual_reports():
    """人工上报列表（按站点范围隔离）"""
    status = request.args.get('status')
    report_type = request.args.get('report_type')
    site_id = request.args.get('site_id')
    allowed = _filter_site_ids()
    if allowed is not None and not allowed:
        return jsonify([])
    site_id_int = int(site_id) if site_id and site_id.isdigit() else None
    with get_db() as db:
        q = '''SELECT mr.*, u.real_name as reporter_name, s.name as site_name
               FROM manual_reports mr
               LEFT JOIN users u ON mr.reporter_id = u.id
               LEFT JOIN sites s ON mr.site_id = s.id WHERE 1=1'''
        params = []
        if status:
            q += ' AND mr.status=?'; params.append(status)
        if report_type:
            q += ' AND mr.report_type=?'; params.append(report_type)
        if site_id_int is not None:
            if allowed is not None and site_id_int not in allowed:
                return jsonify([])
            q += ' AND mr.site_id=?'; params.append(site_id_int)
        elif allowed is not None:
            ph = ','.join('?' * len(allowed))
            q += f' AND mr.site_id IN ({ph})'; params.extend(allowed)
        q += ' ORDER BY mr.reported_at DESC'
        rows = db.execute(q, params).fetchall()
        return jsonify([dict(r) for r in rows])


@app.route('/api/manual-reports', methods=['POST'])
def api_manual_reports_create():
    """移动端一键上报异常，自动生成工单（site_id 受当前用户站点范围约束）"""
    data = request.get_json() or {}
    site_id = data.get('site_id')
    allowed = _filter_site_ids()
    if allowed is not None and (not site_id or int(site_id) not in allowed):
        return jsonify({'error': '无权限上报非本人负责站点的异常'}), 403
    report_type = data['report_type']
    description = data.get('description', '')
    photo_urls = data.get('photo_urls', [])
    if not isinstance(photo_urls, list):
        return jsonify({'error': '现场照片格式无效'}), 400
    photo_urls = list(dict.fromkeys(url for url in photo_urls if isinstance(url, str) and url.startswith('/uploads/')))
    if not photo_urls:
        return jsonify({'error': '请至少提交一张现场照片'}), 400
    if len(photo_urls) > 6:
        return jsonify({'error': '现场照片最多 6 张'}), 400
    gps_lat = data.get('gps_lat')
    gps_lng = data.get('gps_lng')
    # 上报人必须来自已认证的请求上下文，不能信任客户端传入的 user id。
    reporter_id = g.current_user['id']

    import json as _json
    photos_json = _json.dumps(photo_urls, ensure_ascii=False)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    with get_db() as db:
        # 同一现场人员短时间内使用同一批照片重复提交，通常是弱网重试或重复点击。
        # 在写入前持有写锁并返回已有上报，确保一次上报只派生一张工单。
        db.execute('BEGIN IMMEDIATE')
        duplicate = db.execute(
            '''SELECT * FROM manual_reports
               WHERE site_id=? AND reporter_id=? AND report_type=? AND description=? AND photo_urls=?
                 AND reported_at >= datetime('now','localtime','-2 minutes')
               ORDER BY id DESC LIMIT 1''',
            (site_id, reporter_id, report_type, description, photos_json),
        ).fetchone()
        if duplicate:
            result = dict(duplicate)
            result['deduplicated'] = True
            return jsonify(result), 200
        # 写上报记录
        cur = db.execute(
            'INSERT INTO manual_reports (site_id, report_type, description, photo_urls, gps_lat, gps_lng, reporter_id, reported_at) VALUES (?,?,?,?,?,?,?,?)',
            (site_id, report_type, description, photos_json, gps_lat, gps_lng, reporter_id, now))
        report_id = cur.lastrowid

        # 自动生成工单（与机器告警统一队列）
        report_type_map = {'sensory':'感官异常','equipment':'设备异常','environment':'环境异常','violation':'违规操作','pollution':'污染事件'}
        event_type = report_type_map.get(report_type, report_type)
        order_no = 'MR' + now[:10].replace('-','') + str(report_id).zfill(4)
        # 与告警转工单保持一致：按站点责任关系分配给现场运维人员，
        # 由其在移动端完成“接单 -> 签到 -> 处置”流程。
        assignee = _station_operator(site_id)
        cur2 = db.execute(
            '''INSERT INTO work_orders (order_no, site_id, source, event_type, level, title, description, assignee, status)
               VALUES (?,?,"manual_report",?,"normal",?,?,?,"pending")''',
            (order_no, site_id, event_type,
             _generated_workorder_title('manual_report', event_type, event_type), description, assignee))

        # 写入告警队列（与机器告警同表同级别，去重：30秒内同站点同类型同描述不重复创建）
        level_map = {'sensory':'yellow','equipment':'orange','environment':'orange','violation':'red','pollution':'red'}
        alert_level = level_map.get(report_type, 'yellow')
        alert_msg = f'【人工上报】{event_type}: {description[:200]}'
        existing = db.execute(
            "SELECT id FROM alerts WHERE site_id=? AND message=? AND created_at > datetime('now','-30 seconds')",
            (site_id, alert_msg)).fetchone()
        if not existing:
            db.execute(
                '''INSERT INTO alerts (site_id, metric, value, level, message, status, related_order_no, flow_type)
                   VALUES (?,?,?,?,?,'pending',?,'manual')''',
                (site_id, 'manual_report', 0, alert_level, alert_msg, order_no))

        # 关联工单号回写
        db.execute('UPDATE manual_reports SET order_no=?, status="dispatched" WHERE id=?', (order_no, report_id))
        # 将上传暂存照片提升为异常上报证据；审核队列由此可直接追溯到本次上报。
        marks = ','.join('?' * len(photo_urls))
        db.execute(
            f"""UPDATE operation_attachments
                SET source_type='manual_report', source_id=?, description=?
                WHERE stored_path IN ({marks}) AND site_id=? AND uploader_id=?
                  AND source_type='site_photo' AND source_id=0""",
            [report_id, f'异常上报#{report_id}现场证据', *photo_urls, site_id, reporter_id],
        )
        db.commit()

        row = db.execute('SELECT * FROM manual_reports WHERE id=?', (report_id,)).fetchone()
        return jsonify(dict(row)), 201


def _mark_manual_reports_resolved(db, order_no):
    """工单关单时回写其派生的人工异常上报；不自动归档，保留管理者复盘入口。"""
    rows = db.execute(
        "SELECT id FROM manual_reports WHERE order_no=? AND status NOT IN ('resolved', 'archived')",
        (order_no,),
    ).fetchall()
    if not rows:
        return 0
    db.execute(
        """UPDATE manual_reports SET status='resolved', resolved_at=datetime('now','localtime')
           WHERE order_no=? AND status NOT IN ('resolved', 'archived')""",
        (order_no,),
    )
    for row in rows:
        db.execute(
            """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
               VALUES (?,?,?,?,?)""",
            ('manual_report', row['id'], 'resolved', 'system', f'派生工单 {order_no} 已完成，上报已解决'),
        )
    return len(rows)


def _transaction_user_is_active_admin(db, user_id):
    """Re-read active account roles while the caller holds the write transaction."""
    if not _table_exists(db, 'users'):
        return False
    user_columns = {row['name'] for row in db.execute('PRAGMA table_info(users)').fetchall()}
    if not {'id', 'role'}.issubset(user_columns):
        return False
    selected = ['role'] + (['status'] if 'status' in user_columns else [])
    user = db.execute(f"SELECT {','.join(selected)} FROM users WHERE id=?", (user_id,)).fetchone()
    if not user or ('status' in user.keys() and user['status'] != 'active'):
        return False
    roles = []
    if _table_exists(db, 'user_roles'):
        role_columns = {row['name'] for row in db.execute('PRAGMA table_info(user_roles)').fetchall()}
        if {'user_id', 'role'}.issubset(role_columns):
            roles = [row['role'] for row in db.execute(
                'SELECT role FROM user_roles WHERE user_id=?', (user_id,)
            ).fetchall()]
    # Old databases may not have user_roles populated; users.role remains the fallback.
    if not roles:
        roles = [user['role']]
    return 'admin' in _normalize_user_roles(roles, user['role'])


def _schema_safe_related_row_exists(db, table, column, value):
    """Apply cleanup's optional-table/column rule to one exact structured relation."""
    if not _table_exists(db, table):
        return False
    columns = {row['name'] for row in db.execute(f'PRAGMA table_info({table})').fetchall()}
    if column not in columns:
        return False
    return bool(db.execute(f'SELECT 1 FROM {table} WHERE {column}=? LIMIT 1', (value,)).fetchone())


def _workorder_json_list_has_facts(raw_value):
    if raw_value is None or (isinstance(raw_value, str) and not raw_value.strip()):
        return False
    try:
        parsed = json.loads(raw_value) if isinstance(raw_value, str) else raw_value
    except (TypeError, ValueError, json.JSONDecodeError):
        return True
    return not (isinstance(parsed, list) and len(parsed) == 0)


def _manual_report_dismiss_blocker(db, order):
    """Return the first irreversible work-order fact that forbids false-alarm dismissal."""
    if order['status'] != 'pending':
        return '工单已接单或进入处置流程，请继续走正常工单闭环'
    columns = set(order.keys())
    scalar_fields = ('check_in_time', 'check_in_lat', 'check_in_lng', 'remark',
                     'conclusion', 'review_submitted_at', 'resolved_at')
    if any(order[field] is not None and str(order[field]).strip()
           for field in scalar_fields if field in columns):
        return '工单已有签到、定位、影像、处置结果、审核或资源事实，请继续走正常工单闭环'
    if any(_workorder_json_list_has_facts(order[field])
           for field in ('images', 'used_parts') if field in columns):
        return '工单已有签到、定位、影像、处置结果、审核或资源事实，请继续走正常工单闭环'
    if _table_exists(db, 'operation_attachments'):
        attachment_columns = {
            row['name'] for row in db.execute('PRAGMA table_info(operation_attachments)').fetchall()
        }
        if {'source_type', 'source_id'}.issubset(attachment_columns):
            active = "AND COALESCE(is_deleted,0)=0" if 'is_deleted' in attachment_columns else ''
            if db.execute(
                    f"SELECT 1 FROM operation_attachments WHERE source_type='workorder' "
                    f"AND source_id=? {active} LIMIT 1", (order['id'],)).fetchone():
                return '工单已有正式证据附件，请继续走正常工单闭环'
    resource_tables = (
        'parts_requests', 'spare_part_requests', 'device_recycle',
        'vehicle_applications', 'inventory_logs',
    )
    if any(_schema_safe_related_row_exists(db, table, 'work_order_no', order['order_no'])
           for table in resource_tables):
        return '工单已有用车/备件/回收或库存事实，请继续正常工单闭环'
    return None


@app.route('/api/manual-reports/<int:report_id>/dismiss', methods=['POST'])
def api_manual_report_dismiss(report_id):
    """Admin-only false-alarm disposition before the derived order has any field facts."""
    if not _has_any_role(g.get('current_user'), 'admin'):
        return jsonify({'error': '需要管理员权限', 'code': 'FORBIDDEN'}), 403
    data = request.get_json(silent=True) or {}
    reason = str(data.get('reason') or '').strip()
    if not reason:
        return jsonify({'error': '请填写核实消除原因', 'code': 'MANUAL_REPORT_DISMISS_REASON_REQUIRED'}), 400
    if len(reason) > 500:
        return jsonify({'error': '核实消除原因不能超过 500 字', 'code': 'MANUAL_REPORT_DISMISS_REASON_TOO_LONG'}), 400
    with get_db() as db:
        db.execute('BEGIN IMMEDIATE')
        if not _transaction_user_is_active_admin(db, g.current_user.get('id')):
            return jsonify({'error': '管理员权限已变更，请重新登录后重试', 'code': 'FORBIDDEN'}), 403
        report = db.execute(
            'SELECT id,status,order_no FROM manual_reports WHERE id=?', (report_id,)
        ).fetchone()
        if not report:
            return jsonify({'error': '异常上报不存在', 'code': 'MANUAL_REPORT_NOT_FOUND'}), 404
        dismissed = db.execute(
            "SELECT 1 FROM timeline_events WHERE source_type='manual_report' "
            "AND source_id=? AND event_type='dismissed' LIMIT 1", (report_id,)
        ).fetchone()
        if dismissed:
            return jsonify({
                'success': True, 'id': report_id, 'status': report['status'],
                'already_dismissed': True,
            })
        if report['status'] in ('resolved', 'archived'):
            return jsonify({
                'error': '该上报已通过正常工单闭环解决，不能改为核实消除',
                'code': 'MANUAL_REPORT_ALREADY_RESOLVED',
            }), 409
        if report['status'] not in ('dispatched', 'verified'):
            return jsonify({
                'error': '仅已派单或已核实且尚未开始处置的人工上报可核实消除',
                'code': 'MANUAL_REPORT_DISMISS_INVALID_STATUS',
            }), 409
        order = db.execute('SELECT * FROM work_orders WHERE order_no=?', (report['order_no'],)).fetchone()
        if (not order or order['source'] != 'manual_report'
                or str(order['order_no'] or '') != str(report['order_no'] or '')):
            return jsonify({
                'error': '上报与派生工单关联不一致，请刷新后联系管理员核对',
                'code': 'MANUAL_REPORT_LINK_MISMATCH',
            }), 409
        blocker = _manual_report_dismiss_blocker(db, order)
        if blocker:
            return jsonify({'error': blocker, 'code': 'MANUAL_REPORT_DISMISS_ALREADY_STARTED'}), 409

        alerts_by_id = {}
        if 'related_alert_id' in order.keys() and order['related_alert_id']:
            linked = db.execute('SELECT * FROM alerts WHERE id=?', (order['related_alert_id'],)).fetchone()
            if not linked or ('related_order_no' in linked.keys()
                              and linked['related_order_no'] not in (None, '', report['order_no'])):
                return jsonify({
                    'error': '关联告警与工单不一致，请联系管理员核对',
                    'code': 'MANUAL_REPORT_LINK_MISMATCH',
                }), 409
            alerts_by_id[int(linked['id'])] = linked
        if (_table_exists(db, 'alerts') and _table_has_column(db, 'alerts', 'related_order_no')):
            for linked in db.execute(
                    'SELECT * FROM alerts WHERE related_order_no=?', (report['order_no'],)).fetchall():
                alerts_by_id[int(linked['id'])] = linked
        invalid_alert = next((linked for linked in alerts_by_id.values()
                              if str(linked['status'] or '') not in ('pending', 'resolved')), None)
        if invalid_alert:
            return jsonify({
                'error': '关联告警已进入处理中或状态异常，请先完成或撤销告警处理',
                'code': 'MANUAL_REPORT_ALERT_ALREADY_STARTED',
            }), 409

        actor = (g.current_user.get('real_name') or g.current_user.get('username') or '管理员')
        try:
            db.execute(
                """UPDATE manual_reports SET status='resolved', verification_note=?, verified_by=?,
                   verified_at=datetime('now','localtime'), resolved_at=datetime('now','localtime') WHERE id=?""",
                (reason, g.current_user['id'], report_id),
            )
            db.execute(
                """UPDATE work_orders SET status='closed', conclusion='false_alarm', remark=?,
                   resolved_at=datetime('now','localtime') WHERE id=?""", (reason, order['id'])
            )
            for alert_id, linked in alerts_by_id.items():
                if linked['status'] != 'pending':
                    continue
                changed = db.execute(
                    """UPDATE alerts SET status='resolved', resolved_at=datetime('now','localtime'),
                       resolve_reason='false_alarm' WHERE id=? AND status='pending'""",
                    (alert_id,),
                )
                if changed.rowcount:
                    db.execute(
                        """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
                           VALUES ('alert',?,'resolved',?,?)""",
                        (alert_id, actor, f'关联工单{report["order_no"]}核实为误报/无需处置'),
                    )
            db.execute(
                """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
                   VALUES ('manual_report',?,'dismissed',?,?)""", (report_id, actor, reason)
            )
            db.execute(
                """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
                   VALUES ('order',?,'dismissed',?,?)""",
                (order['id'], actor, f'工单{report["order_no"]}核实为误报/无需处置：{reason}'),
            )
            db.commit()
        except sqlite3.DatabaseError:
            db.rollback()
            return jsonify({
                'error': '核实消除未完成，数据未发生变化，请刷新后重试',
                'code': 'MANUAL_REPORT_DISMISS_FAILED',
            }), 503
        return jsonify({'success': True, 'id': report_id, 'status': 'resolved', 'order_status': 'closed'})


@app.route('/api/manual-reports/<int:report_id>/verify', methods=['POST'])
def api_manual_report_verify(report_id):
    """管理者核实现场上报真实性；核实不替代工单处置，也不自动关单。"""
    denied = require_approver()
    if denied:
        return denied
    data = request.get_json(silent=True) or {}
    note = (data.get('note') or '').strip()
    if not note:
        return jsonify({'error': '请填写核实说明'}), 400
    if len(note) > 500:
        return jsonify({'error': '核实说明不能超过 500 字'}), 400
    with get_db() as db:
        report = db.execute('SELECT id, status, order_no FROM manual_reports WHERE id=?', (report_id,)).fetchone()
        if not report:
            return jsonify({'error': '异常上报不存在'}), 404
        if report['status'] != 'dispatched':
            return jsonify({'error': '仅已派单的异常上报可核实'}), 400
        order = db.execute('SELECT status FROM work_orders WHERE order_no=?', (report['order_no'],)).fetchone()
        if not order or order['status'] == 'closed':
            return jsonify({'error': '关联工单不存在或已完成，请刷新后查看处理结果'}), 400
        db.execute(
            """UPDATE manual_reports SET status='verified', verification_note=?, verified_by=?,
               verified_at=datetime('now','localtime') WHERE id=?""",
            (note, g.current_user['id'], report_id),
        )
        db.execute(
            """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
               VALUES (?,?,?,?,?)""",
            ('manual_report', report_id, 'verified', g.current_user.get('real_name') or g.current_user.get('username') or 'manager', note or '管理核实通过'),
        )
        db.commit()
        return jsonify({'success': True, 'status': 'verified'})


@app.route('/api/manual-reports/<int:report_id>/archive', methods=['POST'])
def api_manual_report_archive(report_id):
    """仅已解决上报允许归档，避免把尚未完成的现场问题从待办中隐藏。"""
    denied = require_approver()
    if denied:
        return denied
    with get_db() as db:
        report = db.execute('SELECT id, status FROM manual_reports WHERE id=?', (report_id,)).fetchone()
        if not report:
            return jsonify({'error': '异常上报不存在'}), 404
        if report['status'] != 'resolved':
            return jsonify({'error': '仅已解决的异常上报可归档'}), 400
        db.execute(
            """UPDATE manual_reports SET status='archived', archived_by=?,
               archived_at=datetime('now','localtime') WHERE id=?""",
            (g.current_user['id'], report_id),
        )
        db.execute(
            """INSERT INTO timeline_events (source_type,source_id,event_type,operator,remark)
               VALUES (?,?,?,?,?)""",
            ('manual_report', report_id, 'archived', g.current_user.get('real_name') or g.current_user.get('username') or 'manager', '异常上报已归档'),
        )
        db.commit()
        return jsonify({'success': True, 'status': 'archived'})


